struct ScheduledTransactionPoolTestAccess {
    static void PrintPageForVcFence(
        const ScheduledTransactionPool& pool,
        std::uint64_t absoluteQuantum) {
        if (!pool.Valid() || absoluteQuantum < pool.baseQuantumIndex_ ||
            absoluteQuantum - pool.baseQuantumIndex_ >= pool.pageCount_) return;
        const auto ring = static_cast<std::uint32_t>(
            (absoluteQuantum - pool.sessionBaseQuantumIndex_) % pool.pageCount_);
        const auto& header = pool.pageHeaders_[ring];
        if (header.absoluteQuantumIndex != absoluteQuantum) return;
        std::cerr << "U1VC_TEMP fence_page quantum=" << absoluteQuantum
                  << " stamp=" << pool.PageStamp(absoluteQuantum)
                  << " emptyStamp="
                  << pool.pageEmptyQuantumStamp_[ring].load(std::memory_order_acquire)
                  << " frozen=" << header.frozen
                  << " events=" << pool.pageEventCount_[ring]
                  << " prepared=" << pool.pagePreparedEventCount_[ring]
                  << " batches=" << pool.pageBatchCount_[ring]
                  << " groups=" << pool.pagePlan03GroupCount_[ring]
                  << " preparedGroups=" << pool.pagePreparedPlan03GroupCount_[ring]
                  << " slices=" << pool.pageCurrentSliceCount_[ring]
                  << " holds=" << pool.pagePublicationHolds_[ring] << '\n';
    }
    static void PrintOrdinaryCancelGate(
        const ScheduledTransactionPool& pool,
        CommittedTransactionRef ref,
        std::uint64_t frame) {
        std::uint32_t page = 0;
        if (!ref.Valid() || ref.slot >= pool.transactions_.size() ||
            !pool.PageForFrame(frame, &page)) {
            std::cerr << "ordinary cancel gate invalid ref/frame\n";
            return;
        }
        const auto ring = pool.RingIndex(page);
        const auto& record = pool.transactions_[ref.slot];
        const auto& header = pool.pageHeaders_[ring];
        std::cerr << "ordinary cancel gate ref=" << ref.slot << ':'
                  << ref.commitSerial
                  << " recordUsed=" << record.used
                  << " recordPrepared=" << record.prepared
                  << " recordEvents=" << record.remainingEvents
                  << " summaryEvents=" << record.summary.eventCount
                  << " pageSpan=" << record.summary.pageSpan
                  << " occurrence=" << record.occurrence.present
                  << " immediateEntry=" << record.immediateEntry.Valid()
                  << " groupLive=" << pool.pagePlan03GroupCount_[ring]
                  << " groupPrepared=" << pool.pagePreparedPlan03GroupCount_[ring]
                  << " currentSlices=" << pool.pageCurrentSliceCount_[ring]
                  << " pageFrozen=" << header.frozen
                  << " pageStamp=" << pool.PageStamp(ref.absoluteQuantum)
                  << " pageEvents=" << pool.pageEventCount_[ring]
                  << " pagePreparedEvents=" << pool.pagePreparedEventCount_[ring]
                  << " batchLive=" << pool.pageBatchCount_[ring]
                  << '\n';
        const auto sameArm = [&](TimelineArmToken token) {
            return token.slot == record.armToken.slot &&
                   token.generation == record.armToken.generation &&
                   token.renderSlot == record.armToken.renderSlot &&
                   token.renderGeneration == record.armToken.renderGeneration;
        };
        std::cerr << "U1VC_TEMP frontier enabled="
                  << pool.consumerFrontierEnabled_
                  << " consumed="
                  << pool.consumedFrontierQuantum_->load(std::memory_order_acquire)
                  << " targetQuantum=" << ref.absoluteQuantum
                  << " emptyStamp="
                  << pool.pageEmptyQuantumStamp_[ring].load(std::memory_order_acquire)
                  << " pageGeneration=" << header.pageGeneration
                  << " pageEpoch=" << header.transportEpoch
                  << " pageCommitted=" << header.committedTransactionCount
                  << " poolLive=" << pool.liveTransactionCount_
                  << " pageHolds=" << pool.pagePublicationHolds_[ring]
                  << " batchOccupied=" << pool.pageBatchOccupiedCount_[ring]
                  << " targetOwner=" << record.ownerInstance
                  << " targetScheduleEpoch=" << record.ownerScheduleEpoch
                  << '\n';
        const auto eventBase = static_cast<std::size_t>(ring) *
            pool.config_.maxEventsPerQuantum;
        for (std::uint32_t index = 0; index < pool.pageEventCount_[ring]; ++index) {
            const auto& event = pool.PageEvent(eventBase + index);
            const auto& eventRecord = pool.transactions_[event.txnSlot];
            std::cerr << "U1VC_TEMP page_event index=" << index
                      << " frame=" << event.executeFrame
                      << " txn=" << event.txnSlot
                      << " arm=" << event.armToken.slot << ':'
                      << event.armToken.generation
                      << " targetArm=" << sameArm(event.armToken)
                      << " targetProgram="
                      << (eventRecord.program.program == record.program.program &&
                          eventRecord.program.programGeneration ==
                              record.program.programGeneration)
                      << " owner=" << eventRecord.ownerInstance
                      << " scheduleEpoch=" << eventRecord.ownerScheduleEpoch
                      << " frontier=" << event.frontier.Present() << '\n';
        }
        const auto batchBase = static_cast<std::size_t>(ring) *
            pool.config_.maxFrameBatchesPerQuantum;
        for (std::uint32_t index = 0;
             index < pool.pageBatchOccupiedCount_[ring]; ++index) {
            const auto& batch = pool.pageBatchRows_[batchBase + index];
            std::cerr << "U1VC_TEMP page_batch index=" << index
                      << " frame=" << batch.frame
                      << " live=" << batch.liveReferences
                      << " prepared=" << batch.preparedReferences << '\n';
        }
        const auto groupBase = static_cast<std::size_t>(ring) *
            pool.config_.maxPlan03GroupHeadersPerPage;
        for (std::uint32_t index = 0;
             index < pool.config_.maxPlan03GroupHeadersPerPage; ++index) {
            const auto rowIndex = groupBase + index;
            const auto state = pool.pagePlan03GroupRowStates_[rowIndex];
            if (state != ScheduledTransactionPool::Plan03GroupRowState::Live)
                continue;
            const auto& group = pool.PageGroupData(rowIndex).value;
            const auto& readers = pool.PageGroupData(rowIndex).readers;
            std::cerr << "U1VC_TEMP group row=" << rowIndex
                      << " members=" << group.memberCount
                      << " held=" << group.publicationHeld
                      << " decision=" << group.decision.slot << ':'
                      << group.decision.generation
                      << " frontierValid=" << group.frontier.Valid()
                      << " frontierOwner="
                      << group.frontier.operation.owner.child << ':'
                      << group.frontier.operation.owner.childEpoch
                      << " frontierTxn="
                      << group.frontier.operation.transactionSlot
                      << " frontierTargetProgram="
                      << (group.frontier.operation.program == record.program.program &&
                          group.frontier.operation.programGeneration ==
                              record.program.programGeneration)
                      << " frontierTargetArm="
                      << (group.frontier.operation.armSlot == record.armToken.slot &&
                          group.frontier.operation.armGeneration ==
                              record.armToken.generation &&
                          group.frontier.operation.renderSlot ==
                              record.armToken.renderSlot &&
                          group.frontier.operation.renderGeneration ==
                              record.armToken.renderGeneration)
                      << " readerPins="
                      << readers.pins.load(std::memory_order_acquire)
                      << " lastAudioSequence="
                      << readers.lastAudioSequence.load(std::memory_order_acquire)
                      << '\n';
            for (std::uint16_t member = 0; member < group.memberCount; ++member) {
                std::cerr << "U1VC_TEMP group_member row=" << rowIndex
                          << " member=" << member
                          << " targetArm="
                          << sameArm(pool.PageGroupTokens(rowIndex)[member])
                          << '\n';
            }
        }
    }
    static bool CaptureOrdinaryTransaction(
        const ScheduledTransactionPool& pool,
        TimelineTransactionProgramRef program,
        std::uint64_t absoluteQuantum,
        OrdinaryTransactionProbeForTest* out) noexcept {
        if (out == nullptr || !pool.Valid() || program.program == nullptr ||
            absoluteQuantum < pool.baseQuantumIndex_ ||
            absoluteQuantum - pool.baseQuantumIndex_ >= pool.pageCount_) return false;
        OrdinaryTransactionProbeForTest probe{};
        for (std::uint32_t slot = 0; slot < pool.transactions_.size(); ++slot) {
            const auto& record = pool.transactions_[slot];
            if (!record.used || record.program.program != program.program ||
                record.program.programGeneration != program.programGeneration)
                continue;
            probe.slot = slot;
            probe.remainingEvents = record.remainingEvents;
            ++probe.matchingRecords;
        }
        const auto ring = static_cast<std::uint32_t>(
            (absoluteQuantum - pool.sessionBaseQuantumIndex_) % pool.pageCount_);
        const auto& page = pool.pageHeaders_[ring];
        if (page.absoluteQuantumIndex != absoluteQuantum) return false;
        const auto base = static_cast<std::size_t>(ring) *
            pool.config_.maxEventsPerQuantum;
        probe.pageEventCount = pool.pageEventCount_[ring];
        probe.pageFrameBatchCount = pool.pageBatchCount_[ring];
        probe.committedTransactionCount = page.committedTransactionCount;
        probe.liveTransactionCount = pool.liveTransactionCount_;
        probe.pageGeneration = page.pageGeneration;
        probe.pageFrozen = page.frozen;
        for (std::uint32_t index = 0; index < probe.pageEventCount; ++index)
            if (pool.PageEvent(base + index).txnSlot == probe.slot)
                ++probe.matchingPageEvents;
        *out = probe;
        return true;
    }
    static bool RawPageEventCount(
        const ScheduledTransactionPool& pool,
        const Plan03GroupSliceIdentity& identity,
        std::uint32_t* out,
        std::uint32_t* outGroups = nullptr,
        std::uint32_t* outFrameBatches = nullptr) noexcept {
        if (out == nullptr || !identity.Exact() ||
            identity.backing != Plan03GroupBacking::Page ||
            !pool.Valid() || identity.transportEpoch != pool.epoch_ ||
            identity.absoluteQuantum < pool.baseQuantumIndex_ ||
            identity.absoluteQuantum - pool.baseQuantumIndex_ >= pool.pageCount_ ||
            pool.PageStamp(identity.absoluteQuantum) != identity.absoluteQuantum) {
            return false;
        }
        Plan03PageGroupView group{};
        if (!pool.ResolvePlan03GroupSliceProducer(identity, &group) ||
            !(group.identity == identity)) return false;
        const auto ring = static_cast<std::uint32_t>(
            (identity.absoluteQuantum - pool.sessionBaseQuantumIndex_) % pool.pageCount_);
        const auto& page = pool.pageHeaders_[ring];
        if (!page.frozen || page.transportEpoch != identity.transportEpoch ||
            page.absoluteQuantumIndex != identity.absoluteQuantum ||
            page.pageGeneration != identity.pageGeneration) return false;
        *out = pool.pageEventCount_[ring];
        if (outGroups != nullptr) *outGroups = pool.pagePlan03GroupCount_[ring];
        if (outFrameBatches != nullptr)
            *outFrameBatches = pool.pageBatchCount_[ring];
        return true;
    }
};
bool CaptureOrdinaryTransactionForTest(
    const ScheduledTransactionPool& pool,
    TimelineTransactionProgramRef program,
    std::uint64_t absoluteQuantum,
    OrdinaryTransactionProbeForTest* out) noexcept {
    return ScheduledTransactionPoolTestAccess::CaptureOrdinaryTransaction(
        pool, program, absoluteQuantum, out);
}
