std::string ActionStreamTempPath(const char* name) {
    return std::string(HARKEN_TEMP_DIR "/") + name;
}

std::string WriteActionStream(const char* name, VnSoundId soundId,
                              const std::vector<float>& samples,
                              bool loopable = false) {
    harkentest::StreamSpec spec{};
    spec.soundId = soundId;
    spec.sampleRate = 48000;
    spec.channelCount = 1;
    spec.chunkFrames = 64;
    spec.loopable = loopable;
    spec.loopStartFrame = loopable ? 256 : 0;
    spec.loopEndFrame = loopable ? 1024 : 0;
    const std::string path = ActionStreamTempPath(name);
    harkentest::WriteFileBytes(
        path, harkentest::BuildStreamBytes(spec, samples));
    return path;
}

struct OriginalSourceRetirementProof {
    harken::SourceTerminalToken token{};
    harken::PlayableInstanceHandle leaf = 0;
    std::uint64_t epoch = 0;
    harken::VoiceReleaseObserver release{};
};

std::vector<std::uint32_t> CaptureSourceGenerations(harken::Engine& engine) {
    std::vector<std::uint32_t> generations(engine.sourceTerminals.Capacity());
    for (std::uint32_t slot = 0; slot < generations.size(); ++slot)
        generations[slot] = engine.sourceTerminals.At(slot)->generation;
    return generations;
}

void ExpectBoundSourcesReleased(harken::Engine& engine,
    const std::vector<std::uint32_t>& generations) {
    std::uint32_t bindingsReleased = 0;
    for (std::uint32_t slot = 0; slot < generations.size(); ++slot) {
        const auto& record = *engine.sourceTerminals.At(slot);
        if (record.generation == generations[slot]) continue;
        ++bindingsReleased;
        EXPECT_FALSE(record.occupied);
        EXPECT_TRUE(engine.voices.ReleaseObserved(record.release));
        EXPECT_FALSE(engine.playableInstances.HasSourceRetirementHold(record.leaf));
        EXPECT_FALSE(engine.playableInstances.Classify(record.leaf).live);
    }
    EXPECT_GT(bindingsReleased, 0u);
}

OriginalSourceRetirementProof CaptureOriginalSource(
    harken::Engine& engine, harken::PlayableInstanceHandle leaf) {
    const auto slot = engine.playableInstances.SourceRetirementSlot(leaf);
    const auto* source = engine.sourceTerminals.At(slot);
    EXPECT_NE(nullptr, source);
    if (source == nullptr) return {};
    EXPECT_TRUE(source->occupied);
    EXPECT_EQ(leaf, source->leaf);
    return {{slot, source->generation}, leaf, source->acceptedEpoch, source->release};
}

void ExpectOriginalSourceRetiresAfterLaterBlock(
    harken::Engine& engine, const OriginalSourceRetirementProof& original) {
    const auto* source = engine.sourceTerminals.Resolve(original.token);
    ASSERT_NE(nullptr, source);
    for (std::uint32_t block = 0; block < 96 && !source->releaseSeen; ++block) {
        engine.nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        source = engine.sourceTerminals.Resolve(original.token);
        ASSERT_NE(nullptr, source);
    }
    ASSERT_TRUE(source->releaseSeen);
    ASSERT_TRUE(engine.voices.ReleaseObserved(original.release));
    ASSERT_EQ(original.leaf, source->leaf);
    ASSERT_EQ(original.epoch, source->acceptedEpoch);
    const auto releaseSequence = source->releaseSeenAt;
    ASSERT_EQ(releaseSequence, engine.mixer.BlocksRendered());
    for (std::uint32_t repeat = 0; repeat < 3; ++repeat) {
        ASSERT_EQ(VN_OK, Vn_Update());
        EXPECT_EQ(releaseSequence, engine.mixer.BlocksRendered());
        EXPECT_TRUE(engine.playableInstances.Classify(original.leaf).live);
        EXPECT_TRUE(engine.playableInstances.HasSourceRetirementHold(original.leaf));
        EXPECT_NE(nullptr, engine.sourceTerminals.Resolve(original.token));
    }
    engine.nullBackend.Pump(1);
    ASSERT_EQ(VN_OK, Vn_Update());
    EXPECT_GT(engine.mixer.BlocksRendered(), releaseSequence);
    EXPECT_FALSE(engine.playableInstances.Classify(original.leaf).live);
    EXPECT_EQ(nullptr, engine.sourceTerminals.Resolve(original.token));
}

void ExpectVariableControlNaturalCompletion(
    harken::Engine& engine, VnActionFiringHandle firing, VnActionFiringInfo* info) {
    for (std::uint32_t block = 0; block < 96; ++block) {
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, info));
        if (info->state == VN_ACTION_FIRING_TERMINAL_RETAINED) break;
        engine.nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
    }
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, info));
    ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info->state);
    EXPECT_EQ(VN_ACTION_OUTCOME_SUCCEEDED, info->outcome);
    EXPECT_EQ(VN_ACTION_TERMINAL_NATURAL, info->terminalReason);
    bool played = false;
    for (std::uint32_t index = 0; index < info->directStepCount; ++index) {
        VnActionStepResult step{};
        step.structSize = sizeof(step);
        ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, index, &step));
        if (step.producedPlayableInstance == 0) continue;
        played = true;
        EXPECT_EQ(VN_ACTION_STEP_SUCCEEDED, step.state);
        EXPECT_FALSE(engine.playableInstances.Classify(step.producedPlayableInstance).live);
        EXPECT_TRUE(std::none_of(engine.playableServices.begin(), engine.playableServices.end(),
            [&](const auto& row) { return row.rootInstance == step.producedPlayableInstance && row.frontierLifetimePin.Valid(); }));
    }
    EXPECT_TRUE(played);
    for (std::uint32_t block = 0; block < 4; ++block) {
        engine.nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
    }
}

void ExpectVariableControlNaturalTreeCompletion(
    harken::Engine& engine, VnActionFiringHandle firing,
    harken::PlayableInstanceHandle instance, VnActionFiringInfo* info) {
    ASSERT_NO_FATAL_FAILURE(ExpectVariableControlNaturalCompletion(engine, firing, info));
    EXPECT_FALSE(engine.playableInstances.Classify(instance).live);
}

TEST(ActionFiringApi,
     TimelineVoiceOwnerRetainsRollbackTokenUntilUnbindCanRetry) {
    (void)Vn_Term();
    harkentest::EngineSession session(
        harkentest::MakeNullConfig(2, 64, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();

    harken::OccurrenceToken occurrence{};
    ASSERT_TRUE(engine->timelineOccurrences.Acquire({}, &occurrence));
    constexpr std::uint32_t kBoundRenderGeneration = 17;
    ASSERT_TRUE(engine->timelineOccurrences.BindCompletionProgress(
        occurrence, kBoundRenderGeneration, 23));

    harken::EnginePreparedTimelineVoiceStart prepared{};
    prepared.renderHandle = static_cast<VnVoiceHandle>(19) << 32;
    prepared.progressOccurrence = occurrence;
    prepared.completionProgressBound = true;
    harken::EngineActionPlayScratch::PreparedTimelineVoiceOwnerContext owner{
        engine, &prepared, true};

    engine->forceTimelineVoiceCommitRollbackUnbindFailureForTest = true;
    EXPECT_FALSE(harken::detail::CancelPreparedTimelineVoiceOwnerForTests(
        &owner));
    EXPECT_FALSE(engine->forceTimelineVoiceCommitRollbackUnbindFailureForTest);
    EXPECT_TRUE(owner.committed);
    EXPECT_EQ((static_cast<VnVoiceHandle>(19) << 32),
              prepared.renderHandle);
    EXPECT_EQ(occurrence.slot, prepared.progressOccurrence.slot);
    EXPECT_EQ(occurrence.generation,
              prepared.progressOccurrence.generation);
    EXPECT_TRUE(prepared.completionProgressBound);
    EXPECT_NE(nullptr,
              engine->timelineOccurrences.CompletionProgressOf(occurrence));

    prepared.renderHandle =
        static_cast<VnVoiceHandle>(kBoundRenderGeneration) << 32;
    EXPECT_TRUE(harken::detail::CancelPreparedTimelineVoiceOwnerForTests(
        &owner));
    EXPECT_FALSE(owner.committed);
    EXPECT_EQ(0u, prepared.renderHandle);
    EXPECT_EQ(0u, prepared.progressOccurrence.generation);
    EXPECT_FALSE(prepared.completionProgressBound);
    EXPECT_EQ(nullptr,
              engine->timelineOccurrences.CompletionProgressOf(occurrence));
}

TEST(ActionFiringApi, FreshActionScratchExecutorReservesRootAndChild)
{
    auto storageOwner = std::make_unique<harken::EngineActionPlayStorage>();
    auto scratchOwner =
        std::make_unique<harken::EngineActionPlayScratch>(*storageOwner);
    auto& scratch = *scratchOwner;
    harken::PlayableInstanceTable instances(2);
    harken::PreparedPlayableInstance root{};
    ASSERT_TRUE(instances.PrepareAcquire(
        harken::PlayableKind::Container, 0, &root));
    ASSERT_TRUE(scratch.playableTreeExecutor.AdoptPreparedInstance(
        instances, &root));
    ASSERT_TRUE(scratch.playableTreeExecutor.PrepareInstance(
        instances, harken::PlayableKind::Sound, root.Handle()));
    EXPECT_EQ(1u, scratch.playableTreeExecutor.InstanceReservationCount());
    scratch.playableTreeExecutor.Cancel(instances);
    EXPECT_EQ(instances.Capacity(), instances.FreeCount());
}

TEST(ActionFiringApi, EngineTeardownReturnsItsDeferredPairLoansBeforeReceivers) {
    const auto input = harkentest::MakeNullConfig(1, 64, 48000);
    harken::EngineConfig config{};
    ASSERT_EQ(VN_OK, harken::ResolveConfig(&input, &config));
    auto storage = std::make_unique<harken::Engine>(config);
    auto& engine = *storage;
    auto& scratch = engine.actionDeferredScratch.front();
    harken::ActionDeferredRecord record{};
    record.firing = UINT64_C(0x0000000100000001);
    record.ownerCancellationEpoch = 1;
    record.owner = harken::ActionDeferredOwner::DirectWorld(11);
    record.executionOrdinal = 7;
    record.intendedBoundaryFrame = 100;
    for (unsigned iteration = 0; iteration < 3; ++iteration) {
        const auto prepared = engine.actionDeferredRecords.Prepare(record);
        ASSERT_EQ(harken::ActionDeferredRecordPrepareStatus::Prepared, prepared.status);
        scratch.recordToken = prepared.token;
        harken::DeferredIntent intent{};
        intent.ownerDomain = harken::DeferredIntentOwnerDomain::Action;
        intent.ownerHandle = record.firing;
        intent.ownerEpoch = record.ownerCancellationEpoch;
        intent.executionOrdinal = record.executionOrdinal;
        intent.dueFrame = record.intendedBoundaryFrame;
        intent.payload = scratch.recordToken.slot;
        const auto added = engine.timelineDeferred.AddPrepared(intent);
        ASSERT_EQ(harken::DeferredIntentRefusal::None, added.status);
        scratch.poolToken = added.token;
        ASSERT_TRUE(engine.actionDeferredRecords.ProvePreparedPair(
            scratch.recordToken, engine.timelineDeferred, scratch.poolToken,
            &scratch.pairCommitProof));
        ASSERT_TRUE(scratch.pairCommitProof.Valid());
        EXPECT_FALSE(engine.timelineDeferred.AbandonPrepared(scratch.poolToken));
        if (iteration == 2) break;
        engine.ReturnPreparedActionDeferredLoansAfterQuiescence();
        engine.ReturnPreparedActionDeferredLoansAfterQuiescence();
        EXPECT_FALSE(scratch.pairCommitProof.Valid());
        EXPECT_EQ(1u, engine.actionDeferredRecords.PreparedCount());
        EXPECT_EQ(1u, engine.timelineDeferred.PreparedCount());
        EXPECT_EQ(0u, engine.actionDeferredRecords.LiveCount());
        EXPECT_EQ(0u, engine.timelineDeferred.Count());
        ASSERT_TRUE(engine.timelineDeferred.AbandonPrepared(scratch.poolToken));
        ASSERT_TRUE(engine.actionDeferredRecords.Abandon(&scratch.recordToken));
        EXPECT_EQ(0u, engine.actionDeferredRecords.PreparedCount());
        EXPECT_EQ(0u, engine.timelineDeferred.PreparedCount());
    }
    // Direct internal deletion also returns Engine-owned loans after real join.
    storage.reset();
}

TEST(ActionFiringApi, FrontierAttemptOwnsConfiguredTreeBeyondExternalAdoptionLimit) {
    const auto input = harkentest::MakeNullConfig(1, 64, 48000);
    harken::EngineConfig config{};
    ASSERT_EQ(VN_OK, harken::ResolveConfig(&input, &config));
    config.maxPlayableInstances = 514;
    auto storage = std::make_unique<harken::Engine>(config);
    auto& engine = *storage;
    ASSERT_TRUE(engine.EnsureActionPlaySlot(0));
    auto& executor = engine.actionPlayScratch[0].playableTreeExecutor;
    const auto freeBefore = engine.playableInstances.FreeCount();
    ASSERT_TRUE(executor.PrepareInstance(engine.playableInstances, harken::PlayableKind::Container));
    const auto root = executor.PreparedInstanceHandle(0);
    for (std::uint32_t index = 1; index < config.maxPlayableInstances; ++index) {
        ASSERT_TRUE(executor.PrepareInstance(engine.playableInstances, harken::PlayableKind::Sound, root))
            << "node=" << index;
    }
    EXPECT_EQ(config.maxPlayableInstances, executor.InstanceReservationCount());
    EXPECT_FALSE(executor.PrepareInstance(engine.playableInstances, harken::PlayableKind::Sound, root));
    ASSERT_TRUE(executor.Commit());
    EXPECT_EQ(config.maxPlayableInstances, engine.playableInstances.LiveCount());
    std::uint32_t children = 0;
    for (auto child = engine.playableInstances.FirstChild(root); child != 0;
         child = engine.playableInstances.NextSibling(child)) {
        EXPECT_EQ(root, engine.playableInstances.Classify(child).parent);
        ++children;
    }
    EXPECT_EQ(config.maxPlayableInstances - 1u, children);
    ASSERT_TRUE(executor.RollbackCommitted(engine.playableInstances));
    EXPECT_EQ(freeBefore, engine.playableInstances.FreeCount());
    EXPECT_TRUE(executor.ResetForReuse());
}

TEST(ActionFiringApi, FrontierLedgerRetainsRealOccurrenceAndTreeUntilVoiceUnbindRecovers) {
    harkentest::EngineSession session(harkentest::MakeNullConfig(2, 64, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto& engine = *session.Engine();
    ASSERT_TRUE(engine.EnsureActionPlaySlot(0));
    auto& storage = engine.actionPlayStorage[0];
    auto& ledger = storage.ownerLedger;
    ASSERT_TRUE(ledger.Begin(1));
    storage.ownerBatch = {&ledger, 1};
    harken::OccurrenceToken occurrence{};
    ASSERT_TRUE(engine.timelineOccurrences.PrepareAcquire({}, &occurrence));
    ASSERT_TRUE(engine.timelineOccurrences.CommitPreparedAcquire(occurrence));
    const auto original = occurrence;
    bool prepared = false;
    constexpr std::uint32_t renderGeneration = 17;
    ASSERT_TRUE(engine.timelineOccurrences.BindCompletionProgress(occurrence, renderGeneration, 23));
    harken::EnginePreparedTimelineVoiceStart voice{};
    voice.renderHandle = static_cast<VnVoiceHandle>(renderGeneration) << 32;
    voice.progressOccurrence = occurrence;
    voice.completionProgressBound = true;
    harken::EngineActionPlayScratch::PreparedTimelineVoiceOwnerContext voiceOwner{&engine, &voice, true};
    harken::EngineActionPlayScratch::PreparedOccurrenceOwnerContext occurrenceOwner{
        &engine.timelineOccurrences, &occurrence, &prepared};
    const auto valid = [](void*) noexcept { return true; };
    const auto commit = [](void*, std::uint64_t) noexcept { return true; };
    // Discovery order deliberately disagrees with the required cancellation order.
    ASSERT_TRUE(ledger.Add(1, {harken::FrontierOwnerKind::Voice, 0, renderGeneration}, &voiceOwner,
        harken::FrontierOwnerCommitPhase::Voice, harken::FrontierOwnerCancelPhase::Voice,
        valid, commit, [](void* context) noexcept {
            return harken::detail::CancelPreparedTimelineVoiceOwnerForTests(
                static_cast<harken::EngineActionPlayScratch::PreparedTimelineVoiceOwnerContext*>(context));
        }));
    ASSERT_TRUE(ledger.Add(1, {harken::FrontierOwnerKind::Occurrence, original.slot, original.generation},
        &occurrenceOwner, harken::FrontierOwnerCommitPhase::Completion,
        harken::FrontierOwnerCancelPhase::Completion, valid, commit, [](void* context) noexcept {
            return harken::detail::CancelPreparedOccurrenceOwnerForTests(
                static_cast<harken::EngineActionPlayScratch::PreparedOccurrenceOwnerContext*>(context));
        }));
    auto& executor = *storage.playableTreeExecutor;
    ASSERT_TRUE(executor.PrepareInstance(engine.playableInstances, harken::PlayableKind::Sound));
    const auto root = executor.PreparedInstanceHandle(0);
    ASSERT_TRUE(executor.EnablePreparedOwnerRollbackRetention());
    ASSERT_TRUE(executor.AdoptPreparedOwnerToken(&storage.ownerBatch,
        harken::EngineFrontierOwnerBatch::Validate, harken::EngineFrontierOwnerBatch::Commit,
        harken::EngineFrontierOwnerBatch::Cancel));
    ASSERT_TRUE(executor.Commit(11));
    EXPECT_EQ(0u, executor.OwnerTokenCount());
    engine.forceTimelineVoiceCommitRollbackUnbindFailureForTest = true;
    EXPECT_FALSE(executor.RollbackCommitted(engine.playableInstances));
    EXPECT_EQ(2u, ledger.UnresolvedCount());
    EXPECT_FALSE(ledger.Begin(2));
    EXPECT_TRUE(engine.playableInstances.Classify(root).live);
    EXPECT_NE(nullptr, engine.timelineOccurrences.CompletionProgressOf(original));
    EXPECT_EQ(original.generation, occurrence.generation);
    EXPECT_FALSE(executor.ResetForReuse());
    ASSERT_TRUE(executor.RollbackCommitted(engine.playableInstances));
    EXPECT_TRUE(ledger.Empty());
    EXPECT_FALSE(engine.playableInstances.Classify(root).live);
    EXPECT_EQ(harken::OccurrenceStage::Free, engine.timelineOccurrences.StageOf(original));
    EXPECT_TRUE(executor.ResetForReuse());
    ASSERT_TRUE(ledger.Begin(2));
    EXPECT_FALSE(harken::EngineFrontierOwnerBatch::Cancel(&storage.ownerBatch));
}

TEST(ActionFiringApi, FrontierLedgerChargesEachDomainAndUsesOneOuterCallbackBeyond640Owners) {
    auto input = harkentest::MakeNullConfig(1, 64, 48000);
    harken::EngineConfig config{};
    ASSERT_EQ(VN_OK, harken::ResolveConfig(&input, &config));
    config.maxPlayableInstances = 641;
    auto engineStorage = std::make_unique<harken::Engine>(config);
    auto& engine = *engineStorage;
    ASSERT_TRUE(engine.EnsureActionPlaySlot(0));
    auto& storage = engine.actionPlayStorage[0];
    auto& ledger = storage.ownerLedger;
    ASSERT_TRUE(ledger.Begin(7));
    storage.ownerBatch = {&ledger, 7};
    struct Context { std::uint32_t committed = 0; std::uint32_t cancelled = 0; };
    std::vector<Context> contexts(config.maxPlayableInstances + 1u);
    const auto add = [&](std::uint32_t index, harken::FrontierOwnerKind kind) {
        return ledger.Add(7, {kind, index, 1}, &contexts[index],
            harken::FrontierOwnerCommitPhase::Mode, harken::FrontierOwnerCancelPhase::Mode,
            [](void*) noexcept { return true; },
            [](void* opaque, std::uint64_t ticket) noexcept {
                if (ticket != 19) return false;
                ++static_cast<Context*>(opaque)->committed;
                return true;
            }, [](void* opaque) noexcept {
                ++static_cast<Context*>(opaque)->cancelled;
                return true;
            });
    };
    for (std::uint32_t index = 0; index < config.maxPlayableInstances; ++index)
        ASSERT_TRUE(add(index, harken::FrontierOwnerKind::Service));
    EXPECT_GT(ledger.Capacity(), ledger.UnresolvedCount());
    EXPECT_FALSE(add(config.maxPlayableInstances, harken::FrontierOwnerKind::Service));
    EXPECT_FALSE(add(0, harken::FrontierOwnerKind::Service));
    EXPECT_FALSE(add(0, harken::FrontierOwnerKind::Mode));
    auto& executor = *storage.playableTreeExecutor;
    ASSERT_TRUE(executor.PrepareInstance(engine.playableInstances, harken::PlayableKind::Sound));
    ASSERT_TRUE(executor.EnablePreparedOwnerRollbackRetention());
    ASSERT_TRUE(executor.AdoptPreparedOwnerToken(&storage.ownerBatch,
        harken::EngineFrontierOwnerBatch::Validate, harken::EngineFrontierOwnerBatch::Commit,
        harken::EngineFrontierOwnerBatch::Cancel));
    EXPECT_EQ(1u, executor.OwnerTokenCount());
    ASSERT_TRUE(executor.Commit(19));
    ASSERT_TRUE(executor.RollbackCommitted(engine.playableInstances));
    for (std::uint32_t index = 0; index < config.maxPlayableInstances; ++index) {
        EXPECT_EQ(1u, contexts[index].committed);
        EXPECT_EQ(1u, contexts[index].cancelled);
    }
    EXPECT_EQ(0u, contexts.back().committed);
    EXPECT_TRUE(ledger.Empty());
}

TEST(ActionFiringApi, FrontierLedgerPartialCommitKeepsDependencyPhasesAndExactGeneration) {
    harken::EngineFrontierOwnerLedger ledger;
    harken::EngineFrontierOwnerLedger::Limits limits{};
    limits[static_cast<std::size_t>(harken::FrontierOwnerKind::Selection)] = 1;
    limits[static_cast<std::size_t>(harken::FrontierOwnerKind::Timeline)] = 1;
    ledger.Initialize(limits);
    ASSERT_TRUE(ledger.Begin(41));
    struct Context {
        std::uint32_t commits = 0;
        std::uint32_t cancels = 0;
        bool failCommit = false;
        bool failCancel = false;
        Context* dependency = nullptr;
    } selection{}, publication{};
    publication.failCommit = true;
    publication.failCancel = true;
    publication.dependency = &selection;
    const auto add = [&](Context& context, harken::FrontierOwnerKind kind,
                         harken::FrontierOwnerCommitPhase commitPhase,
                         harken::FrontierOwnerCancelPhase cancelPhase) {
        return ledger.Add(41, {kind, 0, 9}, &context, commitPhase, cancelPhase,
            [](void*) noexcept { return true; },
            [](void* opaque, std::uint64_t) noexcept {
                auto& owner = *static_cast<Context*>(opaque);
                if (owner.dependency != nullptr && owner.dependency->commits != 1) return false;
                ++owner.commits;
                return !owner.failCommit;
            }, [](void* opaque) noexcept {
                auto& owner = *static_cast<Context*>(opaque);
                ++owner.cancels;
                return !owner.failCancel;
            });
    };
    ASSERT_TRUE(add(publication, harken::FrontierOwnerKind::Timeline,
        harken::FrontierOwnerCommitPhase::Publication, harken::FrontierOwnerCancelPhase::Exposure));
    ASSERT_TRUE(add(selection, harken::FrontierOwnerKind::Selection,
        harken::FrontierOwnerCommitPhase::Selection, harken::FrontierOwnerCancelPhase::Selection));
    EXPECT_FALSE(ledger.Commit(41, 23));
    EXPECT_EQ(1u, selection.commits);
    EXPECT_EQ(1u, publication.commits);
    EXPECT_FALSE(ledger.Transfer(41));
    EXPECT_FALSE(ledger.Cancel(41));
    EXPECT_EQ(0u, selection.cancels);
    EXPECT_EQ(2u, ledger.UnresolvedCount());
    EXPECT_FALSE(ledger.Begin(42));
    publication.failCancel = false;
    ASSERT_TRUE(ledger.Cancel(41));
    EXPECT_EQ(1u, selection.cancels);
    EXPECT_EQ(2u, publication.cancels);
    ASSERT_TRUE(ledger.Begin(42));
    EXPECT_FALSE(ledger.Cancel(41));
    EXPECT_FALSE(ledger.Begin(41));
    EXPECT_TRUE(ledger.Commit(42, 24));
    EXPECT_TRUE(ledger.Transfer(42));
    EXPECT_FALSE(ledger.Cancel(42));
}

TEST(ActionFiringApi, FrontierLedgerRealTimelineRegistrationCapacityRetainsPinnedPrefix) {
    auto input = harkentest::MakeNullConfig(1, 64, 48000);
    harken::EngineConfig config{};
    ASSERT_EQ(VN_OK, harken::ResolveConfig(&input, &config));
    config.maxScheduledTransactions = 1;
    auto engineStorage = std::make_unique<harken::Engine>(config);
    auto& engine = *engineStorage;
    ASSERT_TRUE(engine.EnsureActionPlaySlot(0));
    auto& ledger = engine.actionPlayStorage[0].ownerLedger;
    const auto armBaseline = engine.timelineArms.LiveCount();
    struct Context {
        harken::TimelineArmTable* table = nullptr;
        harken::TimelineArmToken arm{};
    } first{&engine.timelineArms}, second{&engine.timelineArms};
    const auto prepare = [&](Context& owner, std::uint32_t renderGeneration) {
        return owner.table->Prepare(0, renderGeneration, 256, 192, 7, {}, &owner.arm);
    };
    const auto add = [&](std::uint64_t generation, Context& owner) {
        return ledger.Add(generation,
            {harken::FrontierOwnerKind::Timeline, owner.arm.slot, owner.arm.generation},
            &owner, harken::FrontierOwnerCommitPhase::Publication,
            harken::FrontierOwnerCancelPhase::Exposure,
            [](void* opaque) noexcept {
                auto& context = *static_cast<Context*>(opaque);
                harken::ArmState state{};
                return context.table->State(context.arm, &state) &&
                    state == harken::ArmState::Prepared;
            }, [](void* opaque, std::uint64_t) noexcept {
                auto& context = *static_cast<Context*>(opaque);
                return context.table->CommitPrepared(context.arm);
            }, [](void* opaque) noexcept {
                auto& context = *static_cast<Context*>(opaque);
                return context.table->CancelPrepared(context.arm);
            });
    };
    ASSERT_TRUE(prepare(first, 7));
    ASSERT_TRUE(prepare(second, 8));
    ASSERT_NE(first.arm.slot, second.arm.slot);
    ASSERT_TRUE(ledger.Begin(1));
    ASSERT_TRUE(add(1, first));
    EXPECT_GT(ledger.Capacity(), ledger.UnresolvedCount());
    EXPECT_FALSE(add(1, second));
    EXPECT_EQ(1u, ledger.UnresolvedCount());
    EXPECT_EQ(1u, ledger.NextContextSlot(harken::FrontierOwnerKind::Timeline));
    ASSERT_TRUE(ledger.Validate(1));
    harken::TimelineArmReaderPin reader;
    ASSERT_TRUE(engine.timelineArms.PinFrontierReader(first.arm, &reader));
    EXPECT_FALSE(ledger.Cancel(1));
    EXPECT_EQ(1u, ledger.UnresolvedCount());
    EXPECT_FALSE(ledger.Begin(2));
    harken::ArmState state{};
    ASSERT_TRUE(engine.timelineArms.State(first.arm, &state));
    EXPECT_EQ(harken::ArmState::Prepared, state);
    ASSERT_TRUE(engine.timelineArms.State(second.arm, &state));
    EXPECT_EQ(harken::ArmState::Prepared, state);
    ASSERT_TRUE(reader.Release(0));
    ASSERT_TRUE(ledger.Cancel(1));
    EXPECT_TRUE(ledger.Empty());
    EXPECT_FALSE(engine.timelineArms.State(first.arm, &state));
    ASSERT_TRUE(engine.timelineArms.State(second.arm, &state));
    EXPECT_EQ(harken::ArmState::Prepared, state);
    ASSERT_TRUE(engine.timelineArms.CancelPrepared(second.arm));
    EXPECT_EQ(armBaseline, engine.timelineArms.LiveCount());

    const auto original = first.arm;
    ASSERT_TRUE(ledger.Begin(2));
    ASSERT_TRUE(prepare(first, 9));
    EXPECT_TRUE(first.arm.slot != original.slot ||
        first.arm.generation != original.generation ||
        first.arm.renderSlot != original.renderSlot ||
        first.arm.renderGeneration != original.renderGeneration);
    EXPECT_FALSE(engine.timelineArms.CancelPrepared(original));
    ASSERT_TRUE(add(2, first));
    ASSERT_TRUE(ledger.Validate(2));
    EXPECT_FALSE(ledger.Cancel(1));
    EXPECT_EQ(1u, ledger.UnresolvedCount());
    ASSERT_TRUE(engine.timelineArms.State(first.arm, &state));
    EXPECT_EQ(harken::ArmState::Prepared, state);
    ASSERT_TRUE(ledger.Cancel(2));
    EXPECT_TRUE(ledger.Empty());
    EXPECT_EQ(armBaseline, engine.timelineArms.LiveCount());
    EXPECT_FALSE(engine.runtimeRecreateRequired);
}

TEST(ActionFiringApi, FrontierInitialDecisionCancellationRetainsModeUntilActualPinRelease) {
    harken::DecisionTable decisions(1, 1);
    harken::DecisionReserveRequest request{};
    request.world = 3;
    request.transport = 1;
    request.expectedContinuationGeneration = 5;
    request.sliceCount = 2;
    harken::PreparedDecisionReservation reservation{};
    ASSERT_TRUE(decisions.PrepareReservation(request, &reservation));
    const auto decision = reservation.Token();
    harken::DecisionFuturePin sourcePin{};
    harken::DecisionFuturePin readerPin{};
    ASSERT_TRUE(decisions.AcquireFuturePin(decision, &sourcePin));
    ASSERT_TRUE(decisions.AcquireFuturePin(decision, &readerPin));
    struct Source {
        harken::DecisionFuturePin* pin = nullptr;
        bool ready = false;
        std::uint32_t cancellations = 0;
    } source{&sourcePin};
    struct Initial {
        harken::DecisionTable* table = nullptr;
        harken::PreparedDecisionReservation* reservation = nullptr;
        std::uint32_t cancellations = 0;
    } initial{&decisions, &reservation};
    struct Mode {
        harken::DecisionTable* table = nullptr;
        std::uint32_t cancellations = 0;
    } mode{&decisions};
    harken::EngineFrontierOwnerLedger ledger;
    harken::EngineFrontierOwnerLedger::Limits limits{};
    limits[static_cast<std::size_t>(harken::FrontierOwnerKind::Occurrence)] = 1;
    limits[static_cast<std::size_t>(harken::FrontierOwnerKind::Decision)] = 1;
    limits[static_cast<std::size_t>(harken::FrontierOwnerKind::Mode)] = 1;
    ledger.Initialize(limits);
    ASSERT_TRUE(ledger.Begin(41));
    const auto validate = [](void*) noexcept { return true; };
    const auto commit = [](void*, std::uint64_t) noexcept { return true; };
    ASSERT_TRUE(ledger.Add(41, {harken::FrontierOwnerKind::Occurrence, 0, 1}, &source,
        harken::FrontierOwnerCommitPhase::Completion, harken::FrontierOwnerCancelPhase::Completion,
        validate, commit, [](void* opaque) noexcept {
            auto& owner = *static_cast<Source*>(opaque);
            ++owner.cancellations;
            return owner.ready && owner.pin->Release();
        }));
    ASSERT_TRUE(ledger.Add(41, {harken::FrontierOwnerKind::Mode, 0, 1}, &mode,
        harken::FrontierOwnerCommitPhase::Mode, harken::FrontierOwnerCancelPhase::Mode,
        validate, commit, [](void* opaque) noexcept {
            auto& owner = *static_cast<Mode*>(opaque);
            if (owner.table->LiveCount() != 0) return false;
            ++owner.cancellations;
            return true;
        }));
    ASSERT_TRUE(ledger.Add(41, {harken::FrontierOwnerKind::Decision, decision.slot, decision.generation}, &initial,
        harken::FrontierOwnerCommitPhase::Decision, harken::FrontierOwnerCancelPhase::InitialDecision,
        validate, commit, [](void* opaque) noexcept {
            auto& owner = *static_cast<Initial*>(opaque);
            ++owner.cancellations;
            return owner.table->CancelPreparedReservation(owner.reservation);
        }));
    EXPECT_FALSE(ledger.Cancel(41));
    EXPECT_EQ(0u, initial.cancellations);
    EXPECT_EQ(0u, mode.cancellations);
    EXPECT_TRUE(reservation.Valid());
    EXPECT_TRUE(sourcePin.Valid());
    source.ready = true;
    EXPECT_FALSE(ledger.Cancel(41));
    EXPECT_FALSE(sourcePin.Valid());
    EXPECT_TRUE(readerPin.Valid());
    EXPECT_TRUE(reservation.Valid());
    EXPECT_TRUE(decisions.IsOpen(decision));
    EXPECT_EQ(2u, source.cancellations);
    EXPECT_EQ(1u, initial.cancellations);
    EXPECT_EQ(0u, mode.cancellations);
    EXPECT_EQ(2u, ledger.UnresolvedCount());
    ASSERT_TRUE(readerPin.Release());
    ASSERT_TRUE(ledger.Cancel(41));
    EXPECT_EQ(2u, source.cancellations);
    EXPECT_EQ(2u, initial.cancellations);
    EXPECT_EQ(1u, mode.cancellations);
    EXPECT_FALSE(reservation.Valid());
    EXPECT_FALSE(decisions.Contains(decision));
    EXPECT_TRUE(ledger.Empty());
    ASSERT_TRUE(ledger.Begin(42));
    EXPECT_FALSE(ledger.Cancel(41));
}

TEST(ActionFiringApi, RetainedOccurrenceAndVoiceOwnersKeepOriginalGenerationUntilUnbindRecovery) {
    for (const bool preparedOccurrence : {false, true}) {
        SCOPED_TRACE(preparedOccurrence);
        harkentest::EngineSession session(harkentest::MakeNullConfig(2, 64, 48000));
        ASSERT_EQ(VN_OK, session.InitResult());
        auto& engine = *session.Engine();
        const auto baseline = engine.timelineOccurrences.OccupiedCount();
        harken::OccurrenceToken occurrence{};
        ASSERT_TRUE(engine.timelineOccurrences.PrepareAcquire({}, &occurrence));
        bool prepared = true;
        if (!preparedOccurrence) {
            ASSERT_TRUE(engine.timelineOccurrences.CommitPreparedAcquire(occurrence));
            prepared = false;
        }
        const auto original = occurrence;
        constexpr std::uint32_t renderGeneration = 17;
        ASSERT_TRUE(engine.timelineOccurrences.BindCompletionProgress(occurrence, renderGeneration, 23));
        harken::EnginePreparedTimelineVoiceStart voice{};
        voice.renderHandle = static_cast<VnVoiceHandle>(renderGeneration) << 32;
        voice.progressOccurrence = occurrence;
        voice.completionProgressBound = true;
        harken::EngineActionPlayScratch::PreparedTimelineVoiceOwnerContext voiceOwner{&engine, &voice, true};
        harken::EngineActionPlayScratch::PreparedOccurrenceOwnerContext occurrenceOwner{
            &engine.timelineOccurrences, &occurrence, &prepared};
        harken::PlayableTreeExecutor executor(1);
        ASSERT_TRUE(executor.PrepareInstance(engine.playableInstances, harken::PlayableKind::Sound));
        const auto root = executor.PreparedInstanceHandle(0);
        ASSERT_TRUE(executor.EnablePreparedOwnerRollbackRetention());
        ASSERT_TRUE(executor.Commit());
        ASSERT_TRUE(executor.AdoptCommittedOwnerToken(&occurrenceOwner, [](void* context) noexcept {
            return harken::detail::CancelPreparedOccurrenceOwnerForTests(
                static_cast<harken::EngineActionPlayScratch::PreparedOccurrenceOwnerContext*>(context));
        }));
        ASSERT_TRUE(executor.AdoptCommittedOwnerToken(&voiceOwner, [](void* context) noexcept {
            return harken::detail::CancelPreparedTimelineVoiceOwnerForTests(
                static_cast<harken::EngineActionPlayScratch::PreparedTimelineVoiceOwnerContext*>(context));
        }));
        engine.forceTimelineVoiceCommitRollbackUnbindFailureForTest = true;
        EXPECT_FALSE(executor.RollbackCommitted(engine.playableInstances));
        EXPECT_FALSE(engine.forceTimelineVoiceCommitRollbackUnbindFailureForTest);
        EXPECT_EQ(original.slot, occurrence.slot);
        EXPECT_EQ(original.generation, occurrence.generation);
        EXPECT_NE(nullptr, engine.timelineOccurrences.KeyOf(original));
        EXPECT_NE(nullptr, engine.timelineOccurrences.CompletionProgressOf(original));
        EXPECT_TRUE(voiceOwner.committed);
        EXPECT_TRUE(voice.completionProgressBound);
        EXPECT_EQ(preparedOccurrence, prepared);
        EXPECT_TRUE(engine.playableInstances.Classify(root).live);
        EXPECT_FALSE(executor.ResetForReuse());
        ASSERT_TRUE(executor.RollbackCommitted(engine.playableInstances));
        EXPECT_EQ(2u, engine.actionTimelineVoiceOwnerRollbackAttemptsForTest);
        EXPECT_FALSE(voiceOwner.committed);
        EXPECT_FALSE(voice.completionProgressBound);
        EXPECT_EQ(0u, occurrence.generation);
        EXPECT_EQ(nullptr, engine.timelineOccurrences.KeyOf(original));
        EXPECT_EQ(baseline, engine.timelineOccurrences.OccupiedCount());
        EXPECT_FALSE(engine.playableInstances.Classify(root).live);
        ASSERT_TRUE(executor.RollbackCommitted(engine.playableInstances));
        EXPECT_EQ(2u, engine.actionTimelineVoiceOwnerRollbackAttemptsForTest);
        EXPECT_TRUE(executor.ResetForReuse());
    }
}

TEST(ActionFiringApi, FailedVariableControlRootPreparationCanReuseScratch)
{
    auto storageOwner = std::make_unique<harken::EngineActionPlayStorage>();
    auto scratchOwner =
        std::make_unique<harken::EngineActionPlayScratch>(*storageOwner);
    auto& scratch = *scratchOwner;
    harken::PlayableInstanceTable instances(1);
    harken::PreparedPlayableInstance root{};
    ASSERT_TRUE(instances.PrepareAcquire(
        harken::PlayableKind::Container, 0, &root));
    ASSERT_TRUE(scratch.playableTreeExecutor.AdoptPreparedInstance(
        instances, &root));
    EXPECT_FALSE(scratch.playableTreeExecutor.PrepareInstance(
        instances, harken::PlayableKind::Sound, root.Handle()));
    EXPECT_TRUE(scratch.playableTreeExecutor.Cancel(instances));
    EXPECT_EQ(0u, instances.LiveCount());
    EXPECT_EQ(instances.Capacity(), instances.FreeCount());

    harken::PreparedPlayableInstance retry{};
    ASSERT_TRUE(instances.PrepareAcquire(
        harken::PlayableKind::Container, 0, &retry));
    ASSERT_TRUE(scratch.playableTreeExecutor.AdoptPreparedInstance(
        instances, &retry));
    EXPECT_TRUE(scratch.playableTreeExecutor.Cancel(instances));
    EXPECT_EQ(instances.Capacity(), instances.FreeCount());
}

