    void MakeImmediateQueueNestedContainerPlayAction(bool randomQueue) {
        if (randomQueue) {
            MakeImmediateRandomQueuePlayAction();
        } else {
            MakeImmediateSequenceQueuePlayAction();
        }

        const auto assignNestedContainer = [&](std::uint32_t index,
                                                const auto& property) {
            auto& queueChild = queueChildren[index];
            queueChild.playable.kind = harken::PlayableKindV1::Container;
            queueChild.playable.stableId = property.stableId;
            queueChild.playable.expectedProgramSemanticFingerprint =
                property.programSemanticFingerprint;
            queueChild.playable.contentRevision = property.contentRevision;
            queueChild.playable.routeStableId = property.routeStableId;
            queueChild.playable.compatibilityFingerprint =
                property.compatibilityFingerprint;
            queueChild.timingHint = {};
            auto& occurrence = occurrences[2 + index];
            occurrence.childPlayable = queueChild.playable;
            occurrence.occurrenceSemanticFingerprint =
                harken::ComputePlayableOccurrenceFingerprintV1(occurrence);
        };

        if (randomQueue) {
            innerVariableControlChild = child;
            innerVariableControlChild.playable = queueChildren[1].playable;
            containers[1].children = &innerVariableControlChild;
            occurrences[1].childPlayable =
                innerVariableControlChild.playable;
            occurrences[1].occurrenceSemanticFingerprint =
                harken::ComputePlayableOccurrenceFingerprintV1(occurrences[1]);
            assignNestedContainer(1, properties[3]);
        } else {
            assignNestedContainer(0, properties[2]);
        }
        world.identity.runtimeSemanticFingerprint =
            harken::ComputeCurrentWorldFingerprintV4(world);
    }

