        engine->timelinePool.LiveTransactionCount();
    const std::uint64_t commandHeadBefore =
        engine->commands.PublishedHead();
    const std::uint32_t commandFreeBefore = engine->commands.FreeSlots();
    const auto startRowsBefore = activeStartRows();
    const auto& definition =
        root == ActionScheduleCapacityRoot::Track
            ? image.tracks[0].rootDefinition
            : image.segments[0].rootDefinition;

