void ExpectScheduleCapacityQueueTransitionCompletes() {
    (void)Vn_Term();
    VnConfig config = harkentest::MakeNullConfig(256, 256, 48000);
    config.fxSlotsPerVoice = 1;
    config.delayEffectPoolCapacity = 64;
    config.commandQueueDepth = 1024;
    config.maxControlCommandsPerQuantum = 256;
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);
    std::vector<float> sourceSamples(1024, 0.25f);
    std::vector<float> targetSamples(4096, -0.25f);
    const VnPCMDesc sourcePcm =
        harkentest::MonoDesc(sourceSamples, 48000);
    const VnPCMDesc targetPcm =
        harkentest::MonoDesc(targetSamples, 48000);
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(ActionScheduleCapacityWorld::kSound,
                             &sourcePcm));
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(ActionScheduleCapacityWorld::kTargetSound,
                             &targetPcm));
    ActionScheduleCapacityWorld image(
        64, 64, ActionScheduleCapacityTransitionRoot::Queue,
        engine->registry.Lookup(ActionScheduleCapacityWorld::kSound)
            .contentRevision,
        engine->registry.Lookup(ActionScheduleCapacityWorld::kTargetSound)
            .contentRevision);
    const auto installed =
        harken::InstallContainerWorldV1(*engine, image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok, installed.status);

    const std::uint32_t firingsBefore = engine->actionFirings.LiveCount();
    const std::uint32_t playablesBefore =
        engine->playableInstances.LiveCount();
    const std::uint32_t queuesBefore = engine->queueInstances.LiveCount();
    const std::uint32_t voicesBefore = engine->voices.ActiveCount();
    const std::uint32_t ledgerAvailableBefore =
        engine->ledger.AvailableEntryCount();
    const std::uint32_t decisionsBefore = engine->decisions.LiveCount();
    const std::uint32_t armsBefore = engine->timelineArms.LiveCount();
    const std::uint32_t armGroupsBefore = engine->armGroups.LiveCount();
    const std::uint32_t transitionsBefore =
        engine->transitionInstances.LiveCount();
    const std::uint32_t occurrencesBefore =
        engine->timelineOccurrences.OccupiedCount();
    const std::uint32_t compositesBefore =
        engine->compositeCompletionOwners.OccupiedCount();
    const std::uint32_t transactionsBefore =
        engine->timelinePool.LiveTransactionCount();
    const std::uint32_t delaysBefore = engine->effectBank.DelayInUse();

    VnEmitterHandle emitter = 0;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&emitter));
    harken::QueueCheckpointKey checkpointKey{};
    checkpointKey.world = installed.resultGeneration;
    checkpointKey.containerStableId =
        image.containers[0].containerStableId;
    checkpointKey.programSemanticFingerprint =
        image.containers[0].programSemanticFingerprint;
    checkpointKey.resetEpoch =
        engine->variables.CurrentTransportEpoch();
    checkpointKey.emitterSlot = static_cast<std::uint32_t>(emitter);
    checkpointKey.emitterGeneration =
        static_cast<std::uint32_t>(emitter >> 32);
    harken::QueueCheckpointImage checkpoint{};
    checkpoint.effective.version = 7;
    checkpoint.effective.cursor = 1;
    checkpoint.effective.currentChildOrdinal =
        image.children[1].stableChildOrdinal;
    checkpoint.effective.selectionOrdinal = 3;
    checkpoint.replayCurrent = true;
    ASSERT_TRUE(engine->queueCheckpoints.Store(
        checkpointKey, checkpoint));

    harken::PlayableStartRequest request{};
    request.root.kind = harken::PlayableKindV1::Container;
    request.root.stableId = image.properties[2].stableId;
    request.root.expectedProgramSemanticFingerprint =
        image.properties[2].programSemanticFingerprint;
    request.root.contentRevision = image.properties[2].contentRevision;
    request.root.routeStableId = image.properties[2].routeStableId;
    request.root.compatibilityFingerprint =
        image.properties[2].compatibilityFingerprint;
    request.emitter = emitter;
    const harken::PlayableStartResult started = harken::StartPlayable(
        *engine, engine->variables.CurrentPlayableWorld(), request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == started.instance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    ASSERT_EQ(64u, row->scheduleLeafCount);
    ASSERT_EQ(64u, row->QueuePayload().queueCurrentScheduleLeafCount);
    ASSERT_LT(row->scheduleStorageBase,
              engine->playableStorage.memberCount);
    ASSERT_EQ(ActionScheduleCapacityWorld::kSound,
              engine->ReadPlayableMember(
                  row->scheduleStorageBase).leaf.stableId);
    ASSERT_TRUE(row->queueContinuationPrepared);
    ASSERT_EQ(0u, row->QueueFiling().queueSuccessorScheduleLeafCount);
    ASSERT_TRUE(row->QueuePayload().queueCurrentCompositeOwner.Valid());
    ASSERT_EQ(0u, row->QueueFiling().queueSourceControlArmCount);
    ASSERT_EQ(1u, row->QueueFiling().queueTransitionGroupArmCount);
    ASSERT_TRUE(row->QueueFiling().queueDecision.Valid());
    ASSERT_TRUE(row->QueueFiling().queueTransition.Valid());
    ASSERT_TRUE(row->QueueFiling().queueArmGroup.Valid());
    ASSERT_LE(row->scheduleStorageBase + 64u,
              engine->playableStorage.memberCount);
    ASSERT_FALSE(row->queueArrivalDecision.Valid());
    ASSERT_TRUE(engine->playableInstances.Classify(started.instance).live);
    for (std::uint32_t index = 0; index < 64; ++index) {
        ASSERT_NE(0u,
                  engine->ReadLogicalPlayableMember(
                      row->scheduleStorageBase + index).postSourceTailFrames);
    }
    engine->nullBackend.Pump(1);
    ASSERT_TRUE(engine->timelinePlanner.ReclaimConsumedQuantum());
    ASSERT_LE(engine->timelinePool.PublishCutoffFrame(),
              row->QueuePayload().queueCompletionFrame);
    const harken::DecisionToken initialDecision = row->QueueFiling().queueDecision;
    const harken::TransitionInstanceToken initialTransition =
        row->QueueFiling().queueTransition;
    const harken::ArmGroupToken initialArmGroup = row->QueueFiling().queueArmGroup;

    harken::QueueInstanceSnapshot queueSnapshot{};
    ASSERT_TRUE(engine->queueInstances.Capture(row->queueInstance,
                                               &queueSnapshot));
    ASSERT_EQ(harken::QueueFailurePhase::Healthy,
              queueSnapshot.failurePhase);
    ASSERT_FALSE(queueSnapshot.resetPending);

    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = ActionScheduleCapacityWorld::kAction;
    desc.emitter = emitter;
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    ASSERT_NE(0u, firing);

    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
    EXPECT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
    VnActionStepResult step{};
    step.structSize = sizeof(step);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &step));
    ASSERT_EQ(VN_ACTION_STEP_SUCCEEDED, step.state);
    EXPECT_EQ(0u, step.producedPlayableInstance);
    ASSERT_EQ(64u, row->scheduleLeafCount);
    ASSERT_EQ(64u, row->QueuePayload().queueCurrentScheduleLeafCount);
    ASSERT_LT(row->scheduleStorageBase,
              engine->playableStorage.memberCount);
    EXPECT_EQ(ActionScheduleCapacityWorld::kSound,
              engine->ReadPlayableMember(
                  row->scheduleStorageBase).leaf.stableId);
    for (std::uint32_t index = 0; index < 64; ++index) {
        ASSERT_NE(0u,
                  engine->ReadLogicalPlayableMember(
                      row->scheduleStorageBase + index).postSourceTailFrames);
    }
    ASSERT_TRUE(row->queueContinuationPrepared);
    ASSERT_EQ(64u, row->QueueFiling().queueSuccessorScheduleLeafCount);
    ASSERT_EQ(64u, row->QueueFiling().queueSourceControlArmCount);
    ASSERT_EQ(128u, row->QueueFiling().queueTransitionGroupArmCount);
    ASSERT_TRUE(row->QueueFiling().queueDecision.Valid());
    ASSERT_TRUE(row->QueueFiling().queueTransition.Valid());
    ASSERT_TRUE(row->QueueFiling().queueArmGroup.Valid());
    EXPECT_TRUE(row->QueueFiling().queueDecision.slot != initialDecision.slot ||
                row->QueueFiling().queueDecision.generation != initialDecision.generation);
    EXPECT_TRUE(row->QueueFiling().queueTransition.slot != initialTransition.slot ||
                row->QueueFiling().queueTransition.generation !=
                    initialTransition.generation);
    EXPECT_TRUE(row->QueueFiling().queueArmGroup.slot != initialArmGroup.slot ||
                row->QueueFiling().queueArmGroup.generation != initialArmGroup.generation);
    const harken::DecisionToken replacementDecision = row->QueueFiling().queueDecision;
    const harken::TransitionInstanceToken replacementTransition =
        row->QueueFiling().queueTransition;
    const harken::ArmGroupToken replacementArmGroup = row->QueueFiling().queueArmGroup;

    std::uint32_t firstPage = 0;
    std::uint32_t lastPage = 0;
    ASSERT_TRUE(engine->timelinePool.PageForFrame(
        row->QueuePayload().queueCompletionFrame, &firstPage));
    ASSERT_TRUE(engine->timelinePool.PageForFrame(
        row->QueuePayload().queueCompletionFrame + 65u, &lastPage));
    ASSERT_EQ(firstPage, lastPage);
    const harken::HorizonPageHeader* header =
        engine->timelinePool.Page(firstPage);
    ASSERT_NE(nullptr, header);
    const auto slice = harkentest::QueueContinuationSlice(*engine, replacementDecision, 0);
    harken::Plan03PageGroupView group{};
    ASSERT_TRUE(engine->timelinePool.ResolvePlan03GroupSliceProducer(
        slice, &group));
    ASSERT_EQ(64u, group.sourceControlCount);
    ASSERT_EQ(128u, group.memberCount);
    ASSERT_NE(nullptr, group.members);
    EXPECT_EQ(replacementDecision.slot, group.identity.decision.slot);
    EXPECT_EQ(replacementDecision.generation,
              group.identity.decision.generation);

    harken::ArmGroupSnapshot armGroup{};
    ASSERT_TRUE(engine->armGroups.Capture(replacementArmGroup, &armGroup));
    EXPECT_EQ(replacementDecision.slot, armGroup.parent.slot);
    EXPECT_EQ(replacementDecision.generation,
              armGroup.parent.generation);
    EXPECT_EQ(128u, armGroup.memberCount);
    for (std::uint32_t index = 0; index < group.memberCount; ++index) {
        SCOPED_TRACE(index);
        EXPECT_EQ(row->QueueFiling().queueTransitionGroupArms[index].slot,
                  group.members[index].slot);
        EXPECT_EQ(row->QueueFiling().queueTransitionGroupArms[index].generation,
                  group.members[index].generation);
        harken::TimelineArmObservation observation{};
        ASSERT_TRUE(engine->timelineArms.Observe(
            group.members[index], &observation));
        EXPECT_EQ(replacementDecision.slot,
                  observation.parentGroup.decision.slot);
        EXPECT_EQ(replacementDecision.generation,
                  observation.parentGroup.decision.generation);
        EXPECT_EQ(index, observation.memberIndex);
    }

    for (std::uint32_t index = 0; index < 64; ++index) {
        const auto* member = engine->FindQueueSuccessorMember(*row, index);
        ASSERT_NE(nullptr, member);
        EXPECT_EQ(row->QueuePayload().queueCompletionFrame + index + 1u,
                  member->startFrame);
    }

    harken::TransitionInstanceSnapshot transition{};
    ASSERT_TRUE(engine->transitionInstances.Capture(
        replacementTransition, &transition));
    EXPECT_EQ(row->QueuePayload().queueCompletionFrame, transition.audibleFrame);
    harken::DecisionCommittedSnapshot decision{};
    std::uint32_t decisionCommitIterations = 0;
    for (; decisionCommitIterations < 16 &&
           !row->QueueFiling().queueDecisionCommitted;
         ++decisionCommitIterations) {
        ASSERT_EQ(VN_OK, Vn_Update());
        if (!row->QueueFiling().queueDecisionCommitted) {
            engine->nullBackend.Pump(1);
        }
    }
    ASSERT_TRUE(row->QueueFiling().queueDecisionCommitted);
    EXPECT_EQ(replacementDecision.slot, row->QueueFiling().queueDecision.slot);
    EXPECT_EQ(replacementDecision.generation, row->QueueFiling().queueDecision.generation);
    EXPECT_EQ(replacementTransition.slot, row->QueueFiling().queueTransition.slot);
    EXPECT_EQ(replacementTransition.generation,
              row->QueueFiling().queueTransition.generation);
    EXPECT_EQ(replacementArmGroup.slot, row->QueueFiling().queueArmGroup.slot);
    EXPECT_EQ(replacementArmGroup.generation,
              row->QueueFiling().queueArmGroup.generation);
    ASSERT_TRUE(engine->decisions.CaptureCommitted(
        replacementDecision, &decision));
    EXPECT_EQ(replacementTransition.slot, decision.transitionGate.slot);
    EXPECT_EQ(replacementTransition.generation,
              decision.transitionGate.generation);
    EXPECT_EQ(replacementArmGroup.slot, decision.armGroup.slot);
    EXPECT_EQ(replacementArmGroup.generation,
              decision.armGroup.generation);

    for (std::uint32_t block = 0;
         block < 64 &&
         engine->playableInstances.Classify(started.instance).live;
         ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
    }
    EXPECT_FALSE(engine->playableInstances.Classify(started.instance).live);
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
    ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
    EXPECT_EQ(VN_ACTION_OUTCOME_SUCCEEDED, info.outcome);
    EXPECT_EQ(VN_ACTION_TERMINAL_NATURAL, info.terminalReason);
    EXPECT_EQ(0u, info.livePlayableCount);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &step));
    EXPECT_EQ(VN_ACTION_STEP_SUCCEEDED, step.state);
    EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    EXPECT_EQ(VN_OK, Vn_DestroyEmitter(emitter));
    EXPECT_EQ(firingsBefore, engine->actionFirings.LiveCount());
    EXPECT_EQ(playablesBefore, engine->playableInstances.LiveCount());
    EXPECT_EQ(queuesBefore, engine->queueInstances.LiveCount());
    EXPECT_EQ(voicesBefore, engine->voices.ActiveCount());
    EXPECT_EQ(ledgerAvailableBefore, engine->ledger.AvailableEntryCount());
    EXPECT_EQ(decisionsBefore, engine->decisions.LiveCount());
    EXPECT_EQ(armsBefore, engine->timelineArms.LiveCount());
    EXPECT_EQ(armGroupsBefore, engine->armGroups.LiveCount());
    EXPECT_EQ(transitionsBefore,
              engine->transitionInstances.LiveCount());
    EXPECT_EQ(occurrencesBefore,
              engine->timelineOccurrences.OccupiedCount());
    EXPECT_EQ(compositesBefore,
              engine->compositeCompletionOwners.OccupiedCount());
    EXPECT_EQ(transactionsBefore,
              engine->timelinePool.LiveTransactionCount());
    EXPECT_EQ(delaysBefore, engine->effectBank.DelayInUse());
    EXPECT_FALSE(engine->runtimeRecreateRequired);
}

void ExpectScheduleCapacityVariableControlTransitionCompletes(
    std::uint32_t targetDelayFrames = 0, bool stopBeforeTarget = false) {
    (void)Vn_Term();
    VnConfig config = harkentest::MakeNullConfig(256, 256, 48000);
    config.fxSlotsPerVoice = 1;
    config.delayEffectPoolCapacity = 64;
    config.commandQueueDepth = 1024;
    config.maxControlCommandsPerQuantum = 256;
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);
    std::vector<float> sourceSamples(4096, 0.25f);
    std::vector<float> targetSamples(256, -0.25f);
    const VnPCMDesc sourcePcm =
        harkentest::MonoDesc(sourceSamples, 48000);
    const VnPCMDesc targetPcm =
        harkentest::MonoDesc(targetSamples, 48000);
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(ActionScheduleCapacityWorld::kSound,
                             &sourcePcm));
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(ActionScheduleCapacityWorld::kTargetSound,
                             &targetPcm));
    ActionScheduleCapacityWorld image(
        63, 64, ActionScheduleCapacityTransitionRoot::VariableControl,
        engine->registry.Lookup(ActionScheduleCapacityWorld::kSound)
            .contentRevision,
        engine->registry.Lookup(ActionScheduleCapacityWorld::kTargetSound)
            .contentRevision, targetDelayFrames);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    const std::uint32_t firingsBefore = engine->actionFirings.LiveCount();
    const std::uint32_t playablesBefore =
        engine->playableInstances.LiveCount();
    const std::uint32_t variableControlsBefore =
        engine->variableControlInstances.LiveCount();
    const std::uint32_t voicesBefore = engine->voices.ActiveCount();
    const std::uint32_t ledgerAvailableBefore =
        engine->ledger.AvailableEntryCount();
    const std::uint32_t decisionsBefore = engine->decisions.LiveCount();
    const std::uint32_t armsBefore = engine->timelineArms.LiveCount();
    const std::uint32_t armGroupsBefore = engine->armGroups.LiveCount();
    const std::uint32_t transitionsBefore =
        engine->transitionInstances.LiveCount();
    const std::uint32_t occurrencesBefore =
        engine->timelineOccurrences.OccupiedCount();
    const std::uint32_t compositesBefore =
        engine->compositeCompletionOwners.OccupiedCount();
    const std::uint32_t transactionsBefore =
        engine->timelinePool.LiveTransactionCount();
    const std::uint32_t delaysBefore = engine->effectBank.DelayInUse();

    FrontierTrace capacityTrace;
    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = ActionScheduleCapacityWorld::kAction;
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    ASSERT_NE(0u, firing);

    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
    EXPECT_EQ(VN_ACTION_FIRING_ACTIVE, info.state);
    EXPECT_EQ(1u, info.livePlayableCount);
    VnActionStepResult play{};
    play.structSize = sizeof(play);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
    ASSERT_EQ(VN_ACTION_STEP_ACTIVE, play.state);
    ASSERT_NE(0u, play.producedPlayableInstance);

    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == play.producedPlayableInstance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    ASSERT_EQ(63u, row->variableControlDiscreteMemberCount);
    ASSERT_EQ(63u, row->scheduleLeafCount);
    ASSERT_LT(row->scheduleStorageBase,
              engine->playableStorage.memberCount);
    EXPECT_EQ(ActionScheduleCapacityWorld::kSound,
              engine->ReadPlayableMember(
                  row->scheduleStorageBase).leaf.stableId);

    for (std::uint32_t block = 0;
         block < 64 && !row->variableControlDiscreteRetargetPrepared;
         ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        if (!row->variableControlDiscreteRetargetPrepared) {
            engine->nullBackend.Pump(1);
            capacityTrace.Capture(*engine);
        }
    }
    ASSERT_TRUE(row->variableControlDiscreteRetargetPrepared);
    ASSERT_EQ(63u,
              row->VariablePayload().variableControlDiscreteRetargetSourceMemberCount);
    ASSERT_EQ(64u,
              row->VariablePayload().variableControlDiscreteRetargetTargetMemberCount);
    ASSERT_EQ(127u,
              row->VariablePayload().variableControlDiscreteRetargetGroupMemberCount);
    ASSERT_TRUE(row->VariablePayload().variableControlDiscreteRetargetDecision.Valid());
    ASSERT_TRUE(row->VariablePayload().variableControlDiscreteRetargetTransition.Valid());
    ASSERT_TRUE(row->VariablePayload().variableControlDiscreteRetargetArmGroup.Valid());
    const harken::DecisionToken retargetDecision =
        row->VariablePayload().variableControlDiscreteRetargetDecision;
    const harken::TransitionInstanceToken retargetTransition =
        row->VariablePayload().variableControlDiscreteRetargetTransition;
    const harken::ArmGroupToken retargetArmGroup =
        row->VariablePayload().variableControlDiscreteRetargetArmGroup;
    const std::uint64_t retargetFrame =
        row->VariablePayload().variableControlDiscreteRetargetFrame;

    harken::Plan03PageGroupView group{};
    ASSERT_TRUE(engine->timelinePool.ResolvePlan03GroupSliceProducer(
        row->VariableControlDiscreteRetargetSlice(), &group));
    ASSERT_EQ(63u, group.sourceControlCount);
    ASSERT_EQ(127u, group.memberCount);
    ASSERT_NE(nullptr, group.members);
    EXPECT_EQ(retargetDecision.slot,
              group.identity.decision.slot);
    EXPECT_EQ(retargetDecision.generation,
              group.identity.decision.generation);

    harken::TransitionInstanceSnapshot transition{};
    ASSERT_TRUE(engine->transitionInstances.Capture(
        retargetTransition, &transition));
    EXPECT_EQ(retargetFrame, transition.audibleFrame);
    harken::ArmGroupSnapshot armGroup{};
    ASSERT_TRUE(engine->armGroups.Capture(retargetArmGroup, &armGroup));
    EXPECT_EQ(retargetDecision.slot, armGroup.parent.slot);
    EXPECT_EQ(retargetDecision.generation, armGroup.parent.generation);
    EXPECT_EQ(127u, armGroup.memberCount);

    for (std::uint32_t index = 0; index < group.memberCount; ++index) {
        const harken::TimelineArmToken expected =
            row->DiscreteRetargetStorage().groupArms[index];
        EXPECT_EQ(expected.slot, group.members[index].slot);
        EXPECT_EQ(expected.generation, group.members[index].generation);
        harken::TimelineArmObservation observation{};
        ASSERT_TRUE(engine->timelineArms.Observe(group.members[index],
                                                 &observation));
        EXPECT_EQ(retargetDecision.slot,
                  observation.parentGroup.decision.slot);
        EXPECT_EQ(retargetDecision.generation,
                  observation.parentGroup.decision.generation);
        EXPECT_EQ(index, observation.memberIndex);
    }

    const std::size_t targetBase = row->scheduleStorageBase +
        row->variableControlDiscreteTransitionOffset;
    for (std::uint32_t index = 0; index < 64; ++index) {
        EXPECT_EQ(retargetFrame + targetDelayFrames + index + 1u,
                  engine->ReadPlayableMember(
                      targetBase + index).startFrame);
    }
    EXPECT_EQ(128u, engine->timelinePool.IngressHighWater());
    EXPECT_EQ(targetDelayFrames == 0 ? 66u : 64u, engine->timelinePool.FrameBatchHighWater());

    std::uint32_t decisionCommitIterations = 0;
    for (; decisionCommitIterations < 16 &&
           !row->variableControlDiscreteRetargetDecisionCommitted;
         ++decisionCommitIterations) {
        ASSERT_EQ(VN_OK, Vn_Update());
        if (!row->variableControlDiscreteRetargetDecisionCommitted) {
            engine->nullBackend.Pump(1);
            capacityTrace.Capture(*engine);
        }
    }
    ASSERT_TRUE(row->variableControlDiscreteRetargetDecisionCommitted);
    EXPECT_EQ(retargetDecision.slot,
              row->VariablePayload().variableControlDiscreteRetargetDecision.slot);
    EXPECT_EQ(retargetDecision.generation,
              row->VariablePayload().variableControlDiscreteRetargetDecision.generation);
    EXPECT_EQ(retargetTransition.slot,
              row->VariablePayload().variableControlDiscreteRetargetTransition.slot);
    EXPECT_EQ(retargetTransition.generation,
              row->VariablePayload().variableControlDiscreteRetargetTransition.generation);
    EXPECT_EQ(retargetArmGroup.slot,
              row->VariablePayload().variableControlDiscreteRetargetArmGroup.slot);
    EXPECT_EQ(retargetArmGroup.generation,
              row->VariablePayload().variableControlDiscreteRetargetArmGroup.generation);
    harken::DecisionCommittedSnapshot decision{};
    ASSERT_TRUE(engine->decisions.CaptureCommitted(
        retargetDecision, &decision));
    EXPECT_EQ(retargetTransition.slot, decision.transitionGate.slot);
    EXPECT_EQ(retargetTransition.generation,
              decision.transitionGate.generation);
    EXPECT_EQ(retargetArmGroup.slot, decision.armGroup.slot);
    EXPECT_EQ(retargetArmGroup.generation, decision.armGroup.generation);

    if (stopBeforeTarget) {
        ASSERT_GE(targetDelayFrames, engine->config.blockFrames);
        while (engine->mixer.BlocksRendered() * engine->config.blockFrames <= retargetFrame) {
            ASSERT_EQ(VN_OK, Vn_Update());
            engine->nullBackend.Pump(1);
            capacityTrace.Capture(*engine);
        }
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_TRUE(row->variableControlDiscreteRetargetApplied);
        ASSERT_EQ(harken::AudioSliceState::SliceApplied, group.lease->Capture().state);
        ASSERT_EQ(VN_OK, Vn_StopActionFiring(firing, 0));
    }
    for (std::uint32_t block = 0; block < 96; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        capacityTrace.Capture(*engine);
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
        if (info.state == VN_ACTION_FIRING_TERMINAL_RETAINED) {
            break;
        }
    }
    EXPECT_EQ(stopBeforeTarget ? 63u : 127u, capacityTrace.heard.size());
    std::uint32_t targetStarts = 0;
    for (const auto& heard : capacityTrace.heard) {
        EXPECT_EQ(heard.expectedStart, heard.start);
        if (heard.subject == ActionScheduleCapacityWorld::kTargetSound) {
            ++targetStarts;
            EXPECT_NE(0u, heard.complete);
        }
    }
    EXPECT_EQ(stopBeforeTarget ? 0u : 64u, targetStarts);
    if (!stopBeforeTarget) {
        ASSERT_NO_FATAL_FAILURE(ExpectVariableControlNaturalCompletion(
            *engine, firing, &info));
    } else {
        ASSERT_FALSE(row->frontierLifetimePin.Valid());
        ASSERT_EQ(VN_OK, Vn_Update());
    }
    ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
    EXPECT_EQ(stopBeforeTarget ? VN_ACTION_OUTCOME_CANCELLED : VN_ACTION_OUTCOME_SUCCEEDED, info.outcome);
    EXPECT_EQ(stopBeforeTarget ? VN_ACTION_TERMINAL_STOP_REQUESTED : VN_ACTION_TERMINAL_NATURAL, info.terminalReason);
    EXPECT_EQ(0u, info.livePlayableCount);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
    EXPECT_EQ(stopBeforeTarget ? VN_ACTION_STEP_CANCELLED : VN_ACTION_STEP_SUCCEEDED, play.state);
    for (std::uint32_t block = 0;
         block < 16 &&
         engine->timelinePool.LiveTransactionCount() != transactionsBefore;
         ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
    }
    EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    EXPECT_EQ(firingsBefore, engine->actionFirings.LiveCount());
    EXPECT_EQ(playablesBefore, engine->playableInstances.LiveCount());
    EXPECT_EQ(variableControlsBefore,
              engine->variableControlInstances.LiveCount());
    EXPECT_EQ(voicesBefore, engine->voices.ActiveCount());
    EXPECT_EQ(ledgerAvailableBefore, engine->ledger.AvailableEntryCount());
    EXPECT_EQ(decisionsBefore, engine->decisions.LiveCount());
    EXPECT_EQ(armsBefore, engine->timelineArms.LiveCount());
    EXPECT_EQ(armGroupsBefore, engine->armGroups.LiveCount());
    EXPECT_EQ(transitionsBefore,
              engine->transitionInstances.LiveCount());
    EXPECT_EQ(occurrencesBefore,
              engine->timelineOccurrences.OccupiedCount());
    EXPECT_EQ(compositesBefore,
              engine->compositeCompletionOwners.OccupiedCount());
    EXPECT_EQ(transactionsBefore,
              engine->timelinePool.LiveTransactionCount());
    EXPECT_EQ(delaysBefore, engine->effectBank.DelayInUse());
    EXPECT_FALSE(engine->runtimeRecreateRequired);
}

struct ActionPreparationOwnerSnapshot {
    std::uint64_t logicSequence = 0;
    std::uint64_t commandHead = 0;
    std::uint64_t renderedBlocks = 0;
    std::uint32_t commandFree = 0;
    std::uint32_t firingLive = 0;
    std::uint32_t firingFree = 0;
    std::uint32_t firingHighWater = 0;
    std::uint32_t playableLive = 0;
    std::uint32_t playableFree = 0;
    std::uint32_t playableHighWater = 0;
    std::uint32_t variableControlLive = 0;
    std::uint32_t variableControlHighWater = 0;
    std::uint32_t queueLive = 0;
    std::uint32_t queueCheckpointLive = 0;
    std::uint32_t decisionLive = 0;
    std::uint32_t transitionLive = 0;
    std::uint32_t transitionFree = 0;
    std::uint32_t armGroupLive = 0;
    std::uint32_t armGroupFree = 0;
    std::uint32_t voiceActive = 0;
    std::uint32_t voiceHighWater = 0;
    std::uint32_t ledgerAvailable = 0;
    std::uint32_t armLive = 0;
    std::uint32_t armFree = 0;
    std::uint32_t occurrenceOccupied = 0;
    std::uint32_t occurrenceFree = 0;
    std::uint32_t occurrenceHighWater = 0;
    std::uint32_t compositeOccupied = 0;
    std::uint32_t compositeFree = 0;
    std::uint32_t compositeHighWater = 0;
    std::uint32_t delayInUse = 0;
    std::uint32_t delayHighWater = 0;
    std::uint32_t transactionLive = 0;
    std::uint32_t transactionHighWater = 0;
    std::uint32_t frameBatchHighWater = 0;
    std::uint32_t eventHighWater = 0;
    std::uint32_t ingress = 0;
    std::uint32_t ingressHighWater = 0;
    std::size_t occupiedStartRows = 0;
    std::size_t occupiedQueueProgramBanks = 0;
};

ActionPreparationOwnerSnapshot CaptureActionPreparationOwners(
    const harken::Engine& engine) {
    ActionPreparationOwnerSnapshot snapshot{};
    snapshot.logicSequence = engine.logicCommits.IssuedCount();
    snapshot.commandHead = engine.commands.PublishedHead();
    snapshot.renderedBlocks = engine.mixer.BlocksRendered();
    snapshot.commandFree = engine.commands.FreeSlots();
    snapshot.firingLive = engine.actionFirings.LiveCount();
    snapshot.firingFree = engine.actionFirings.FreeCount();
    snapshot.firingHighWater = engine.actionFirings.HighWater();
    snapshot.playableLive = engine.playableInstances.LiveCount();
    snapshot.playableFree = engine.playableInstances.FreeCount();
    snapshot.playableHighWater = engine.playableInstances.HighWater();
    snapshot.variableControlLive =
        engine.variableControlInstances.LiveCount();
    snapshot.variableControlHighWater =
        engine.variableControlInstances.HighWater();
    snapshot.queueLive = engine.queueInstances.LiveCount();
    snapshot.queueCheckpointLive = engine.queueCheckpoints.LiveCount();
    snapshot.decisionLive = engine.decisions.LiveCount();
    snapshot.transitionLive = engine.transitionInstances.LiveCount();
    snapshot.transitionFree = engine.transitionInstances.FreeCount();
    snapshot.armGroupLive = engine.armGroups.LiveCount();
    snapshot.armGroupFree = engine.armGroups.FreeCount();
    snapshot.voiceActive = engine.voices.ActiveCount();
    snapshot.voiceHighWater = engine.voices.HighWaterVoices();
    snapshot.ledgerAvailable = engine.ledger.AvailableEntryCount();
    snapshot.armLive = engine.timelineArms.LiveCount();
    snapshot.armFree = engine.timelineArms.FreeCount();
    snapshot.occurrenceOccupied = engine.timelineOccurrences.OccupiedCount();
    snapshot.occurrenceFree = engine.timelineOccurrences.FreeCount();
    snapshot.occurrenceHighWater = engine.timelineOccurrences.HighWater();
    snapshot.compositeOccupied =
        engine.compositeCompletionOwners.OccupiedCount();
    snapshot.compositeFree = engine.compositeCompletionOwners.FreeCount();
    snapshot.compositeHighWater =
        engine.compositeCompletionOwners.HighWater();
    snapshot.delayInUse = engine.effectBank.DelayInUse();
    snapshot.delayHighWater = engine.effectBank.DelayHighWater();
    snapshot.transactionLive = engine.timelinePool.LiveTransactionCount();
    snapshot.transactionHighWater =
        engine.timelinePool.TransactionHighWater();
    snapshot.frameBatchHighWater = engine.timelinePool.FrameBatchHighWater();
    snapshot.eventHighWater = engine.timelinePool.EventHighWater();
    snapshot.ingress = engine.timelinePool.IngressThisQuantum();
    snapshot.ingressHighWater = engine.timelinePool.IngressHighWater();
    snapshot.occupiedStartRows = std::count_if(
        engine.playableServices.begin(), engine.playableServices.end(),
        [](const harken::EnginePlayableServiceRow& row) {
            return row.actionPrepared ||
                   row.phase != harken::EnginePlayableStartPhase::Free;
        });
    snapshot.occupiedQueueProgramBanks = std::count_if(engine.queueProgramBanks.begin(),
        engine.queueProgramBanks.end(), [](const auto& bank) { return bank.occupied; });
    return snapshot;
}

std::array<std::uint64_t, 19> CaptureActionReclaimableOwners(
    const harken::Engine& engine) {
    const auto owners = CaptureActionPreparationOwners(engine);
    return {
        owners.firingLive,
        owners.playableLive,
        owners.variableControlLive,
        owners.queueLive,
        owners.queueCheckpointLive,
        owners.decisionLive,
        owners.transitionLive,
        owners.armGroupLive,
        owners.voiceActive,
        owners.ledgerAvailable,
        owners.armLive,
        owners.occurrenceOccupied,
        owners.compositeOccupied,
        owners.delayInUse,
        owners.transactionLive,
        static_cast<std::uint64_t>(engine.containerPlayback.LiveCount()),
        owners.occupiedStartRows,
        static_cast<std::uint64_t>(engine.selectionMemory.RowCount()),
        static_cast<std::uint64_t>(
            engine.selectionMemory.FreeDeltaCount()),
    };
}


void ExpectAcceptedActionVoiceRetired(
    harken::Engine& engine, harken::TimelineArmToken originalArm,
    VnVoiceHandle originalRender, harken::VoiceReleaseObserver originalRelease) {
    const auto* source = engine.originalSourceSubmissions.Find(originalArm);
    ASSERT_NE(nullptr, source);
    EXPECT_EQ(harken::OriginalSourceSubmissionRegistry::Phase::Disposed, source->State());
    EXPECT_TRUE(engine.voices.ReleaseObserved(originalRelease));
    EXPECT_EQ(nullptr, engine.voices.Resolve(originalRender));
    harken::TimelineArmObservation oldArm{};
    EXPECT_FALSE(engine.timelineArms.Observe(originalArm, &oldArm));
    harken::EngineTimelineVoiceInstallIdentity oldInstallation{};
    EXPECT_FALSE(engine.CaptureTimelineVoiceInstallIdentity(originalRender, &oldInstallation));
}

