TEST(ActionFiringApi, DelayedStopJustBeforeWindowEndDoesNotStopImmediately) {
    (void)Vn_Term();
    harkentest::EngineSession session(
        harkentest::MakeNullConfig(2, 256, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    const auto stopFrame = engine->timelinePool.WindowEndFrame() - 1u;
    std::vector<float> samples(stopFrame + 4096u, 0.25f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision);
    image.MakeDelayedSeparateSoundStopAction(
        DelayNanosecondsForTargetFrame(*engine, stopFrame));
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    VnPostActionDesc playDesc = ValidPostDesc();
    playDesc.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle playFiring = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&playDesc, &playFiring));
    ASSERT_EQ(1u, engine->playableInstances.LiveCount());
    const auto playable = engine->playableServices[0].rootInstance;
    const auto renderHandle = engine->playableServices[0].renderHandle;
    const auto releaseObserver = engine->playableServices[0].releaseObserver;
    const auto voiceOwner = engine->ledger.OwnerForRender(renderHandle);
    ASSERT_TRUE(voiceOwner.live);
    const auto lifecycleBefore =
        engine->playableServices[0].controlLifecycle;

    VnPostActionDesc stopDesc = ValidPostDesc();
    stopDesc.actionId = image.actions[8].actionStableId;
    VnActionFiringHandle stopFiring = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&stopDesc, &stopFiring));
    const auto stopRequest = engine->monitorRequests.LastSequence();
    harken::MonitorControlCause capturedCause{};
    EXPECT_FALSE(engine->playableInstances.CaptureControlCause(playable, &capturedCause));
    bool observedAppliedCause = false;
    bool observedVoiceCause = false;
    bool foundPreparedCause = false;
    for (const auto& operation : engine->authoredStopRoots) {
        if (!operation.operation || operation.operation->Identity().actionFiring != stopFiring) continue;
        foundPreparedCause = true;
        EXPECT_EQ(stopRequest, operation.controlCause.request.key.sequence);
        EXPECT_EQ(stopFiring, operation.controlCause.actionFiring);
        EXPECT_EQ(0u, operation.controlCause.executionOrdinal);
        EXPECT_FALSE(operation.applied);
    }
    EXPECT_TRUE(foundPreparedCause);
    EXPECT_EQ(0u, engine->actionDeferredRecords.LiveCount());
    EXPECT_EQ(1u, engine->playableInstances.LiveCount());
    EXPECT_EQ(playable, engine->playableServices[0].rootInstance);
    EXPECT_EQ(lifecycleBefore, engine->playableServices[0].controlLifecycle);
    EXPECT_NE(harken::PlayableControlLifecycle::Cancelling,
              engine->playableServices[0].controlLifecycle);
    VnActionStepResult step{};
    step.structSize = sizeof(step);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(stopFiring, 0, &step));
    EXPECT_EQ(VN_ACTION_STEP_ACTIVE, step.state);
    EXPECT_EQ(1u, step.capturedPlayableCount);
    EXPECT_EQ(VN_IN_USE, Vn_ReleaseActionFiring(stopFiring));
    EXPECT_EQ(VN_IN_USE, Vn_ReleaseActionFiring(playFiring));
    engine->nullBackend.Pump(1);
    ASSERT_EQ(VN_OK, Vn_Update());
    const auto startFrame = engine->playableServices[0].startFrame;
    bool audibleBeforeStop = false;
    bool checkedAfterStop = false;
    const auto blockFrames = engine->nullBackend.BlockFrames();
    while (engine->mixer.BlocksRendered() * blockFrames <
           stopFrame + 4u * blockFrames) {
        ASSERT_EQ(VN_OK, Vn_Update());
        if (engine->playableInstances.CaptureControlCause(playable, &capturedCause)) {
            observedAppliedCause = true;
            EXPECT_GT(engine->mixer.BlocksRendered() * blockFrames, stopFrame);
            EXPECT_EQ(stopRequest, capturedCause.request.key.sequence);
            EXPECT_EQ(stopFiring, capturedCause.actionFiring);
        }
        const auto before = engine->mixer.BlocksRendered();
        engine->nullBackend.Pump(1);
        ASSERT_GT(engine->mixer.BlocksRendered(), before);
        const auto endFrame = engine->mixer.BlocksRendered() * blockFrames;
        const auto* render = engine->voices.Resolve(renderHandle);
        harken::VoiceLedger::MonitorIdentity voiceIdentity{};
        if (engine->ledger.CaptureMonitorIdentity(voiceOwner.ledgerSlot, &voiceIdentity) &&
            voiceIdentity.controlCause.request.key.Valid()) {
            observedVoiceCause = true;
            EXPECT_GT(endFrame, stopFrame);
            EXPECT_EQ(renderHandle, voiceIdentity.renderHandle);
            EXPECT_EQ(stopRequest, voiceIdentity.controlCause.request.key.sequence);
            EXPECT_EQ(stopFiring, voiceIdentity.controlCause.actionFiring);
            EXPECT_FALSE(voiceIdentity.controlObservationIncomplete);
        }
        float peak = 0.0f;
        for (std::uint32_t index = 0;
             index < blockFrames * engine->nullBackend.Channels(); ++index) {
            peak = std::max(peak, std::abs(engine->nullBackend.LastBlock()[index]));
        }
        if (endFrame <= stopFrame && endFrame > startFrame) {
            EXPECT_NE(nullptr, render) << "frame=" << endFrame;
            if (render != nullptr) EXPECT_FALSE(render->fading);
            EXPECT_GT(peak, 0.001f) << "frame=" << endFrame;
            audibleBeforeStop = audibleBeforeStop ||
                (render != nullptr && !render->fading && peak > 0.001f);
        }
        if (endFrame > stopFrame + blockFrames) {
            EXPECT_EQ(nullptr, render) << "frame=" << endFrame;
            EXPECT_TRUE(engine->voices.ReleaseObserved(releaseObserver));
            EXPECT_EQ(0u, engine->voices.ActiveCount());
            const auto channels = engine->nullBackend.Channels();
            for (std::uint32_t frame = 0; frame < blockFrames; ++frame) {
                const auto absoluteFrame = endFrame - blockFrames + frame;
                if (absoluteFrame < stopFrame + 240u) continue;
                for (std::uint32_t channel = 0; channel < channels; ++channel) {
                    EXPECT_LE(std::abs(engine->nullBackend.LastBlock()[frame * channels + channel]),
                              harkentest::kSilenceFloor) << "frame=" << absoluteFrame;
                }
            }
            checkedAfterStop = true;
        }
    }
    EXPECT_TRUE(audibleBeforeStop);
    EXPECT_TRUE(checkedAfterStop);
    EXPECT_TRUE(observedAppliedCause);
    EXPECT_TRUE(observedVoiceCause);
    ASSERT_EQ(VN_OK, Vn_Update());
    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    for (const auto firing : {playFiring, stopFiring}) {
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
        EXPECT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
        EXPECT_EQ(VN_ACTION_OUTCOME_SUCCEEDED, info.outcome);
        EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    }
    EXPECT_EQ(0u, engine->playableInstances.LiveCount());
    EXPECT_EQ(0u, engine->timelineArms.LiveCount());
    EXPECT_EQ(0u, engine->timelinePool.LiveTransactionCount());
}

TEST(ActionFiringApi, DelayedStopPublicationWaitsForTransientArmReservation) {
    (void)Vn_Term();
    harkentest::EngineSession session(harkentest::MakeNullConfig(8, 256, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    std::vector<float> samples(8192, 0.25f);
    const auto pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
    CanonicalActionWorld image(engine->registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision);
    image.MakeDelayedSeparateSoundStopAction(DelayNanosecondsForTargetFrame(*engine, 4096));
    ASSERT_EQ(harken::WorldInstallStatus::Ok, harken::InstallContainerWorldV1(*engine, image.world).status);
    auto play = ValidPostDesc();
    play.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle playFiring = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&play, &playFiring));
    auto stop = ValidPostDesc();
    stop.actionId = image.actions[8].actionStableId;
    VnActionFiringHandle stopFiring = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&stop, &stopFiring));
    const auto resource = std::find_if(engine->authoredStopResources.begin(),
        engine->authoredStopResources.end(), [](const auto& candidate) {
            return candidate.committed && candidate.arm.Valid();
        });
    ASSERT_NE(engine->authoredStopResources.end(), resource);
    auto* arm = engine->timelineArms.Resolve(resource->arm);
    ASSERT_NE(nullptr, arm);
    engine->nullBackend.Pump(1);
    harken::ArmState state{};
    ASSERT_TRUE(engine->timelineArms.State(resource->arm, &state));
    ASSERT_EQ(harken::ArmState::Armed, state);
    ASSERT_FALSE(arm->reservation.test_and_set());
    ASSERT_EQ(VN_OK, Vn_Update());
    EXPECT_FALSE(engine->runtimeRecreateRequired);
    ASSERT_TRUE(engine->timelineArms.State(resource->arm, &state));
    EXPECT_EQ(harken::ArmState::Armed, state);
    arm->reservation.clear();
    ASSERT_EQ(VN_OK, Vn_Update());
    EXPECT_FALSE(engine->runtimeRecreateRequired);
    ASSERT_TRUE(engine->timelineArms.State(resource->arm, &state));
    EXPECT_EQ(harken::ArmState::Published, state);
}

TEST(ActionFiringApi, PositiveDelayedImmediateStopCapturesTrackAndSegmentRoots) {
    for (const auto kind : {harken::ActionTargetKindV1::Track,
                            harken::ActionTargetKindV1::Segment}) {
        SCOPED_TRACE(static_cast<std::uint32_t>(kind));
        (void)Vn_Term();
        harkentest::EngineSession session(
            harkentest::MakeNullConfig(8, 256, 48000));
        ASSERT_EQ(VN_OK, session.InitResult());
        harken::Engine* engine = session.Engine();
        const std::uint64_t stopFrame =
            engine->timelinePool.WindowEndFrame() +
            engine->config.blockFrames;
        std::vector<float> first(stopFrame + 4096u, 0.25f);
        std::vector<float> second(stopFrame + 4096u, -0.25f);
        const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
        const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
        ASSERT_EQ(VN_OK, Vn_RegisterPCM(
                             CanonicalActionWorld::kFirstSound, &firstPcm));
        ASSERT_EQ(VN_OK, Vn_RegisterPCM(
                             CanonicalActionWorld::kSecondSound, &secondPcm));
        CanonicalActionWorld image(
            engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
                .contentRevision,
            engine->registry.Lookup(CanonicalActionWorld::kSecondSound)
                .contentRevision);
        image.MakeImmediatePlayThenStopAction(kind);
        SetAbsoluteTime(&image.steps[12].delay,
                        DelayNanosecondsForTargetFrame(*engine, stopFrame));
        image.actions[9].directFeatureMask = 1u;
        image.actions[9].transitiveFeatureMask = 1u;
        image.actions[9].programSemanticFingerprint =
            harken::ComputeActionProgramFingerprintV1(image.actions[9]);
        image.world.identity.runtimeSemanticFingerprint =
            harken::ComputeCurrentWorldFingerprintV4(image.world);
        ASSERT_EQ(harken::WorldInstallStatus::Ok,
                  harken::InstallContainerWorldV1(*engine, image.world).status);

        const auto definitionKind =
            kind == harken::ActionTargetKindV1::Track
                ? harken::PlayableKindV1::Track
                : harken::PlayableKindV1::Segment;
        const auto direct = harken::StartCurrentPlayableByIdentity(
            definitionKind, image.steps[11].target.stableId, 0);
        ASSERT_EQ(harken::PlayableStartStatus::Accepted, direct.status);
        ASSERT_NE(0u, direct.instance);

        VnPostActionDesc desc = ValidPostDesc();
        desc.actionId = image.actions[9].actionStableId;
        VnActionFiringHandle firing = 0;
        ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
        VnActionStepResult play{};
        play.structSize = sizeof(play);
        ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
        ASSERT_NE(0u, play.producedPlayableInstance);
        const auto captured = engine->playableInstances.Classify(
            play.producedPlayableInstance);
        ASSERT_TRUE(captured.live);
        VnActionStepResult stop{};
        stop.structSize = sizeof(stop);
        ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 1, &stop));
        EXPECT_EQ(VN_ACTION_STEP_AWAITING_MATERIALIZATION, stop.state);
        EXPECT_EQ(1u, stop.capturedPlayableCount);
        EXPECT_EQ(1u, stop.remainingPlayableCount);
        ASSERT_EQ(1u, engine->actionDeferredRecords.LiveCount());
        harken::ActionDeferredRecordToken token{};
        harken::ActionDeferredRecord record{};
        harken::ActionDeferredRecordState state =
            harken::ActionDeferredRecordState::Free;
        ASSERT_TRUE(engine->actionDeferredRecords.CaptureAt(
            0, &token, &record, &state));
        EXPECT_EQ(stopFrame, record.intendedBoundaryFrame);
        EXPECT_EQ(play.producedPlayableInstance, record.rootPlayable);
        EXPECT_EQ(captured.scheduleEpoch, record.rootScheduleEpoch);
        EXPECT_TRUE(engine->playableInstances.Classify(direct.instance).live);
        EXPECT_FALSE(engine->playableInstances.HasCancellationClaim(
            direct.instance));
        EXPECT_EQ(stopFrame, DrainRematerializedStopSilence(engine));
        ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 1, &stop));
        EXPECT_EQ(VN_ACTION_STEP_ACTIVE, stop.state);
        EXPECT_TRUE(engine->playableInstances.Classify(direct.instance).live);
        EXPECT_FALSE(engine->playableInstances.HasCancellationClaim(
            direct.instance));
        EXPECT_EQ(VN_IN_USE, Vn_ReleaseActionFiring(firing));
    }
}

static void CheckDistantStopContainerSuccessors(std::uint32_t sourceFrames, bool crossesStop) {
    (void)Vn_Term();
    harkentest::EngineSession session(harkentest::MakeNullConfig(8, 256, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    const auto stopFrame = engine->timelinePool.WindowEndFrame() - 1u;
    std::vector<float> samples(sourceFrames, 0.25f);
    const auto pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
    CanonicalActionWorld image(engine->registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision);
    image.MakeDelayedSeparateSoundStopAction(DelayNanosecondsForTargetFrame(*engine, stopFrame));
    image.MakeImmediateSequenceContainerPlayAction();
    image.properties[2].payload.presentMask |= UINT64_C(1) << 3;
    image.properties[2].payload.values[3].bits = 12;
    image.properties[2].programSemanticFingerprint =
        harken::ComputePlayablePropertyFingerprintV1(image.properties[2]);
    image.containers[0].programSemanticFingerprint = image.properties[2].programSemanticFingerprint;
    image.occurrences[0].parentProgramSemanticFingerprint = image.properties[2].programSemanticFingerprint;
    image.occurrences[0].occurrenceSemanticFingerprint =
        harken::ComputePlayableOccurrenceFingerprintV1(image.occurrences[0]);
    for (auto& step : image.steps) {
        if (step.target.kind == harken::ActionTargetKindV1::Container &&
            step.target.stableId == image.properties[2].stableId) {
            step.target.expectedProgramSemanticFingerprint = image.properties[2].programSemanticFingerprint;
        }
    }
    image.steps[10].target = image.steps[11].target;
    for (auto& action : image.actions)
        action.programSemanticFingerprint = harken::ComputeActionProgramFingerprintV1(action);
    image.world.identity.runtimeSemanticFingerprint = harken::ComputeCurrentWorldFingerprintV4(image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok, harken::InstallContainerWorldV1(*engine, image.world).status);
    auto play = ValidPostDesc();
    play.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle playFiring = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&play, &playFiring));
    const auto root = engine->playableServices[0].rootInstance;
    const auto initialRender = engine->playableServices[0].renderHandle;
    auto stop = ValidPostDesc();
    stop.actionId = image.actions[8].actionStableId;
    VnActionFiringHandle stopFiring = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&stop, &stopFiring));
    ASSERT_EQ(VN_OK, Vn_Update());
    engine->nullBackend.Pump(1);
    ASSERT_EQ(VN_OK, Vn_Update());
    EXPECT_LT(engine->timelinePool.PublishCutoffFrame(), stopFrame / 2u);
    bool inherited = false;
    bool successorAudible = false;
    VnVoiceHandle successor = 0;
    harken::VoiceReleaseObserver successorRelease{};
    std::uint64_t successorOnset = 0;
    const auto blockFrames = engine->config.blockFrames;
    while (engine->mixer.BlocksRendered() * blockFrames < stopFrame / blockFrames * blockFrames) {
        ASSERT_EQ(VN_OK, Vn_Update());
        for (const auto& resource : engine->authoredStopResources) {
            harken::EngineTimelineVoiceInstallIdentity installation{};
            if (!resource.committed || resource.retiring ||
                resource.installation.renderHandle == 0 ||
                resource.installation.renderHandle == initialRender ||
                !engine->CaptureTimelineVoiceInstallIdentity(resource.installation.renderHandle, &installation) ||
                installation.rootInstance != root || installation.onsetFrame < successorOnset) continue;
            inherited = true;
            if (successor != resource.installation.renderHandle) successorAudible = false;
            successor = resource.installation.renderHandle;
            successorRelease = resource.installation.releaseObserver;
            successorOnset = installation.onsetFrame;
            EXPECT_GT(installation.onsetFrame, 0u);
            EXPECT_LT(installation.onsetFrame, stopFrame);
            ASSERT_LT(resource.operationSlot, engine->authoredStopRoots.size());
            EXPECT_EQ(stopFrame, engine->authoredStopRoots[resource.operationSlot].operation->Identity().stopFrame);
        }
        const auto before = engine->mixer.BlocksRendered();
        engine->nullBackend.Pump(1);
        ASSERT_GT(engine->mixer.BlocksRendered(), before);
        if (successor != 0 && before * blockFrames >= successorOnset &&
            (before + 1u) * blockFrames <= stopFrame &&
            !engine->voices.ReleaseObserved(successorRelease)) {
            float peak = 0.0f;
            for (std::uint32_t index = 0; index < blockFrames * engine->nullBackend.Channels(); ++index)
                peak = std::max(peak, std::abs(engine->nullBackend.LastBlock()[index]));
            EXPECT_GT(peak, 0.001f);
            successorAudible = successorAudible || peak > 0.001f;
        }
    }
    ASSERT_TRUE(inherited);
    ASSERT_TRUE(successorAudible);
    ASSERT_TRUE(successorRelease.Valid());
    ASSERT_LT(successorOnset, stopFrame);
    if (crossesStop) {
        ASSERT_GT(successorOnset + samples.size(), stopFrame + 240u);
        ASSERT_NE(nullptr, engine->voices.Resolve(successor));
        EXPECT_FALSE(engine->voices.ReleaseObserved(successorRelease));
    } else {
        ASSERT_LT(successorOnset + samples.size(), stopFrame);
        EXPECT_TRUE(engine->voices.ReleaseObserved(successorRelease));
    }
    // The published audio controls must reach the original boundary without logic service.
    for (std::uint32_t block = 0; block < 3; ++block) {
        const auto before = engine->mixer.BlocksRendered();
        engine->nullBackend.Pump(1);
        ASSERT_GT(engine->mixer.BlocksRendered(), before);
        const auto firstFrame = before * blockFrames;
        for (std::uint32_t frame = 0; frame < blockFrames; ++frame) {
            if (firstFrame + frame < stopFrame + 240u) continue;
            for (std::uint32_t channel = 0; channel < engine->nullBackend.Channels(); ++channel)
                EXPECT_LE(std::abs(engine->nullBackend.LastBlock()[frame * engine->nullBackend.Channels() + channel]),
                          harkentest::kSilenceFloor);
        }
    }
    EXPECT_EQ(nullptr, engine->voices.Resolve(successor));
    EXPECT_TRUE(engine->voices.ReleaseObserved(successorRelease));
    for (std::uint32_t block = 0; block < 8; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    ASSERT_EQ(VN_OK, Vn_Update());
    EXPECT_FALSE(engine->runtimeRecreateRequired);
    EXPECT_FALSE(engine->playableInstances.Classify(root).live);
    VnActionStepResult result{};
    result.structSize = sizeof(result);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(stopFiring, 0, &result));
    EXPECT_EQ(VN_ACTION_STEP_SUCCEEDED, result.state);
    EXPECT_EQ(0u, result.remainingPlayableCount);
}

TEST(ActionFiringApi, DistantStopKeepsRollingPagesAndLaterContainerSuccessors) {
    CheckDistantStopContainerSuccessors(6000, true);
}

TEST(ActionFiringApi, DistantStopNaturalEndBeforeBoundaryPreventsPostBoundarySuccessor) {
    CheckDistantStopContainerSuccessors(4096, false);
}

TEST(ActionFiringApi, DelayedStopInheritedDiscreteReplacementArmRefusalPreservesSelection) {
    (void)Vn_Term();
    harkentest::EngineSession session(harkentest::MakeNullConfig(4, 256, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    std::vector<float> samples(32768, 0.25f);
    const auto pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &pcm));
    CanonicalActionWorld image(engine->registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
                               engine->registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
    image.MakeDelayedSeparateSoundStopAction(DelayNanosecondsForTargetFrame(*engine, 15000));
    image.MakeImmediateVariableControlPlayAction();
    image.containers[3].discreteTiming = 1;
    image.containers[3].evaluationPeriodFrames = 256;
    image.steps[10].target = image.steps[11].target;
    image.actions[8].programSemanticFingerprint = harken::ComputeActionProgramFingerprintV1(image.actions[8]);
    image.world.identity.runtimeSemanticFingerprint = harken::ComputeCurrentWorldFingerprintV4(image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok, harken::InstallContainerWorldV1(*engine, image.world).status);
    auto play = ValidPostDesc();
    play.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle playFiring = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&play, &playFiring));
    auto& row = engine->playableServices[0];
    const auto root = row.rootInstance;
    auto stop = ValidPostDesc();
    stop.actionId = image.actions[8].actionStableId;
    VnActionFiringHandle stopFiring = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&stop, &stopFiring));
    for (std::uint32_t block = 0; block < 8; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    ASSERT_EQ(VN_OK, Vn_Update());
    const auto originalChild = row.variableControlChildInstances[0];
    const auto originalOrdinal = row.variableControlDiscreteCurrentChildOrdinal;
    const auto playableCount = engine->playableInstances.LiveCount();
    const auto decisionCount = engine->decisions.LiveCount();
    const auto rootEpoch = engine->playableInstances.Classify(root).scheduleEpoch;
    std::vector<harken::TimelineArmToken> blockers;
    while (engine->timelineArms.FreeCount() > 2u) {
        harken::TimelineArmToken token{};
        ASSERT_TRUE(engine->timelineArms.Prepare(0, 1, 15000, 15000, root, row.payload.target, &token));
        blockers.push_back(token);
    }
    ASSERT_EQ(VN_OK, Vn_SetValue(harkentest::ObjectId(41), 1.0f));
    for (std::uint32_t block = 0; block < 4; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    EXPECT_FALSE(engine->runtimeRecreateRequired);
    EXPECT_EQ(rootEpoch, engine->playableInstances.Classify(root).scheduleEpoch);
    EXPECT_EQ(originalChild, row.variableControlChildInstances[0]);
    EXPECT_EQ(originalOrdinal, row.variableControlDiscreteCurrentChildOrdinal);
    EXPECT_EQ(playableCount, engine->playableInstances.LiveCount());
    EXPECT_EQ(decisionCount, engine->decisions.LiveCount());
    EXPECT_FALSE(row.variableControlDiscreteRetargetPrepared);
    for (const auto token : blockers) ASSERT_TRUE(engine->timelineArms.CancelPrepared(token));
    bool promoted = false;
    for (std::uint32_t block = 0; block < 24 && !promoted; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        promoted = row.variableControlDiscreteCurrentChildOrdinal == 8u;
    }
    EXPECT_TRUE(promoted);
    EXPECT_FALSE(engine->runtimeRecreateRequired);
}

TEST(ActionFiringApi, DelayedStopLastControlArmRefusalLeavesCapturedRootUnchanged) {
    (void)Vn_Term();
    harkentest::EngineSession session(harkentest::MakeNullConfig(2, 256, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    std::vector<float> samples(4096, 0.25f);
    EXPECT_EQ(2ull * engine->config.maxPlayableInstances + engine->config.maxScheduledTransactions,
              engine->queueProgramBanks.size());
    ::testing::Test::RecordProperty("queue_program_bank_bytes", static_cast<int>(sizeof(harken::EngineQueueProgramBank)));
    ::testing::Test::RecordProperty("queue_program_bank_capacity", static_cast<int>(engine->queueProgramBanks.size()));
    ::testing::Test::RecordProperty("queue_program_bank_storage_bytes",
        std::to_string(engine->queueProgramBanks.size() * sizeof(harken::EngineQueueProgramBank)));
    const auto pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &pcm));
    CanonicalActionWorld image(engine->registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
                               engine->registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
    image.MakeDelayedSeparateSoundStopAction(DelayNanosecondsForTargetFrame(*engine, 3072));
    image.MakeImmediateCompositeSegmentPlayAction();
    image.steps[10].target = image.steps[11].target;
    image.actions[8].programSemanticFingerprint = harken::ComputeActionProgramFingerprintV1(image.actions[8]);
    image.world.identity.runtimeSemanticFingerprint = harken::ComputeCurrentWorldFingerprintV4(image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok, harken::InstallContainerWorldV1(*engine, image.world).status);
    auto play = ValidPostDesc();
    play.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle playFiring = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&play, &playFiring));
    const auto root = engine->playableServices[0].rootInstance;
    const auto before = engine->playableInstances.Classify(root);
    std::vector<harken::TimelineArmToken> blockers;
    while (engine->timelineArms.FreeCount() > 1u) {
        harken::TimelineArmToken token{};
        ASSERT_TRUE(engine->timelineArms.Prepare(0, 1, 3072, 3072, root,
                                               engine->playableServices[0].payload.target, &token));
        blockers.push_back(token);
    }
    ASSERT_EQ(1u, engine->timelineArms.FreeCount());
    const auto arms = engine->timelineArms.LiveCount();
    const auto transactions = engine->timelinePool.LiveTransactionCount();
    auto stop = ValidPostDesc();
    stop.actionId = image.actions[8].actionStableId;
    VnActionFiringHandle stopFiring = 0;
    EXPECT_EQ(VN_BACKPRESSURE, Vn_PostAction(&stop, &stopFiring));
    EXPECT_EQ(0u, stopFiring);
    EXPECT_EQ(arms, engine->timelineArms.LiveCount());
    EXPECT_EQ(1u, engine->timelineArms.FreeCount());
    EXPECT_EQ(transactions, engine->timelinePool.LiveTransactionCount());
    EXPECT_EQ(before.scheduleEpoch, engine->playableInstances.Classify(root).scheduleEpoch);
    EXPECT_FALSE(engine->playableInstances.HasCancellationClaim(root));
    EXPECT_FALSE(engine->runtimeRecreateRequired);
    for (const auto& operation : engine->authoredStopRoots) EXPECT_FALSE(operation.operation.has_value());
    for (const auto& resource : engine->authoredStopResources) EXPECT_FALSE(resource.prepared || resource.committed);
    for (const auto token : blockers) ASSERT_TRUE(engine->timelineArms.CancelPrepared(token));
    ASSERT_EQ(VN_OK, Vn_PostAction(&stop, &stopFiring));
    EXPECT_NE(0u, stopFiring);
}

TEST(ActionFiringApi, DelayedStopApplyingDecisionSurvivesRowReuseUntilDone) {
    (void)Vn_Term();
    harkentest::EngineSession session(harkentest::MakeNullConfig(4, 256, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    std::vector<float> samples(32768, 0.25f);
    const auto pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &pcm));
    CanonicalActionWorld image(engine->registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
                               engine->registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
    image.MakeDelayedSeparateSoundStopAction(DelayNanosecondsForTargetFrame(*engine, 15000));
    image.MakeImmediateVariableControlPlayAction();
    image.steps[10].target = image.steps[11].target;
    image.actions[8].programSemanticFingerprint = harken::ComputeActionProgramFingerprintV1(image.actions[8]);
    image.world.identity.runtimeSemanticFingerprint = harken::ComputeCurrentWorldFingerprintV4(image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok, harken::InstallContainerWorldV1(*engine, image.world).status);
    auto play = ValidPostDesc();
    play.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle playFiring = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&play, &playFiring));
    auto& row = engine->playableServices[0];
    const auto oldRoot = row.rootInstance;
    const auto oldDecision = row.variableControlDiscreteDecision;
    const auto oldGroup = row.variableControlDiscreteArmGroup;
    harken::DecisionReserveRequest reserve{};
    reserve.ticket.sequence = 100;
    reserve.world = engine->variables.CurrentWorldGeneration();
    reserve.transport = engine->timelinePool.Epoch();
    reserve.expectedContinuationGeneration = 1;
    reserve.sliceCount = 1;
    std::vector<harken::DecisionToken> blockers;
    while (engine->decisions.LiveCount() < engine->decisions.Capacity()) {
        harken::DecisionToken blocker{};
        ASSERT_TRUE(engine->decisions.Reserve(reserve, &blocker));
        blockers.push_back(blocker);
    }
    auto stop = ValidPostDesc();
    stop.actionId = image.actions[8].actionStableId;
    VnActionFiringHandle stopFiring = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&stop, &stopFiring));
    const auto resource = std::find_if(engine->authoredStopResources.begin(),
        engine->authoredStopResources.end(), [&](const auto& candidate) {
            return candidate.committed && candidate.fence &&
                candidate.fence->decision.slot == oldDecision.slot &&
                candidate.fence->decision.generation == oldDecision.generation;
        });
    ASSERT_NE(engine->authoredStopResources.end(), resource);
    ASSERT_EQ(harken::AuthoredStopFenceAccess::Armed, resource->fence->Access());
    ASSERT_TRUE(resource->fence->TryBeginApply());
    harken::DecisionFuturePin secondPin;
    ASSERT_TRUE(engine->decisions.AcquireFuturePin(oldDecision, &secondPin));
    std::optional<harken::AuthoredStopFenceDescriptor> secondDescriptor;
    secondDescriptor.emplace(resource->fence->operation, resource->fence->identity,
        oldDecision, &resource->runtime, resource->runtime.generation, std::move(secondPin));
    ASSERT_TRUE(secondDescriptor->TryBeginApply());
    for (std::uint32_t block = 0; block < 8; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    ASSERT_EQ(harken::AuthoredStopFenceAccess::Applying, resource->fence->Access());
    ASSERT_EQ(harken::AuthoredStopFenceAccess::Applying, secondDescriptor->Access());
    ASSERT_TRUE(engine->decisions.Contains(oldDecision));
    ASSERT_TRUE(engine->playableInstances.Classify(oldRoot).live);
    ASSERT_EQ(VN_OK, Vn_StopActionFiring(playFiring, 0));
    for (std::uint32_t block = 0; block < 12 && engine->playableInstances.Classify(oldRoot).live; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    ASSERT_FALSE(engine->playableInstances.Classify(oldRoot).live);
    ASSERT_EQ(VN_OK, Vn_Update());
    EXPECT_EQ(harken::EnginePlayableStartPhase::Free, row.phase);
    ASSERT_TRUE(engine->decisions.Contains(oldDecision));
    auto& retired = engine->decisionRetirements[oldDecision.slot];
    ASSERT_EQ(oldDecision.generation, retired.decision.generation);
    for (std::uint32_t block = 0; block < 2; ++block) {
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
    }
    harken::ArmGroupSnapshot group{};
    EXPECT_FALSE(engine->armGroups.Capture(oldGroup, &group));
    EXPECT_FALSE(retired.group.Valid());
    EXPECT_TRUE(engine->decisions.Contains(oldDecision));
    while (engine->decisions.LiveCount() < engine->decisions.Capacity()) {
        harken::DecisionToken blocker{};
        ASSERT_TRUE(engine->decisions.Reserve(reserve, &blocker));
        EXPECT_NE(oldDecision.slot, blocker.slot);
        blockers.push_back(blocker);
    }
    harken::DecisionToken refused{};
    EXPECT_FALSE(engine->decisions.Reserve(reserve, &refused));
    harken::PlayableStartRequest freshSound{};
    freshSound.root = image.child.playable;
    const auto replacement = harken::StartPlayable(*engine, engine->variables.CurrentPlayableWorld(), freshSound);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, replacement.status);
    ASSERT_EQ(replacement.instance, row.rootInstance);
    const auto newVoice = row.renderHandle;
    resource->fence->FinishApply();
    ASSERT_EQ(VN_OK, Vn_Update());
    EXPECT_TRUE(engine->decisions.Contains(oldDecision));
    secondDescriptor->FinishApply();
    ASSERT_TRUE(secondDescriptor->DisarmAndReleaseDecisionPin());
    ASSERT_EQ(VN_OK, Vn_Update());
    EXPECT_FALSE(engine->decisions.Contains(oldDecision));
    EXPECT_FALSE(retired.decision.Valid());
    harken::DecisionToken reused{};
    ASSERT_TRUE(engine->decisions.Reserve(reserve, &reused));
    EXPECT_EQ(oldDecision.slot, reused.slot);
    EXPECT_NE(oldDecision.generation, reused.generation);
    EXPECT_FALSE(secondDescriptor->TryBeginApply());
    EXPECT_TRUE(engine->decisions.IsOpen(reused));
    const auto handOffRetiredDecision = [&](harken::DecisionToken decision) {
        row.queueArrivalDecision = decision;
        row.queueArrivalDecisionCancelled = true;
        row.queueArrivalCleanupStarted = true;
        ASSERT_EQ(VN_OK, Vn_Update());
        EXPECT_FALSE(row.queueArrivalDecision.Valid());
    };
    handOffRetiredDecision(reused);
    ASSERT_FALSE(engine->decisions.Contains(reused));
    ASSERT_FALSE(retired.decision.Valid());
    // A repeated producer handoff must not recreate the reclaimed generation.
    handOffRetiredDecision(reused);
    ASSERT_FALSE(retired.decision.Valid());
    harken::DecisionToken nextGeneration{};
    ASSERT_TRUE(engine->decisions.Reserve(reserve, &nextGeneration));
    ASSERT_EQ(reused.slot, nextGeneration.slot);
    ASSERT_NE(reused.generation, nextGeneration.generation);
    harken::DecisionFuturePin nextPin;
    ASSERT_TRUE(engine->decisions.AcquireFuturePin(nextGeneration, &nextPin));
    handOffRetiredDecision(nextGeneration);
    ASSERT_TRUE(engine->decisions.Contains(nextGeneration));
    EXPECT_EQ(nextGeneration.generation, retired.decision.generation);
    ASSERT_TRUE(nextPin.Release());
    ASSERT_EQ(VN_OK, Vn_Update());
    EXPECT_FALSE(engine->decisions.Contains(nextGeneration));
    EXPECT_FALSE(retired.decision.Valid());
    for (const auto blocker : blockers) {
        ASSERT_TRUE(engine->decisions.Cancel(blocker));
        ASSERT_TRUE(engine->decisions.ReclaimCancelled(blocker));
    }
    EXPECT_NE(nullptr, engine->voices.Resolve(newVoice));
    EXPECT_EQ(replacement.instance, row.rootInstance);
    EXPECT_FALSE(engine->runtimeRecreateRequired);
}

TEST(ActionFiringApi, StopSkipsCompletedPublicOwnerWhileItsPartitionRetires) {
    harkentest::EngineSession session(harkentest::MakeNullConfig(4, 64, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    std::vector<float> shortSound(64, 0.25f);
    std::vector<float> longSound(8192, -0.25f);
    const auto shortPcm = harkentest::MonoDesc(shortSound, 48000);
    const auto longPcm = harkentest::MonoDesc(longSound, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &shortPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &longPcm));
    CanonicalActionWorld image(engine->registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
    image.MakeImmediateSoundPlayAction();
    image.steps[12] = image.steps[11];
    image.steps[12].authoredEventIndex = 1;
    image.steps[12].target.stableId = image.properties[1].stableId;
    image.steps[12].target.expectedProgramSemanticFingerprint = image.properties[1].programSemanticFingerprint;
    image.actions[9].stepCount = 2;
    image.actions[9].expandedStepOccurrenceCount = 2;
    image.actions[9].programSemanticFingerprint = harken::ComputeActionProgramFingerprintV1(image.actions[9]);
    image.world.identity.runtimeSemanticFingerprint = harken::ComputeCurrentWorldFingerprintV4(image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok, harken::InstallContainerWorldV1(*engine, image.world).status);
    auto desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    auto& shortRow = engine->playableServices[0];
    auto& longRow = engine->playableServices[1];
    const auto shortRoot = shortRow.rootInstance;
    const auto longRoot = longRow.rootInstance;
    const auto shortPartition = shortRow.partition;
    const auto shortIdentity = shortRow.identity;
    for (std::uint32_t block = 0; block < 32 && !shortRow.partitionRetiring; ++block) {
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
    }
    ASSERT_TRUE(shortRow.partitionRetiring);
    ASSERT_FALSE(engine->playableInstances.Classify(shortRoot).live);
    ASSERT_TRUE(engine->playableInstances.Classify(longRoot).live);
    ASSERT_NE(harken::EnginePlayableStartPhase::Free, shortRow.phase);
    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
    ASSERT_EQ(1u, info.livePlayableCount);
    ASSERT_EQ(VN_OK, Vn_StopActionFiring(firing, 0));
    EXPECT_TRUE(shortRow.partitionRetiring);
    EXPECT_EQ(shortPartition.slot, shortRow.partition.slot);
    EXPECT_EQ(shortPartition.generation, shortRow.partition.generation);
    EXPECT_EQ(shortIdentity, shortRow.identity);
    ASSERT_EQ(VN_OK, Vn_Update());
    EXPECT_TRUE(shortRow.partitionRetiring);
    for (std::uint32_t block = 0; block < 64; ++block) {
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        if (engine->playablePartitions.OccupiedCount() == 0) break;
    }
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
    EXPECT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
    EXPECT_EQ(0u, info.livePlayableCount);
    EXPECT_EQ(0u, engine->playablePartitions.OccupiedCount());
    EXPECT_EQ(0u, engine->playableInstances.LiveCount());
    EXPECT_FALSE(engine->runtimeRecreateRequired);
    EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
}

static void CheckCapturedStopAudioAndRetirement(harken::Engine& engine,
    harken::PlayableInstanceHandle root, VnVoiceHandle render,
    harken::VoiceReleaseObserver release, std::uint64_t onset, std::uint64_t stopFrame) {
    ASSERT_TRUE(release.Valid());
    const auto blockFrames = engine.config.blockFrames;
    bool audible = false;
    bool remainedActive = true;
    while (engine.mixer.BlocksRendered() * blockFrames < stopFrame / blockFrames * blockFrames) {
        ASSERT_EQ(VN_OK, Vn_Update());
        for (const auto& row : engine.playableServices) {
            if (row.rootInstance == root && engine.mixer.BlocksRendered() * blockFrames > onset)
                remainedActive = remainedActive && row.controlLifecycle == harken::PlayableControlLifecycle::Active;
        }
        const auto before = engine.mixer.BlocksRendered();
        engine.nullBackend.Pump(1);
        ASSERT_GT(engine.mixer.BlocksRendered(), before);
        if (before * blockFrames >= onset && (before + 1u) * blockFrames <= stopFrame) {
            EXPECT_FALSE(engine.voices.ReleaseObserved(release));
            float peak = 0.0f;
            for (std::uint32_t sample = 0; sample < blockFrames * engine.nullBackend.Channels(); ++sample)
                peak = std::max(peak, std::abs(engine.nullBackend.LastBlock()[sample]));
            EXPECT_GT(peak, 0.001f);
            audible = audible || peak > 0.001f;
        }
    }
    ASSERT_TRUE(audible);
    EXPECT_TRUE(remainedActive);
    ASSERT_NE(nullptr, engine.voices.Resolve(render));
    // Cross the original Stop boundary using only fresh audio blocks.
    for (std::uint32_t block = 0; block < 3; ++block) {
        const auto before = engine.mixer.BlocksRendered();
        engine.nullBackend.Pump(1);
        ASSERT_GT(engine.mixer.BlocksRendered(), before);
        float stoppedPeak = 0.0f;
        for (std::uint32_t frame = 0; frame < blockFrames; ++frame) {
            if (before * blockFrames + frame < stopFrame + 240u) continue;
            for (std::uint32_t channel = 0; channel < engine.nullBackend.Channels(); ++channel)
                stoppedPeak = std::max(stoppedPeak,
                    std::abs(engine.nullBackend.LastBlock()[frame * engine.nullBackend.Channels() + channel]));
        }
        EXPECT_LE(stoppedPeak, harkentest::kSilenceFloor) << "block=" << before << " stop=" << stopFrame;
    }
    EXPECT_TRUE(engine.voices.ReleaseObserved(release));
    EXPECT_EQ(nullptr, engine.voices.Resolve(render));
    for (std::uint32_t block = 0; block < 12; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine.nullBackend.Pump(1);
    }
    ASSERT_EQ(VN_OK, Vn_Update());
    EXPECT_FALSE(engine.playableInstances.Classify(root).live);
    EXPECT_EQ(0u, engine.playableInstances.LiveCount());
    EXPECT_EQ(0u, engine.decisions.LiveCount());
    EXPECT_EQ(0u, engine.timelineExecutor.Stats().protocolViolation);
    EXPECT_FALSE(engine.runtimeRecreateRequired);
}

static void CheckDelayedStopMatchEnteringNestedDecision(bool refuseLastArm) {
    (void)Vn_Term();
    harkentest::EngineSession session(harkentest::MakeNullConfig(6, 256, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    std::vector<float> samples(32768, 0.25f);
    const auto pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &pcm));
    CanonicalActionWorld image(engine->registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
                               engine->registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
    image.MakeDelayedSeparateSoundStopAction(DelayNanosecondsForTargetFrame(*engine, 15000));
    image.MakeImmediateNestedVariableControlRetargetPlayAction();
    image.containers[3].discreteTiming = 1;
    image.containers[3].evaluationPeriodFrames = 64;
    image.containers[1].children = &image.variableControlChildren[0];
    auto nestedRow = image.variableControlRows[0];
    nestedRow.cells = &image.variableControlCells[1];
    image.containers[1].discreteRows = &nestedRow;
    image.occurrences[1].childPlayable = image.variableControlChildren[0].playable;
    image.occurrences[1].occurrenceSemanticFingerprint =
        harken::ComputePlayableOccurrenceFingerprintV1(image.occurrences[1]);
    image.actions[9].stepCount = 1;
    image.actions[9].expandedStepOccurrenceCount = 1;
    image.actions[9].programSemanticFingerprint = harken::ComputeActionProgramFingerprintV1(image.actions[9]);
    image.steps[10].target = image.steps[11].target;
    image.actions[8].programSemanticFingerprint = harken::ComputeActionProgramFingerprintV1(image.actions[8]);
    image.world.identity.runtimeSemanticFingerprint = harken::ComputeCurrentWorldFingerprintV4(image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok, harken::InstallContainerWorldV1(*engine, image.world).status);
    auto play = ValidPostDesc();
    play.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle playFiring = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&play, &playFiring));
    auto& row = engine->playableServices[0];
    const auto root = row.rootInstance;
    auto stop = ValidPostDesc();
    stop.actionId = image.actions[8].actionStableId;
    VnActionFiringHandle stopFiring = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&stop, &stopFiring));
    for (std::uint32_t block = 0; block < 8; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    ASSERT_EQ(VN_OK, Vn_Update());
    std::vector<harken::TimelineArmToken> blockers;
    const auto originalChild = row.variableControlChildInstances[0];
    const auto originalEpoch = engine->playableInstances.Classify(root).scheduleEpoch;
    const auto originalChildren = row.variableControlChildInstances.Snapshot();
    const auto originalInstances = engine->playableInstances.LiveCount();
    const auto originalDecisions = engine->decisions.LiveCount();
    std::vector<VnVoiceHandle> originalStopVoices;
    for (const auto& resource : engine->authoredStopResources)
        if (resource.committed && resource.installation.renderHandle != 0)
            originalStopVoices.push_back(resource.installation.renderHandle);
    const auto originalResources = std::count_if(engine->authoredStopResources.begin(),
        engine->authoredStopResources.end(), [](const auto& resource) {
            return resource.prepared || resource.committed;
        });
    if (refuseLastArm) {
        while (engine->timelineArms.FreeCount() > 2u) {
            harken::TimelineArmToken token{};
            ASSERT_TRUE(engine->timelineArms.Prepare(0, 1, 15000, 15000, root,
                                                   row.payload.target, &token));
            blockers.push_back(token);
        }
        ASSERT_EQ(2u, engine->timelineArms.FreeCount());
    }
    ASSERT_EQ(VN_OK, Vn_SetValue(image.variables[3].variableId, 1.0f));
    if (refuseLastArm) {
        for (std::uint32_t block = 0; block < 4; ++block) {
            ASSERT_EQ(VN_OK, Vn_Update());
            engine->nullBackend.Pump(1);
        }
        EXPECT_EQ(originalEpoch, engine->playableInstances.Classify(root).scheduleEpoch);
        EXPECT_EQ(originalChild, row.variableControlChildInstances[0]);
        EXPECT_EQ(originalChildren, row.variableControlChildInstances.Snapshot());
        EXPECT_EQ(originalInstances, engine->playableInstances.LiveCount());
        EXPECT_EQ(originalDecisions, engine->decisions.LiveCount());
        EXPECT_EQ(originalResources, std::count_if(engine->authoredStopResources.begin(),
            engine->authoredStopResources.end(), [](const auto& resource) {
                return resource.prepared || resource.committed;
            }));
        EXPECT_FALSE(row.variableControlDiscreteRetargetPrepared);
        EXPECT_EQ(2u, engine->timelineArms.FreeCount());
        EXPECT_FALSE(engine->runtimeRecreateRequired);
        for (const auto token : blockers) ASSERT_TRUE(engine->timelineArms.CancelPrepared(token));
    }
    bool captured = false;
    harken::DecisionToken incoming{};
    for (std::uint32_t block = 0; block < 16 && !captured; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        if (row.VariablePayload().variableControlDiscreteRetargetIncomingNestedVariableControlCount != 0) {
            incoming = row.VariableControlRetargetIncoming().controllers[0].decision;
            captured = incoming.Valid();
        }
        engine->nullBackend.Pump(1);
    }
    ASSERT_TRUE(captured);
    const auto descriptor = std::find_if(engine->authoredStopResources.begin(),
        engine->authoredStopResources.end(), [&](const auto& resource) {
            return resource.committed && resource.fence &&
                resource.fence->decision.slot == incoming.slot &&
                resource.fence->decision.generation == incoming.generation;
        });
    ASSERT_NE(engine->authoredStopResources.end(), descriptor);
    EXPECT_EQ(15000u, descriptor->fence->identity.stopFrame);
    EXPECT_EQ(root, descriptor->fence->identity.root);
    EXPECT_FALSE(engine->runtimeRecreateRequired);
    const auto voice = std::find_if(engine->authoredStopResources.begin(),
        engine->authoredStopResources.end(), [&](const auto& resource) {
            harken::EngineTimelineVoiceInstallIdentity installation{};
            return resource.committed && resource.installation.renderHandle != 0 &&
                std::find(originalStopVoices.begin(), originalStopVoices.end(),
                    resource.installation.renderHandle) == originalStopVoices.end() &&
                engine->CaptureTimelineVoiceInstallIdentity(resource.installation.renderHandle, &installation) &&
                installation.rootInstance == root && installation.onsetFrame > 1024;
        });
    ASSERT_NE(engine->authoredStopResources.end(), voice);
    harken::EngineTimelineVoiceInstallIdentity installation{};
    ASSERT_TRUE(engine->CaptureTimelineVoiceInstallIdentity(voice->installation.renderHandle, &installation));
    CheckCapturedStopAudioAndRetirement(*engine, root, voice->installation.renderHandle,
        voice->installation.releaseObserver, installation.onsetFrame, 15000);
    EXPECT_FALSE(engine->decisions.Contains(incoming));
    VnActionStepResult result{};
    result.structSize = sizeof(result);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(stopFiring, 0, &result));
    EXPECT_EQ(VN_ACTION_STEP_SUCCEEDED, result.state);
    EXPECT_EQ(0u, result.remainingPlayableCount);
}

TEST(ActionFiringApi, DelayedStopMatchEnteringNestedDecisionInheritsOriginalBoundary) {
    CheckDelayedStopMatchEnteringNestedDecision(false);
}

TEST(ActionFiringApi, DelayedStopMatchNestedLastArmRefusalPreservesWholeSelection) {
    CheckDelayedStopMatchEnteringNestedDecision(true);
}

struct PreparedRoutingGuardProbe {
    harken::Engine& engine;
    std::uint32_t plain = 0;
    std::uint32_t inherited = 0;

    explicit PreparedRoutingGuardProbe(harken::Engine& current) : engine(current) {
        engine.timelineVoicePreparedContextForTest = this;
        engine.timelineVoicePreparedHookForTest = [](harken::Engine& current,
            const harken::EnginePreparedTimelineVoiceStart& original, void* context) {
            auto& probe = *static_cast<PreparedRoutingGuardProbe*>(context);
            ASSERT_TRUE(harken::ValidatePreparedTimelineVoiceStartRoutingV1(current, original));
            auto candidate = original;
            if (original.inheritedStop.operationSlot == UINT32_MAX) {
                ++probe.plain;
                EXPECT_EQ(original.commandCount, original.commands[0].payload.play.batch.batchCommandCount);
                --candidate.commands[0].payload.play.batch.batchCommandCount;
                EXPECT_FALSE(harken::ValidatePreparedTimelineVoiceStartRoutingV1(current, candidate));
                return;
            }
            ++probe.inherited;
            ASSERT_GT(original.commandCount, 1u);
            ASSERT_LT(original.commandCount, original.commands.size());
            const auto last = original.commandCount - 1;
            EXPECT_EQ(last, original.commands[0].payload.play.batch.batchCommandCount);
            EXPECT_EQ(harken::PlayLedBatchKind::TimelineControlArm,
                original.commands[last].payload.play.batch.batchKind);
            EXPECT_EQ(1u, original.commands[last].payload.play.batch.batchCommandCount);
            const auto rejected = [&](auto mutate) {
                candidate = original;
                mutate(candidate);
                EXPECT_FALSE(harken::ValidatePreparedTimelineVoiceStartRoutingV1(current, candidate));
            };
            rejected([](auto& value) { value.commands[0].payload.play.batch.batchCommandCount = value.commandCount; });
            rejected([](auto& value) { --value.commandCount; });
            rejected([&](auto& value) { value.commands[last].opcode = harken::kOpcodeSetVoiceSend; });
            rejected([&](auto& value) { value.commands[last].opcode = harken::kOpcodeClearVoiceSend; });
            rejected([&](auto& value) { value.commands[last].payload.play.batch.batchKind = harken::PlayLedBatchKind::TimelineArm; });
            rejected([&](auto& value) { value.commands[last].payload.play.batch.batchCommandCount = 2; });
            rejected([&](auto& value) { value.commands[last].payload.play.batch.armToken ^= UINT64_C(1) << 32; });
            rejected([&](auto& value) { value.commands[last].payload.play.handle ^= UINT64_C(1) << 32; });
            rejected([&](auto& value) { value.commands[last].payload.play.sourceIdentity ^= UINT64_C(1) << 32; });
            rejected([](auto& value) { value.commands[value.commandCount++] = {}; });
            rejected([](auto& value) { value.inheritedStop.firstResource = UINT32_MAX; });
            EXPECT_TRUE(harken::ValidatePreparedTimelineVoiceStartRoutingV1(current, original));
        };
    }

    ~PreparedRoutingGuardProbe() {
        engine.timelineVoicePreparedHookForTest = nullptr;
        engine.timelineVoicePreparedContextForTest = nullptr;
    }
};

static void CheckInheritedStopSuccessorLastCommand(bool nestedQueue) {
    harkentest::EngineSession session(harkentest::MakeNullConfig(8, 256, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    PreparedRoutingGuardProbe routingProbe(*engine);
    std::vector<float> samples(2048, 0.25f);
    const auto pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &pcm));
    CanonicalActionWorld image(engine->registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
                               engine->registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
    image.MakeDelayedSeparateSoundStopAction(DelayNanosecondsForTargetFrame(*engine, 15000));
    auto nestedChild = image.queueChildren[0];
    if (nestedQueue) {
        image.MakeImmediateQueueNestedContainerPlayAction(false);
        nestedChild.stableChildOrdinal = image.child.stableChildOrdinal;
        nestedChild.frequencyWeight = 0;
        image.containers[0].mode = harken::ContainerModeV1::SequenceQueue;
        image.containers[0].memoryScope = harken::MemoryScopeV1::Emitter;
        image.containers[0].queueCycle = harken::QueueCycleV1::Once;
        image.containers[0].queueSplice = harken::QueueSpliceV1::Butt;
        image.containers[0].children = &nestedChild;
    } else {
        image.MakeImmediateSequenceContainerPlayAction();
        image.properties[2].payload.presentMask |= UINT64_C(1) << 3;
        image.properties[2].payload.values[3].bits = 2;
        image.properties[2].programSemanticFingerprint =
            harken::ComputePlayablePropertyFingerprintV1(image.properties[2]);
        image.containers[0].programSemanticFingerprint = image.properties[2].programSemanticFingerprint;
        image.occurrences[0].parentProgramSemanticFingerprint = image.properties[2].programSemanticFingerprint;
        image.occurrences[0].occurrenceSemanticFingerprint =
            harken::ComputePlayableOccurrenceFingerprintV1(image.occurrences[0]);
        image.steps[11].target.expectedProgramSemanticFingerprint = image.properties[2].programSemanticFingerprint;
        for (auto& step : image.steps) {
            if (step.target.kind == harken::ActionTargetKindV1::Container &&
                step.target.stableId == image.properties[2].stableId)
                step.target.expectedProgramSemanticFingerprint = image.properties[2].programSemanticFingerprint;
        }
    }
    image.steps[10].target = image.steps[11].target;
    for (auto& action : image.actions)
        action.programSemanticFingerprint = harken::ComputeActionProgramFingerprintV1(action);
    image.world.identity.runtimeSemanticFingerprint = harken::ComputeCurrentWorldFingerprintV4(image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok, harken::InstallContainerWorldV1(*engine, image.world).status);
    const auto ownersBefore = CaptureActionReclaimableOwners(*engine);
    const auto sourceCount = [&]() {
        std::uint32_t count = 0;
        for (std::uint32_t slot = 0; slot < engine->sourceTerminals.Capacity(); ++slot)
            count += engine->sourceTerminals.At(slot)->occupied ? 1u : 0u;
        return count;
    };
    const auto sourcesBefore = sourceCount();
    VnEmitterHandle emitter = 0;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&emitter));
    auto play = ValidPostDesc();
    play.actionId = image.actions[9].actionStableId;
    play.emitter = emitter;
    VnActionFiringHandle playFiring = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&play, &playFiring));
    auto& row = engine->playableServices[0];
    const auto root = row.rootInstance;
    auto* sourceService = FrontierActiveResourceService(*engine, row);
    ASSERT_NE(nullptr, sourceService);
    const auto originalRender = row.renderHandle;
    const auto sourceRelease = sourceService->releaseObserver;
    const auto sourceRender = sourceService->renderHandle;
    const auto originalLeaf = sourceService->activeLeafInstance;
    const auto originalOrdinals = row.selectedChildOrdinals.Snapshot();
    const auto originalIteration = row.containerLoopIteration;
    const auto rootEpoch = engine->playableInstances.Classify(root).scheduleEpoch;
    const auto originalQueue = sourceService->queueInstance;
    const auto originalParent = row.queueInstance;
    const auto originalChild = row.frontierChildService;
    harken::QueueInstanceSnapshot originalParentSnapshot{};
    if (nestedQueue) {
        ASSERT_TRUE(originalQueue.Valid());
        ASSERT_TRUE(originalParent.Valid());
        ASSERT_TRUE(engine->queueInstances.Capture(originalParent, &originalParentSnapshot));
        ASSERT_EQ(sourceService, engine->ResolvePlayableService(originalChild));
    }
    auto stop = ValidPostDesc();
    stop.actionId = image.actions[8].actionStableId;
    stop.emitter = emitter;
    VnActionFiringHandle stopFiring = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&stop, &stopFiring));
    for (std::uint32_t block = 0; block < 8; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    ASSERT_EQ(VN_OK, Vn_Update());
    for (std::uint32_t block = 0; block < 24 && !engine->voices.ReleaseObserved(sourceRelease); ++block)
        engine->nullBackend.Pump(1);
    ASSERT_TRUE(engine->voices.ReleaseObserved(sourceRelease));
    bool refused = false;
    bool resumed = false;
    for (std::uint32_t attempt = 0; attempt < 8 && !refused; ++attempt) {
        harken::QueueInstanceSnapshot parentBefore{};
        if (nestedQueue) ASSERT_TRUE(engine->queueInstances.Capture(originalParent, &parentBefore));
        const auto resourcesBefore = std::count_if(engine->authoredStopResources.begin(),
            engine->authoredStopResources.end(), [](const auto& resource) { return resource.prepared; });
        ASSERT_EQ(engine->commands.Capacity(), engine->commands.FreeSlots());
        // Base Start preflight needs three commands; its inherited Stop needs the last one.
        constexpr std::uint32_t availableCommands = 3;
        while (engine->commands.FreeSlots() > availableCommands) {
            harken::CommandRecord command{};
            command.opcode = harken::kOpcodeStop;
            ASSERT_TRUE(engine->commands.TryPush(command));
        }
        const auto pressureBefore = engine->commands.BackpressureCount();
        if (nestedQueue) {
            engine->queueContinuationFinalOnsetHookForTest =
                [](harken::Engine& current, harken::PlayableInstanceHandle) {
                    current.queueContinuationFinalOnsetHookForTest = nullptr;
                    EXPECT_EQ(3u, current.commands.FreeSlots());
                    EXPECT_FALSE(current.commands.HasRoom(4));
                };
        }
        ASSERT_EQ(VN_OK, Vn_Update());
        if (nestedQueue) {
            ASSERT_EQ(VN_OK, Vn_Update());
            ASSERT_EQ(VN_OK, Vn_Update());
        }
        refused = nestedQueue ? engine->queueContinuationFinalOnsetHookForTest == nullptr
                              : engine->commands.BackpressureCount() > pressureBefore;
        engine->queueContinuationFinalOnsetHookForTest = nullptr;
        EXPECT_EQ(availableCommands, engine->commands.FreeSlots());
        EXPECT_EQ(originalRender, row.renderHandle);
        EXPECT_EQ(rootEpoch, engine->playableInstances.Classify(root).scheduleEpoch);
        EXPECT_EQ(resourcesBefore, std::count_if(engine->authoredStopResources.begin(),
            engine->authoredStopResources.end(), [](const auto& resource) { return resource.prepared; }));
        if (nestedQueue) {
            EXPECT_EQ(originalParent.slot, row.queueInstance.slot);
            EXPECT_EQ(originalParent.generation, row.queueInstance.generation);
            EXPECT_EQ(originalChild.owner, row.frontierChildService.owner);
            EXPECT_EQ(originalChild.epoch, row.frontierChildService.epoch);
            harken::QueueInstanceSnapshot after{};
            ASSERT_TRUE(engine->queueInstances.Capture(originalParent, &after));
            EXPECT_EQ(parentBefore.logicMirror.version, after.logicMirror.version);
            EXPECT_EQ(parentBefore.logicMirror.currentChildOrdinal, after.logicMirror.currentChildOrdinal);
        } else {
            harken::ContainerPlaybackRow after{};
            ASSERT_TRUE(engine->containerPlayback.Capture(root, &after));
            EXPECT_EQ(0u, after.activeChild);
            EXPECT_EQ(1u, after.completedSelections);
            EXPECT_EQ(originalLeaf, after.lastConsumedChild);
            EXPECT_EQ(originalLeaf, row.activeLeafInstance);
            EXPECT_EQ(originalOrdinals, row.selectedChildOrdinals.Snapshot());
            EXPECT_EQ(originalIteration, row.containerLoopIteration);
        }
        for (std::uint32_t index = availableCommands; index < engine->commands.Capacity(); ++index) {
            harken::CommandRecord command{};
            ASSERT_TRUE(engine->commands.TryPop(command));
            ASSERT_EQ(harken::kOpcodeStop, command.opcode);
        }
        EXPECT_FALSE(engine->runtimeRecreateRequired);
        if (nestedQueue && refused) {
            harken::ContainerPlaybackRow completedChild{};
            ASSERT_TRUE(engine->containerPlayback.Capture(row.ownerInstance, &completedChild));
            ASSERT_EQ(originalChild.owner, completedChild.lastConsumedChild);
            ASSERT_EQ(originalChild.epoch, completedChild.lastConsumedChildEpoch);
            ASSERT_NE(0u, completedChild.lastConsumedOutcomeOrdinal);
            ASSERT_EQ(0u, completedChild.activeChild);
            const auto completedBlock = engine->mixer.BlocksRendered();
            ASSERT_EQ(VN_OK, Vn_Update());
            EXPECT_EQ(completedBlock, engine->mixer.BlocksRendered());
            resumed = row.renderHandle != originalRender;
        }
        if (!refused) engine->nullBackend.Pump(1);
    }
    ASSERT_TRUE(refused);
    if (!nestedQueue) {
        EXPECT_EQ(harken::PlayableControlReason::StartRefused, row.controlReason);
        for (std::uint32_t block = 0; block < 16 && row.phase != harken::EnginePlayableStartPhase::Free; ++block) {
            ASSERT_EQ(VN_OK, Vn_Update());
            engine->nullBackend.Pump(1);
        }
        EXPECT_EQ(harken::EnginePlayableStartPhase::Free, row.phase);
        EXPECT_EQ(0u, engine->playableInstances.LiveCount());
        EXPECT_EQ(0u, engine->containerPlayback.LiveCount());
        EXPECT_EQ(0u, engine->voices.ActiveCount());
        EXPECT_FALSE(engine->runtimeRecreateRequired);
        VnActionStepResult result{};
        result.structSize = sizeof(result);
        ASSERT_EQ(VN_OK, Vn_QueryActionStep(playFiring, 0, &result));
        EXPECT_EQ(VN_ACTION_STEP_FAILED, result.state);
        EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(playFiring));
        return;
    }
    ASSERT_TRUE(resumed);
    EXPECT_GT(routingProbe.plain, 0u);
    EXPECT_GT(routingProbe.inherited, 0u);
    const auto successor = std::find_if(engine->authoredStopResources.begin(), engine->authoredStopResources.end(),
        [&](const auto& resource) {
            return resource.committed && resource.installation.renderHandle == row.renderHandle;
        });
    ASSERT_NE(engine->authoredStopResources.end(), successor);
    ASSERT_LT(successor->operationSlot, engine->authoredStopRoots.size());
    const auto successorRender = row.renderHandle;
    const auto successorRelease = successor->installation.releaseObserver;
    EXPECT_EQ(15000u, engine->authoredStopRoots[successor->operationSlot].operation->Identity().stopFrame);
    if (nestedQueue) {
        EXPECT_FALSE(row.queueParentInstance.Valid());
        EXPECT_EQ(originalParent.slot, row.queueInstance.slot);
        EXPECT_EQ(originalParent.generation, row.queueInstance.generation);
        harken::QueueInstanceSnapshot after{};
        // Independent child services retire after their original completion fences.
        if (engine->queueInstances.Capture(originalQueue, &after)) {
            const auto* retired = engine->ResolvePlayableService(originalChild);
            ASSERT_NE(nullptr, retired);
            EXPECT_TRUE(engine->playablePartitions.Owns(retired->partition, retired->identity));
            EXPECT_EQ(originalQueue.slot, retired->queueInstance.slot);
            EXPECT_EQ(originalQueue.generation, retired->queueInstance.generation);
            EXPECT_EQ(harken::PlayableControlReason::Natural, retired->controlReason);
            EXPECT_TRUE(retired->controlLifecycle == harken::PlayableControlLifecycle::LogicalComplete ||
                        retired->controlLifecycle == harken::PlayableControlLifecycle::AudibleRetiring);
            EXPECT_TRUE(retired->queueNaturalEnd);
            EXPECT_TRUE(engine->voices.ReleaseObserved(sourceRelease));
        }
        ASSERT_TRUE(engine->queueInstances.Capture(originalParent, &after));
        EXPECT_EQ(originalParentSnapshot.logicMirror.version, after.logicMirror.version);
        ASSERT_TRUE(row.frontierAcceptedSignal.Valid());
        const auto entry = row.frontierEntry;
        const auto successorArm = row.arm;
        const auto onset = row.startFrame;
        while (engine->mixer.BlocksRendered() <= onset / engine->config.blockFrames) {
            ASSERT_EQ(VN_OK, Vn_Update());
            ASSERT_TRUE(engine->queueInstances.Capture(originalParent, &after));
            EXPECT_EQ(originalParentSnapshot.logicMirror.version, after.logicMirror.version);
            engine->nullBackend.Pump(1);
        }
        harken::TimelineArmObservation observed{};
        ASSERT_TRUE(engine->timelineArms.Observe(successorArm, &observed));
        EXPECT_EQ(onset / engine->config.blockFrames + 1u, observed.startedBlockSequence);
        const auto* activation = engine->decisions.ResolveFrontierActivation(entry.coordinator);
        ASSERT_NE(nullptr, activation);
        harken::FrontierActivationReceipt receipt{};
        ASSERT_EQ(harken::FrontierReceiptRead::Ready,
            activation->Read(entry, engine->mixer.BlocksRendered(), &receipt));
        EXPECT_EQ(harken::FrontierReceiptOutcome::Applied, receipt.outcome);
        ASSERT_TRUE(engine->queueInstances.Capture(originalParent, &after));
        EXPECT_EQ(originalParentSnapshot.logicMirror.version, after.logicMirror.version);
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_TRUE(engine->queueInstances.Capture(originalParent, &after));
        EXPECT_EQ(2u, after.logicMirror.version);
    }
    EXPECT_FALSE(engine->runtimeRecreateRequired);
    for (std::uint32_t block = 0; block < 96 && row.phase != harken::EnginePlayableStartPhase::Free; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    ASSERT_EQ(VN_OK, Vn_Update());
    EXPECT_EQ(harken::EnginePlayableStartPhase::Free, row.phase);
    EXPECT_EQ(0u, engine->playableInstances.LiveCount());
    EXPECT_EQ(0u, engine->voices.ActiveCount());
    EXPECT_EQ(0u, std::count_if(engine->authoredStopResources.begin(),
        engine->authoredStopResources.end(), [](const auto& resource) { return resource.prepared; }));
    EXPECT_FALSE(engine->runtimeRecreateRequired);
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(playFiring));
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(stopFiring));
    ASSERT_EQ(VN_OK, Vn_DestroyEmitter(emitter));
    for (std::uint32_t block = 0; block < 64 &&
         CaptureActionReclaimableOwners(*engine) != ownersBefore; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    EXPECT_EQ(ownersBefore, CaptureActionReclaimableOwners(*engine));
    EXPECT_EQ(sourcesBefore, sourceCount());
    harken::QueueInstanceSnapshot retiredQueue{};
    EXPECT_FALSE(engine->queueInstances.Capture(originalQueue, &retiredQueue));
    EXPECT_EQ(nullptr, engine->ResolvePlayableService(originalChild));
    EXPECT_TRUE(engine->voices.ReleaseObserved(sourceRelease));
    EXPECT_TRUE(engine->voices.ReleaseObserved(successorRelease));
    harken::EngineTimelineVoiceInstallIdentity retiredInstallation{};
    EXPECT_FALSE(engine->CaptureTimelineVoiceInstallIdentity(sourceRender, &retiredInstallation));
    EXPECT_FALSE(engine->CaptureTimelineVoiceInstallIdentity(successorRender, &retiredInstallation));
    EXPECT_FALSE(engine->runtimeRecreateRequired);
}

TEST(ActionFiringApi, DelayedStopOrdinarySoundLastCommandRefusalPreservesWholeSelection) {
    CheckInheritedStopSuccessorLastCommand(false);
}

TEST(ActionFiringApi, DelayedStopQueueParentLastCommandRefusalPreservesWholeSelection) {
    CheckInheritedStopSuccessorLastCommand(true);
}

static void ExpectFrozenQueueBank(const harken::EngineQueueProgramBank& bank,
                                  const harken::EngineQueueProgramBankBody& original) {
    ASSERT_TRUE(bank.occupied);
    ASSERT_EQ(original.programCount, bank.programCount);
    ASSERT_EQ(original.eventCount, bank.eventCount);
    ASSERT_EQ(original.aggregateCount, bank.aggregateCount);
    ASSERT_EQ(original.curveCount, bank.curveCount);
    EXPECT_EQ(0, std::memcmp(original.payloads.data(), bank.payloads.data(),
                            bank.eventCount * sizeof(bank.payloads[0])));
    EXPECT_EQ(0, std::memcmp(original.events.data(), bank.events.data(),
                            bank.eventCount * sizeof(bank.events[0])));
    EXPECT_EQ(0, std::memcmp(original.runtimes.data(), bank.runtimes.data(),
                            bank.programCount * sizeof(bank.runtimes[0])));
    EXPECT_EQ(0, std::memcmp(original.schedules.data(), bank.schedules.data(),
                            bank.programCount * sizeof(bank.schedules[0])));
    EXPECT_EQ(0, std::memcmp(original.aggregateRuntimes.data(), bank.aggregateRuntimes.data(),
                            bank.aggregateCount * sizeof(bank.aggregateRuntimes[0])));
    EXPECT_EQ(0, std::memcmp(original.aggregateSchedules.data(), bank.aggregateSchedules.data(),
                            bank.aggregateCount * sizeof(bank.aggregateSchedules[0])));
    EXPECT_EQ(0, std::memcmp(original.curves.data(), bank.curves.data(),
                            bank.curveCount * sizeof(bank.curves[0])));
}

static void CheckQueueResetAndScheduledStop(bool deferred, bool refuseCommand, bool inspectOldProgram = false,
    std::uint32_t availableBanks = UINT32_MAX, bool inspectRetirement = false, bool inspectOwners = false,
    bool refuseSourceSeal = false, bool refuseCalendarPlacement = false, bool refuseVoiceCapture = false,
    bool cancelPreparedCalendar = false) {
    (void)Vn_Term();
    harkentest::EngineSession session(harkentest::MakeNullConfig(8, 256, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    std::vector<float> samples(4096, 0.25f);
    const auto pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &pcm));
    CanonicalActionWorld image(engine->registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
                               engine->registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
    const auto reset = image.steps[10];
    image.MakeDelayedSeparateSoundStopAction(125000000);
    image.MakeImmediateSequenceQueuePlayAction();
    std::array<harken::ContainerChildProgramViewV2, 3> expandedChildren{
        image.queueChildren[0], image.queueChildren[1], image.queueChildren[0]};
    if (inspectOldProgram) {
        expandedChildren[2].stableChildOrdinal = 9;
        expandedChildren[2].authoredStableOrder = 2;
        image.containers[2].children = expandedChildren.data();
        image.containers[2].childCount = static_cast<std::uint32_t>(expandedChildren.size());
        image.occurrences[4] = image.occurrences[2];
        image.occurrences[4].stableOccurrenceOrdinal = expandedChildren[2].stableChildOrdinal;
        image.occurrences[4].occurrenceSemanticFingerprint =
            harken::ComputePlayableOccurrenceFingerprintV1(image.occurrences[4]);
        image.world.playableOccurrenceCount = 5;
    }
    image.containers[2].queueCycle = harken::QueueCycleV1::Loop;
    image.steps[14] = reset;
    image.steps[15] = image.steps[10];
    image.steps[15].authoredEventIndex = 1;
    image.steps[15].target = image.steps[11].target;
    image.containers[2].resumePosition = 1;
    image.actions[8].steps = &image.steps[14];
    image.actions[8].stepCount = 2;
    image.actions[8].expandedStepOccurrenceCount = 2;
    image.actions[8].programSemanticFingerprint = harken::ComputeActionProgramFingerprintV1(image.actions[8]);
    if (deferred) {
        image.MakeQuantizedPostAction(harken::ActionQuantizeTimingV1::Immediate,
            harken::ActionIfSilentV1::Immediate,
            DelayNanosecondsForTargetFrame(*engine, engine->timelinePool.WindowEndFrame()), 10, 13, harkentest::ObjectId(51), 8);
    }
    image.world.identity.runtimeSemanticFingerprint = harken::ComputeCurrentWorldFingerprintV4(image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok, harken::InstallContainerWorldV1(*engine, image.world).status);
    VnEmitterHandle emitter = 0;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&emitter));
    harken::QueueCheckpointKey checkpointKey{};
    checkpointKey.world = engine->variables.CurrentWorldGeneration();
    checkpointKey.containerStableId = image.containers[2].containerStableId;
    checkpointKey.programSemanticFingerprint = image.containers[2].programSemanticFingerprint;
    checkpointKey.resetEpoch = engine->variables.CurrentTransportEpoch();
    checkpointKey.emitterSlot = static_cast<std::uint32_t>(emitter);
    checkpointKey.emitterGeneration = static_cast<std::uint32_t>(emitter >> 32);
    harken::QueueCheckpointImage checkpoint{};
    checkpoint.effective.version = 7;
    checkpoint.effective.cursor = 1;
    checkpoint.effective.currentChildOrdinal = image.queueChildren[1].stableChildOrdinal;
    checkpoint.effective.selectionOrdinal = 3;
    checkpoint.replayCurrent = true;
    ASSERT_TRUE(engine->queueCheckpoints.Store(checkpointKey, checkpoint));
    const auto ownersBeforePlay = CaptureActionReclaimableOwners(*engine);
    const auto banksBeforePlay = CaptureActionPreparationOwners(*engine).occupiedQueueProgramBanks;
    auto play = ValidPostDesc();
    play.actionId = image.actions[9].actionStableId;
    play.emitter = emitter;
    VnActionFiringHandle playFiring = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&play, &playFiring));
    if (inspectRetirement) {
        // This case checks a published bank's completed-callback retirement fence.
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
    }
    auto& row = engine->playableServices[0];
    ASSERT_EQ(CanonicalActionWorld::kSecondSound, row.leaf.stableId);
    ASSERT_TRUE(row.queueContinuationPrepared);
    ASSERT_FALSE(row.queueArrivalDecision.Valid());
    const auto oldSuccessor = row.QueuePayload().queueSuccessorRenderHandle;
    const auto* oldProgram = row.QueueFiling().queueSuccessorSchedule.runtimeProgram.program;
    ASSERT_NE(nullptr, oldProgram);
    const auto oldPayload = oldProgram->payloads[0];
    const auto oldRuntime = *oldProgram;
    auto* const oldBank = row.QueueFiling().queueSuccessorProgramBank;
    ASSERT_NE(nullptr, oldBank);
    ASSERT_TRUE(oldBank->occupied);
    if (row.pendingImmediateEntry) {
        // Post owns the original unplaced cohort; normal service binds its timing.
        ASSERT_TRUE(row.pendingImmediateEntry);
        ASSERT_FALSE(row.queueTimingFinalized);
        EXPECT_FALSE(oldBank->published);
        ASSERT_TRUE(row.InvocationValid());
        ASSERT_TRUE(engine->playablePartitions.Owns(row.partition, row.identity));
        ASSERT_EQ(playFiring, row.PendingImmediateCohortRoot());
        const auto* pending = std::find_if(engine->immediateEntryAttempts.data(),
            engine->immediateEntryAttempts.data() + engine->immediateEntryAttempts.size(),
            [&](const auto& candidate) {
                return candidate.active && candidate.root == playFiring;
            });
        ASSERT_NE(engine->immediateEntryAttempts.data() + engine->immediateEntryAttempts.size(), pending);
        EXPECT_EQ(row.identity, pending->initialService);
        EXPECT_EQ(row.invocationGeneration, pending->initialInvocationGeneration);
        ASSERT_NE(0u, pending->generation);
        ASSERT_TRUE(std::any_of(oldBank->runtimes.begin(),
            oldBank->runtimes.begin() + oldBank->programCount,
            [&](const auto& runtime) { return &runtime == oldProgram; }));
        ASSERT_TRUE(std::any_of(oldBank->payloads.begin(),
            oldBank->payloads.begin() + oldBank->eventCount,
            [&](const auto& payload) { return &payload == oldProgram->payloads; }));
        harken::QueueInstanceSnapshot ownedQueue{};
        ASSERT_TRUE(engine->queueInstances.Capture(row.queueInstance, &ownedQueue));
        EXPECT_EQ(row.rootInstance, ownedQueue.rootInstance);
        EXPECT_EQ(0u, engine->mixer.BlocksRendered());
        harken::TimelineArmObservation currentArm{};
        harken::TimelineArmObservation futureArm{};
        ASSERT_TRUE(engine->timelineArms.Observe(row.arm, &currentArm));
        ASSERT_TRUE(engine->timelineArms.Observe(row.QueueFiling().queueSuccessorArm, &futureArm));
        EXPECT_EQ(harken::ArmState::PendingApply, currentArm.state);
        EXPECT_EQ(harken::ArmState::PendingApply, futureArm.state);
        EXPECT_EQ(0u, currentArm.armedCompletionSequence);
        EXPECT_EQ(0u, currentArm.startedBlockSequence);
        EXPECT_EQ(0u, futureArm.armedCompletionSequence);
        EXPECT_EQ(0u, futureArm.startedBlockSequence);
    } else {
        ASSERT_TRUE(oldBank->published);
    }
    ASSERT_NE(0u, oldSuccessor);
    const auto oldDecision = row.QueueFiling().queueDecision;
    const auto originalQueue = row.queueInstance;
    const auto root = row.rootInstance;
    const auto rootEpoch = engine->playableInstances.Classify(root).scheduleEpoch;
    SCOPED_TRACE(::testing::Message()
        << "beforeReset pendingEntry=" << row.pendingImmediateEntry
        << " queueTimingPending=" << row.queueTimingPending
        << " laneValid=" << row.immediateLane.Valid()
        << " preparedPagesValid=" << row.QueuePayload().queuePreparedPages.Valid()
        << " queue=" << row.queueInstance.slot << ":" << row.queueInstance.generation
        << " currentArm=" << row.arm.slot << ":" << row.arm.generation
        << " futureArm=" << row.QueueFiling().queueSuccessorArm.slot << ":" << row.QueueFiling().queueSuccessorArm.generation
        << " currentRender=" << row.renderHandle
        << " futureRender=" << row.QueuePayload().queueSuccessorRenderHandle);
    auto command = ValidPostDesc();
    command.actionId = image.actions[deferred ? 10 : 8].actionStableId;
    command.emitter = emitter;
    VnActionFiringHandle firing = 0;
    const auto capture = deferred && availableBanks == 0
        ? harkentest::monitor::OpenActivityEvents() : 0;
    std::vector<harken::EngineQueueProgramBank*> heldBanks;
    std::vector<harken::EngineQueueProgramBank::OriginalLifetimePin> heldBankLoans;
    const auto releaseHeldBanks = [&]() {
        while (!heldBanks.empty()) {
            heldBankLoans.back().Release();
            ASSERT_TRUE(engine->ResetOriginalQueueBank(*heldBanks.back()));
            heldBankLoans.pop_back();
            heldBanks.pop_back();
        }
    };
    if (availableBanks != UINT32_MAX) {
        while (auto* bank = engine->ReserveOriginalQueueBank()) {
            auto* original = engine->OriginalQueueBankHolderFor(bank);
            ASSERT_NE(nullptr, original);
            harken::EngineQueueProgramBank::OriginalLifetimePin loan;
            ASSERT_TRUE(original->baseline.Borrow(&loan));
            heldBanks.push_back(bank);
            heldBankLoans.push_back(std::move(loan));
        }
        ASSERT_GE(heldBanks.size(), availableBanks);
        for (std::uint32_t remaining = availableBanks; remaining != 0; --remaining) {
            heldBankLoans.back().Release();
            ASSERT_TRUE(engine->ResetOriginalQueueBank(*heldBanks.back()));
            heldBankLoans.pop_back();
            heldBanks.pop_back();
        }
    }
    if (refuseCommand || refuseSourceSeal || refuseVoiceCapture || (!deferred && availableBanks == 0)) {
        harken::CommandRecord occupied{};
        occupied.opcode = harken::kOpcodeStop;
        occupied.payload.stop.handle = 1;
        if (refuseCommand) {
            while (engine->commands.FreeSlots() > 5u) ASSERT_TRUE(engine->commands.TryPush(occupied));
        }
        const auto before = CaptureActionPreparationOwners(*engine);
        const auto beforeCaptureBytes = engine->CapturedVoiceStorageBytes();
        if (refuseVoiceCapture) ASSERT_TRUE(engine->queueScheduleStorage.CollectUnused());
        const auto coldScheduleBytes = engine->queueScheduleStorage.StorageBytes();
        if (refuseSourceSeal) engine->forceTimelineVoiceCommitRollbackForTest = true;
        if (refuseVoiceCapture) harken::detail::ArmLogicAllocFaultForTests(
            1, harken::detail::LogicAllocSite::CapturedVoiceInstall);
        const auto allocationsBefore = engine->nativeBackingAllocationCountForTest;
        const auto result = Vn_PostAction(&command, &firing);
        if (refuseVoiceCapture) harken::detail::DisarmLogicAllocFaultForTests();
        EXPECT_EQ(VN_BACKPRESSURE, result);
        EXPECT_FALSE(engine->forceTimelineVoiceCommitRollbackForTest);
        ExpectActionPreparationOwnersUnchanged(*engine, before);
        EXPECT_EQ(beforeCaptureBytes, engine->CapturedVoiceStorageBytes());
        EXPECT_EQ(0u, firing);
        EXPECT_EQ(oldSuccessor, row.QueuePayload().queueSuccessorRenderHandle);
        EXPECT_EQ(oldDecision.generation, row.QueueFiling().queueDecision.generation);
        EXPECT_EQ(rootEpoch, engine->playableInstances.Classify(root).scheduleEpoch);
        EXPECT_FALSE(engine->playableInstances.HasCancellationClaim(root));
        for (const auto& resource : engine->authoredStopResources) EXPECT_FALSE(resource.prepared || resource.committed);
        EXPECT_FALSE(engine->runtimeRecreateRequired);
        if (refuseVoiceCapture) {
            const auto allocationCount = engine->nativeBackingAllocationCountForTest - allocationsBefore;
            ASSERT_TRUE(engine->queueScheduleStorage.CollectUnused());
            EXPECT_EQ(coldScheduleBytes, engine->queueScheduleStorage.StorageBytes());
            for (std::uint64_t ordinal = 0; ordinal < allocationCount; ++ordinal) {
                SCOPED_TRACE(::testing::Message() << "replacement allocation refusal " << ordinal);
                engine->nativeBackingAllocationFailureCountdownForTest = static_cast<std::int32_t>(ordinal);
                const auto refused = Vn_PostAction(&command, &firing);
                engine->nativeBackingAllocationFailureCountdownForTest = -1;
                ASSERT_EQ(VN_BACKPRESSURE, refused);
                ASSERT_EQ(0u, firing);
                ASSERT_TRUE(engine->queueScheduleStorage.CollectUnused());
                EXPECT_EQ(coldScheduleBytes, engine->queueScheduleStorage.StorageBytes());
                ExpectActionPreparationOwnersUnchanged(*engine, before);
                EXPECT_EQ(beforeCaptureBytes, engine->CapturedVoiceStorageBytes());
                EXPECT_EQ(oldSuccessor, row.QueuePayload().queueSuccessorRenderHandle);
                EXPECT_EQ(oldDecision.generation, row.QueueFiling().queueDecision.generation);
                EXPECT_FALSE(engine->runtimeRecreateRequired);
            }
        }
        releaseHeldBanks();
        return;
    }
    if (cancelPreparedCalendar) {
        engine->nullBackend.Pump(1);
        for (const auto arm : {row.arm, row.QueueFiling().queueSuccessorArm}) {
            harken::TimelineArmObservation ack{};
            ASSERT_TRUE(engine->timelineArms.Observe(arm, &ack));
            ASSERT_EQ(harken::ArmState::Armed, ack.state);
            ASSERT_NE(0u, ack.armedCompletionSequence);
        }
    }
    ASSERT_EQ(VN_OK, Vn_PostAction(&command, &firing));
    if (cancelPreparedCalendar) {
        auto& selected = engine->originalQueueReplacementHolders[originalQueue.slot];
        const auto coordinator = selected.decisions[0];
        const auto groups = selected.groups;
        const auto calendar = selected.calendar.HandleObservation();
        const auto replacement = row.QueuePayload().queueSuccessorRenderHandle;
        harken::VoiceReleaseObserver release{};
        ASSERT_TRUE(engine->voices.CaptureReleaseObserver(replacement, &release));
        harken::TimelineArmObservation source{};
        ASSERT_TRUE(engine->timelineArms.Observe(row.QueueFiling().queueSuccessorArm, &source));
        ASSERT_EQ(harken::ArmState::PendingApply, source.state);
        ASSERT_EQ(0u, source.armedCompletionSequence);
        const auto serviceFence = engine->mixer.BlocksRendered();
        bool hookRan = false;
        engine->immediateQueuePostC0PublishContextForTest = &hookRan;
        engine->immediateQueuePostC0PublishHookForTest = +[](
            harken::Engine& actual, harken::EngineImmediateEntryAttempt&, void* context) {
            actual.immediateQueuePostC0PublishHookForTest = nullptr;
            actual.immediateQueuePostC0PublishContextForTest = nullptr;
            actual.nullBackend.Pump(1);
            *static_cast<bool*>(context) = true;
        };
        const auto updated = Vn_Update();
        engine->immediateQueuePostC0PublishHookForTest = nullptr;
        engine->immediateQueuePostC0PublishContextForTest = nullptr;
        ASSERT_EQ(VN_OK, updated);
        ASSERT_TRUE(hookRan);
        ASSERT_EQ(serviceFence + 1, engine->mixer.BlocksRendered());
        ASSERT_EQ(harken::Engine::OriginalQueueReplacementHolder::Phase::Selected, selected.phase);
        ASSERT_TRUE(selected.sourceClockBound && selected.clockBound && selected.calendarPinned && selected.conditionalBound);
        ASSERT_EQ(2u, selected.frontierBoundCount);
        const auto* activation = engine->decisions.ResolveFrontierActivation(coordinator);
        ASSERT_NE(nullptr, activation);
        ASSERT_EQ(harken::FrontierReceiptState::Prepared, activation->State());
        harken::FrontierActivationSidecarSnapshot pins{};
        ASSERT_TRUE(engine->decisions.CaptureFrontierActivationSidecar(coordinator, selected.entry,
            engine->mixer.BlocksRendered(), &pins));
        ASSERT_TRUE(pins.pagePinHeld && pins.observerPinHeld);
        ASSERT_EQ(harken::FrontierReceiptRead::InFlight, pins.receiptRead);
        const auto stop = std::find_if(engine->authoredStopResources.begin(), engine->authoredStopResources.end(),
            [&](const auto& control) {
                return control.nativeStopLaneOwner.Valid() &&
                    control.nativeQueueReplacement.slot == originalQueue.slot &&
                    control.nativeQueueReplacement.generation == originalQueue.generation &&
                    control.nativeReplacementDomain == selected.domain.RootObservation() &&
                    control.nativeStopSequence == selected.sequence;
            });
        ASSERT_NE(engine->authoredStopResources.end(), stop);
        ASSERT_FALSE(stop->nativeStopPublished);
        ASSERT_EQ(harken::CommandQueue::OriginalRangeState::Completed, stop->originalControlHeader.State());
        ASSERT_EQ(harken::CommandQueue::OriginalControlDisposition::Settled, stop->originalControlHeader.ControlDisposition());
        ASSERT_TRUE(engine->timelineArms.Observe(stop->arm, &source));
        ASSERT_EQ(serviceFence + 1, source.armedCompletionSequence);
        harken::ImmediateLaneObservation lane{};
        ASSERT_TRUE(engine->immediateActionLane.Observe(calendar, &lane));
        ASSERT_FALSE(lane.committed);
        ASSERT_EQ(VN_OK, Vn_StopActionFiring(playFiring, 0));
        ASSERT_EQ(VN_OK, Vn_StopActionFiring(firing, 0));
        EXPECT_FALSE(engine->immediateActionLane.Observe(calendar, &lane) && lane.committed);
        VnActionFiringInfo playInfo{}, resetInfo{};
        playInfo.structSize = resetInfo.structSize = sizeof(playInfo);
        for (unsigned block = 0; block < 128; ++block) {
            engine->nullBackend.Pump(1);
            ASSERT_EQ(VN_OK, Vn_Update());
            ASSERT_EQ(VN_OK, Vn_QueryActionFiring(playFiring, &playInfo));
            ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &resetInfo));
            if (playInfo.state == VN_ACTION_FIRING_TERMINAL_RETAINED &&
                resetInfo.state == VN_ACTION_FIRING_TERMINAL_RETAINED) break;
        }
        ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, playInfo.state);
        ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, resetInfo.state);
        ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(playFiring));
        ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
        for (unsigned block = 0; block < 128 && (CaptureActionReclaimableOwners(*engine) != ownersBeforePlay ||
                CaptureActionPreparationOwners(*engine).occupiedQueueProgramBanks != banksBeforePlay); ++block) {
            engine->nullBackend.Pump(1);
            ASSERT_EQ(VN_OK, Vn_Update());
        }
        EXPECT_EQ(harken::Engine::OriginalQueueReplacementHolder::Phase::Empty, selected.phase);
        EXPECT_EQ(0u, engine->originalQueueReplacementCount);
        EXPECT_FALSE(engine->decisions.Contains(coordinator));
        EXPECT_FALSE(engine->immediateActionLane.Observe(calendar, &lane));
        for (const auto identity : groups) {
            harken::Plan03PageGroupView group{};
            EXPECT_FALSE(engine->timelinePool.ResolvePlan03GroupSliceProducer(identity, &group));
        }
        EXPECT_TRUE(engine->voices.ReleaseObserved(release));
        EXPECT_EQ(nullptr, engine->voices.Resolve(replacement));
        EXPECT_EQ(ownersBeforePlay, CaptureActionReclaimableOwners(*engine));
        EXPECT_EQ(banksBeforePlay, CaptureActionPreparationOwners(*engine).occupiedQueueProgramBanks);
        EXPECT_FALSE(engine->runtimeRecreateRequired);
        EXPECT_EQ(0u, engine->mixer.CommandProtocolViolationCount());
        return;
    }
    if (refuseCalendarPlacement) {
        struct CalendarPressure {
            harken::Engine& engine;
            harken::QueueInstanceToken queue;
            std::vector<harken::ImmediateLaneHandle> lanes;
            bool installed = false;
            ~CalendarPressure() {
                engine.immediateQueuePostC0PublishHookForTest = nullptr;
                engine.immediateQueuePostC0PublishContextForTest = nullptr;
                for (const auto lane : lanes) {
                    (void)engine.immediateActionLane.Cancel(lane);
                    (void)engine.immediateActionLane.Retire(lane, engine.mixer.BlocksRendered());
                }
            }
        } pressure{*engine, row.queueInstance};
        engine->immediateQueuePostC0PublishContextForTest = &pressure;
        engine->immediateQueuePostC0PublishHookForTest = +[](
            harken::Engine& actual, harken::EngineImmediateEntryAttempt& original, void* context) {
            auto& held = *static_cast<CalendarPressure*>(context);
            actual.immediateQueuePostC0PublishHookForTest = nullptr;
            auto& selected = actual.originalQueueReplacementHolders[held.queue.slot];
            ASSERT_EQ(harken::Engine::OriginalQueueReplacementHolder::Phase::Selected, selected.phase);
            harken::QueueInstanceTable::OriginalConditionalInitialClockBinding clock{};
            ASSERT_TRUE(selected.clock.CaptureInitialBinding(&clock));
            harken::TimelineTransactionProgramRef controller{};
            ASSERT_TRUE(actual.decisions.CaptureFrontierControlProgram(selected.decisions[0], &controller));
            // Reserve real private Lane demand beside the original C1's two events.
            // These scheduling inputs never publish or acquire audio authority.
            auto remaining = actual.immediateActionLane.MaxEventsPerQuantum() - 2u;
            ASSERT_GT(remaining, 0u);
            while (remaining != 0) {
                const auto count = std::min(remaining, actual.immediateActionLane.EventsPerAttempt());
                std::vector<harken::ImmediateLaneEvent> events(count);
                for (auto& event : events) event.event.program = controller;
                harken::ImmediateLaneHandle lane{};
                ASSERT_TRUE(actual.immediateActionLane.Reserve(original.root, {count, 0, 0, 1}, &lane));
                held.lanes.push_back(lane);
                ASSERT_TRUE(actual.immediateActionLane.Prepare(lane, events.data(), count));
                ASSERT_TRUE(actual.immediateActionLane.TryPlaceExactPrivate(
                    lane, clock.anchorFrame + selected.relativeFrame));
                remaining -= count;
            }
            held.installed = true;
        };
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_TRUE(pressure.installed);
        auto& selected = engine->originalQueueReplacementHolders[pressure.queue.slot];
        ASSERT_EQ(harken::Engine::OriginalQueueReplacementHolder::Phase::Selected, selected.phase);
        ASSERT_FALSE(selected.clockBound);
        ASSERT_TRUE(selected.sourceClockBound);
        const auto currentRender = row.renderHandle;
        const auto currentOccurrence = row.QueuePayload().queueCurrentOccurrence;
        const auto currentOwner = row.QueuePayload().queueCurrentCompletion.owner;
        harken::QueueInstanceTable::OriginalConditionalInitialClockBinding before{};
        ASSERT_TRUE(selected.clock.CaptureInitialBinding(&before));
        ASSERT_EQ(VN_OK, Vn_Update());
        EXPECT_EQ(harken::Engine::OriginalQueueReplacementHolder::Phase::Selected, selected.phase);
        EXPECT_FALSE(selected.clockBound);
        for (const auto lane : pressure.lanes) {
            ASSERT_TRUE(engine->immediateActionLane.Cancel(lane));
            ASSERT_TRUE(engine->immediateActionLane.Retire(lane, engine->mixer.BlocksRendered()));
        }
        pressure.lanes.clear();
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_EQ(harken::Engine::OriginalQueueReplacementHolder::Phase::Published, selected.phase);
        EXPECT_TRUE(selected.clockBound);
        EXPECT_TRUE(selected.oldSourceAborted);
        const auto oldFutureOwner = engine->ledger.OwnerForRender(oldSuccessor);
        ASSERT_TRUE(oldFutureOwner.live);
        harken::VoiceLedger::MonitorIdentity oldFutureIdentity{}, currentIdentity{};
        ASSERT_TRUE(engine->ledger.CaptureMonitorIdentity(oldFutureOwner.ledgerSlot, &oldFutureIdentity));
        EXPECT_EQ(selected.resetCause.request.key, oldFutureIdentity.controlCause.request.key);
        EXPECT_EQ(selected.resetCause.actionFiring, oldFutureIdentity.controlCause.actionFiring);
        EXPECT_EQ(selected.resetCause.executionOrdinal, oldFutureIdentity.controlCause.executionOrdinal);
        const auto currentLedgerOwner = engine->ledger.OwnerForRender(currentRender);
        ASSERT_TRUE(currentLedgerOwner.live);
        ASSERT_TRUE(engine->ledger.CaptureMonitorIdentity(currentLedgerOwner.ledgerSlot, &currentIdentity));
        EXPECT_FALSE(currentIdentity.controlCause.request.key.Valid());
        EXPECT_EQ(currentRender, row.renderHandle);
        EXPECT_EQ(currentOccurrence.slot, row.QueuePayload().queueCurrentOccurrence.slot);
        EXPECT_EQ(currentOccurrence.generation, row.QueuePayload().queueCurrentOccurrence.generation);
        EXPECT_TRUE(harken::SameCompletionOwner(currentOwner, row.QueuePayload().queueCurrentCompletion.owner));
        harken::QueueInstanceTable::OriginalConditionalInitialClockBinding after{};
        ASSERT_TRUE(selected.clock.CaptureInitialBinding(&after));
        EXPECT_EQ(before.anchorFrame, after.anchorFrame);
        EXPECT_EQ(before.sourceStartFrame, after.sourceStartFrame);
        EXPECT_EQ(before.installedAckSequence, after.installedAckSequence);
        EXPECT_FALSE(engine->runtimeRecreateRequired);
    }
    if (inspectOldProgram) {
        const auto* original = engine->OriginalQueueConditionalForService(row);
        if (original != nullptr) {
            ASSERT_EQ(oldBank, original->initialFuture.queueSuccessorProgramBank);
            ASSERT_TRUE(original->initialFutureBank.Valid());
            EXPECT_EQ(oldBank->Generation(), original->initialFutureBank.Generation());
        } else EXPECT_TRUE(engine->timelinePool.HasProgramReference({oldRuntime.generation, oldProgram}));
        EXPECT_EQ(oldRuntime.payloads, oldProgram->payloads);
        EXPECT_EQ(oldRuntime.generation, oldProgram->generation);
        EXPECT_EQ(oldPayload.target.occurrenceOrdinal, oldProgram->payloads[0].target.occurrenceOrdinal);
        EXPECT_EQ(0, std::memcmp(&oldPayload, &oldProgram->payloads[0], sizeof(oldPayload)));
        if (inspectRetirement) {
            auto& scratch = engine->actionQueueReplacementScratch[0];
            ASSERT_EQ(nullptr, scratch.programBank);
            scratch.programBank = oldBank;
            ASSERT_EQ(VN_OK, Vn_StopActionFiring(firing, 0));
            ASSERT_EQ(VN_OK, Vn_StopActionFiring(playFiring, 0));
            for (std::uint32_t block = 0; block < 32; ++block) {
                ASSERT_EQ(VN_OK, Vn_Update());
                engine->nullBackend.Pump(1);
            }
            ASSERT_TRUE(oldBank->occupied);
            ASSERT_FALSE(engine->OriginalQueueBankHasExternalOwners(*oldBank));
            EXPECT_FALSE(engine->timelinePool.HasProgramReference({oldRuntime.generation, oldProgram}));
            if (inspectOwners) {
                auto* freeOwner = engine->PrepareFreePlayableService();
                ASSERT_NE(nullptr, freeOwner);
                auto& owner = *freeOwner;
                ASSERT_EQ(harken::EnginePlayableStartPhase::Free, owner.phase);
                ASSERT_TRUE(owner.PrepareFeatureArrays());
                ASSERT_EQ(nullptr, owner.QueuePayload().queueCurrentProgramBank);
                owner.QueuePayload().queueCurrentProgramBank = oldBank;
                scratch.programBank = nullptr;
                engine->nullBackend.Pump(1);
                ASSERT_EQ(VN_OK, Vn_Update());
                EXPECT_TRUE(oldBank->occupied);
                scratch.programBank = oldBank;
                owner.QueuePayload().queueCurrentProgramBank = nullptr;
                engine->nullBackend.Pump(1);
                ASSERT_EQ(VN_OK, Vn_Update());
                EXPECT_TRUE(oldBank->occupied);
            }
            scratch.programBank = nullptr;
            const auto observed = engine->mixer.BlocksRendered();
            for (std::uint32_t update = 0; update < 3; ++update) ASSERT_EQ(VN_OK, Vn_Update());
            EXPECT_EQ(observed, engine->mixer.BlocksRendered());
            EXPECT_FALSE(oldBank->occupied);
        }
        return;
    }
    VnActionFiringHandle stopFiring = firing;
    if (deferred) {
        ASSERT_NE(0u, engine->actionDeferredRecords.LiveCount());
        for (std::uint32_t block = 0; block < 8 && row.QueuePayload().queueSuccessorRenderHandle == oldSuccessor; ++block) {
            ASSERT_EQ(VN_OK, Vn_Update());
            engine->nullBackend.Pump(1);
        }
        VnActionStepResult parent{};
        parent.structSize = sizeof(parent);
        ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &parent));
        if (availableBanks == 0) {
            EXPECT_EQ(VN_ACTION_STEP_FAILED, parent.state);
            EXPECT_EQ(VN_BACKPRESSURE, parent.result);
            VnActionFiringInfo settled{};
            settled.structSize = sizeof(settled);
            ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &settled));
            EXPECT_EQ(VN_ACTION_TERMINAL_CAPACITY, settled.terminalReason);
            EXPECT_EQ(0u, parent.childFiring);
            EXPECT_EQ(0u, engine->actionDeferredRecords.LiveCount());
            EXPECT_EQ(oldSuccessor, row.QueuePayload().queueSuccessorRenderHandle);
            EXPECT_FALSE(engine->runtimeRecreateRequired);
            for (const auto& event : harkentest::monitor::ReadActivityEvents(capture)) {
                EXPECT_NE(VN_MONITOR_FACT_STEP_EXECUTED, event.fact.fact.factKind);
            }
            EXPECT_EQ(VN_OK, Vn_MonitorCloseSession(capture));
            releaseHeldBanks();
            return;
        }
        ASSERT_NE(0u, parent.childFiring) << "state=" << parent.state << " result=" << parent.result
            << " blocks=" << engine->mixer.BlocksRendered() << " successor=" << row.QueuePayload().queueSuccessorRenderHandle
            << " oldSuccessor=" << oldSuccessor << " deferred=" << engine->actionDeferredRecords.LiveCount();
        stopFiring = parent.childFiring;
    }
    VnActionStepResult stopResult{};
    stopResult.structSize = sizeof(stopResult);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(stopFiring, 1, &stopResult));
    harken::MonitorQueueResetObservation resetObservation{};
    ASSERT_TRUE(engine->queueInstances.CaptureMonitorReset(row.queueInstance, &resetObservation));
    EXPECT_EQ(stopFiring, resetObservation.cause.actionFiring);
    EXPECT_EQ(0u, resetObservation.cause.executionOrdinal);
    EXPECT_TRUE(resetObservation.cause.request.key.Valid());
    EXPECT_EQ(harken::MonitorQueueResetObservation::Stage::Selected, resetObservation.stage);
    const auto replacementOwner = engine->ledger.OwnerForRender(row.QueuePayload().queueSuccessorRenderHandle);
    ASSERT_TRUE(replacementOwner.live);
    harken::VoiceLedger::MonitorIdentity replacementIdentity{};
    ASSERT_TRUE(engine->ledger.CaptureMonitorIdentity(replacementOwner.ledgerSlot, &replacementIdentity));
    EXPECT_EQ(resetObservation.cause.request.key, replacementIdentity.selectionCause.request.key);
    EXPECT_EQ(stopFiring, replacementIdentity.selectionCause.actionFiring);
    EXPECT_EQ(0u, replacementIdentity.selectionCause.executionOrdinal);
    EXPECT_FALSE(replacementIdentity.controlCause.request.key.Valid());
    harken::MonitorRequestContext originalPlayback{};
    ASSERT_TRUE(engine->playableInstances.CapturePlaybackRequest(row.rootInstance, &originalPlayback));
    EXPECT_EQ(originalPlayback.key, replacementIdentity.playbackRequest.key);
    EXPECT_EQ(VN_ACTION_STEP_ACTIVE, stopResult.state);
    EXPECT_EQ(1u, stopResult.remainingPlayableCount);
    EXPECT_EQ(1u, stopResult.capturedPlayableCount);
    EXPECT_NE(oldSuccessor, row.QueuePayload().queueSuccessorRenderHandle);
    EXPECT_TRUE(oldDecision.slot != row.QueueFiling().queueDecision.slot || oldDecision.generation != row.QueueFiling().queueDecision.generation);
    const auto inheritedVoice = std::find_if(engine->authoredStopResources.begin(),
        engine->authoredStopResources.end(), [&](const auto& resource) {
            return resource.committed && resource.installation.renderHandle == row.QueuePayload().queueSuccessorRenderHandle;
        });
    ASSERT_NE(engine->authoredStopResources.end(), inheritedVoice);
    const auto inheritedDecision = std::find_if(engine->authoredStopResources.begin(),
        engine->authoredStopResources.end(), [&](const auto& resource) {
            return resource.committed && resource.fence && resource.fence->decision.slot == row.QueueFiling().queueDecision.slot &&
                resource.fence->decision.generation == row.QueueFiling().queueDecision.generation;
        });
    ASSERT_NE(engine->authoredStopResources.end(), inheritedDecision);
    EXPECT_FALSE(engine->runtimeRecreateRequired);
    const auto stopFrame = engine->authoredStopRoots[inheritedVoice->operationSlot].operation->Identity().stopFrame;
    harken::EngineTimelineVoiceInstallIdentity installation{};
    ASSERT_TRUE(engine->CaptureTimelineVoiceInstallIdentity(inheritedVoice->installation.renderHandle, &installation));
    CheckCapturedStopAudioAndRetirement(*engine, root, inheritedVoice->installation.renderHandle,
        inheritedVoice->installation.releaseObserver, installation.onsetFrame, stopFrame);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(stopFiring, 1, &stopResult));
    EXPECT_EQ(VN_ACTION_STEP_SUCCEEDED, stopResult.state);
    EXPECT_EQ(0u, stopResult.remainingPlayableCount);
}

