static void CheckQueueBankAcrossRealRowReuse(bool transportReset, bool continuousReset = false) {
    harkentest::EngineSession session(harkentest::MakeNullConfig(8, 64, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    std::vector<float> first(2048, 0.25f);
    std::vector<float> second(2048, -0.25f);
    const auto firstPcm = harkentest::MonoDesc(first, 48000);
    const auto secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &secondPcm));
    CanonicalActionWorld image(engine->registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
    image.MakeImmediateSequenceQueuePlayAction();
    image.containers[2].queueCycle = harken::QueueCycleV1::Loop;
    image.world.identity.runtimeSemanticFingerprint = harken::ComputeCurrentWorldFingerprintV4(image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok, harken::InstallContainerWorldV1(*engine, image.world).status);
    VnEmitterHandle emitter = 0;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&emitter));
    auto desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    desc.emitter = emitter;
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    auto& row = engine->playableServices[0];
    const auto root = row.rootInstance;
    const auto originalRender = row.renderHandle;
    if (continuousReset) {
        auto resetDesc = desc;
        resetDesc.actionId = harkentest::ObjectId(49);
        for (std::uint32_t iteration = 0; iteration < 3; ++iteration) {
            SCOPED_TRACE(iteration);
            bool ready = false;
            harken::QueueInstanceSnapshot snapshot{};
            for (std::uint32_t block = 0; block < 128; ++block) {
                ASSERT_TRUE(engine->queueInstances.Capture(row.queueInstance, &snapshot));
                ready = !snapshot.resetPending && !row.queueArrivalDecision.Valid() && row.queueContinuationPrepared;
                if (ready) break;
                engine->nullBackend.Pump(1);
                ASSERT_EQ(VN_OK, Vn_Update());
            }
            const auto& native = engine->originalQueueReplacementHolders[row.queueInstance.slot];
            harken::QueueInstanceTable::OriginalConditionalInitialClockBinding nativeClock{};
            const bool nativeClockAvailable = native.clock.CaptureInitialBinding(&nativeClock);
            const auto* originalAttempt = native.originalAttempt;
            harken::ImmediateLaneObservation originalLane{};
            const bool originalLaneObserved = originalAttempt != nullptr &&
                engine->immediateActionLane.Observe(originalAttempt->lane, &originalLane);
            harken::TimelineArmObservation actualCurrent{};
            const bool currentObserved = engine->timelineArms.Observe(row.arm, &actualCurrent);
            ASSERT_TRUE(ready) << " originalObserved=" << originalLaneObserved
                << " originalActive=" << (originalAttempt != nullptr && originalAttempt->active)
                << " abort=" << (originalAttempt != nullptr && originalAttempt->producerAbortPending)
                << " failureCapacity=" << (originalAttempt != nullptr && originalAttempt->producerFailureCapacity)
                << " laneCommitted=" << originalLane.committed << " laneApplied=" << originalLane.applied
                << " laneMissed=" << originalLane.missed << " laneCancelled=" << originalLane.cancelled
                << " initialEntry=" << (originalAttempt == nullptr ? 0 : originalAttempt->initialEntryFrame)
                << " rowPending=" << row.pendingImmediateEntry << " timingPending=" << row.queueTimingPending
                << " rowPhase=" << static_cast<int>(row.phase) << " currentObserved=" << currentObserved
                << " currentState=" << static_cast<int>(actualCurrent.state)
                << " ack=" << actualCurrent.armedCompletionSequence << " start=" << actualCurrent.startedBlockSequence
                << " nativePhase=" << static_cast<int>(native.phase)
                << " clockAvailable=" << nativeClockAvailable << " firstS=" << nativeClock.anchorFrame
                << " clockBound=" << native.clockBound << " frontierCount=" << native.frontierBoundCount
                << " conditionalBound=" << native.conditionalBound << " calendarPinned=" << native.calendarPinned
                << " sourceBound=" << native.sourceClockBound << " sourcePublished=" << native.sourceArmPublished
                << " oldAborted=" << native.oldSourceAborted << " recreate=" << engine->runtimeRecreateRequired
                << " now=" << engine->mixer.BlocksRendered() * engine->config.blockFrames
                << " window=" << engine->timelinePool.WindowStartFrame()
                << " cutoff=" << engine->timelinePool.PublishCutoffFrame()
                << " boundary=" << row.QueuePayload().queueCompletionFrame
                << " committed=" << row.QueueFiling().queueDecisionCommitted
                << " arrival=" << row.queueArrivalDecision.Valid()
                << " pendingReset=" << snapshot.resetPending
                << " activation=" << static_cast<int>(snapshot.pendingActivation);
            ASSERT_EQ(0u, row.QueuePayload().queueAbortedSuccessorOccurrence.generation);
            const auto source = row.renderHandle;
            const auto currentOccurrence = row.QueuePayload().queueCurrentOccurrence;
            const auto currentOwner = row.QueuePayload().queueCurrentCompletion.owner;
            const auto* const currentProgress = engine->timelineOccurrences.CompletionProgressOf(currentOccurrence);
            const bool originalCurrent = harken::Engine::ResolveOriginalSingleOccurrenceBaseline(
                engine, engine->timelineOccurrences, currentOccurrence) != nullptr;
            harken::DecisionCommittedSnapshot beforeCurrentDecision{};
            const bool currentWasCommitted = engine->decisions.CaptureCommitted(
                currentOwner.singleDecision, &beforeCurrentDecision);
            auto* const replacedBank = row.QueueFiling().queueSuccessorProgramBank;
            const auto replacedBody = replacedBank == nullptr ? nullptr :
                std::make_unique<harken::EngineQueueProgramBankBody>(*replacedBank);
            VnActionFiringHandle resetFiring = 0;
            if (iteration == 1u && originalCurrent) {
                const auto originalCompletion = row.QueuePayload().queueCurrentCompletion;
                const auto beforeRefusal = CaptureActionPreparationOwners(*engine);
                row.QueuePayload().queueCurrentCompletion.progressBaselineOutputFrames ^= 1u;
                EXPECT_EQ(VN_BACKPRESSURE, Vn_PostAction(&resetDesc, &resetFiring));
                row.QueuePayload().queueCurrentCompletion = originalCompletion;
                EXPECT_EQ(0u, resetFiring);
                ExpectActionPreparationOwnersUnchanged(*engine, beforeRefusal);
                ASSERT_FALSE(engine->runtimeRecreateRequired);
            }
            const auto acceptedReset = Vn_PostAction(&resetDesc, &resetFiring);
            const auto* currentInstall = engine->ResolvePlayableServiceVoice(row);
            ASSERT_NE(nullptr, currentInstall);
            ASSERT_EQ(VN_OK, acceptedReset)
                << " now=" << engine->mixer.BlocksRendered() * engine->config.blockFrames
                << " window=" << engine->timelinePool.WindowStartFrame()
                << " cutoff=" << engine->timelinePool.PublishCutoffFrame()
                << " boundary=" << row.QueuePayload().queueCompletionFrame
                << " source=" << currentInstall->Facts().soundId
                << " prepared=" << row.queueContinuationPrepared
                << " sameKey=" << row.QueueFiling().queueSameProgramKey;
            EXPECT_EQ(root, row.rootInstance);
            EXPECT_EQ(source, row.renderHandle);
            if (originalCurrent) {
                EXPECT_EQ(currentOccurrence.slot, row.QueuePayload().queueCurrentOccurrence.slot);
                EXPECT_EQ(currentOccurrence.generation, row.QueuePayload().queueCurrentOccurrence.generation);
                EXPECT_EQ(currentProgress, engine->timelineOccurrences.CompletionProgressOf(currentOccurrence));
                EXPECT_TRUE(harken::SameCompletionOwner(currentOwner, row.QueuePayload().queueCurrentCompletion.owner));
                harken::CompletionOwnerRef actualOwner{};
                ASSERT_TRUE(engine->timelineOccurrences.CaptureCompletionOwner(currentOccurrence, &actualOwner));
                EXPECT_TRUE(harken::SameCompletionOwner(currentOwner, actualOwner));
                if (currentWasCommitted) {
                    harken::DecisionCommittedSnapshot currentDecision{};
                    ASSERT_TRUE(engine->decisions.CaptureCommitted(currentOwner.singleDecision, &currentDecision));
                    EXPECT_NE(harken::AudioGroupState::Invalidated, currentDecision.audioState);
                } else EXPECT_TRUE(engine->decisions.IsOpen(currentOwner.singleDecision));
            }
            if (replacedBank != nullptr) ExpectFrozenQueueBank(*replacedBank, *replacedBody);
            ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(resetFiring));
        }
    }
    bool promoted = false;
    bool heardSecond = false;
    for (std::uint32_t block = 0; block < 128 && (!promoted || !heardSecond); ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        const auto* currentInstall = engine->ResolvePlayableServiceVoice(row);
        promoted = row.renderHandle != originalRender && currentInstall != nullptr &&
            currentInstall->Facts().soundId == CanonicalActionWorld::kSecondSound;
        const auto* output = engine->nullBackend.LastBlock();
        for (std::uint32_t sample = 0; sample < engine->config.blockFrames * engine->nullBackend.Channels(); ++sample)
            heardSecond = heardSecond || output[sample] < -0.01f;
    }
    ASSERT_TRUE(promoted);
    ASSERT_TRUE(heardSecond);
    auto* const oldBank = row.QueuePayload().queueCurrentProgramBank;
    ASSERT_NE(nullptr, oldBank);
    const auto originalBank = std::make_unique<harken::EngineQueueProgramBankBody>(*oldBank);
    const auto resetEpoch = engine->timelinePool.Epoch();
    const auto resetFrame = engine->mixer.BlocksRendered() * engine->config.blockFrames;
    auto resetStatus = harken::RuntimeTransportResetStatus::Backpressure;
    if (transportReset) {
        resetStatus = harken::BeginRuntimeTransportReset(*engine, resetFrame);
        ASSERT_EQ(harken::RuntimeTransportResetStatus::Backpressure, resetStatus);
    } else {
        ASSERT_EQ(harken::PlayableControlStatus::Ok, harken::StopPlayable(*engine, root, 0));
    }
    for (std::uint32_t block = 0; block < 64 && row.phase != harken::EnginePlayableStartPhase::Free; ++block) {
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        if (transportReset && row.phase != harken::EnginePlayableStartPhase::Free) {
            resetStatus = harken::BeginRuntimeTransportReset(*engine, resetFrame);
            ASSERT_NE(harken::RuntimeTransportResetStatus::RuntimeRecreateRequired, resetStatus);
        }
    }
    ASSERT_EQ(harken::EnginePlayableStartPhase::Free, row.phase);
    ASSERT_FALSE(engine->playableInstances.Classify(root).live);
    ASSERT_EQ(nullptr, row.QueuePayload().queueCurrentProgramBank);
    ExpectFrozenQueueBank(*oldBank, *originalBank);
    if (transportReset) {
        resetStatus = harken::BeginRuntimeTransportReset(*engine, resetFrame);
        ASSERT_EQ(harken::RuntimeTransportResetStatus::Complete, resetStatus);
        ASSERT_GT(engine->timelinePool.Epoch(), resetEpoch);
        ExpectFrozenQueueBank(*oldBank, *originalBank);
    }
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    harken::ScheduledEventInput heldEvent{};
    heldEvent.executeFrame = engine->timelinePool.WindowEndFrame() - 1u;
    harken::TransactionRequest heldRequest{};
    heldRequest.transactionId = UINT64_MAX - 1u;
    heldRequest.transportEpoch = engine->timelinePool.Epoch();
    heldRequest.program = oldBank->schedules[0].runtimeProgram;
    heldRequest.events = &heldEvent;
    heldRequest.eventCount = 1;
    harken::PreparedTransactionBatch heldReference{};
    struct TemporaryBankOwner {
        harken::EngineQueueProgramBank** slot = nullptr;
        ~TemporaryBankOwner() { if (slot != nullptr) *slot = nullptr; }
    } temporaryOwner;
    if (transportReset) {
        // A prepared transaction freezes the whole window. Retain the bank
        // through an existing scratch owner until the new epoch catches up.
        auto& scratch = engine->actionQueueReplacementScratch[0];
        ASSERT_EQ(nullptr, scratch.programBank);
        scratch.programBank = oldBank;
        temporaryOwner.slot = &scratch.programBank;
        ASSERT_EQ(VN_OK, Vn_Update());
        ExpectFrozenQueueBank(*oldBank, *originalBank);
        const auto initialFrontier = engine->timelinePool.ConsumerFrontier().load(std::memory_order_acquire);
        const auto initialRendered = engine->mixer.BlocksRendered();
        const auto initialDebt = initialRendered > initialFrontier ? initialRendered - initialFrontier : 0u;
        for (std::uint64_t step = 0; step <= initialDebt; ++step) {
            const auto frontier = engine->timelinePool.ConsumerFrontier().load(std::memory_order_acquire);
            if (frontier >= engine->mixer.BlocksRendered()) break;
            engine->nullBackend.Pump(1);
            ASSERT_EQ(VN_OK, Vn_Update());
            ASSERT_GT(engine->timelinePool.ConsumerFrontier().load(std::memory_order_acquire), frontier);
            ASSERT_TRUE(oldBank->occupied);
            ExpectFrozenQueueBank(*oldBank, *originalBank);
        }
        ASSERT_GE(engine->timelinePool.ConsumerFrontier().load(std::memory_order_acquire),
            engine->mixer.BlocksRendered());
    }
    ASSERT_EQ(harken::ReserveRefusal::None, engine->timelinePool.PrepareTransactionBatch(
        &heldRequest, 1, engine->timelinePool.PublishCutoffFrame(), &heldReference));
    ASSERT_TRUE(engine->timelinePool.HasProgramReference(heldRequest.program));
    if (temporaryOwner.slot != nullptr) {
        *temporaryOwner.slot = nullptr;
        temporaryOwner.slot = nullptr;
    }
    VnActionFiringHandle replacementFiring = 0;
    const auto replacementResult = Vn_PostAction(&desc, &replacementFiring);
    ASSERT_EQ(VN_OK, replacementResult)
        << " B=" << engine->mixer.BlocksRendered()
        << " F=" << engine->timelinePool.ConsumerFrontier().load(std::memory_order_acquire)
        << " cutoff=" << engine->timelinePool.PublishCutoffFrame()
        << " window=" << engine->timelinePool.WindowStartFrame()
        << " end=" << engine->timelinePool.WindowEndFrame()
        << " target=" << std::max(engine->timelinePool.PublishCutoffFrame(),
            (engine->mixer.BlocksRendered() + std::max<std::uint64_t>(1u,
                engine->timelinePool.PublishLeadQuanta())) * engine->config.blockFrames)
        << " frontierStamp=" << engine->timelinePool.PageStamp(
            engine->timelinePool.ConsumerFrontier().load(std::memory_order_acquire))
        << " resetFrame=" << resetFrame;
    ASSERT_NE(root, row.rootInstance);
    ASSERT_NE(harken::EnginePlayableStartPhase::Free, row.phase);
    auto* const replacementBank = row.QueuePayload().queueCurrentProgramBank;
    ASSERT_NE(nullptr, replacementBank);
    ASSERT_NE(oldBank, replacementBank);
    engine->nullBackend.Pump(1);
    ASSERT_EQ(VN_OK, Vn_Update());
    ASSERT_FALSE(row.pendingImmediateEntry);
    ExpectFrozenQueueBank(*oldBank, *originalBank);
    const auto replacementBody = std::make_unique<harken::EngineQueueProgramBankBody>(*replacementBank);
    for (std::uint32_t block = 0; block < 3; ++block) {
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_TRUE(engine->timelinePool.HasProgramReference(heldRequest.program));
        ExpectFrozenQueueBank(*oldBank, *originalBank);
        ExpectFrozenQueueBank(*replacementBank, *replacementBody);
    }
    ASSERT_TRUE(engine->timelinePool.CancelPreparedTransactionBatch(&heldReference));
    ASSERT_EQ(VN_OK, Vn_Update());
    const auto retiredAt = engine->mixer.BlocksRendered();
    ASSERT_EQ(VN_OK, Vn_Update());
    EXPECT_EQ(retiredAt, engine->mixer.BlocksRendered());
    EXPECT_FALSE(oldBank->occupied);
    ExpectFrozenQueueBank(*replacementBank, *replacementBody);
    ASSERT_EQ(VN_OK, Vn_StopActionFiring(replacementFiring, 0));
    for (std::uint32_t block = 0; block < 64 && row.phase != harken::EnginePlayableStartPhase::Free; ++block) {
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
    }
    EXPECT_EQ(harken::EnginePlayableStartPhase::Free, row.phase);
    EXPECT_EQ(0u, engine->queueInstances.LiveCount());
    EXPECT_EQ(0u, engine->decisions.LiveCount());
    EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(replacementFiring));
    EXPECT_FALSE(engine->runtimeRecreateRequired);
}

