TEST(ActionFiringApi,
     ImmediateNestedQueueOwnerFailureRetriesBlockedQueueAndVoiceCleanup) {
    (void)Vn_Term();
    harkentest::EngineSession session(
        harkentest::MakeNullConfig(8, 64, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> first(64, 0.25f);
    std::vector<float> second(128, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound,
                                    &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound,
                                    &secondPcm));

    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound)
            .contentRevision);
    image.MakeImmediateSequenceQueuePlayAction();
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    const auto playableBaseline = engine->playableInstances.LiveCount();
    const auto containerBaseline = engine->containerPlayback.LiveCount();
    const auto queueBaseline = engine->queueInstances.LiveCount();
    const auto voiceBaseline = engine->voices.ActiveCount();
    const auto armBaseline = engine->timelineArms.LiveCount();
    const auto decisionBaseline = engine->decisions.LiveCount();
    const auto selectionRowBaseline = engine->selectionMemory.RowCount();
    const auto selectionDeltaBaseline =
        engine->selectionMemory.FreeDeltaCount();
    const auto pageGroupBaseline =
        engine->timelinePool.CaptureLivePlan03Groups(nullptr, 0);
    VnEmitterHandle emitter = 0;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&emitter));
    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    desc.emitter = emitter;
    engine->forceActionFinalOwnerCommitFailureForTest = true;
    engine->forceActionTimelineVoiceOwnerRollbackFailureForTest = true;

    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    ASSERT_NE(0u, firing);
    EXPECT_TRUE(engine->runtimeRecreateRequired);
    EXPECT_FALSE(engine->forceActionFinalOwnerCommitFailureForTest);
    EXPECT_FALSE(engine->forceActionTimelineVoiceOwnerRollbackFailureForTest);
    EXPECT_EQ(1u, engine->actionQueueInstanceOwnerCancelAttemptsForTest);
    EXPECT_EQ(3u,
              engine->actionTimelineVoiceOwnerRollbackAttemptsForTest);
    EXPECT_EQ(playableBaseline, engine->playableInstances.LiveCount());
    EXPECT_EQ(containerBaseline, engine->containerPlayback.LiveCount());
    EXPECT_EQ(queueBaseline, engine->queueInstances.LiveCount());
    EXPECT_EQ(voiceBaseline, engine->voices.ActiveCount());
    EXPECT_EQ(armBaseline, engine->timelineArms.LiveCount());
    EXPECT_EQ(decisionBaseline, engine->decisions.LiveCount());
    EXPECT_EQ(selectionRowBaseline, engine->selectionMemory.RowCount());
    EXPECT_EQ(selectionDeltaBaseline,
              engine->selectionMemory.FreeDeltaCount());
    EXPECT_EQ(pageGroupBaseline,
              engine->timelinePool.CaptureLivePlan03Groups(nullptr, 0));
    for (std::uint64_t frame = engine->timelinePool.WindowStartFrame();
         frame < engine->timelinePool.WindowEndFrame();
         frame += engine->timelinePool.QuantumFrames()) {
        SCOPED_TRACE(frame);
        std::uint32_t page = 0;
        ASSERT_TRUE(engine->timelinePool.PageForFrame(frame, &page));
        const auto* header = engine->timelinePool.Page(page);
        ASSERT_NE(nullptr, header);
        if (header->frozen) {
            continue;
        }
        EXPECT_EQ(harken::Plan03GroupReserveStatus::Committed,
                  engine->timelinePool.PreflightPlan03GroupSlices(
                      frame,
                      engine->timelinePool.MaxPlan03GroupHeadersPerPage()));
    }
    for (std::uint32_t index = 0;
         index < engine->actionPlayScratch.size(); ++index) {
        if (!engine->actionPlayScratch.IsConstructed(index)) continue;
        SCOPED_TRACE(index);
        const auto& scratch = engine->actionPlayScratch[index];
        EXPECT_FALSE(scratch.prepared)
            << "phase=" << static_cast<int>(scratch.storage.phase)
            << " ledger=" << scratch.storage.ownerLedger.UnresolvedCount()
            << " tree=" << scratch.playableTreeExecutor.Committed()
            << " currentOccurrence=" << scratch.queueCurrentOccurrencePrepared
            << " currentPins=" << scratch.queueCompletionOwnerPinned
            << " currentMutation=" << scratch.queueCompletionMutationCount
            << " successorPins=" << scratch.queueSuccessorCompletionOwnerPinned
            << " successorMutation=" << scratch.queueSuccessorCompletionMutationCount;
        EXPECT_EQ(nullptr, scratch.row);
        EXPECT_EQ(0u, scratch.playableTreeExecutor.OwnerTokenCount());
    }

    VnActionStepResult step{};
    step.structSize = sizeof(step);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &step));
    EXPECT_EQ(VN_ACTION_STEP_FAILED, step.state);
    EXPECT_EQ(VN_RUNTIME_RECREATE_REQUIRED, step.result);
    EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    ASSERT_EQ(VN_OK, Vn_DestroyEmitter(emitter));
}

TEST(ActionFiringApi,
     DelayedPlayIgnoresActionScratchOverwrittenAfterAdmission) {
    (void)Vn_Term();
    harkentest::EngineSession session(
        harkentest::MakeNullConfig(4, 256, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> samples(4096, 0.25f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision);
    image.MakeDelayedSoundPlayAction(DelayNanosecondsForTargetFrame(
        *engine, engine->timelinePool.WindowEndFrame()));
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle delayedFiring = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &delayedFiring));

    desc.actionId = image.actions[0].actionStableId;
    VnActionFiringHandle overwritingFiring = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &overwritingFiring));
    ASSERT_NE(nullptr, engine->actionFiringPlanScratch[0].action);
    ASSERT_EQ(image.actions[0].actionStableId,
              engine->actionFiringPlanScratch[0].action->actionStableId);

    DrainActionDeferred(engine);
    VnActionStepResult delayed{};
    delayed.structSize = sizeof(delayed);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(delayedFiring, 0, &delayed));
    EXPECT_EQ(VN_ACTION_STEP_ACTIVE, delayed.state);
    EXPECT_EQ(image.actions[9].actionStableId, delayed.ownerActionId);
    EXPECT_NE(0u, delayed.producedPlayableInstance);
    EXPECT_EQ(VN_IN_USE, Vn_ReleaseActionFiring(delayedFiring));
    EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(overwritingFiring));
}

