TEST(ActionFiringApi,
     ImmediateAndDelayedPlayCountsTrackOnlyCommittedInstances) {
    (void)Vn_Term();
    harkentest::EngineSession session(
        harkentest::MakeNullConfig(4, 256, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> samples(4096, 0.25f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision);
    image.MakeImmediateSoundPlayAction();
    image.steps[12] = image.steps[11];
    image.steps[13] = image.steps[11];
    image.steps[13].authoredEventIndex = 1;
    SetAbsoluteTime(&image.steps[13].delay,
                    DelayNanosecondsForTargetFrame(
                        *engine, engine->timelinePool.WindowEndFrame()));
    image.actions[9].steps = &image.steps[12];
    image.actions[9].stepCount = 2;
    image.actions[9].directFeatureMask = 1;
    image.actions[9].transitiveFeatureMask = 1;
    image.actions[9].expandedStepOccurrenceCount = 2;
    image.actions[9].programSemanticFingerprint =
        harken::ComputeActionProgramFingerprintV1(image.actions[9]);
    image.world.identity.runtimeSemanticFingerprint =
        harken::ComputeCurrentWorldFingerprintV4(image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));

    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
    EXPECT_EQ(VN_ACTION_FIRING_ACTIVE, info.state);
    EXPECT_EQ(1u, info.livePlayableCount);

    DrainActionDeferred(engine);
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
    EXPECT_EQ(VN_ACTION_FIRING_ACTIVE, info.state);
    EXPECT_EQ(2u, info.livePlayableCount);

    VnActionStepResult immediate{};
    immediate.structSize = sizeof(immediate);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &immediate));
    VnActionStepResult delayed{};
    delayed.structSize = sizeof(delayed);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 1, &delayed));
    ASSERT_EQ(VN_ACTION_STEP_ACTIVE, immediate.state);
    ASSERT_EQ(VN_ACTION_STEP_ACTIVE, delayed.state);
    ASSERT_TRUE(engine->actionFirings.CompletePlayable(
        firing, immediate.executionOrdinal, VN_OK,
        harken::ActionTerminalReason::None));
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
    EXPECT_EQ(VN_ACTION_FIRING_ACTIVE, info.state);
    EXPECT_EQ(1u, info.livePlayableCount);

    ASSERT_TRUE(engine->actionFirings.CompletePlayable(
        firing, delayed.executionOrdinal, VN_OK,
        harken::ActionTerminalReason::None));
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
    EXPECT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
    EXPECT_EQ(0u, info.livePlayableCount);
    EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
}

TEST(ActionFiringApi, DelayedStopCapturesTheEarlierPlayAtAdmission) {
    (void)Vn_Term();
    harkentest::EngineSession session(
        harkentest::MakeNullConfig(2, 256, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> samples(4096, 0.25f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision);
    image.MakeImmediatePlayThenStopAction(
        harken::ActionTargetKindV1::Sound);
    SetAbsoluteTime(&image.steps[12].delay,
                    DelayNanosecondsForTargetFrame(
                        *engine, engine->timelinePool.WindowEndFrame()));
    image.actions[9].directFeatureMask = 1;
    image.actions[9].transitiveFeatureMask = 1;
    image.actions[9].programSemanticFingerprint =
        harken::ComputeActionProgramFingerprintV1(image.actions[9]);
    image.world.identity.runtimeSemanticFingerprint =
        harken::ComputeCurrentWorldFingerprintV4(image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle firing = 0;
    engine->authoredStopResources.SetCommitPageLimitForTests(0);
    EXPECT_EQ(VN_BACKPRESSURE, Vn_PostAction(&desc, &firing));
    EXPECT_EQ(0u, firing);
    EXPECT_EQ(0u, engine->actionFirings.LiveCount());
    EXPECT_EQ(0u, engine->playableInstances.LiveCount());
    EXPECT_EQ(0u, engine->actionDeferredRecords.LiveCount());
    engine->authoredStopResources.SetCommitPageLimitForTests(SIZE_MAX);
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    engine->authoredStopResources.SetCommitPageLimitForTests(0);
    ASSERT_EQ(1u, engine->playableInstances.LiveCount());
    ASSERT_EQ(1u, engine->actionDeferredRecords.LiveCount());

    harken::ActionDeferredRecordToken recordToken{};
    harken::ActionDeferredRecord record{};
    harken::ActionDeferredRecordState recordState{};
    ASSERT_TRUE(engine->actionDeferredRecords.CaptureAt(
        0, &recordToken, &record, &recordState));
    EXPECT_NE(0u, record.rootPlayable);
    EXPECT_NE(0u, record.rootScheduleEpoch);
    EXPECT_TRUE(engine->playableInstances.ValidateStamp(
        record.rootPlayable, record.rootScheduleEpoch));

    VnActionStepResult stop{};
    stop.structSize = sizeof(stop);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 1, &stop));
    EXPECT_EQ(VN_ACTION_STEP_AWAITING_MATERIALIZATION, stop.state);

    DrainActionDeferred(engine);
    EXPECT_EQ(0u, engine->actionDeferredRecords.LiveCount());
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 1, &stop));
    EXPECT_EQ(VN_ACTION_STEP_ACTIVE, stop.state);
    EXPECT_EQ(1u, stop.capturedPlayableCount);
    EXPECT_EQ(1u, stop.remainingPlayableCount);
    EXPECT_EQ(VN_IN_USE, Vn_ReleaseActionFiring(firing));
}

