TEST(ActionFiringApi,
     DestroyEmitterCancelsOnlyExactGenerationHeldDelayedSetValue) {
    (void)Vn_Term();
    harkentest::EngineSession session(harkentest::MakeNullConfig());
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    CanonicalActionWorld image;
    image.MakeDelayedSetValueAction(1000000000, true);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&desc.emitter));
    const VnEmitterHandle predecessor = desc.emitter;
    VnActionFiringHandle predecessorFiring = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &predecessorFiring));
    ASSERT_EQ(VN_OK, Vn_DestroyEmitter(predecessor));
    EXPECT_EQ(0u, engine->actionDeferredRecords.LiveCount());
    EXPECT_EQ(0u,
              engine->actionFirings.OwnedDeferredCount(predecessorFiring));

    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&desc.emitter));
    ASSERT_EQ(static_cast<std::uint32_t>(predecessor),
              static_cast<std::uint32_t>(desc.emitter));
    ASSERT_NE(predecessor, desc.emitter);
    VnActionFiringHandle successorFiring = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &successorFiring));
    ASSERT_EQ(1u, engine->actionDeferredRecords.LiveCount());
    EXPECT_EQ(VN_STALE_HANDLE, Vn_DestroyEmitter(predecessor));
    EXPECT_EQ(1u, engine->actionDeferredRecords.LiveCount());
    EXPECT_EQ(1u, engine->actionFirings.OwnedDeferredCount(successorFiring));

    ASSERT_EQ(VN_OK, Vn_DestroyEmitter(desc.emitter));
    EXPECT_EQ(0u, engine->actionDeferredRecords.LiveCount());
    EXPECT_EQ(0u, engine->timelineDeferred.Count());
    EXPECT_EQ(0u, engine->actionFirings.OwnedDeferredCount(successorFiring));
    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(predecessorFiring, &info));
    EXPECT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
    EXPECT_EQ(VN_ACTION_TERMINAL_TARGET_GONE, info.terminalReason);
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(successorFiring, &info));
    EXPECT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
    EXPECT_EQ(VN_ACTION_TERMINAL_TARGET_GONE, info.terminalReason);
    EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(predecessorFiring));
    EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(successorFiring));
}

