TEST(ActionFiringApi,
     ImmediateSoundPlayServicesUnpublishedDebtBeforeTheNextGameUpdate) {
    harkentest::EngineSession session(harkentest::MakeNullConfig(8, 256, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    std::vector<float> samples(48000, 0.02f);
    const auto pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
    CanonicalActionWorld image(engine->registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision);
    image.MakeImmediateSoundPlayAction();
    ASSERT_EQ(harken::WorldInstallStatus::Ok, harken::InstallContainerWorldV1(*engine, image.world).status);
    ASSERT_EQ(VN_OK, Vn_Update());
    // A 30 Hz game can submit a trigger before its next Update, seven audio
    // blocks after the prior pump. Unpublished empty debt is not exhaustion.
    engine->nullBackend.Pump(7);
    const auto rendered = engine->mixer.BlocksRendered();
    const auto frontier = engine->timelinePool.ConsumerFrontier().load();
    ASSERT_LT(engine->timelinePool.PublishedEmptyPrefixEnd(frontier, rendered), rendered);
    auto desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    ASSERT_NE(0u, firing);
    const auto& row = engine->playableServices[0];
    const auto arm = row.arm;
    const auto render = row.renderHandle;
    const auto postStart = row.startFrame;
    ASSERT_GT(postStart / 256 + 1u, rendered);
    bool observed = false;
    for (unsigned block = 0; block < 16 && !observed; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        harken::TimelineArmObservation onset{};
        observed = engine->timelineArms.Observe(arm, &onset) && onset.startedBlockSequence != 0;
        if (observed) {
            EXPECT_GE(row.startFrame, postStart);
            EXPECT_EQ(row.startFrame / 256 + 1u,
                      onset.startedBlockSequence);
        }
    }
    ASSERT_TRUE(observed);
    ASSERT_NE(nullptr, engine->voices.Resolve(render));
    EXPECT_FALSE(engine->voices.Resolve(render)->timelineGated);
    EXPECT_GT(harkentest::Peak(engine->nullBackend.LastBlock(), 512), 0.001f);
    EXPECT_FALSE(engine->runtimeRecreateRequired);
}

TEST(ActionFiringApi,
     ImmediateSoundPlayAcceptsSecondLaneAcrossLiveVoicePageDebt) {
    (void)Vn_Term();
    harkentest::EngineSession session(harkentest::MakeNullConfig());
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> samples(1'000'000, 0.25f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision);
    image.MakeImmediateSoundPlayAction();
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    ASSERT_EQ(VN_OK, Vn_Update());
    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle firstFiring = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firstFiring));
    ASSERT_NE(0u, firstFiring);

    engine->nullBackend.Pump(256);
    ASSERT_GT(engine->mixer.BlocksRendered() * engine->config.blockFrames,
              engine->timelinePool.WindowEndFrame());
    ASSERT_NE(nullptr,
              engine->voices.Resolve(engine->playableServices[0].renderHandle));
    const std::uint64_t windowEndBefore =
        engine->timelinePool.WindowEndFrame();
    const auto originalRender = engine->playableServices[0].renderHandle;
    const auto voiceCountBefore = engine->voices.ActiveCount();

    VnActionFiringHandle secondFiring = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &secondFiring));
    ASSERT_NE(0u, secondFiring);
    // The existing source remains owned while the second lane cohort is accepted.
    EXPECT_GE(engine->timelinePool.WindowEndFrame(), windowEndBefore);
    EXPECT_LT(engine->timelinePool.WindowEndFrame(),
              engine->mixer.BlocksRendered() * engine->config.blockFrames);
    EXPECT_NE(nullptr, engine->voices.Resolve(originalRender));
    EXPECT_EQ(voiceCountBefore + 1u, engine->voices.ActiveCount());
    const auto secondIt = std::find_if(engine->playableServices.begin(),
        engine->playableServices.end(), [secondFiring](const auto& candidate) {
            return candidate.InvocationValid() &&
                candidate.Invocation().actionFiring == secondFiring;
        });
    ASSERT_NE(engine->playableServices.end(), secondIt);
    auto* secondRow = &*secondIt;
    ASSERT_TRUE(secondRow->pendingImmediateEntry);
    const auto secondArm = secondRow->arm;
    engine->nullBackend.Pump(1);
    ASSERT_EQ(VN_OK, Vn_Update());
    ASSERT_LT(engine->timelinePool.WindowEndFrame(), secondRow->startFrame);
    bool secondStarted = false;
    for (std::uint32_t block = 0; block < 16 && !secondStarted; ++block) {
        engine->nullBackend.Pump(1);
        harken::TimelineArmObservation observation{};
        secondStarted = engine->timelineArms.Observe(secondArm, &observation) &&
            observation.startedBlockSequence != 0;
        if (secondStarted)
            EXPECT_EQ(secondRow->startFrame / engine->config.blockFrames + 1u,
                      observation.startedBlockSequence);
    }
    EXPECT_TRUE(secondStarted);
    EXPECT_LT(engine->timelinePool.WindowEndFrame(), secondRow->startFrame);
}

TEST(ActionFiringApi, GlobalCooldownSuppressesUntilItsExclusiveEndFrame) {
    (void)Vn_Term();
    harkentest::EngineSession session(
        harkentest::MakeNullConfig(8, 256, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> samples(4096, 0.25f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision);
    image.MakeImmediateSoundPlayAction();
    image.SetImmediateSoundPlayCooldown(5333333);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle first = 0;
    VnActionFiringHandle suppressed = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &first));
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &suppressed));

    VnActionStepResult step{};
    step.structSize = sizeof(step);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(suppressed, 0, &step));
    EXPECT_EQ(VN_ACTION_STEP_SUPPRESSED, step.state);
    EXPECT_EQ(1u, engine->actionCooldowns.LiveCount());
    EXPECT_EQ(0u, engine->actionCooldowns.PreparedCount());

    engine->nullBackend.Pump(1);
    ASSERT_EQ(1u, engine->mixer.BlocksRendered());
    VnActionFiringHandle boundary = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &boundary));
    step = {};
    step.structSize = sizeof(step);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(boundary, 0, &step));
    EXPECT_EQ(VN_ACTION_STEP_ACTIVE, step.state);
    EXPECT_EQ(1u, engine->actionCooldowns.LiveCount());
}

TEST(ActionFiringApi,
     MixedCooldownSuppressionDoesNotReserveSuppressedPlayParticipant) {
    (void)Vn_Term();
    harkentest::EngineSession session(
        harkentest::MakeNullConfig(8, 256, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> samples(4096, 0.25f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision);
    image.MakeNestedImmediateSoundPlayAction();
    image.SetImmediateSoundPlayCooldown(1000000000);
    image.steps[10].target.expectedProgramSemanticFingerprint =
        image.actions[9].programSemanticFingerprint;
    image.steps[12] = image.steps[11];
    image.actions[9].steps = &image.steps[12];
    image.steps[11] = image.steps[10];
    image.steps[11].authoredEventIndex = 1;
    image.actions[8].stepCount = 2;
    image.actions[8].expandedStepOccurrenceCount = 4;
    image.actions[8].expandedFiringCount = 3;
    image.actions[8].transitiveFeatureMask = 4;
    image.actions[8].programSemanticFingerprint =
        harken::ComputeActionProgramFingerprintV1(image.actions[8]);
    image.world.capacity.maxActionExpandedWork = 4;
    image.world.identity.runtimeSemanticFingerprint =
        harken::ComputeCurrentWorldFingerprintV4(image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[8].actionStableId;
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    ASSERT_NE(0u, firing);
    EXPECT_EQ(1u, engine->playableInstances.LiveCount());
    EXPECT_EQ(1u, engine->actionCooldowns.LiveCount());

    VnActionStepResult firstPost{};
    firstPost.structSize = sizeof(firstPost);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &firstPost));
    ASSERT_NE(0u, firstPost.childFiring);
    VnActionStepResult secondPost{};
    secondPost.structSize = sizeof(secondPost);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 1, &secondPost));
    ASSERT_NE(0u, secondPost.childFiring);

    VnActionStepResult first{};
    first.structSize = sizeof(first);
    ASSERT_EQ(VN_OK,
              Vn_QueryActionStep(firstPost.childFiring, 0, &first));
    EXPECT_EQ(VN_ACTION_STEP_ACTIVE, first.state);
    EXPECT_NE(0u, first.producedPlayableInstance);

    VnActionStepResult suppressed{};
    suppressed.structSize = sizeof(suppressed);
    ASSERT_EQ(VN_OK,
              Vn_QueryActionStep(secondPost.childFiring, 0, &suppressed));
    EXPECT_EQ(VN_ACTION_STEP_SUPPRESSED, suppressed.state);
    EXPECT_EQ(0u, suppressed.producedPlayableInstance);

    EXPECT_EQ(VN_IN_USE, Vn_ReleaseActionFiring(firing));
}

TEST(ActionFiringApi, PerEmitterCooldownUsesTheExactEmitterGeneration) {
    (void)Vn_Term();
    harkentest::EngineSession session(harkentest::MakeNullConfig());
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> samples(4096, 0.25f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision);
    image.MakeImmediateSoundPlayAction();
    image.SetImmediateSoundPlayCooldown(
        1000000000, harken::ActionCooldownScopeV1::PerEmitter);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    VnEmitterHandle firstEmitter = 0;
    VnEmitterHandle secondEmitter = 0;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&firstEmitter));
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&secondEmitter));
    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    desc.emitter = firstEmitter;
    VnActionFiringHandle first = 0;
    VnActionFiringHandle repeated = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &first));
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &repeated));
    VnActionStepResult step{};
    step.structSize = sizeof(step);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(repeated, 0, &step));
    EXPECT_EQ(VN_ACTION_STEP_SUPPRESSED, step.state);

    desc.emitter = secondEmitter;
    VnActionFiringHandle isolated = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &isolated));
    step = {};
    step.structSize = sizeof(step);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(isolated, 0, &step));
    EXPECT_EQ(VN_ACTION_STEP_ACTIVE, step.state);
    EXPECT_EQ(2u, engine->actionCooldowns.LiveCount());

    ASSERT_EQ(VN_OK, Vn_DestroyEmitter(firstEmitter));
    EXPECT_EQ(1u, engine->actionCooldowns.LiveCount());
    VnEmitterHandle replacementEmitter = 0;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&replacementEmitter));
    EXPECT_NE(firstEmitter, replacementEmitter);
    desc.emitter = replacementEmitter;
    VnActionFiringHandle replacement = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &replacement));
    step = {};
    step.structSize = sizeof(step);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(replacement, 0, &step));
    EXPECT_EQ(VN_ACTION_STEP_ACTIVE, step.state);
    EXPECT_EQ(2u, engine->actionCooldowns.LiveCount());
}

