TEST(ActionFiringApi,
     ImmediateContinuousOnlyVariableControlPlayStartsWeightedSoundAndCompletes) {
    (void)Vn_Term();
    VnConfig config = harkentest::MakeNullConfig(4, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> first(64, 0.25f);
    std::vector<float> second(128, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kSecondSound,
                             &secondPcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound)
            .contentRevision);
    image.MakeImmediateContinuousOnlyVariableControlPlayAction();
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);
    const std::uint32_t decisionsBefore = engine->decisions.LiveCount();
    const std::uint32_t armGroupsBefore = engine->armGroups.LiveCount();

    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));

    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
    EXPECT_EQ(VN_ACTION_FIRING_ACTIVE, info.state);
    EXPECT_EQ(1u, info.livePlayableCount);
    EXPECT_EQ(2u, engine->playableInstances.LiveCount());
    EXPECT_EQ(1u, engine->variableControlInstances.LiveCount());
    EXPECT_EQ(decisionsBefore + 2u, engine->decisions.LiveCount());
    EXPECT_EQ(armGroupsBefore + 2u, engine->armGroups.LiveCount());
    EXPECT_EQ(1u, engine->voices.ActiveCount());

    VnActionStepResult play{};
    play.structSize = sizeof(play);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
    EXPECT_EQ(VN_ACTION_STEP_ACTIVE, play.state);
    ASSERT_NE(0u, play.producedPlayableInstance);
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == play.producedPlayableInstance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    EXPECT_EQ(0u, row->variableControlDiscreteMemberCount);
    EXPECT_EQ(1u, row->variableControlContinuousMemberCount);
    EXPECT_FALSE(row->variableControlDiscreteDecision.Valid());
    EXPECT_TRUE(row->variableControlContinuousDecision.Valid());
    EXPECT_FALSE(row->variableControlDiscreteArmGroup.Valid());
    EXPECT_TRUE(row->variableControlContinuousArmGroup.Valid());
    ExpectVariableControlTree(*engine, *row, 1u, 1u);
    const harken::VariableControlInstanceToken control =
        row->variableControlInstance;
    ASSERT_TRUE(control.Valid());
    harken::VariableControlInstanceSnapshot controlSnapshot{};
    ASSERT_TRUE(engine->variableControlInstances.Capture(
        control, &controlSnapshot));
    EXPECT_EQ(harken::VariableControlSideState::Empty,
              controlSnapshot.discrete.state);
    EXPECT_EQ(harken::VariableControlSideState::Pending,
              controlSnapshot.continuous.state);
    const std::size_t continuousSlot =
        row->scheduleStorageBase +
        row->variableControlContinuousMemberOffset;
    ASSERT_LT(continuousSlot,
              engine->playableStorage.memberCount);
    ASSERT_EQ(row->variableControlContinuousMemberCount, row->VariablePayload().variableControlMemberWeights.size());
    ASSERT_FALSE(row->VariablePayload().variableControlMemberWeights.empty());
    EXPECT_EQ(CanonicalActionWorld::kSecondSound,
              engine->ReadPlayableMember(continuousSlot).leaf.stableId);
    const harken::WeightSegmentV1 preparedWeight =
        row->VariablePayload().variableControlMemberWeights[0];
    EXPECT_EQ(row->variableControlContinuousDecision.slot,
              preparedWeight.decision.slot);
    EXPECT_EQ(row->variableControlContinuousDecision.generation,
              preparedWeight.decision.generation);
    EXPECT_EQ(row->variableControlContinuousBank.slot,
              preparedWeight.bank.slot);
    EXPECT_EQ(row->variableControlContinuousBank.generation,
              preparedWeight.bank.generation);
    EXPECT_FLOAT_EQ(1.0f, preparedWeight.startWeight);
    EXPECT_FLOAT_EQ(1.0f, preparedWeight.endWeight);
    const VnVoiceHandle render =
        engine->ReadPlayableMember(continuousSlot).render;

    const auto postAnchor = row->startFrame;
    const auto postEvaluation = row->VariablePayload().variableControlNextEvaluationFrame;
    engine->nullBackend.Pump(3);
    ASSERT_EQ(VN_OK, Vn_Update());
    ASSERT_FALSE(row->pendingImmediateEntry);
    const auto finalAnchor = row->startFrame;
    ASSERT_GE(finalAnchor, postAnchor);
    const auto shift = finalAnchor - postAnchor;
    EXPECT_GE(shift, 3u * config.blockFrames);
    EXPECT_EQ(postEvaluation + shift,
              row->VariablePayload().variableControlNextEvaluationFrame);
    for (std::uint32_t block = 0;
         block < 16 && engine->mixer.BlocksRendered() <=
             finalAnchor / config.blockFrames; ++block)
        engine->nullBackend.Pump(1);
    ASSERT_GT(engine->mixer.BlocksRendered(),
              finalAnchor / config.blockFrames);
    EXPECT_LT(engine->nullBackend.LastBlock()[0], -0.01f);
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
    EXPECT_EQ(VN_ACTION_FIRING_ACTIVE, info.state);
    EXPECT_EQ(1u, engine->voices.ActiveCount());
    const harken::VoiceRenderContext* voice = engine->voices.Resolve(render);
    ASSERT_NE(nullptr, voice);
    const auto* ownedWeight = FrontierOwnedVariableWeight(*voice, *row);
    ASSERT_NE(nullptr, ownedWeight);
    EXPECT_TRUE(ownedWeight->active);
    EXPECT_EQ(preparedWeight.startFrame + shift,
              ownedWeight->segment.startFrame);
    EXPECT_EQ(preparedWeight.endFrame + shift,
              ownedWeight->segment.endFrame);
    EXPECT_EQ(preparedWeight.segmentGeneration,
              ownedWeight->segment.segmentGeneration);
    EXPECT_EQ(preparedWeight.decision.slot,
              ownedWeight->segment.decision.slot);
    EXPECT_EQ(preparedWeight.decision.generation,
              ownedWeight->segment.decision.generation);
    EXPECT_EQ(preparedWeight.bank.slot,
              ownedWeight->segment.bank.slot);
    EXPECT_EQ(preparedWeight.bank.generation,
              ownedWeight->segment.bank.generation);
    EXPECT_FLOAT_EQ(preparedWeight.startWeight,
                    ownedWeight->segment.startWeight);
    EXPECT_FLOAT_EQ(preparedWeight.endWeight,
                    ownedWeight->segment.endWeight);

    for (std::uint32_t block = 1; block < 32; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
        if (info.state == VN_ACTION_FIRING_TERMINAL_RETAINED) {
            break;
        }
    }

    ASSERT_NO_FATAL_FAILURE(ExpectVariableControlNaturalCompletion(
            *engine, firing, &info));
    ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
    EXPECT_EQ(VN_ACTION_OUTCOME_SUCCEEDED, info.outcome);
    EXPECT_EQ(VN_ACTION_TERMINAL_NATURAL, info.terminalReason);
    EXPECT_EQ(0u, info.livePlayableCount);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
    EXPECT_EQ(VN_ACTION_STEP_SUCCEEDED, play.state);
    EXPECT_EQ(0u, engine->voices.ActiveCount());
    EXPECT_EQ(0u, engine->variableControlInstances.LiveCount());
    EXPECT_EQ(decisionsBefore, engine->decisions.LiveCount());
    EXPECT_EQ(armGroupsBefore, engine->armGroups.LiveCount());
    EXPECT_FALSE(engine->variableControlInstances.Capture(
        control, &controlSnapshot));
    EXPECT_FALSE(engine->playableInstances
                     .Classify(play.producedPlayableInstance)
                     .live);
    EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    EXPECT_EQ(0u, engine->actionFirings.LiveCount());
}

enum class AuthoredVariableStopCase { Started, SameAction, BeforeUpdate, Fade, RefusedThenRetry };

static void ExpectAuthoredVariableControlStopReclaims(
    bool mixed, AuthoredVariableStopCase testCase = AuthoredVariableStopCase::Started) {
    const bool sameAction = testCase == AuthoredVariableStopCase::SameAction;
    const bool beforeUpdate = testCase == AuthoredVariableStopCase::BeforeUpdate;
    const bool fade = testCase == AuthoredVariableStopCase::Fade;
    (void)Vn_Term();
    harkentest::EngineSession session(harkentest::MakeNullConfig(8, 64, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    std::vector<float> samples(65536, 0.25f);
    const auto pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &pcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
    if (mixed) image.MakeImmediateMixedVariableControlPlayAction();
    else image.MakeImmediateContinuousOnlyVariableControlPlayAction();
    image.steps[12] = image.steps[11];
    image.steps[12].opcode = harken::ActionOpcodeV1::Stop;
    image.steps[12].authoredEventIndex = sameAction ? 1 : 0;
    SetAbsoluteTime(&image.steps[12].fade, fade ? 10'000'000 : 0);
    image.actions[10] = {};
    image.actions[10].actionStableId = harkentest::ObjectId(51);
    image.actions[10].steps = &image.steps[12];
    image.actions[10].stepCount = 1;
    image.actions[10].expandedStepOccurrenceCount = 1;
    image.actions[10].expandedFiringCount = 1;
    if (sameAction) {
        image.actions[9].stepCount = 2;
        image.actions[9].expandedStepOccurrenceCount = 2;
    }
    image.actions[9].programSemanticFingerprint =
        harken::ComputeActionProgramFingerprintV1(image.actions[9]);
    image.actions[10].programSemanticFingerprint =
        harken::ComputeActionProgramFingerprintV1(image.actions[10]);
    image.world.actions = &image.actions[9];
    image.world.actionCount = sameAction ? 1 : 2;
    image.world.identity.runtimeSemanticFingerprint =
        harken::ComputeCurrentWorldFingerprintV4(image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);
    const auto baseline = CaptureActionReclaimableOwners(*engine);
    const auto sourcesBefore = engine->sourceTerminals.OccupiedCount();
    for (unsigned cycle = 0; cycle < 2; ++cycle) {
        SCOPED_TRACE(cycle);
        auto desc = ValidPostDesc();
        desc.actionId = image.actions[9].actionStableId;
        VnActionFiringHandle play = 0;
        ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &play));
        VnActionFiringHandle stop = play;
        VnActionFiringHandle repeat = 0;
        if (!sameAction) {
            for (unsigned block = 0; block < (beforeUpdate ? 0u : 24u); ++block) {
                ASSERT_EQ(VN_OK, Vn_Update());
                engine->nullBackend.Pump(1);
            }
            if (!beforeUpdate) {
                ASSERT_GT(engine->nullBackend.LastBlock()[0], 0.01f);
                ASSERT_EQ(mixed ? 2u : 1u, engine->voices.ActiveCount());
            }
            desc.actionId = image.actions[10].actionStableId;
            if (testCase == AuthoredVariableStopCase::RefusedThenRetry) {
                harken::CommandRecord filler{};
                filler.opcode = harken::kOpcodeStop;
                filler.payload.stop.handle = 1;
                while (engine->commands.FreeSlots() != 0) ASSERT_TRUE(engine->commands.TryPush(filler));
                const auto before = CaptureActionReclaimableOwners(*engine);
                ASSERT_EQ(VN_BACKPRESSURE, Vn_PostAction(&desc, &stop));
                EXPECT_EQ(0u, stop);
                EXPECT_EQ(before, CaptureActionReclaimableOwners(*engine));
                engine->nullBackend.Pump(1);
                EXPECT_GT(engine->nullBackend.LastBlock()[0], 0.01f);
                ASSERT_EQ(VN_OK, Vn_Update());
            }
            ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &stop));
            if (!beforeUpdate) {
                // Immediate Stop must affect the next audio block, without
                // waiting for the scheduling publication lead.
                engine->nullBackend.Pump(1);
                const auto* block = engine->nullBackend.LastBlock();
                if (fade) {
                    EXPECT_GT(block[0], block[63]);
                    EXPECT_GT(block[63], 0.01f);
                } else {
                    EXPECT_NEAR(0.0f, block[0], 1.0e-6f);
                    EXPECT_NEAR(0.0f, block[63], 1.0e-6f);
                }
                ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &repeat));
                VnActionStepResult repeated{};
                repeated.structSize = sizeof(repeated);
                ASSERT_EQ(VN_OK, Vn_QueryActionStep(repeat, 0, &repeated));
                EXPECT_EQ(VN_ACTION_STEP_NO_OP, repeated.state);
                if (fade) {
                    // 10 ms at 48 kHz ends within eight 64-frame blocks;
                    // a repeated Stop must not restart or extend that fade.
                    engine->nullBackend.Pump(7);
                    EXPECT_NEAR(0.0f, engine->nullBackend.LastBlock()[63], 1.0e-6f);
                }
            }
        }
        for (unsigned block = 0; block < 96; ++block) {
            ASSERT_EQ(VN_OK, Vn_Update());
            engine->nullBackend.Pump(1);
        }
        ASSERT_EQ(VN_OK, Vn_Update());
        EXPECT_FALSE(engine->runtimeRecreateRequired);
        EXPECT_EQ(0u, engine->voices.ActiveCount());
        EXPECT_NEAR(0.0f, engine->nullBackend.LastBlock()[0], 1.0e-6f);
        VnActionFiringInfo info{};
        info.structSize = sizeof(info);
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(play, &info));
        EXPECT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(stop, &info));
        EXPECT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
        VnActionStepResult stopped{};
        stopped.structSize = sizeof(stopped);
        ASSERT_EQ(VN_OK, Vn_QueryActionStep(stop, sameAction ? 1 : 0, &stopped));
        EXPECT_EQ(VN_ACTION_STEP_SUCCEEDED, stopped.state);
        EXPECT_EQ(0u, stopped.remainingPlayableCount);
        ASSERT_FALSE(::testing::Test::HasFailure());
        ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(play));
        if (!sameAction) ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(stop));
        if (repeat != 0) ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(repeat));
        for (unsigned block = 0; block < 32; ++block) {
            ASSERT_EQ(VN_OK, Vn_Update());
            engine->nullBackend.Pump(1);
        }
        EXPECT_EQ(baseline, CaptureActionReclaimableOwners(*engine));
        EXPECT_EQ(sourcesBefore, engine->sourceTerminals.OccupiedCount());
    }
}

