TEST(ActionFiringApi,
     ImmediateContinuousOwnedRampStartsAtReanchoredFirstSample) {
    (void)Vn_Term();
    constexpr std::uint32_t kBlockFrames = 64;
    harkentest::EngineSession session(
        harkentest::MakeNullConfig(4, kBlockFrames, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    std::vector<float> first(1024, 0.25f);
    std::vector<float> second(1024, -0.5f);
    const auto firstPcm = harkentest::MonoDesc(first, 48000);
    const auto secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK,
        Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK,
        Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &secondPcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound)
            .contentRevision);
    image.MakeImmediateContinuousOnlyVariableControlPlayAction();
    image.containers[3].envelopeFrames = 128;
    image.world.identity.runtimeSemanticFingerprint =
        harken::ComputeCurrentWorldFingerprintV4(image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
        harken::InstallContainerWorldV1(*engine, image.world).status);

    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [firing](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.InvocationValid() &&
                candidate.Invocation().actionFiring == firing;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    const auto postAnchor = row->startFrame;
    const auto postEvaluation = row->VariablePayload().variableControlNextEvaluationFrame;
    engine->nullBackend.Pump(3);
    ASSERT_EQ(VN_OK, Vn_Update());
    ASSERT_FALSE(row->pendingImmediateEntry);
    ASSERT_GT(row->startFrame, postAnchor);
    EXPECT_EQ(postEvaluation + row->startFrame - postAnchor,
              row->VariablePayload().variableControlNextEvaluationFrame);
    const auto render = engine->ReadPlayableMember(
        row->scheduleStorageBase + row->variableControlContinuousMemberOffset).render;
    const auto* voice = engine->voices.Resolve(render);
    ASSERT_NE(nullptr, voice);
    const auto* owned = FrontierOwnedVariableWeight(*voice, *row);
    ASSERT_NE(nullptr, owned);
    EXPECT_EQ(0.0f, owned->segment.startWeight);
    EXPECT_EQ(1.0f, owned->segment.endWeight);

    while (engine->mixer.BlocksRendered() * kBlockFrames <= row->startFrame)
        engine->nullBackend.Pump(1);
    const auto* onset = engine->nullBackend.LastBlock();
    EXPECT_NEAR(0.0f, onset[0], 0.001f);
    EXPECT_LT(onset[kBlockFrames - 1], -0.05f);
    voice = engine->voices.Resolve(render);
    ASSERT_NE(nullptr, voice);
    owned = FrontierOwnedVariableWeight(*voice, *row);
    ASSERT_NE(nullptr, owned);
    EXPECT_EQ(row->startFrame, owned->segment.startFrame);
    EXPECT_EQ(row->startFrame + 128u, owned->segment.endFrame);
    ASSERT_EQ(VN_OK, Vn_StopActionFiring(firing, 0));
    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    for (std::uint32_t block = 0; block < 64; ++block) {
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
        if (info.state == VN_ACTION_FIRING_TERMINAL_RETAINED) break;
    }
    ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
}

TEST(ActionFiringApi,
     ImmediateNestedContinuousOwnedRampStartsAtReanchoredFirstSample) {
    (void)Vn_Term();
    constexpr std::uint32_t kBlockFrames = 64;
    harkentest::EngineSession session(
        harkentest::MakeNullConfig(4, kBlockFrames, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    std::vector<float> first(1024, 0.25f);
    std::vector<float> second(1024, -0.5f);
    const auto firstPcm = harkentest::MonoDesc(first, 48000);
    const auto secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK,
        Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK,
        Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &secondPcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound)
            .contentRevision);
    image.MakeImmediateVariableControlWithNestedContinuousRampPlayAction();
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
        harken::InstallContainerWorldV1(*engine, image.world).status);

    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    const auto nested = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [firing](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.InvocationValid() &&
                candidate.Invocation().actionFiring == firing &&
                candidate.parentService.Valid() &&
                candidate.variableControlInstance.Valid();
        });
    ASSERT_NE(engine->playableServices.end(), nested);
    ASSERT_EQ(1u, nested->variableControlContinuousMemberCount);
    const auto postAnchor = nested->startFrame;
    const auto postEvaluation = nested->VariablePayload().variableControlNextEvaluationFrame;
    engine->nullBackend.Pump(3);
    ASSERT_EQ(VN_OK, Vn_Update());
    ASSERT_GT(nested->startFrame, postAnchor);
    EXPECT_EQ(postEvaluation + nested->startFrame - postAnchor,
        nested->VariablePayload().variableControlNextEvaluationFrame);
    std::size_t renderSlot = 0;
    ASSERT_TRUE(engine->ResolvePlayableMemberSlot(
        nested->scheduleStorageBase +
            nested->variableControlContinuousMemberOffset,
        &renderSlot));
    const auto render = engine->ReadPlayableMember(renderSlot).render;
    const auto* voice = engine->voices.Resolve(render);
    ASSERT_NE(nullptr, voice)
        << " phase=" << static_cast<int>(nested->phase)
        << " leafCount=" << nested->scheduleLeafCount
        << " render=" << render
        << " recreate=" << engine->runtimeRecreateRequired;
    const auto* owned = FrontierOwnedVariableWeight(*voice, *nested);
    ASSERT_NE(nullptr, owned);
    EXPECT_EQ(0.0f, owned->segment.startWeight);
    EXPECT_EQ(1.0f, owned->segment.endWeight);

    while (engine->mixer.BlocksRendered() * kBlockFrames <=
            nested->startFrame)
        engine->nullBackend.Pump(1);
    const auto* onset = engine->nullBackend.LastBlock();
    EXPECT_NEAR(0.0f, onset[0], 0.001f);
    EXPECT_GT(onset[kBlockFrames - 1], 0.05f);
    voice = engine->voices.Resolve(render);
    ASSERT_NE(nullptr, voice);
    owned = FrontierOwnedVariableWeight(*voice, *nested);
    ASSERT_NE(nullptr, owned);
    EXPECT_EQ(nested->startFrame, owned->segment.startFrame);
    EXPECT_EQ(nested->startFrame + 128u, owned->segment.endFrame);
    ASSERT_EQ(VN_OK, Vn_StopActionFiring(firing, 0));
    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    for (std::uint32_t block = 0; block < 64; ++block) {
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
        if (info.state == VN_ACTION_FIRING_TERMINAL_RETAINED) break;
    }
    ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
}

TEST(ActionFiringApi,
     ImmediateMixedVariableControlPlayCompletesAfterBothSidesRetire) {
    (void)Vn_Term();
    VnConfig config = harkentest::MakeNullConfig(4, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> first(64, 0.25f);
    std::vector<float> second(192, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kSecondSound,
                             &secondPcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound)
            .contentRevision);
    image.MakeImmediateMixedVariableControlPlayAction();
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);
    const std::uint32_t decisionsBefore = engine->decisions.LiveCount();
    const std::uint32_t armGroupsBefore = engine->armGroups.LiveCount();

    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));

    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
    EXPECT_EQ(VN_ACTION_FIRING_ACTIVE, info.state);
    EXPECT_EQ(1u, info.livePlayableCount);
    EXPECT_EQ(3u, engine->playableInstances.LiveCount());
    EXPECT_EQ(1u, engine->variableControlInstances.LiveCount());
    EXPECT_EQ(decisionsBefore + 3u, engine->decisions.LiveCount());
    EXPECT_EQ(armGroupsBefore + 3u, engine->armGroups.LiveCount());
    EXPECT_EQ(2u, engine->voices.ActiveCount());

    VnActionStepResult play{};
    play.structSize = sizeof(play);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
    ASSERT_NE(0u, play.producedPlayableInstance);
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == play.producedPlayableInstance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    ExpectVariableControlTree(*engine, *row, 2u, 2u);
    EXPECT_EQ(1u, row->variableControlDiscreteMemberCount);
    EXPECT_EQ(1u, row->variableControlContinuousMemberCount);
    EXPECT_TRUE(row->variableControlDiscreteDecision.Valid());
    EXPECT_TRUE(row->variableControlContinuousDecision.Valid());
    EXPECT_NE(row->variableControlDiscreteDecision.slot,
              row->variableControlContinuousDecision.slot);
    EXPECT_TRUE(row->variableControlDiscreteArmGroup.Valid());
    EXPECT_TRUE(row->variableControlContinuousArmGroup.Valid());
    EXPECT_EQ(row->variableControlDiscreteBank.slot,
              row->variableControlContinuousBank.slot);
    EXPECT_EQ(row->variableControlDiscreteBank.generation,
              row->variableControlContinuousBank.generation);
    const harken::VariableControlInstanceToken control =
        row->variableControlInstance;
    harken::VariableControlInstanceSnapshot controlSnapshot{};
    ASSERT_TRUE(engine->variableControlInstances.Capture(
        control, &controlSnapshot));
    EXPECT_EQ(harken::VariableControlSideState::Pending,
              controlSnapshot.discrete.state);
    EXPECT_EQ(harken::VariableControlSideState::Pending,
              controlSnapshot.continuous.state);
    EXPECT_NE(controlSnapshot.discrete.decision.slot,
              controlSnapshot.continuous.decision.slot);
    const std::size_t discreteSlot = row->scheduleStorageBase;
    const std::size_t continuousSlot =
        row->scheduleStorageBase +
        row->variableControlContinuousMemberOffset;
    EXPECT_EQ(CanonicalActionWorld::kFirstSound,
              engine->ReadPlayableMember(discreteSlot).leaf.stableId);
    EXPECT_EQ(CanonicalActionWorld::kSecondSound,
              engine->ReadPlayableMember(continuousSlot).leaf.stableId);
    ASSERT_EQ(row->variableControlContinuousMemberCount, row->VariablePayload().variableControlMemberWeights.size());
    ASSERT_FALSE(row->VariablePayload().variableControlMemberWeights.empty());
    const harken::WeightSegmentV1 preparedWeight =
        row->VariablePayload().variableControlMemberWeights[0];
    EXPECT_EQ(row->variableControlContinuousDecision.slot,
              preparedWeight.decision.slot);
    EXPECT_EQ(row->variableControlContinuousDecision.generation,
              preparedWeight.decision.generation);
    EXPECT_EQ(row->variableControlContinuousBank.slot,
              preparedWeight.bank.slot);
    EXPECT_EQ(row->variableControlContinuousBank.generation,
              preparedWeight.bank.generation);
    EXPECT_FLOAT_EQ(1.0f, preparedWeight.startWeight);
    EXPECT_FLOAT_EQ(1.0f, preparedWeight.endWeight);
    const VnVoiceHandle continuousRender =
        engine->ReadPlayableMember(continuousSlot).render;

    ASSERT_EQ(VN_OK, Vn_Update());
    engine->nullBackend.Pump(1);
    ASSERT_EQ(VN_OK, Vn_Update());
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
    const harken::VoiceRenderContext* continuousVoice =
        engine->voices.Resolve(continuousRender);
    ASSERT_NE(nullptr, continuousVoice);
    const auto* ownedWeight = FrontierOwnedVariableWeight(*continuousVoice, *row);
    ASSERT_NE(nullptr, ownedWeight);
    EXPECT_TRUE(ownedWeight->active);
    EXPECT_EQ(preparedWeight.startFrame,
              ownedWeight->segment.startFrame);
    EXPECT_EQ(preparedWeight.endFrame,
              ownedWeight->segment.endFrame);
    EXPECT_EQ(preparedWeight.segmentGeneration,
              ownedWeight->segment.segmentGeneration);
    EXPECT_EQ(preparedWeight.decision.slot,
              ownedWeight->segment.decision.slot);
    EXPECT_EQ(preparedWeight.decision.generation,
              ownedWeight->segment.decision.generation);
    EXPECT_EQ(preparedWeight.bank.slot,
              ownedWeight->segment.bank.slot);
    EXPECT_EQ(preparedWeight.bank.generation,
              ownedWeight->segment.bank.generation);
    EXPECT_FLOAT_EQ(preparedWeight.startWeight,
                    ownedWeight->segment.startWeight);
    EXPECT_FLOAT_EQ(preparedWeight.endWeight,
                    ownedWeight->segment.endWeight);

    bool observedPartialRetirement = engine->voices.ActiveCount() == 1u;
    if (observedPartialRetirement) {
        EXPECT_EQ(VN_ACTION_FIRING_ACTIVE, info.state);
        ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
        EXPECT_EQ(VN_ACTION_STEP_ACTIVE, play.state);
    }
    for (std::uint32_t block = 1; block < 32; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
        if (engine->voices.ActiveCount() == 1u) {
            observedPartialRetirement = true;
            EXPECT_EQ(VN_ACTION_FIRING_ACTIVE, info.state);
            ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
            EXPECT_EQ(VN_ACTION_STEP_ACTIVE, play.state);
        }
        if (info.state == VN_ACTION_FIRING_TERMINAL_RETAINED) {
            break;
        }
    }

    EXPECT_TRUE(observedPartialRetirement);
    ASSERT_NO_FATAL_FAILURE(ExpectVariableControlNaturalCompletion(
            *engine, firing, &info));
    ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
    EXPECT_EQ(VN_ACTION_OUTCOME_SUCCEEDED, info.outcome);
    EXPECT_EQ(VN_ACTION_TERMINAL_NATURAL, info.terminalReason);
    EXPECT_EQ(0u, info.livePlayableCount);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
    EXPECT_EQ(VN_ACTION_STEP_SUCCEEDED, play.state);
    EXPECT_EQ(0u, engine->voices.ActiveCount());
    EXPECT_EQ(0u, engine->variableControlInstances.LiveCount());
    EXPECT_EQ(decisionsBefore, engine->decisions.LiveCount());
    EXPECT_EQ(armGroupsBefore, engine->armGroups.LiveCount());
    EXPECT_FALSE(engine->variableControlInstances.Capture(
        control, &controlSnapshot));
    EXPECT_FALSE(engine->playableInstances
                     .Classify(play.producedPlayableInstance)
                     .live);
    EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    EXPECT_EQ(0u, engine->actionFirings.LiveCount());
}

TEST(ActionFiringApi,
     ImmediateMixedVariableControlPlayUsesEarlierPreparedSetValueForContinuousAxis) {
    (void)Vn_Term();
    VnConfig config = harkentest::MakeNullConfig(4, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> first(64, 0.25f);
    std::vector<float> second(128, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kSecondSound,
                             &secondPcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound)
            .contentRevision);
    image.MakeSetValueThenImmediateMixedVariableControlPlayAction();
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);
    const std::uint32_t decisionsBefore = engine->decisions.LiveCount();
    const std::uint32_t armGroupsBefore = engine->armGroups.LiveCount();

    const VnVariableId continuousAxis = image.variables[0].variableId;
    float committedValue = 1.0f;
    harken::BankVersionToken committedBank{};
    ASSERT_TRUE(engine->variables.CaptureCurrentBank(
        0, &continuousAxis, 1, &committedValue, &committedBank));
    EXPECT_FLOAT_EQ(0.0f, committedValue);

    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    ASSERT_TRUE(engine->variables.CaptureCurrentBank(
        0, &continuousAxis, 1, &committedValue, &committedBank));
    EXPECT_FLOAT_EQ(0.0f, committedValue);

    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
    EXPECT_EQ(VN_ACTION_FIRING_ACTIVE, info.state);
    EXPECT_EQ(1u, info.livePlayableCount);
    EXPECT_EQ(decisionsBefore + 3u, engine->decisions.LiveCount());
    EXPECT_EQ(armGroupsBefore + 3u, engine->armGroups.LiveCount());

    VnActionStepResult setValue{};
    setValue.structSize = sizeof(setValue);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &setValue));
    EXPECT_EQ(VN_ACTION_STEP_SUCCEEDED, setValue.state);
    EXPECT_EQ(VN_ACTION_OPCODE_SET_VARIABLE, setValue.opcode);
    EXPECT_EQ(continuousAxis, setValue.targetStableId);
    VnActionStepResult play{};
    play.structSize = sizeof(play);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 1, &play));
    EXPECT_EQ(VN_ACTION_STEP_ACTIVE, play.state);
    EXPECT_EQ(VN_ACTION_OPCODE_PLAY, play.opcode);
    EXPECT_EQ(setValue.logicCommitSequence, play.logicCommitSequence);
    EXPECT_EQ(info.acceptedLogicSequence, play.logicCommitSequence);
    ASSERT_NE(0u, play.producedPlayableInstance);

    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == play.producedPlayableInstance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    ASSERT_EQ(1u, row->variableControlDiscreteMemberCount);
    ASSERT_EQ(2u, row->variableControlContinuousMemberCount);
    ASSERT_EQ(3u, row->scheduleLeafCount);
    EXPECT_TRUE(row->variableControlDiscreteDecision.Valid());
    EXPECT_TRUE(row->variableControlContinuousDecision.Valid());
    EXPECT_NE(row->variableControlDiscreteDecision.slot,
              row->variableControlContinuousDecision.slot);
    EXPECT_EQ(row->variableControlDiscreteBank.slot,
              row->variableControlContinuousBank.slot);
    EXPECT_EQ(row->variableControlDiscreteBank.generation,
              row->variableControlContinuousBank.generation);
    const std::size_t discreteSlot = row->scheduleStorageBase;
    const std::size_t continuousSlot =
        row->scheduleStorageBase +
        row->variableControlContinuousMemberOffset;
    ASSERT_LT(continuousSlot, engine->playableStorage.memberCount);
    EXPECT_EQ(CanonicalActionWorld::kFirstSound,
              engine->ReadPlayableMember(discreteSlot).leaf.stableId);
    EXPECT_EQ(CanonicalActionWorld::kFirstSound,
              engine->ReadPlayableMember(continuousSlot).leaf.stableId);
    EXPECT_EQ(CanonicalActionWorld::kSecondSound,
              engine->ReadPlayableMember(continuousSlot + 1u).leaf.stableId);
    ASSERT_EQ(2u, row->variableControlChildWeightCount);
    for (std::uint32_t index = 0; index < row->variableControlChildWeightCount; ++index) {
        const auto& weight = row->VariablePayload().variableControlMemberWeights.Children()[index];
        EXPECT_EQ(image.variableControlChildren[index].stableChildOrdinal, weight.ordinal);
        EXPECT_FLOAT_EQ(index == 0 ? 0.0f : 1.0f, weight.current.startWeight);
        EXPECT_FLOAT_EQ(index == 0 ? 0.0f : 1.0f, weight.current.endWeight);
    }

    for (std::uint32_t block = 0; block < 32; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
        if (info.state == VN_ACTION_FIRING_TERMINAL_RETAINED) {
            break;
        }
    }

    ASSERT_NO_FATAL_FAILURE(ExpectVariableControlNaturalCompletion(
            *engine, firing, &info));
    ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
    EXPECT_EQ(VN_ACTION_OUTCOME_SUCCEEDED, info.outcome);
    EXPECT_EQ(VN_ACTION_TERMINAL_NATURAL, info.terminalReason);
    EXPECT_EQ(2u, info.directStepTerminalCount);
    EXPECT_EQ(0u, info.livePlayableCount);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &setValue));
    EXPECT_EQ(VN_ACTION_STEP_SUCCEEDED, setValue.state);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 1, &play));
    EXPECT_EQ(VN_ACTION_STEP_SUCCEEDED, play.state);
    EXPECT_EQ(0u, engine->voices.ActiveCount());
    EXPECT_EQ(0u, engine->variableControlInstances.LiveCount());
    EXPECT_EQ(decisionsBefore, engine->decisions.LiveCount());
    EXPECT_EQ(armGroupsBefore, engine->armGroups.LiveCount());
    EXPECT_FALSE(engine->playableInstances
                     .Classify(play.producedPlayableInstance)
                     .live);
    EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    EXPECT_EQ(0u, engine->actionFirings.LiveCount());
}

static void CheckImmediateMixedVariableControlEarlierSetValueCadence(bool lateFirstUpdate, bool withGain = false, std::vector<float>* captured = nullptr) {
    (void)Vn_Term();
    VnConfig config = harkentest::MakeNullConfig(4, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> first(64, 0.25f);
    std::vector<float> second(128, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kSecondSound,
                             &secondPcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound)
            .contentRevision, false, withGain);
    image.MakeSetValueThenImmediateMixedVariableControlPlayActionAtCadence();
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);
    const std::uint32_t playableBefore =
        engine->playableInstances.LiveCount();
    const std::uint32_t variableControlBefore =
        engine->variableControlInstances.LiveCount();
    const std::uint32_t voicesBefore = engine->voices.ActiveCount();
    const std::uint32_t decisionsBefore = engine->decisions.LiveCount();
    const std::uint32_t armsBefore = engine->timelineArms.LiveCount();
    const std::uint32_t armGroupsBefore = engine->armGroups.LiveCount();

    if (lateFirstUpdate) ASSERT_EQ(VN_OK, Vn_Update());
    const auto ownersBefore = CaptureActionReclaimableOwners(*engine);
    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    struct OriginalEffects {
        std::vector<std::pair<VnVoiceHandle, harken::EffectInstanceRef>> rows;
        std::uint32_t matchedLiveHosts = 0;
    } originalEffects;
    if (withGain) {
        engine->timelineVoicePreparedContextForTest = &originalEffects;
        engine->timelineVoicePreparedHookForTest = [](harken::Engine&,
            const harken::EnginePreparedTimelineVoiceStart& voice, void* opaque) {
            auto& effects = *static_cast<OriginalEffects*>(opaque);
            ASSERT_EQ(1u, voice.effectCount);
            ASSERT_EQ(VN_EFFECT_GAIN, voice.effects[0].type);
            ASSERT_NE(VnObjectId{}, voice.effectIdentities[0].effectId);
            effects.rows.emplace_back(voice.renderHandle, voice.effects[0]);
        };
    }
    const auto pump = [&]() {
        engine->nullBackend.Pump(1);
        const auto* output = engine->nullBackend.LastBlock();
        if (captured != nullptr) captured->insert(captured->end(), output,
            output + engine->nullBackend.BlockFrames() * engine->nullBackend.Channels());
        for (const auto& original : originalEffects.rows) {
            const auto* voice = engine->voices.Resolve(original.first);
            if (voice == nullptr || voice->fxSlotEffectRef[0].type == harken::kEffectTypeNone) continue;
            EXPECT_EQ(original.second.type, voice->fxSlotEffectRef[0].type);
            EXPECT_EQ(original.second.poolIndex, voice->fxSlotEffectRef[0].poolIndex);
            EXPECT_EQ(original.second.generation, voice->fxSlotEffectRef[0].generation);
            ++originalEffects.matchedLiveHosts;
        }
    };
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    engine->timelineVoicePreparedHookForTest = nullptr;
    engine->timelineVoicePreparedContextForTest = nullptr;
    if (withGain) ASSERT_EQ(3u, originalEffects.rows.size());
    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
    EXPECT_EQ(VN_ACTION_FIRING_ACTIVE, info.state);
    EXPECT_EQ(1u, info.livePlayableCount);

    VnActionStepResult setValue{};
    setValue.structSize = sizeof(setValue);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &setValue));
    EXPECT_EQ(VN_ACTION_STEP_SUCCEEDED, setValue.state);
    VnActionStepResult play{};
    play.structSize = sizeof(play);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 1, &play));
    EXPECT_EQ(VN_ACTION_STEP_ACTIVE, play.state);
    EXPECT_EQ(setValue.logicCommitSequence, play.logicCommitSequence);
    ASSERT_NE(0u, play.producedPlayableInstance);
    const auto producedRoot = play.producedPlayableInstance;
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == producedRoot;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    const harken::VariableControlInstanceToken control =
        row->variableControlInstance;
    EXPECT_EQ(1u, row->variableControlDiscreteMemberCount);
    EXPECT_EQ(2u, row->variableControlContinuousMemberCount);
    EXPECT_EQ(3u, row->scheduleLeafCount);

    if (lateFirstUpdate) {
        const std::array<std::size_t, 3> logicalSlots = {
            row->scheduleStorageBase,
            row->scheduleStorageBase + row->variableControlContinuousMemberOffset,
            row->scheduleStorageBase + row->variableControlContinuousMemberOffset + 1u};
        std::array<harken::TimelineArmToken, 3> arms{};
        for (unsigned member = 0; member < arms.size(); ++member) {
            std::size_t slot = 0;
            ASSERT_TRUE(engine->ResolvePlayableMemberSlot(logicalSlots[member], &slot));
            arms[member] = engine->ReadPlayableMember(slot).arm;
            ASSERT_TRUE(arms[member].Valid());
        }
        for (const auto& arm : arms) {
            harken::TimelineArmObservation before{};
            ASSERT_TRUE(engine->timelineArms.Observe(arm, &before));
            ASSERT_EQ(0u, before.startedBlockSequence);
        }
        const auto originalStart = row->startFrame;
        for (unsigned block = 0; block < 12u; ++block) {
            pump();
            const auto* output = engine->nullBackend.LastBlock();
            for (std::uint32_t sample = 0; sample < engine->nullBackend.BlockFrames() *
                    engine->nullBackend.Channels(); ++sample)
                EXPECT_EQ(0.0f, output[sample]);
        }
        const auto beforeUpdate = engine->mixer.BlocksRendered();
        ASSERT_GT(beforeUpdate * engine->config.blockFrames, originalStart);
        ASSERT_EQ(VN_OK, Vn_Update());
        bool heardPreparedContinuousSound = false;
        for (unsigned block = 0; block < 16u; ++block) {
            pump();
            const auto* output = engine->nullBackend.LastBlock();
            for (std::uint32_t sample = 0; sample < engine->nullBackend.BlockFrames() *
                    engine->nullBackend.Channels(); ++sample)
                heardPreparedContinuousSound = heardPreparedContinuousSound || output[sample] < -0.01f;
        }
        EXPECT_TRUE(heardPreparedContinuousSound);
        std::array<harken::TimelineArmObservation, 3> started{};
        for (unsigned member = 0; member < arms.size(); ++member) {
            ASSERT_TRUE(engine->timelineArms.Observe(arms[member], &started[member]));
            EXPECT_GT(started[member].startedBlockSequence, beforeUpdate);
        }
        EXPECT_EQ(started[0].startedBlockSequence, started[1].startedBlockSequence);
        EXPECT_EQ(started[0].startedBlockSequence, started[2].startedBlockSequence);
    }

    for (std::uint32_t block = 0; block < 32; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        pump();
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
        if (info.state == VN_ACTION_FIRING_TERMINAL_RETAINED) {
            break;
        }
    }

    ASSERT_NO_FATAL_FAILURE(ExpectVariableControlNaturalCompletion(
            *engine, firing, &info));
    EXPECT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
    EXPECT_EQ(VN_ACTION_OUTCOME_SUCCEEDED, info.outcome);
    EXPECT_EQ(VN_ACTION_TERMINAL_NATURAL, info.terminalReason);
    EXPECT_EQ(2u, info.directStepTerminalCount);
    EXPECT_EQ(0u, info.livePlayableCount);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &setValue));
    EXPECT_EQ(VN_ACTION_STEP_SUCCEEDED, setValue.state);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 1, &play));
    EXPECT_EQ(VN_ACTION_STEP_SUCCEEDED, play.state);
    EXPECT_EQ(producedRoot, play.producedPlayableInstance);
    harken::VariableControlInstanceSnapshot snapshot{};
    EXPECT_FALSE(engine->variableControlInstances.Capture(control, &snapshot));
    EXPECT_FALSE(engine->playableInstances.Classify(producedRoot).live);
    EXPECT_EQ(playableBefore, engine->playableInstances.LiveCount());
    EXPECT_EQ(variableControlBefore,
              engine->variableControlInstances.LiveCount());
    EXPECT_EQ(voicesBefore, engine->voices.ActiveCount());
    EXPECT_EQ(decisionsBefore, engine->decisions.LiveCount());
    EXPECT_EQ(armsBefore, engine->timelineArms.LiveCount());
    EXPECT_EQ(armGroupsBefore, engine->armGroups.LiveCount());
    if (info.state == VN_ACTION_FIRING_TERMINAL_RETAINED) {
        EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
        EXPECT_EQ(0u, engine->actionFirings.LiveCount());
    }
    if (lateFirstUpdate || withGain || captured != nullptr) {
        for (unsigned block = 0; block < 96u && CaptureActionReclaimableOwners(*engine) != ownersBefore; ++block) {
            pump();
            ASSERT_EQ(VN_OK, Vn_Update());
        }
        EXPECT_EQ(ownersBefore, CaptureActionReclaimableOwners(*engine));
        EXPECT_FALSE(engine->runtimeRecreateRequired);
    }
    if (withGain) {
        EXPECT_GT(originalEffects.matchedLiveHosts, 0u);
        EXPECT_EQ(0u, engine->effectBank.InUseOf(VN_EFFECT_GAIN));
    }
}

