TEST(ActionFiringApi,
     ImmediateMixedVariableControlSilentDiscreteSideCompletesWithContinuousChild) {
    (void)Vn_Term();
    VnConfig config = harkentest::MakeNullConfig(4, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> first(64, 0.25f);
    std::vector<float> second(128, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kSecondSound,
                             &secondPcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound)
            .contentRevision);
    image.MakeImmediateMixedVariableControlPlayWithSilentDiscreteSide();
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);
    const std::uint32_t playableBefore =
        engine->playableInstances.LiveCount();
    const std::uint32_t variableControlBefore =
        engine->variableControlInstances.LiveCount();
    const std::uint32_t voicesBefore = engine->voices.ActiveCount();
    const std::uint32_t decisionsBefore = engine->decisions.LiveCount();
    const std::uint32_t armsBefore = engine->timelineArms.LiveCount();
    const std::uint32_t armGroupsBefore = engine->armGroups.LiveCount();

    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
    EXPECT_EQ(VN_ACTION_FIRING_ACTIVE, info.state);
    EXPECT_EQ(image.actions[9].actionStableId, info.actionId);
    EXPECT_EQ(1u, info.livePlayableCount);
    VnActionStepResult play{};
    play.structSize = sizeof(play);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
    EXPECT_EQ(VN_ACTION_STEP_ACTIVE, play.state);
    EXPECT_EQ(VN_ACTION_OPCODE_PLAY, play.opcode);
    EXPECT_EQ(VN_ACTION_TARGET_CONTAINER, play.targetKind);
    EXPECT_EQ(image.containers[3].containerStableId, play.targetStableId);
    ASSERT_NE(0u, play.producedPlayableInstance);
    const auto producedRoot = play.producedPlayableInstance;

    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == producedRoot;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    EXPECT_TRUE(row->variableControlDiscreteSilent);
    ASSERT_TRUE(row->pendingImmediateEntry);
    const auto producer = std::find_if(
        engine->actionPlayScratch.begin(), engine->actionPlayScratch.end(),
        [&](const harken::EngineActionPlayScratch& candidate) {
            return candidate.row == &*row && candidate.variableControlCommitted;
        });
    ASSERT_NE(engine->actionPlayScratch.end(), producer);
    const auto entry = producer->frontierDescriptor.entry;
    ASSERT_TRUE(entry.Valid());
    ASSERT_TRUE(engine->decisions.Contains(entry.coordinator));
    EXPECT_EQ(0u, row->variableControlDiscreteMemberCount);
    EXPECT_EQ(1u, row->variableControlContinuousMemberCount);
    EXPECT_EQ(1u, row->scheduleLeafCount);
    EXPECT_FALSE(row->variableControlDiscreteDecision.Valid());
    EXPECT_TRUE(row->variableControlContinuousDecision.Valid());
    EXPECT_FALSE(row->variableControlDiscreteArmGroup.Valid());
    EXPECT_TRUE(row->variableControlContinuousArmGroup.Valid());
    const std::size_t continuousSlot = row->scheduleStorageBase +
        row->variableControlContinuousMemberOffset;
    ASSERT_LT(continuousSlot, engine->playableStorage.memberCount);
    EXPECT_EQ(CanonicalActionWorld::kSecondSound,
              engine->ReadPlayableMember(continuousSlot).leaf.stableId);
    const harken::VariableControlInstanceToken control =
        row->variableControlInstance;
    EXPECT_EQ(playableBefore + 2u, engine->playableInstances.LiveCount());
    EXPECT_EQ(variableControlBefore + 1u,
              engine->variableControlInstances.LiveCount());
    EXPECT_EQ(voicesBefore + 1u, engine->voices.ActiveCount());
    EXPECT_EQ(decisionsBefore + 2u, engine->decisions.LiveCount());
    EXPECT_EQ(armsBefore + 1u, engine->timelineArms.LiveCount());
    EXPECT_EQ(armGroupsBefore + 2u, engine->armGroups.LiveCount());

    const auto member = engine->ReadPlayableMember(continuousSlot).completion;
    const auto* source = engine->sourceTerminals.Resolve(member.source);
    ASSERT_NE(nullptr, source);
    const auto release = source->release;
    bool terminalSeen = false;
    harken::SourceTerminalPayload terminal{};
    bool leafRetired = false;
    bool entryPublished = false;
    for (std::uint32_t block = 0; block < 32 && !leafRetired; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        terminalSeen = engine->sourceTerminals.Capture(member.source,
            engine->mixer.BlocksRendered(), &terminal) || terminalSeen;
        ASSERT_EQ(VN_OK, Vn_Update());
        if (row->frontierEntry.Valid()) {
            EXPECT_TRUE(row->frontierEntry == entry);
            entryPublished = true;
        }
        leafRetired = engine->voices.ActiveCount() == voicesBefore &&
            !engine->playableInstances.Classify(member.leafInstance).live;
    }
    ASSERT_TRUE(leafRetired);
    ASSERT_TRUE(entryPublished);
    EXPECT_TRUE(terminalSeen);
    EXPECT_EQ(harken::SourceTerminalKind::Natural, terminal.kind);
    EXPECT_TRUE(engine->voices.ReleaseObserved(release));
    ASSERT_NO_FATAL_FAILURE(ExpectVariableControlNaturalCompletion(*engine, firing, &info));
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
    EXPECT_EQ(VN_ACTION_STEP_SUCCEEDED, play.state);
    EXPECT_EQ(producedRoot, play.producedPlayableInstance);
    harken::VariableControlInstanceSnapshot snapshot{};
    EXPECT_FALSE(engine->variableControlInstances.Capture(control, &snapshot));
    EXPECT_FALSE(engine->playableInstances
                     .Classify(producedRoot)
                     .live);
    EXPECT_EQ(playableBefore, engine->playableInstances.LiveCount());
    EXPECT_EQ(variableControlBefore,
              engine->variableControlInstances.LiveCount());
    EXPECT_EQ(voicesBefore, engine->voices.ActiveCount());
    ASSERT_NO_FATAL_FAILURE(ExpectTransferredDecisionsReclaimed(*engine, decisionsBefore));
    EXPECT_EQ(armsBefore, engine->timelineArms.LiveCount());
    EXPECT_EQ(armGroupsBefore, engine->armGroups.LiveCount());
    EXPECT_FALSE(engine->runtimeRecreateRequired);
    EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    EXPECT_EQ(0u, engine->actionFirings.LiveCount());
}

void ExpectImmediateVariableControlCompositePlayCompletes(bool segmentChild) {
    (void)Vn_Term();
    VnConfig config = harkentest::MakeNullConfig(8, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> first(64, 0.25f);
    std::vector<float> second(192, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kSecondSound,
                             &secondPcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound)
            .contentRevision);
    image.MakeImmediateVariableControlPlayAction();
    if (segmentChild) {
        image.MakeFirstVariableControlChildCompositeSegment();
    } else {
        image.MakeFirstVariableControlChildCompositeTrack();
    }
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));

    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
    EXPECT_EQ(VN_ACTION_FIRING_ACTIVE, info.state);
    EXPECT_EQ(1u, info.livePlayableCount);
    EXPECT_EQ(4u, engine->playableInstances.LiveCount());
    EXPECT_EQ(1u, engine->variableControlInstances.LiveCount());

    VnActionStepResult play{};
    play.structSize = sizeof(play);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
    EXPECT_EQ(VN_ACTION_STEP_ACTIVE, play.state);
    EXPECT_EQ(VN_ACTION_TARGET_CONTAINER, play.targetKind);
    ASSERT_NE(0u, play.producedPlayableInstance);
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == play.producedPlayableInstance;
    });
    ASSERT_NE(engine->playableServices.end(), row);
    ExpectVariableControlTree(*engine, *row, 1u, 2u);
    const harken::VariableControlInstanceToken control =
        row->variableControlInstance;
    EXPECT_TRUE(control.Valid());
    ASSERT_EQ(2u, row->scheduleLeafCount);
    ASSERT_EQ(2u, row->variableControlDiscreteMemberCount);
    const std::size_t base = row->scheduleStorageBase;
    ASSERT_LT(base + 1u, engine->playableStorage.memberCount);
    bool observedFirstLeaf = false;
    bool observedSecondLeaf = false;
    for (std::uint32_t index = 0; index < row->scheduleLeafCount; ++index) {
        const VnSoundId sound =
            engine->ReadPlayableMember(base + index).leaf.stableId;
        EXPECT_NE(0u,
                  engine->ReadPlayableMember(base + index).render);
        EXPECT_NE(nullptr,
                  engine->voices.Resolve(
                      engine->ReadPlayableMember(base + index).render));
        observedFirstLeaf = observedFirstLeaf ||
            sound == CanonicalActionWorld::kFirstSound;
        observedSecondLeaf = observedSecondLeaf ||
            sound == CanonicalActionWorld::kSecondSound;
    }
    EXPECT_TRUE(observedFirstLeaf);
    EXPECT_TRUE(observedSecondLeaf);
    EXPECT_EQ(2u, engine->voices.ActiveCount());

    bool observedPartialRetirement = false;
    for (std::uint32_t block = 0; block < 32; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
        if (engine->voices.ActiveCount() == 1u) {
            observedPartialRetirement = true;
            EXPECT_EQ(VN_ACTION_FIRING_ACTIVE, info.state);
            ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
            EXPECT_EQ(VN_ACTION_STEP_ACTIVE, play.state);
        }
        if (info.state == VN_ACTION_FIRING_TERMINAL_RETAINED) {
            break;
        }
    }

    EXPECT_TRUE(observedPartialRetirement);
    ASSERT_NO_FATAL_FAILURE(ExpectVariableControlNaturalCompletion(
            *engine, firing, &info));
    ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
    EXPECT_EQ(VN_ACTION_OUTCOME_SUCCEEDED, info.outcome);
    EXPECT_EQ(VN_ACTION_TERMINAL_NATURAL, info.terminalReason);
    EXPECT_EQ(0u, info.livePlayableCount);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
    EXPECT_EQ(VN_ACTION_STEP_SUCCEEDED, play.state);
    EXPECT_EQ(0u, engine->voices.ActiveCount());
    EXPECT_EQ(0u, engine->variableControlInstances.LiveCount());
    harken::VariableControlInstanceSnapshot snapshot{};
    EXPECT_FALSE(engine->variableControlInstances.Capture(control,
                                                           &snapshot));
    EXPECT_FALSE(engine->playableInstances
                     .Classify(play.producedPlayableInstance)
                     .live);
    EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
}

