void ExpectImmediateVariableControlOffsetTrackStartsFutureLeafWithoutAnotherUpdate(
    std::uint32_t offsetFrames) {
    (void)Vn_Term();
    constexpr std::uint32_t kBlockFrames = 64;
    harkentest::EngineSession session(
        harkentest::MakeNullConfig(8, kBlockFrames, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    std::vector<float> first(1024, 0.25f);
    std::vector<float> second(1024, -0.75f);
    const auto firstPcm = harkentest::MonoDesc(first, 48000);
    const auto secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK,
        Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK,
        Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &secondPcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound)
            .contentRevision);
    image.MakeImmediateVariableControlPlayAction();
    image.MakeFirstVariableControlChildCompositeTrack();
    image.trackPlacements[1].authoredStart =
        (static_cast<std::int64_t>(offsetFrames) * INT64_C(1000000000) +
            47999) / 48000;
    image.track.scheduleSemanticFingerprint =
        harken::ComputeTrackScheduleFingerprintV1(image.track);
    image.world.identity.runtimeSemanticFingerprint =
        harken::ComputeCurrentWorldFingerprintV4(image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
        harken::InstallContainerWorldV1(*engine, image.world).status);

    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    VnActionStepResult play{};
    play.structSize = sizeof(play);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
    EXPECT_EQ(VN_ACTION_STEP_ACTIVE, play.state) << play.result;
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [firing](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.InvocationValid() &&
                candidate.Invocation().actionFiring == firing;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    ASSERT_EQ(2u, row->scheduleLeafCount);
    ASSERT_TRUE(row->pendingImmediateEntry);
    engine->nullBackend.Pump(1);
    ASSERT_EQ(VN_OK, Vn_Update());
    harken::TimelineArmObservation firstArm{};
    harken::TimelineArmObservation secondArm{};
    const auto firstArmObserved = engine->timelineArms.Observe(
        engine->ReadPlayableMember(row->scheduleStorageBase).arm, &firstArm);
    const auto secondArmObserved = engine->timelineArms.Observe(
        engine->ReadPlayableMember(row->scheduleStorageBase + 1u).arm,
        &secondArm);
    SCOPED_TRACE(::testing::Message()
        << "phase=" << static_cast<int>(row->phase)
        << " firstArm=" << firstArmObserved << ":"
        << static_cast<int>(firstArm.state)
        << " secondArm=" << secondArmObserved << ":"
        << static_cast<int>(secondArm.state)
        << " blocks=" << engine->mixer.BlocksRendered()
        << " lane=" << row->immediateLane.Valid());
    ASSERT_FALSE(row->pendingImmediateEntry);
    const auto base = row->scheduleStorageBase;
    const auto firstStart = engine->ReadPlayableMember(base).startFrame;
    const auto secondStart = engine->ReadPlayableMember(base + 1u).startFrame;
    ASSERT_EQ(offsetFrames, secondStart - firstStart);

    bool heardFirst = false;
    bool heardSecond = false;
    const auto channels = engine->nullBackend.Channels();
    ASSERT_GT(channels, 0u);
    std::uint64_t firstNegativeFrame = UINT64_MAX;
    for (std::uint32_t block = 0; block < 24; ++block) {
        engine->nullBackend.Pump(1);
        const auto frame =
            (engine->mixer.BlocksRendered() - 1u) * kBlockFrames;
        const auto* output = engine->nullBackend.LastBlock();
        const auto sampleAt = [&](std::uint32_t sample) {
            return output[static_cast<std::size_t>(sample) * channels];
        };
        for (std::uint32_t sample = 0; sample < kBlockFrames; ++sample)
            if (sampleAt(sample) < -0.01f &&
                firstNegativeFrame == UINT64_MAX)
                firstNegativeFrame = frame + sample;
        if (frame < firstStart)
            EXPECT_TRUE(std::all_of(output,
                output + static_cast<std::size_t>(kBlockFrames) * channels,
                [](float sample) { return std::abs(sample) < 0.01f; }));
        if (frame >= firstStart && frame < secondStart) {
            const auto audibleFirst = static_cast<std::uint32_t>(
                std::min<std::uint64_t>(secondStart - frame, kBlockFrames));
            EXPECT_TRUE(std::all_of(output,
                output + static_cast<std::size_t>(audibleFirst) * channels,
                [](float sample) { return sample > -0.01f; }));
        }
        if (frame == firstStart)
            heardFirst = sampleAt(0) > 0.01f;
        if (frame == secondStart - secondStart % kBlockFrames) {
            const auto firstFutureSample = static_cast<std::uint32_t>(
                secondStart - frame);
            if (firstFutureSample != 0)
                EXPECT_GT(sampleAt(firstFutureSample - 1u), -0.01f);
            EXPECT_LT(sampleAt(firstFutureSample), -0.01f);
            heardSecond = sampleAt(firstFutureSample) < -0.01f;
        }
    }
    harken::TimelineArmObservation finalFirst{};
    harken::TimelineArmObservation finalSecond{};
    (void)engine->timelineArms.Observe(
        engine->ReadPlayableMember(base).arm, &finalFirst);
    (void)engine->timelineArms.Observe(
        engine->ReadPlayableMember(base + 1u).arm, &finalSecond);
    harken::ImmediateLaneObservation finalLane{};
    (void)engine->immediateActionLane.Observe(row->immediateLane, &finalLane);
    SCOPED_TRACE(::testing::Message()
        << "finalFirst=" << static_cast<int>(finalFirst.state)
        << " finalSecond=" << static_cast<int>(finalSecond.state)
        << " firstNegativeFrame=" << firstNegativeFrame
        << " secondStart=" << secondStart
        << " laneApplied=" << finalLane.applied
        << " laneMissed=" << finalLane.missed
        << " laneComplete=" << finalLane.complete);
    EXPECT_TRUE(heardFirst);
    EXPECT_TRUE(heardSecond);
    EXPECT_EQ(secondStart, firstNegativeFrame);
    EXPECT_FALSE(engine->runtimeRecreateRequired);
    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    ASSERT_EQ(VN_OK, Vn_Update());
    EXPECT_EQ(0u, engine->voices.ActiveCount());
    ASSERT_NO_FATAL_FAILURE(ExpectVariableControlNaturalTreeCompletion(
        *engine, firing, row->rootInstance, &info));
    ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
    EXPECT_EQ(VN_ACTION_OUTCOME_SUCCEEDED, info.outcome);
    EXPECT_EQ(VN_ACTION_TERMINAL_NATURAL, info.terminalReason);
    EXPECT_EQ(0u, engine->voices.ActiveCount());
    EXPECT_EQ(0u, engine->variableControlInstances.LiveCount());
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));

    VnActionFiringHandle replay = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &replay));
    engine->nullBackend.Pump(1);
    ASSERT_EQ(VN_OK, Vn_Update());
    bool replayHeard = false;
    for (std::uint32_t block = 0; block < 24; ++block) {
        engine->nullBackend.Pump(1);
        const auto* output = engine->nullBackend.LastBlock();
        replayHeard = replayHeard || std::any_of(
            output, output + static_cast<std::size_t>(kBlockFrames) * channels,
            [](float sample) { return sample < -0.01f; });
    }
    EXPECT_TRUE(replayHeard);
    ASSERT_EQ(VN_OK, Vn_Update());
    const auto replayRow = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [replay](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.InvocationValid() &&
                candidate.Invocation().actionFiring == replay;
        });
    ASSERT_NE(engine->playableServices.end(), replayRow);
    ASSERT_NO_FATAL_FAILURE(ExpectVariableControlNaturalTreeCompletion(
        *engine, replay, replayRow->rootInstance, &info));
    ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
    EXPECT_EQ(VN_ACTION_OUTCOME_SUCCEEDED, info.outcome);
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(replay));
}

