struct NestedQueueCancellationRace {
    std::atomic<bool> validated{false};
    std::atomic<bool> allowClaim{false};
    std::atomic<bool> claimed{false};
    std::atomic<bool> applied{false};
    std::atomic<bool> allowApply{false};
    std::atomic<bool> done{false};
    std::uint64_t mixerQuantum = UINT64_MAX;
    static void AfterMixerExecute(void* opaque, std::uint64_t quantum) noexcept {
        auto& state = *static_cast<NestedQueueCancellationRace*>(opaque);
        if (quantum != state.mixerQuantum) return;
        state.applied.store(true, std::memory_order_release);
        while (!state.allowApply.load(std::memory_order_acquire)) std::this_thread::yield();
    }
    static void AfterValidation(void* opaque) {
        auto& state = *static_cast<NestedQueueCancellationRace*>(opaque);
        state.validated.store(true, std::memory_order_release);
        while (!state.allowClaim.load(std::memory_order_acquire)) std::this_thread::yield();
    }
    static void AfterClaim(void* opaque) {
        auto& state = *static_cast<NestedQueueCancellationRace*>(opaque);
        state.claimed.store(true, std::memory_order_release);
        while (!state.allowApply.load(std::memory_order_acquire)) std::this_thread::yield();
    }
    static void AfterApplied(void* opaque, std::uint16_t sliceIndex) {
        if (sliceIndex != 1) return;
        auto& state = *static_cast<NestedQueueCancellationRace*>(opaque);
        state.applied.store(true, std::memory_order_release);
        while (!state.allowApply.load(std::memory_order_acquire)) std::this_thread::yield();
    }
    static void AfterPrescan(harken::Engine& engine, void* opaque) {
        engine.cancellationPrescanHookForTest = nullptr;
        auto& state = *static_cast<NestedQueueCancellationRace*>(opaque);
        state.allowClaim.store(true, std::memory_order_release);
        for (unsigned i = 0; i < 1000000 && !state.claimed.load(std::memory_order_acquire) &&
             !state.done.load(std::memory_order_acquire); ++i) std::this_thread::yield();
        EXPECT_TRUE(state.claimed.load(std::memory_order_acquire));
    }
};

static void CheckNestedQueueCancellationPostscanRace(
    bool wrap, bool afterApplied = false, bool invalidOwner = false,
    bool playbackOnly = false, bool refuseBinding = false,
    bool mixerFence = false, bool rejectForeignFuture = false,
    bool retainCompletion = false, bool expirePrelude = false) {
    harkentest::EngineSession session(harkentest::MakeNullConfig(4, 64, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    std::vector<float> first(retainCompletion ? 1027u : 1024u, 0.25f), second(1024, -0.25f);
    const auto firstPcm = harkentest::MonoDesc(first, 48000);
    const auto secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &secondPcm));
    CanonicalActionWorld image(engine->registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
    image.MakeImmediateNestedQueueVariableControlPlayAction();
    image.EnableImmediateVariableControlTransition(256, 192);
    image.containers[2].transitionProgramIndex = 0;
    image.containers[2].curves = image.containers[3].curves;
    image.containers[2].curveCount = image.containers[3].curveCount;
    image.containers[3].transitionProgramIndex = UINT32_MAX;
    image.containers[3].curves = nullptr;
    image.containers[3].curveCount = 0;
    image.transition.ownerContainerStableId = image.containers[2].containerStableId;
    image.transitionRules[0].sourceExit = harken::TransitionSourceExitV1::NaturalEnd;
    image.world.identity.runtimeSemanticFingerprint = harken::ComputeCurrentWorldFingerprintV4(image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok, harken::InstallContainerWorldV1(*engine, image.world).status);
    if (wrap) {
        for (std::uint32_t block = 0; block < engine->timelinePool.PageCount() - 18u; ++block) {
            engine->nullBackend.Pump(1);
            ASSERT_EQ(VN_OK, Vn_Update());
        }
    }
    VnEmitterHandle emitter = 0;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&emitter));
    auto desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    desc.emitter = emitter;
    const auto ownersBefore = CaptureActionReclaimableOwners(*engine);
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    auto child = std::find_if(engine->playableServices.begin(), engine->playableServices.end(),
        [](const auto& row) { return row.queueMode && row.parentService.Valid(); });
    ASSERT_NE(engine->playableServices.end(), child);
    const auto* parent = engine->ResolvePlayableService(child->parentService);
    ASSERT_NE(nullptr, parent);
    const auto root = parent->rootInstance;
    const auto initialSourceArm = child->arm;
    ASSERT_TRUE(parent->variableControlInstance.Valid());
    if (refuseBinding) engine->forceImmediateLaneBindLeafFailureForTest = 0;
    engine->nullBackend.Pump(1);
    ASSERT_EQ(VN_OK, Vn_Update());
    EXPECT_FALSE(engine->runtimeRecreateRequired);
    if (refuseBinding) {
        EXPECT_EQ(UINT32_MAX, engine->forceImmediateLaneBindLeafFailureForTest);
        VnActionFiringInfo refused{};
        refused.structSize = sizeof(refused);
        bool heard = false;
        for (unsigned block = 0; block < 96u; ++block) {
            engine->nullBackend.Pump(1);
            const auto* output = engine->nullBackend.LastBlock();
            heard = heard || std::any_of(output, output + 64u * engine->nullBackend.Channels(),
                [](float sample) { return std::abs(sample) > 0.01f; });
            ASSERT_EQ(VN_OK, Vn_Update());
            ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &refused));
            if (refused.state == VN_ACTION_FIRING_TERMINAL_RETAINED &&
                engine->playablePartitions.OccupiedCount() == 0u) break;
        }
        EXPECT_FALSE(heard);
        ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, refused.state);
        EXPECT_EQ(0u, engine->playablePartitions.OccupiedCount());
        EXPECT_EQ(0u, engine->queueInstances.LiveCount());
        EXPECT_EQ(0u, engine->voices.ActiveCount());
        EXPECT_FALSE(engine->runtimeRecreateRequired);
        ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
        EXPECT_EQ(ownersBefore, CaptureActionReclaimableOwners(*engine));
        return;
    }
    const auto entry = parent->frontierEntry;
    const auto* initialActivation = engine->decisions.ResolveFrontierActivation(entry.coordinator);
    ASSERT_NE(nullptr, initialActivation);
    const auto initialQuantum =
        initialActivation->Descriptor().order.executeFrame / 64u;
    while (engine->mixer.BlocksRendered() <= initialQuantum) {
        engine->nullBackend.Pump(1);
    }
    harken::FrontierActivationReceipt initialReceipt{};
    ASSERT_EQ(harken::FrontierReceiptRead::Ready,
        initialActivation->Read(entry, engine->mixer.BlocksRendered(), &initialReceipt));
    ASSERT_EQ(harken::FrontierReceiptOutcome::Applied, initialReceipt.outcome);
    ASSERT_EQ(VN_OK, Vn_Update());
    EXPECT_FALSE(engine->runtimeRecreateRequired);
    const auto future = std::find_if(engine->queueFutureRecords.begin(),
        engine->queueFutureRecords.end(), [&](const auto& record) {
            return record.occupied && record.service == child->identity &&
                record.root == firing;
        });
    ASSERT_NE(engine->queueFutureRecords.end(), future);
    ASSERT_TRUE(future->sourceMember.Exact());
    ASSERT_TRUE(future->targetMember.Exact());
    // The same full Decision owns source completion and both frozen slices.
    const auto decision = future->memberDecision;
    ASSERT_TRUE(child->QueuePayload().canonicalInitialQueueDecision.Valid());
    EXPECT_EQ(decision.slot, child->QueuePayload().canonicalInitialQueueDecision.slot);
    EXPECT_EQ(decision.generation, child->QueuePayload().canonicalInitialQueueDecision.generation);
    EXPECT_EQ(decision.slot, child->QueueFiling().queueDecision.slot);
    EXPECT_EQ(decision.generation, child->QueueFiling().queueDecision.generation);
    EXPECT_EQ(decision.slot, child->QueuePayload().queueCurrentCompletion.owner.singleDecision.slot);
    EXPECT_EQ(decision.generation, child->QueuePayload().queueCurrentCompletion.owner.singleDecision.generation);
    EXPECT_EQ(nullptr, child->QueuePayload().privateInitialQueueCurrent);
    const auto preludeQuantum = future->descriptor.order.executeFrame / 64u;
    const auto completionQuantum = child->QueuePayload().queueCompletionFrame / 64u;
    if (wrap) EXPECT_GT(preludeQuantum % engine->timelinePool.PageCount(),
        completionQuantum % engine->timelinePool.PageCount());
    while (engine->mixer.BlocksRendered() < preludeQuantum) {
        engine->nullBackend.Pump(1);
    }
    std::array<harken::Plan03PageGroupView, 8> groups{};
    const auto count = engine->timelinePool.CaptureLivePlan03Groups(groups.data(), groups.size());
    ASSERT_LE(count, groups.size());
    harken::Plan03PageGroupView prelude{}, completion{};
    for (std::size_t i = 0; i < count; ++i) {
        if (groups[i].identity == future->sourceMember) prelude = groups[i];
        if (groups[i].identity == future->targetMember) completion = groups[i];
    }
    ASSERT_NE(nullptr, prelude.lease);
    ASSERT_NE(nullptr, completion.lease);
    if (wrap && prelude.identity.backing == harken::Plan03GroupBacking::Page)
        EXPECT_NE(prelude.identity.pageGeneration, completion.identity.pageGeneration);
    if (prelude.identity.backing == harken::Plan03GroupBacking::Page)
        EXPECT_EQ(preludeQuantum, engine->timelinePool.PageStamp(preludeQuantum));
    if (expirePrelude) {
        ASSERT_EQ(harken::Plan03GroupBacking::ImmediateLane, prelude.identity.backing);
        ASSERT_EQ(2u, prelude.memberCount);
        const auto targetArm = prelude.members[1];
        const auto lane = child->immediateLane;
        ASSERT_TRUE(lane.Valid());
        harken::QueueInstanceSnapshot before{};
        ASSERT_TRUE(engine->queueInstances.Capture(child->queueInstance, &before));
        const auto* bucket = engine->immediateActionLane.CaptureDue(lane.slot, preludeQuantum);
        ASSERT_NE(nullptr, bucket);
        ASSERT_EQ(preludeQuantum, bucket->quantum);
        ASSERT_EQ(0u, bucket->sourceWaitSequence.load(std::memory_order_acquire));
        engine->nullBackend.Pump(1);
        ASSERT_EQ(preludeQuantum + 1u, engine->mixer.BlocksRendered());
        ASSERT_TRUE(engine->immediateActionLane.ReleaseCapture(lane.slot, bucket));
        engine->nullBackend.Pump(1);
        EXPECT_NE(harken::AudioSliceState::SliceApplied, prelude.lease->Capture().state);
        EXPECT_NE(harken::AudioSliceState::SliceApplied, completion.lease->Capture().state);
        harken::DecisionCommittedSnapshot unconsumed{};
        ASSERT_TRUE(engine->decisions.CaptureCommitted(decision, &unconsumed));
        EXPECT_EQ(0u, unconsumed.consumedSlices);
        harken::TimelineArmObservation target{};
        ASSERT_TRUE(engine->timelineArms.Observe(targetArm, &target));
        EXPECT_EQ(0u, target.startedBlockSequence);
        harken::QueueInstanceSnapshot after{};
        ASSERT_TRUE(engine->queueInstances.Capture(child->queueInstance, &after));
        EXPECT_EQ(before.logicMirror.version, after.logicMirror.version);
        EXPECT_NE(harken::ConditionalQueueActivation::Activated, after.pendingActivation);
        VnActionFiringInfo terminal{};
        terminal.structSize = sizeof(terminal);
        bool targetHeard = false;
        for (unsigned block = 0; block < 96u; ++block) {
            engine->nullBackend.Pump(1);
            const auto* output = engine->nullBackend.LastBlock();
            targetHeard = targetHeard || std::any_of(output, output + 64u * engine->nullBackend.Channels(),
                [](float sample) { return sample < -0.0001f; });
            ASSERT_EQ(VN_OK, Vn_Update());
            ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &terminal));
            if (terminal.state == VN_ACTION_FIRING_TERMINAL_RETAINED &&
                engine->playablePartitions.OccupiedCount() == 0u) break;
        }
        EXPECT_FALSE(targetHeard);
        EXPECT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, terminal.state);
        EXPECT_EQ(0u, engine->playablePartitions.OccupiedCount());
        EXPECT_EQ(0u, engine->queueInstances.LiveCount());
        EXPECT_EQ(0u, engine->voices.ActiveCount());
        EXPECT_FALSE(engine->runtimeRecreateRequired);
        ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
        EXPECT_EQ(ownersBefore, CaptureActionReclaimableOwners(*engine));
        return;
    }
    if (playbackOnly) {
        ASSERT_EQ(harken::Plan03GroupBacking::ImmediateLane, prelude.identity.backing);
        ASSERT_EQ(2u, prelude.memberCount);
        const auto targetArm = prelude.members[1];
        harken::DecisionCommittedSnapshot before{};
        ASSERT_TRUE(engine->decisions.CaptureCommitted(decision, &before));
        EXPECT_EQ(prelude.frontier->transition.Valid(), before.transitionGate.Valid());
        harken::TransitionInstanceSnapshot transition{};
        ASSERT_TRUE(engine->transitionInstances.Capture(child->QueueFiling().queueTransition, &transition));
        engine->nullBackend.Pump(1);
        EXPECT_EQ(preludeQuantum + 1u, engine->mixer.BlocksRendered());
        EXPECT_EQ(harken::AudioSliceState::SliceApplied, prelude.lease->Capture().state);
        harken::DecisionCommittedSnapshot sourceApplied{};
        ASSERT_TRUE(engine->decisions.CaptureCommitted(decision, &sourceApplied));
        EXPECT_EQ(1u, sourceApplied.consumedSlices);
        EXPECT_EQ(preludeQuantum + 1u, sourceApplied.lastAudioSequence);
        harken::QueueInstanceSnapshot beforeTarget{};
        ASSERT_TRUE(engine->queueInstances.Capture(child->queueInstance, &beforeTarget));
        EXPECT_EQ(harken::ConditionalQueueActivation::Waiting, beforeTarget.pendingActivation);
        ASSERT_TRUE(completion.frontier->canonicalInitialCompletion);
        ASSERT_EQ(harken::FrontierGroupRole::Future, completion.frontier->role);
        const auto nextVersion = completion.frontier->queueInitialCompletion.pendingVersion;
        std::uint64_t actualCompletionQuantum = completionQuantum;
        if (retainCompletion) {
            ASSERT_EQ(3u, completion.frontier->operation.order.executeFrame % 64u);
            while (engine->mixer.BlocksRendered() < completionQuantum)
                engine->nullBackend.Pump(1);
            const auto lane = child->immediateLane;
            ASSERT_TRUE(lane.Valid());
            const harken::ImmediateLaneBucket* original = nullptr;
            for (unsigned retained = 0; retained < 5u; ++retained) {
                const auto quantum = engine->mixer.BlocksRendered();
                const auto* bucket = engine->immediateActionLane.CaptureDue(lane.slot, quantum);
                ASSERT_NE(nullptr, bucket);
                ASSERT_EQ(lane.generation, bucket->attemptGeneration);
                ASSERT_EQ(completionQuantum, bucket->quantum);
                if (original == nullptr) original = bucket;
                else ASSERT_EQ(original, bucket);
                const auto* captured = engine->immediateActionLane.Groups(lane.slot, bucket);
                ASSERT_NE(nullptr, captured);
                ASSERT_EQ(1u, bucket->groupCount);
                ASSERT_EQ(completion.identity, captured[0].identity);
                ASSERT_EQ(1u, bucket->memberCount);
                ASSERT_EQ(harken::AudioSliceState::Ready, completion.lease->Capture().state);
                engine->nullBackend.Pump(1);
                ASSERT_EQ(quantum + 1u, engine->mixer.BlocksRendered());
                ASSERT_TRUE(engine->immediateActionLane.SuspendCaptureForSourceWait(
                    lane.slot, bucket, &completion.frontier->entry, 1u));
                harken::DecisionCommittedSnapshot retainedDecision{};
                ASSERT_TRUE(engine->decisions.CaptureCommitted(decision, &retainedDecision));
                ASSERT_EQ(1u, retainedDecision.consumedSlices);
                ASSERT_EQ(harken::AudioSliceState::Ready, completion.lease->Capture().state);
                const auto* retainedOutput = engine->nullBackend.LastBlock();
                for (unsigned frame = retained == 0u ? 3u : 0u; frame < 64u; ++frame)
                    EXPECT_NEAR(0.0f, retainedOutput[frame * engine->nullBackend.Channels()], 1e-7f);
            }
            actualCompletionQuantum = engine->mixer.BlocksRendered();
            ASSERT_EQ(completionQuantum + 5u, actualCompletionQuantum);
            harken::CompletionProgressSnapshot progress{};
            const auto* progressRow = engine->timelineOccurrences.CompletionProgressOf(child->QueuePayload().queueCurrentOccurrence);
            ASSERT_NE(nullptr, progressRow);
            ASSERT_TRUE(harken::CaptureCompletionProgressExact(
                *progressRow,
                child->QueuePayload().queueCurrentOccurrence, initialSourceArm.renderGeneration, &progress));
            ASSERT_EQ(first.size(), progress.logicalOutputFramesProduced);
            ASSERT_LE(progress.completedThroughBlockSequence, actualCompletionQuantum);
        }
        while (engine->mixer.BlocksRendered() <= actualCompletionQuantum)
            engine->nullBackend.Pump(1);
        EXPECT_EQ(harken::AudioSliceState::SliceApplied, completion.lease->Capture().state);
        harken::QueueInstanceSnapshot activated{};
        ASSERT_TRUE(engine->queueInstances.Capture(child->queueInstance, &activated));
        EXPECT_EQ(harken::ConditionalQueueActivation::Activated, activated.pendingActivation);
        EXPECT_EQ(beforeTarget.logicMirror.version, activated.logicMirror.version);
        EXPECT_EQ(nextVersion, activated.pendingVersion);
        harken::DecisionCommittedSnapshot complete{};
        ASSERT_TRUE(engine->decisions.CaptureCommitted(decision, &complete));
        EXPECT_EQ(2u, complete.consumedSlices);
        EXPECT_EQ(actualCompletionQuantum + 1u, complete.lastAudioSequence);
        harken::TimelineArmObservation target{};
        ASSERT_TRUE(engine->timelineArms.Observe(targetArm, &target));
        EXPECT_EQ(actualCompletionQuantum + 1u, target.startedBlockSequence);
        const auto* output = engine->nullBackend.LastBlock();
        ASSERT_NE(nullptr, output);
        EXPECT_TRUE(std::any_of(output, output + engine->config.blockFrames,
            [](float sample) { return sample < -0.0001f; }));
        if (retainCompletion) {
            EXPECT_LT(output[0], -0.0001f);
            testing::Test::RecordProperty("completion_recovery_quantum", std::to_string(actualCompletionQuantum));
        }
        EXPECT_FALSE(engine->runtimeRecreateRequired);
        VnActionFiringInfo natural{};
        natural.structSize = sizeof(natural);
        for (unsigned block = 0; block < 96u; ++block) {
            engine->nullBackend.Pump(1);
            ASSERT_EQ(VN_OK, Vn_Update());
            ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &natural));
            if (natural.state == VN_ACTION_FIRING_TERMINAL_RETAINED &&
                engine->playablePartitions.OccupiedCount() == 0u) break;
        }
        EXPECT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, natural.state);
        EXPECT_EQ(0u, engine->playablePartitions.OccupiedCount());
        EXPECT_EQ(0u, engine->queueInstances.LiveCount());
        EXPECT_EQ(0u, engine->voices.ActiveCount());
        EXPECT_FALSE(engine->runtimeRecreateRequired);
        ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
        EXPECT_EQ(ownersBefore, CaptureActionReclaimableOwners(*engine));
        return;
    }
    if (invalidOwner) {
        harken::SourceTerminalRecord* source = nullptr;
        for (std::uint32_t slot = 0; slot < engine->sourceTerminals.Capacity(); ++slot) {
            auto* candidate = engine->sourceTerminals.At(slot);
            if (candidate->occupied && candidate->render == child->renderHandle) source = candidate;
        }
        ASSERT_NE(nullptr, source);
        const auto savedOwner = source->resourceOwner;
        ++source->resourceOwner.epoch;
        const auto before = CaptureActionPreparationOwners(*engine);
        const auto phase = parent->phase;
        const auto lifecycle = parent->controlLifecycle;
        EXPECT_EQ(VN_BACKPRESSURE, Vn_StopActionFiring(firing, 3));
        ExpectActionPreparationOwnersUnchanged(*engine, before);
        EXPECT_EQ(phase, parent->phase);
        EXPECT_EQ(lifecycle, parent->controlLifecycle);
        EXPECT_EQ(0u, parent->pendingCancellationIntent);
        EXPECT_FALSE(parent->variableControlDeferredCancellation);
        EXPECT_EQ(harken::AudioSliceState::Ready, prelude.lease->Capture().state);
        EXPECT_EQ(harken::AudioSliceState::Ready, completion.lease->Capture().state);
        EXPECT_FALSE(engine->runtimeRecreateRequired);
        source->resourceOwner = savedOwner;
        return;
    }
    if (afterApplied) {
        while (engine->mixer.BlocksRendered() < completionQuantum) {
            engine->nullBackend.Pump(1);
            ASSERT_EQ(VN_OK, Vn_Update());
        }
    }
    std::vector<harken::TimelineArmObservation> members(prelude.memberCount);
    if (!afterApplied) {
        for (std::uint16_t i = 0; i < prelude.memberCount; ++i)
            ASSERT_TRUE(engine->timelineArms.Observe(prelude.members[i], &members[i]));
    }
    NestedQueueCancellationRace race;
    harken::detail::QueueCancellationRaceTestAccess::SelectLaneGroup(engine->timelineSink,
        afterApplied ? completion.identity : prelude.identity);
    if (mixerFence) {
        race.mixerQuantum = completionQuantum;
        engine->mixer.SetTimelineFinalizedHookForTest(&NestedQueueCancellationRace::AfterMixerExecute, &race);
    } else if (afterApplied) {
        harken::detail::QueueCancellationRaceTestAccess::SetAppliedHook(
            engine->timelineSink, &NestedQueueCancellationRace::AfterApplied, &race);
    } else {
        harken::detail::QueueCancellationRaceTestAccess::SetHooks(engine->timelineSink,
            &NestedQueueCancellationRace::AfterValidation, &NestedQueueCancellationRace::AfterClaim, &race);
        engine->cancellationPrescanHookForTest = &NestedQueueCancellationRace::AfterPrescan;
        engine->cancellationPrescanContextForTest = &race;
    }
    std::thread audio([&] { engine->nullBackend.Pump(1); race.done.store(true, std::memory_order_release); });
    const auto paused = [&] {
        return afterApplied ? race.applied.load(std::memory_order_acquire)
                            : race.validated.load(std::memory_order_acquire);
    };
    for (unsigned i = 0; i < 1000000 && !paused() &&
         !race.done.load(std::memory_order_acquire); ++i) std::this_thread::yield();
    const bool reached = paused();
    if (reached) {
        if (afterApplied) {
            harken::DecisionCommittedSnapshot applied{};
            EXPECT_TRUE(engine->decisions.CaptureCommitted(decision, &applied));
            EXPECT_EQ(2u, applied.consumedSlices);
            EXPECT_EQ(completionQuantum + 1u, applied.lastAudioSequence);
            EXPECT_EQ(completionQuantum, engine->mixer.BlocksRendered());
            EXPECT_EQ(harken::AudioSliceState::SliceApplied, completion.lease->Capture().state);
            for (std::uint16_t i = 0; i < prelude.memberCount; ++i)
                EXPECT_TRUE(engine->timelineArms.Observe(prelude.members[i], &members[i]));
        }
        EXPECT_EQ(harken::PlayableControlStatus::Ok, harken::StopPlayable(*engine, root, 3));
        EXPECT_NE(0u, parent->pendingCancellationIntent);
        EXPECT_TRUE(parent->variableControlDeferredCancellation);
        const auto deferred = parent->variableControlDeferredCancellationSlice;
        EXPECT_EQ(decision.slot, deferred.decision.slot);
        EXPECT_EQ(decision.generation, deferred.decision.generation);
        EXPECT_LT(deferred.sliceIndex, 2u);
        const auto& savedSlice = deferred.sliceIndex == 0 ? prelude : completion;
        EXPECT_EQ(savedSlice.identity.absoluteQuantum, deferred.absoluteQuantum);
        EXPECT_EQ(savedSlice.identity.pageGeneration, deferred.pageGeneration);
        if (!afterApplied) {
            EXPECT_TRUE(race.claimed.load(std::memory_order_acquire));
            EXPECT_EQ(harken::AudioSliceState::Ready, completion.lease->Capture().state);
        }
        for (std::uint16_t i = 0; i < prelude.memberCount; ++i) {
            harken::TimelineArmObservation current{};
            EXPECT_TRUE(engine->timelineArms.Observe(prelude.members[i], &current));
            EXPECT_EQ(members[i].state, current.state);
        }
        const auto published = engine->commands.PublishedHead();
        EXPECT_EQ(harken::PlayableControlStatus::Ok, harken::StopPlayable(*engine, root, 99));
        EXPECT_EQ(published, engine->commands.PublishedHead());
        EXPECT_EQ(3u, parent->pendingCancellationFadeMs);
        if (afterApplied) {
            EXPECT_EQ(VN_OK, Vn_Update());
            EXPECT_NE(0u, parent->pendingCancellationIntent);
            EXPECT_TRUE(parent->variableControlDeferredCancellation);
            const auto unchanged = parent->variableControlDeferredCancellationSlice;
            EXPECT_EQ(deferred.decision.slot, unchanged.decision.slot);
            EXPECT_EQ(deferred.decision.generation, unchanged.decision.generation);
            EXPECT_EQ(deferred.absoluteQuantum, unchanged.absoluteQuantum);
            EXPECT_EQ(deferred.pageGeneration, unchanged.pageGeneration);
            EXPECT_EQ(deferred.sliceIndex, unchanged.sliceIndex);
            for (std::uint16_t i = 0; i < prelude.memberCount; ++i) {
                harken::TimelineArmObservation current{};
                EXPECT_TRUE(engine->timelineArms.Observe(prelude.members[i], &current));
                EXPECT_EQ(members[i].state, current.state);
            }
            EXPECT_EQ(completionQuantum, engine->mixer.BlocksRendered());
        }
    }
    race.allowClaim.store(true, std::memory_order_release);
    race.allowApply.store(true, std::memory_order_release);
    audio.join();
    engine->mixer.SetTimelineFinalizedHookForTest(nullptr, nullptr);
    harken::detail::QueueCancellationRaceTestAccess::SelectLaneGroup(engine->timelineSink, {});
    engine->cancellationPrescanHookForTest = nullptr;
    engine->cancellationPrescanContextForTest = nullptr;
    harken::detail::QueueCancellationRaceTestAccess::SetHooks(engine->timelineSink, nullptr, nullptr, nullptr);
    harken::detail::QueueCancellationRaceTestAccess::SetAppliedHook(engine->timelineSink, nullptr, nullptr);
    ASSERT_TRUE(reached);
    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    for (unsigned block = 0; block < 96; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
        if (info.state == VN_ACTION_FIRING_TERMINAL_RETAINED &&
            engine->playablePartitions.OccupiedCount() == 0) break;
    }
    ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
    ASSERT_EQ(0u, engine->playablePartitions.OccupiedCount());
    ASSERT_EQ(0u, engine->queueInstances.LiveCount());
    ASSERT_EQ(0u, engine->voices.ActiveCount());
    ASSERT_FALSE(engine->runtimeRecreateRequired);
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    EXPECT_EQ(ownersBefore, CaptureActionReclaimableOwners(*engine));
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    const auto replay = std::find_if(engine->playableServices.begin(), engine->playableServices.end(),
        [](const auto& row) { return row.queueMode && row.parentService.Valid(); });
    ASSERT_NE(engine->playableServices.end(), replay);
    const auto arm = replay->arm;
    EXPECT_FALSE(arm.slot == initialSourceArm.slot && arm.generation == initialSourceArm.generation &&
        arm.renderSlot == initialSourceArm.renderSlot && arm.renderGeneration == initialSourceArm.renderGeneration);
    const auto replayDecision = replay->initialQueueEntryDecision;
    ASSERT_TRUE(replayDecision.Valid());
    EXPECT_FALSE(replayDecision.slot == decision.slot && replayDecision.generation == decision.generation);
    engine->nullBackend.Pump(1);
    ASSERT_EQ(VN_OK, Vn_Update());
    harken::EngineTimelineVoiceInstallIdentity installation{};
    ASSERT_EQ(replayDecision.slot, replay->initialQueueEntryDecision.slot);
    ASSERT_EQ(replayDecision.generation, replay->initialQueueEntryDecision.generation);
    ASSERT_EQ(replayDecision.slot, replay->QueueFiling().queueDecision.slot);
    ASSERT_EQ(replayDecision.generation, replay->QueueFiling().queueDecision.generation);
    ASSERT_TRUE(engine->CaptureTimelineVoiceInstallIdentity(replay->renderHandle, &installation));
    ASSERT_EQ(arm.slot, installation.startArm.slot);
    ASSERT_EQ(arm.generation, installation.startArm.generation);
    ASSERT_EQ(arm.renderSlot, installation.startArm.renderSlot);
    ASSERT_EQ(arm.renderGeneration, installation.startArm.renderGeneration);
    EXPECT_EQ(replay->startFrame, installation.onsetFrame);
    const auto plannedBlock = installation.onsetFrame / engine->config.blockFrames + 1u;
    ASSERT_GT(plannedBlock, engine->mixer.BlocksRendered());
    bool started = false;
    for (unsigned block = 0; block < 32 && !started; ++block) {
        engine->nullBackend.Pump(1);
        harken::TimelineArmObservation observation{};
        if (engine->timelineArms.Observe(arm, &observation) && observation.startedBlockSequence != 0) {
            started = true;
            EXPECT_EQ(plannedBlock, observation.startedBlockSequence);
            EXPECT_EQ(engine->mixer.BlocksRendered(), observation.startedBlockSequence);
            const auto* pcm = engine->nullBackend.LastBlock();
            ASSERT_NE(nullptr, pcm);
            EXPECT_TRUE(std::any_of(pcm, pcm + engine->config.blockFrames,
                [](float sample) { return sample > 0.0001f; }));
        }
        ASSERT_EQ(VN_OK, Vn_Update());
    }
    EXPECT_TRUE(started);
    EXPECT_FALSE(engine->runtimeRecreateRequired);
    ASSERT_EQ(VN_OK, Vn_StopActionFiring(firing, 0));
    if (rejectForeignFuture) {
        auto activeAttempt = std::find_if(engine->immediateEntryAttempts.data(),
            engine->immediateEntryAttempts.data() + engine->immediateEntryAttempts.size(),
            [&](const auto& attempt) { return attempt.active && attempt.root == firing; });
        ASSERT_NE(engine->immediateEntryAttempts.data() + engine->immediateEntryAttempts.size(), activeAttempt);
        harken::ImmediateLaneObservation cancelledLane{};
        ASSERT_TRUE(engine->immediateActionLane.Observe(activeAttempt->lane, &cancelledLane));
        ASSERT_TRUE(cancelledLane.committed);
        ASSERT_TRUE(cancelledLane.complete);
        ASSERT_TRUE(cancelledLane.cancelled);
        ASSERT_FALSE(cancelledLane.missed);
        ASSERT_FALSE(cancelledLane.claimed);
        ASSERT_EQ(1u, activeAttempt->queueFutureCount);
        ASSERT_LT(activeAttempt->queueFutureHead, engine->queueFutureRecords.size());
        auto& retained = engine->queueFutureRecords[activeAttempt->queueFutureHead];
        const auto expectedEntry = retained.descriptor.entry;
        const auto parentEntry = retained.parentEntry;
        const auto bindingEntry = retained.bindingArmPinEntry;
        const auto prerequisite = retained.prerequisiteMember;
        const auto sourceMember = retained.sourceMember;
        const auto service = retained.service;
        harken::FrontierActivationSidecarSnapshot before{};
        const auto publishedBlock = engine->mixer.BlocksRendered();
        ASSERT_TRUE(engine->decisions.CaptureFrontierActivationSidecar(retained.coordinator,
            expectedEntry, publishedBlock, &before));
        ASSERT_EQ(harken::FrontierReceiptRead::InFlight, before.receiptRead);
        ASSERT_TRUE(before.pagePinHeld);
        ASSERT_TRUE(before.observerPinHeld);
        harken::DecisionCommittedSnapshot memberBefore{};
        ASSERT_TRUE(engine->decisions.CaptureCommitted(retained.memberDecision, &memberBefore));
        for (unsigned mismatch = 0; mismatch < 5u; ++mismatch) {
            SCOPED_TRACE(mismatch);
            switch (mismatch) {
                case 0: ++retained.parentEntry.coordinator.generation; break;
                case 1: ++retained.bindingArmPinEntry.coordinator.generation; break;
                case 2: ++retained.prerequisiteMember.rowClaimGeneration; break;
                case 3: ++retained.sourceMember.decision.generation; break;
                case 4: ++retained.service.generation; break;
            }
            ASSERT_EQ(VN_OK, Vn_Update());
            ASSERT_EQ(publishedBlock, engine->mixer.BlocksRendered());
            harken::FrontierActivationSidecarSnapshot held{};
            ASSERT_TRUE(engine->decisions.CaptureFrontierActivationSidecar(retained.coordinator,
                expectedEntry, publishedBlock, &held));
            EXPECT_EQ(before.state, held.state);
            EXPECT_EQ(harken::FrontierReceiptRead::InFlight, held.receiptRead);
            EXPECT_TRUE(held.pagePinHeld);
            EXPECT_TRUE(held.observerPinHeld);
            EXPECT_TRUE(retained.parentPin.Valid());
            EXPECT_TRUE(retained.prerequisiteMemberPin.Valid());
            EXPECT_TRUE(activeAttempt->lane.Valid());
            harken::DecisionCommittedSnapshot unchanged{};
            ASSERT_TRUE(engine->decisions.CaptureCommitted(retained.memberDecision, &unchanged));
            EXPECT_EQ(memberBefore.consumedSlices, unchanged.consumedSlices);
            EXPECT_EQ(memberBefore.lastAudioSequence, unchanged.lastAudioSequence);
            retained.parentEntry = parentEntry;
            retained.bindingArmPinEntry = bindingEntry;
            retained.prerequisiteMember = prerequisite;
            retained.sourceMember = sourceMember;
            retained.service = service;
        }
    }
    for (unsigned block = 0; block < 96 && engine->playablePartitions.OccupiedCount() != 0; ++block) {
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
    }
    EXPECT_EQ(0u, engine->playablePartitions.OccupiedCount());
    EXPECT_EQ(0u, engine->voices.ActiveCount());
    EXPECT_FALSE(engine->runtimeRecreateRequired);
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
    EXPECT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    EXPECT_EQ(ownersBefore, CaptureActionReclaimableOwners(*engine));
}

