            ASSERT_EQ(VN_OK, Vn_Update());
            ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &stopped));
            if (stopped.state == VN_ACTION_FIRING_TERMINAL_RETAINED) break;
