void AddIndependentSecondSoundPlayAction(CanonicalActionWorld& image);

void ExpectImmediateShortQueueMirrorFaultRejected(std::uint32_t fault,
    bool blockSecondStop = false, bool dropFirstTerminal = false,
    bool claimedReaderSibling = false) {
    SCOPED_TRACE(fault);
    (void)Vn_Term();
    constexpr std::uint32_t kFrames = 64;
    harkentest::EngineSession session(harkentest::MakeNullConfig(4, kFrames, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    std::vector<float> first(1024, 0.25f);
    std::vector<float> second(1024, -0.25f);
    const auto firstPcm = harkentest::MonoDesc(first, 48000);
    const auto secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &secondPcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
    image.MakeImmediateNestedQueueVariableControlPlayAction();
    if (claimedReaderSibling) AddIndependentSecondSoundPlayAction(image);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
        harken::InstallContainerWorldV1(*engine, image.world).status);
    VnEmitterHandle emitter = 0;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&emitter));
    const auto decisionBaseline = engine->decisions.LiveCount();
    const auto armGroupBaseline = engine->armGroups.LiveCount();
    const auto armBaseline = engine->timelineArms.LiveCount();
    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    desc.emitter = emitter;
    VnActionFiringHandle failed = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &failed));
    const auto holder = std::find_if(engine->playableServices.begin(),
        engine->playableServices.end(), [&](const auto& row) {
            return row.queueMode && row.parentService.Valid() &&
                row.InvocationValid() && row.Invocation().actionFiring == failed;
        });
    ASSERT_NE(engine->playableServices.end(), holder);
    ASSERT_TRUE(holder->queueFirstContinuationLane);
    ASSERT_NE(nullptr, holder->QueueFiling().queueSuccessorProgramBank);
    ASSERT_TRUE(holder->QueueFiling().queueSuccessorArm.Valid());
    const auto initialArmGroup = holder->QueuePayload().queueInitialLaneArmGroup;
    const auto successorArmGroup = holder->QueueFiling().queueArmGroup;
    const auto initialDecision = holder->initialQueueEntryDecision;
    const auto queueDecision = holder->QueueFiling().queueDecision;
    auto& aggregate = holder->QueueFiling().queueSuccessorProgramPlane == 0
        ? holder->schedule : holder->QueueFiling().queueSuccessorSchedule;
    const auto* successorMember = engine->FindQueueSuccessorMember(*holder, 0);
    ASSERT_NE(nullptr, successorMember);
    const auto successorMemberToken = holder->QueueFiling().queueSuccessorProgramBank->members[holder->QueueFiling().queueSuccessorPrograms.first];
    const auto oldPhysicalStart = successorMember->startFrame;
    const auto oldAggregateAnchor = aggregate.entryAnchorFrame;
    const auto oldInstallOnset = engine->timelineVoiceInstallIdentities[
        holder->QueueFiling().queueSuccessorArm.renderSlot].onsetFrame;
    struct PartialPublishClaimContext {
        struct ArmWitness {
            harken::TimelineArmToken arm{};
            harken::DecisionToken parent{};
            harken::ArmGroupToken group{};
            std::uint16_t memberIndex = UINT16_MAX;
            std::uint64_t tombstoneSequence = 0;
            bool captured = false;
            bool recorded = false;
            bool exactAtRecord = false;
        };
        harken::ImmediateLaneFrontierClaim claim{};
        harken::Plan03GroupSliceIdentity group{};
        std::array<harken::Plan03GroupSliceIdentity, 8> groups{};
        std::array<harken::TimelineArmToken, 2> arms{};
        std::array<VnVoiceHandle, 2> renders{};
        std::array<harken::SourceTerminalToken, 2> sources{};
        std::array<ArmWitness, 2> armWitnesses{};
        std::uint64_t attemptGeneration = 0;
        std::uint64_t faultBlock = 0;
        std::uint64_t claimBlock = 0;
        std::uint64_t postBlock = 0;
        std::uint32_t groupCount = 0;
        std::uint32_t eventOrdinal = 0;
        std::uint32_t faultOrdinal = 0;
        std::uint32_t claimOrdinal = 0;
        std::uint32_t postOrdinal = 0;
        bool invoked = false;
        bool injectionConsumed = false;
        bool exactPartialPublish = false;
    } partialClaim{};
    struct PartialPublishHookReset {
        harken::Engine* engine;
        ~PartialPublishHookReset() {
            engine->initialQueuePartialPublishAbortHookForTest = nullptr;
            engine->initialQueuePartialPublishAbortContextForTest = nullptr;
            if (engine->armGroupTombstoneObservationContextForTest != nullptr) {
                engine->armGroupTombstoneObservationHookForTest = nullptr;
                engine->armGroupTombstoneObservationContextForTest = nullptr;
            }
        }
    } partialHookReset{engine};
    if (claimedReaderSibling) {
        engine->initialQueuePartialPublishAbortContextForTest = &partialClaim;
        engine->armGroupTombstoneObservationContextForTest = &partialClaim;
        engine->armGroupTombstoneObservationHookForTest = +[](
            harken::Engine& observedEngine, harken::DecisionToken parent,
            harken::ArmGroupToken group, harken::TimelineArmToken arm,
            std::uint16_t memberIndex, std::uint64_t sequence,
            void* rawContext) {
            auto& context = *static_cast<PartialPublishClaimContext*>(rawContext);
            for (auto& witness : context.armWitnesses) {
                if (!witness.captured || witness.arm.slot != arm.slot ||
                    witness.arm.generation != arm.generation ||
                    witness.arm.renderSlot != arm.renderSlot ||
                    witness.arm.renderGeneration != arm.renderGeneration)
                    continue;
                harken::ArmGroupSnapshot groupSnapshot{};
                harken::ArmGroupMemberSnapshot member{};
                harken::TimelineArmObservation observation{};
                witness.exactAtRecord = !witness.recorded && sequence != 0 &&
                    witness.parent.slot == parent.slot &&
                    witness.parent.generation == parent.generation &&
                    witness.group.slot == group.slot &&
                    witness.group.generation == group.generation &&
                    witness.memberIndex == memberIndex &&
                    observedEngine.armGroups.Capture(group, &groupSnapshot) &&
                    groupSnapshot.state == harken::ArmGroupState::Retiring &&
                    groupSnapshot.parent.slot == parent.slot &&
                    groupSnapshot.parent.generation == parent.generation &&
                    observedEngine.armGroups.CaptureMember(group, memberIndex,
                        &member) && member.tombstoned &&
                    member.token.slot == arm.slot &&
                    member.token.generation == arm.generation &&
                    member.token.renderSlot == arm.renderSlot &&
                    member.token.renderGeneration == arm.renderGeneration &&
                    observedEngine.timelineArms.Observe(arm, &observation) &&
                    observation.state == harken::ArmState::Tombstoned &&
                    observation.startedBlockSequence == 0 &&
                    observation.tombstoneAudioSequence == sequence;
                witness.tombstoneSequence = sequence;
                witness.recorded = true;
                return;
            }
        };
        engine->initialQueuePartialPublishAbortHookForTest = +[](
            harken::Engine& observedEngine,
            harken::EngineImmediateEntryAttempt& attempt,
            void* rawContext) {
            auto& context = *static_cast<PartialPublishClaimContext*>(rawContext);
            if (context.invoked) return;
            context.invoked = true;
            context.attemptGeneration = attempt.generation;
            context.injectionConsumed =
                observedEngine.forceImmediateQueueArmPublishFailureAtForTest ==
                    UINT32_MAX;
            if (context.injectionConsumed) {
                context.faultOrdinal = ++context.eventOrdinal;
                context.faultBlock = observedEngine.mixer.BlocksRendered();
            }
            if (!attempt.producerAbortPartialArmPublished ||
                attempt.privateVoiceCount != context.arms.size()) return;
            std::uint32_t published = 0;
            std::uint32_t unpublished = 0;
            for (std::size_t index = 0; index < context.arms.size(); ++index) {
                const auto& voice = attempt.privateVoices[index];
                context.arms[index] = voice.startArm;
                context.renders[index] = voice.render;
                context.sources[index] = voice.source;
                harken::ArmState state = harken::ArmState::Free;
                harken::TimelineArmObservation observation{};
                if (!observedEngine.timelineArms.State(voice.startArm, &state) ||
                    !observedEngine.timelineArms.Observe(
                        voice.startArm, &observation) ||
                    !observation.parentGroup.Valid() ||
                    observation.memberIndex == UINT16_MAX)
                    return;
                harken::DecisionCommittedSnapshot committed{};
                harken::ArmGroupSnapshot group{};
                harken::ArmGroupMemberSnapshot member{};
                if (!observedEngine.decisions.CaptureCommitted(
                        observation.parentGroup.decision, &committed) ||
                    !observedEngine.armGroups.Capture(
                        committed.armGroup, &group) ||
                    !observedEngine.armGroups.CaptureMember(
                        committed.armGroup, observation.memberIndex,
                        &member) ||
                    group.parent.slot != observation.parentGroup.decision.slot ||
                    group.parent.generation !=
                        observation.parentGroup.decision.generation ||
                    member.token.slot != voice.startArm.slot ||
                    member.token.generation != voice.startArm.generation ||
                    member.token.renderSlot != voice.startArm.renderSlot ||
                    member.token.renderGeneration !=
                        voice.startArm.renderGeneration)
                    return;
                context.armWitnesses[index] = {voice.startArm,
                    observation.parentGroup.decision, committed.armGroup,
                    observation.memberIndex, 0, true, false, false};
                published += state == harken::ArmState::Published;
                unpublished += state == harken::ArmState::Armed;
            }
            context.exactPartialPublish = published == 1u &&
                unpublished == 1u;
            const auto count = observedEngine.immediateActionLane.
                PrivatePinGroupCount(attempt.lane);
            if (count == 0 || count > context.groups.size()) return;
            for (std::uint32_t index = 0; index < count; ++index) {
                harken::Plan03GroupSliceIdentity identity{};
                if (!observedEngine.immediateActionLane.CapturePrivatePinGroup(
                        attempt.lane, index, &identity) || !identity.Exact())
                    return;
                context.groups[index] = identity;
                if (!context.claim.Valid() &&
                    observedEngine.timelinePool.ClaimPrivateImmediateLaneFrontier(
                        identity, &context.claim)) {
                    context.group = identity;
                    context.claimOrdinal = ++context.eventOrdinal;
                    context.claimBlock = observedEngine.mixer.BlocksRendered();
                }
            }
            context.groupCount = count;
        };
    }
    switch (fault) {
    case 0:
        ASSERT_GE(aggregate.entryAnchorFrame, kFrames);
        aggregate.entryAnchorFrame -= kFrames;
        break;
    case 1:
        ASSERT_GE(holder->QueueFiling().queueSuccessorProgramBank->aggregateSchedules[0].
            entryAnchorFrame, kFrames);
        holder->QueueFiling().queueSuccessorProgramBank->aggregateSchedules[0].
            entryAnchorFrame -= kFrames;
        break;
    case 2: {
        const auto arm = holder->QueueFiling().queueSuccessorArm;
        ASSERT_TRUE(arm.Valid());
        auto& install = engine->timelineVoiceInstallIdentities[arm.renderSlot];
        ASSERT_GE(install.onsetFrame, kFrames);
        install.onsetFrame -= kFrames;
        break;
    }
    case 3:
        holder->QueueFiling().queueSuccessorProgramPlane = holder->QueuePayload().queueCurrentProgramPlane;
        break;
    case 4: {
        const auto programs = holder->QueueFiling().queueSuccessorPrograms.Resolve(holder->QueueFiling().queueSuccessorProgramBank);
        ASSERT_EQ(1u, programs.size());
        ASSERT_NE(nullptr, programs[0].events);
        ASSERT_GT(programs[0].eventCount, 0u);
        aggregate.events = programs[0].events + programs[0].eventCount;
        break;
    }
    case 5:
    case 6:
        engine->forceImmediateQueueArmPublishFailureAtForTest = fault - 5u;
        if (blockSecondStop)
            engine->forceInitialQueuePrivateStopPushFailureAtForTest = 1;
        break;
    default:
        FAIL() << "Invalid fault";
    }
    if (fault < 5 && blockSecondStop)
        engine->forceInitialQueuePrivateStopPushFailureAtForTest = 1;
    bool publishFailureObserved = false;
    const auto observePublishFailure = [&] {
        if (fault < 5 || publishFailureObserved ||
            engine->forceImmediateQueueArmPublishFailureAtForTest != UINT32_MAX)
            return;
        publishFailureObserved = true;
        const auto* member = engine->FindPlayableMember(successorMemberToken);
        ASSERT_NE(nullptr, member);
        const auto physical = member->startFrame;
        const auto onset = engine->timelineVoiceInstallIdentities[
            holder->QueueFiling().queueSuccessorArm.renderSlot].onsetFrame;
        if (fault == 5) {
            EXPECT_EQ(oldPhysicalStart, physical);
            EXPECT_EQ(oldAggregateAnchor, aggregate.entryAnchorFrame);
            EXPECT_EQ(oldInstallOnset, onset);
        } else {
            EXPECT_GT(physical, oldPhysicalStart);
            EXPECT_NE(oldAggregateAnchor, aggregate.entryAnchorFrame);
            EXPECT_EQ(physical, onset);
        }
    };
    ASSERT_EQ(VN_OK, Vn_Update());
    observePublishFailure();
    VnActionFiringHandle siblingFiring = 0;
    harken::EnginePlayableServiceRow* siblingRow = nullptr;
    if (claimedReaderSibling) {
        std::uint32_t updatesBeforeFault = 0;
        for (; updatesBeforeFault < 64 && !partialClaim.invoked;
             ++updatesBeforeFault) {
            engine->nullBackend.Pump(1);
            const auto* output = engine->nullBackend.LastBlock();
            EXPECT_TRUE(std::all_of(output,
                output + kFrames * engine->nullBackend.Channels(),
                [](float sample) { return std::abs(sample) <= 0.01f; }));
            ASSERT_EQ(VN_OK, Vn_Update());
            observePublishFailure();
        }
        testing::Test::RecordProperty("claimed_updates_before_fault",
            std::to_string(updatesBeforeFault));
        ASSERT_TRUE(partialClaim.invoked);
        ASSERT_TRUE(partialClaim.injectionConsumed);
        ASSERT_TRUE(partialClaim.exactPartialPublish);
        ASSERT_TRUE(partialClaim.group.Exact());
        ASSERT_TRUE(partialClaim.claim.Valid());
        ASSERT_GT(partialClaim.groupCount, 0u);
        for (const auto& witness : partialClaim.armWitnesses)
            ASSERT_TRUE(witness.captured);
        const auto exactAttempt = std::find_if(
            engine->immediateEntryAttempts.data(),
            engine->immediateEntryAttempts.data() +
                engine->immediateEntryAttempts.size(),
            [&](const auto& candidate) {
                return candidate.active && candidate.root == failed &&
                    candidate.generation == partialClaim.attemptGeneration;
            });
        ASSERT_NE(engine->immediateEntryAttempts.data() +
            engine->immediateEntryAttempts.size(), exactAttempt);
        ASSERT_TRUE(exactAttempt->producerAbortPending);
        ASSERT_TRUE(exactAttempt->producerAbortPartialArmPublished);
        VnPostActionDesc siblingPost = desc;
        siblingPost.actionId = image.actions[10].actionStableId;
        ASSERT_EQ(VN_OK, Vn_PostAction(&siblingPost, &siblingFiring));
        partialClaim.postOrdinal = ++partialClaim.eventOrdinal;
        partialClaim.postBlock = engine->mixer.BlocksRendered();
        ASSERT_LT(partialClaim.faultOrdinal, partialClaim.claimOrdinal);
        ASSERT_LT(partialClaim.claimOrdinal, partialClaim.postOrdinal);
        testing::Test::RecordProperty("claimed_event_ordinals",
            std::to_string(partialClaim.faultOrdinal) + "/" +
            std::to_string(partialClaim.claimOrdinal) + "/" +
            std::to_string(partialClaim.postOrdinal));
        testing::Test::RecordProperty("claimed_event_blocks",
            std::to_string(partialClaim.faultBlock) + "/" +
            std::to_string(partialClaim.claimBlock) + "/" +
            std::to_string(partialClaim.postBlock));
        const auto found = std::find_if(engine->playableServices.begin(),
            engine->playableServices.end(), [&](auto& row) {
                return row.InvocationValid() &&
                    row.Invocation().actionFiring == siblingFiring &&
                    !row.parentService.Valid();
            });
        ASSERT_NE(engine->playableServices.end(), found);
        siblingRow = &*found;
    }
    struct TombstoneWitness {
        harken::TimelineArmToken arm{};
        harken::DecisionToken parent{};
        harken::ArmGroupToken group{};
        std::uint16_t memberIndex = UINT16_MAX;
        std::uint64_t audioSequence = 0;
        bool recorded = false;
        bool exactAtRecord = false;
        bool secondStopPendingAtRecord = false;
    };
    std::array<TombstoneWitness, 2> tombstoneWitnesses{};
    bool unexpectedTombstoneRecord = false;
    const harken::EngineImmediateEntryAttempt* strictAttempt = nullptr;
    if (fault == 6 && blockSecondStop) {
        for (std::uint32_t index = 0;
             index < engine->immediateEntryAttempts.size(); ++index) {
            const auto& candidate = engine->immediateEntryAttempts[index];
            if (candidate.active && candidate.root == failed) {
                strictAttempt = &candidate;
                break;
            }
        }
        ASSERT_NE(nullptr, strictAttempt);
    }
    bool strictArmsCaptured = false;
    const auto captureStrictArms = [&] {
        ASSERT_EQ(2u, strictAttempt->privateVoiceCount);
        for (std::size_t index = 0; index < tombstoneWitnesses.size(); ++index) {
            const auto arm = strictAttempt->privateVoices[index].startArm;
            ASSERT_TRUE(arm.Valid());
            harken::TimelineArmObservation observed{};
            ASSERT_TRUE(engine->timelineArms.Observe(arm, &observed));
            ASSERT_TRUE(observed.parentGroup.Valid());
            harken::DecisionCommittedSnapshot committed{};
            ASSERT_TRUE(engine->decisions.CaptureCommitted(
                observed.parentGroup.decision, &committed));
            harken::ArmGroupSnapshot group{};
            ASSERT_TRUE(engine->armGroups.Capture(committed.armGroup, &group));
            EXPECT_EQ(observed.parentGroup.decision.slot, group.parent.slot);
            EXPECT_EQ(observed.parentGroup.decision.generation,
                group.parent.generation);
            harken::ArmGroupMemberSnapshot member{};
            ASSERT_TRUE(engine->armGroups.CaptureMember(
                committed.armGroup, observed.memberIndex, &member));
            EXPECT_EQ(arm.slot, member.token.slot);
            EXPECT_EQ(arm.generation, member.token.generation);
            EXPECT_EQ(arm.renderSlot, member.token.renderSlot);
            EXPECT_EQ(arm.renderGeneration, member.token.renderGeneration);
            tombstoneWitnesses[index] = {arm, observed.parentGroup.decision,
                committed.armGroup, observed.memberIndex};
        }
        EXPECT_NE(tombstoneWitnesses[0].parent.slot,
            tombstoneWitnesses[1].parent.slot);
        EXPECT_NE(initialDecision.slot, tombstoneWitnesses[0].parent.slot);
        EXPECT_EQ(queueDecision.slot, tombstoneWitnesses[1].parent.slot);
        EXPECT_EQ(queueDecision.generation,
            tombstoneWitnesses[1].parent.generation);
        strictArmsCaptured = true;
    };
    struct TombstoneHookReset {
        harken::Engine* engine;
        ~TombstoneHookReset() {
            engine->armGroupTombstoneObservationHookForTest = nullptr;
            engine->armGroupTombstoneObservationContextForTest = nullptr;
        }
    } tombstoneHookReset{engine};
    struct TombstoneHookContext {
        std::array<TombstoneWitness, 2>* witnesses;
        const harken::EngineImmediateEntryAttempt* attempt;
        bool* unexpected;
    } hookContext{&tombstoneWitnesses, strictAttempt, &unexpectedTombstoneRecord};
    if (strictAttempt != nullptr) {
        engine->armGroupTombstoneObservationContextForTest = &hookContext;
        engine->armGroupTombstoneObservationHookForTest = +[](
            harken::Engine& observedEngine, harken::DecisionToken parent,
            harken::ArmGroupToken group, harken::TimelineArmToken arm,
            std::uint16_t memberIndex, std::uint64_t sequence,
            void* rawContext) {
            auto& context = *static_cast<TombstoneHookContext*>(rawContext);
            for (std::size_t index = 0; index < context.witnesses->size(); ++index) {
                auto& witness = (*context.witnesses)[index];
                if (witness.arm.slot != arm.slot ||
                    witness.arm.generation != arm.generation ||
                    witness.arm.renderSlot != arm.renderSlot ||
                    witness.arm.renderGeneration != arm.renderGeneration)
                    continue;
                harken::ArmGroupSnapshot snapshot{};
                harken::ArmGroupMemberSnapshot member{};
                harken::TimelineArmObservation observed{};
                const bool exact = !witness.recorded && sequence != 0 &&
                    sequence == witness.audioSequence &&
                    witness.parent.slot == parent.slot &&
                    witness.parent.generation == parent.generation &&
                    witness.group.slot == group.slot &&
                    witness.group.generation == group.generation &&
                    witness.memberIndex == memberIndex &&
                    observedEngine.armGroups.Capture(group, &snapshot) &&
                    snapshot.state == harken::ArmGroupState::Retiring &&
                    snapshot.parent.slot == parent.slot &&
                    snapshot.parent.generation == parent.generation &&
                    observedEngine.armGroups.CaptureMember(group, memberIndex,
                        &member) && member.tombstoned &&
                    member.token.slot == arm.slot &&
                    member.token.generation == arm.generation &&
                    member.token.renderSlot == arm.renderSlot &&
                    member.token.renderGeneration == arm.renderGeneration &&
                    observedEngine.timelineArms.Observe(arm, &observed) &&
                    observed.state == harken::ArmState::Tombstoned &&
                    observed.tombstoneAudioSequence == sequence;
                witness.recorded = true;
                witness.exactAtRecord = exact;
                if (index == 0)
                    witness.secondStopPendingAtRecord = context.attempt->active &&
                        !context.attempt->privateVoices[1].stopQueued &&
                        observedEngine.forceInitialQueuePrivateStopPushFailureAtForTest ==
                            UINT32_MAX - 1u;
                return;
            }
            *context.unexpected = true;
        };
    }
    VnVoiceHandle firstAbortRender = 0;
    VnVoiceHandle secondAbortRender = 0;
    harken::VoiceReleaseObserver secondAbortRelease{};
    bool heard = false;
    bool droppedTerminal = false;
    bool observedSecondStopRetry = false;
    bool secondReleasedAfterFullQueue = false;
    bool siblingHeardWhileClaimed = false;
    bool siblingFiledWhileClaimed = false;
    std::uint64_t siblingStartFrame = UINT64_MAX;
    std::uint64_t siblingFirstNegativeFrame = UINT64_MAX;
    harken::TimelineArmToken siblingArm{};
    VnVoiceHandle siblingRender = 0;
    harken::TimelineArmToken firstAbortArm{};
    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    for (std::uint32_t block = 0; block < 64; ++block) {
        if (claimedReaderSibling && partialClaim.claim.Valid() &&
            siblingRow != nullptr &&
            siblingRow->phase == harken::EnginePlayableStartPhase::Filed &&
            siblingStartFrame == UINT64_MAX) {
            siblingStartFrame = siblingRow->startFrame;
            siblingArm = siblingRow->arm;
            siblingRender = siblingRow->renderHandle;
            siblingFiledWhileClaimed = siblingArm.Valid() &&
                siblingRender != 0 &&
                siblingArm.renderSlot ==
                    static_cast<std::uint32_t>(siblingRender) &&
                siblingArm.renderGeneration ==
                    static_cast<std::uint32_t>(siblingRender >> 32);
        }
        const auto audioBefore = engine->mixer.BlocksRendered();
        const bool claimedAtPump = partialClaim.claim.Valid();
        engine->nullBackend.Pump(1);
        EXPECT_EQ(audioBefore + 1u, engine->mixer.BlocksRendered());
        if (strictAttempt != nullptr) {
            for (auto& witness : tombstoneWitnesses) {
                if (witness.audioSequence != 0) continue;
                harken::TimelineArmObservation observed{};
                if (engine->timelineArms.Observe(witness.arm, &observed) &&
                    observed.state == harken::ArmState::Tombstoned)
                    witness.audioSequence = observed.tombstoneAudioSequence;
            }
        }
        if (blockSecondStop && secondAbortRender != 0 &&
            engine->voices.ReleaseObserved(secondAbortRelease))
            secondReleasedAfterFullQueue = true;
        if (dropFirstTerminal && !droppedTerminal) {
            std::array<VnNotification, 32> preserved{};
            std::size_t preservedCount = 0;
            VnNotification event{};
            while (engine->notifications.TryPop(event)) {
                if (event.voiceHandle == firstAbortRender &&
                    (event.type == VN_NOTIFY_VOICE_ENDED ||
                     event.type == VN_NOTIFY_VOICE_STOPPED_BY_FADE ||
                     event.type == VN_NOTIFY_VOICE_STOLEN)) {
                    droppedTerminal = true;
                    continue;
                }
                ASSERT_LT(preservedCount, preserved.size());
                preserved[preservedCount++] = event;
            }
            for (std::size_t index = 0; index < preservedCount; ++index)
                ASSERT_TRUE(engine->notifications.Push(preserved[index]));
        }
        const auto* output = engine->nullBackend.LastBlock();
        const bool audible = std::any_of(output,
            output + kFrames * engine->nullBackend.Channels(),
            [](float sample) { return std::abs(sample) > 0.01f; });
        heard = heard || audible;
        if (claimedReaderSibling && claimedAtPump) {
            EXPECT_TRUE(partialClaim.exactPartialPublish);
            EXPECT_TRUE(partialClaim.group.Exact());
            const auto exactAttempt = std::find_if(
                engine->immediateEntryAttempts.data(),
                engine->immediateEntryAttempts.data() +
                    engine->immediateEntryAttempts.size(),
                [&](const auto& candidate) {
                    return candidate.active && candidate.root == failed &&
                        candidate.generation ==
                            partialClaim.attemptGeneration;
                });
            ASSERT_NE(engine->immediateEntryAttempts.data() +
                engine->immediateEntryAttempts.size(), exactAttempt);
            for (std::uint32_t index = 0;
                 index < partialClaim.groupCount; ++index) {
                harken::Plan03PageGroupView audioGroup{};
                EXPECT_FALSE(engine->timelinePool.ResolvePlan03GroupSliceRt(
                    partialClaim.groups[index], &audioGroup));
            }
            for (std::size_t index = 0;
                 index < partialClaim.arms.size(); ++index) {
                const auto arm = partialClaim.arms[index];
                const auto& voice = exactAttempt->privateVoices[index];
                const auto* source = engine->sourceTerminals.Resolve(
                    partialClaim.sources[index]);
                if (source != nullptr) {
                    EXPECT_EQ(voice.leafInstance, source->leaf);
                    EXPECT_EQ(voice.render, source->render);
                    EXPECT_EQ(voice.release.slot, source->release.slot);
                    EXPECT_EQ(voice.release.targetSequence,
                        source->release.targetSequence);
                }
                harken::TimelineArmObservation observation{};
                if (engine->timelineArms.Observe(arm, &observation)) {
                    EXPECT_NE(harken::ArmState::Started, observation.state);
                    EXPECT_EQ(0u, observation.startedBlockSequence);
                } else {
                    const auto& witness = partialClaim.armWitnesses[index];
                    EXPECT_TRUE(witness.recorded);
                    EXPECT_TRUE(witness.exactAtRecord);
                    EXPECT_NE(0u, witness.tombstoneSequence);
                    EXPECT_GT(engine->mixer.BlocksRendered(),
                        witness.tombstoneSequence);
                    EXPECT_TRUE(engine->voices.ReleaseObserved(voice.release));
                    EXPECT_EQ(nullptr, engine->voices.Resolve(voice.render));
                    EXPECT_FALSE(engine->ledger.OwnerForRender(voice.render).live);
                    if (source != nullptr) {
                        EXPECT_TRUE(engine->playableInstances.
                            HasSourceRetirementHold(voice.leafInstance));
                    } else {
                        EXPECT_FALSE(engine->playableInstances.
                            HasSourceRetirementHold(voice.leafInstance));
                    }
                }
            }
            if (siblingFiledWhileClaimed &&
                audioBefore <= UINT64_MAX / kFrames &&
                siblingStartFrame >= audioBefore * kFrames &&
                siblingStartFrame < (audioBefore + 1u) * kFrames) {
                harken::TimelineArmObservation observation{};
                harken::EngineTimelineVoiceInstallIdentity identity{};
                const bool exactSibling =
                    engine->timelineArms.Observe(siblingArm, &observation) &&
                    observation.startedBlockSequence ==
                        engine->mixer.BlocksRendered() &&
                    engine->CaptureTimelineVoiceInstallIdentity(
                        siblingRender, &identity) &&
                    identity.startArm.slot == siblingArm.slot &&
                    identity.startArm.generation == siblingArm.generation &&
                    identity.renderHandle == siblingRender;
                EXPECT_TRUE(exactSibling);
                for (std::uint32_t sample = 0; sample < kFrames; ++sample) {
                    if (output[static_cast<std::size_t>(sample) *
                            engine->nullBackend.Channels()] < -0.01f) {
                        siblingFirstNegativeFrame = audioBefore * kFrames +
                            sample;
                        break;
                    }
                }
                EXPECT_EQ(siblingStartFrame, siblingFirstNegativeFrame);
                siblingHeardWhileClaimed = exactSibling &&
                    siblingFirstNegativeFrame == siblingStartFrame;
            }
        }
        ASSERT_EQ(VN_OK, Vn_Update());
        if (claimedReaderSibling && partialClaim.claim.Valid() &&
            (siblingHeardWhileClaimed || block == 47u)) {
            ASSERT_TRUE(engine->timelinePool.ReleaseImmediateLaneFrontier(
                &partialClaim.claim));
        }
        observePublishFailure();
        if (strictAttempt != nullptr && !strictArmsCaptured &&
            strictAttempt->privateVoiceCount == 2) {
            captureStrictArms();
            ASSERT_TRUE(strictArmsCaptured);
        }
        if (blockSecondStop && firstAbortRender == 0 &&
            engine->forceInitialQueuePrivateStopPushFailureAtForTest ==
                UINT32_MAX - 1u) {
            const harken::EngineImmediateEntryAttempt* attempt = nullptr;
            for (std::uint32_t index = 0;
                 index < engine->immediateEntryAttempts.size(); ++index) {
                const auto& candidate = engine->immediateEntryAttempts[index];
                if (candidate.active && candidate.root == failed) {
                    attempt = &candidate;
                    break;
                }
            }
            ASSERT_NE(nullptr, attempt);
            ASSERT_TRUE(attempt->producerAbortFullyPrivate ||
                attempt->producerAbortPartialArmPublished);
            ASSERT_EQ(2u, attempt->privateVoiceCount);
            EXPECT_TRUE(attempt->privateVoices[0].stopQueued);
            EXPECT_FALSE(attempt->privateVoices[1].stopQueued);
            EXPECT_TRUE(attempt->privateVoices[1].armCancelRequested);
            firstAbortRender = attempt->privateVoices[0].render;
            firstAbortArm = attempt->privateVoices[0].startArm;
            secondAbortRender = attempt->privateVoices[1].render;
            secondAbortRelease = attempt->privateVoices[1].release;
            std::uint32_t firstStopCount = 0;
            harken::CommandRecord queued{};
            for (std::uint32_t index = 0;
                 index < engine->commands.Capacity() - engine->commands.FreeSlots();
                 ++index) {
                ASSERT_TRUE(engine->commands.PeekAt(index, queued));
                if (queued.opcode == harken::kOpcodeStop &&
                    queued.payload.stop.handle == firstAbortRender)
                    ++firstStopCount;
            }
            EXPECT_EQ(1u, firstStopCount);
            ASSERT_EQ(VN_OK, Vn_Update());
            EXPECT_TRUE(attempt->active);
            EXPECT_TRUE(attempt->privateVoices[0].stopQueued);
            EXPECT_FALSE(attempt->privateVoices[1].stopQueued);
            EXPECT_EQ(UINT32_MAX - 1u,
                engine->forceInitialQueuePrivateStopPushFailureAtForTest);
        }
        if (blockSecondStop && !observedSecondStopRetry &&
            engine->forceInitialQueuePrivateStopPushFailureAtForTest == UINT32_MAX) {
            std::uint32_t secondStopCount = 0;
            harken::CommandRecord queued{};
            for (std::uint32_t index = 0;
                 index < engine->commands.Capacity() - engine->commands.FreeSlots();
                 ++index) {
                ASSERT_TRUE(engine->commands.PeekAt(index, queued));
                if (queued.opcode == harken::kOpcodeStop &&
                    queued.payload.stop.handle == secondAbortRender)
                    ++secondStopCount;
            }
            EXPECT_EQ(1u, secondStopCount);
            observedSecondStopRetry = true;
        }
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(failed, &info));
        if (info.state == VN_ACTION_FIRING_TERMINAL_RETAINED &&
            (!claimedReaderSibling || !partialClaim.claim.Valid())) break;
    }
    if (!claimedReaderSibling) EXPECT_FALSE(heard);
    if (claimedReaderSibling) {
        EXPECT_TRUE(partialClaim.invoked);
        EXPECT_TRUE(partialClaim.exactPartialPublish);
        EXPECT_TRUE(partialClaim.group.Exact());
        EXPECT_TRUE(siblingFiledWhileClaimed);
        EXPECT_TRUE(siblingHeardWhileClaimed)
            << "startFrame=" << siblingStartFrame
            << " currentBlock=" << engine->mixer.BlocksRendered();
        testing::Test::RecordProperty("claimed_sibling_start_frame",
            std::to_string(siblingStartFrame));
        testing::Test::RecordProperty("claimed_sibling_first_negative_frame",
            std::to_string(siblingFirstNegativeFrame));
        EXPECT_FALSE(partialClaim.claim.Valid());
        VnActionFiringInfo siblingInfo{};
        siblingInfo.structSize = sizeof(siblingInfo);
        for (std::uint32_t block = 0; block < 64; ++block) {
            ASSERT_EQ(VN_OK, Vn_QueryActionFiring(siblingFiring,
                &siblingInfo));
            if (siblingInfo.state == VN_ACTION_FIRING_TERMINAL_RETAINED)
                break;
            engine->nullBackend.Pump(1);
            ASSERT_EQ(VN_OK, Vn_Update());
        }
        EXPECT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED,
            siblingInfo.state);
        EXPECT_EQ(VN_ACTION_OUTCOME_SUCCEEDED, siblingInfo.outcome);
        ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(siblingFiring));
    }
    if (blockSecondStop) {
        EXPECT_NE(0u, firstAbortRender);
        EXPECT_TRUE(observedSecondStopRetry || secondReleasedAfterFullQueue);
    }
    if (strictAttempt != nullptr) {
        EXPECT_TRUE(strictArmsCaptured);
        EXPECT_FALSE(unexpectedTombstoneRecord);
        for (std::size_t index = 0; index < tombstoneWitnesses.size(); ++index) {
            SCOPED_TRACE(index);
            const auto& witness = tombstoneWitnesses[index];
            EXPECT_NE(0u, witness.audioSequence);
            EXPECT_TRUE(witness.recorded);
            EXPECT_TRUE(witness.exactAtRecord);
        }
        EXPECT_TRUE(tombstoneWitnesses[0].secondStopPendingAtRecord);
    }
    if (dropFirstTerminal) EXPECT_TRUE(droppedTerminal);
    if (fault >= 5) EXPECT_TRUE(publishFailureObserved);
    ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
    if (claimedReaderSibling)
        EXPECT_EQ(VN_ACTION_OUTCOME_FAILED, info.outcome);
    if (claimedReaderSibling) {
        for (const auto source : partialClaim.sources)
            EXPECT_EQ(nullptr, engine->sourceTerminals.Resolve(source));
        for (std::size_t index = 0;
             index < partialClaim.armWitnesses.size(); ++index) {
            const auto& witness = partialClaim.armWitnesses[index];
            EXPECT_TRUE(witness.recorded);
            EXPECT_TRUE(witness.exactAtRecord);
            testing::Test::RecordProperty(
                index == 0 ? "claimed_first_arm_tombstone_sequence"
                           : "claimed_second_arm_tombstone_sequence",
                std::to_string(witness.tombstoneSequence));
        }
    }
    EXPECT_EQ(0u, engine->voices.ActiveCount());
    EXPECT_EQ(0u, engine->playableInstances.LiveCount());
    EXPECT_EQ(0u, engine->queueInstances.LiveCount());
    if (fault == 6) {
        EXPECT_EQ(decisionBaseline, engine->decisions.LiveCount());
        EXPECT_EQ(armGroupBaseline, engine->armGroups.LiveCount());
        EXPECT_EQ(armBaseline, engine->timelineArms.LiveCount());
    }
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(failed));

    VnActionFiringHandle replay = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &replay));
    if (claimedReaderSibling) {
        harken::Plan03PageGroupView oldGroup{};
        harken::ImmediateLaneFrontierClaim oldClaim{};
        EXPECT_FALSE(engine->timelinePool.ResolvePlan03GroupSliceProducer(
            partialClaim.group, &oldGroup));
        EXPECT_FALSE(engine->timelinePool.ClaimPrivateImmediateLaneFrontier(
            partialClaim.group, &oldClaim));
    }
    const auto replayRow = std::find_if(engine->playableServices.begin(),
        engine->playableServices.end(), [&](const auto& row) {
            return row.InvocationValid() &&
                row.Invocation().actionFiring == replay &&
                !row.parentService.Valid();
        });
    ASSERT_NE(engine->playableServices.end(), replayRow);
    for (std::uint32_t block = 0; block < 8 &&
         replayRow->phase != harken::EnginePlayableStartPhase::Filed; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        if (replayRow->phase != harken::EnginePlayableStartPhase::Filed)
            engine->nullBackend.Pump(1);
    }
    ASSERT_EQ(harken::EnginePlayableStartPhase::Filed, replayRow->phase);
    std::uint64_t positive = UINT64_MAX;
    std::uint64_t negative = UINT64_MAX;
    for (std::uint32_t block = 0; block < 48; ++block) {
        engine->nullBackend.Pump(1);
        const auto* output = engine->nullBackend.LastBlock();
        const auto frame = (engine->mixer.BlocksRendered() - 1u) * kFrames;
        for (std::uint32_t sample = 0; sample < kFrames; ++sample) {
            const auto value = output[static_cast<std::size_t>(sample) *
                engine->nullBackend.Channels()];
            if (value > 0.01f && positive == UINT64_MAX) positive = frame + sample;
            if (value < -0.01f && negative == UINT64_MAX) negative = frame + sample;
        }
    }
    testing::Test::RecordProperty("replay_first_positive", std::to_string(positive));
    testing::Test::RecordProperty("replay_first_negative", std::to_string(negative));
    EXPECT_NE(UINT64_MAX, positive);
    EXPECT_NE(UINT64_MAX, negative);
    EXPECT_EQ(positive + 1024u, negative);
    ASSERT_EQ(VN_OK, Vn_Update());
    ASSERT_EQ(VN_OK, Vn_StopActionFiring(replay, 0));
    for (std::uint32_t block = 0; block < 64; ++block) {
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
    }
    EXPECT_EQ(0u, engine->playableInstances.LiveCount());
    EXPECT_EQ(0u, engine->queueInstances.LiveCount());
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(replay));
    ASSERT_EQ(VN_OK, Vn_DestroyEmitter(emitter));
}

