TEST(ActionFiringApi,
     ImmediateVariableControlDeepNestedQueueUsesDeepestOwner) {
    (void)Vn_Term();
    VnConfig config = harkentest::MakeNullConfig(4, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> first(1024, 0.25f);
    std::vector<float> second(1024, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(
                         CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(
                         CanonicalActionWorld::kSecondSound, &secondPcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound)
            .contentRevision);
    image.MakeImmediateDeepNestedQueueVariableControlPlayAction();
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    VnEmitterHandle emitter = 0;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&emitter));
    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    desc.emitter = emitter;
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    VnActionStepResult play{};
    play.structSize = sizeof(play);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
    ASSERT_NE(0u, play.producedPlayableInstance);
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == play.producedPlayableInstance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    ASSERT_EQ(3u, row->variableControlNestedContainerCount);
    const auto deepest = row->variableControlContainers[2].handle;
    const auto queueService = std::find_if(engine->playableServices.begin(), engine->playableServices.end(),
        [&](const auto& service) { return service.ownerInstance == deepest && service.queueMode; });
    ASSERT_NE(engine->playableServices.end(), queueService);
    ASSERT_TRUE(queueService->queueMode);
    ASSERT_TRUE(queueService->queueInstance.Valid());
    ASSERT_EQ(deepest, queueService->ownerInstance);
    ASSERT_EQ(&row->Invocation(), &queueService->Invocation());
    ASSERT_FALSE(row->queueMode);
    const auto deepestView = engine->playableInstances.Classify(deepest);
    ASSERT_TRUE(deepestView.live);
    ASSERT_EQ(queueService->ownerEpoch,
              deepestView.scheduleEpoch);
    ASSERT_EQ(row->variableControlContainers[1].handle,
              deepestView.parent);
    ASSERT_EQ(row->variableControlContainers[0].handle,
              engine->playableInstances.Classify(deepestView.parent).parent);
    ASSERT_EQ(row->rootInstance,
              engine->playableInstances.Classify(
                  row->variableControlContainers[0].handle)
                  .parent);

    harken::QueueInstanceSnapshot queueSnapshot{};
    ASSERT_TRUE(engine->queueInstances.Capture(
        queueService->queueInstance, &queueSnapshot));
    EXPECT_EQ(deepest, queueSnapshot.rootInstance);
    const auto leaf = row->variableControlLeafInstances[0];
    ASSERT_EQ(deepest, engine->playableInstances.Classify(leaf).parent);
    harken::PlayableInstanceHandle successor = 0;

    bool successorActivated = false;
    std::uint64_t firstPositiveFrame = UINT64_MAX;
    std::uint64_t firstNegativeFrame = UINT64_MAX;
    std::uint32_t updatesBeforePublish = 0;
    for (std::uint32_t block = 0;
         block < 48 && !row->frontierEntry.Valid(); ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        ++updatesBeforePublish;
        if (!row->frontierEntry.Valid())
            engine->nullBackend.Pump(1);
    }
    ASSERT_TRUE(row->frontierEntry.Valid());
    testing::Test::RecordProperty("deep_updates_before_publish",
        std::to_string(updatesBeforePublish));
    for (std::uint32_t block = 0;
         block < 48 && firstNegativeFrame == UINT64_MAX;
         ++block) {
        engine->nullBackend.Pump(1);
        const auto outputFrame =
            (engine->mixer.BlocksRendered() - 1u) * config.blockFrames;
        const auto* output = engine->nullBackend.LastBlock();
        for (std::uint32_t sample = 0; sample < config.blockFrames; ++sample) {
            const auto value = output[static_cast<std::size_t>(sample) *
                engine->nullBackend.Channels()];
            if (value > 0.01f && firstPositiveFrame == UINT64_MAX)
                firstPositiveFrame = outputFrame + sample;
            if (value < -0.01f && firstNegativeFrame == UINT64_MAX)
                firstNegativeFrame = outputFrame + sample;
        }
    }
    testing::Test::RecordProperty("deep_first_positive_frame",
        std::to_string(firstPositiveFrame));
    testing::Test::RecordProperty("deep_first_negative_frame",
        std::to_string(firstNegativeFrame));
    const auto receiptText = [&](harken::FrontierEntryReceiptRef entry) {
        EXPECT_TRUE(entry.Valid());
        if (!entry.Valid()) return std::string("invalid entry");
        const auto* activation = engine->decisions.ResolveFrontierActivation(
            entry.coordinator);
        EXPECT_NE(nullptr, activation);
        if (activation == nullptr) return std::string("missing activation");
        harken::FrontierActivationReceipt receipt{};
        const auto read = activation->Read(entry,
            engine->mixer.BlocksRendered(), &receipt);
        EXPECT_EQ(harken::FrontierReceiptRead::Ready, read);
        EXPECT_EQ(harken::FrontierReceiptOutcome::Applied, receipt.outcome);
        return std::string("read=") +
            std::to_string(static_cast<int>(read)) +
            " outcome=" + std::to_string(static_cast<int>(receipt.outcome)) +
            " reason=" + std::to_string(static_cast<int>(receipt.reason)) +
            " failingMember=" + std::to_string(receipt.failingMember) +
            " sequence=" + std::to_string(receipt.audioSequence) +
            " ownerChild=" + std::to_string(entry.owner.child) +
            " ownerParent=" + std::to_string(entry.owner.parent) +
            " ownerService=" + std::to_string(entry.owner.serviceSlot);
    };
    testing::Test::RecordProperty("deep_root_receipt",
        receiptText(row->frontierEntry));
    testing::Test::RecordProperty("deep_binding_layout",
        std::string("binding=") +
        std::to_string(sizeof(harken::FrontierGroupBinding)) +
        " descendant=" +
        std::to_string(sizeof(harken::FrontierQueueDescendantIdentity)));
    const auto* attempt = std::find_if(
        engine->immediateEntryAttempts.data(),
        engine->immediateEntryAttempts.data() +
            engine->immediateEntryAttempts.size(),
        [&](const auto& candidate) {
            return candidate.active && candidate.root == firing;
        });
    if (attempt != engine->immediateEntryAttempts.data() +
            engine->immediateEntryAttempts.size()) {
        testing::Test::RecordProperty("deep_route_counts",
            std::string("continuation=") +
                std::to_string(attempt->queueContinuationCount) +
                " future=" + std::to_string(attempt->queueFutureCount) +
                " head=" + std::to_string(attempt->queueContinuationHead));
        if (attempt->queueContinuationCount == 1 &&
            attempt->queueContinuationHead <
                engine->queueContinuationRecords.size()) {
            const auto& record = engine->queueContinuationRecords[
                attempt->queueContinuationHead];
            EXPECT_EQ(row->startFrame, firstPositiveFrame);
            EXPECT_EQ(record.descriptor.order.executeFrame,
                firstNegativeFrame);
            testing::Test::RecordProperty("deep_conditional_receipt",
                receiptText(record.descriptor.entry));
            testing::Test::RecordProperty("deep_planned_due_quantums",
                std::string("root=") +
                std::to_string(row->startFrame / config.blockFrames) +
                " conditional=" +
                std::to_string(record.descriptor.order.executeFrame /
                    config.blockFrames));
            testing::Test::RecordProperty("deep_continuation_route",
                std::string("service=") + std::to_string(record.service.slot) +
                "/" + std::to_string(record.service.generation) +
                " queue=" + std::to_string(record.queue.slot) +
                "/" + std::to_string(record.queue.generation) +
                " owner=" + std::to_string(record.ownerInstance) +
                "/" + std::to_string(record.ownerEpoch) +
                " primary=" + std::to_string(record.primaryGroup.committedRow) +
                "@" + std::to_string(record.primaryGroup.absoluteQuantum) +
                " prerequisite=" +
                std::to_string(record.prerequisiteMember.committedRow) +
                "@" +
                std::to_string(record.prerequisiteMember.absoluteQuantum) +
                " conditional=" +
                std::to_string(record.conditionalMember.committedRow) +
                "@" +
                std::to_string(record.conditionalMember.absoluteQuantum) +
                " prereqDecisionIsInitial=" +
                std::to_string(record.prerequisiteMember.decision.slot ==
                        queueService->initialQueueEntryDecision.slot &&
                    record.prerequisiteMember.decision.generation ==
                        queueService->initialQueueEntryDecision.generation));
            std::uint32_t publishedGroups = 0;
            if (engine->immediateActionLane.CapturePublishedGroupCount(
                    attempt->lane, &publishedGroups)) {
                for (std::uint32_t groupIndex = 0;
                     groupIndex < publishedGroups; ++groupIndex) {
                    harken::ImmediateLaneGroupRef group{};
                    if (!engine->immediateActionLane.CapturePublishedGroupDescriptor(
                            attempt->lane, groupIndex, &group)) continue;
                    const char* role = group.identity == record.prerequisiteMember
                        ? "prerequisite" : group.identity == record.primaryGroup
                        ? "primary" : group.identity == record.conditionalMember
                        ? "conditional" : nullptr;
                    if (role == nullptr) continue;
                    testing::Test::RecordProperty(std::string("deep_group_") + role,
                        std::string("due=") + std::to_string(group.dueQuantum) +
                        " bucket=" + std::to_string(group.bucketOrdinal) +
                        " index=" + std::to_string(group.groupIndex) +
                        " row=" + std::to_string(group.identity.committedRow));
                }
            }
        }
        harken::ImmediateLaneObservation lane{};
        if (engine->immediateActionLane.Observe(attempt->lane, &lane))
            testing::Test::RecordProperty("deep_lane_state",
                std::string("committed=") + std::to_string(lane.committed) +
                " applied=" + std::to_string(lane.applied) +
                " missed=" + std::to_string(lane.missed) +
                " cancelled=" + std::to_string(lane.cancelled) +
                " complete=" + std::to_string(lane.complete));
    }
    EXPECT_NE(UINT64_MAX, firstPositiveFrame);
    EXPECT_NE(UINT64_MAX, firstNegativeFrame);
    if (firstPositiveFrame != UINT64_MAX &&
        firstNegativeFrame != UINT64_MAX)
        EXPECT_EQ(1024u, firstNegativeFrame - firstPositiveFrame);
    for (std::uint32_t block = 0;
         block < 48 && !successorActivated; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        harken::ContainerPlaybackRow nestedSnapshot{};
        if (engine->containerPlayback.Capture(deepest, &nestedSnapshot) &&
            nestedSnapshot.activeChild != 0 &&
            nestedSnapshot.activeChild != leaf) {
            successor = nestedSnapshot.activeChild;
            EXPECT_EQ(deepest,
                engine->playableInstances.Classify(successor).parent);
            successorActivated = true;
        }
    }
    harken::QueueInstanceSnapshot finalQueue{};
    (void)engine->queueInstances.Capture(queueService->queueInstance,
        &finalQueue);
    ASSERT_TRUE(successorActivated)
        << " queue phase=" << static_cast<int>(queueService->phase)
        << " root phase=" << static_cast<int>(row->phase)
        << " queue control=" << static_cast<int>(queueService->controlReason)
        << " timingPending=" << queueService->queueTimingPending
        << " timingFinalized=" << queueService->queueTimingFinalized
        << " continuationPrepared=" << queueService->queueContinuationPrepared
        << " completion=" << queueService->QueuePayload().queueCompletionFrame
        << " queueNaturalEnd=" << queueService->queueNaturalEnd
        << " queueAbort=" << queueService->queueAbortRequested
        << " current=" << queueService->activeLeafInstance
        << " pendingVersion=" << finalQueue.pendingVersion
        << " pendingActivation=" << static_cast<int>(finalQueue.pendingActivation)
        << " firstPositive=" << firstPositiveFrame
        << " firstNegative=" << firstNegativeFrame;

    ASSERT_EQ(VN_OK, Vn_StopActionFiring(firing, 0));
    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    for (std::uint32_t block = 0; block < 128; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
        if (info.state == VN_ACTION_FIRING_TERMINAL_RETAINED) break;
    }
    ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
    EXPECT_FALSE(engine->playableInstances.Classify(play.producedPlayableInstance).live);
    EXPECT_EQ(0u, engine->variableControlInstances.LiveCount());
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    ASSERT_EQ(VN_OK, Vn_DestroyEmitter(emitter));
}

static void ExpectImmediateDeepNestedQueueWrongIdentityRejected(
    std::uint32_t fault) {
    (void)Vn_Term();
    VnConfig config = harkentest::MakeNullConfig(4, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> first(1024, 0.25f);
    std::vector<float> second(1024, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(
                         CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(
                         CanonicalActionWorld::kSecondSound, &secondPcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound)
            .contentRevision);
    image.MakeImmediateDeepNestedQueueVariableControlPlayAction();
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    const auto playableBaseline = engine->playableInstances.LiveCount();
    const auto queueBaseline = engine->queueInstances.LiveCount();
    const auto variableBaseline = engine->variableControlInstances.LiveCount();
    const auto partitionBaseline = engine->playablePartitions.OccupiedCount();
    VnEmitterHandle emitter = 0;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&emitter));
    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    desc.emitter = emitter;
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    VnActionStepResult play{};
    play.structSize = sizeof(play);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == play.producedPlayableInstance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    for (std::uint32_t block = 0;
         block < 48 && !row->frontierEntry.Valid(); ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        if (!row->frontierEntry.Valid()) engine->nullBackend.Pump(1);
    }
    ASSERT_TRUE(row->frontierEntry.Valid());
    const auto* attempt = std::find_if(
        engine->immediateEntryAttempts.data(),
        engine->immediateEntryAttempts.data() +
            engine->immediateEntryAttempts.size(),
        [&](const auto& candidate) {
            return candidate.active && candidate.root == firing;
        });
    ASSERT_NE(engine->immediateEntryAttempts.data() +
                  engine->immediateEntryAttempts.size(), attempt);
    ASSERT_EQ(1u, attempt->queueContinuationCount);
    ASSERT_EQ(0u, attempt->queueFutureCount);
    ASSERT_LT(attempt->queueContinuationHead,
              engine->queueContinuationRecords.size());
    const auto& record = engine->queueContinuationRecords[
        attempt->queueContinuationHead];
    harken::Plan03PageGroupView initialView{};
    harken::Plan03PageGroupView coordinatorView{};
    harken::Plan03PageGroupView conditionalView{};
    ASSERT_TRUE(engine->timelinePool.ResolvePlan03GroupSliceProducer(
        record.prerequisiteMember, &initialView));
    ASSERT_TRUE(engine->timelinePool.ResolvePlan03GroupSliceProducer(
        record.primaryGroup, &coordinatorView));
    ASSERT_TRUE(engine->timelinePool.ResolvePlan03GroupSliceProducer(
        record.conditionalMember, &conditionalView));
    ASSERT_NE(nullptr, initialView.frontier);
    ASSERT_NE(nullptr, coordinatorView.frontier);
    ASSERT_NE(nullptr, conditionalView.frontier);
    auto* initial = const_cast<harken::FrontierGroupBinding*>(
        initialView.frontier);
    auto* coordinator = const_cast<harken::FrontierGroupBinding*>(
        coordinatorView.frontier);
    auto* conditional = const_cast<harken::FrontierGroupBinding*>(
        conditionalView.frontier);
    ASSERT_TRUE(initial->queueDescendant.Valid());
    ASSERT_TRUE(initial->queueInitial.Valid());
    ASSERT_TRUE(conditional->queueDescendant.Empty());
    ASSERT_EQ(record.prerequisiteMember,
              initial->operation.group);
    switch (fault) {
    case 0:
        ++initial->queueDescendant.selectedSideMember.rowClaimGeneration;
        break;
    case 1:
        ++initial->queueDescendant.selectedSide.sideGeneration;
        break;
    case 2:
        ++initial->queueDescendant.selectedSideMember.decision.generation;
        break;
    case 3:
        ++initial->queueInitial.generation;
        break;
    case 4:
        ++initial->operation.owner.childEpoch;
        break;
    case 5:
        initial->queueDescendant = {};
        break;
    case 6:
        ++conditional->queueDescendant.selectedSide.sideGeneration;
        break;
    case 7:
        coordinator->prerequisiteMember =
            initial->queueDescendant.selectedSideMember.Expand();
        break;
    case 8:
        break;
    default:
        FAIL() << "unknown fault " << fault;
        return;
    }

    bool heard = false;
    for (std::uint32_t block = 0; block < 48; ++block) {
        engine->nullBackend.Pump(1);
        const auto* output = engine->nullBackend.LastBlock();
        for (std::uint32_t sample = 0; sample < config.blockFrames;
             ++sample) {
            const auto value = output[static_cast<std::size_t>(sample) *
                engine->nullBackend.Channels()];
            heard |= std::abs(value) > 0.01f;
        }
    }
    EXPECT_EQ(fault == 8, heard);
    const auto* activation = engine->decisions.ResolveFrontierActivation(
        row->frontierEntry.coordinator);
    ASSERT_NE(nullptr, activation);
    harken::FrontierActivationReceipt receipt{};
    ASSERT_EQ(harken::FrontierReceiptRead::Ready,
              activation->Read(row->frontierEntry,
                  engine->mixer.BlocksRendered(), &receipt));
    EXPECT_EQ(fault == 8 ? harken::FrontierReceiptOutcome::Applied :
                           harken::FrontierReceiptOutcome::DefinitivelyNotApplied,
              receipt.outcome);

    ASSERT_EQ(VN_OK, Vn_StopActionFiring(firing, 0));
    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    for (std::uint32_t block = 0; block < 128; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
        if (info.state == VN_ACTION_FIRING_TERMINAL_RETAINED) break;
    }
    harken::ImmediateLaneObservation lane{};
    const auto observedLane = engine->immediateActionLane.Observe(
        attempt->lane, &lane);
    const auto* queueService = engine->ResolvePlayableService(
        record.service, record.ownerInstance, record.ownerEpoch);
    harken::QueueInstanceSnapshot queueSnapshot{};
    const bool queueCaptured = engine->queueInstances.Capture(
        record.queue, &queueSnapshot);
    harken::Plan03PageGroupView initialAfter{};
    harken::Plan03PageGroupView conditionalAfter{};
    const bool initialResolved = engine->timelinePool.ResolvePlan03GroupSliceProducer(
        record.prerequisiteMember, &initialAfter);
    const bool conditionalResolved = engine->timelinePool.ResolvePlan03GroupSliceProducer(
        record.conditionalMember, &conditionalAfter);
    ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state)
        << " fault=" << fault
        << " live=" << info.livePlayableCount
        << " rootPhase=" << static_cast<int>(row->phase)
        << " rootControl=" << static_cast<int>(row->controlReason)
        << " rootPending=" << row->pendingImmediateEntry
        << " rootRetry=" << row->pendingImmediateRetry
        << " rootFrontier=" << row->frontierEntry.Valid()
        << " rootLifetimePin=" << row->frontierLifetimePin.Valid()
        << " rootArmPin=" << row->frontierArmPin.Valid()
        << " rootDeferred=" << row->variableControlDeferredCancellation
        << " rootCancelIntent=" << row->pendingCancellationIntent
        << " rootPartitionRetiring=" << row->partitionRetiring
        << " queueService=" << (queueService != nullptr)
        << " queuePhase=" << (queueService == nullptr ? -1 :
               static_cast<int>(queueService->phase))
        << " queueControl=" << (queueService == nullptr ? -1 :
               static_cast<int>(queueService->controlReason))
        << " queueTimingPending=" << (queueService != nullptr &&
               queueService->queueTimingPending)
        << " queueAbort=" << (queueService != nullptr &&
               queueService->queueAbortRequested)
        << " queueFrontier=" << (queueService != nullptr &&
               queueService->frontierEntry.Valid())
        << " queueLifetimePin=" << (queueService != nullptr &&
               queueService->frontierLifetimePin.Valid())
        << " queueArmPin=" << (queueService != nullptr &&
               queueService->frontierArmPin.Valid())
        << " queueDeferred=" << (queueService != nullptr &&
               queueService->variableControlDeferredCancellation)
        << " queueCancelIntent=" << (queueService == nullptr ? 0 :
               queueService->pendingCancellationIntent)
        << " queuePartitionRetiring=" << (queueService != nullptr &&
               queueService->partitionRetiring)
        << " continuationPin=" << record.prerequisiteMemberPin.Valid()
        << " attemptActive=" << attempt->active
        << " attemptLane=" << attempt->lane.Valid()
        << " attemptContinuationFailed=" << attempt->queueContinuationFailed
        << " recordDescriptor=" << record.descriptor.Valid()
        << " recordCoordinator=" << record.coordinator.Valid()
        << " recordPrimary=" << record.primaryGroup.Exact()
        << " queueCaptured=" << queueCaptured
        << " queuePendingVersion=" << queueSnapshot.pendingVersion
        << " queueFailurePhase=" << static_cast<int>(queueSnapshot.failurePhase)
        << " initialResolved=" << initialResolved
        << " initialLease=" << (initialResolved && initialAfter.lease != nullptr ?
               static_cast<int>(initialAfter.lease->Capture().state) : -1)
        << " conditionalResolved=" << conditionalResolved
        << " conditionalLease=" << (conditionalResolved && conditionalAfter.lease != nullptr ?
               static_cast<int>(conditionalAfter.lease->Capture().state) : -1)
        << " runtimeRecreate=" << engine->runtimeRecreateRequired
        << " laneObserved=" << observedLane
        << " laneComplete=" << lane.complete
        << " laneCancelled=" << lane.cancelled
        << " laneMissed=" << lane.missed
        << " playable=" << engine->playableInstances.LiveCount()
        << " queue=" << engine->queueInstances.LiveCount()
        << " vc=" << engine->variableControlInstances.LiveCount()
        << " partitions=" << engine->playablePartitions.OccupiedCount()
        << " voices=" << engine->voices.ActiveCount();
    EXPECT_EQ(playableBaseline, engine->playableInstances.LiveCount());
    EXPECT_EQ(queueBaseline, engine->queueInstances.LiveCount());
    EXPECT_EQ(variableBaseline,
              engine->variableControlInstances.LiveCount());
    EXPECT_EQ(partitionBaseline,
              engine->playablePartitions.OccupiedCount());
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    ASSERT_EQ(VN_OK, Vn_DestroyEmitter(emitter));
}

TEST(ActionFiringApi,
     ImmediateVariableControlDeepNestedQueueRejectsWrongFrozenIdentity) {
    for (std::uint32_t fault = 0; fault < 9; ++fault) {
        SCOPED_TRACE(fault);
        ExpectImmediateDeepNestedQueueWrongIdentityRejected(fault);
    }
}

TEST(ActionFiringApi, ImmediateQueueDescendantKeepsExactLaneIdentity) {
    harken::Plan03GroupSliceIdentity lane{};
    lane.absoluteQuantum = 0;
    lane.pageGeneration = 1;
    lane.decision = {7, 11};
    lane.sliceIndex = 3;
    lane.committedRow = 17;
    lane.rowClaimGeneration = 19;
    lane.transportEpoch = 23;
    lane.backing = harken::Plan03GroupBacking::ImmediateLane;
    harken::FrontierImmediateLaneMemberIdentity compact{};
    ASSERT_TRUE(compact.Capture(lane));
    EXPECT_EQ(lane, compact.Expand());
    EXPECT_EQ(32u, sizeof(compact));
    harken::FrontierVariableSideIdentity side{};
    side.slot = 2;
    side.generation = 5;
    side.side = 1;
    side.sideGeneration = 29;
    side.bankSlot = 31;
    side.bankGeneration = 37;
    harken::FrontierQueueDescendantIdentity descendant{};
    ASSERT_TRUE(descendant.Freeze(lane, side));
    EXPECT_EQ(lane, descendant.selectedSideMember.Expand());
    EXPECT_EQ(side, descendant.selectedSide);
    EXPECT_EQ(64u, sizeof(descendant));
    EXPECT_FALSE(descendant.Empty());

    for (auto invalid : {
             [&] { auto value = lane; value.backing = harken::Plan03GroupBacking::Page; return value; }(),
             [&] { auto value = lane; value.absoluteQuantum = 1; return value; }(),
             [&] { auto value = lane; value.pageGeneration = 2; return value; }()}) {
        harken::FrontierImmediateLaneMemberIdentity rejected{};
        EXPECT_FALSE(rejected.Capture(invalid));
        EXPECT_TRUE(rejected.Empty());
    }
}

static void ExpectImmediateVariableControlNestedRetargetPromotesCompleteInstanceTree(
    std::uint32_t playableCapacity = 0, std::uint32_t modeCapacity = 0,
    bool holdPreparationScratch = false, bool stopAll = false,
    std::uint32_t ordinal = 7) {
    SCOPED_TRACE(ordinal);
    (void)Vn_Term();
    harkentest::PlayableCapacityScope limits(playableCapacity, modeCapacity);
    VnConfig config = harkentest::MakeNullConfig(6, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> first(2048, 0.25f);
    std::vector<float> second(2048, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(
                         CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(
                         CanonicalActionWorld::kSecondSound, &secondPcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound)
            .contentRevision);
    image.MakeImmediateNestedVariableControlRetargetPlayAction();
    image.containers[3].discreteTiming = 1;
    image.containers[3].evaluationPeriodFrames = 64;
    image.child.stableChildOrdinal = ordinal;
    image.nestedVariableControlChild.stableChildOrdinal = ordinal;
    for (const auto index : {0u, 1u}) {
        image.occurrences[index].stableOccurrenceOrdinal = ordinal;
        image.occurrences[index].occurrenceSemanticFingerprint =
            harken::ComputePlayableOccurrenceFingerprintV1(image.occurrences[index]);
    }
    auto nestedSelection = image.variableControlRows[0];
    nestedSelection.childStableOrdinal = ordinal;
    const auto nestedCell = image.variableControlCells[1];
    nestedSelection.cells = &nestedCell;
    image.containers[1].discreteRows = &nestedSelection;
    image.world.identity.runtimeSemanticFingerprint =
        harken::ComputeCurrentWorldFingerprintV4(image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    const auto playableBaseline = engine->playableInstances.LiveCount();
    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle firing = 0;
    harkentest::PlayableStorageObservation storage(*engine, playableCapacity != 0);
    const auto Vn_PostAction = [&](const VnPostActionDesc* post, VnActionFiringHandle* handle) {
        return storage.Measure([&] { return ::Vn_PostAction(post, handle); });
    };
    const auto Vn_Update = [&] { return storage.Measure([] { return ::Vn_Update(); }); };
    const auto Vn_StopActionFiring = [&](VnActionFiringHandle handle, std::uint32_t fade) {
        return storage.Measure([&] {
            return stopAll ? ::Vn_StopAll(fade) : ::Vn_StopActionFiring(handle, fade);
        });
    };
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    VnActionStepResult play{};
    play.structSize = sizeof(play);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
    ASSERT_NE(0u, play.producedPlayableInstance);
    VnActionStepResult setValue{};
    setValue.structSize = sizeof(setValue);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 1, &setValue));
    EXPECT_EQ(VN_ACTION_STEP_SUCCEEDED, setValue.state);
    float currentVariableValue = 0.0f;
    ASSERT_TRUE(engine->variables.CurrentValue(
        image.variables[3].variableId, &currentVariableValue));
    EXPECT_FLOAT_EQ(3.0f, currentVariableValue);
    auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == play.producedPlayableInstance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    EXPECT_NE(harken::EnginePlayableStartPhase::Free, row->phase)
        << "play state=" << play.state
        << " leaf=" << row->leaf.stableId
        << " root=" << row->rootInstance;
    const auto outgoingChild = row->variableControlChildInstances[0];
    ASSERT_NE(0u, outgoingChild);
    const auto original = CaptureOriginalSource(*engine, row->variableControlLeafInstances[0]);
    if (holdPreparationScratch) {
        engine->servicePreparedScheduleLeavesInUse = true;
        for (std::uint32_t block = 0; block < 8; ++block) {
            ASSERT_EQ(VN_OK, Vn_Update());
            storage.Pump(1);
            EXPECT_FALSE(row->variableControlDiscreteRetargetPrepared);
            EXPECT_TRUE(engine->servicePreparedScheduleLeavesInUse);
            EXPECT_EQ(outgoingChild, row->variableControlChildInstances[0]);
            EXPECT_TRUE(engine->playableInstances.Classify(outgoingChild).live);
        }
        engine->servicePreparedScheduleLeavesInUse = false;
        const auto selectedOrdinal = row->variableControlDiscreteCurrentChildOrdinal;
        const auto allocationCount = engine->nativeBackingAllocationCountForTest;
        const auto allocationCountdown = engine->nativeBackingAllocationFailureCountdownForTest;
        engine->nativeBackingAllocationFailureCountdownForTest = 0;
        for (std::uint32_t block = 0; block < 8; ++block) {
            EXPECT_EQ(VN_OK, Vn_Update());
            storage.Pump(1);
            EXPECT_FALSE(row->variableControlDiscreteRetargetPrepared);
            EXPECT_EQ(outgoingChild, row->variableControlChildInstances[0]);
            EXPECT_EQ(selectedOrdinal, row->variableControlDiscreteCurrentChildOrdinal);
            EXPECT_TRUE(engine->playableInstances.Classify(outgoingChild).live);
            EXPECT_FALSE(engine->runtimeRecreateRequired);
        }
        engine->nativeBackingAllocationFailureCountdownForTest = allocationCountdown;
        EXPECT_GT(engine->nativeBackingAllocationCountForTest, allocationCount);
        const auto liveBeforeRefusal = engine->playableInstances.LiveCount();
        harken::detail::ArmLogicAllocFaultForTests(1, harken::detail::LogicAllocSite::RetargetIncomingStorage);
        const auto refusedUpdate = Vn_Update();
        const auto remainingFault = harken::detail::g_logicAllocFault.remaining;
        harken::detail::DisarmLogicAllocFaultForTests();
        ASSERT_EQ(VN_OK, refusedUpdate);
        EXPECT_EQ(0u, remainingFault);
        EXPECT_FALSE(row->variableControlDiscreteRetargetPrepared);
        EXPECT_EQ(outgoingChild, row->variableControlChildInstances[0]);
        EXPECT_EQ(selectedOrdinal, row->variableControlDiscreteCurrentChildOrdinal);
        EXPECT_EQ(liveBeforeRefusal, engine->playableInstances.LiveCount());
        EXPECT_TRUE(engine->playableInstances.Classify(outgoingChild).live);
        EXPECT_FALSE(engine->runtimeRecreateRequired);
    }
    bool prepared = false;
    for (std::uint32_t block = 0; block < 64 && !prepared; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        storage.Pump(1);
        prepared = row->variableControlDiscreteRetargetPrepared;
    }
    ASSERT_TRUE(prepared)
        << "phase=" << static_cast<int>(row->phase)
        << " lifecycle=" << static_cast<int>(row->controlLifecycle)
        << " leaf=" << row->leaf.stableId
        << " childOrdinal=" << row->variableControlDiscreteCurrentChildOrdinal
        << " nextFrame=" << row->variableControlDiscreteNextEvaluationFrame
        << " runtimeRecreate=" << engine->runtimeRecreateRequired;
    EXPECT_FALSE(engine->servicePreparedScheduleLeavesInUse);
    ASSERT_EQ(1u, row->VariablePayload().variableControlDiscreteRetargetIncomingLeafCount);
    EXPECT_EQ(1u, row->VariablePayload().variableControlDiscreteRetargetIncomingNestedCount);
    ASSERT_GE(row->VariablePayload().variableControlDiscreteRetargetIncomingContainerCount, 2u);
    EXPECT_EQ(playableBaseline + 5u,
              engine->playableInstances.LiveCount());
    const auto incomingRoot = row->VariablePayload().variableControlDiscreteRetargetIncomingChild;
    const auto nestedRoot =
        row->VariableControlRetargetIncoming().containers[0].handle;
    const auto nestedChild =
        row->VariableControlRetargetIncoming().containers[1].handle;
    ASSERT_EQ(incomingRoot, nestedRoot);
    ASSERT_EQ(row->rootInstance,
              engine->playableInstances.Classify(nestedRoot).parent);
    ASSERT_EQ(nestedRoot,
              engine->playableInstances.Classify(nestedChild).parent);
    const auto incomingLeaf =
        row->VariableControlRetargetIncoming().leaves[0].handle;
    ASSERT_EQ(nestedChild,
              engine->playableInstances.Classify(incomingLeaf).parent);

    ASSERT_EQ(1u, row->VariablePayload().variableControlDiscreteRetargetIncomingNestedVariableControlCount);
    auto* nestedControlService = engine->ResolvePlayableService(
        row->VariableControlRetargetIncoming().controllers[0].service);
    ASSERT_NE(nullptr, nestedControlService);
    EXPECT_EQ(nestedRoot, nestedControlService->ownerInstance);
    const auto resource = std::find_if(engine->playableServices.begin(), engine->playableServices.end(),
        [nestedChild](const auto& service) { return service.partition.Valid() && service.ownerInstance == nestedChild; });
    ASSERT_NE(engine->playableServices.end(), resource);
    auto* resourceService = &*resource;
    ASSERT_NE(nullptr, resourceService);
    EXPECT_EQ(nestedChild, resourceService->ownerInstance);
    EXPECT_NE(row->partition.slot, resourceService->partition.slot);
    const auto incomingSource = CaptureOriginalSource(*engine, incomingLeaf);
    const auto* sourceRecord = engine->sourceTerminals.Resolve(incomingSource.token);
    ASSERT_NE(nullptr, sourceRecord);
    EXPECT_EQ(resourceService, engine->ResolveSourceResourceOwner(sourceRecord->resourceOwner));
    const auto incomingReference = engine->ReadPlayableMemberReference(
        row->scheduleStorageBase + row->variableControlDiscreteTransitionOffset);
    harken::EnginePlayableServiceRow* referenceOwner = nullptr;
    std::size_t incomingPhysicalSlot = 0;
    ASSERT_TRUE(engine->ResolvePlayableMember(incomingReference, &referenceOwner, &incomingPhysicalSlot));
    EXPECT_EQ(resourceService, referenceOwner);
    EXPECT_EQ(incomingLeaf, engine->ReadPlayableMember(incomingPhysicalSlot).completion.leafInstance);
    const auto* record = engine->ResolveMemberProgram(incomingReference);
    ASSERT_NE(nullptr, record);
    const auto& ownedProgram = record->schedule;
    const auto* originalMember = &engine->ReadPlayableMember(incomingPhysicalSlot).completion;
    const auto* originalRuntime = ownedProgram.runtimeProgram.program;
    const auto* originalEvents = ownedProgram.events;
    ASSERT_EQ(&record->runtime, originalRuntime);
    ASSERT_NE(nullptr, originalRuntime);
    const auto* originalPayloads = originalRuntime->payloads;
    EXPECT_EQ(incomingLeaf, ownedProgram.ownerInstance);
    EXPECT_EQ(record->events.data(), originalEvents);
    EXPECT_EQ(record->payloads.data(), originalPayloads);

    const auto incomingContainerCount = row->VariablePayload().variableControlDiscreteRetargetIncomingContainerCount;
    bool promoted = false;
    for (std::uint32_t block = 0; block < 96 && !promoted; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        storage.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        promoted = row->variableControlDiscreteRetargetSourceExited &&
            row->variableControlChildInstances[0] == incomingRoot;
    }
    ASSERT_TRUE(promoted);
    EXPECT_EQ(incomingRoot, row->variableControlChildInstances[0]);
    EXPECT_EQ(incomingContainerCount, row->variableControlNestedContainerCount);
    EXPECT_EQ(0u, row->VariablePayload().variableControlDiscreteRetargetIncomingContainerCount);
    EXPECT_EQ(incomingRoot, row->variableControlContainers[0].handle);
    EXPECT_EQ(incomingLeaf, row->variableControlLeafInstances[0]);
    const auto promotedReference = engine->ReadPlayableMemberReference(row->scheduleStorageBase);
    EXPECT_EQ(incomingReference.service.token, promotedReference.service.token);
    EXPECT_EQ(incomingReference.partitionGeneration, promotedReference.partitionGeneration);
    EXPECT_EQ(incomingReference.memberOffset, promotedReference.memberOffset);
    EXPECT_EQ(incomingReference.leaf, promotedReference.leaf);
    EXPECT_EQ(incomingReference.leafEpoch, promotedReference.leafEpoch);
    EXPECT_EQ(originalRuntime, ownedProgram.runtimeProgram.program);
    EXPECT_EQ(originalEvents, ownedProgram.events);
    EXPECT_EQ(originalPayloads, ownedProgram.runtimeProgram.program->payloads);
    EXPECT_EQ(originalMember, &engine->ReadPlayableMember(incomingPhysicalSlot).completion);
    ASSERT_NO_FATAL_FAILURE(ExpectOriginalSourceRetiresAfterLaterBlock(*engine, original));
    EXPECT_FALSE(engine->playableInstances.Classify(outgoingChild).live);

    ASSERT_EQ(VN_OK, Vn_StopActionFiring(firing, 0));
    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    for (std::uint32_t block = 0; block < 128; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        storage.Pump(1);
        if (engine->playablePartitions.Owns(resourceService->partition, resourceService->identity)) {
            EXPECT_EQ(originalRuntime, ownedProgram.runtimeProgram.program);
            EXPECT_EQ(originalEvents, ownedProgram.events);
            EXPECT_EQ(originalPayloads, ownedProgram.runtimeProgram.program->payloads);
            EXPECT_EQ(originalMember, &engine->ReadPlayableMember(incomingPhysicalSlot).completion);
        }
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
        if (info.state == VN_ACTION_FIRING_TERMINAL_RETAINED) break;
    }
    ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
    EXPECT_EQ(playableBaseline, engine->playableInstances.LiveCount());
    EXPECT_FALSE(engine->playableInstances.Classify(incomingRoot).live);
    EXPECT_FALSE(engine->playableInstances.Classify(nestedChild).live);
    EXPECT_FALSE(engine->playableInstances.Classify(incomingLeaf).live);
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    for (std::uint32_t block = 0; block < 16 && engine->playablePartitions.OccupiedCount() != 0; ++block) {
        storage.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
    }
    EXPECT_EQ(0u, engine->playablePartitions.OccupiedCount());
    storage.Finish();
}

