TEST(ActionFiringApi, DirectRandomContainerToVariableControlBuildsAndReclaimsTree) {
    (void)Vn_Term();
    VnConfig config = harkentest::MakeNullConfig(4, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> first(2048, 0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(
                         CanonicalActionWorld::kFirstSound, &firstPcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision,
        1);
    image.MakeImmediateRandomToVariableControlPlayAction();
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    const auto playableBaseline = engine->playableInstances.LiveCount();
    VnEmitterHandle emitter = 0;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&emitter));
    const harken::PlayableStartResult started =
        harken::StartCurrentPlayableByIdentity(
            harken::PlayableKindV1::Container,
            image.containers[0].containerStableId, emitter);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);

    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.InvocationValid() && candidate.Invocation().variableControlOuterRootInstance ==
                   started.instance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    ASSERT_NE(0u, row->Invocation().variableControlOuterRootInstance);
    const auto outerRoot = row->Invocation().variableControlOuterRootInstance;
    EXPECT_EQ(outerRoot, started.instance);
    const auto outerView = engine->playableInstances.Classify(outerRoot);
    const auto vcView = engine->playableInstances.Classify(row->rootInstance);
    ASSERT_TRUE(outerView.live);
    ASSERT_TRUE(vcView.live);
    EXPECT_EQ(harken::PlayableKind::Container, outerView.kind);
    EXPECT_EQ(outerRoot, vcView.parent);
    EXPECT_EQ(0u, outerView.parent);
    harken::ContainerPlaybackRow outerRow{};
    ASSERT_TRUE(engine->containerPlayback.Capture(outerRoot, &outerRow));
    EXPECT_EQ(row->rootInstance, outerRow.activeChild);
    EXPECT_TRUE(row->variableControlInstance.Valid());

    ASSERT_EQ(harken::PlayableControlStatus::Ok,
              harken::StopPlayable(*engine, started.instance, 0));
    for (std::uint32_t block = 0; block < 128; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        if (!engine->playableInstances.Classify(started.instance).live) {
            break;
        }
    }
    EXPECT_FALSE(engine->playableInstances.Classify(started.instance).live);
    EXPECT_FALSE(engine->playableInstances.Classify(outerRoot).live);
    EXPECT_EQ(playableBaseline, engine->playableInstances.LiveCount());
    EXPECT_EQ(0u, engine->variableControlInstances.LiveCount());
    ASSERT_EQ(VN_OK, Vn_DestroyEmitter(emitter));
}

void ExpectVariableControlToVariableControlInitial(bool direct, std::uint32_t ordinal) {
    SCOPED_TRACE(ordinal);
    (void)Vn_Term();
    VnConfig config = harkentest::MakeNullConfig(4, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    const auto partitionBaseline = engine->playablePartitions.OccupiedCount();
    std::vector<float> samples(2048, 0.25f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision,
        1);
    image.MakeImmediateVariableControlToVariableControlPlayAction(ordinal);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    VnEmitterHandle emitter = 0;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&emitter));
    VnActionFiringHandle firing = 0;
    harken::PlayableInstanceHandle produced = 0;
    if (direct) {
        const auto started = harken::StartCurrentPlayableByIdentity(
            harken::PlayableKindV1::Container,
            image.containers[3].containerStableId, emitter);
        ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
        produced = started.instance;
    } else {
        VnPostActionDesc desc = ValidPostDesc();
        desc.actionId = image.actions[9].actionStableId;
        desc.emitter = emitter;
        ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
        VnActionStepResult play{};
        play.structSize = sizeof(play);
        ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
        ASSERT_EQ(VN_ACTION_STEP_ACTIVE, play.state);
        produced = play.producedPlayableInstance;
    }
    ASSERT_NE(0u, produced);

    auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [produced](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.InvocationValid() && candidate.Invocation().variableControlOuterRootInstance == 0 &&
                   candidate.rootInstance == produced;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    ASSERT_TRUE(row->variableControlInstance.Valid());
    ASSERT_EQ(1u, row->variableControlNestedVariableControlCount);
    EXPECT_EQ(image.containers[0].children[0].stableChildOrdinal,
              row->variableControlControllers[0].selectedOrdinal);
    EXPECT_EQ(0u, row->variableControlControllers[0].continuationOrdinal);
    const auto innerToken = row->variableControlControllers[0].instance;
    ASSERT_TRUE(innerToken.Valid());
    harken::VariableControlInstanceSnapshot innerSnapshot{};
    ASSERT_TRUE(engine->variableControlInstances.Capture(
        innerToken, &innerSnapshot));
    EXPECT_EQ(row->variableControlChildInstances[0], innerSnapshot.rootInstance);
    EXPECT_EQ(image.containers[0].containerStableId,
              innerSnapshot.containerStableId);
    EXPECT_EQ(harken::VariableControlSideState::Pending,
              innerSnapshot.discrete.state);
    EXPECT_TRUE(innerSnapshot.discrete.decision.Valid());
    EXPECT_FALSE(innerSnapshot.discrete.lastApplied.Valid());

    const auto innerRoot = row->variableControlChildInstances[0];
    const auto innerView = engine->playableInstances.Classify(innerRoot);
    ASSERT_TRUE(innerView.live);
    EXPECT_EQ(row->rootInstance, innerView.parent);
    const auto innerChild = engine->playableInstances.FirstChild(innerRoot);
    ASSERT_NE(0u, innerChild);
    EXPECT_EQ(innerRoot,
              engine->playableInstances.Classify(innerChild).parent);
    EXPECT_EQ(harken::PlayableKind::Sound,
              engine->playableInstances.Classify(innerChild).kind);
    EXPECT_EQ(innerChild, row->variableControlChildInstances[1]);
    harken::ContainerPlaybackRow innerPlayback{};
    ASSERT_TRUE(engine->containerPlayback.Capture(innerRoot, &innerPlayback));
    EXPECT_EQ(static_cast<std::uint8_t>(harken::ContainerModeV1::VariableControl), innerPlayback.mode);
    EXPECT_EQ(harken::ContainerPlaybackPhase::Active, innerPlayback.phase);
    EXPECT_EQ(innerView.scheduleEpoch, innerPlayback.expectedScheduleEpoch);
    EXPECT_EQ(0u, innerPlayback.activeChild);
    EXPECT_EQ(CanonicalActionWorld::kFirstSound, row->leaf.stableId);
    EXPECT_EQ(2u, row->variableControlNestedChildCount);

    auto* innerService = engine->ResolvePlayableService(row->variableControlControllers[0].service);
    ASSERT_NE(nullptr, innerService);
    EXPECT_EQ(innerRoot, innerService->ownerInstance);
    EXPECT_NE(row->identity, innerService->identity);
    EXPECT_NE(row->partition.slot, innerService->partition.slot);
    EXPECT_EQ(&row->Invocation(), &innerService->Invocation());
    const auto originalSource = CaptureOriginalSource(*engine, innerChild);
    const auto* originalRecord = engine->sourceTerminals.Resolve(originalSource.token);
    ASSERT_NE(nullptr, originalRecord);
    EXPECT_EQ(innerService, engine->ResolveSourceResourceOwner(originalRecord->resourceOwner));
    const auto logicalSlot = engine->playableStorage.MemberBase(row->partition.slot);
    const auto reference = engine->ReadPlayableMemberReference(logicalSlot);
    const auto innerServiceReference = reference.service;
    harken::EnginePlayableServiceRow* resourceOwner = nullptr;
    std::size_t physicalSlot = 0;
    ASSERT_TRUE(engine->ResolvePlayableMember(reference, &resourceOwner, &physicalSlot));
    EXPECT_EQ(innerService, resourceOwner);
    EXPECT_EQ(innerChild, engine->ReadPlayableMember(physicalSlot).completion.leafInstance);
    EXPECT_EQ(originalSource.token.slot, engine->ReadPlayableMember(physicalSlot).completion.source.slot);
    EXPECT_EQ(originalSource.token.generation,
              engine->ReadPlayableMember(physicalSlot).completion.source.generation);
    const auto* record = engine->ResolveMemberProgram(reference);
    ASSERT_NE(nullptr, record);
    const auto& ownedProgram = record->schedule;
    EXPECT_EQ(innerChild, ownedProgram.ownerInstance);
    EXPECT_EQ(&record->runtime, ownedProgram.runtimeProgram.program);
    EXPECT_EQ(record->events.data(), ownedProgram.events);
    ASSERT_NE(nullptr, ownedProgram.runtimeProgram.program);
    EXPECT_EQ(record->payloads.data(), ownedProgram.runtimeProgram.program->payloads);

    if (direct) {
        ASSERT_EQ(harken::PlayableControlStatus::Ok,
                  harken::StopPlayable(*engine, produced, 0));
    } else {
        ASSERT_EQ(VN_OK, Vn_StopActionFiring(firing, 0));
    }
    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    for (std::uint32_t block = 0; block < 128; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        if (!direct) {
            ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
            if (info.state == VN_ACTION_FIRING_TERMINAL_RETAINED) break;
        } else if (!engine->playableInstances.Classify(produced).live) {
            break;
        }
    }
    if (!direct) {
        ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
    }
    EXPECT_FALSE(engine->playableInstances.Classify(produced).live);
    EXPECT_FALSE(engine->playableInstances.Classify(innerRoot).live);
    EXPECT_FALSE(engine->playableInstances.Classify(innerChild).live);
    for (std::uint32_t block = 0; block < 8 &&
         engine->playablePartitions.OccupiedCount() != partitionBaseline; ++block) {
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
    }
    EXPECT_EQ(nullptr, engine->ResolvePlayableService(innerServiceReference));
    EXPECT_EQ(0u, engine->variableControlInstances.LiveCount());
    EXPECT_EQ(partitionBaseline, engine->playablePartitions.OccupiedCount());
    if (!direct) ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    ASSERT_EQ(VN_OK, Vn_DestroyEmitter(emitter));
}

void ExpectDeepVariableControlInitialPlayback(bool direct, std::uint32_t ordinal) {
    SCOPED_TRACE(ordinal);
    (void)Vn_Term();
    harkentest::EngineSession session(harkentest::MakeNullConfig(4, 64, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto& engine = *session.Engine();
    std::vector<float> samples(8192, 0.25f);
    const auto pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
    CanonicalActionWorld image(
        engine.registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision, 1);
    image.MakeImmediateVariableControlToVariableControlPlayAction(ordinal);
    image.containers[2] = image.containers[0];
    image.containers[2].containerStableId = image.properties[4].stableId;
    image.containers[2].programSemanticFingerprint =
        image.properties[4].programSemanticFingerprint;
    image.containers[2].authoredStableOrder = 2;
    harken::ContainerChildProgramViewV2 children[4]{};
    const std::uint32_t targetProperties[] = {4, 0, 3, 2};
    for (std::uint32_t index = 0; index < 4; ++index) {
        children[index] = image.innerVariableControlChild;
        const auto& property = image.properties[targetProperties[index]];
        auto& playable = children[index].playable;
        playable.kind = index == 1 ? harken::PlayableKindV1::Sound
                                  : harken::PlayableKindV1::Container;
        playable.stableId = property.stableId;
        playable.expectedProgramSemanticFingerprint = property.programSemanticFingerprint;
        playable.contentRevision = property.contentRevision;
        playable.routeStableId = property.routeStableId;
        playable.compatibilityFingerprint = property.compatibilityFingerprint;
        children[index].frequencyWeight = index == 1 ? 1 : 0;
        image.containers[index].children = &children[index];
        auto& occurrence = image.occurrences[index];
        occurrence.parentStableId = image.containers[index].containerStableId;
        occurrence.parentProgramSemanticFingerprint =
            image.containers[index].programSemanticFingerprint;
        occurrence.stableOccurrenceOrdinal = ordinal;
        occurrence.childPlayable = playable;
        occurrence.occurrenceSemanticFingerprint =
            harken::ComputePlayableOccurrenceFingerprintV1(occurrence);
    }
    image.world.playableOccurrenceCount = 4;
    image.world.identity.capabilityMask =
        harken::detail::ComputeCurrentWorldLocalCapabilityMaskV1(image.world);
    image.world.identity.runtimeSemanticFingerprint =
        harken::ComputeCurrentWorldFingerprintV4(image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(engine, image.world).status);

    const auto playableBaseline = engine.playableInstances.LiveCount();
    const auto containerBaseline = engine.containerPlayback.LiveCount();
    const auto variableControlBaseline = engine.variableControlInstances.LiveCount();
    const auto decisionBaseline = engine.decisions.LiveCount();
    const auto partitionBaseline = engine.playablePartitions.OccupiedCount();
    VnEmitterHandle emitter = 0;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&emitter));
    VnActionFiringHandle firing = 0;
    harken::PlayableInstanceHandle produced = 0;
    VnActionStepResult step{};
    step.structSize = sizeof(step);
    if (direct) {
        const auto started = harken::StartCurrentPlayableByIdentity(
            harken::PlayableKindV1::Container,
            image.containers[3].containerStableId, emitter);
        ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
        produced = started.instance;
    } else {
        auto desc = ValidPostDesc();
        desc.actionId = image.actions[9].actionStableId;
        desc.emitter = emitter;
        ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
        ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &step));
        ASSERT_EQ(VN_OK, step.result);
        ASSERT_EQ(VN_ACTION_STEP_ACTIVE, step.state);
        produced = step.producedPlayableInstance;
    }
    ASSERT_NE(0u, produced);
    std::array<harken::PlayableInstanceHandle, 5> tree{produced};
    for (std::size_t index = 1; index < tree.size(); ++index) {
        tree[index] = engine.playableInstances.FirstChild(tree[index - 1]);
        ASSERT_NE(0u, tree[index]);
        const auto child = engine.playableInstances.Classify(tree[index]);
        EXPECT_TRUE(child.live);
        EXPECT_EQ(tree[index - 1], child.parent);
        EXPECT_EQ(index + 1 == tree.size() ? harken::PlayableKind::Sound
                                         : harken::PlayableKind::Container, child.kind);
    }
    EXPECT_EQ(variableControlBaseline + 3u, engine.variableControlInstances.LiveCount());
    EXPECT_EQ(containerBaseline + 4u, engine.containerPlayback.LiveCount());

    float peak = 0.0f;
    for (std::uint32_t block = 0; block < 16; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine.nullBackend.Pump(1);
        const auto* output = engine.nullBackend.LastBlock();
        ASSERT_NE(nullptr, output);
        const auto sampleCount = engine.nullBackend.BlockFrames() * engine.nullBackend.Channels();
        for (std::uint32_t sample = 0; sample < sampleCount; ++sample)
            peak = std::max(peak, std::abs(output[sample]));
        if (!direct) {
            ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &step));
            ASSERT_EQ(VN_OK, step.result);
            ASSERT_EQ(VN_ACTION_STEP_ACTIVE, step.state);
        }
    }
    ASSERT_GT(peak, 0.0f);
    EXPECT_FALSE(engine.runtimeRecreateRequired);
    for (const auto instance : tree)
        EXPECT_TRUE(engine.playableInstances.Classify(instance).live);
    if (direct) {
        ASSERT_EQ(harken::PlayableControlStatus::Ok,
                  harken::StopPlayable(engine, produced, 0));
    } else {
        ASSERT_EQ(VN_OK, Vn_StopActionFiring(firing, 0));
    }
    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    for (std::uint32_t block = 0; block < 128; ++block) {
        engine.nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        if (!direct) {
            ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
            if (info.state != VN_ACTION_FIRING_TERMINAL_RETAINED) continue;
        }
        if (engine.playableInstances.LiveCount() == playableBaseline &&
            engine.containerPlayback.LiveCount() == containerBaseline &&
            engine.variableControlInstances.LiveCount() == variableControlBaseline &&
            engine.decisions.LiveCount() == decisionBaseline &&
            engine.playablePartitions.OccupiedCount() == partitionBaseline) break;
    }
    if (!direct) {
        ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
        ASSERT_EQ(0u, info.livePlayableCount);
        ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &step));
        EXPECT_EQ(VN_OK, step.result);
        ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    }
    for (const auto instance : tree)
        EXPECT_FALSE(engine.playableInstances.Classify(instance).live);
    EXPECT_EQ(playableBaseline, engine.playableInstances.LiveCount());
    EXPECT_EQ(containerBaseline, engine.containerPlayback.LiveCount());
    EXPECT_EQ(variableControlBaseline, engine.variableControlInstances.LiveCount());
    EXPECT_EQ(decisionBaseline, engine.decisions.LiveCount());
    EXPECT_EQ(partitionBaseline, engine.playablePartitions.OccupiedCount());
    EXPECT_EQ(0u, engine.voices.ActiveCount());
    ASSERT_EQ(VN_OK, Vn_DestroyEmitter(emitter));
}

TEST(ActionFiringApi,
     ImmediateVariableControlToVariableControlInitialStopsAndReclaims) {
    for (const auto ordinal : {0u, 7u}) {
        ExpectVariableControlToVariableControlInitial(false, ordinal);
        ExpectDeepVariableControlInitialPlayback(false, ordinal);
    }
}

TEST(ActionFiringApi, VariableControlSourceFailurePreservesOriginalStreamReason) {
    for (const auto reason : {harken::StreamTerminalReason::ProducerFailure,
                              harken::StreamTerminalReason::IntegrityAbort}) {
        SCOPED_TRACE(static_cast<int>(reason));
        std::array<float, 512> storage{};
        storage.fill(0.25f);
        float* planes[harken::kMaxChannels] = {storage.data()};
        harken::StreamRing ring;
        ring.Wire(planes, storage.size());
        ring.ResetForUse(1);
        ring.PublishWrite(256);
        ring.state.store(harken::StreamSlotState::Active);
        ASSERT_TRUE(ring.MarkEndOfData(reason));
        harkentest::EngineSession session(harkentest::MakeNullConfig(4, 64, 48000));
        ASSERT_EQ(VN_OK, session.InitResult());
        auto& engine = *session.Engine();
        const std::vector<float> pcmSamples(4096, 0.25f);
        const auto pcm = harkentest::MonoDesc(pcmSamples, 48000);
        ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
        ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &pcm));
        CanonicalActionWorld image(
            engine.registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
            engine.registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
        image.MakeImmediateVariableControlPlayAction();
        ASSERT_EQ(harken::WorldInstallStatus::Ok,
            harken::InstallContainerWorldV1(engine, image.world).status);
        const auto playableBefore = engine.playableInstances.LiveCount();
        const auto controlBefore = engine.variableControlInstances.LiveCount();
        VnPostActionDesc desc = ValidPostDesc();
        desc.actionId = image.actions[9].actionStableId;
        VnActionFiringHandle firing = 0;
        ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
        VnActionStepResult step{};
        step.structSize = sizeof(step);
        ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &step));
        const auto controller = step.producedPlayableInstance;
        auto row = std::find_if(engine.playableServices.begin(), engine.playableServices.end(),
            [controller](const auto& candidate) { return candidate.rootInstance == controller; });
        ASSERT_NE(engine.playableServices.end(), row);
        for (std::uint32_t block = 0; block < 16; ++block) {
            engine.nullBackend.Pump(1);
            ASSERT_EQ(VN_OK, Vn_Update());
        }
        ASSERT_EQ(harken::PlayableControlLifecycle::Active, row->controlLifecycle);
        ASSERT_EQ(1u, engine.voices.ActiveCount());

        // Isolate source-result consumption with a real stream child under the
        // accepted controller. This does not claim authored streaming support.
        const auto leaf = engine.playableInstances.Acquire(harken::PlayableKind::Sound, controller);
        const auto epoch = engine.playableInstances.Classify(leaf).scheduleEpoch;
        ASSERT_TRUE(engine.playableInstances.AcquireSourceRetirementHold(leaf, epoch));
        VnVoiceHandle voice = 0;
        const auto pan = harken::ResolvePanGains(engine.config.mixChannelLayout, 0.0f);
        ASSERT_EQ(VN_OK, engine.voices.PlayStream(&ring, 1, 48000,
            0, 0.0f, 1.0, 0, false, 0.0f, 0.0f, 0.0f, pan, 0, 256, 0, 256, 1,
            harken::SelectResampleProfile(48000, 48000), &voice));
        harken::VoiceReleaseObserver release{};
        ASSERT_TRUE(engine.voices.CaptureReleaseObserver(voice, &release));
        const auto source = engine.sourceTerminals.Reserve(engine.playableInstances,
            leaf, epoch, voice, release, controller,
            {row->identity.slot, row->identity.generation, row->ownerInstance,
             row->ownerEpoch, row->Invocation().slot, row->invocationGeneration});
        ASSERT_TRUE(source.Valid());
        ASSERT_TRUE(engine.voices.BindSourceTerminal(voice, engine.sourceTerminals.Resolve(source), source));
        engine.voices.ApplyPlay(voice, voice, 0, engine.mixer.BlocksRendered());
        engine.nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        harken::SourceTerminalPayload payload{};
        EXPECT_FALSE(engine.sourceTerminals.Capture(source, engine.mixer.BlocksRendered(), &payload));
        EXPECT_EQ(harken::PlayableControlLifecycle::Active, row->controlLifecycle);
        bool completed = false;
        for (std::uint32_t block = 0; block < 8 && !completed; ++block) {
            engine.nullBackend.Pump(1);
            completed = engine.sourceTerminals.Capture(source, engine.mixer.BlocksRendered(), &payload);
            ASSERT_EQ(VN_OK, Vn_Update());
        }
        ASSERT_TRUE(completed);
        const bool corrupt = reason == harken::StreamTerminalReason::IntegrityAbort;
        const auto expected = corrupt ? VN_BAD_STREAM_FILE : VN_RUNTIME_RECREATE_REQUIRED;
        EXPECT_EQ(corrupt ? harken::SourceTerminalKind::IntegrityAbort
                         : harken::SourceTerminalKind::ProducerFailure, payload.kind);
        const auto leafState = engine.playableInstances.Classify(leaf);
        ASSERT_TRUE(leafState.live);
        EXPECT_EQ(harken::PlayableTerminalKind::Failure, leafState.terminalOutcome.kind);
        EXPECT_EQ(expected, leafState.terminalOutcome.resultCode);
        EXPECT_EQ(harken::PlayableControlReason::StartRefused, row->controlReason);
        EXPECT_TRUE(engine.voices.ReleaseObserved(release));
        const auto sequence = engine.mixer.BlocksRendered();
        for (std::uint32_t repeat = 0; repeat < 3; ++repeat) {
            ASSERT_EQ(VN_OK, Vn_Update());
            EXPECT_EQ(sequence, engine.mixer.BlocksRendered());
            EXPECT_TRUE(engine.playableInstances.HasSourceRetirementHold(leaf));
            EXPECT_TRUE(engine.playableInstances.Classify(controller).live);
        }
        VnActionFiringInfo info{};
        info.structSize = sizeof(info);
        for (std::uint32_t block = 0; block < 96; ++block) {
            engine.nullBackend.Pump(1);
            ASSERT_EQ(VN_OK, Vn_Update());
            ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
            if (info.state == VN_ACTION_FIRING_TERMINAL_RETAINED) break;
        }
        ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
        EXPECT_EQ(corrupt ? VN_ACTION_TERMINAL_MEDIA_NOT_READY
                         : VN_ACTION_TERMINAL_RUNTIME_ERROR, info.terminalReason);
        ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &step));
        EXPECT_EQ(VN_ACTION_STEP_FAILED, step.state);
        EXPECT_EQ(expected, step.result);
        EXPECT_EQ(nullptr, engine.sourceTerminals.Resolve(source));
        EXPECT_EQ(playableBefore, engine.playableInstances.LiveCount());
        EXPECT_EQ(controlBefore, engine.variableControlInstances.LiveCount());
        EXPECT_EQ(0u, engine.voices.ActiveCount());
        ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    }
}

TEST(ActionFiringApi,
     ImmediateVariableControlOwnerFailureReclaimsNestedInstances) {
    (void)Vn_Term();
    harkentest::EngineSession session(
        harkentest::MakeNullConfig(8, 64, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> samples(2048, 0.25f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision,
        1);
    image.MakeImmediateVariableControlToVariableControlPlayAction();
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    const auto playableBaseline = engine->playableInstances.LiveCount();
    const auto containerBaseline = engine->containerPlayback.LiveCount();
    const auto variableControlBaseline =
        engine->variableControlInstances.LiveCount();
    const auto decisionBaseline = engine->decisions.LiveCount();
    VnEmitterHandle emitter = 0;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&emitter));
    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    desc.emitter = emitter;
    engine->forceActionFinalOwnerCommitFailureForTest = true;

    auto ownersBefore = CaptureActionReclaimableOwners(*engine);
    ++ownersBefore[0]; // The accepted failure retains its queryable firing until Release.
    const auto commandHead = engine->commands.PublishedHead();
    const auto sourceGenerations = CaptureSourceGenerations(*engine);
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    ASSERT_NE(0u, firing);
    EXPECT_TRUE(engine->runtimeRecreateRequired);
    EXPECT_FALSE(engine->forceActionFinalOwnerCommitFailureForTest);
    ASSERT_NO_FATAL_FAILURE(ExpectBoundSourcesReleased(*engine, sourceGenerations));
    EXPECT_EQ(commandHead, engine->commands.PublishedHead());
    EXPECT_EQ(0u, engine->voices.ActiveCount());
    EXPECT_EQ(0u, engine->timelineArms.LiveCount());
    for (std::uint32_t block = 0; block < 16; ++block) {
        const auto before = engine->mixer.BlocksRendered();
        engine->nullBackend.Pump(1);
        ASSERT_EQ(before + 1u, engine->mixer.BlocksRendered());
        const auto* output = engine->nullBackend.LastBlock();
        ASSERT_NE(nullptr, output);
        for (std::uint32_t sample = 0; sample < engine->nullBackend.BlockFrames() * engine->nullBackend.Channels(); ++sample)
            EXPECT_FLOAT_EQ(0.0f, output[sample]);
        ASSERT_EQ(VN_OK, Vn_Update());
        if (CaptureActionReclaimableOwners(*engine) == ownersBefore) break;
    }
    EXPECT_EQ(ownersBefore, CaptureActionReclaimableOwners(*engine));
    EXPECT_EQ(commandHead, engine->commands.PublishedHead());
    EXPECT_EQ(playableBaseline, engine->playableInstances.LiveCount());
    EXPECT_EQ(containerBaseline, engine->containerPlayback.LiveCount());
    EXPECT_EQ(variableControlBaseline,
              engine->variableControlInstances.LiveCount());
    EXPECT_EQ(decisionBaseline, engine->decisions.LiveCount());
    for (const auto& scratch : engine->actionPlayScratch) {
        EXPECT_FALSE(scratch.prepared);
        EXPECT_EQ(nullptr, scratch.row);
        EXPECT_EQ(0u, scratch.playableTreeExecutor.OwnerTokenCount());
    }
    VnActionStepResult step{};
    step.structSize = sizeof(step);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &step));
    EXPECT_EQ(VN_ACTION_STEP_FAILED, step.state);
    EXPECT_EQ(VN_RUNTIME_RECREATE_REQUIRED, step.result);
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    ASSERT_EQ(VN_OK, Vn_DestroyEmitter(emitter));
}

TEST(ActionFiringApi,
     ImmediateVariableControlFailureBeforeMemberAttachReclaimsNestedInstances) {
    (void)Vn_Term();
    harkentest::EngineSession session(
        harkentest::MakeNullConfig(8, 64, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> samples(2048, 0.25f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision,
        1);
    image.MakeImmediateVariableControlToVariableControlPlayAction();
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    const auto playableBaseline = engine->playableInstances.LiveCount();
    const auto containerBaseline = engine->containerPlayback.LiveCount();
    const auto variableControlBaseline =
        engine->variableControlInstances.LiveCount();
    const auto decisionBaseline = engine->decisions.LiveCount();
    const auto partitionBaseline = engine->playablePartitions.OccupiedCount();
    VnEmitterHandle emitter = 0;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&emitter));
    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    desc.emitter = emitter;
    engine->forceActionVariableControlBeforeMemberFailureForTest = true;

    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_RUNTIME_RECREATE_REQUIRED, Vn_PostAction(&desc, &firing));
    EXPECT_EQ(0u, firing);
    EXPECT_FALSE(engine->forceActionVariableControlBeforeMemberFailureForTest);
    EXPECT_TRUE(engine->runtimeRecreateRequired);
    for (std::uint32_t block = 0; block < 16; ++block) {
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        if (engine->playableInstances.LiveCount() == playableBaseline &&
            engine->containerPlayback.LiveCount() == containerBaseline &&
            engine->variableControlInstances.LiveCount() ==
                variableControlBaseline &&
            engine->playablePartitions.OccupiedCount() == partitionBaseline)
            break;
    }
    EXPECT_EQ(playableBaseline, engine->playableInstances.LiveCount());
    EXPECT_EQ(containerBaseline, engine->containerPlayback.LiveCount());
    EXPECT_EQ(variableControlBaseline,
              engine->variableControlInstances.LiveCount());
    EXPECT_EQ(decisionBaseline, engine->decisions.LiveCount());
    EXPECT_EQ(partitionBaseline, engine->playablePartitions.OccupiedCount());
    EXPECT_EQ(0u, engine->voices.ActiveCount());
    for (const auto& scratch : engine->actionPlayScratch) {
        EXPECT_FALSE(scratch.prepared);
        EXPECT_EQ(nullptr, scratch.row);
        EXPECT_EQ(0u, scratch.playableTreeExecutor.OwnerTokenCount());
    }
    ASSERT_EQ(VN_OK, Vn_DestroyEmitter(emitter));
}

