TEST(ActionFiringApi, LongVariableControlChildrenAllowOverlappingPostsPastTimelineHorizon) {
    harkentest::EngineSession session(harkentest::MakeNullConfig(64, 256, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    std::vector<float> samples(48000, 0.02f);
    const auto pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &pcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
    image.MakeImmediateVariableControlPlayAction();
    ASSERT_EQ(harken::WorldInstallStatus::Ok, harken::InstallContainerWorldV1(*engine, image.world).status);
    auto desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    std::array<VnActionFiringHandle, 12> firings{};
    VnVoiceHandle previousRender = 0;
    for (unsigned trigger = 0; trigger < firings.size(); ++trigger) {
        SCOPED_TRACE(trigger);
        const std::uint64_t target = static_cast<std::uint64_t>(trigger) * 670 * 48 / 256;
        while (engine->mixer.BlocksRendered() < target) {
            ASSERT_EQ(VN_OK, Vn_Update());
            engine->nullBackend.Pump(1);
        }
        ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firings[trigger]));
        VnActionStepResult step{};
        step.structSize = sizeof(step);
        ASSERT_EQ(VN_OK, Vn_QueryActionStep(firings[trigger], 0, &step));
        const auto row = std::find_if(engine->playableServices.begin(), engine->playableServices.end(),
            [&](const auto& candidate) { return candidate.rootInstance == step.producedPlayableInstance; });
        ASSERT_NE(engine->playableServices.end(), row);
        const auto render = row->renderHandle;
        std::size_t slot = 0;
        ASSERT_TRUE(engine->ResolvePlayableMemberSlot(row->scheduleStorageBase, &slot));
        const auto originalArm = engine->ReadPlayableMember(slot).arm;
        const auto before = engine->mixer.BlocksRendered();
        for (unsigned block = 0; block < 8; ++block) {
            ASSERT_EQ(VN_OK, Vn_Update());
            engine->nullBackend.Pump(1);
        }
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_NE(nullptr, engine->voices.Resolve(render));
        EXPECT_FALSE(engine->voices.Resolve(render)->timelineGated);
        harken::EngineTimelineVoiceInstallIdentity installation{};
        ASSERT_TRUE(engine->CaptureTimelineVoiceInstallIdentity(render, &installation));
        EXPECT_EQ(step.producedPlayableInstance, installation.rootInstance);
        EXPECT_TRUE(harken::OriginalSourceSubmissionRegistry::SameToken(originalArm, installation.startArm));
        EXPECT_EQ(installation.onsetFrame / engine->config.blockFrames + 1u,
            engine->ReadPlayableMember(slot).completion.sourceStartedBlockSequence);
        EXPECT_GT(engine->mixer.BlocksRendered(), before);
        if (previousRender != 0) EXPECT_NE(nullptr, engine->voices.Resolve(previousRender));
        previousRender = render;
        EXPECT_GT(harkentest::Peak(engine->nullBackend.LastBlock(),
            engine->nullBackend.BlockFrames() * engine->nullBackend.Channels()), 0.001f);
    }
    for (auto firing : firings) ASSERT_EQ(VN_OK, Vn_StopActionFiring(firing, 0));
    for (unsigned block = 0; block < 96; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    for (auto firing : firings) ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    EXPECT_EQ(0u, engine->voices.ActiveCount());
    EXPECT_EQ(0u, engine->playableInstances.LiveCount());
    EXPECT_FALSE(engine->runtimeRecreateRequired);
}

TEST(ActionFiringApi,
     ImmediateVariableControlPlayUsesLastCrossScopeStep) {
    for (bool globalFirst : {false, true}) {
        SCOPED_TRACE(globalFirst);
        harkentest::EngineSession session(harkentest::MakeNullConfig(2, 64, 48000));
        ASSERT_EQ(VN_OK, session.InitResult());
        auto* engine = session.Engine();
        std::vector<float> first(64, 0.25f);
        std::vector<float> second(128, -0.25f);
        const auto firstPcm = harkentest::MonoDesc(first, 48000);
        const auto secondPcm = harkentest::MonoDesc(second, 48000);
        ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &firstPcm));
        ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &secondPcm));
        CanonicalActionWorld image(
            engine->registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
            engine->registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
        image.MakeSetValueThenImmediateVariableControlPlayAction();
        image.steps[13] = image.steps[12];
        image.steps[13].authoredEventIndex = 2;
        image.steps[12] = image.steps[11];
        image.steps[12].authoredEventIndex = 1;
        auto& global = image.steps[globalFirst ? 11 : 12];
        auto& local = image.steps[globalFirst ? 12 : 11];
        global.scope = harken::ActionScopeV1::Global;
        global.valueBits = std::bit_cast<std::uint32_t>(3.0f);
        local.scope = harken::ActionScopeV1::Emitter;
        local.valueBits = std::bit_cast<std::uint32_t>(1.0f);
        image.actions[9].stepCount = 3;
        image.actions[9].expandedStepOccurrenceCount = 3;
        image.actions[9].programSemanticFingerprint =
            harken::ComputeActionProgramFingerprintV1(image.actions[9]);
        image.world.identity.runtimeSemanticFingerprint =
            harken::ComputeCurrentWorldFingerprintV4(image.world);
        ASSERT_EQ(harken::WorldInstallStatus::Ok,
                  harken::InstallContainerWorldV1(*engine, image.world).status);
        VnEmitterHandle emitter = 0;
        ASSERT_EQ(VN_OK, Vn_CreateEmitter(&emitter));
        auto desc = ValidPostDesc();
        desc.actionId = image.actions[9].actionStableId;
        desc.emitter = emitter;
        VnActionFiringHandle firing = 0;
        ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
        VnActionStepResult play{};
        play.structSize = sizeof(play);
        ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 2, &play));
        ASSERT_NE(0u, play.producedPlayableInstance);
        const auto row = std::find_if(
            engine->playableServices.begin(), engine->playableServices.end(),
            [&](const harken::EnginePlayableServiceRow& candidate) {
                return candidate.rootInstance == play.producedPlayableInstance;
            });
        ASSERT_NE(engine->playableServices.end(), row);
        EXPECT_EQ(globalFirst ? CanonicalActionWorld::kSecondSound
                              : CanonicalActionWorld::kFirstSound, row->leaf.stableId);
        for (std::uint32_t block = 0; block < 32; ++block) {
            ASSERT_EQ(VN_OK, Vn_Update());
            engine->nullBackend.Pump(1);
        }
        ASSERT_EQ(VN_OK, Vn_Update());
        VnVariableQueryDescV1 query{};
        query.structSize = sizeof(query);
        query.variableId = image.variables[3].variableId;
        query.emitter = emitter;
        VnVariableQueryResultV1 value{};
        value.structSize = sizeof(value);
        ASSERT_EQ(VN_OK, Vn_QueryVariable(&query, &value));
        EXPECT_FLOAT_EQ(globalFirst ? 1.0f : 3.0f, value.currentValue);
        EXPECT_EQ(globalFirst ? 1u : 0u, value.hasEmitterOverride);
        EXPECT_EQ(0u, value.pendingCount);
        ASSERT_EQ(VN_OK, Vn_DestroyEmitter(emitter));
    }
}

TEST(ActionFiringApi,
     ImmediateVariableControlPlayIgnoresLaterPreparedSetValue) {
    (void)Vn_Term();
    VnConfig config = harkentest::MakeNullConfig(2, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> first(64, 0.25f);
    std::vector<float> second(128, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kSecondSound,
                             &secondPcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound)
            .contentRevision);
    image.MakeImmediateVariableControlPlayThenSetValueAction();
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));

    VnActionStepResult play{};
    play.structSize = sizeof(play);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
    ASSERT_NE(0u, play.producedPlayableInstance);
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == play.producedPlayableInstance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    ExpectVariableControlTree(*engine, *row, 1u, 1u);
    EXPECT_EQ(CanonicalActionWorld::kFirstSound, row->leaf.stableId);

    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    for (std::uint32_t block = 0; block < 16; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
        if (info.state == VN_ACTION_FIRING_TERMINAL_RETAINED) {
            break;
        }
    }
    ASSERT_NO_FATAL_FAILURE(ExpectVariableControlNaturalCompletion(
            *engine, firing, &info));
    ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
    EXPECT_EQ(VN_ACTION_OUTCOME_SUCCEEDED, info.outcome);
    EXPECT_EQ(2u, info.directStepTerminalCount);
    EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
}

