TEST(ActionFiringApi, SiblingFiringDoesNotSeeOtherFiringStagedSetValue) {
    (void)Vn_Term();
    VnConfig config = harkentest::MakeNullConfig(4, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> first(64, 0.25f);
    std::vector<float> second(128, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kSecondSound,
                             &secondPcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound)
            .contentRevision);
    image.MakeSetValueThenImmediateVariableControlPlayAction();
    image.MakeSiblingImmediateVariableControlPlayAction();
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle firingA = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firingA));
    desc.actionId = image.actions[10].actionStableId;
    VnActionFiringHandle firingB = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firingB));

    VnActionStepResult playA{};
    playA.structSize = sizeof(playA);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firingA, 1, &playA));
    ASSERT_NE(0u, playA.producedPlayableInstance);
    const auto rowA = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == playA.producedPlayableInstance;
        });
    ASSERT_NE(engine->playableServices.end(), rowA);
    EXPECT_EQ(CanonicalActionWorld::kSecondSound, rowA->leaf.stableId);

    VnActionStepResult playB{};
    playB.structSize = sizeof(playB);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firingB, 0, &playB));
    ASSERT_NE(0u, playB.producedPlayableInstance);
    const auto rowB = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == playB.producedPlayableInstance;
        });
    ASSERT_NE(engine->playableServices.end(), rowB);
    EXPECT_EQ(CanonicalActionWorld::kFirstSound, rowB->leaf.stableId);

    VnVariableQueryDescV1 query{};
    query.structSize = sizeof(query);
    query.variableId = image.variables[3].variableId;
    VnVariableQueryResultV1 out{};
    out.structSize = sizeof(out);
    ASSERT_EQ(VN_OK, Vn_QueryVariable(&query, &out));
    EXPECT_FLOAT_EQ(3.0f, out.currentValue);

    VnActionFiringInfo infoA{};
    infoA.structSize = sizeof(infoA);
    VnActionFiringInfo infoB{};
    infoB.structSize = sizeof(infoB);
    for (std::uint32_t block = 0; block < 16; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firingA, &infoA));
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firingB, &infoB));
        if (infoA.state == VN_ACTION_FIRING_TERMINAL_RETAINED &&
            infoB.state == VN_ACTION_FIRING_TERMINAL_RETAINED) {
            break;
        }
    }
    ASSERT_NO_FATAL_FAILURE(ExpectVariableControlNaturalCompletion(
            *engine, firingA, &infoA));
    ASSERT_NO_FATAL_FAILURE(ExpectVariableControlNaturalCompletion(
            *engine, firingB, &infoB));
    ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, infoA.state);
    ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, infoB.state);
    EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(firingA));
    EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(firingB));
}

