TEST(ActionFiringApi, StopActionFiringCancelsDescendantPlayableTree) {
    (void)Vn_Term();
    VnConfig config = harkentest::MakeNullConfig(1, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> samples(4096, 0.25f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision);
    image.MakeNestedImmediateSoundPlayAction();
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[8].actionStableId;
    VnActionFiringHandle root = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &root));
    VnActionStepResult post{};
    post.structSize = sizeof(post);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(root, 0, &post));
    ASSERT_NE(0u, post.childFiring);
    ASSERT_EQ(VN_OK, Vn_Update());
    engine->nullBackend.Pump(1);
    ASSERT_EQ(VN_OK, Vn_Update());

    ASSERT_EQ(VN_OK, Vn_StopActionFiring(root, 1));
    VnActionFiringInfo rootInfo{};
    rootInfo.structSize = sizeof(rootInfo);
    VnActionFiringInfo childInfo{};
    childInfo.structSize = sizeof(childInfo);
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(root, &rootInfo));
    ASSERT_EQ(VN_OK,
              Vn_QueryActionFiring(post.childFiring, &childInfo));
    EXPECT_EQ(VN_ACTION_FIRING_STOPPING, rootInfo.state);
    EXPECT_EQ(VN_ACTION_FIRING_STOPPING, childInfo.state);
    EXPECT_EQ(1u, childInfo.livePlayableCount);

    for (std::uint32_t block = 0; block < 32; ++block) {
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(root, &rootInfo));
        if (rootInfo.state == VN_ACTION_FIRING_TERMINAL_RETAINED) {
            break;
        }
    }

    ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, rootInfo.state);
    EXPECT_EQ(VN_ACTION_OUTCOME_CANCELLED, rootInfo.outcome);
    EXPECT_EQ(VN_ACTION_TERMINAL_STOP_REQUESTED,
              rootInfo.terminalReason);
    ASSERT_EQ(VN_OK,
              Vn_QueryActionFiring(post.childFiring, &childInfo));
    EXPECT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, childInfo.state);
    EXPECT_EQ(VN_ACTION_OUTCOME_CANCELLED, childInfo.outcome);
    EXPECT_EQ(0u, childInfo.livePlayableCount);
    EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(root));
}

TEST(ActionFiringApi,
     StopActionFiringDescendantRefusalLeavesTheWholeTreeUnchanged) {
    (void)Vn_Term();
    VnConfig config = harkentest::MakeNullConfig(2, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> samples(4096, 0.25f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision);
    image.MakeNestedImmediateTwoSoundPlayAction();
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[8].actionStableId;
    VnActionFiringHandle root = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &root));
    VnActionStepResult post{};
    post.structSize = sizeof(post);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(root, 0, &post));
    ASSERT_NE(0u, post.childFiring);
    VnActionStepResult firstPlay{};
    firstPlay.structSize = sizeof(firstPlay);
    ASSERT_EQ(VN_OK,
              Vn_QueryActionStep(post.childFiring, 0, &firstPlay));
    VnActionStepResult secondPlay{};
    secondPlay.structSize = sizeof(secondPlay);
    ASSERT_EQ(VN_OK,
              Vn_QueryActionStep(post.childFiring, 1, &secondPlay));
    ASSERT_NE(0u, firstPlay.producedPlayableInstance);
    ASSERT_NE(0u, secondPlay.producedPlayableInstance);
    ASSERT_EQ(VN_OK, Vn_Update());
    engine->nullBackend.Pump(1);
    ASSERT_EQ(VN_OK, Vn_Update());

    const auto findRow = [engine](harken::PlayableInstanceHandle instance) {
        return std::find_if(
            engine->playableServices.begin(), engine->playableServices.end(),
            [instance](const harken::EnginePlayableServiceRow& row) {
                return row.phase != harken::EnginePlayableStartPhase::Free &&
                       row.rootInstance == instance;
            });
    };
    const auto firstIt = findRow(firstPlay.producedPlayableInstance);
    const auto secondIt = findRow(secondPlay.producedPlayableInstance);
    ASSERT_NE(engine->playableServices.end(), firstIt);
    ASSERT_NE(engine->playableServices.end(), secondIt);
    const std::size_t firstIndex = static_cast<std::size_t>(
        std::distance(engine->playableServices.begin(), firstIt));
    const std::size_t secondIndex = static_cast<std::size_t>(
        std::distance(engine->playableServices.begin(), secondIt));
    const std::size_t earlyIndex = std::min(firstIndex, secondIndex);
    const std::size_t refusingIndex = std::max(firstIndex, secondIndex);
    harken::EnginePlayableServiceRow& early =
        engine->playableServices[earlyIndex];
    harken::EnginePlayableServiceRow& refusing =
        engine->playableServices[refusingIndex];
    refusing.queueMode = true;
    refusing.queueArrivalDecision = {0, 1};

    VnActionFiringInfo rootBefore{};
    rootBefore.structSize = sizeof(rootBefore);
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(root, &rootBefore));
    VnActionFiringInfo childBefore{};
    childBefore.structSize = sizeof(childBefore);
    ASSERT_EQ(VN_OK,
              Vn_QueryActionFiring(post.childFiring, &childBefore));
    const std::uint64_t commandHeadBefore =
        engine->commands.PublishedHead();
    const harken::PlayableInstanceView earlyBefore =
        engine->playableInstances.Classify(early.rootInstance);
    const harken::PlayableInstanceView refusingBefore =
        engine->playableInstances.Classify(refusing.rootInstance);
    const harken::EnginePlayableStartPhase earlyPhaseBefore = early.phase;
    const harken::PlayableControlLifecycle earlyLifecycleBefore =
        early.controlLifecycle;
    const harken::EnginePlayableStartPhase refusingPhaseBefore =
        refusing.phase;
    const harken::PlayableControlLifecycle refusingLifecycleBefore =
        refusing.controlLifecycle;
    harken::PlayableRetirementObserver observer{};
    EXPECT_FALSE(engine->playableInstances.CaptureRetirementObserver(
        early.rootInstance, &observer));
    EXPECT_FALSE(engine->playableInstances.CaptureRetirementObserver(
        refusing.rootInstance, &observer));

    EXPECT_EQ(VN_OK, Vn_StopActionFiring(root, 1));
    EXPECT_GE(engine->commands.PublishedHead(), commandHeadBefore);
    EXPECT_NE(earlyBefore.scheduleEpoch,
              engine->playableInstances.Classify(early.rootInstance)
                  .scheduleEpoch);
    EXPECT_NE(refusingBefore.scheduleEpoch,
              engine->playableInstances.Classify(refusing.rootInstance)
                  .scheduleEpoch);
    EXPECT_EQ(harken::EnginePlayableStartPhase::Cancelling, early.phase);
    EXPECT_EQ(harken::PlayableControlLifecycle::Cancelling,
              early.controlLifecycle);
    EXPECT_EQ(harken::EnginePlayableStartPhase::Cancelling, refusing.phase);
    EXPECT_EQ(harken::PlayableControlLifecycle::Cancelling,
              refusing.controlLifecycle);
    EXPECT_FALSE(engine->playableInstances.CaptureRetirementObserver(
        early.rootInstance, &observer));
    EXPECT_FALSE(engine->playableInstances.CaptureRetirementObserver(
        refusing.rootInstance, &observer));
    EXPECT_FALSE(engine->runtimeRecreateRequired);

    VnActionFiringInfo rootAfter{};
    rootAfter.structSize = sizeof(rootAfter);
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(root, &rootAfter));
    VnActionFiringInfo childAfter{};
    childAfter.structSize = sizeof(childAfter);
    ASSERT_EQ(VN_OK,
              Vn_QueryActionFiring(post.childFiring, &childAfter));
    EXPECT_EQ(VN_ACTION_FIRING_STOPPING, rootAfter.state);
    EXPECT_EQ(VN_ACTION_OUTCOME_PENDING, rootAfter.outcome);
    EXPECT_EQ(VN_ACTION_TERMINAL_STOP_REQUESTED,
              rootAfter.terminalReason);
    EXPECT_EQ(VN_ACTION_FIRING_STOPPING, childAfter.state);
    EXPECT_EQ(VN_ACTION_OUTCOME_PENDING, childAfter.outcome);
    EXPECT_EQ(VN_ACTION_TERMINAL_STOP_REQUESTED,
              childAfter.terminalReason);
    EXPECT_EQ(2u, childAfter.directStepTerminalCount);

    refusing.queueArrivalDecision = {};
    refusing.queueMode = false;
    for (std::uint32_t block = 0; block < 128; ++block) {
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(root, &rootAfter));
        if (rootAfter.state == VN_ACTION_FIRING_TERMINAL_RETAINED) {
            break;
        }
    }
    ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, rootAfter.state);
    EXPECT_EQ(VN_ACTION_OUTCOME_CANCELLED, rootAfter.outcome);
    EXPECT_EQ(VN_ACTION_TERMINAL_STOP_REQUESTED,
              rootAfter.terminalReason);
    ASSERT_EQ(VN_OK,
              Vn_QueryActionFiring(post.childFiring, &childAfter));
    EXPECT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, childAfter.state);
    EXPECT_EQ(VN_ACTION_OUTCOME_CANCELLED, childAfter.outcome);
    EXPECT_EQ(VN_ACTION_TERMINAL_STOP_REQUESTED,
              childAfter.terminalReason);
    EXPECT_EQ(0u, childAfter.livePlayableCount);
}

void ExpectStopDetachesAuthoredStopObserverBeforeLateRetirement(bool stopAll) {
    (void)Vn_Term();
    VnConfig config = harkentest::MakeNullConfig(1, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> samples(4096, 0.25f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision);
    image.MakeImmediateSoundPlayAndSeparateStopActions();
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    VnPostActionDesc playDesc = ValidPostDesc();
    playDesc.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle playFiring = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&playDesc, &playFiring));
    VnPostActionDesc stopDesc = ValidPostDesc();
    stopDesc.actionId = image.actions[8].actionStableId;
    VnActionFiringHandle stopFiring = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&stopDesc, &stopFiring));

    VnActionStepResult play{};
    play.structSize = sizeof(play);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(playFiring, 0, &play));
    ASSERT_NE(0u, play.producedPlayableInstance);
    harken::PlayableRetirementObserver observer{};
    ASSERT_TRUE(engine->playableInstances.CaptureRetirementObserver(
        play.producedPlayableInstance, &observer));
    ASSERT_EQ(stopFiring, observer.actionFiring);

    ASSERT_EQ(VN_OK, stopAll ? Vn_StopAll(0) : Vn_StopActionFiring(stopFiring, 0));
    EXPECT_EQ(VN_OK, stopAll ? Vn_StopAll(0) : Vn_StopActionFiring(stopFiring, 0));
    EXPECT_FALSE(engine->playableInstances.CaptureRetirementObserver(
        play.producedPlayableInstance, &observer));
    VnActionFiringInfo stopInfo{};
    stopInfo.structSize = sizeof(stopInfo);
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(stopFiring, &stopInfo));
    EXPECT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, stopInfo.state);
    EXPECT_EQ(VN_ACTION_OUTCOME_CANCELLED, stopInfo.outcome);
    EXPECT_EQ(VN_ACTION_TERMINAL_STOP_REQUESTED,
              stopInfo.terminalReason);
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(stopFiring));

    VnActionFiringInfo playInfo{};
    playInfo.structSize = sizeof(playInfo);
    for (std::uint32_t block = 0; block < 32; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_EQ(VN_OK,
                  Vn_QueryActionFiring(playFiring, &playInfo));
        if (playInfo.state == VN_ACTION_FIRING_TERMINAL_RETAINED) {
            break;
        }
    }
    ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, playInfo.state);
    EXPECT_FALSE(engine->runtimeRecreateRequired);
    EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(playFiring));
}

TEST(ActionFiringApi, StopActionFiringDetachesAuthoredStopObserverBeforeLateRetirement) {
    ExpectStopDetachesAuthoredStopObserverBeforeLateRetirement(false);
}

TEST(ActionFiringApi, StopAllDetachesAuthoredStopObserverBeforeLateRetirement) {
    ExpectStopDetachesAuthoredStopObserverBeforeLateRetirement(true);
}

TEST(ActionFiringApi, CurrentWorldReplacementCancelsActiveActionFiring) {
    (void)Vn_Term();
    VnConfig config = harkentest::MakeNullConfig(8, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> first(4096, 0.25f);
    std::vector<float> second(4096, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kSecondSound,
                             &secondPcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound)
            .contentRevision);
    image.MakeImmediateSequenceQueuePlayAction();
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&desc.emitter));
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    ASSERT_EQ(VN_OK, Vn_Update());
    engine->nullBackend.Pump(1);
    ASSERT_EQ(VN_OK, Vn_Update());

    CanonicalActionWorld replacement(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound)
            .contentRevision);
    replacement.variables[0].defaultValue = 0.25f;
    replacement.world.identity.runtimeSemanticFingerprint =
        harken::ComputeCurrentWorldFingerprintV4(replacement.world);
    ASSERT_EQ(harken::WorldInstallStatus::Backpressure,
              harken::InstallContainerWorldV1(*engine, replacement.world)
                  .status);

    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
    EXPECT_EQ(VN_ACTION_FIRING_STOPPING, info.state);
    EXPECT_EQ(VN_ACTION_TERMINAL_WORLD_REPLACED, info.terminalReason);
    for (std::uint32_t block = 0; block < 96; ++block) {
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
        if (info.state == VN_ACTION_FIRING_TERMINAL_RETAINED) {
            break;
        }
    }

    ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
    EXPECT_EQ(VN_ACTION_OUTCOME_CANCELLED, info.outcome);
    EXPECT_EQ(VN_ACTION_TERMINAL_WORLD_REPLACED, info.terminalReason);
    VnActionStepResult play{};
    play.structSize = sizeof(play);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
    EXPECT_EQ(VN_ACTION_STEP_CANCELLED, play.state);
    EXPECT_EQ(VN_OK, play.result);
    EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
}

TEST(ActionFiringApi, TransportResetCancelsActiveActionFiring) {
    (void)Vn_Term();
    VnConfig config = harkentest::MakeNullConfig(1, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> samples(4096, 0.25f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision);
    image.MakeImmediateSoundPlayAction();
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    ASSERT_EQ(VN_OK, Vn_Update());
    engine->nullBackend.Pump(1);
    ASSERT_EQ(VN_OK, Vn_Update());

    harken::RuntimeTransportResetStatus reset =
        harken::BeginRuntimeTransportReset(*engine, 0);
    ASSERT_EQ(harken::RuntimeTransportResetStatus::Backpressure, reset);
    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
    EXPECT_EQ(VN_ACTION_FIRING_STOPPING, info.state);
    EXPECT_EQ(VN_ACTION_TERMINAL_TRANSPORT_RESET, info.terminalReason);
    for (std::uint32_t block = 0;
         block < 96 &&
         reset == harken::RuntimeTransportResetStatus::Backpressure;
         ++block) {
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        reset = harken::BeginRuntimeTransportReset(*engine, 0);
    }

    ASSERT_EQ(harken::RuntimeTransportResetStatus::Complete, reset);
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
    ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
    EXPECT_EQ(VN_ACTION_OUTCOME_CANCELLED, info.outcome);
    EXPECT_EQ(VN_ACTION_TERMINAL_TRANSPORT_RESET, info.terminalReason);
    VnActionStepResult play{};
    play.structSize = sizeof(play);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
    EXPECT_EQ(VN_ACTION_STEP_CANCELLED, play.state);
    EXPECT_EQ(VN_OK, play.result);
    EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
}

TEST(ActionFiringApi, AuthoredStopCompletesCapturedSameFiringPlay) {
    (void)Vn_Term();
    VnConfig config = harkentest::MakeNullConfig(1, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> samples(4096, 0.25f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision);
    image.MakeImmediateSoundPlayThenStopAction();
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));

    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
    EXPECT_EQ(VN_ACTION_FIRING_ACTIVE, info.state);
    EXPECT_EQ(0u, info.directStepTerminalCount);
    EXPECT_EQ(1u, info.livePlayableCount);

    VnActionStepResult play{};
    play.structSize = sizeof(play);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
    EXPECT_EQ(VN_ACTION_STEP_ACTIVE, play.state);

    VnActionStepResult stop{};
    stop.structSize = sizeof(stop);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 1, &stop));
    EXPECT_EQ(VN_ACTION_STEP_ACTIVE, stop.state);
    EXPECT_EQ(1u, stop.capturedPlayableCount);
    EXPECT_EQ(1u, stop.remainingPlayableCount);

    for (std::uint32_t block = 0; block < 32; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
        if (info.state == VN_ACTION_FIRING_TERMINAL_RETAINED) {
            break;
        }
    }

    ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
    EXPECT_EQ(VN_ACTION_OUTCOME_SUCCEEDED, info.outcome);
    EXPECT_EQ(VN_ACTION_TERMINAL_NATURAL, info.terminalReason);
    EXPECT_EQ(2u, info.directStepTerminalCount);
    EXPECT_EQ(0u, info.livePlayableCount);

    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
    EXPECT_EQ(VN_ACTION_STEP_SUCCEEDED, play.state);
    EXPECT_EQ(VN_OK, play.result);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 1, &stop));
    EXPECT_EQ(VN_ACTION_STEP_SUCCEEDED, stop.state);
    EXPECT_EQ(VN_OK, stop.result);
    EXPECT_EQ(1u, stop.capturedPlayableCount);
    EXPECT_EQ(0u, stop.remainingPlayableCount);
    EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
}

