TEST(ActionFiringApi, ImmediateCompositeTrackUsesLaneWhenItsPageIsFull) {
    (void)Vn_Term();
    constexpr std::uint32_t kBlockFrames = 64;
    harkentest::EngineSession session(
        harkentest::MakeNullConfig(8, kBlockFrames, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    std::vector<float> first(kBlockFrames, 0.25f);
    std::vector<float> second(kBlockFrames, -0.25f);
    const auto firstPcm = harkentest::MonoDesc(first, 48000);
    const auto secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &secondPcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
    image.MakeImmediateCompositeTrackPlayAction(
        (2 * kBlockFrames * INT64_C(1000000000) + 47999) / 48000);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
        harken::InstallContainerWorldV1(*engine, image.world).status);
    const auto pageFrame = ImmediateActionStartFrame(*engine);
    const auto capacity = engine->timelinePool.MaxEventsPerQuantum();
    const auto perTransaction = engine->timelinePool.MaxTransactionEvents();
    for (std::uint32_t filled = 0, transaction = 1; filled < capacity; ++transaction) {
        const auto count = std::min(perTransaction, capacity - filled);
        ASSERT_EQ(harken::ReserveStatus::Committed,
            ReserveActionPreparationTransaction(
                *engine, 2000u + transaction, pageFrame, count).status);
        filled += count;
    }
    ASSERT_EQ(harken::ReserveRefusal::PageEventCapacity,
        engine->timelinePool.PreflightSingleEvent(
            pageFrame, engine->timelinePool.PublishCutoffFrame()));
    VnPostActionDesc post = ValidPostDesc();
    post.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&post, &firing));
    const auto row = std::find_if(engine->playableServices.begin(),
        engine->playableServices.end(), [firing](const auto& candidate) {
            return candidate.InvocationValid() &&
                candidate.Invocation().actionFiring == firing;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    ASSERT_TRUE(row->pendingImmediateEntry);
    ASSERT_EQ(2u, row->scheduleLeafCount);
    engine->nullBackend.Pump(1);
    ASSERT_EQ(VN_OK, Vn_Update());
    const auto secondStart =
        engine->ReadPlayableMember(row->scheduleStorageBase + 1u).startFrame /
        kBlockFrames;
    bool heardFirst = false;
    bool heardSecondAtExpectedBlock = false;
    for (std::uint32_t block = 0; block < 8; ++block) {
        engine->nullBackend.Pump(1);
        const float* output = engine->nullBackend.LastBlock();
        heardFirst = heardFirst || std::any_of(output, output + kBlockFrames,
            [](float sample) { return sample > 0.01f; });
        if (engine->mixer.BlocksRendered() == secondStart + 1u)
            heardSecondAtExpectedBlock = std::any_of(
                output, output + kBlockFrames,
                [](float sample) { return sample < -0.01f; });
    }
    EXPECT_TRUE(heardFirst);
    EXPECT_TRUE(heardSecondAtExpectedBlock);
}

TEST(ActionFiringApi, ImmediateLanePlayPostsPastStalledPageWindow) {
    (void)Vn_Term();
    constexpr std::uint32_t kBlockFrames = 64;
    harkentest::EngineSession session(
        harkentest::MakeNullConfig(4, kBlockFrames, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    std::vector<float> samples(512, 0.25f);
    const auto pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision);
    image.MakeImmediateSoundPlayAction();
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
        harken::InstallContainerWorldV1(*engine, image.world).status);
    engine->nullBackend.Pump(engine->timelinePool.PageCount() +
        engine->timelinePool.PublishLeadQuanta() + 4u);
    ASSERT_GE(ImmediateActionStartFrame(*engine),
              engine->timelinePool.WindowEndFrame());
    ASSERT_LT(engine->timelinePool.ConsumerFrontier().load(std::memory_order_acquire),
              engine->mixer.BlocksRendered());
    VnPostActionDesc post = ValidPostDesc();
    post.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&post, &firing));
    engine->nullBackend.Pump(1);
    ASSERT_EQ(VN_OK, Vn_Update());
    bool heard = false;
    for (std::uint32_t block = 0; block < 16; ++block) {
        engine->nullBackend.Pump(1);
        const float* output = engine->nullBackend.LastBlock();
        heard = heard || std::any_of(output, output + kBlockFrames,
            [](float sample) { return sample > 0.01f; });
    }
    EXPECT_TRUE(heard);
}

TEST(ActionFiringApi, ImmediateTrackAcrossPagesSurvivesLateNormalUpdate) {
    (void)Vn_Term();
    constexpr std::uint32_t kBlockFrames = 64;
    harkentest::EngineSession session(
        harkentest::MakeNullConfig(8, kBlockFrames, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    std::vector<float> first(256, 0.25f);
    std::vector<float> second(256, 0.125f);
    const auto firstPcm = harkentest::MonoDesc(first, 48000);
    const auto secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(
                         CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(
                         CanonicalActionWorld::kSecondSound, &secondPcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound)
            .contentRevision);
    image.MakeImmediateCompositeTrackPlayAction(
        2 * kBlockFrames * INT64_C(1000000000) / 48000);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);
    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [firing](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.InvocationValid() &&
                   candidate.Invocation().actionFiring == firing;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    ASSERT_EQ(2u, row->scheduleLeafCount);
    ASSERT_TRUE(row->pendingImmediateEntry);
    const auto oldStart = row->startFrame / kBlockFrames;
    const auto rendered = engine->mixer.BlocksRendered();
    ASSERT_LE(rendered, oldStart);
    ASSERT_LE(oldStart - rendered + 1u, 64u);
    engine->nullBackend.Pump(static_cast<std::uint32_t>(
        oldStart - rendered + 1u));
    ASSERT_EQ(VN_OK, Vn_Update());
    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    bool audible = false;
    for (std::uint32_t block = 0; block < 64; ++block) {
        engine->nullBackend.Pump(1);
        const float* output = engine->nullBackend.LastBlock();
        audible = audible || std::any_of(
            output, output + kBlockFrames,
            [](float sample) { return std::abs(sample) > 0.001f; });
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
        if (info.state == VN_ACTION_FIRING_TERMINAL_RETAINED) break;
    }
    EXPECT_TRUE(audible);
    EXPECT_EQ(VN_ACTION_OUTCOME_SUCCEEDED, info.outcome);
    EXPECT_EQ(VN_ACTION_TERMINAL_NATURAL, info.terminalReason);
}

TEST(ActionFiringApi,
     ImmediateTrackFuturePageStartsWithoutAnotherLogicUpdate) {
    (void)Vn_Term();
    constexpr std::uint32_t kBlockFrames = 64;
    harkentest::EngineSession session(
        harkentest::MakeNullConfig(8, kBlockFrames, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
#if defined(_DEBUG) && defined(_MSC_VER)
    ASSERT_TRUE(harken::memguard::IsArmed());
#endif
    auto* engine = session.Engine();
    std::vector<float> first(kBlockFrames, 0.25f);
    std::vector<float> second(kBlockFrames, -0.25f);
    const auto firstPcm = harkentest::MonoDesc(first, 48000);
    const auto secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(
                         CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(
                         CanonicalActionWorld::kSecondSound, &secondPcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound)
            .contentRevision);
    image.MakeImmediateCompositeTrackPlayAction(
        (2 * kBlockFrames * INT64_C(1000000000) + 47999) / 48000);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);
    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    ASSERT_NE(0u, firing);
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [firing](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.InvocationValid() &&
                   candidate.Invocation().actionFiring == firing;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    ASSERT_EQ(2u, row->scheduleLeafCount);
    const harken::TimelineArmToken firstArm = row->arm;
    harken::TimelineArmObservation beforeAudio{};
    ASSERT_TRUE(engine->timelineArms.Observe(firstArm, &beforeAudio));
    ASSERT_EQ(0u, beforeAudio.armedCompletionSequence);
    const auto oldStart = row->startFrame / kBlockFrames;
    const auto postedBlock = engine->mixer.BlocksRendered();
    ASSERT_LE(postedBlock, oldStart);
    for (auto block = postedBlock; block <= oldStart; ++block) {
        const auto allocationHitsBefore = harken::memguard::HitCount();
        engine->nullBackend.Pump(1);
        const auto allocationHitsAfter = harken::memguard::HitCount();
        EXPECT_EQ(allocationHitsBefore, allocationHitsAfter);
        const float* output = engine->nullBackend.LastBlock();
        EXPECT_TRUE(std::all_of(output, output + kBlockFrames,
            [](float sample) { return std::abs(sample) < 0.001f; }));
    }
    const auto publishUpdateBlock = engine->mixer.BlocksRendered();
    harken::TimelineArmObservation afterAudio{};
    ASSERT_TRUE(engine->timelineArms.Observe(firstArm, &afterAudio));
    ASSERT_EQ(harken::ArmState::Armed, afterAudio.state);
    ASSERT_GT(afterAudio.armedCompletionSequence, 0u);
    ASSERT_LE(afterAudio.armedCompletionSequence, oldStart);
    ASSERT_EQ(0u, afterAudio.startedBlockSequence);
    const auto expectedFirstStart =
        ImmediateActionStartFrame(*engine) / kBlockFrames;
    ASSERT_EQ(VN_OK, Vn_Update());
    harken::TimelineArmObservation afterPublish{};
    ASSERT_TRUE(engine->timelineArms.Observe(firstArm, &afterPublish));
    ASSERT_EQ(harken::ArmState::Published, afterPublish.state);
    const auto base = row->scheduleStorageBase;
    const auto firstStart =
        engine->ReadPlayableMember(base).startFrame / kBlockFrames;
    const auto secondStart =
        engine->ReadPlayableMember(base + 1u).startFrame / kBlockFrames;
    EXPECT_EQ(expectedFirstStart, firstStart);
    ASSERT_GT(firstStart, publishUpdateBlock);
    ASSERT_EQ(2u, secondStart - firstStart);
    ::testing::Test::RecordProperty("post_block", postedBlock);
    ::testing::Test::RecordProperty("arm_ack_sequence",
        afterAudio.armedCompletionSequence);
    ::testing::Test::RecordProperty("publish_update_block", publishUpdateBlock);
    ::testing::Test::RecordProperty("first_start_block", firstStart);
    ::testing::Test::RecordProperty("second_start_block", secondStart);
    ASSERT_LT(engine->mixer.BlocksRendered(), firstStart);
    SCOPED_TRACE(::testing::Message()
                 << "firstStart=" << firstStart
                 << " secondStart=" << secondStart
                 << " cutoff=" << engine->timelinePool.PublishCutoffFrame()
                 << " futureStamp="
                 << engine->timelinePool.PageStamp(secondStart)
                 << " deadlineMissesBefore="
                 << engine->timelineExecutor.Stats().deadlineMissQuanta);
    bool heardFirstAtExpectedBlock = false;
    bool heardSecondAtExpectedBlock = false;
    for (std::uint32_t block = 0; block < 8; ++block) {
        const auto renderedBlock = engine->mixer.BlocksRendered();
        const auto allocationHitsBefore = harken::memguard::HitCount();
        engine->nullBackend.Pump(1);
        const auto allocationHitsAfter = harken::memguard::HitCount();
        EXPECT_EQ(allocationHitsBefore, allocationHitsAfter);
        const float* output = engine->nullBackend.LastBlock();
        const bool positive = std::any_of(output, output + kBlockFrames,
            [](float sample) { return sample > 0.01f; });
        const bool negative = std::any_of(output, output + kBlockFrames,
            [](float sample) { return sample < -0.01f; });
        if (renderedBlock == firstStart) {
            heardFirstAtExpectedBlock = positive;
            EXPECT_FALSE(negative);
        } else if (renderedBlock == secondStart) {
            heardSecondAtExpectedBlock = std::any_of(
                output, output + kBlockFrames,
                [](float sample) { return sample < -0.01f; });
            EXPECT_FALSE(positive);
        } else {
            EXPECT_FALSE(positive);
            EXPECT_FALSE(negative);
        }
    }
    EXPECT_TRUE(heardFirstAtExpectedBlock);
    EXPECT_TRUE(heardSecondAtExpectedBlock);
}

TEST(ActionFiringApi,
     ImmediateTrackPlayDefersFutureLeafAndKeepsIndependentClipDeadlines) {
    (void)Vn_Term();
    VnConfig config = harkentest::MakeNullConfig(8, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> first(4096, 0.25f);
    std::vector<float> second(4096, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &secondPcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound)
            .contentRevision);
    image.MakeImmediateCompositeTrackPlayAction();
    const std::uint64_t futureOffsetFrames =
        engine->timelinePool.WindowEndFrame() + config.blockFrames;
    const std::int64_t futureOffsetNanoseconds =
        static_cast<std::int64_t>(
            (futureOffsetFrames * UINT64_C(1000000000) + 47999u) /
            48000u);
    image.trackPlacements[0].authoredDuration = INT64_C(4000000);
    image.trackPlacements[1].authoredStart = futureOffsetNanoseconds;
    image.trackPlacements[1].authoredDuration = INT64_C(8000000);
    image.track.scheduleSemanticFingerprint =
        harken::ComputeTrackScheduleFingerprintV1(image.track);
    image.queueChildren[0].timingHint =
        harken::MakeScheduleReferenceTimingHint(
            harken::PlayableKindV1::Track,
            image.track.rootDefinition.stableId,
            image.track.scheduleSemanticFingerprint);
    image.world.identity.runtimeSemanticFingerprint =
        harken::ComputeCurrentWorldFingerprintV4(image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    ASSERT_NE(0u, firing);
    ASSERT_EQ(1u, engine->timelineDeferred.Count());

    VnActionStepResult play{};
    play.structSize = sizeof(play);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == play.producedPlayableInstance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    ASSERT_EQ(2u, row->scheduleLeafCount);
    const std::size_t base = row->scheduleStorageBase;
    const std::uint64_t firstStart =
        engine->ReadPlayableMember(base).startFrame;
    const std::uint64_t secondStart =
        engine->ReadPlayableMember(base + 1u).startFrame;
    EXPECT_EQ(futureOffsetFrames, secondStart - firstStart);
    const auto* firstVoice = engine->voices.Resolve(
        engine->ReadPlayableMember(base).render);
    const auto* secondVoice = engine->voices.Resolve(
        engine->ReadPlayableMember(base + 1u).render);
    ASSERT_NE(nullptr, firstVoice);
    ASSERT_NE(nullptr, secondVoice);
    EXPECT_EQ(firstStart + 192u, firstVoice->authoredSourceDeadlineFrame);
    EXPECT_EQ(secondStart + 384u, secondVoice->authoredSourceDeadlineFrame);

    VnActionSeekDescV1 seek{};
    seek.structSize = sizeof(seek);
    seek.firing = firing;
    seek.positionMs = 64.0 * 1000.0 / 48000.0;
    seek.mode = VN_ACTION_SEEK_ABSOLUTE;
    VnActionSeekTicket seekTicket = 0;
    EXPECT_EQ(VN_CAPABILITY_UNAVAILABLE,
              Vn_SeekActionFiring(&seek, &seekTicket));
    EXPECT_EQ(0u, seekTicket);
    firstVoice = engine->voices.Resolve(
        engine->ReadPlayableMember(base).render);
    secondVoice = engine->voices.Resolve(
        engine->ReadPlayableMember(base + 1u).render);
    ASSERT_NE(nullptr, firstVoice);
    ASSERT_NE(nullptr, secondVoice);
    EXPECT_EQ(firstStart + 192u, firstVoice->authoredSourceDeadlineFrame);
    EXPECT_EQ(secondStart + 384u, secondVoice->authoredSourceDeadlineFrame);

    FrontierTrace trace;
    const std::uint64_t blockBudget =
        secondStart / config.blockFrames + 16u;
    const auto executorBefore = engine->timelineExecutor.Stats();
    for (std::uint64_t block = 0; block < blockBudget; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        trace.Capture(*engine);
        if (trace.heard.size() == 2u && engine->voices.ActiveCount() == 0) {
            break;
        }
    }
    ASSERT_EQ(VN_OK, Vn_Update());
    const auto executorAfter = engine->timelineExecutor.Stats();
    ASSERT_EQ(2u, trace.heard.size());
    EXPECT_EQ(CanonicalActionWorld::kFirstSound, trace.heard[0].subject);
    EXPECT_EQ(CanonicalActionWorld::kSecondSound, trace.heard[1].subject);
    EXPECT_EQ(firstStart / config.blockFrames + 1u, trace.heard[0].start);
    EXPECT_EQ(secondStart / config.blockFrames + 1u, trace.heard[1].start);
    EXPECT_EQ(0u, engine->timelineDeferred.Count());
    EXPECT_EQ(executorBefore.staleSkippedTransactions,
              executorAfter.staleSkippedTransactions);
    EXPECT_EQ(executorBefore.armPendingSkipped,
              executorAfter.armPendingSkipped);
    EXPECT_EQ(executorBefore.armFailedTransactions,
              executorAfter.armFailedTransactions);
    EXPECT_EQ(executorBefore.protocolViolation,
              executorAfter.protocolViolation);
    EXPECT_EQ(executorBefore.lateConsumedEvents,
              executorAfter.lateConsumedEvents);
    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
    unsigned retirementAudioBlocks = 0;
    for (; retirementAudioBlocks < 16 &&
           info.state != VN_ACTION_FIRING_TERMINAL_RETAINED;
         ++retirementAudioBlocks) {
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
    }
    testing::Test::RecordProperty("retirement_audio_blocks", retirementAudioBlocks);
    EXPECT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
    EXPECT_EQ(VN_ACTION_OUTCOME_SUCCEEDED, info.outcome);
    EXPECT_EQ(VN_ACTION_TERMINAL_NATURAL, info.terminalReason);
    EXPECT_EQ(0u, info.livePlayableCount);
    unsigned remainingSources = 0;
    for (std::uint32_t slot = 0; slot < engine->sourceTerminals.Capacity(); ++slot)
        remainingSources += engine->sourceTerminals.At(slot)->occupied;
    EXPECT_EQ(0u, remainingSources);
    EXPECT_EQ(0u, engine->playableInstances.LiveCount());
    EXPECT_FALSE(engine->playableInstances.Classify(play.producedPlayableInstance).live);
    EXPECT_EQ(0u, engine->voices.ActiveCount());
    EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
}

TEST(ActionFiringApi,
     ImmediateTrackFutureLeafRefusesAtomicallyWhenDeferredPoolIsFull) {
    (void)Vn_Term();
    VnConfig config = harkentest::MakeNullConfig(8, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> samples(4096, 0.25f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &pcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound)
            .contentRevision);
    image.MakeImmediateCompositeTrackPlayAction();
    const std::uint64_t futureOffsetFrames =
        engine->timelinePool.WindowEndFrame() + config.blockFrames;
    image.trackPlacements[1].authoredStart =
        static_cast<std::int64_t>(
            (futureOffsetFrames * UINT64_C(1000000000) + 47999u) /
            48000u);
    image.trackPlacements[1].authoredDuration = INT64_C(4000000);
    image.track.scheduleSemanticFingerprint =
        harken::ComputeTrackScheduleFingerprintV1(image.track);
    image.queueChildren[0].timingHint =
        harken::MakeScheduleReferenceTimingHint(
            harken::PlayableKindV1::Track,
            image.track.rootDefinition.stableId,
            image.track.scheduleSemanticFingerprint);
    image.world.identity.runtimeSemanticFingerprint =
        harken::ComputeCurrentWorldFingerprintV4(image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    std::vector<harken::DeferredIntentToken> fillers;
    fillers.reserve(engine->timelineDeferred.Capacity());
    for (std::uint32_t index = 0;
         index < engine->timelineDeferred.Capacity(); ++index) {
        harken::DeferredIntent intent{};
        intent.ownerDomain = harken::DeferredIntentOwnerDomain::Action;
        intent.ownerHandle = 0x4000u + index;
        intent.ownerEpoch = 1;
        intent.dueFrame = UINT64_MAX - index;
        const auto added = engine->timelineDeferred.AddClaimable(intent);
        ASSERT_EQ(harken::DeferredIntentRefusal::None, added.status);
        fillers.push_back(added.token);
    }
    const auto ownersBefore = CaptureActionReclaimableOwners(*engine);
    const std::uint64_t commandHeadBefore = engine->commands.PublishedHead();
    const std::uint64_t sequenceBefore = engine->logicCommits.IssuedCount();

    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle firing = 99;
    EXPECT_EQ(VN_BACKPRESSURE, Vn_PostAction(&desc, &firing));
    EXPECT_EQ(0u, firing);
    EXPECT_EQ(ownersBefore, CaptureActionReclaimableOwners(*engine));
    EXPECT_EQ(commandHeadBefore, engine->commands.PublishedHead());
    EXPECT_EQ(sequenceBefore, engine->logicCommits.IssuedCount());
    EXPECT_EQ(0u, engine->timelineDeferred.PreparedCount());
    EXPECT_EQ(engine->timelineDeferred.Capacity(),
              engine->timelineDeferred.Count());

    for (const auto token : fillers) {
        ASSERT_TRUE(engine->timelineDeferred.Cancel(token));
    }
}

TEST(ActionFiringApi,
     ImmediateTrackRetirementRetryRetainsActionOwnerUntilTreeRetires) {
    (void)Vn_Term();
    VnConfig config = harkentest::MakeNullConfig(16, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> first(64, 0.25f);
    std::vector<float> second(64, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kSecondSound,
                             &secondPcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound)
            .contentRevision);
    image.MakeImmediateCompositeTrackPlayAction();
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    VnActionStepResult play{};
    play.structSize = sizeof(play);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
    ASSERT_NE(0u, play.producedPlayableInstance);

    const auto foreignParent = engine->playableInstances.Acquire(
        harken::PlayableKind::Track, 0);
    const auto blockedChild = engine->playableInstances.Acquire(
        harken::PlayableKind::Sound, play.producedPlayableInstance);
    ASSERT_NE(0u, foreignParent);
    ASSERT_NE(0u, blockedChild);
    ASSERT_TRUE(harken::detail::PlayableInstanceTableTestAccess::SetParent(
        engine->playableInstances, blockedChild, foreignParent));

    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    bool retryBlocked = false;
    for (std::uint32_t block = 0; block < 32 && !retryBlocked; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
        const auto root = engine->playableInstances.Classify(
            play.producedPlayableInstance);
        const auto child = engine->playableInstances.Classify(blockedChild);
        retryBlocked = engine->voices.ActiveCount() == 0 && root.live &&
            child.live &&
            child.lifecycle == harken::PlayableLifecycle::AudibleRetiring;
    }

    ASSERT_TRUE(retryBlocked);
    EXPECT_EQ(VN_ACTION_FIRING_ACTIVE, info.state);
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [firing](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.phase != harken::EnginePlayableStartPhase::Free &&
                   candidate.Invocation().actionFiring == firing;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    EXPECT_EQ(firing, row->Invocation().actionFiring);
    EXPECT_TRUE(engine->playableInstances
                    .Classify(play.producedPlayableInstance)
                    .live);

    ASSERT_TRUE(harken::detail::PlayableInstanceTableTestAccess::SetParent(
        engine->playableInstances, blockedChild,
        play.producedPlayableInstance));
    for (std::uint32_t retry = 0; retry < 8; ++retry) {
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
        if (info.state == VN_ACTION_FIRING_TERMINAL_RETAINED) break;
    }

    ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
    EXPECT_EQ(VN_ACTION_OUTCOME_SUCCEEDED, info.outcome);
    EXPECT_EQ(VN_ACTION_TERMINAL_NATURAL, info.terminalReason);
    EXPECT_FALSE(engine->playableInstances
                     .Classify(play.producedPlayableInstance)
                     .live);
    EXPECT_FALSE(engine->playableInstances.Classify(blockedChild).live);
    EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    EXPECT_TRUE(harken::PlayableTreeExecutor::RetirePlayableTreeBottomUp(
        engine->playableInstances, engine->containerPlayback, foreignParent,
        harken::PlayableTerminalKind::NaturalCompletion));
}

TEST(ActionFiringApi, ImmediateSegmentPlayCompletesAfterEveryLeafRetires) {
    (void)Vn_Term();
    VnConfig config = harkentest::MakeNullConfig(8, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> first(64, 0.25f);
    std::vector<float> second(64, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kSecondSound,
                             &secondPcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound)
            .contentRevision);
    image.MakeImmediateCompositeSegmentPlayAction();
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle firing = 0;
    const auto capture = harkentest::monitor::OpenIdentityEvents();
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    const auto preparedRecords = harkentest::monitor::ReadIdentityEvents(capture);
    for (const auto& record : preparedRecords)
        EXPECT_NE(VN_MONITOR_FACT_SELECTION_COMMITTED, record.fact.factKind);

    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
    EXPECT_EQ(VN_ACTION_FIRING_ACTIVE, info.state);
    EXPECT_EQ(1u, info.livePlayableCount);
    VnActionStepResult play{};
    play.structSize = sizeof(play);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
    EXPECT_EQ(VN_ACTION_STEP_ACTIVE, play.state);
    EXPECT_EQ(VN_ACTION_TARGET_SEGMENT, play.targetKind);
    EXPECT_NE(0u, play.producedPlayableInstance);
    unsigned rootCandidates = 0;
    for (const auto& record : preparedRecords) {
        if (record.fact.factKind != VN_MONITOR_FACT_PLAYABLE_PREPARED) continue;
        EXPECT_EQ(firing, record.fact.selection.action);
        EXPECT_EQ(0u, record.fact.selection.executionOrdinal);
        EXPECT_NE(0u, record.fact.playbackRequest.sequence);
        if (record.header.instanceHandle == play.producedPlayableInstance) ++rootCandidates;
    }
    EXPECT_EQ(1u, rootCandidates);

    for (std::uint32_t block = 0; block < 32; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
        if (info.state == VN_ACTION_FIRING_TERMINAL_RETAINED) {
            break;
        }
    }

    ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
    EXPECT_EQ(VN_ACTION_OUTCOME_SUCCEEDED, info.outcome);
    EXPECT_EQ(VN_ACTION_TERMINAL_NATURAL, info.terminalReason);
    EXPECT_EQ(0u, info.livePlayableCount);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
    EXPECT_EQ(VN_ACTION_STEP_SUCCEEDED, play.state);
    EXPECT_FALSE(engine->playableInstances
                     .Classify(play.producedPlayableInstance)
                     .live);
    EXPECT_EQ(0u, engine->voices.ActiveCount());
    EXPECT_EQ(0u, engine->playableInstances.LiveCount());
    auto records = preparedRecords;
    harkentest::monitor::CollectIdentityEvents(capture, records);
    ExpectCompositeSoundLifecycle(records, play.producedPlayableInstance, VN_MONITOR_TERMINAL_NATURAL_COMPLETION);
    std::vector<harkentest::monitor::IdentityRecord> selected;
    for (const auto& record : records)
        if (record.fact.factKind == VN_MONITOR_FACT_SELECTION_COMMITTED) selected.push_back(record);
    ASSERT_EQ(2u, selected.size());
    EXPECT_NE(selected[0].fact.logicalVoice, selected[1].fact.logicalVoice);
    EXPECT_EQ(CanonicalActionWorld::kFirstSound, selected[0].header.stableId);
    EXPECT_EQ(CanonicalActionWorld::kSecondSound, selected[1].header.stableId);
    for (const auto& record : selected) {
        EXPECT_EQ(play.producedPlayableInstance, record.fact.root);
        EXPECT_EQ(firing, record.fact.selection.action);
        EXPECT_EQ(record.fact.playbackRequest.sequence, record.fact.selectionRequest.sequence);
        EXPECT_NE(0u, record.fact.selectionRequest.sequence);
    }
    EXPECT_EQ(VN_OK, Vn_MonitorCloseSession(capture));
    EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
}

TEST(ActionFiringApi, ImmediateCompositePlayReanchorsAfterStalePublicationFrame) {
    (void)Vn_Term();
    VnConfig config = harkentest::MakeNullConfig(8, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> first(64, 0.25f);
    std::vector<float> second(64, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &secondPcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound)
            .contentRevision);
    image.MakeImmediateCompositeTrackPlayAction();
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    VnActionStepResult play{};
    play.structSize = sizeof(play);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
    ASSERT_NE(0u, play.producedPlayableInstance);

    // Let both leaf arms receive their audio-thread acknowledgement, then
    // move the publication frontier beyond their original scheduled frame.
    ASSERT_EQ(VN_OK, Vn_Update());
    engine->nullBackend.Pump(1);
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == play.producedPlayableInstance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    ASSERT_GE(row->scheduleLeafCount, 2u);
    const std::size_t base = row->scheduleStorageBase;
    std::uint64_t latestStart = row->startFrame;
    for (std::uint32_t index = 0; index < row->scheduleLeafCount; ++index) {
        latestStart = std::max(
            latestStart, engine->ReadPlayableMember(base + index).startFrame);
    }
    engine->timelinePool.Publish(
        latestStart + 1u, &engine->playableInstances,
        &engine->timelineOccurrences, &engine->timelineArms);
    ASSERT_GT(engine->timelinePool.PublishCutoffFrame(), latestStart);

    ASSERT_EQ(VN_OK, Vn_Update());
    for (std::uint32_t block = 0; block < 8; ++block) {
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
    }
    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
    EXPECT_EQ(VN_ACTION_TERMINAL_NATURAL, info.terminalReason);
    EXPECT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
    EXPECT_EQ(VN_ACTION_OUTCOME_SUCCEEDED, info.outcome);
    EXPECT_EQ(0u, info.livePlayableCount);
    EXPECT_EQ(0u, engine->voices.ActiveCount());
    EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
}

TEST(ActionFiringApi, DirectCompositePlayRejectsStaleMultiLeafArmPublication) {
    (void)Vn_Term();
    VnConfig config = harkentest::MakeNullConfig(8, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> first(64, 0.25f);
    std::vector<float> second(64, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &secondPcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound)
            .contentRevision);
    image.MakeImmediateDirectContainerCompositePlayAction(
        harken::PlayableKindV1::Track);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    VnEmitterHandle emitter = 0;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&emitter));
    const harken::PlayableStartResult started =
        harken::StartCurrentPlayableByIdentity(
            harken::PlayableKindV1::Container,
            image.containers[0].containerStableId, emitter);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    ASSERT_NE(0u, started.instance);

    ASSERT_EQ(VN_OK, Vn_Update());
    engine->nullBackend.Pump(1);
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == started.instance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    ASSERT_GE(row->scheduleLeafCount, 2u);
    const std::size_t base = row->scheduleStorageBase;
    std::uint64_t latestStart = row->startFrame;
    for (std::uint32_t index = 0; index < row->scheduleLeafCount; ++index) {
        latestStart = std::max(
            latestStart, engine->ReadPlayableMember(base + index).startFrame);
    }
    engine->timelinePool.Publish(
        latestStart + 1u, &engine->playableInstances,
        &engine->timelineOccurrences, &engine->timelineArms);
    ASSERT_GT(engine->timelinePool.PublishCutoffFrame(), latestStart);

    for (std::uint32_t block = 0; block < 32; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        if (!engine->playableInstances.Classify(started.instance).live) {
            break;
        }
    }
    EXPECT_FALSE(engine->playableInstances.Classify(started.instance).live);
    EXPECT_EQ(0u, engine->containerPlayback.LiveCount());
    EXPECT_EQ(0u, engine->voices.ActiveCount());
    ASSERT_EQ(VN_OK, Vn_DestroyEmitter(emitter));
}

