TEST(ActionFiringApi, MultiLeafLateNormalUpdateKeepsOriginalSourcesAndAuthoredOffsets) {
    for (const bool track : {false, true}) {
        for (const std::int64_t secondLeafStartNanoseconds :
             {INT64_C(0), INT64_C(128) * INT64_C(1000000000) / 48000}) {
            (void)Vn_Term();
            constexpr std::uint32_t kBlockFrames = 64;
            harkentest::EngineSession session(harkentest::MakeNullConfig(8, kBlockFrames, 48000));
            ASSERT_EQ(VN_OK, session.InitResult());
            auto* engine = session.Engine();
            std::vector<float> first(1024, 0.25f);
            std::vector<float> second(1024, 0.125f);
            const auto firstPcm = harkentest::MonoDesc(first, 48000);
            const auto secondPcm = harkentest::MonoDesc(second, 48000);
            ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &firstPcm));
            ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &secondPcm));
            CanonicalActionWorld image(
                engine->registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
                engine->registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
            if (track)
                image.MakeImmediateCompositeTrackPlayAction(secondLeafStartNanoseconds);
            else
                image.MakeImmediateCompositeContainerPlayAction(secondLeafStartNanoseconds);
            ASSERT_EQ(harken::WorldInstallStatus::Ok,
                      harken::InstallContainerWorldV1(*engine, image.world).status);
            VnPostActionDesc desc = ValidPostDesc();
            desc.actionId = image.actions[9].actionStableId;
            VnActionFiringHandle firing = 0;
            ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
            auto row = std::find_if(engine->playableServices.begin(),
                                    engine->playableServices.end(), [firing](const auto& member) {
                                        return member.InvocationValid() &&
                                               member.Invocation().actionFiring == firing;
                                    });
            ASSERT_NE(engine->playableServices.end(), row);
            ASSERT_EQ(2u, row->scheduleLeafCount);
            const auto base = row->scheduleStorageBase;
            const auto firstArm = engine->ReadPlayableMember(base).arm;
            const auto secondArm = engine->ReadPlayableMember(base + 1u).arm;
            const std::array<VnVoiceHandle, 2> originalRenders{
                engine->ReadPlayableMember(base).render,
                engine->ReadPlayableMember(base + 1u).render};
            // Audio advances before normal service; Source identity must survive.
            engine->nullBackend.Pump(3);
            ASSERT_EQ(VN_OK, Vn_Update());
            VnActionFiringInfo info{};
            info.structSize = sizeof(info);
            bool audible = false;
            std::array<bool, 2> originalStarted{};
            std::array<std::uint64_t, 2> actualOnsets{};
            const std::array<harken::TimelineArmToken, 2> originalArms{firstArm, secondArm};
            for (std::uint32_t block = 0; block < 64; ++block) {
                ASSERT_EQ(VN_OK, Vn_Update());
                engine->nullBackend.Pump(1);
                for (std::size_t member = 0; member < originalArms.size(); ++member) {
                    harken::TimelineArmObservation actual{};
                    if (!originalStarted[member] &&
                        engine->timelineArms.Observe(originalArms[member], &actual) &&
                        actual.startedBlockSequence != 0) {
                        harken::EngineTimelineVoiceInstallIdentity installation{};
                        ASSERT_TRUE(engine->CaptureTimelineVoiceInstallIdentity(
                            originalRenders[member], &installation));
                        ASSERT_TRUE(harken::OriginalSourceSubmissionRegistry::SameToken(
                            originalArms[member], installation.startArm));
                        originalStarted[member] = true;
                        actualOnsets[member] = installation.onsetFrame;
                    }
                }
                const float* output = engine->nullBackend.LastBlock();
                audible = audible || std::any_of(output, output + kBlockFrames, [](float sample) {
                              return std::abs(sample) > 0.001f;
                          });
                ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
                if (info.state == VN_ACTION_FIRING_TERMINAL_RETAINED &&
                    engine->playableInstances.LiveCount() == 0 &&
                    engine->playablePartitions.OccupiedCount() == 0)
                    break;
            }
            EXPECT_TRUE(audible);
            EXPECT_NE(VN_ACTION_TERMINAL_DEADLINE, info.terminalReason);
            EXPECT_TRUE(originalStarted[0]);
            EXPECT_TRUE(originalStarted[1]);
            ASSERT_GE(actualOnsets[1], actualOnsets[0]);
            const auto authoredOffset = static_cast<std::uint64_t>(secondLeafStartNanoseconds) *
                UINT64_C(48000) / UINT64_C(1000000000);
            EXPECT_EQ(authoredOffset, actualOnsets[1] - actualOnsets[0]);
            EXPECT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
            EXPECT_EQ(VN_ACTION_OUTCOME_SUCCEEDED, info.outcome);
            EXPECT_EQ(0u, engine->playableInstances.LiveCount());
            EXPECT_EQ(0u, engine->playablePartitions.OccupiedCount());
            EXPECT_FALSE(engine->runtimeRecreateRequired);
            ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
            EXPECT_EQ(0u, engine->voices.ActiveCount());
        }
    }
}

TEST(ActionFiringApi, ImmediateNestedSequenceContainerTrackChildBuildsCompleteTree) {
    (void)Vn_Term();
    harkentest::EngineSession session(harkentest::MakeNullConfig(8, 64, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> samples(64, 0.25f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &pcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
    image.MakeImmediateNestedCompositeContainerPlayAction();
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    VnActionStepResult step{};
    step.structSize = sizeof(step);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &step));
    ASSERT_EQ(VN_ACTION_STEP_ACTIVE, step.state);
    ASSERT_NE(0u, step.producedPlayableInstance);

    const auto outer = engine->playableInstances.Classify(step.producedPlayableInstance);
    ASSERT_TRUE(outer.live);
    ASSERT_EQ(harken::PlayableKind::Container, outer.kind);
    ASSERT_NE(0u, outer.firstChild);
    const auto inner = engine->playableInstances.Classify(outer.firstChild);
    ASSERT_TRUE(inner.live);
    ASSERT_EQ(harken::PlayableKind::Container, inner.kind);
    EXPECT_EQ(step.producedPlayableInstance, inner.parent);
    ASSERT_NE(0u, inner.firstChild);
    const auto track = engine->playableInstances.Classify(inner.firstChild);
    ASSERT_TRUE(track.live);
    ASSERT_EQ(harken::PlayableKind::Track, track.kind);
    EXPECT_EQ(outer.firstChild, track.parent);
    ASSERT_NE(0u, track.firstChild);
    EXPECT_EQ(harken::PlayableKind::Sound,
              engine->playableInstances.Classify(track.firstChild).kind);
    EXPECT_EQ(2u, engine->containerPlayback.LiveCount());

    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    for (std::uint32_t block = 0; block < 96; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
        if (info.state == VN_ACTION_FIRING_TERMINAL_RETAINED) break;
    }
    ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
    EXPECT_EQ(VN_ACTION_OUTCOME_SUCCEEDED, info.outcome);
    EXPECT_EQ(0u, info.livePlayableCount);
    EXPECT_EQ(0u, engine->containerPlayback.LiveCount());
    EXPECT_FALSE(engine->playableInstances.Classify(outer.firstChild).live);
    EXPECT_FALSE(engine->playableInstances.Classify(inner.firstChild).live);
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
}

TEST(ActionFiringApi, InitialQueueTimingCandidateRetainsCompositeOffsetsAndPrivateBank) {
    (void)Vn_Term();
    harkentest::EngineSession session(harkentest::MakeNullConfig(8, 64, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> samples(128, 0.25f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &pcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
    image.MakeImmediateSequenceQueuePlayAction();
    image.MakeFirstQueueChildCompositeTrack();
    image.trackPlacements[1].authoredStart = 2000000;
    image.track.scheduleSemanticFingerprint =
        harken::ComputeTrackScheduleFingerprintV1(image.track);
    image.queueChildren[0].timingHint =
        harken::MakeScheduleReferenceTimingHint(
            harken::PlayableKindV1::Track,
            image.track.rootDefinition.stableId,
            image.track.scheduleSemanticFingerprint);
    image.world.identity.runtimeSemanticFingerprint =
        harken::ComputeCurrentWorldFingerprintV4(image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);
    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&desc.emitter));
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    const auto* attempt = std::find_if(
        engine->immediateEntryAttempts.data(),
        engine->immediateEntryAttempts.data() +
            engine->immediateEntryAttempts.size(),
        [firing](const auto& candidate) {
            return candidate.active && candidate.root == firing;
        });
    ASSERT_NE(engine->immediateEntryAttempts.data() +
                  engine->immediateEntryAttempts.size(), attempt);
    ASSERT_TRUE(attempt->initialService.Valid());
    ASSERT_LE(attempt->initialEntryFrame, UINT64_MAX - 64u);
    std::size_t memberCount = 0;
    std::size_t programCount = 0;
    std::size_t eventCount = 0;
    std::size_t leafCount = 0;
    std::size_t groupCount = 0;
    std::size_t holderCount = 0;
    ASSERT_TRUE(harken::test::CollectInitialQueueTimingMembersForTest(
        *engine, firing, attempt->initialEntryFrame + 64u,
        &memberCount, &programCount, &eventCount, &leafCount,
        &groupCount, &holderCount));
    ASSERT_GE(memberCount, 1u);
    ASSERT_GE(leafCount, 2u);
    ASSERT_GE(groupCount, 1u);
    ASSERT_GE(holderCount, 1u);
    std::vector<harken::TransactionRequest> requests;
    std::vector<harken::ScheduledEventInput> scheduledEvents;
    std::vector<harken::UnplacedBatchCohortMember> cohort;
    const auto buildMaterializationInputs = [&] {
        requests.assign(programCount, {});
        scheduledEvents.assign(eventCount, {});
        cohort.clear();
        for (std::size_t index = 0; index < eventCount; ++index) {
            const auto& staged = engine->initialQueueTimingEventsScratch[index];
            const auto& source = *staged.frozen;
            auto& scheduled = scheduledEvents[index];
            scheduled.executeFrame = staged.newExecuteFrame;
            scheduled.logicCommitSequence = source.logicCommitSequence;
            scheduled.executionOrdinal = source.executionOrdinal;
            scheduled.eventIndex = source.eventIndex;
            scheduled.transactionOrdinal = source.transactionOrdinal;
            scheduled.subeventPhase = source.subeventPhase;
            scheduled.payload = source.payload;
            scheduled.authoredFadeOutCandidate = source.authoredFadeOutCandidate;
            scheduled.armToken = source.armToken;
            scheduled.frontier = source.frontier;
        }
        for (std::size_t index = 0; index < programCount; ++index) {
            const auto& staged = engine->initialQueueTimingProgramsScratch[index];
            const auto& frozen = *staged.frozen;
            auto& request = requests[index];
            request.transactionId = frozen.transactionId;
            request.transportEpoch = engine->timelinePool.Epoch();
            request.ownerInstanceHandle = frozen.ownerInstance;
            request.ownerInstanceScheduleEpoch = frozen.ownerInstanceScheduleEpoch;
            request.occurrence = frozen.occurrence;
            request.program = frozen.runtimeProgram;
            request.armToken = frozen.armToken;
            request.events = &scheduledEvents[staged.firstEvent];
            request.eventCount = staged.eventCount;
        }
        for (std::size_t index = 0; index < memberCount; ++index) {
            const auto& candidate = engine->initialQueueTimingMembersScratch[index];
            if (!candidate.credit.Valid()) continue;
            harken::UnplacedBatchCohortMember holder{};
            holder.credit = &engine->playableServices[candidate.service.slot].QueuePayload().queueUnplacedCredit;
            holder.requests = candidate.transactionCount == 0 ? nullptr
                : &requests[candidate.firstProgram];
            holder.requestCount = candidate.transactionCount;
            holder.groups = candidate.groupCount == 0 ? nullptr
                : &engine->initialQueueTimingGroupsScratch[candidate.firstGroup];
            holder.groupCount = candidate.groupCount;
            cohort.push_back(holder);
        }
        EXPECT_EQ(holderCount, cohort.size());
    };
    buildMaterializationInputs();
    const auto composite = std::find_if(
        engine->initialQueueTimingMembersScratch.begin(),
        engine->initialQueueTimingMembersScratch.begin() + memberCount,
        [](const auto& candidate) {
            return candidate.currentLeafCount == 2u &&
                   candidate.conditional.Valid();
        });
    ASSERT_NE(engine->initialQueueTimingMembersScratch.begin() + memberCount,
              composite);
    EXPECT_EQ(composite->oldEntryFrame + 64u, composite->newEntryFrame);
    EXPECT_EQ(0u, composite->conditionalLogicalStartFrame);
    EXPECT_EQ(0u, composite->conditionalLogicalCompletionFrame);
    harken::KnownScheduleLeafV1 originalFirst{};
    harken::KnownScheduleLeafV1 originalSecond{};
    ASSERT_TRUE(engine->compositeCompletionOwners.CaptureLeaf(
        engine->playableServices[composite->service.slot]
            .QueuePayload().queueCurrentCompositeOwner, 0, &originalFirst));
    ASSERT_TRUE(engine->compositeCompletionOwners.CaptureLeaf(
        engine->playableServices[composite->service.slot]
            .QueuePayload().queueCurrentCompositeOwner, 1, &originalSecond));
    const auto compositeOwner = engine->playableServices[composite->service.slot].QueuePayload().queueCurrentCompositeOwner;
    harken::CompositeCompletionOwnerPool::PrivateReanchorProof shiftedProof;
    ASSERT_TRUE(engine->compositeCompletionOwners.ProvePrivateUniformReanchorBeforePublication(
        compositeOwner, composite->oldEntryFrame, composite->newEntryFrame,
        engine->timelineOccurrences, &shiftedProof));
    engine->compositeCompletionOwners.ApplyPrivateReanchorBeforePublication(shiftedProof);
    harken::KnownScheduleLeafV1 first{}, second{};
    ASSERT_TRUE(engine->compositeCompletionOwners.CaptureLeaf(compositeOwner, 0, &first));
    ASSERT_TRUE(engine->compositeCompletionOwners.CaptureLeaf(compositeOwner, 1, &second));
    ASSERT_EQ(96u, second.absoluteLeafStartFrame - first.absoluteLeafStartFrame);
    EXPECT_EQ(originalFirst.absoluteLeafStartFrame + 64u,
              first.absoluteLeafStartFrame);
    EXPECT_EQ(originalSecond.absoluteLeafStartFrame + 64u,
              second.absoluteLeafStartFrame);
    EXPECT_EQ(originalSecond.predicate.progressBaselineRevision,
              second.predicate.progressBaselineRevision);
    harken::CompositeCompletionOwnerPool::PrivateReanchorProof restoredProof;
    ASSERT_TRUE(engine->compositeCompletionOwners.ProvePrivateUniformReanchorBeforePublication(
        compositeOwner, composite->newEntryFrame, composite->oldEntryFrame,
        engine->timelineOccurrences, &restoredProof));
    engine->compositeCompletionOwners.ApplyPrivateReanchorBeforePublication(restoredProof);
    ASSERT_NE(nullptr, composite->successorBank);
    ASSERT_FALSE(composite->successorBank->published);
    ASSERT_GT(composite->transactionCount, 0u);
    ASSERT_LT(composite->firstProgram, programCount);
    const auto& stagedProgram = engine->initialQueueTimingProgramsScratch[
        composite->firstProgram];
    ASSERT_GT(stagedProgram.eventCount, 0u);
    ASSERT_LT(stagedProgram.firstEvent, eventCount);
    const auto& staged = engine->initialQueueTimingEventsScratch[
        stagedProgram.firstEvent];
    const auto& request = requests[composite->firstProgram];
    const auto& scheduled = scheduledEvents[stagedProgram.firstEvent];
    ASSERT_EQ(stagedProgram.eventCount, request.eventCount);
    ASSERT_EQ(&scheduled, request.events);
    EXPECT_EQ(staged.newExecuteFrame, scheduled.executeFrame);
    EXPECT_EQ(composite->service, staged.holder);
    EXPECT_EQ(composite->firstProgram, staged.programIndex);
    EXPECT_EQ(staged.newExecuteFrame - (attempt->initialEntryFrame + 64u),
              staged.relativeFrame);
    EXPECT_EQ(stagedProgram.frozen->ownerInstance,
              request.ownerInstanceHandle);
    EXPECT_EQ(stagedProgram.frozen->ownerInstanceScheduleEpoch,
              request.ownerInstanceScheduleEpoch);
    EXPECT_EQ(stagedProgram.frozen->transactionId,
              request.transactionId);
    EXPECT_EQ(stagedProgram.frozen->runtimeProgram.program,
              request.program.program);
    ASSERT_LT(composite->firstGroup, groupCount);
    const auto& queueHolder = engine->playableServices[composite->service.slot];
    const auto& queueFuture = engine->InitialQueueFilingFuture(queueHolder);
    ASSERT_TRUE(queueHolder.queueFirstContinuationLane);
    ASSERT_TRUE(queueHolder.initialQueueEntryDecision.Valid());
    ASSERT_TRUE(queueFuture.queueDecision.Valid());
    EXPECT_TRUE(queueHolder.initialQueueEntryDecision.slot != queueFuture.queueDecision.slot ||
                queueHolder.initialQueueEntryDecision.generation != queueFuture.queueDecision.generation);
    EXPECT_EQ(queueFuture.queueDecision.slot, composite->decision.slot);
    EXPECT_EQ(queueFuture.queueDecision.generation,
              composite->decision.generation);
    ASSERT_GE(composite->groupCount, 2u);
    ASSERT_LE(composite->groupCount, composite->newGroupFrames.size());
    ASSERT_LE(composite->firstGroup + composite->groupCount, groupCount);
    ASSERT_EQ(1u, queueHolder.QueuePayload().queueInitialCurrentDelayedCount);
    for (std::uint32_t index = 0; index < composite->groupCount; ++index) {
        const auto& expected = engine->initialQueueTimingGroupsScratch[
            composite->firstGroup + index];
        EXPECT_EQ(composite->newGroupFrames[index], expected.executeFrame);
        const auto decision = index == 0u ? queueHolder.initialQueueEntryDecision
                                          : queueFuture.queueDecision;
        EXPECT_EQ(decision.slot, expected.decision.slot);
        EXPECT_EQ(decision.generation, expected.decision.generation);
        EXPECT_EQ(index == 0u ? 0u : index - 1u, expected.sliceIndex);
        if (index == 0u) {
            EXPECT_EQ(queueHolder.QueuePayload().queueInitialCurrentDelayedArms.data(), expected.members);
            EXPECT_EQ(queueHolder.QueuePayload().queueInitialCurrentDelayedCount, expected.memberCount);
            EXPECT_EQ(0u, expected.sourceControlCount);
        } else {
            EXPECT_EQ(queueFuture.queueTransitionGroupArms.data(), expected.members);
            EXPECT_EQ(queueFuture.queueTransitionGroupArmCount, expected.memberCount);
            EXPECT_EQ(queueFuture.queueSourceControlArmCount, expected.sourceControlCount);
        }
    }
    const auto& group = engine->initialQueueTimingGroupsScratch[
        composite->firstGroup];
    const auto holder = std::find_if(
        cohort.begin(), cohort.end(),
        [composite](const auto& candidate) {
            return candidate.credit != nullptr &&
                candidate.credit->slot == composite->credit.slot &&
                candidate.credit->generation ==
                    composite->credit.generation;
        });
    ASSERT_NE(cohort.end(), holder);
    EXPECT_EQ(composite->transactionCount, holder->requestCount);
    EXPECT_EQ(composite->groupCount, holder->groupCount);
    EXPECT_EQ(&request, holder->requests);
    EXPECT_EQ(&group, holder->groups);
    std::uint32_t groupPage = UINT32_MAX;
    ASSERT_TRUE(engine->timelinePool.PageForFrame(
        group.executeFrame, &groupPage));
    const auto beforePage = *engine->timelinePool.Page(groupPage);
    {
        harken::ScheduledTransactionPool::PrivateMaterializationTransaction
            failedPage{};
        harken::ReserveRefusal transactionRefusal =
            harken::ReserveRefusal::None;
        harken::Plan03GroupReserveStatus groupStatus =
            harken::Plan03GroupReserveStatus::Committed;
        engine->timelinePool.SetPrivateMaterializationFaultStepForTest(2u);
        EXPECT_FALSE(engine->timelinePool.TryMaterializeUnplacedCohort(
            cohort.data(), cohort.size(),
            engine->timelineArms, engine->timelinePool.PublishCutoffFrame(),
            &failedPage, &transactionRefusal, &groupStatus));
        EXPECT_FALSE(failedPage.Valid());
    }
    const auto afterFailure = *engine->timelinePool.Page(groupPage);
    EXPECT_EQ(beforePage.committedTransactionCount,
              afterFailure.committedTransactionCount);
    EXPECT_EQ(beforePage.plan03GroupCount,
              afterFailure.plan03GroupCount);
    {
        harken::ScheduledTransactionPool::PrivateMaterializationTransaction
            privatePage{};
        harken::ReserveRefusal transactionRefusal =
            harken::ReserveRefusal::None;
        harken::Plan03GroupReserveStatus groupStatus =
            harken::Plan03GroupReserveStatus::Committed;
        ASSERT_TRUE(engine->timelinePool.TryMaterializeUnplacedCohort(
            cohort.data(), cohort.size(),
            engine->timelineArms, engine->timelinePool.PublishCutoffFrame(),
            &privatePage, &transactionRefusal, &groupStatus));
        ASSERT_TRUE(privatePage.Valid());
        EXPECT_EQ(groupCount, privatePage.GroupCount());
    }
    EXPECT_TRUE(engine->playableServices[composite->service.slot]
                    .QueuePayload().queueUnplacedCredit.Valid());
    ASSERT_NE(nullptr, staged.frozen);
    ASSERT_NE(nullptr, staged.payload);
    ASSERT_EQ(&composite->successorBank->schedules[0],
              stagedProgram.frozen);
    ASSERT_EQ(stagedProgram.frozen->events, staged.frozen);
    EXPECT_EQ(stagedProgram.frozen->entryAnchorFrame +
                  static_cast<std::uint64_t>(
                      staged.frozen->frameOffsetFromEntry) + 64u,
              staged.newExecuteFrame);
    EXPECT_FALSE(composite->successorBank->published);
    EXPECT_FALSE(harken::test::CollectInitialQueueTimingMembersForTest(
        *engine, firing, UINT64_MAX, &memberCount, &programCount,
        &eventCount, &leafCount, &groupCount, &holderCount));
    auto& groupOnlyRow = engine->playableServices[composite->service.slot];
    ASSERT_TRUE(engine->timelinePool.CancelUnplacedBatchCredit(
        &groupOnlyRow.QueuePayload().queueUnplacedCredit));
    harken::UnplacedBatchCreditRequest groupOnlyDemand{};
    groupOnlyDemand.groupHeaders = groupOnlyRow.QueuePayload().queueUnplacedGroupCount;
    ASSERT_GT(groupOnlyDemand.groupHeaders, 0u);
    ASSERT_TRUE(engine->timelinePool.ReserveUnplacedBatchCredit(
        groupOnlyDemand, &groupOnlyRow.QueuePayload().queueUnplacedCredit));
    groupOnlyRow.QueuePayload().queueUnplacedDemand = groupOnlyDemand;
    groupOnlyRow.QueuePayload().queueUnplacedDemandCredit =
        groupOnlyRow.QueuePayload().queueUnplacedCredit;
    groupOnlyRow.QueuePayload().queueUnplacedTransactionCount = 0;
    ASSERT_TRUE(harken::test::CollectInitialQueueTimingMembersForTest(
        *engine, firing, attempt->initialEntryFrame + 64u,
        &memberCount, &programCount, &eventCount, &leafCount,
        &groupCount, &holderCount));
    buildMaterializationInputs();
    const auto groupOnly = std::find_if(
        cohort.begin(), cohort.end(),
        [&groupOnlyRow](const auto& candidate) {
            return candidate.credit == &groupOnlyRow.QueuePayload().queueUnplacedCredit;
        });
    ASSERT_NE(cohort.end(), groupOnly);
    EXPECT_EQ(0u, groupOnly->requestCount);
    EXPECT_EQ(nullptr, groupOnly->requests);
    EXPECT_EQ(groupOnlyDemand.groupHeaders, groupOnly->groupCount);
    EXPECT_NE(nullptr, groupOnly->groups);
}

void AddIndependentSecondSoundPlayAction(CanonicalActionWorld& image) {
    image.steps[14] = image.steps[11];
    image.steps[14].target.kind = harken::ActionTargetKindV1::Sound;
    image.steps[14].target.stableId = CanonicalActionWorld::kSecondSound;
    image.steps[14].target.expectedProgramSemanticFingerprint =
        image.properties[1].programSemanticFingerprint;
    image.actions[10] = image.actions[9];
    image.actions[10].actionStableId = harkentest::ObjectId(51);
    image.actions[10].steps = &image.steps[14];
    image.actions[10].programSemanticFingerprint =
        harken::ComputeActionProgramFingerprintV1(image.actions[10]);
    image.world.actionCount = 11;
    image.world.identity.runtimeSemanticFingerprint =
        harken::ComputeCurrentWorldFingerprintV4(image.world);
}

TEST(ActionFiringApi, IndependentSoundInQueueWorldBaseline) {
    (void)Vn_Term();
    harkentest::EngineSession session(harkentest::MakeNullConfig(8, 64, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> samples(128, 0.25f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &pcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
    image.MakeImmediateSequenceQueuePlayAction();
    AddIndependentSecondSoundPlayAction(image);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);
    VnPostActionDesc independent = ValidPostDesc();
    independent.actionId = image.actions[10].actionStableId;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&independent.emitter));
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&independent, &firing));
    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    for (std::uint32_t block = 0; block < 8; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
        if (info.state == VN_ACTION_FIRING_TERMINAL_RETAINED) break;
    }
    VnActionStepResult step{};
    step.structSize = sizeof(step);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &step));
    EXPECT_EQ(VN_ACTION_OUTCOME_SUCCEEDED, info.outcome)
        << "terminalReason=" << info.terminalReason
        << " stepState=" << step.state
        << " stepResult=" << step.result;
}

void CheckInitialQueueLanePrepareFaultLeavesIndependentActionLive(
    bool yieldAfterFirstRootReader, bool blockSecondStop = false,
    bool repeatExternalStop = false, bool dropNotification = false) {
    (void)Vn_Term();
    auto config = harkentest::MakeNullConfig(8, 64, 48000);
    if (dropNotification) config.notificationQueueDepth = 32;
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> firstSamples(128, 0.25f);
    std::vector<float> secondSamples(128, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(firstSamples, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(secondSamples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound,
                                   &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound,
                                   &secondPcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
    image.MakeImmediateSequenceQueuePlayAction();
    AddIndependentSecondSoundPlayAction(image);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);
    VnPostActionDesc queue = ValidPostDesc();
    queue.actionId = image.actions[9].actionStableId;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&queue.emitter));
    VnActionFiringHandle queueFiring = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&queue, &queueFiring));
    const auto queueRow = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [queueFiring](const auto& row) {
            return row.queueTimingPending && row.InvocationValid() &&
                row.Invocation().actionFiring == queueFiring;
        });
    ASSERT_NE(engine->playableServices.end(), queueRow);
    ASSERT_TRUE(queueRow->QueuePayload().queueUnplacedCredit.Valid());
    const auto queueArm = queueRow->arm;
    const auto queueDecision = queueRow->QueueFiling().queueDecision;
    const auto queueCredit = queueRow->QueuePayload().queueUnplacedCredit;
    ASSERT_TRUE(queueDecision.Valid());
    const auto queueAttempt = std::find_if(
        engine->immediateEntryAttempts.data(),
        engine->immediateEntryAttempts.data() +
            engine->immediateEntryAttempts.size(),
        [queueFiring](const auto& candidate) {
            return candidate.active && candidate.root == queueFiring;
        });
    ASSERT_NE(engine->immediateEntryAttempts.data() +
                  engine->immediateEntryAttempts.size(), queueAttempt);
    const auto queueAttemptGeneration = queueAttempt->generation;
    const auto queueLane = queueAttempt->lane;
    ASSERT_TRUE(queueLane.Valid());
    std::array<harken::Plan03ImmediateLaneGroupDescriptor, 4> queueGroups{};
    const auto queueGroupCount = engine->timelinePool.
        CaptureImmediateLaneCohortGroups(
            queueFiring, queueGroups.data(), queueGroups.size());
    ASSERT_GT(queueGroupCount, 0u);
    ASSERT_LE(queueGroupCount, queueGroups.size());
    for (std::size_t index = 0; index < queueGroupCount; ++index)
        EXPECT_TRUE(queueGroups[index].identity.Exact());
    std::vector<harken::HorizonPageHeader> before;
    for (std::uint32_t page = 0;
         page < engine->timelinePool.PageCount(); ++page)
        before.push_back(*engine->timelinePool.Page(page));
    const auto baselineAudioSequence = engine->mixer.BlocksRendered();
    const auto commandBackpressureBefore = engine->commands.BackpressureCount();
    if (yieldAfterFirstRootReader)
        engine->forceInitialQueuePrivateRootReaderYieldAfterForTest = 0;
    if (blockSecondStop)
        engine->forceInitialQueuePrivateStopPushFailureAtForTest = 1;
    engine->forceImmediateLaneFutureEventFaultForTest = 3u;
    VnPostActionDesc independent = queue;
    independent.actionId = image.actions[10].actionStableId;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&independent.emitter));
    VnActionFiringHandle independentFiring = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&independent, &independentFiring));
    const auto privateBefore = engine->timelinePool
        .CapturePrivateMaterializationSnapshotForTest();
    VnActionFiringInfo independentInfo{};
    independentInfo.structSize = sizeof(independentInfo);
    bool observedFault = false;
    bool observedHeldArmAfterAudioBlock = false;
    bool observedSecondStopRetry = false;
    bool droppedExactTerminal = false;
    bool observedExactLedgerSweep = false;
    std::uint64_t faultAudioSequence = 0;
    int faultCoordinatorState = -1;
    std::uint32_t faultBoundFrontierGroups = 0;
    bool heardQueue = false;
    bool heardIndependent = false;
    for (std::uint32_t block = 0; block < 16; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        if (blockSecondStop && observedFault && !observedSecondStopRetry &&
            engine->forceInitialQueuePrivateStopPushFailureAtForTest == UINT32_MAX) {
            const auto secondRender = queueAttempt->privateVoices[1].render;
            std::uint32_t secondStopCount = 0;
            harken::CommandRecord queued{};
            for (std::uint32_t index = 0;
                 index < engine->commands.Capacity() - engine->commands.FreeSlots();
                 ++index) {
                ASSERT_TRUE(engine->commands.PeekAt(index, queued));
                if (queued.opcode == harken::kOpcodeStop &&
                    queued.payload.stop.handle == secondRender)
                    ++secondStopCount;
            }
            EXPECT_EQ(1u, secondStopCount);
            EXPECT_TRUE(queueAttempt->privateVoices[1].stopQueued);
            observedSecondStopRetry = true;
        }
        if (!observedFault &&
            engine->forceImmediateLaneFutureEventFaultForTest == 0) {
            observedFault = true;
            faultAudioSequence = engine->mixer.BlocksRendered();
            if (yieldAfterFirstRootReader) {
                ASSERT_EQ(UINT32_MAX - 1u,
                    engine->forceInitialQueuePrivateRootReaderYieldAfterForTest);
                ASSERT_GE(queueAttempt->privateVoiceCount, 2u);
                const auto& first = queueAttempt->privateVoices[0];
                const auto* firstArm = engine->timelineArms.Resolve(first.startArm);
                ASSERT_NE(nullptr, firstArm);
                EXPECT_TRUE(first.rootReaderReleased);
                EXPECT_TRUE(first.rootArmComplete);
                EXPECT_EQ(0u, firstArm->frontierReaderPins.load());
                EXPECT_TRUE(firstArm->frontierAdmissionFinished.load());
                EXPECT_EQ(nullptr, firstArm->frontierActiveLease.load());
            }
            if (blockSecondStop) {
                ASSERT_EQ(UINT32_MAX - 1u,
                    engine->forceInitialQueuePrivateStopPushFailureAtForTest);
                ASSERT_EQ(2u, queueAttempt->privateVoiceCount);
                EXPECT_EQ(harken::InitialQueuePrivateCleanupPhase::StopQueued,
                    queueAttempt->privateCleanupPhase);
                EXPECT_TRUE(queueAttempt->privateVoices[0].stopQueued);
                EXPECT_FALSE(queueAttempt->privateVoices[1].stopQueued);
                EXPECT_TRUE(engine->ledger.IsTerminating(
                    queueAttempt->privateVoices[0].render));
                EXPECT_FALSE(engine->ledger.IsTerminating(
                    queueAttempt->privateVoices[1].render));
                EXPECT_TRUE(engine->ledger.OwnerForRender(
                    queueAttempt->privateVoices[1].render).live);
                EXPECT_TRUE(engine->commands.Full());
                EXPECT_GT(engine->commands.BackpressureCount(),
                          commandBackpressureBefore);
                std::uint32_t firstStopCount = 0;
                std::uint32_t secondStopCount = 0;
                harken::CommandRecord queued{};
                for (std::uint32_t index = 0;
                     index < engine->commands.Capacity() -
                         engine->commands.FreeSlots(); ++index) {
                    ASSERT_TRUE(engine->commands.PeekAt(index, queued));
                    if (queued.opcode != harken::kOpcodeStop) continue;
                    firstStopCount += queued.payload.stop.handle ==
                        queueAttempt->privateVoices[0].render;
                    secondStopCount += queued.payload.stop.handle ==
                        queueAttempt->privateVoices[1].render;
                }
                EXPECT_EQ(1u, firstStopCount);
                EXPECT_EQ(0u, secondStopCount);
            }
            if (repeatExternalStop) {
                ASSERT_EQ(VN_OK, Vn_StopActionFiring(queueFiring, 0));
                ASSERT_EQ(VN_OK, Vn_StopActionFiring(queueFiring, 0));
                EXPECT_NE(0u, queueRow->pendingCancellationIntent);
            }
            auto* coordinator = engine->decisions.ResolveFrontierActivation(
                queueAttempt->QueueCoordinators().initialQueueCoordinator);
            if (coordinator != nullptr)
                faultCoordinatorState = static_cast<int>(coordinator->State());
            for (std::size_t index = 0; index < queueGroupCount; ++index) {
                harken::Plan03PageGroupView group{};
                if (!engine->timelinePool.ResolvePlan03GroupSliceProducer(
                        queueGroups[index].identity, &group) ||
                    group.frontier == nullptr) continue;
                const auto& owner = group.frontier->operation.owner;
                if (owner.serviceSlot == queueRow->identity.slot &&
                    owner.serviceGeneration == queueRow->identity.generation)
                    ++faultBoundFrontierGroups;
            }
            const auto snapshot = engine->timelinePool
                .CapturePrivateMaterializationSnapshotForTest();
            EXPECT_LE(snapshot.preparedEvents,
                      privateBefore.preparedEvents);
            EXPECT_LE(snapshot.preparedGroups,
                      privateBefore.preparedGroups);
            EXPECT_LE(snapshot.publicationHolds,
                      privateBefore.publicationHolds);
            EXPECT_FALSE(snapshot.active);
            EXPECT_FALSE(queueRow->queueTimingFinalized);
            EXPECT_NE(harken::ImmediateEntryAttemptState::Committed,
                      queueAttempt->gate.Observe(queueAttemptGeneration));
            harken::ImmediateLaneObservation lane{};
            if (engine->immediateActionLane.Observe(
                    queueLane, &lane))
                EXPECT_FALSE(lane.committed);
            for (std::size_t index = 0; index < queueGroupCount; ++index) {
                harken::Plan03PageGroupView audioGroup{};
                EXPECT_FALSE(engine->timelinePool.ResolvePlan03GroupSliceRt(
                    queueGroups[index].identity, &audioGroup));
            }
            harken::ArmState armState = harken::ArmState::Free;
            if (engine->timelineArms.State(queueArm, &armState)) {
                EXPECT_NE(harken::ArmState::Published, armState);
                EXPECT_NE(harken::ArmState::Started, armState);
            }
            testing::Test::RecordProperty(
                "fault_decision_open",
                engine->decisions.IsOpen(queueDecision) ? 1 : 0);
            testing::Test::RecordProperty(
                "fault_decision_cancelled",
                engine->decisions.IsCancelled(queueDecision) ? 1 : 0);
            testing::Test::RecordProperty(
                "fault_credit_exact",
                queueRow->QueuePayload().queueUnplacedCredit.Valid() &&
                    queueRow->QueuePayload().queueUnplacedCredit.slot == queueCredit.slot &&
                    queueRow->QueuePayload().queueUnplacedCredit.generation ==
                        queueCredit.generation ? 1 : 0);
        }
        engine->nullBackend.Pump(1);
        if (dropNotification && observedFault && !droppedExactTerminal) {
            const auto& first = queueAttempt->privateVoices[0];
            std::array<VnNotification, 32> preserved{};
            std::size_t preservedCount = 0;
            VnNotification event{};
            while (engine->notifications.TryPop(event)) {
                if (event.voiceHandle == first.render &&
                    (event.type == VN_NOTIFY_VOICE_ENDED ||
                     event.type == VN_NOTIFY_VOICE_STOPPED_BY_FADE ||
                     event.type == VN_NOTIFY_VOICE_STOLEN)) {
                    EXPECT_FALSE(droppedExactTerminal);
                    droppedExactTerminal = true;
                    continue;
                }
                ASSERT_LT(preservedCount, preserved.size());
                preserved[preservedCount++] = event;
            }
            for (std::size_t index = 0; index < preservedCount; ++index)
                ASSERT_TRUE(engine->notifications.Push(preserved[index]));
            if (droppedExactTerminal) {
                EXPECT_TRUE(engine->voices.ReleaseObserved(first.release));
                EXPECT_EQ(nullptr, engine->voices.Resolve(first.render));
                EXPECT_TRUE(engine->ledger.OwnerForRender(first.render).live);
            }
        }
        if (yieldAfterFirstRootReader && observedFault &&
            engine->forceInitialQueuePrivateRootReaderYieldAfterForTest ==
                UINT32_MAX - 1u &&
            engine->mixer.BlocksRendered() >
                engine->forceInitialQueuePrivateRootReaderYieldSequenceForTest) {
            const auto& first = queueAttempt->privateVoices[0];
            const auto* firstArm = engine->timelineArms.Resolve(first.startArm);
            ASSERT_NE(nullptr, firstArm);
            ASSERT_LT(first.startArm.slot, engine->initialFrontierArmPins.size());
            EXPECT_FALSE(engine->initialFrontierArmPins[first.startArm.slot].pin.Valid());
            EXPECT_TRUE(first.rootReaderReleased);
            EXPECT_TRUE(first.rootArmComplete);
            EXPECT_EQ(0u, firstArm->frontierReaderPins.load());
            observedHeldArmAfterAudioBlock = true;
        }
        const auto* output = engine->nullBackend.LastBlock();
        heardQueue = heardQueue || std::any_of(output, output + 64,
            [](float sample) { return sample > 0.01f; });
        heardIndependent = heardIndependent || std::any_of(output, output + 64,
            [](float sample) { return sample < -0.01f; });
        ASSERT_EQ(VN_OK, Vn_Update());
        if (dropNotification && droppedExactTerminal && !observedExactLedgerSweep) {
            EXPECT_FALSE(engine->ledger.OwnerForRender(
                queueAttempt->privateVoices[0].render).live);
            observedExactLedgerSweep = true;
        }
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(
            independentFiring, &independentInfo));
        if (independentInfo.state == VN_ACTION_FIRING_TERMINAL_RETAINED)
            break;
    }
    EXPECT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED,
              independentInfo.state);
    VnActionStepResult independentStep{};
    independentStep.structSize = sizeof(independentStep);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(
        independentFiring, 0, &independentStep));
    EXPECT_EQ(VN_ACTION_OUTCOME_SUCCEEDED, independentInfo.outcome)
        << "terminalReason=" << independentInfo.terminalReason
        << " stepState=" << independentStep.state
        << " stepResult=" << independentStep.result;
    EXPECT_TRUE(observedFault);
    EXPECT_EQ(0u, engine->forceImmediateLaneFutureEventFaultForTest);
    EXPECT_TRUE(heardIndependent);
    for (std::uint32_t page = 0; page < before.size(); ++page) {
        const auto after = *engine->timelinePool.Page(page);
        EXPECT_EQ(before[page].committedTransactionCount,
                  after.committedTransactionCount);
        EXPECT_EQ(before[page].plan03GroupCount,
                  after.plan03GroupCount);
    }
    EXPECT_FALSE(queueRow->queueTimingFinalized);
    VnActionFiringInfo queueInfo{};
    queueInfo.structSize = sizeof(queueInfo);
    for (std::uint32_t block = 0; block < 32; ++block) {
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(queueFiring, &queueInfo));
        if (queueInfo.state == VN_ACTION_FIRING_TERMINAL_RETAINED)
            break;
        engine->nullBackend.Pump(1);
        const auto* output = engine->nullBackend.LastBlock();
        heardQueue = heardQueue || std::any_of(output, output + 64,
            [](float sample) { return sample > 0.01f; });
        ASSERT_EQ(VN_OK, Vn_Update());
    }
    harken::ImmediateLaneObservation laneAtRetirement{};
    const bool laneObservedAtRetirement =
        engine->immediateActionLane.Observe(queueLane, &laneAtRetirement);
    harken::FrontierActivationReceipt frontierReceipt{};
    auto* frontier = queueRow->frontierEntry.Valid()
        ? engine->decisions.ResolveFrontierActivation(
              queueRow->frontierEntry.coordinator)
        : nullptr;
    const auto frontierRead = frontier != nullptr
        ? frontier->Read(queueRow->frontierEntry,
              engine->mixer.BlocksRendered(), &frontierReceipt)
        : harken::FrontierReceiptRead::Stale;
    harken::ArmState rootArmState = harken::ArmState::Free;
    const bool rootArmObserved =
        engine->timelineArms.State(queueArm, &rootArmState);
    harken::TimelineArmObservation rootArmObservation{};
    (void)engine->timelineArms.Observe(queueArm, &rootArmObservation);
    const auto finalAudioSequence = engine->mixer.BlocksRendered();
    auto* finalCoordinator = engine->decisions.ResolveFrontierActivation(
        queueAttempt->QueueCoordinators().initialQueueCoordinator);
    SCOPED_TRACE(::testing::Message()
        << "queue state=" << queueInfo.state
        << " live=" << queueInfo.livePlayableCount
        << " phase=" << static_cast<int>(queueRow->phase)
        << " lifecycle=" << static_cast<int>(queueRow->controlLifecycle)
        << " reason=" << static_cast<int>(queueRow->controlReason)
        << " timing pending=" << queueRow->queueTimingPending
        << " credit=" << queueRow->QueuePayload().queueUnplacedCredit.Valid()
        << " voices=" << engine->voices.ActiveCount()
        << " queue instances=" << engine->queueInstances.LiveCount()
        << " playables=" << engine->playableInstances.LiveCount()
        << " frontier=" << queueRow->frontierEntry.Valid()
        << " frontier read=" << static_cast<int>(frontierRead)
        << " frontier outcome=" << static_cast<int>(frontierReceipt.outcome)
        << " frontier pin=" << queueRow->frontierArmPin.Valid()
        << " lane observed=" << laneObservedAtRetirement
        << " lane cancelled=" << laneAtRetirement.cancelled
        << " lane complete=" << laneAtRetirement.complete
        << " root arm observed=" << rootArmObserved
        << " root arm state=" << static_cast<int>(rootArmState)
        << " root arm started=" << rootArmObservation.startedBlockSequence
        << " root arm logical=" << rootArmObservation.logicalCompletionSequence
        << " root arm tombstone=" << rootArmObservation.tombstoneAudioSequence
        << " parent=" << queueRow->parentService.Valid()
        << " zero work=" << queueRow->zeroWorkMarker
        << " has zero completion=" << queueRow->hasZeroWorkCompletion
        << " deferred cancellation=" << queueRow->variableControlDeferredCancellation
        << " pending cancellation=" << queueRow->pendingCancellationIntent
        << " pending entry=" << queueRow->pendingImmediateEntry
        << " producer slot=" << queueAttempt->producerSlot
        << " queue cleanup=" << queueRow->queueCleanupStarted
        << " queue decision committed=" << queueRow->QueueFiling().queueDecisionCommitted
        << " queue natural end=" << queueRow->queueNaturalEnd
        << " queue deferred full=" << queueRow->queueDeferredNeedsFullPreparation
        << " queue final tomb=" << queueRow->queueFinalSourceTombstoned
        << " firing=" << queueFiring
        << " row slot=" << queueRow->identity.slot
        << " row generation=" << queueRow->identity.generation
        << " attempt generation=" << queueAttemptGeneration
        << " attempt active=" << queueAttempt->active
        << " private phase=" << static_cast<int>(queueAttempt->privateCleanupPhase)
        << " private voices=" << queueAttempt->privateVoiceCount
        << " gate state=" << static_cast<int>(queueAttempt->gate.Observe(queueAttemptGeneration))
        << " coordinator slot=" << queueAttempt->QueueCoordinators().initialQueueCoordinator.slot
        << " coordinator generation=" << queueAttempt->QueueCoordinators().initialQueueCoordinator.generation
        << " coordinator state=" << (finalCoordinator != nullptr
            ? static_cast<int>(finalCoordinator->State()) : -1)
        << " bound frontier groups=" << faultBoundFrontierGroups
        << " baseline audio seq=" << baselineAudioSequence
        << " fault audio seq=" << faultAudioSequence
        << " fault coordinator state=" << faultCoordinatorState
        << " final audio seq=" << finalAudioSequence
        << " initial decision=" << queueRow->initialQueueEntryDecision.Valid()
        << " initial group=" << queueRow->QueuePayload().queueInitialLaneArmGroup.Valid());
    ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, queueInfo.state);
    EXPECT_FALSE(heardQueue);
    EXPECT_EQ(0u, queueInfo.livePlayableCount);
    EXPECT_EQ(0u, engine->queueInstances.LiveCount());
    EXPECT_EQ(0u, engine->voices.ActiveCount());
    EXPECT_EQ(0u, engine->playableInstances.LiveCount());
    if (dropNotification) {
        EXPECT_TRUE(droppedExactTerminal);
        EXPECT_TRUE(observedExactLedgerSweep);
    }
    if (yieldAfterFirstRootReader) {
        EXPECT_TRUE(observedHeldArmAfterAudioBlock);
        EXPECT_EQ(UINT32_MAX,
            engine->forceInitialQueuePrivateRootReaderYieldAfterForTest);
        EXPECT_GT(finalAudioSequence,
            engine->forceInitialQueuePrivateRootReaderYieldSequenceForTest);
    }
    if (blockSecondStop) {
        EXPECT_TRUE(observedSecondStopRetry);
        EXPECT_EQ(UINT32_MAX,
            engine->forceInitialQueuePrivateStopPushFailureAtForTest);
        EXPECT_GT(finalAudioSequence,
            engine->forceInitialQueuePrivateStopRetrySequenceForTest);
    }
    ASSERT_EQ(2u, queueAttempt->privateVoiceCount);
    std::array<std::pair<VnVoiceHandle, harken::VoiceReleaseObserver>, 2>
        retiredVoices{};
    for (std::uint32_t index = 0; index < queueAttempt->privateVoiceCount; ++index) {
        const auto& voice = queueAttempt->privateVoices[index];
        retiredVoices[index] = {voice.render, voice.release};
        EXPECT_TRUE(voice.rootReaderReleased);
        EXPECT_TRUE(voice.rootArmComplete);
        EXPECT_TRUE(engine->voices.ReleaseObserved(voice.release));
        EXPECT_EQ(nullptr, engine->voices.Resolve(voice.render));
        EXPECT_GT(finalAudioSequence, voice.stopQueued
            ? voice.stopQueuedAudioSequence : voice.capturedAudioSequence);
        EXPECT_FALSE(engine->ledger.OwnerForRender(voice.render).live);
    }
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(queueFiring));
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(independentFiring));
    VnActionFiringHandle replay = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&queue, &replay));
    for (std::size_t index = 0; index < queueGroupCount; ++index) {
        harken::Plan03PageGroupView staleGroup{};
        harken::ImmediateLaneFrontierClaim staleClaim{};
        EXPECT_FALSE(engine->timelinePool.ResolvePlan03GroupSliceProducer(
            queueGroups[index].identity, &staleGroup));
        EXPECT_FALSE(engine->timelinePool.ClaimPrivateImmediateLaneFrontier(
            queueGroups[index].identity, &staleClaim));
    }
    for (const auto& [oldRender, oldRelease] : retiredVoices) {
        const auto slot = static_cast<std::uint32_t>(oldRender);
        ASSERT_LT(slot, engine->timelineVoiceInstallIdentities.size());
        const auto& replacement = engine->timelineVoiceInstallIdentities[slot];
        ASSERT_NE(0u, replacement.renderHandle);
        EXPECT_EQ(slot, static_cast<std::uint32_t>(replacement.renderHandle));
        EXPECT_NE(oldRender, replacement.renderHandle);
        EXPECT_NE(static_cast<std::uint32_t>(oldRender >> 32),
                  static_cast<std::uint32_t>(replacement.renderHandle >> 32));
        EXPECT_TRUE(engine->voices.ReleaseObserved(oldRelease));
        EXPECT_EQ(nullptr, engine->voices.Resolve(oldRender));
        EXPECT_FALSE(engine->ledger.OwnerForRender(oldRender).live);
        EXPECT_FALSE(engine->voices.ReleaseObserved(replacement.releaseObserver));
        EXPECT_NE(nullptr, engine->voices.Resolve(replacement.renderHandle));
        EXPECT_TRUE(engine->ledger.OwnerForRender(replacement.renderHandle).live);
    }
    bool replayHeard = false;
    VnActionFiringInfo replayInfo{};
    replayInfo.structSize = sizeof(replayInfo);
    for (std::uint32_t block = 0; block < 32; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        const auto* output = engine->nullBackend.LastBlock();
        replayHeard = replayHeard || std::any_of(output, output + 64,
            [](float sample) { return sample > 0.01f; });
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(replay, &replayInfo));
        if (replayInfo.state == VN_ACTION_FIRING_TERMINAL_RETAINED)
            break;
    }
    EXPECT_TRUE(replayHeard);
    EXPECT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, replayInfo.state);
    EXPECT_EQ(VN_ACTION_OUTCOME_SUCCEEDED, replayInfo.outcome);
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(replay));
}

TEST(ActionFiringApi, InitialQueueLanePrepareFaultLeavesIndependentActionLive) {
    CheckInitialQueueLanePrepareFaultLeavesIndependentActionLive(false);
}

TEST(ActionFiringApi, InitialQueuePrivateRootReadersResumeAfterAudioBlock) {
    CheckInitialQueueLanePrepareFaultLeavesIndependentActionLive(true);
}

TEST(ActionFiringApi, InitialQueuePrivateSecondStopRetriesAfterFullCommandQueue) {
    CheckInitialQueueLanePrepareFaultLeavesIndependentActionLive(false, true);
}

TEST(ActionFiringApi, InitialQueuePrivateRepeatedExternalStopRetainsCleanupOwner) {
    CheckInitialQueueLanePrepareFaultLeavesIndependentActionLive(true, false, true);
}

TEST(ActionFiringApi, InitialQueuePrivateDroppedTerminalNotificationStillReapsLedger) {
    CheckInitialQueueLanePrepareFaultLeavesIndependentActionLive(false, false,
        false, true);
}


TEST(ActionFiringApi, ImmediateSequenceQueuePlayCompletesAfterEveryChildRetires) {
    (void)Vn_Term();
    VnConfig config = harkentest::MakeNullConfig(8, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> first(64, 0.25f);
    std::vector<float> second(128, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kSecondSound,
                             &secondPcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound)
            .contentRevision);
    image.MakeImmediateSequenceQueuePlayAction();
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&desc.emitter));
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));

    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
    EXPECT_EQ(VN_ACTION_FIRING_ACTIVE, info.state);
    EXPECT_EQ(1u, info.livePlayableCount);
    VnActionStepResult play{};
    play.structSize = sizeof(play);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
    EXPECT_EQ(VN_ACTION_STEP_ACTIVE, play.state);
    EXPECT_EQ(VN_ACTION_TARGET_CONTAINER, play.targetKind);
    ASSERT_NE(0u, play.producedPlayableInstance);
    const auto initialQueue = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == play.producedPlayableInstance &&
                candidate.queueMode;
        });
    ASSERT_NE(engine->playableServices.end(), initialQueue);
    ASSERT_TRUE(initialQueue->initialQueueEntryDecision.Valid());
    ASSERT_TRUE(initialQueue->QueueFiling().queueDecision.Valid());
    EXPECT_TRUE(initialQueue->initialQueueEntryDecision.slot !=
                    initialQueue->QueueFiling().queueDecision.slot ||
                initialQueue->initialQueueEntryDecision.generation !=
                    initialQueue->QueueFiling().queueDecision.generation);

    bool observedSecondChild = false;
    bool continuationApplied = false;
    std::uint64_t initialActivationSequence = 0;
    std::uint64_t pendingVersion = 0;
    harken::ConditionalQueueActivation pendingActivation =
        harken::ConditionalQueueActivation::Waiting;
    std::uint32_t lastVoiceCount = 0;
    for (std::uint32_t block = 0; block < 64; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        const auto row = std::find_if(
            engine->playableServices.begin(), engine->playableServices.end(),
            [&](const harken::EnginePlayableServiceRow& candidate) {
                return candidate.rootInstance ==
                       play.producedPlayableInstance;
            });
        if (row != engine->playableServices.end() &&
            row->leaf.stableId == CanonicalActionWorld::kSecondSound) {
            observedSecondChild = true;
        }
        if (row != engine->playableServices.end() &&
            row->queueInstance.Valid()) {
            harken::QueueInstanceSnapshot queue{};
            if (engine->queueInstances.Capture(row->queueInstance, &queue)) {
                initialActivationSequence = queue.initialActivationSequence;
                pendingActivation = queue.pendingActivation;
                pendingVersion = queue.pendingVersion;
            }
        }
        const auto attempt = std::find_if(
            engine->immediateEntryAttempts.data(),
            engine->immediateEntryAttempts.data() +
                engine->immediateEntryAttempts.size(),
            [firing](const auto& candidate) {
                return candidate.active && candidate.root == firing;
            });
        if (attempt != engine->immediateEntryAttempts.data() +
                engine->immediateEntryAttempts.size() &&
            attempt->QueueCoordinators().queueContinuationCoordinator.Valid()) {
            const auto* activation = engine->decisions.ResolveFrontierActivation(
                attempt->QueueCoordinators().queueContinuationCoordinator);
            harken::FrontierActivationReceipt receipt{};
            continuationApplied = continuationApplied ||
                (activation != nullptr &&
                 activation->Read(attempt->QueueCoordinators().queueContinuationDescriptor.entry,
                     engine->mixer.BlocksRendered(), &receipt) ==
                     harken::FrontierReceiptRead::Ready &&
                 receipt.outcome ==
                     harken::FrontierReceiptOutcome::Applied);
        }
        lastVoiceCount = engine->voices.ActiveCount();
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
        if (info.state == VN_ACTION_FIRING_TERMINAL_RETAINED) {
            break;
        }
    }

    const auto finalQueue = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const auto& candidate) {
            return candidate.rootInstance == play.producedPlayableInstance &&
                candidate.queueMode;
        });
    const auto finalAttempt = std::find_if(
        engine->immediateEntryAttempts.data(),
        engine->immediateEntryAttempts.data() +
            engine->immediateEntryAttempts.size(),
        [firing](const auto& candidate) {
            return candidate.active && candidate.root == firing;
        });
    std::array<harken::Plan03ImmediateLaneGroupDescriptor, 4>
        remainingGroups{};
    const auto remainingGroupCount =
        engine->timelinePool.CaptureImmediateLaneCohortGroups(
            firing, remainingGroups.data(), remainingGroups.size());
    SCOPED_TRACE(::testing::Message()
        << "C1 applied=" << continuationApplied
        << " initial sequence=" << initialActivationSequence
        << " pending activation=" << static_cast<int>(pendingActivation)
        << " pending version=" << pendingVersion
        << " voices=" << lastVoiceCount
        << " queues=" << engine->queueInstances.LiveCount()
        << " live playables=" << info.livePlayableCount
        << " row=" << (finalQueue != engine->playableServices.end())
        << " phase=" << (finalQueue == engine->playableServices.end()
            ? -1 : static_cast<int>(finalQueue->phase))
        << " terminal=" << (finalQueue != engine->playableServices.end() &&
            finalQueue->terminalObserved)
        << " final tombstone=" <<
            (finalQueue != engine->playableServices.end() &&
             finalQueue->queueFinalSourceTombstoned)
        << " continuation=" <<
            (finalQueue != engine->playableServices.end() &&
             finalQueue->queueContinuationPrepared)
        << " timing finalized=" <<
            (finalQueue != engine->playableServices.end() &&
             finalQueue->queueTimingFinalized)
        << " pending futures=" <<
            (finalQueue == engine->playableServices.end()
                ? 0u : finalQueue->pendingFutureCount)
        << " arrival decision=" <<
            (finalQueue != engine->playableServices.end() &&
             finalQueue->queueArrivalDecision.Valid())
        << " retiring occurrence=" <<
            (finalQueue == engine->playableServices.end()
                ? 0u : finalQueue->QueuePayload().queueRetiringOccurrence.generation)
        << " lane attempt=" <<
            (finalAttempt != engine->immediateEntryAttempts.data() +
                engine->immediateEntryAttempts.size())
        << " lane groups=" << remainingGroupCount
        << " lane valid=" <<
            (finalAttempt != engine->immediateEntryAttempts.data() +
                engine->immediateEntryAttempts.size() &&
             finalAttempt->lane.Valid())
        << " C0 group=" <<
            (finalAttempt != engine->immediateEntryAttempts.data() +
                engine->immediateEntryAttempts.size() &&
             finalAttempt->QueueCoordinators().initialQueuePrimaryGroup.Exact())
        << " C1 group=" <<
            (finalAttempt != engine->immediateEntryAttempts.data() +
                engine->immediateEntryAttempts.size() &&
             finalAttempt->QueueCoordinators().queueContinuationPrimaryGroup.Exact()));
    EXPECT_TRUE(observedSecondChild);
    ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
    EXPECT_EQ(VN_ACTION_OUTCOME_SUCCEEDED, info.outcome);
    EXPECT_EQ(VN_ACTION_TERMINAL_NATURAL, info.terminalReason);
    EXPECT_EQ(0u, info.livePlayableCount);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
    EXPECT_EQ(VN_ACTION_STEP_SUCCEEDED, play.state);
    EXPECT_EQ(0u, engine->voices.ActiveCount());
    EXPECT_EQ(0u, engine->queueInstances.LiveCount());
    EXPECT_FALSE(engine->playableInstances
                     .Classify(play.producedPlayableInstance)
                     .live);
    EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
}

TEST(ActionFiringApi, InitialQueueChildrenStartAfterOneNormalUpdate) {
    (void)Vn_Term();
    constexpr std::uint32_t kBlockFrames = 64;
    harkentest::EngineSession session(
        harkentest::MakeNullConfig(8, kBlockFrames, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    std::vector<float> first(kBlockFrames, 0.25f);
    std::vector<float> second(2 * kBlockFrames, -0.25f);
    const auto firstPcm = harkentest::MonoDesc(first, 48000);
    const auto secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound,
                                   &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound,
                                   &secondPcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
    image.MakeImmediateSequenceQueuePlayAction();
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);
    auto post = ValidPostDesc();
    post.actionId = image.actions[9].actionStableId;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&post.emitter));
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&post, &firing));
    const auto* before = std::find_if(
        engine->immediateEntryAttempts.data(),
        engine->immediateEntryAttempts.data() + engine->immediateEntryAttempts.size(),
        [firing](const auto& candidate) { return candidate.active && candidate.root == firing; });
    ASSERT_NE(engine->immediateEntryAttempts.data() + engine->immediateEntryAttempts.size(), before);
    ASSERT_TRUE(before->QueueCoordinators().initialQueuePrimaryGroup.Exact());
    ASSERT_TRUE(before->QueueCoordinators().initialQueueCoordinator.Valid());
    const auto savedGroupCount = engine->timelinePool.CaptureImmediateLaneCohortGroups(
        firing, engine->initialQueueLaneGroupsScratch.data(),
        engine->initialQueueLaneGroupsScratch.size());
    std::array<harken::Plan03GroupSliceIdentity, 4> savedGroups{};
    for (std::size_t groupIndex = 0;
         groupIndex < savedGroupCount && groupIndex < savedGroups.size();
         ++groupIndex)
        savedGroups[groupIndex] = engine->initialQueueLaneGroupsScratch[groupIndex].identity;
    ASSERT_EQ(4u, savedGroupCount);
    const auto futureGroup = savedGroups[0] == before->QueueCoordinators().initialQueuePrimaryGroup
        ? savedGroups[1] : savedGroups[0];
    ASSERT_TRUE(futureGroup.Exact());
    engine->nullBackend.Pump(1);
    ASSERT_EQ(VN_OK, Vn_Update());

    const auto* attempt = std::find_if(
        engine->immediateEntryAttempts.data(),
        engine->immediateEntryAttempts.data() +
            engine->immediateEntryAttempts.size(),
        [firing](const auto& candidate) {
            return candidate.active && candidate.root == firing;
        });
    ASSERT_NE(engine->immediateEntryAttempts.data() +
                  engine->immediateEntryAttempts.size(), attempt);
    harken::ImmediateLaneObservation initialLane{};
    ASSERT_TRUE(engine->immediateActionLane.Observe(attempt->lane,
                                                  &initialLane));
    EXPECT_TRUE(initialLane.committed);
    for (const auto& holder : engine->playableServices) {
        if (holder.PendingImmediateCohortRoot() != firing ||
            !holder.queueTimingPending) continue;
        testing::Test::RecordProperty("queue_transactions",
            holder.QueuePayload().queueUnplacedTransactionCount);
        testing::Test::RecordProperty("queue_groups",
            holder.QueuePayload().queueUnplacedGroupCount);
        testing::Test::RecordProperty("queue_group_arms",
            holder.QueueFiling().queueTransitionGroupArmCount);
        testing::Test::RecordProperty("queue_source_control_arms",
            holder.QueueFiling().queueSourceControlArmCount);
    }
    const auto firstQuantum = attempt->entryQuantum;
    const auto rendered = engine->mixer.BlocksRendered();
    ASSERT_GE(firstQuantum, rendered);
    ASSERT_LT(firstQuantum - rendered + 2u, 8u);
    std::array<float, 8> blockAverages{};
    for (std::uint32_t block = 0; block < 8; ++block) {
        const auto entryBlock = static_cast<std::uint32_t>(
            firstQuantum - rendered);
        if (block == entryBlock + 1u) {
            const auto* bucket = engine->immediateActionLane.CaptureDue(
                attempt->lane.slot, firstQuantum + 1u);
            ASSERT_NE(nullptr, bucket);
            EXPECT_EQ(2u, bucket->groupCount);
            EXPECT_EQ(2u, bucket->eventCount);
            EXPECT_EQ(1u, bucket->memberCount);
            const auto* groups = engine->immediateActionLane.Groups(
                attempt->lane.slot, bucket);
            const auto* events = engine->immediateActionLane.Events(
                attempt->lane.slot, bucket);
            ASSERT_NE(nullptr, groups);
            ASSERT_NE(nullptr, events);
            std::uint32_t controllers = 0;
            std::uint32_t starts = 0;
            for (std::uint32_t index = 0; index < bucket->eventCount;
                 ++index) {
                const auto& event = events[index];
                if (event.futureGroupedStart) {
                    ++starts;
                    EXPECT_EQ(harken::FrontierOperationKind::Dependent,
                        event.event.frontier.kind);
                    EXPECT_EQ(20u, event.event.subeventPhase);
                    EXPECT_EQ(attempt->QueueCoordinators().queueContinuationDescriptor.entry,
                        event.event.frontier.entry);
                    EXPECT_NE(attempt->QueueCoordinators().queueContinuationPrimaryGroup,
                        event.event.frontier.group);
                } else {
                    ++controllers;
                    EXPECT_EQ(harken::FrontierOperationKind::Entry,
                        event.event.frontier.kind);
                    EXPECT_EQ(attempt->QueueCoordinators().queueContinuationPrimaryGroup,
                        event.event.frontier.group);
                }
            }
            EXPECT_EQ(1u, controllers);
            EXPECT_EQ(1u, starts);
            EXPECT_TRUE(groups[0].identity ==
                    attempt->QueueCoordinators().queueContinuationPrimaryGroup ||
                groups[1].identity ==
                    attempt->QueueCoordinators().queueContinuationPrimaryGroup);
            EXPECT_TRUE(engine->immediateActionLane.ReleaseCapture(
                attempt->lane.slot, bucket));
        }
        engine->nullBackend.Pump(1);
        harken::ImmediateLaneObservation observedLane{};
        ASSERT_TRUE(engine->immediateActionLane.Observe(attempt->lane, &observedLane));
        if (block == entryBlock || block == entryBlock + 1u) {
            harken::Plan03PageGroupView future{};
            ASSERT_TRUE(engine->timelinePool.ResolvePlan03GroupSliceProducer(
                futureGroup, &future));
            ASSERT_NE(nullptr, future.lease);
            EXPECT_EQ(block == entryBlock ? harken::AudioSliceState::Ready
                                         : harken::AudioSliceState::SliceApplied,
                      future.lease->Capture().state);
            EXPECT_EQ(block == entryBlock + 1u, observedLane.complete);
        }
        const auto* output = engine->nullBackend.LastBlock();
        float sum = 0.0f;
        for (std::uint32_t sample = 0; sample < kBlockFrames; ++sample)
            sum += output[sample];
        blockAverages[block] = sum / kBlockFrames;
    }
    const auto firstIndex = static_cast<std::size_t>(firstQuantum - rendered);
    EXPECT_GT(blockAverages[firstIndex], 0.1f);
    EXPECT_LT(blockAverages[firstIndex + 1u], -0.1f);
    EXPECT_LT(blockAverages[firstIndex + 2u], -0.1f);
}

static void CheckInitialQueueSourceWaitPcm(bool compositeCurrent, unsigned currentDelay = 0,
    bool shortCurrent = false, bool publishedWait = false, bool retainSuccessor = false, bool chain = false,
    bool sourceWait = true, bool refuseFollowing = false) {
    constexpr std::uint32_t block = 64;
    constexpr std::uint32_t rate = 48000;
    harkentest::EngineSession session(harkentest::MakeNullConfig(8, block, rate));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto& engine = *session.Engine();
    const unsigned currentDurationBlocks = currentDelay >= block ? 4u : 3u;
    const std::vector<float> first(chain ? 16u : shortCurrent ? block + (retainSuccessor ? 3u : 0u)
                                               : currentDurationBlocks * block, 0.25f);
    const std::vector<float> second(chain ? 23u : shortCurrent ? 1u : 2u * block, -0.125f);
    const auto firstPcm = harkentest::MonoDesc(first, rate);
    const auto secondPcm = harkentest::MonoDesc(second, rate);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &secondPcm));
    CanonicalActionWorld image(engine.registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
        engine.registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
    image.MakeImmediateSequenceQueuePlayAction();
    if (chain) {
        image.containers[2].queueCycle = harken::QueueCycleV1::Loop;
        image.containers[2].queueCycleCount = 2;
        image.world.identity.runtimeSemanticFingerprint = harken::ComputeCurrentWorldFingerprintV4(image.world);
    }
    if (compositeCurrent) {
        image.MakeFirstQueueChildCompositeTrack();
        image.trackPlacements[1].authoredStart =
            (currentDelay * INT64_C(1000000000) + rate - 1) / rate;
        image.track.scheduleSemanticFingerprint = harken::ComputeTrackScheduleFingerprintV1(image.track);
        image.queueChildren[0].timingHint = harken::MakeScheduleReferenceTimingHint(
            harken::PlayableKindV1::Track, image.track.rootDefinition.stableId,
            image.track.scheduleSemanticFingerprint);
        image.world.identity.runtimeSemanticFingerprint = harken::ComputeCurrentWorldFingerprintV4(image.world);
    }
    ASSERT_EQ(harken::WorldInstallStatus::Ok, harken::InstallContainerWorldV1(engine, image.world).status);
    VnBindingDesc binding{};
    binding.structSize = sizeof(binding);
    binding.variableId = image.variables[0].variableId;
    binding.targetScopeKind = VN_TARGET_SCOPE_VOICE;
    binding.targetId = harken::kTargetVoiceVolume;
    binding.curve.structSize = sizeof(binding.curve);
    binding.curve.pointCount = 2;
    binding.curve.points[0] = {0, 0};
    binding.curve.points[1] = {1, -12};
    binding.curve.handles[0] = harkentest::EndpointHandles(binding.curve.points[0], binding.curve.points[1]);
    const auto bindingId = harkentest::ObjectId(9062);
    ASSERT_EQ(VN_OK, Vn_RegisterBinding(bindingId, &binding));
    VnBindingAttachDesc attach{};
    attach.structSize = sizeof(attach);
    attach.scopeKind = VN_TARGET_SCOPE_VOICE;
    for (const auto sound : {CanonicalActionWorld::kFirstSound, CanonicalActionWorld::kSecondSound}) {
        attach.objectId = sound;
        ASSERT_EQ(VN_OK, Vn_AttachBinding(bindingId, &attach));
    }
    ASSERT_EQ(VN_OK, Vn_Update());
    engine.nullBackend.Pump(2);
    ASSERT_EQ(VN_OK, Vn_SetBusVolume(VN_BUS_MASTER, 1, 0));
    ASSERT_EQ(VN_OK, Vn_SetValue(binding.variableId, 0));
    const auto baseline = CaptureActionReclaimableOwners(engine);
    const auto bankBaseline = CaptureActionPreparationOwners(engine).occupiedQueueProgramBanks;
    struct FollowingRefusal {
        unsigned count = 0;
        bool prefixPublished = false;
    } refusal;
    if (refuseFollowing) {
        engine.timelineVoicePreparedContextForTest = &refusal;
        engine.timelineVoicePreparedHookForTest = [](harken::Engine& actual,
            const harken::EnginePreparedTimelineVoiceStart&, void* context) noexcept {
            auto& probe = *static_cast<FollowingRefusal*>(context);
            for (const auto& row : actual.playableServices) {
                if (!row.HasFeatureArrays() || row.QueuePayload().queuePreparingFollowing == nullptr) continue;
                if (++probe.count == 2u) {
                    const auto& predecessor = *row.QueuePayload().queuePreparingFollowing;
                    harken::DecisionCommittedSnapshot decision{};
                    probe.prefixPublished = predecessor.published && predecessor.chain.recorded &&
                        actual.decisions.CaptureCommitted(predecessor.chain.decision, &decision);
                    actual.forceTimelineVoiceCommitRollbackForTest = true;
                }
                break;
            }
        };
    }
    auto post = ValidPostDesc();
    post.actionId = image.actions[9].actionStableId;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&post.emitter));
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&post, &firing));
    struct VariableApplication {
        harken::Engine& engine;
        VnVariableId variable;
        harken::LogicCommitSequence sequence;
        std::uint64_t blockEndFrame = UINT64_MAX;
        ~VariableApplication() {
            engine.variableOutcomeSink = nullptr;
            engine.variableOutcomeSinkContext = nullptr;
        }
    } variableApplication{engine, binding.variableId, engine.logicCommits.Current() + 1u};
    engine.variableOutcomeSinkContext = &variableApplication;
    engine.variableOutcomeSink = [](void* context, const harken::VariableOutcomeRecord& record) noexcept {
        auto& observed = *static_cast<VariableApplication*>(context);
        if (record.outcome == harken::VariableOutcomeKind::Applied && record.variableId == observed.variable &&
            record.acceptedTicket.sequence == observed.sequence)
            observed.blockEndFrame = record.actualFrame;
    };
    ASSERT_EQ(VN_OK, Vn_SetValue(binding.variableId, 1));
    ASSERT_EQ(variableApplication.sequence, engine.logicCommits.Current());
    ASSERT_EQ(VN_OK, Vn_Update());
    if (publishedWait) engine.mixer.SetCurrentSliceScratchLimitForTest(0u);
    else engine.mixer.SetMaxCommandsPerQuantumForTest(0);
    bool publishedDuringWait = false;
    for (unsigned waiting = 0; waiting < (sourceWait ? 10u : 0u); ++waiting) {
        engine.nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        VnActionStepResult play{};
        play.structSize = sizeof(play);
        ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
        ASSERT_EQ(VN_OK, play.result) << "waiting block " << waiting;
        EXPECT_EQ(VN_ACTION_STEP_ACTIVE, play.state);
        EXPECT_NEAR(0, harkentest::Peak(engine.nullBackend.LastBlock(), 2 * block), 1e-7f);
        for (const auto& service : engine.playableServices) {
            if (!service.InvocationValid() || service.Invocation().actionFiring != firing) continue;
            harken::ImmediateLaneObservation lane{};
            if (engine.immediateActionLane.Observe(service.immediateLane, &lane) && lane.committed)
                publishedDuringWait = true;
        }
    }
    if (publishedWait) {
        engine.mixer.RestoreCurrentSliceScratchLimitForTest();
        ASSERT_TRUE(publishedDuringWait);
    } else engine.mixer.SetMaxCommandsPerQuantumForTest(engine.config.maxControlCommandsPerQuantum);
    const auto gainB = std::pow(10.0f, -12.0f / 20.0f);
    const auto masterGain = std::pow(10.0f, 1.0f / 20.0f);
    std::vector<float> recoveredPcm;
    const auto recoveryStartFrame = engine.mixer.BlocksRendered() * block;
    unsigned successorHolds = 0;
    std::uint64_t successorRecoveryFrame = UINT64_MAX;
    const harken::ImmediateLaneBucket* originalSuccessor = nullptr;
    harken::ImmediateLaneHandle originalSuccessorLane{};
    harken::Plan03GroupSliceIdentity originalSuccessorGroup{};
    harken::FrontierEntryReceiptRef originalSuccessorEntry{};
    harken::FrontierOwnerIdentity originalSuccessorOwner{};
    std::ostringstream recoveryTrace;
    const auto observeRecovery = [&]() {
        recoveryTrace << "\nsequence=" << engine.mixer.BlocksRendered()
            << " recreate=" << engine.runtimeRecreateRequired;
        for (const auto& service : engine.playableServices) {
            if (!service.InvocationValid() || service.Invocation().actionFiring != firing) continue;
            recoveryTrace << " service=" << service.identity.slot << " phase=" << static_cast<unsigned>(service.phase)
                << " start=" << service.startFrame << " completion=" << service.QueuePayload().queueCompletionFrame
                << " reason=" << static_cast<unsigned>(service.controlReason);
            harken::ImmediateLaneObservation lane{};
            if (engine.immediateActionLane.Observe(service.immediateLane, &lane))
                recoveryTrace << " committed=" << lane.committed << " applied=" << lane.applied
                    << " complete=" << lane.complete << " missed=" << lane.missed
                    << " refused=" << lane.protocolRefused;
        }
    };
    for (unsigned step = 0; step < 24; ++step) {
        ASSERT_EQ(VN_OK, Vn_Update());
        const harken::ImmediateLaneBucket* heldSuccessor = nullptr;
        std::uint32_t heldSuccessorSlot = UINT32_MAX;
        if (retainSuccessor && successorRecoveryFrame == UINT64_MAX) {
            for (const auto& service : engine.playableServices) {
                if (!service.InvocationValid() || service.Invocation().actionFiring != firing) continue;
                const auto* bucket = engine.immediateActionLane.CaptureDue(
                    service.immediateLane.slot, engine.mixer.BlocksRendered());
                if (bucket == nullptr) continue;
                const auto* groups = engine.immediateActionLane.Groups(service.immediateLane.slot, bucket);
                bool successor = false;
                for (std::uint32_t index = 0; groups != nullptr && index < bucket->groupCount; ++index) {
                    harken::Plan03PageGroupView group{};
                    ASSERT_TRUE(engine.timelinePool.ResolvePlan03GroupSliceRt(groups[index].identity, &group));
                    if (group.frontier == nullptr || !group.frontier->queueConditional.Valid()) continue;
                    ASSERT_FALSE(successor);
                    successor = true;
                    ASSERT_EQ(harken::FrontierGroupRole::EntryMember, group.frontier->role);
                    ASSERT_FALSE(group.frontier->canonicalInitialCompletion);
                    ASSERT_EQ(1u, group.memberCount);
                    ASSERT_EQ(0u, group.sourceControlCount);
                    if (originalSuccessor == nullptr) {
                        originalSuccessor = bucket;
                        originalSuccessorLane = service.immediateLane;
                        originalSuccessorGroup = group.identity;
                        originalSuccessorEntry = group.frontier->entry;
                        originalSuccessorOwner = group.frontier->operation.owner;
                    } else {
                        ASSERT_EQ(originalSuccessor, bucket);
                        ASSERT_EQ(originalSuccessorLane.slot, service.immediateLane.slot);
                        ASSERT_EQ(originalSuccessorLane.generation, service.immediateLane.generation);
                        ASSERT_EQ(originalSuccessorGroup, group.identity);
                        ASSERT_EQ(originalSuccessorEntry, group.frontier->entry);
                        ASSERT_EQ(originalSuccessorOwner, group.frontier->operation.owner);
                    }
                    std::uint64_t capturedQuantum = UINT64_MAX;
                    ASSERT_TRUE(engine.immediateActionLane.CapturedSourceWaitQuantum(
                        service.immediateLane.slot, bucket, &capturedQuantum));
                    ASSERT_EQ(engine.mixer.BlocksRendered(), capturedQuantum);
                }
                if (successor && successorHolds < 5u) {
                    heldSuccessor = bucket;
                    heldSuccessorSlot = service.immediateLane.slot;
                } else {
                    ASSERT_TRUE(engine.immediateActionLane.ReleaseCapture(service.immediateLane.slot, bucket));
                    if (successor) successorRecoveryFrame = engine.mixer.BlocksRendered() * block;
                }
                break;
            }
        }
        observeRecovery();
        const auto beforePump = engine.mixer.BlocksRendered();
        engine.nullBackend.Pump(1);
        ASSERT_EQ(beforePump + 1u, engine.mixer.BlocksRendered());
        if (heldSuccessor != nullptr) {
            ASSERT_TRUE(engine.immediateActionLane.SuspendCaptureForSourceWait(
                heldSuccessorSlot, heldSuccessor));
            ++successorHolds;
        }
        observeRecovery();
        const auto* output = engine.nullBackend.LastBlock();
        for (unsigned frame = 0; frame < block; ++frame)
            recoveredPcm.push_back(output[2 * frame]);
        ASSERT_EQ(VN_OK, Vn_Update());
        observeRecovery();
        VnActionStepResult play{};
        play.structSize = sizeof(play);
        ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
        ASSERT_EQ(VN_OK, play.result) << "recovery block " << step << recoveryTrace.str();
        if (play.state == VN_ACTION_STEP_SUCCEEDED) break;
    }
    if (chain) {
        ASSERT_NE(UINT64_MAX, variableApplication.blockEndFrame);
        ASSERT_GE(variableApplication.blockEndFrame, block);
        ASSERT_EQ(0u, variableApplication.blockEndFrame % block);
        // The outcome reports the one-based applied block's end. MixerLoop applies
        // its targets before rendering that block, subject to the initial read cut.
        const auto variableAppliedFrame = variableApplication.blockEndFrame - block;
        const auto firstOutput = std::find_if(recoveredPcm.begin(), recoveredPcm.end(),
            [](float sample) { return std::abs(sample) > 1e-7f; });
        ASSERT_NE(recoveredPcm.end(), firstOutput) << recoveryTrace.str();
        const auto onset = static_cast<std::size_t>(firstOutput - recoveredPcm.begin());
        const auto length = first.size() + second.size();
        recoveryTrace << " variableAppliedFrame=" << variableAppliedFrame
            << " onsetFrame=" << recoveryStartFrame + onset;
        ::testing::Test::RecordProperty("variable_applied_frame", std::to_string(variableAppliedFrame));
        ASSERT_GE(recoveredPcm.size(), onset + 2u * length) << recoveryTrace.str();
        for (std::size_t frame = 0; frame < recoveredPcm.size(); ++frame) {
            float expected = 0;
            if (frame >= onset && frame - onset < 2u * length) {
                const auto offset = frame - onset;
                expected = offset % length < first.size() ? 0.25f : -0.125f;
                const auto absoluteFrame = recoveryStartFrame + frame;
                const bool initialReadCut = offset < first.size() && absoluteFrame / block ==
                    (recoveryStartFrame + onset) / block;
                if (!initialReadCut && absoluteFrame >= variableAppliedFrame) expected *= gainB;
            }
            EXPECT_NEAR(expected * masterGain, recoveredPcm[frame], 1e-6f)
                << "chain frame " << frame << recoveryTrace.str();
        }
    } else if (retainSuccessor) {
        ASSERT_EQ(5u, successorHolds);
        ASSERT_NE(UINT64_MAX, successorRecoveryFrame);
        const auto firstOutput = std::find_if(recoveredPcm.begin(), recoveredPcm.end(),
            [](float sample) { return std::abs(sample) > 1e-7f; });
        ASSERT_NE(recoveredPcm.end(), firstOutput) << recoveryTrace.str();
        const auto onset = static_cast<std::size_t>(firstOutput - recoveredPcm.begin());
        const auto successorOffset = successorRecoveryFrame - recoveryStartFrame;
        ASSERT_GE(recoveredPcm.size(), successorOffset + second.size());
        EXPECT_GT(successorOffset, onset + first.size());
        for (std::size_t frame = 0; frame < recoveredPcm.size(); ++frame) {
            float expected = 0;
            if (frame >= onset && frame - onset < first.size())
                expected += 0.25f * ((recoveryStartFrame + frame) / block ==
                    (recoveryStartFrame + onset) / block ? 1.0f : gainB);
            if (compositeCurrent && frame >= onset + currentDelay &&
                frame - onset - currentDelay < second.size())
                expected -= 0.125f * ((recoveryStartFrame + frame) / block ==
                    (recoveryStartFrame + onset + currentDelay) / block ? 1.0f : gainB);
            if (frame >= successorOffset && frame - successorOffset < second.size())
                expected -= 0.125f * gainB;
            EXPECT_NEAR(expected * masterGain, recoveredPcm[frame], 1e-6f)
                << "recovery frame " << frame << recoveryTrace.str();
        }
        ::testing::Test::RecordProperty("successor_recovery_frame", std::to_string(successorRecoveryFrame));
    } else if (shortCurrent) {
        std::vector<std::size_t> positive, negative;
        for (std::size_t frame = 0; frame < recoveredPcm.size(); ++frame) {
            if (recoveredPcm[frame] > 1e-7f) positive.push_back(frame);
            else if (recoveredPcm[frame] < -1e-7f) negative.push_back(frame);
        }
        ::testing::Test::RecordProperty("positive_sample_count", static_cast<int>(positive.size()));
        ::testing::Test::RecordProperty("negative_sample_count", static_cast<int>(negative.size()));
        ASSERT_EQ(block, positive.size()) << recoveryTrace.str();
        ASSERT_EQ(2u, negative.size()) << recoveryTrace.str();
        ::testing::Test::RecordProperty("current_start_frame",
            std::to_string(recoveryStartFrame + positive.front()));
        ::testing::Test::RecordProperty("delayed_current_start_frame",
            std::to_string(recoveryStartFrame + negative[0]));
        ::testing::Test::RecordProperty("successor_start_frame",
            std::to_string(recoveryStartFrame + negative[1]));
        EXPECT_EQ(positive.front() + currentDelay, negative[0]);
        EXPECT_EQ(negative[0] + 1u, negative[1]);
        EXPECT_EQ((recoveryStartFrame + negative[0]) / block,
            (recoveryStartFrame + negative[1]) / block);
        for (unsigned frame = 0; frame < block; ++frame) {
            EXPECT_EQ(positive.front() + frame, positive[frame]);
            EXPECT_NEAR(0.25f * masterGain,
                recoveredPcm[positive[frame]], 1e-6f);
        }
        EXPECT_NEAR(-0.125f * masterGain,
            recoveredPcm[negative[0]], 1e-6f);
        EXPECT_NEAR(-0.125f * gainB * masterGain,
            recoveredPcm[negative[1]], 1e-6f);
    } else {
        const auto firstOutput = std::find_if(recoveredPcm.begin(), recoveredPcm.end(),
            [](float sample) { return std::abs(sample) > 1e-7f; });
        ASSERT_NE(recoveredPcm.end(), firstOutput) << recoveryTrace.str();
        const auto onset = static_cast<std::size_t>(firstOutput - recoveredPcm.begin());
        const auto successorOffset = std::max(first.size(), compositeCurrent ? currentDelay + second.size() : 0u);
        ASSERT_GE(recoveredPcm.size(), onset + successorOffset + second.size()) << recoveryTrace.str();
        for (std::size_t frame = 0; frame < recoveredPcm.size(); ++frame) {
            float expected = 0;
            if (frame >= onset) {
                const auto relative = frame - onset;
                if (relative < first.size())
                    expected += 0.25f * ((recoveryStartFrame + frame) / block ==
                        (recoveryStartFrame + onset) / block ? 1.0f : gainB);
                if (compositeCurrent && relative >= currentDelay && relative - currentDelay < second.size())
                    expected -= 0.125f * ((recoveryStartFrame + frame) / block ==
                        (recoveryStartFrame + onset + currentDelay) / block ? 1.0f : gainB);
                if (relative >= successorOffset && relative - successorOffset < second.size())
                    expected -= 0.125f * gainB;
            }
            EXPECT_NEAR(expected * masterGain, recoveredPcm[frame], 1e-6f)
                << "recovery frame " << frame << " onset " << onset << recoveryTrace.str();
        }
    }
    VnActionStepResult play{};
    play.structSize = sizeof(play);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
    EXPECT_EQ(VN_ACTION_STEP_SUCCEEDED, play.state);
    EXPECT_EQ(0u, engine.voices.ActiveCount());
    EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    if (chain) {
        for (unsigned step = 0; step < 128 && (CaptureActionReclaimableOwners(engine) != baseline ||
                CaptureActionPreparationOwners(engine).occupiedQueueProgramBanks != bankBaseline); ++step) {
            engine.nullBackend.Pump(1);
            ASSERT_EQ(VN_OK, Vn_Update());
        }
        EXPECT_EQ(baseline, CaptureActionReclaimableOwners(engine));
        EXPECT_EQ(bankBaseline, CaptureActionPreparationOwners(engine).occupiedQueueProgramBanks);
    }
    if (refuseFollowing) {
        EXPECT_GE(refusal.count, 2u);
        EXPECT_TRUE(refusal.prefixPublished);
        EXPECT_FALSE(engine.forceTimelineVoiceCommitRollbackForTest);
        EXPECT_FALSE(engine.runtimeRecreateRequired);
        engine.timelineVoicePreparedHookForTest = nullptr;
        engine.timelineVoicePreparedContextForTest = nullptr;
    }
}

