static void CheckShortQueueChainControl(bool reset, bool audioAhead) {
    constexpr std::uint32_t block = 64;
    harkentest::EngineSession session(harkentest::MakeNullConfig(8, block, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto& engine = *session.Engine();
    const std::vector<float> first(16, 0.25f), second(23, -0.125f);
    const auto firstPcm = harkentest::MonoDesc(first, 48000);
    const auto secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &secondPcm));
    CanonicalActionWorld image(engine.registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
        engine.registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
    image.MakeImmediateSequenceQueuePlayAction();
    image.containers[2].queueCycle = harken::QueueCycleV1::Loop;
    image.containers[2].queueCycleCount = 3;
    image.world.identity.runtimeSemanticFingerprint = harken::ComputeCurrentWorldFingerprintV4(image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok, harken::InstallContainerWorldV1(engine, image.world).status);
    ASSERT_EQ(VN_OK, Vn_SetBusVolume(VN_BUS_MASTER, 0, 0));
    ASSERT_EQ(VN_OK, Vn_Update());
    engine.nullBackend.Pump(2);
    auto post = ValidPostDesc();
    post.actionId = image.actions[9].actionStableId;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&post.emitter));
    const auto baseline = CaptureActionReclaimableOwners(engine);
    const auto bankBaseline = CaptureActionPreparationOwners(engine).occupiedQueueProgramBanks;
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&post, &firing));
    harken::EnginePlayableServiceRow* row = nullptr;
    std::vector<harken::TimelineArmToken> oldStarts;
    for (unsigned attempt = 0; attempt < 16; ++attempt) {
        ASSERT_EQ(VN_OK, Vn_Update());
        for (auto& candidate : engine.playableServices) {
            if (candidate.InvocationValid() && candidate.Invocation().actionFiring == firing && candidate.queueMode) {
                row = &candidate;
                break;
            }
        }
        if (row != nullptr && row->HasFeatureArrays() && row->QueueFiling().queueSuccessorProgramBank != nullptr) {
            oldStarts.clear();
            for (auto* bank = row->QueueFiling().queueSuccessorProgramBank; bank != nullptr; bank = bank->chain.following)
                oldStarts.push_back(bank->chain.arm);
            if (oldStarts.size() >= 3u) break;
        }
        engine.nullBackend.Pump(1);
        EXPECT_NEAR(0, harkentest::Peak(engine.nullBackend.LastBlock(), 2 * block), 1e-7f);
    }
    ASSERT_NE(nullptr, row);
    ASSERT_GE(oldStarts.size(), 3u);
    ASSERT_TRUE(row->queueTimingPending);
    const auto root = row->rootInstance;
    if (audioAhead) {
        bool started = false;
        for (unsigned attempt = 0; attempt < 16 && !started; ++attempt) {
            engine.nullBackend.Pump(1);
            const auto* pcm = engine.nullBackend.LastBlock();
            unsigned onset = 0;
            while (onset < block && std::abs(pcm[2 * onset]) <= 1e-7f) ++onset;
            started = onset != block;
            if (started) {
                ASSERT_LE(onset + 2u * first.size() + second.size(), block);
                for (unsigned frame = onset; frame < block; ++frame)
                    EXPECT_NEAR((frame - onset) % 39u < 16u ? 0.25f : -0.125f, pcm[2 * frame], 1e-6f);
            } else ASSERT_EQ(VN_OK, Vn_Update());
        }
        ASSERT_TRUE(started);
        unsigned startedFollowing = 0;
        for (const auto arm : oldStarts) {
            harken::TimelineArmObservation observed{};
            if (engine.timelineArms.Observe(arm, &observed) && observed.startedBlockSequence != 0) ++startedFollowing;
        }
        ASSERT_GE(startedFollowing, 2u);
    }
    const auto controlSequence = engine.mixer.BlocksRendered();
    VnActionFiringHandle resetFiring = 0;
    if (reset) {
        auto resetPost = post;
        resetPost.actionId = harkentest::ObjectId(49);
        ASSERT_EQ(VN_OK, Vn_PostAction(&resetPost, &resetFiring));
        EXPECT_EQ(root, row->rootInstance);
    } else ASSERT_EQ(VN_OK, Vn_StopActionFiring(firing, 0));
    VnActionStepResult play{};
    play.structSize = sizeof(play);
    VnActionFiringInfo firingInfo{};
    firingInfo.structSize = sizeof(firingInfo);
    bool boundReplacementChain = false;
    for (unsigned step = 0; step < 128; ++step) {
        ASSERT_EQ(VN_OK, Vn_Update());
        if (reset && !audioAhead && row->HasFeatureArrays() && row->QueueFiling().queueSuccessorProgramBank != nullptr) {
            const auto& selected = engine.originalQueueReplacementHolders[row->queueInstance.slot];
            if (step == 0) {
                ASSERT_EQ(harken::EnginePlayableStartPhase::Filed, row->phase);
                ASSERT_EQ(harken::Engine::OriginalQueueReplacementHolder::Phase::Selected, selected.phase);
                ASSERT_FALSE(selected.sourceClockBound);
                harken::TimelineArmObservation pending{};
                ASSERT_TRUE(engine.timelineArms.Observe(row->QueueFiling().queueSuccessorArm, &pending));
                ASSERT_EQ(harken::ArmState::PendingApply, pending.state);
                EXPECT_EQ(nullptr, row->QueueFiling().queueSuccessorProgramBank->chain.following);
            }
            if (selected.sourceClockBound && row->QueueFiling().queueSuccessorProgramBank->chain.following != nullptr) {
                boundReplacementChain = true;
                const auto* bank = row->QueueFiling().queueSuccessorProgramBank;
                for (; bank->chain.following != nullptr; bank = bank->chain.following) {
                    const auto& next = bank->chain.following->chain;
                    if (harken::IsBoundKnownCompletionPredicate(next.completion))
                        EXPECT_EQ(bank->chain.completion.absoluteLogicalCompleteFrame,
                            next.completion.absoluteLogicalStartFrame);
                }
            }
        }
        engine.nullBackend.Pump(1);
        for (const auto arm : oldStarts) {
            harken::TimelineArmObservation observed{};
            if (engine.timelineArms.Observe(arm, &observed))
                EXPECT_LE(observed.startedBlockSequence, controlSequence);
        }
        ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
        ASSERT_EQ(VN_OK, play.result);
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &firingInfo));
        if (firingInfo.state == VN_ACTION_FIRING_TERMINAL_RETAINED) break;
    }
    if (reset && !audioAhead) EXPECT_TRUE(boundReplacementChain);
    EXPECT_EQ(reset ? VN_ACTION_STEP_SUCCEEDED : VN_ACTION_STEP_CANCELLED, play.state);
    EXPECT_FALSE(engine.runtimeRecreateRequired);
    ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, firingInfo.state);
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    if (resetFiring != 0) ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(resetFiring));
    for (unsigned step = 0; step < 128 && (CaptureActionReclaimableOwners(engine) != baseline ||
            CaptureActionPreparationOwners(engine).occupiedQueueProgramBanks != bankBaseline); ++step) {
        engine.nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
    }
    ASSERT_EQ(baseline, CaptureActionReclaimableOwners(engine));
    ASSERT_EQ(bankBaseline, CaptureActionPreparationOwners(engine).occupiedQueueProgramBanks);

    ASSERT_EQ(VN_OK, Vn_PostAction(&post, &firing));
    std::vector<float> replay;
    for (unsigned step = 0; step < 128; ++step) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine.nullBackend.Pump(1);
        for (unsigned frame = 0; frame < block; ++frame) replay.push_back(engine.nullBackend.LastBlock()[2 * frame]);
        ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
        ASSERT_EQ(VN_OK, play.result);
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &firingInfo));
        if (firingInfo.state == VN_ACTION_FIRING_TERMINAL_RETAINED) break;
    }
    EXPECT_EQ(VN_ACTION_STEP_SUCCEEDED, play.state);
    ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, firingInfo.state);
    const auto firstOutput = std::find_if(replay.begin(), replay.end(), [](float sample) { return std::abs(sample) > 1e-7f; });
    ASSERT_NE(replay.end(), firstOutput);
    const auto onset = static_cast<std::size_t>(firstOutput - replay.begin());
    ASSERT_GE(replay.size(), onset + 117u);
    for (std::size_t frame = 0; frame < replay.size(); ++frame) {
        const auto expected = frame < onset || frame - onset >= 117u ? 0.0f
            : (frame - onset) % 39u < 16u ? 0.25f : -0.125f;
        EXPECT_NEAR(expected, replay[frame], 1e-6f) << "replay frame " << frame;
    }
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    for (unsigned step = 0; step < 128 && (CaptureActionReclaimableOwners(engine) != baseline ||
            CaptureActionPreparationOwners(engine).occupiedQueueProgramBanks != bankBaseline); ++step) {
        engine.nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
    }
    EXPECT_EQ(baseline, CaptureActionReclaimableOwners(engine));
    EXPECT_EQ(bankBaseline, CaptureActionPreparationOwners(engine).occupiedQueueProgramBanks);
}

TEST(ActionFiringApi, ShortQueueChainStopAndResetRetirePublishedSuffixAndReplay) {
    for (const bool reset : {false, true}) {
        for (const bool audioAhead : {false, true}) {
            SCOPED_TRACE(::testing::Message() << "reset=" << reset << " audioAhead=" << audioAhead);
            CheckShortQueueChainControl(reset, audioAhead);
        }
    }
}

TEST(ActionFiringApi, InitialQueueArenaRefusalLeavesNoPartialSoundAndRecovers) {
    (void)Vn_Term();
    constexpr std::uint32_t kBlockFrames = 64;
    harkentest::EngineSession session(
        harkentest::MakeNullConfig(8, kBlockFrames, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    std::vector<float> first(kBlockFrames, 0.25f);
    std::vector<float> second(2 * kBlockFrames, -0.25f);
    const auto firstPcm = harkentest::MonoDesc(first, 48000);
    const auto secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound,
                                   &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound,
                                   &secondPcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
    image.MakeImmediateSequenceQueuePlayAction();
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);
    VnMonitorSessionDesc monitorDesc{};
    monitorDesc.structSize = sizeof(monitorDesc);
    monitorDesc.requestedStreamKindMask = VN_MONITOR_STREAM_EVENT;
    monitorDesc.requestedPermissionMask = VN_MONITOR_PERM_OBSERVE_EVENTS;
    monitorDesc.consumerQueueBytes = 65536;
    VnMonitorSessionHandle monitorSession = 0;
    ASSERT_EQ(VN_OK, Vn_MonitorOpenSession(&monitorDesc, &monitorSession));
    VnPostActionDesc post = ValidPostDesc();
    post.actionId = image.actions[9].actionStableId;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&post.emitter));
    const auto ownersBeforePost = CaptureActionReclaimableOwners(*engine);
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&post, &firing));
    ASSERT_NE(0u, firing);
    std::array<harken::Plan03ImmediateLaneGroupDescriptor, 4> groups{};
    ASSERT_EQ(4u, engine->timelinePool.CaptureImmediateLaneCohortGroups(
        firing, groups.data(), groups.size()));
    engine->nullBackend.Pump(1);
    ASSERT_EQ(VN_OK, Vn_Update());

    const auto attempt = std::find_if(
        engine->immediateEntryAttempts.data(),
        engine->immediateEntryAttempts.data() + engine->immediateEntryAttempts.size(),
        [firing](const auto& candidate) {
            return candidate.active && candidate.root == firing;
        });
    ASSERT_NE(engine->immediateEntryAttempts.data() +
                  engine->immediateEntryAttempts.size(), attempt);
    ASSERT_TRUE(attempt->QueueCoordinators().initialQueueCoordinator.Valid());
    ASSERT_TRUE(attempt->QueueCoordinators().queueContinuationCoordinator.Valid());
    ASSERT_TRUE(attempt->lane.Valid());
    for (const auto& group : groups) ASSERT_TRUE(group.identity.Exact());
    const auto continuationQueue = attempt->queueContinuationQueue;
    harken::QueueInstanceSnapshot queueBeforeRefusal{};
    ASSERT_TRUE(engine->queueInstances.Capture(continuationQueue,
        &queueBeforeRefusal));
    ASSERT_NE(0u, queueBeforeRefusal.pendingVersion);
    const auto lane = attempt->lane;
    const auto firstQuantum = attempt->entryQuantum;
    ASSERT_GT(firstQuantum, engine->mixer.BlocksRendered());
    while (engine->mixer.BlocksRendered() < firstQuantum) {
        engine->nullBackend.Pump(1);
        const float* output = engine->nullBackend.LastBlock();
        EXPECT_TRUE(std::all_of(output, output + kBlockFrames,
            [](float sample) { return std::abs(sample) < 0.001f; }));
    }
    const auto required = engine->voices.ScratchBytesBeforeTimeline(kBlockFrames);
    ASSERT_GT(required, 0u);
    const std::uint64_t busPlaneBytes = 2u * kBlockFrames * sizeof(float);
    ASSERT_LE(busPlaneBytes + required, UINT32_MAX);
    const auto frontier = engine->timelinePool.ConsumerFrontier().load();
    const auto refusals =
        engine->timelineExecutor.Stats().renderUnavailableDeferrals;
    const auto overflows = engine->mixer.Arena().OverflowCount();
    struct ArenaAdmissionProbe {
        harken::Engine* engine;
        std::uint64_t expectedQuantum;
        std::uint32_t capacity = 0;
        std::uint32_t used = 0;
        std::uint64_t overflows = 0;
        bool seen = false;
    } probe{engine, firstQuantum};
    engine->mixer.SetCurrentSliceFrontierHookForTest(
        [](void* context, harken::MixerLoop::CurrentSliceHookPhaseForTest phase,
           std::uint64_t quantum, std::size_t, std::uint32_t,
           harken::TimelinePagePrefixStopReason) noexcept {
            auto& snapshot = *static_cast<ArenaAdmissionProbe*>(context);
            if (phase != harken::MixerLoop::CurrentSliceHookPhaseForTest::
                    AfterStageBeforeExecute ||
                quantum != snapshot.expectedQuantum) return;
            snapshot.capacity = snapshot.engine->mixer.Arena().CapacityBytes();
            snapshot.used = snapshot.engine->mixer.Arena().UsedBytes();
            snapshot.overflows = snapshot.engine->mixer.Arena().OverflowCount();
            snapshot.seen = true;
        }, &probe);
    engine->mixer.ArenaForTests().SetCapacityForTests(
        static_cast<std::uint32_t>(busPlaneBytes + required - 1u));
#if defined(_DEBUG) && defined(_MSC_VER)
    ASSERT_TRUE(harken::memguard::IsArmed());
#endif
    const auto allocationHitsBefore = harken::memguard::HitCount();
    engine->nullBackend.Pump(1);
    const auto allocationHitsAfter = harken::memguard::HitCount();
    engine->mixer.SetCurrentSliceFrontierHookForTest(nullptr, nullptr);
    EXPECT_EQ(allocationHitsBefore, allocationHitsAfter);
    ASSERT_TRUE(probe.seen);
    EXPECT_EQ(busPlaneBytes, probe.used);
    EXPECT_EQ(required - 1u, probe.capacity - probe.used);
    EXPECT_EQ(overflows, probe.overflows);
    EXPECT_EQ(frontier, engine->timelinePool.ConsumerFrontier().load());
    EXPECT_EQ(refusals + 1u,
        engine->timelineExecutor.Stats().renderUnavailableDeferrals);
    const float* refusedOutput = engine->nullBackend.LastBlock();
    EXPECT_TRUE(std::all_of(refusedOutput, refusedOutput + kBlockFrames,
        [](float sample) { return std::abs(sample) < 0.001f; }));
    for (const auto& group : groups) {
        harken::Plan03PageGroupView view{};
        ASSERT_TRUE(engine->timelinePool.ResolvePlan03GroupSliceProducer(
            group.identity, &view));
        ASSERT_NE(nullptr, view.lease);
        EXPECT_NE(harken::AudioSliceState::SliceApplied,
                  view.lease->Capture().state);
    }
    engine->mixer.ArenaForTests().RestoreCapacityForTests();

    const auto hitsBeforeMiss = harken::memguard::HitCount();
    engine->nullBackend.Pump(1);
    EXPECT_EQ(hitsBeforeMiss, harken::memguard::HitCount());
    harken::ImmediateLaneObservation missedLane{};
    ASSERT_TRUE(engine->immediateActionLane.Observe(lane, &missedLane));
    EXPECT_TRUE(missedLane.missed);
    EXPECT_TRUE(std::all_of(engine->nullBackend.LastBlock(),
        engine->nullBackend.LastBlock() + kBlockFrames,
        [](float sample) { return std::abs(sample) < 0.001f; }));
    VnActionFiringInfo refusedInfo{};
    refusedInfo.structSize = sizeof(refusedInfo);
    bool lateSound = false;
    for (std::uint32_t block = 0; block < 64; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        const auto hitsBefore = harken::memguard::HitCount();
        engine->nullBackend.Pump(1);
        const auto hitsAfter = harken::memguard::HitCount();
        EXPECT_EQ(hitsBefore, hitsAfter);
        const float* output = engine->nullBackend.LastBlock();
        lateSound = lateSound || std::any_of(output, output + kBlockFrames,
            [](float sample) { return std::abs(sample) > 0.01f; });
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &refusedInfo));
        if (refusedInfo.state == VN_ACTION_FIRING_TERMINAL_RETAINED) break;
    }
    EXPECT_FALSE(lateSound);
    harken::monitor::StopDrainForTests();
    harken::monitor::DrainOnceForTests();
    harken::monitor::StartDrainForTests();
    std::array<std::uint8_t, 65536> monitorBuffer{};
    VnMonitorPollDesc monitorPoll{};
    monitorPoll.structSize = sizeof(monitorPoll);
    monitorPoll.buffer = monitorBuffer.data();
    monitorPoll.bufferBytes = monitorBuffer.size();
    VnMonitorPollResult monitorResult{};
    monitorResult.structSize = sizeof(monitorResult);
    ASSERT_EQ(VN_OK, Vn_MonitorPoll(monitorSession, &monitorPoll,
                                   &monitorResult));
    const auto read32 = [](const std::uint8_t* bytes) {
        return static_cast<std::uint32_t>(bytes[0]) |
            (static_cast<std::uint32_t>(bytes[1]) << 8) |
            (static_cast<std::uint32_t>(bytes[2]) << 16) |
            (static_cast<std::uint32_t>(bytes[3]) << 24);
    };
    const auto read64 = [&](const std::uint8_t* bytes) {
        return static_cast<std::uint64_t>(read32(bytes)) |
            (static_cast<std::uint64_t>(read32(bytes + 4)) << 32);
    };
    const std::uint64_t queueHandle =
        (static_cast<std::uint64_t>(continuationQueue.generation) << 32) |
        continuationQueue.slot;
    bool observedQueueCapacity = false;
    for (std::uint64_t offset = 0;
         offset + VN_MONITOR_RECORD_ENVELOPE_PACKED_BYTES <=
             monitorResult.bytesWritten;) {
        const auto* record = monitorBuffer.data() + offset;
        const auto recordBytes = read64(record + 16);
        ASSERT_GE(recordBytes, VN_MONITOR_RECORD_ENVELOPE_PACKED_BYTES);
        ASSERT_LE(offset + recordBytes, monitorResult.bytesWritten);
        if (read32(record) == VN_MONITOR_RECORD_EVENT &&
            read32(record + 156) == VN_MONITOR_ENTITY_QUEUE &&
            read64(record + 200) == queueHandle &&
            read64(record + 208) == continuationQueue.generation &&
            recordBytes >= VN_MONITOR_RECORD_ENVELOPE_PACKED_BYTES +
                               sizeof(VnMonitorEventPayload)) {
            VnMonitorEventPayload payload{};
            std::memcpy(&payload,
                record + VN_MONITOR_RECORD_ENVELOPE_PACKED_BYTES,
                sizeof(payload));
            observedQueueCapacity = observedQueueCapacity ||
                payload.eventClass == VN_MONITOR_EVENT_REJECT &&
                payload.reason ==
                    static_cast<std::uint32_t>(harken::QueueFailureReason::Capacity);
        }
        offset += recordBytes;
    }
    EXPECT_TRUE(observedQueueCapacity);
    EXPECT_EQ(VN_OK, Vn_MonitorCloseSession(monitorSession));
    EXPECT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, refusedInfo.state);
    EXPECT_EQ(VN_ACTION_OUTCOME_FAILED, refusedInfo.outcome);
    EXPECT_EQ(VN_ACTION_TERMINAL_CAPACITY, refusedInfo.terminalReason);
    EXPECT_EQ(0u, refusedInfo.livePlayableCount);
    EXPECT_EQ(0u, engine->queueInstances.LiveCount());
    EXPECT_EQ(0u, engine->voices.ActiveCount());
    EXPECT_FALSE(engine->runtimeRecreateRequired);
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    for (std::uint32_t block = 0; block < 64; ++block) {
        if (CaptureActionReclaimableOwners(*engine) == ownersBeforePost) break;
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
    }
    EXPECT_EQ(ownersBeforePost, CaptureActionReclaimableOwners(*engine));
    EXPECT_FALSE(attempt->active);
    VnActionFiringHandle replay = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&post, &replay));
    ASSERT_NE(0u, replay);
    ASSERT_NE(firing, replay);
    engine->nullBackend.Pump(1);
    ASSERT_EQ(VN_OK, Vn_Update());
    bool heardFirst = false;
    bool heardSecond = false;
    for (std::uint32_t block = 0; block < 16 && !heardSecond; ++block) {
        const auto hitsBefore = harken::memguard::HitCount();
        engine->nullBackend.Pump(1);
        const auto hitsAfter = harken::memguard::HitCount();
        EXPECT_EQ(hitsBefore, hitsAfter);
        const float* output = engine->nullBackend.LastBlock();
        heardFirst = heardFirst || std::any_of(output, output + kBlockFrames,
            [](float sample) { return sample > 0.01f; });
        heardSecond = heardSecond || std::any_of(output, output + kBlockFrames,
            [](float sample) { return sample < -0.01f; });
    }
    EXPECT_TRUE(heardFirst);
    EXPECT_TRUE(heardSecond);
    VnActionFiringInfo replayInfo{};
    replayInfo.structSize = sizeof(replayInfo);
    for (std::uint32_t block = 0; block < 64; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(replay, &replayInfo));
        if (replayInfo.state == VN_ACTION_FIRING_TERMINAL_RETAINED) break;
        engine->nullBackend.Pump(1);
    }
    EXPECT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, replayInfo.state);
    EXPECT_EQ(VN_ACTION_OUTCOME_SUCCEEDED, replayInfo.outcome);
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(replay));
    for (std::uint32_t block = 0; block < 64; ++block) {
        if (CaptureActionReclaimableOwners(*engine) == ownersBeforePost) break;
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
    }
    EXPECT_EQ(ownersBeforePost, CaptureActionReclaimableOwners(*engine));
}

TEST(ActionFiringApi, InitialQueueContinuationArenaRefusalKeepsFirstSoundAndFails) {
    (void)Vn_Term();
    constexpr std::uint32_t kBlockFrames = 64;
    harkentest::EngineSession session(
        harkentest::MakeNullConfig(8, kBlockFrames, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    std::vector<float> first(kBlockFrames, 0.25f);
    std::vector<float> second(2 * kBlockFrames, -0.25f);
    const auto firstPcm = harkentest::MonoDesc(first, 48000);
    const auto secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound,
                                   &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound,
                                   &secondPcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
    image.MakeImmediateSequenceQueuePlayAction();
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);
    VnMonitorSessionDesc monitorDesc{};
    monitorDesc.structSize = sizeof(monitorDesc);
    monitorDesc.requestedStreamKindMask = VN_MONITOR_STREAM_EVENT;
    monitorDesc.requestedPermissionMask = VN_MONITOR_PERM_OBSERVE_EVENTS;
    monitorDesc.consumerQueueBytes = 65536;
    VnMonitorSessionHandle monitorSession = 0;
    ASSERT_EQ(VN_OK, Vn_MonitorOpenSession(&monitorDesc, &monitorSession));
    VnPostActionDesc post = ValidPostDesc();
    post.actionId = image.actions[9].actionStableId;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&post.emitter));
    const auto ownersBeforePost = CaptureActionReclaimableOwners(*engine);
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&post, &firing));
    engine->nullBackend.Pump(1);
    ASSERT_EQ(VN_OK, Vn_Update());
    const auto attempt = std::find_if(
        engine->immediateEntryAttempts.data(),
        engine->immediateEntryAttempts.data() + engine->immediateEntryAttempts.size(),
        [firing](const auto& candidate) {
            return candidate.active && candidate.root == firing;
        });
    ASSERT_NE(engine->immediateEntryAttempts.data() +
                  engine->immediateEntryAttempts.size(), attempt);
    ASSERT_TRUE(attempt->QueueCoordinators().initialQueueCoordinator.Valid());
    ASSERT_TRUE(attempt->QueueCoordinators().queueContinuationCoordinator.Valid());
    const auto firstQuantum = attempt->entryQuantum;
    const auto continuationQueue = attempt->queueContinuationQueue;
    const auto continuationCoordinator = attempt->QueueCoordinators().queueContinuationCoordinator;
    const auto continuationDescriptor = attempt->QueueCoordinators().queueContinuationDescriptor;
    const auto initialCoordinator = attempt->QueueCoordinators().initialQueueCoordinator;
    const auto initialDescriptor = attempt->QueueCoordinators().initialQueueDescriptor;
    harken::QueueInstanceSnapshot queueBefore{};
    ASSERT_TRUE(engine->queueInstances.Capture(continuationQueue, &queueBefore));
    ASSERT_NE(0u, queueBefore.pendingVersion);
    while (engine->mixer.BlocksRendered() < firstQuantum)
        engine->nullBackend.Pump(1);
    const auto* initialActivation =
        engine->decisions.ResolveFrontierActivation(initialCoordinator);
    const auto* continuationActivation =
        engine->decisions.ResolveFrontierActivation(continuationCoordinator);
    ASSERT_NE(nullptr, initialActivation);
    ASSERT_NE(nullptr, continuationActivation);
    harken::DecisionFuturePin continuationReceiptPin;
    ASSERT_TRUE(engine->decisions.AcquireFuturePin(
        continuationCoordinator, &continuationReceiptPin));
    engine->nullBackend.Pump(1);
    const auto* firstOutput = engine->nullBackend.LastBlock();
    EXPECT_TRUE(std::any_of(firstOutput, firstOutput + kBlockFrames,
        [](float sample) { return sample > 0.1f; }));
    harken::FrontierActivationReceipt firstReceipt{};
    ASSERT_EQ(harken::FrontierReceiptRead::Ready,
        initialActivation->Read(initialDescriptor.entry,
            engine->mixer.BlocksRendered(), &firstReceipt));
    EXPECT_EQ(harken::FrontierReceiptOutcome::Applied, firstReceipt.outcome);
    const auto required = engine->voices.ScratchBytesBeforeTimeline(kBlockFrames);
    const std::uint32_t busPlaneBytes = 2u * kBlockFrames * sizeof(float);
    ASSERT_GT(required, 0u);
    const auto frontier = engine->timelinePool.ConsumerFrontier().load();
    const auto refusals =
        engine->timelineExecutor.Stats().renderUnavailableDeferrals;
    const auto overflows = engine->mixer.Arena().OverflowCount();
    engine->mixer.ArenaForTests().SetCapacityForTests(
        busPlaneBytes + required - 1u);
#if defined(_DEBUG) && defined(_MSC_VER)
    ASSERT_TRUE(harken::memguard::IsArmed());
#endif
    const auto allocationHitsBefore = harken::memguard::HitCount();
    engine->nullBackend.Pump(1);
    EXPECT_EQ(allocationHitsBefore, harken::memguard::HitCount());
    engine->mixer.ArenaForTests().RestoreCapacityForTests();
    EXPECT_EQ(overflows, engine->mixer.Arena().OverflowCount());
    EXPECT_EQ(frontier, engine->timelinePool.ConsumerFrontier().load());
    EXPECT_EQ(refusals + 1u,
        engine->timelineExecutor.Stats().renderUnavailableDeferrals);
    EXPECT_TRUE(std::all_of(engine->nullBackend.LastBlock(),
        engine->nullBackend.LastBlock() + kBlockFrames,
        [](float sample) { return std::abs(sample) < 0.001f; }));
    engine->nullBackend.Pump(1);
    harken::ImmediateLaneObservation missedLane{};
    ASSERT_TRUE(engine->immediateActionLane.Observe(attempt->lane, &missedLane));
    EXPECT_TRUE(missedLane.missed);
    EXPECT_TRUE(missedLane.arenaCapacityMissed);
    harken::FrontierActivationReceipt secondReceipt{};
    bool secondReceiptObserved = false;
    bool lateSecondSound = false;
    VnActionFiringInfo refusedInfo{};
    refusedInfo.structSize = sizeof(refusedInfo);
    for (std::uint32_t block = 0; block < 64; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        if (!secondReceiptObserved) {
            const auto* actual = engine->decisions.ResolveFrontierActivation(
                continuationCoordinator);
            ASSERT_NE(nullptr, actual);
            const auto read = actual->Read(continuationDescriptor.entry,
                engine->mixer.BlocksRendered(), &secondReceipt);
            ASSERT_NE(harken::FrontierReceiptRead::Stale, read);
            if (read == harken::FrontierReceiptRead::Ready) {
                EXPECT_EQ(continuationDescriptor.entry, secondReceipt.entry);
                secondReceiptObserved = true;
                ASSERT_TRUE(continuationReceiptPin.Release());
            }
        }
        engine->nullBackend.Pump(1);
        const auto* output = engine->nullBackend.LastBlock();
        lateSecondSound = lateSecondSound || std::any_of(output,
            output + kBlockFrames,
            [](float sample) { return sample < -0.01f; });
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &refusedInfo));
        if (refusedInfo.state == VN_ACTION_FIRING_TERMINAL_RETAINED) break;
    }
    EXPECT_FALSE(lateSecondSound);
    ASSERT_TRUE(secondReceiptObserved);
    EXPECT_NE(harken::FrontierReceiptOutcome::Applied, secondReceipt.outcome);
    EXPECT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, refusedInfo.state);
    EXPECT_EQ(VN_ACTION_OUTCOME_FAILED, refusedInfo.outcome);
    EXPECT_EQ(VN_ACTION_TERMINAL_CAPACITY, refusedInfo.terminalReason);
    EXPECT_EQ(0u, refusedInfo.livePlayableCount);
    harken::monitor::StopDrainForTests();
    harken::monitor::DrainOnceForTests();
    harken::monitor::StartDrainForTests();
    std::array<std::uint8_t, 65536> monitorBuffer{};
    VnMonitorPollDesc monitorPoll{};
    monitorPoll.structSize = sizeof(monitorPoll);
    monitorPoll.buffer = monitorBuffer.data();
    monitorPoll.bufferBytes = monitorBuffer.size();
    VnMonitorPollResult monitorResult{};
    monitorResult.structSize = sizeof(monitorResult);
    ASSERT_EQ(VN_OK, Vn_MonitorPoll(monitorSession, &monitorPoll,
                                   &monitorResult));
    const auto read32 = [](const std::uint8_t* bytes) {
        return static_cast<std::uint32_t>(bytes[0]) |
            (static_cast<std::uint32_t>(bytes[1]) << 8) |
            (static_cast<std::uint32_t>(bytes[2]) << 16) |
            (static_cast<std::uint32_t>(bytes[3]) << 24);
    };
    const auto read64 = [&](const std::uint8_t* bytes) {
        return static_cast<std::uint64_t>(read32(bytes)) |
            (static_cast<std::uint64_t>(read32(bytes + 4)) << 32);
    };
    const std::uint64_t queueHandle =
        (static_cast<std::uint64_t>(continuationQueue.generation) << 32) |
        continuationQueue.slot;
    bool queueCapacity = false;
    for (std::uint64_t offset = 0;
         offset + VN_MONITOR_RECORD_ENVELOPE_PACKED_BYTES <=
             monitorResult.bytesWritten;) {
        const auto* record = monitorBuffer.data() + offset;
        const auto recordBytes = read64(record + 16);
        ASSERT_GE(recordBytes, VN_MONITOR_RECORD_ENVELOPE_PACKED_BYTES);
        ASSERT_LE(offset + recordBytes, monitorResult.bytesWritten);
        if (read32(record) == VN_MONITOR_RECORD_EVENT &&
            read32(record + 156) == VN_MONITOR_ENTITY_QUEUE &&
            read64(record + 200) == queueHandle &&
            read64(record + 208) == continuationQueue.generation &&
            recordBytes >= VN_MONITOR_RECORD_ENVELOPE_PACKED_BYTES +
                               sizeof(VnMonitorEventPayload)) {
            VnMonitorEventPayload payload{};
            std::memcpy(&payload,
                record + VN_MONITOR_RECORD_ENVELOPE_PACKED_BYTES,
                sizeof(payload));
            queueCapacity = queueCapacity ||
                payload.eventClass == VN_MONITOR_EVENT_REJECT &&
                payload.reason ==
                    static_cast<std::uint32_t>(harken::QueueFailureReason::Capacity);
        }
        offset += recordBytes;
    }
    EXPECT_TRUE(queueCapacity);
    EXPECT_EQ(VN_OK, Vn_MonitorCloseSession(monitorSession));
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    for (std::uint32_t block = 0; block < 64; ++block) {
        if (CaptureActionReclaimableOwners(*engine) == ownersBeforePost) break;
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
    }
    EXPECT_EQ(ownersBeforePost, CaptureActionReclaimableOwners(*engine));
    EXPECT_FALSE(attempt->active);
    EXPECT_EQ(0u, engine->queueInstances.LiveCount());
    EXPECT_EQ(0u, engine->voices.ActiveCount());
    EXPECT_FALSE(engine->runtimeRecreateRequired);
}

TEST(ActionFiringApi, InitialQueueCommittedC0BeforeHandoffPublishFailureReclaimsOwners) {
    for (const std::uint32_t fault : {1u, 2u}) {
        SCOPED_TRACE(fault == 1u ? "C1 publication" : "lane publication");
        (void)Vn_Term();
        constexpr std::uint32_t kBlockFrames = 64;
        harkentest::EngineSession session(
            harkentest::MakeNullConfig(8, kBlockFrames, 48000));
        ASSERT_EQ(VN_OK, session.InitResult());
        auto* engine = session.Engine();
        std::vector<float> first(kBlockFrames, 0.25f);
        std::vector<float> second(2 * kBlockFrames, -0.25f);
        const auto firstPcm = harkentest::MonoDesc(first, 48000);
        const auto secondPcm = harkentest::MonoDesc(second, 48000);
        ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound,
                                       &firstPcm));
        ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound,
                                       &secondPcm));
        CanonicalActionWorld image(
            engine->registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
            engine->registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
        image.MakeImmediateSequenceQueuePlayAction();
        ASSERT_EQ(harken::WorldInstallStatus::Ok,
                  harken::InstallContainerWorldV1(*engine, image.world).status);
        VnPostActionDesc post = ValidPostDesc();
        post.actionId = image.actions[9].actionStableId;
        ASSERT_EQ(VN_OK, Vn_CreateEmitter(&post.emitter));
        const auto ownersBeforePost = CaptureActionReclaimableOwners(*engine);
        VnActionFiringHandle firing = 0;
        ASSERT_EQ(VN_OK, Vn_PostAction(&post, &firing));
        const auto attempt = std::find_if(
            engine->immediateEntryAttempts.data(),
            engine->immediateEntryAttempts.data() +
                engine->immediateEntryAttempts.size(),
            [firing](const auto& candidate) {
                return candidate.active && candidate.root == firing;
            });
        ASSERT_NE(engine->immediateEntryAttempts.data() +
                      engine->immediateEntryAttempts.size(), attempt);
        const auto c0 = attempt->QueueCoordinators().initialQueueCoordinator;
        const auto c1 = attempt->QueueCoordinators().queueContinuationCoordinator;
        ASSERT_TRUE(c0.Valid());
        ASSERT_TRUE(c1.Valid());
        struct PostC0Proof {
            bool called = false;
            bool c0Committed = false;
            bool c0Pending = false;
            bool serviceEntryEmpty = false;
        } proof{};
        engine->immediateQueuePostC0PublishContextForTest = &proof;
        engine->immediateQueuePostC0PublishHookForTest = +[](
            harken::Engine& current, harken::EngineImmediateEntryAttempt& pending,
            void* context) {
            auto& proof = *static_cast<PostC0Proof*>(context);
            proof.called = true;
            harken::DecisionCommittedSnapshot committed{};
            proof.c0Committed = current.decisions.CaptureCommitted(
                pending.QueueCoordinators().initialQueueCoordinator, &committed);
            const auto* activation = current.decisions.ResolveFrontierActivation(
                pending.QueueCoordinators().initialQueueCoordinator);
            proof.c0Pending = activation != nullptr &&
                activation->State() == harken::FrontierReceiptState::Pending;
            const auto service = std::find_if(current.playableServices.begin(),
                current.playableServices.end(), [&](const auto& row) {
                    return row.identity == pending.initialService &&
                        row.PendingImmediateCohortRoot() == pending.root;
                });
            proof.serviceEntryEmpty =
                service != current.playableServices.end() &&
                !service->frontierEntry.Valid();
        };
        engine->forceImmediateQueuePostC0PublishFailureForTest = fault;
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->immediateQueuePostC0PublishHookForTest = nullptr;
        engine->immediateQueuePostC0PublishContextForTest = nullptr;
        EXPECT_TRUE(proof.called);
        EXPECT_TRUE(proof.c0Committed);
        EXPECT_TRUE(proof.c0Pending);
        EXPECT_TRUE(proof.serviceEntryEmpty);
        EXPECT_EQ(0u, engine->forceImmediateQueuePostC0PublishFailureForTest);
        bool sound = false;
        VnActionFiringInfo info{};
        info.structSize = sizeof(info);
        for (std::uint32_t block = 0; block < 128; ++block) {
            engine->nullBackend.Pump(1);
            const auto* output = engine->nullBackend.LastBlock();
            sound = sound || std::any_of(output, output + kBlockFrames,
                [](float sample) { return std::abs(sample) > 0.01f; });
            ASSERT_EQ(VN_OK, Vn_Update());
            ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
            if (info.state == VN_ACTION_FIRING_TERMINAL_RETAINED &&
                !attempt->active && engine->queueInstances.LiveCount() == 0)
                break;
        }
        EXPECT_FALSE(sound);
        EXPECT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
        EXPECT_EQ(VN_ACTION_OUTCOME_FAILED, info.outcome);
        EXPECT_EQ(0u, info.livePlayableCount);
        EXPECT_FALSE(attempt->active);
        EXPECT_EQ(0u, engine->queueInstances.LiveCount());
        EXPECT_FALSE(engine->runtimeRecreateRequired);
        ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
        for (std::uint32_t block = 0; block < 64; ++block) {
            if (CaptureActionReclaimableOwners(*engine) == ownersBeforePost &&
                !engine->decisions.Contains(c0) &&
                !engine->decisions.Contains(c1))
                break;
            engine->nullBackend.Pump(1);
            ASSERT_EQ(VN_OK, Vn_Update());
        }
        EXPECT_EQ(ownersBeforePost, CaptureActionReclaimableOwners(*engine));
        EXPECT_FALSE(engine->decisions.Contains(c0));
        EXPECT_FALSE(engine->decisions.Contains(c1));
    }
}

TEST(ActionFiringApi, ImmediateLaneCapacityReasonDoesNotCarryIntoNextProtocolRefusal) {
    (void)Vn_Term();
    constexpr std::uint32_t kBlockFrames = 64;
    harkentest::EngineSession session(
        harkentest::MakeNullConfig(8, kBlockFrames, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    std::vector<float> first(kBlockFrames, 0.25f);
    std::vector<float> second(2 * kBlockFrames, -0.25f);
    const auto firstPcm = harkentest::MonoDesc(first, 48000);
    const auto secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound,
                                   &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound,
                                   &secondPcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
    image.MakeImmediateSequenceQueuePlayAction();
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);
    VnPostActionDesc post = ValidPostDesc();
    post.actionId = image.actions[9].actionStableId;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&post.emitter));
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&post, &firing));
    engine->nullBackend.Pump(1);
    ASSERT_EQ(VN_OK, Vn_Update());
    const auto attempt = std::find_if(
        engine->immediateEntryAttempts.data(),
        engine->immediateEntryAttempts.data() + engine->immediateEntryAttempts.size(),
        [firing](const auto& candidate) {
            return candidate.active && candidate.root == firing;
        });
    ASSERT_NE(engine->immediateEntryAttempts.data() +
                  engine->immediateEntryAttempts.size(), attempt);
    const auto firstQuantum = attempt->entryQuantum;
    const std::array<harken::DecisionToken, 2> pageDecisions = {
        attempt->QueueCoordinators().initialQueueCoordinator,
        attempt->QueueCoordinators().queueContinuationCoordinator};
    harken::Plan03GroupSliceInput pageGroup{};
    pageGroup.executeFrame = (firstQuantum + 1u) * kBlockFrames;
    for (const auto decision : pageDecisions) {
        ASSERT_TRUE(decision.Valid());
        harken::DecisionCommittedSnapshot committed{};
        ASSERT_TRUE(engine->decisions.CaptureCommitted(
            decision, &committed));
        pageGroup.decision = decision;
        ASSERT_EQ(harken::Plan03GroupReserveStatus::Committed,
                  engine->timelinePool.ReservePlan03GroupSlice(
                      pageGroup, engine->timelineArms));
    }
    engine->timelinePool.Publish((firstQuantum + 2u) * kBlockFrames,
                                 nullptr, nullptr, &engine->timelineArms);
    std::array<harken::Plan03PageGroupView, 8> dueGroups{};
    ASSERT_EQ(2u, engine->timelinePool.CapturePlan03PageGroupsRt(
        firstQuantum + 1u, dueGroups.data(), dueGroups.size()));
    EXPECT_EQ(firstQuantum + 1u,
              dueGroups[0].identity.absoluteQuantum);
    EXPECT_EQ(firstQuantum + 1u,
              dueGroups[1].identity.absoluteQuantum);
    EXPECT_NE(0u, dueGroups[0].identity.pageGeneration);
    EXPECT_NE(0u, dueGroups[1].identity.pageGeneration);

    harken::ImmediateActionLane lane;
    ASSERT_TRUE(lane.Reset({2, 1, 1, kBlockFrames}));
    const harken::TimelineProgramView program{};
    harken::ImmediateLaneEvent event{};
    event.event.program.program = &program;
    harken::ImmediateLaneHandle capacityHandle{};
    harken::ImmediateLaneHandle protocolHandle{};
    ASSERT_TRUE(lane.Reserve(101, 1, &capacityHandle));
    ASSERT_TRUE(lane.Prepare(capacityHandle, &event, 1));
    std::uint64_t anchor = 0;
    ASSERT_TRUE(lane.TryPlace(capacityHandle,
        firstQuantum * kBlockFrames, 0, &anchor));
    ASSERT_TRUE(lane.Publish(capacityHandle));
    ASSERT_TRUE(lane.Reserve(102, 1, &protocolHandle));
    ASSERT_NE(capacityHandle.slot, protocolHandle.slot);
    ASSERT_TRUE(lane.Prepare(protocolHandle, &event, 1));
    ASSERT_TRUE(lane.TryPlace(protocolHandle,
        (firstQuantum + 1u) * kBlockFrames, 0, &anchor));
    ASSERT_TRUE(lane.Publish(protocolHandle));

    harken::VoiceTimelineSink sink(engine->voices, engine->timelineArms);
    ASSERT_TRUE(sink.AttachImmediateLane(lane, kBlockFrames));
    ASSERT_TRUE(sink.AttachPlan03ScratchAuthority(engine->decisions,
                                                  engine->timelinePool));
    sink.SetArenaAdmission(0, kBlockFrames);
    ASSERT_TRUE(sink.CaptureIndependentWork(firstQuantum));
    EXPECT_FALSE(sink.AdmitQuantum(firstQuantum));
    sink.DiscardIndependentWork();
    const auto* firstDue = lane.CaptureDue(capacityHandle.slot, firstQuantum);
    ASSERT_NE(nullptr, firstDue);
    EXPECT_EQ(capacityHandle.generation, firstDue->attemptGeneration);
    EXPECT_EQ(firstQuantum, firstDue->quantum);
    EXPECT_EQ(harken::ImmediateLaneAdmissionFailure::ArenaCapacity,
        firstDue->admissionFailure.load(std::memory_order_acquire));
    ASSERT_TRUE(lane.ReleaseCapture(capacityHandle.slot, firstDue));

    ASSERT_TRUE(sink.CaptureIndependentWork(firstQuantum + 1u));
    sink.SetArenaAdmission(UINT32_MAX, kBlockFrames);
    const auto originalScratch =
        harken::detail::VoiceTimelineSinkTestAccess::SetPageGroupScratchCount(
            sink, 1);
    ASSERT_GT(originalScratch, 1u);
    EXPECT_FALSE(sink.AdmitQuantum(firstQuantum + 1u));
    sink.DiscardIndependentWork();
    harken::detail::VoiceTimelineSinkTestAccess::SetPageGroupScratchCount(
        sink, originalScratch);
    const auto* secondDue = lane.CaptureDue(protocolHandle.slot,
                                           firstQuantum + 1u);
    ASSERT_NE(nullptr, secondDue);
    EXPECT_EQ(protocolHandle.generation, secondDue->attemptGeneration);
    EXPECT_EQ(firstQuantum + 1u, secondDue->quantum);
    EXPECT_EQ(harken::ImmediateLaneAdmissionFailure::None,
        secondDue->admissionFailure.load(std::memory_order_acquire));
    ASSERT_TRUE(lane.ReleaseCapture(protocolHandle.slot, secondDue));
    (void)sink.CaptureIndependentWork(firstQuantum + 2u);
    harken::ImmediateLaneObservation firstObservation{};
    harken::ImmediateLaneObservation secondObservation{};
    ASSERT_TRUE(lane.Observe(capacityHandle, &firstObservation));
    ASSERT_TRUE(lane.Observe(protocolHandle, &secondObservation));
    EXPECT_TRUE(firstObservation.missed);
    EXPECT_TRUE(firstObservation.arenaCapacityMissed);
    EXPECT_TRUE(secondObservation.missed);
    EXPECT_FALSE(secondObservation.arenaCapacityMissed);
    ASSERT_TRUE(lane.Cancel(capacityHandle));
    ASSERT_TRUE(lane.Cancel(protocolHandle));
    EXPECT_TRUE(lane.Retire(capacityHandle));
    EXPECT_TRUE(lane.Retire(protocolHandle));
}

TEST(ActionFiringApi, InitialQueueRejectsExtraGroupOutsideExactEntry) {
    for (const int fault : {0, 1, 2}) {
        SCOPED_TRACE(fault == 0 ? "wrong role" :
            fault == 1 ? "wrong entry" : "missing prerequisite member");
        (void)Vn_Term();
        constexpr std::uint32_t kBlockFrames = 64;
        harkentest::EngineSession session(
            harkentest::MakeNullConfig(8, kBlockFrames, 48000));
        ASSERT_EQ(VN_OK, session.InitResult());
        auto* engine = session.Engine();
        std::vector<float> first(kBlockFrames, 0.25f);
        std::vector<float> second(2 * kBlockFrames, -0.25f);
        const auto firstPcm = harkentest::MonoDesc(first, 48000);
        const auto secondPcm = harkentest::MonoDesc(second, 48000);
        ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound,
                                       &firstPcm));
        ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound,
                                       &secondPcm));
        CanonicalActionWorld image(
            engine->registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
            engine->registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
        image.MakeImmediateSequenceQueuePlayAction();
        ASSERT_EQ(harken::WorldInstallStatus::Ok,
                  harken::InstallContainerWorldV1(*engine, image.world).status);
        auto post = ValidPostDesc();
        post.actionId = image.actions[9].actionStableId;
        ASSERT_EQ(VN_OK, Vn_CreateEmitter(&post.emitter));
        VnActionFiringHandle firing = 0;
        ASSERT_EQ(VN_OK, Vn_PostAction(&post, &firing));
        const auto* attempt = std::find_if(
            engine->immediateEntryAttempts.data(),
            engine->immediateEntryAttempts.data() +
                engine->immediateEntryAttempts.size(),
            [firing](const auto& candidate) {
                return candidate.active && candidate.root == firing;
            });
        ASSERT_NE(engine->immediateEntryAttempts.data() +
                      engine->immediateEntryAttempts.size(), attempt);
        std::array<harken::Plan03ImmediateLaneGroupDescriptor, 4> groups{};
        ASSERT_EQ(4u, engine->timelinePool.CaptureImmediateLaneCohortGroups(
            firing, groups.data(), groups.size()));
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        harken::Plan03GroupSliceIdentity member{};
        for (const auto& group : groups) {
            harken::Plan03PageGroupView view{};
            ASSERT_TRUE(engine->timelinePool.ResolvePlan03GroupSliceProducer(
                group.identity, &view));
            ASSERT_NE(nullptr, view.frontier);
            if (view.frontier->role == harken::FrontierGroupRole::EntryMember &&
                view.frontier->queueInitial.Valid() &&
                view.frontier->entry == attempt->QueueCoordinators().initialQueueDescriptor.entry) {
                EXPECT_FALSE(member.Exact());
                member = group.identity;
            }
        }
        ASSERT_TRUE(member.Exact());
        harken::Plan03PageGroupView memberView{};
        ASSERT_TRUE(engine->timelinePool.ResolvePlan03GroupSliceProducer(
            member, &memberView));
        ASSERT_NE(nullptr, memberView.frontier);
        auto* binding = const_cast<harken::FrontierGroupBinding*>(
            memberView.frontier);
        if (fault == 0)
            binding->role = harken::FrontierGroupRole::Future;
        else if (fault == 1)
            ++binding->entry.attempt;
        else {
            harken::Plan03PageGroupView continuation{};
            ASSERT_TRUE(engine->timelinePool.ResolvePlan03GroupSliceProducer(
                attempt->QueueCoordinators().queueContinuationPrimaryGroup, &continuation));
            ASSERT_NE(nullptr, continuation.frontier);
            auto* coordinator = const_cast<harken::FrontierGroupBinding*>(
                continuation.frontier);
            coordinator->prerequisiteMember = {};
        }
        const auto entryQuantum = attempt->entryQuantum;
        while (engine->mixer.BlocksRendered() <= entryQuantum)
            engine->nullBackend.Pump(1);
        const auto* activation = engine->decisions.ResolveFrontierActivation(
            attempt->QueueCoordinators().initialQueueCoordinator);
        ASSERT_NE(nullptr, activation);
        harken::FrontierActivationReceipt receipt{};
        ASSERT_EQ(harken::FrontierReceiptRead::Ready,
                  activation->Read(activation->Descriptor().entry,
                      engine->mixer.BlocksRendered(), &receipt));
        EXPECT_EQ(harken::FrontierReceiptOutcome::DefinitivelyNotApplied,
                  receipt.outcome);
        for (const auto& group : groups) {
            harken::Plan03PageGroupView view{};
            ASSERT_TRUE(engine->timelinePool.ResolvePlan03GroupSliceProducer(
                group.identity, &view));
            ASSERT_NE(nullptr, view.lease);
            EXPECT_NE(harken::AudioSliceState::SliceApplied,
                      view.lease->Capture().state);
        }
        const auto* output = engine->nullBackend.LastBlock();
        for (std::uint32_t frame = 0; frame < kBlockFrames; ++frame)
            EXPECT_FLOAT_EQ(0.0f, output[frame]);
    }
}

TEST(ActionFiringApi, InitialQueueContinuationRejectsMissingPriorReceiptOrIdentity) {
    for (const bool corruptPrerequisite : {false, true}) {
        SCOPED_TRACE(corruptPrerequisite ? "wrong C0 identity" :
            "C0 cancelled before audio");
        (void)Vn_Term();
        harkentest::EngineSession session(
            harkentest::MakeNullConfig(8, 64, 48000));
        ASSERT_EQ(VN_OK, session.InitResult());
        auto* engine = session.Engine();
        std::vector<float> first(64, 0.25f);
        std::vector<float> second(128, -0.25f);
        const auto firstPcm = harkentest::MonoDesc(first, 48000);
        const auto secondPcm = harkentest::MonoDesc(second, 48000);
        ASSERT_EQ(VN_OK, Vn_RegisterPCM(
            CanonicalActionWorld::kFirstSound, &firstPcm));
        ASSERT_EQ(VN_OK, Vn_RegisterPCM(
            CanonicalActionWorld::kSecondSound, &secondPcm));
        CanonicalActionWorld image(
            engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
                .contentRevision,
            engine->registry.Lookup(CanonicalActionWorld::kSecondSound)
                .contentRevision);
        image.MakeImmediateSequenceQueuePlayAction();
        ASSERT_EQ(harken::WorldInstallStatus::Ok,
            harken::InstallContainerWorldV1(*engine, image.world).status);
        auto post = ValidPostDesc();
        post.actionId = image.actions[9].actionStableId;
        ASSERT_EQ(VN_OK, Vn_CreateEmitter(&post.emitter));
        VnActionFiringHandle firing = 0;
        ASSERT_EQ(VN_OK, Vn_PostAction(&post, &firing));
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        auto* attempt = std::find_if(
            engine->immediateEntryAttempts.data(),
            engine->immediateEntryAttempts.data() +
                engine->immediateEntryAttempts.size(),
            [firing](const auto& candidate) {
                return candidate.active && candidate.root == firing;
            });
        ASSERT_NE(engine->immediateEntryAttempts.data() +
            engine->immediateEntryAttempts.size(), attempt);
        if (corruptPrerequisite) {
            harken::Plan03PageGroupView primary{};
            ASSERT_TRUE(engine->timelinePool.ResolvePlan03GroupSliceProducer(
                attempt->QueueCoordinators().queueContinuationPrimaryGroup, &primary));
            ASSERT_NE(nullptr, primary.frontier);
            auto* binding = const_cast<harken::FrontierGroupBinding*>(
                primary.frontier);
            ++binding->prerequisite.attempt;
        } else {
            auto* activation = engine->decisions.ResolveFrontierActivation(
                attempt->QueueCoordinators().initialQueueCoordinator);
            ASSERT_NE(nullptr, activation);
            EXPECT_EQ(harken::FrontierCancelDisposition::CancelledBeforeAudio,
                activation->Cancel(attempt->QueueCoordinators().initialQueueDescriptor.entry,
                    harken::AudioSliceInvalidateReason::Cancel));
        }
        bool secondAudible = false;
        VnActionFiringInfo info{};
        info.structSize = sizeof(info);
        for (std::uint32_t block = 0; block < 64; ++block) {
            ASSERT_EQ(VN_OK, Vn_Update());
            engine->nullBackend.Pump(1);
            const auto* output = engine->nullBackend.LastBlock();
            for (std::uint32_t frame = 0; frame < 64; ++frame)
                secondAudible = secondAudible || output[frame] < -0.1f;
            ASSERT_EQ(VN_OK, Vn_Update());
            ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
            if (info.state == VN_ACTION_FIRING_TERMINAL_RETAINED) break;
        }
        const auto* finalAttempt = std::find_if(
            engine->immediateEntryAttempts.data(),
            engine->immediateEntryAttempts.data() +
                engine->immediateEntryAttempts.size(),
            [firing](const auto& candidate) {
                return candidate.active && candidate.root == firing;
            });
        const auto finalRow = std::find_if(
            engine->playableServices.begin(),
            engine->playableServices.end(),
            [firing](const auto& candidate) {
                return candidate.PendingImmediateCohortRoot() == firing &&
                    candidate.queueMode;
            });
        harken::ImmediateLaneObservation finalLane{};
        harken::QueueInstanceSnapshot finalQueue{};
        const bool queueCaptured =
            finalRow != engine->playableServices.end() &&
            engine->queueInstances.Capture(
                finalRow->queueInstance, &finalQueue);
        const auto* c0 = finalAttempt ==
                engine->immediateEntryAttempts.data() +
                    engine->immediateEntryAttempts.size()
            ? nullptr : engine->decisions.ResolveFrontierActivation(
                finalAttempt->QueueCoordinators().initialQueueCoordinator);
        const auto* c1 = finalAttempt ==
                engine->immediateEntryAttempts.data() +
                    engine->immediateEntryAttempts.size()
            ? nullptr : engine->decisions.ResolveFrontierActivation(
                finalAttempt->QueueCoordinators().queueContinuationCoordinator);
        harken::FrontierActivationReceipt c0Receipt{};
        harken::FrontierActivationReceipt c1Receipt{};
        const auto c0Read = c0 == nullptr ? harken::FrontierReceiptRead::Stale :
            c0->Read(finalAttempt->QueueCoordinators().initialQueueDescriptor.entry,
                engine->mixer.BlocksRendered(), &c0Receipt);
        const auto c1Read = c1 == nullptr ? harken::FrontierReceiptRead::Stale :
            c1->Read(finalAttempt->QueueCoordinators().queueContinuationDescriptor.entry,
                engine->mixer.BlocksRendered(), &c1Receipt);
        const bool laneObserved = finalAttempt !=
                engine->immediateEntryAttempts.data() +
                    engine->immediateEntryAttempts.size() &&
            finalAttempt->lane.Valid() &&
            engine->immediateActionLane.Observe(
                finalAttempt->lane, &finalLane);
        SCOPED_TRACE(::testing::Message()
            << "lane observed=" << laneObserved
            << " lane applied=" << finalLane.applied
            << " lane missed=" << finalLane.missed
            << " lane complete=" << finalLane.complete
            << " attempt active=" << (finalAttempt !=
                engine->immediateEntryAttempts.data() +
                    engine->immediateEntryAttempts.size())
            << " row=" << (finalRow != engine->playableServices.end())
            << " phase=" << (finalRow == engine->playableServices.end()
                ? -1 : static_cast<int>(finalRow->phase))
            << " retry=" << (finalRow != engine->playableServices.end() &&
                finalRow->pendingImmediateRetry)
            << " control=" << (finalRow == engine->playableServices.end()
                ? -1 : static_cast<int>(finalRow->controlLifecycle))
            << " queue captured=" << queueCaptured
            << " queue pending=" << finalQueue.pendingVersion
            << " queue activation=" <<
                static_cast<int>(finalQueue.pendingActivation)
            << " queue failure=" <<
                static_cast<int>(finalQueue.failurePhase)
            << " C0 state=" << (c0 == nullptr ? -1 :
                static_cast<int>(c0->State()))
            << " C0 read=" << static_cast<int>(c0Read)
            << " C1 state=" << (c1 == nullptr ? -1 :
                static_cast<int>(c1->State()))
            << " C1 read=" << static_cast<int>(c1Read)
            << " exact version=" << (finalAttempt !=
                engine->immediateEntryAttempts.data() +
                    engine->immediateEntryAttempts.size() &&
                finalAttempt->queueContinuationVersion.Valid())
            << " decision=" << (finalRow != engine->playableServices.end() &&
                finalRow->HasFeatureArrays() && finalRow->QueueFiling().queueDecision.Valid())
            << " abort=" << (finalRow != engine->playableServices.end() &&
                finalRow->queueAbortRequested)
            << " runtime recreate=" << engine->runtimeRecreateRequired);
        EXPECT_FALSE(secondAudible);
        EXPECT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
        EXPECT_EQ(0u, info.livePlayableCount);
        EXPECT_EQ(0u, engine->queueInstances.LiveCount());
        EXPECT_EQ(0u, engine->voices.ActiveCount());
    }
}

void ExpectImmediateQueueNestedContainerPlay(bool randomQueue) {
    (void)Vn_Term();
    VnConfig config = harkentest::MakeNullConfig(8, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> first(64, 0.25f);
    std::vector<float> second(128, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kSecondSound,
                             &secondPcm));

    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound)
            .contentRevision);
    image.MakeImmediateQueueNestedContainerPlayAction(randomQueue);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&desc.emitter));
    std::uint32_t expectedOrdinal = image.queueChildren[0].stableChildOrdinal;
    if (randomQueue) {
        bool foundContainerFirst = false;
        for (std::uint64_t callerSeed = 1; callerSeed < 128;
             ++callerSeed) {
            desc.callerSeed = callerSeed;
            harken::RandomQueueSeedContext expectedSeed{};
            expectedSeed.worldSemanticFingerprint =
                image.world.identity.runtimeSemanticFingerprint;
            expectedSeed.rootStableId = image.containers[2].containerStableId;
            expectedSeed.callerSeed = ExpectedImmediateActionPlayCallerSeed(
                image.actions[9], desc.callerSeed, 0);
            expectedSeed.acceptedPostOrdinal =
                engine->logicCommits.Current() + 1u;
            expectedSeed.emitterSlot =
                static_cast<std::uint32_t>(desc.emitter);
            expectedSeed.emitterGeneration =
                static_cast<std::uint32_t>(desc.emitter >> 32);
            expectedSeed.resetEpoch = engine->transportEpochOwner.Current();
            harken::EffectiveQueueState expectedInitial{};
            expectedInitial.version = 1;
            expectedInitial.selectionOrdinal = 1;
            std::array<harken::SelectionChildV1, 2> selectionChildren{};
            std::array<std::uint32_t, 2> remaining{};
            std::array<std::uint32_t, 2> permutation{};
            ASSERT_EQ(harken::SelectionStatusV1::Ok,
                      harken::BuildRandomQueuePermutationV1(
                          image.containers[2], expectedSeed, expectedInitial,
                          selectionChildren.data(), remaining.data(),
                          permutation.data(), permutation.size()));
            if (permutation[0] == image.queueChildren[1].stableChildOrdinal) {
                expectedOrdinal = permutation[0];
                foundContainerFirst = true;
                break;
            }
        }
        ASSERT_TRUE(foundContainerFirst);
    }

    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
    ASSERT_EQ(VN_ACTION_FIRING_ACTIVE, info.state);
    EXPECT_EQ(1u, info.livePlayableCount);
    VnActionStepResult play{};
    play.structSize = sizeof(play);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
    ASSERT_EQ(VN_ACTION_STEP_ACTIVE, play.state);
    ASSERT_EQ(VN_ACTION_TARGET_CONTAINER, play.targetKind);
    ASSERT_NE(0u, play.producedPlayableInstance);

    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == play.producedPlayableInstance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    EXPECT_TRUE(row->queueMode);
    EXPECT_TRUE(row->queueSignalOnlyNoOverlap);
    EXPECT_FALSE(row->queueContinuationPrepared);
    const auto* childService = engine->ResolvePlayableService(row->frontierChildService);
    ASSERT_NE(nullptr, childService);
    EXPECT_NE(row->partition.slot, childService->partition.slot);
    EXPECT_EQ(expectedOrdinal, row->selectedChildOrdinals[0]);
    EXPECT_EQ(randomQueue ? CanonicalActionWorld::kSecondSound
                          : CanonicalActionWorld::kFirstSound,
              row->leaf.stableId);
    const auto* arm = engine->timelineArms.Resolve(childService->arm);
    ASSERT_NE(nullptr, arm);
    const auto* childInstall = engine->ResolvePlayableServiceVoice(*childService);
    ASSERT_NE(nullptr, childInstall);
    EXPECT_EQ(row->payload.target.occurrenceOrdinal,
              childInstall->Facts().target.occurrenceOrdinal);
    EXPECT_EQ(row->payload.target.occurrenceOrdinal,
              arm->target.occurrenceOrdinal);
    if (randomQueue) {
        EXPECT_NE(expectedOrdinal, row->payload.target.occurrenceOrdinal);
    }
    EXPECT_FALSE(row->QueueFiling().queueDecision.Valid());
    harken::QueueInstanceSnapshot initialQueue{};
    ASSERT_TRUE(engine->queueInstances.Capture(row->queueInstance, &initialQueue));
    EXPECT_EQ(1u, initialQueue.logicMirror.version);

    const auto root = engine->playableInstances.Classify(row->rootInstance);
    ASSERT_TRUE(root.live);
    ASSERT_EQ(harken::PlayableKind::Container, root.kind);
    ASSERT_NE(0u, root.firstChild);
    const auto nested = engine->playableInstances.Classify(root.firstChild);
    ASSERT_TRUE(nested.live);
    EXPECT_EQ(row->rootInstance, nested.parent);
    EXPECT_EQ(harken::PlayableKind::Container, nested.kind);
    ASSERT_NE(0u, nested.firstChild);
    const auto leaf = engine->playableInstances.Classify(nested.firstChild);
    ASSERT_TRUE(leaf.live);
    EXPECT_EQ(harken::PlayableKind::Sound, leaf.kind);
    EXPECT_EQ(root.firstChild, leaf.parent);

    harken::ContainerPlaybackRow nestedRow{};
    ASSERT_TRUE(engine->containerPlayback.Capture(root.firstChild,
                                                  &nestedRow));
    EXPECT_EQ(root.firstChild, nestedRow.instance);
    EXPECT_EQ(2u, engine->containerPlayback.LiveCount());
    const auto initialRelease = childService->releaseObserver;
    const auto initialChild = root.firstChild;
    const auto initialLeaf = nested.firstChild;
    const auto initialLeafEpoch = leaf.scheduleEpoch;
    std::uint64_t initialReleaseBlock = 0;
    std::uint64_t initialChildRetiredBlock = 0;
    bool consumedOriginalLeaf = false;
    FrontierTrace trace;
    std::uint64_t firstPositiveFrame = UINT64_MAX;
    std::uint64_t firstNegativeFrame = UINT64_MAX;
    float maximumFreshMagnitude = 0.0f;
    std::uint64_t freshPositiveSamples = 0;
    std::uint64_t freshNegativeSamples = 0;


    for (std::uint32_t block = 0; block < 96; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        trace.Capture(*engine);
        const auto beforePump = engine->mixer.BlocksRendered();
        engine->nullBackend.Pump(1);
        ASSERT_EQ(beforePump + 1u, engine->mixer.BlocksRendered());
        const auto* output = engine->nullBackend.LastBlock();
        const auto channels = engine->nullBackend.Channels();
        const auto blockFrames = engine->nullBackend.BlockFrames();
        for (std::uint32_t sample = 0; sample < blockFrames; ++sample) {
            const auto value = output[static_cast<std::size_t>(sample) * channels];
            maximumFreshMagnitude = std::max(maximumFreshMagnitude, std::abs(value));
            if (value > 0.01f) {
                ++freshPositiveSamples;
                if (firstPositiveFrame == UINT64_MAX)
                    firstPositiveFrame = beforePump * blockFrames + sample;
            }
            if (value < -0.01f) {
                ++freshNegativeSamples;
                if (firstNegativeFrame == UINT64_MAX)
                    firstNegativeFrame = beforePump * blockFrames + sample;
            }
        }
        trace.Capture(*engine);
        ASSERT_EQ(VN_OK, Vn_Update());
        if (initialReleaseBlock == 0 && engine->voices.ReleaseObserved(initialRelease)) {
            initialReleaseBlock = engine->mixer.BlocksRendered();
            ASSERT_TRUE(engine->playableInstances.Classify(initialLeaf).live);
            ASSERT_TRUE(engine->playableInstances.Classify(initialChild).live);
            ASSERT_EQ(VN_OK, Vn_Update());
            ASSERT_EQ(initialReleaseBlock, engine->mixer.BlocksRendered());
            EXPECT_TRUE(engine->playableInstances.Classify(initialLeaf).live);
            EXPECT_TRUE(engine->playableInstances.Classify(initialChild).live);
        }
        if (engine->containerPlayback.Capture(initialChild, &nestedRow) &&
            nestedRow.lastConsumedChild != 0) {
            EXPECT_EQ(initialLeaf, nestedRow.lastConsumedChild);
            EXPECT_EQ(initialLeafEpoch, nestedRow.lastConsumedChildEpoch);
            EXPECT_NE(0u, nestedRow.lastConsumedOutcomeOrdinal);
            consumedOriginalLeaf = true;
        }
        if (initialChildRetiredBlock == 0 && !engine->playableInstances.Classify(initialChild).live)
            initialChildRetiredBlock = engine->mixer.BlocksRendered();
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
        if (info.state == VN_ACTION_FIRING_TERMINAL_RETAINED) {
            break;
        }
    }

    SCOPED_TRACE("fresh PCM positive=" + std::to_string(firstPositiveFrame) +
        " negative=" + std::to_string(firstNegativeFrame) +
        " positive samples=" + std::to_string(freshPositiveSamples) +
        " negative samples=" + std::to_string(freshNegativeSamples) +
        " maximum magnitude=" + std::to_string(maximumFreshMagnitude));
    EXPECT_NE(UINT64_MAX, firstPositiveFrame);
    EXPECT_NE(UINT64_MAX, firstNegativeFrame);
    if (firstPositiveFrame != UINT64_MAX && firstNegativeFrame != UINT64_MAX) {
        if (randomQueue) EXPECT_LT(firstNegativeFrame, firstPositiveFrame);
        else EXPECT_LT(firstPositiveFrame, firstNegativeFrame);
    }
    EXPECT_TRUE(consumedOriginalLeaf);
    ASSERT_NE(0u, initialReleaseBlock);
    EXPECT_GT(initialChildRetiredBlock, initialReleaseBlock);
    ASSERT_EQ(2u, trace.heard.size());
    EXPECT_EQ(randomQueue ? CanonicalActionWorld::kSecondSound : CanonicalActionWorld::kFirstSound,
              trace.heard[0].subject);
    EXPECT_EQ(randomQueue ? CanonicalActionWorld::kFirstSound : CanonicalActionWorld::kSecondSound,
              trace.heard[1].subject);
    for (const auto& heard : trace.heard) {
        EXPECT_EQ(heard.expectedStart, heard.start);
        heard.ExpectNaturalSourceReleased();
    }
    ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
    EXPECT_EQ(VN_ACTION_OUTCOME_SUCCEEDED, info.outcome);
    EXPECT_EQ(VN_ACTION_TERMINAL_NATURAL, info.terminalReason);
    EXPECT_EQ(0u, info.livePlayableCount);
    EXPECT_EQ(0u, engine->voices.ActiveCount());
    EXPECT_EQ(0u, engine->queueInstances.LiveCount());
    EXPECT_FALSE(engine->playableInstances.Classify(row->rootInstance).live);
    EXPECT_FALSE(engine->playableInstances.Classify(root.firstChild).live);
    EXPECT_FALSE(engine->playableInstances.Classify(nested.firstChild).live);
    EXPECT_EQ(0u, engine->containerPlayback.LiveCount());
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
    EXPECT_EQ(VN_ACTION_STEP_SUCCEEDED, play.state);
    EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
}

