void CaptureImmediateContainerToQueuePlay(bool direct,
                                          SharedQueueTrace* outTrace) {
    SharedQueueTrace trace{};
    (void)Vn_Term();
    harkentest::EngineSession session(harkentest::MakeNullConfig(8, 64, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> first(64, 0.25f);
    std::vector<float> second(128, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound,
                                    &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound,
                                    &secondPcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound)
            .contentRevision);
    image.MakeImmediateContainerToQueuePlayAction();
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    VnEmitterHandle emitter = 0;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&emitter));
    VnActionFiringHandle firing = 0;
    harken::PlayableInstanceHandle produced = 0;
    if (direct) {
        const auto started = harken::StartCurrentPlayableByIdentity(
            harken::PlayableKindV1::Container,
            image.containers[0].containerStableId, emitter);
        ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
        produced = started.instance;
    } else {
        VnPostActionDesc desc = ValidPostDesc();
        desc.actionId = image.actions[9].actionStableId;
        desc.emitter = emitter;
        ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
        VnActionStepResult step{};
        step.structSize = sizeof(step);
        ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &step));
        ASSERT_EQ(VN_ACTION_STEP_ACTIVE, step.state);
        produced = step.producedPlayableInstance;
    }
    ASSERT_NE(0u, produced);

    auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [produced](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == produced;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    const auto root = engine->playableInstances.Classify(row->rootInstance);
    ASSERT_TRUE(root.live);
    ASSERT_EQ(harken::PlayableKind::Container, root.kind);
    harken::ContainerPlaybackRow outerPlayback{};
    ASSERT_TRUE(engine->containerPlayback.Capture(row->rootInstance,
                                                   &outerPlayback));
    EXPECT_EQ(static_cast<std::uint8_t>(harken::ContainerModeV1::Random),
              outerPlayback.mode);
    ASSERT_NE(0u, outerPlayback.activeChild);
    const auto queue = engine->playableInstances.Classify(root.firstChild);
    ASSERT_TRUE(queue.live);
    ASSERT_EQ(harken::PlayableKind::Container, queue.kind);
    EXPECT_EQ(row->rootInstance, queue.parent);
    harken::ContainerPlaybackRow queuePlayback{};
    ASSERT_TRUE(engine->containerPlayback.Capture(root.firstChild,
                                                   &queuePlayback));
    EXPECT_EQ(static_cast<std::uint8_t>(harken::ContainerModeV1::SequenceQueue),
              queuePlayback.mode);
    EXPECT_EQ(root.firstChild, outerPlayback.activeChild);
    const auto* queueService = FrontierServiceForOwner(*engine, root.firstChild);
    ASSERT_NE(nullptr, queueService);
    EXPECT_EQ(&*row, engine->ResolvePlayableService(queueService->parentService));
    harken::QueueInstanceSnapshot queueSnapshot{};
    ASSERT_TRUE(engine->queueInstances.Capture(queueService->queueInstance,
                                                &queueSnapshot));
    EXPECT_EQ(root.firstChild, queueSnapshot.rootInstance);
    EXPECT_EQ(queue.scheduleEpoch,
              engine->playableInstances.Classify(queueSnapshot.rootInstance)
                  .scheduleEpoch);
    ASSERT_NE(0u, queue.firstChild);
    const auto leaf = engine->playableInstances.Classify(queue.firstChild);
    ASSERT_TRUE(leaf.live);
    EXPECT_EQ(harken::PlayableKind::Sound, leaf.kind);
    EXPECT_EQ(root.firstChild, leaf.parent);
    EXPECT_EQ(queuePlayback.activeChildEpoch, leaf.scheduleEpoch);
    EXPECT_EQ(image.queueChildren[0].playable.stableId, queueService->leaf.stableId);
    EXPECT_EQ(7u, queueService->selectedChildOrdinals[0]);
    EXPECT_EQ(7u, queueService->payload.target.occurrenceOrdinal);
    trace.selectedOrdinals = {queueService->selectedChildOrdinals[0],
                              queueService->payload.target.occurrenceOrdinal};
    ASSERT_NE(nullptr, queueService->schedule.events);
    ASSERT_NE(0u, queueService->schedule.eventCount);
    trace.onsetRelativeFrame = queueService->schedule.events[0].frameOffsetFromEntry;
    trace.parentLinked = CaptureNestedRuntimeParentPath(
        row->rootInstance, root.firstChild, queue.firstChild, root, queue,
        leaf, outerPlayback.expectedScheduleEpoch,
        outerPlayback.activeChildEpoch, queuePlayback.expectedScheduleEpoch,
        queuePlayback.activeChildEpoch, &trace.parentPathHash,
        &trace.parentPathDepth);
    trace.parentEpoch = queuePlayback.activeChildEpoch;
    harken::PlayableExecutionRequest invalid{};
    invalid.root.kind = harken::PlayableKindV1::Sound;
    invalid.root.stableId = harkentest::ObjectId(0xfffffff1u);
    invalid.root.expectedProgramSemanticFingerprint = 0xfffffff2u;
    trace.typedError = static_cast<std::uint32_t>(
        harken::ResolvePlayableExecutionEntry(
            harken::PlayableExecutionAuthority::Current(
                engine->variables.CurrentPlayableWorld()),
            invalid)
            .status);

    if (direct) {
        ASSERT_EQ(harken::PlayableControlStatus::Ok,
                  harken::StopPlayable(*engine, produced, 0));
    } else {
        ASSERT_EQ(VN_OK, Vn_StopActionFiring(firing, 0));
    }
    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    for (std::uint32_t block = 0; block < 128; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        if (!direct) {
            ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
            if (info.state == VN_ACTION_FIRING_TERMINAL_RETAINED) break;
        } else if (!engine->playableInstances.Classify(produced).live) {
            break;
        }
    }
    if (!direct) {
        ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
        EXPECT_EQ(VN_ACTION_OUTCOME_CANCELLED, info.outcome);
    }
    EXPECT_FALSE(engine->playableInstances.Classify(produced).live);
    EXPECT_FALSE(engine->playableInstances.Classify(root.firstChild).live);
    EXPECT_FALSE(engine->playableInstances.Classify(queue.firstChild).live);
    EXPECT_EQ(0u, engine->queueInstances.LiveCount());
    EXPECT_EQ(0u, engine->containerPlayback.LiveCount());
    trace.reclaimed = !engine->playableInstances.Classify(produced).live &&
                      engine->queueInstances.LiveCount() == 0 &&
                      engine->containerPlayback.LiveCount() == 0;
    trace.nestedReclaimed =
        !engine->playableInstances.Classify(root.firstChild).live;
    trace.leafReclaimed =
        !engine->playableInstances.Classify(queue.firstChild).live;
    trace.valid = true;
    if (!direct) ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    ASSERT_EQ(VN_OK, Vn_DestroyEmitter(emitter));
    if (outTrace != nullptr) *outTrace = trace;
}

void CaptureImmediateRootQueuePlay(bool direct,
                                   SharedQueueTrace* outTrace,
                                   bool randomQueue) {
    SharedQueueTrace trace{};
    (void)Vn_Term();
    harkentest::EngineSession session(harkentest::MakeNullConfig(8, 64, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> first(64, 0.25f);
    std::vector<float> second(128, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound,
                                    &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound,
                                    &secondPcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound)
            .contentRevision);
    if (randomQueue) {
        image.MakeImmediateRandomQueuePlayAction();
    } else {
        image.MakeImmediateSequenceQueuePlayAction();
    }
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);
    VnEmitterHandle emitter = 0;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&emitter));
    VnActionFiringHandle firing = 0;
    harken::PlayableInstanceHandle produced = 0;
    if (direct) {
        harken::PlayableStartRequest request{};
        request.root.kind = harken::PlayableKindV1::Container;
        request.root.stableId = image.containers[2].containerStableId;
        request.root.expectedProgramSemanticFingerprint =
            image.containers[2].programSemanticFingerprint;
        request.root.contentRevision = image.properties[4].contentRevision;
        request.root.routeStableId = image.properties[4].routeStableId;
        request.root.compatibilityFingerprint =
            image.properties[4].compatibilityFingerprint;
        request.emitter = emitter;
        if (randomQueue) {
            request.callerSeed = ExpectedImmediateActionPlayCallerSeed(
                image.actions[9], 0, 0);
        }
        const auto started = harken::StartCurrentPlayable(request);
        ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
        produced = started.instance;
    } else {
        VnPostActionDesc desc = ValidPostDesc();
        desc.actionId = image.actions[9].actionStableId;
        desc.emitter = emitter;
        ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
        VnActionStepResult step{};
        step.structSize = sizeof(step);
        ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &step));
        ASSERT_EQ(VN_ACTION_STEP_ACTIVE, step.state);
        produced = step.producedPlayableInstance;
    }
    ASSERT_NE(0u, produced);
    auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [produced](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == produced;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    ASSERT_TRUE(row->queueMode);
    ASSERT_TRUE(row->queueContinuationPrepared);
    harken::ContainerPlaybackRow rootPlayback{};
    ASSERT_TRUE(engine->containerPlayback.Capture(row->rootInstance,
                                                   &rootPlayback));
    const auto rootView =
        engine->playableInstances.Classify(row->rootInstance);
    const auto childHandle = rootPlayback.activeChild;
    const auto childView = engine->playableInstances.Classify(childHandle);
    trace.parentLinked =
        rootView.live && childHandle != 0 && childView.live &&
        rootView.firstChild == childHandle &&
        childView.parent == row->rootInstance &&
        rootPlayback.expectedScheduleEpoch == rootView.scheduleEpoch &&
        rootPlayback.activeChildEpoch == childView.scheduleEpoch;
    trace.parentEpoch = childView.scheduleEpoch;
    const std::uint32_t current = row->selectedChildOrdinals[0];
    const std::uint32_t successor = row->QueueNextState().currentChildOrdinal;
    ASSERT_NE(current, successor);
    ASSERT_TRUE((current == 7u && successor == 8u) ||
                (current == 8u && successor == 7u));
    const VnObjectId expectedSound =
        successor == 8u ? CanonicalActionWorld::kSecondSound
                        : CanonicalActionWorld::kFirstSound;
    ASSERT_EQ(expectedSound, row->QueueSuccessorLeaf().stableId);
    trace.selectedOrdinals = {current, successor};
    trace.successorObserved = true;
    trace.successorOrdinal = successor;
    if (direct) {
        ASSERT_EQ(harken::PlayableControlStatus::Ok,
                  harken::StopPlayable(*engine, produced, 0));
    } else {
        ASSERT_EQ(VN_OK, Vn_StopActionFiring(firing, 0));
    }
    for (std::uint32_t block = 0; block < 128; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        if (!engine->playableInstances.Classify(produced).live) break;
    }
    trace.reclaimed = !engine->playableInstances.Classify(produced).live &&
                      engine->queueInstances.LiveCount() == 0 &&
                      engine->containerPlayback.LiveCount() == 0;
    trace.leafReclaimed =
        !engine->playableInstances.Classify(childHandle).live;
    trace.valid = trace.parentLinked && trace.reclaimed &&
                  trace.leafReclaimed && trace.successorObserved;
    if (!direct) ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    ASSERT_EQ(VN_OK, Vn_DestroyEmitter(emitter));
    if (outTrace != nullptr) *outTrace = trace;
}

void ExpectDirectContainerCompositeChild(harken::PlayableKindV1 childKind,
                                         harken::PlayableKind expectedKind) {
    (void)Vn_Term();
    harkentest::EngineSession session(harkentest::MakeNullConfig(8, 64, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> first(256, 0.25f);
    std::vector<float> second(256, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kSecondSound,
                             &secondPcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound)
            .contentRevision);
    image.MakeImmediateDirectContainerCompositePlayAction(childKind);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    VnEmitterHandle emitter = 0;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&emitter));
    const auto started = harken::StartCurrentPlayableByIdentity(
        harken::PlayableKindV1::Container, image.containers[0].containerStableId,
        emitter);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    ASSERT_NE(0u, started.instance);

    const auto root = engine->playableInstances.Classify(started.instance);
    ASSERT_TRUE(root.live);
    ASSERT_EQ(harken::PlayableKind::Container, root.kind);
    ASSERT_NE(0u, root.firstChild);
    const auto child = engine->playableInstances.Classify(root.firstChild);
    ASSERT_TRUE(child.live);
    EXPECT_EQ(expectedKind, child.kind);
    EXPECT_EQ(started.instance, child.parent);
    ASSERT_NE(0u, child.firstChild);
    const auto leaf = engine->playableInstances.Classify(child.firstChild);
    ASSERT_TRUE(leaf.live);
    EXPECT_EQ(harken::PlayableKind::Sound, leaf.kind);
    EXPECT_EQ(root.firstChild, leaf.parent);
    EXPECT_EQ(1u, engine->containerPlayback.LiveCount());

    ASSERT_EQ(harken::PlayableControlStatus::Ok,
              harken::StopPlayable(*engine, started.instance, 0));
    for (std::uint32_t block = 0; block < 128; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        if (!engine->playableInstances.Classify(started.instance).live) {
            break;
        }
    }
    EXPECT_FALSE(engine->playableInstances.Classify(started.instance).live);
    EXPECT_FALSE(engine->playableInstances.Classify(root.firstChild).live);
    EXPECT_FALSE(engine->playableInstances.Classify(child.firstChild).live);
    EXPECT_EQ(0u, engine->containerPlayback.LiveCount());
    EXPECT_EQ(0u, engine->voices.ActiveCount());
    ASSERT_EQ(VN_OK, Vn_DestroyEmitter(emitter));
}

