TEST(ActionFiringApi,
     ImmediateRandomQueuePlayCompletesAfterEveryRotatedChildRetires) {
    (void)Vn_Term();
    VnConfig config = harkentest::MakeNullConfig(8, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> first(64, 0.25f);
    std::vector<float> second(128, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kSecondSound,
                             &secondPcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound)
            .contentRevision);
    image.MakeImmediateRandomQueuePlayAction();
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    desc.callerSeed = 0x123456789abcdef0ULL;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&desc.emitter));
    harken::RandomQueueSeedContext expectedSeed{};
    expectedSeed.worldSemanticFingerprint =
        image.world.identity.runtimeSemanticFingerprint;
    expectedSeed.rootStableId = image.containers[2].containerStableId;
    expectedSeed.callerSeed = ExpectedImmediateActionPlayCallerSeed(
        image.actions[9], desc.callerSeed, 0);
    expectedSeed.acceptedPostOrdinal =
        engine->logicCommits.Current() + 1u;
    expectedSeed.emitterSlot = static_cast<std::uint32_t>(desc.emitter);
    expectedSeed.emitterGeneration =
        static_cast<std::uint32_t>(desc.emitter >> 32);
    expectedSeed.resetEpoch = engine->transportEpochOwner.Current();
    harken::EffectiveQueueState expectedInitial{};
    expectedInitial.version = 1;
    expectedInitial.selectionOrdinal = 1;
    std::array<harken::SelectionChildV1, 2> selectionChildren{};
    std::array<std::uint32_t, 2> remaining{};
    std::array<std::uint32_t, 2> permutation{};
    ASSERT_EQ(harken::SelectionStatusV1::Ok,
              harken::BuildRandomQueuePermutationV1(
                  image.containers[2], expectedSeed, expectedInitial,
                  selectionChildren.data(), remaining.data(),
                  permutation.data(), permutation.size()));
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));

    VnActionStepResult play{};
    play.structSize = sizeof(play);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
    ASSERT_NE(0u, play.producedPlayableInstance);
    const auto initialRow = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == play.producedPlayableInstance;
        });
    ASSERT_NE(engine->playableServices.end(), initialRow);
    const auto expectedChild = std::find_if(
        std::begin(image.queueChildren), std::end(image.queueChildren),
        [&](const harken::ContainerChildProgramViewV2& candidate) {
            return candidate.stableChildOrdinal == permutation[0];
        });
    ASSERT_NE(std::end(image.queueChildren), expectedChild);
    EXPECT_EQ(expectedChild->playable.stableId,
              initialRow->leaf.stableId);
    EXPECT_EQ(expectedSeed.callerSeed,
              initialRow->QueueRandomSeed().callerSeed);
    EXPECT_EQ(expectedSeed.acceptedPostOrdinal,
              initialRow->QueueRandomSeed().acceptedPostOrdinal);
    bool observedFirst = false;
    bool observedSecond = false;
    const auto observeCurrent = [&]() {
        const auto row = std::find_if(
            engine->playableServices.begin(), engine->playableServices.end(),
            [&](const harken::EnginePlayableServiceRow& candidate) {
                return candidate.rootInstance ==
                       play.producedPlayableInstance;
            });
        if (row == engine->playableServices.end()) {
            return;
        }
        observedFirst = observedFirst ||
            row->leaf.stableId == CanonicalActionWorld::kFirstSound;
        observedSecond = observedSecond ||
            row->leaf.stableId == CanonicalActionWorld::kSecondSound;
    };
    observeCurrent();

    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    for (std::uint32_t block = 0; block < 64; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        observeCurrent();
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
        if (info.state == VN_ACTION_FIRING_TERMINAL_RETAINED) {
            break;
        }
    }

    EXPECT_TRUE(observedFirst);
    EXPECT_TRUE(observedSecond);
    ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
    EXPECT_EQ(VN_ACTION_OUTCOME_SUCCEEDED, info.outcome);
    EXPECT_EQ(VN_ACTION_TERMINAL_NATURAL, info.terminalReason);
    EXPECT_EQ(0u, info.livePlayableCount);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
    EXPECT_EQ(VN_ACTION_STEP_SUCCEEDED, play.state);
    EXPECT_EQ(0u, engine->voices.ActiveCount());
    EXPECT_EQ(0u, engine->queueInstances.LiveCount());
    EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
}

TEST(ActionFiringApi,
     ImmediateRandomQueuePlayResumesTheStoredPermutationPosition) {
    (void)Vn_Term();
    VnConfig config = harkentest::MakeNullConfig(8, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> first(64, 0.25f);
    std::vector<float> second(128, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kSecondSound,
                             &secondPcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound)
            .contentRevision);
    image.MakeImmediateRandomQueuePlayAction();
    image.containers[2].resumePosition = 1;
    image.world.identity.runtimeSemanticFingerprint =
        harken::ComputeCurrentWorldFingerprintV4(image.world);
    const harken::WorldInstallResult installed =
        harken::InstallContainerWorldV1(*engine, image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok, installed.status);

    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    desc.callerSeed = 0x1020304050607080ULL;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&desc.emitter));
    harken::QueueCheckpointKey key{};
    key.world = installed.resultGeneration;
    key.containerStableId = image.containers[2].containerStableId;
    key.programSemanticFingerprint =
        image.containers[2].programSemanticFingerprint;
    key.resetEpoch = engine->transportEpochOwner.Current();
    key.emitterSlot = static_cast<std::uint32_t>(desc.emitter);
    key.emitterGeneration =
        static_cast<std::uint32_t>(desc.emitter >> 32);
    harken::QueueCheckpointImage checkpoint{};
    checkpoint.randomSeed.worldSemanticFingerprint =
        image.world.identity.runtimeSemanticFingerprint;
    checkpoint.randomSeed.rootStableId =
        image.containers[2].containerStableId;
    checkpoint.randomSeed.callerSeed = 0xa1a2a3a4a5a6a7a8ULL;
    checkpoint.randomSeed.acceptedPostOrdinal = 17;
    checkpoint.randomSeed.emitterSlot = key.emitterSlot;
    checkpoint.randomSeed.emitterGeneration = key.emitterGeneration;
    checkpoint.randomSeed.resetEpoch = key.resetEpoch;
    checkpoint.randomSeedValid = true;
    checkpoint.replayCurrent = true;
    checkpoint.effective.version = 2;
    checkpoint.effective.cursor = 1;
    checkpoint.effective.selectionOrdinal = 1;
    std::array<harken::SelectionChildV1, 2> selectionChildren{};
    std::array<std::uint32_t, 2> remaining{};
    std::array<std::uint32_t, 2> permutation{};
    ASSERT_EQ(harken::SelectionStatusV1::Ok,
              harken::BuildRandomQueuePermutationV1(
                  image.containers[2], checkpoint.randomSeed,
                  checkpoint.effective, selectionChildren.data(),
                  remaining.data(), permutation.data(),
                  permutation.size()));
    checkpoint.effective.currentChildOrdinal = permutation[1];
    ASSERT_TRUE(engine->queueCheckpoints.Store(key, checkpoint));

    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    VnActionStepResult play{};
    play.structSize = sizeof(play);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == play.producedPlayableInstance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    const auto expectedChild = std::find_if(
        std::begin(image.queueChildren), std::end(image.queueChildren),
        [&](const harken::ContainerChildProgramViewV2& candidate) {
            return candidate.stableChildOrdinal == permutation[1];
        });
    ASSERT_NE(std::end(image.queueChildren), expectedChild);
    EXPECT_EQ(expectedChild->playable.stableId, row->leaf.stableId);
    EXPECT_EQ(checkpoint.randomSeed.callerSeed,
              row->QueueRandomSeed().callerSeed);
    EXPECT_EQ(checkpoint.randomSeed.acceptedPostOrdinal,
              row->QueueRandomSeed().acceptedPostOrdinal);
    harken::QueueInstanceSnapshot queue{};
    ASSERT_TRUE(engine->queueInstances.Capture(row->queueInstance, &queue));
    EXPECT_EQ(checkpoint.effective.cursor, queue.logicMirror.cursor);
    EXPECT_EQ(checkpoint.effective.currentChildOrdinal,
              queue.logicMirror.currentChildOrdinal);

    const auto originalArm = row->arm;
    const auto originalRender = row->renderHandle;
    ASSERT_TRUE(originalArm.Valid());
    harken::VoiceReleaseObserver originalRelease{};
    ASSERT_TRUE(engine->voices.CaptureReleaseObserver(originalRender, &originalRelease));
    EXPECT_FALSE(engine->voices.ReleaseObserved(originalRelease));
    const bool positiveExpected = expectedChild->playable.stableId == CanonicalActionWorld::kFirstSound;
    bool originalStarted = false;
    float peak = 0.0f;
    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    for (std::uint32_t block = 0; block < 64; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        const auto beforeBlock = engine->mixer.BlocksRendered();
        engine->nullBackend.Pump(1);
        ASSERT_EQ(beforeBlock + 1u, engine->mixer.BlocksRendered());
        const auto* output = engine->nullBackend.LastBlock();
        for (std::uint32_t sample = 0; sample < config.blockFrames * engine->nullBackend.Channels(); ++sample) {
            peak = std::max(peak, std::abs(output[sample]));
            if (positiveExpected) EXPECT_GE(output[sample], -1.0e-5f);
            else EXPECT_LE(output[sample], 1.0e-5f);
        }
        harken::TimelineArmObservation originalObservation{};
        if (engine->timelineArms.Observe(originalArm, &originalObservation) &&
            originalObservation.startedBlockSequence != 0) {
            EXPECT_LE(originalObservation.startedBlockSequence, engine->mixer.BlocksRendered());
            originalStarted = true;
        }
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
        if (info.state == VN_ACTION_FIRING_TERMINAL_RETAINED) {
            break;
        }
    }
    ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
    EXPECT_EQ(VN_ACTION_OUTCOME_SUCCEEDED, info.outcome);
    EXPECT_EQ(0u, engine->voices.ActiveCount());
    EXPECT_EQ(0u, engine->queueInstances.LiveCount());
    EXPECT_TRUE(originalStarted);
    EXPECT_GT(peak, 0.005f);
    EXPECT_FALSE(engine->runtimeRecreateRequired);
    EXPECT_TRUE(engine->voices.ReleaseObserved(originalRelease));
    EXPECT_FALSE(engine->ledger.OwnerForRender(originalRender).live);
    EXPECT_FALSE(engine->playableInstances.Classify(play.producedPlayableInstance).live);
    EXPECT_EQ(0u, engine->playableInstances.LiveCount());
    EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
}

