TEST(ActionFiringApi,
     PreparedRandomQueueResumeRollsBackWithoutChangingItsCheckpoint) {
    (void)Vn_Term();
    VnConfig config = harkentest::MakeNullConfig(8, 64, 48000);
    config.emitterVariableSlots = 1;
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> first(64, 0.25f);
    std::vector<float> second(128, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kSecondSound,
                             &secondPcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound)
            .contentRevision);
    image.MakeImmediateSequenceQueuePlayThenEmitterSetValuesAction();
    image.containers[2].mode = harken::ContainerModeV1::RandomQueue;
    image.containers[2].randomDiscipline =
        harken::RandomDisciplineV1::Rotation;
    image.containers[2].resumePosition = 1;
    image.queueChildren[0].orderWeight = 1;
    image.queueChildren[1].orderWeight = 2;
    image.world.identity.capabilityMask &=
        ~harken::kWorldCapabilitySequenceQueue;
    image.world.identity.capabilityMask |=
        harken::kWorldCapabilityRandomQueue;
    image.world.identity.runtimeSemanticFingerprint =
        harken::ComputeCurrentWorldFingerprintV4(image.world);
    const harken::WorldInstallResult installed =
        harken::InstallContainerWorldV1(*engine, image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok, installed.status);

    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    desc.callerSeed = 0x9988776655443322ULL;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&desc.emitter));
    harken::QueueCheckpointKey key{};
    key.world = installed.resultGeneration;
    key.containerStableId = image.containers[2].containerStableId;
    key.programSemanticFingerprint =
        image.containers[2].programSemanticFingerprint;
    key.resetEpoch = engine->transportEpochOwner.Current();
    key.emitterSlot = static_cast<std::uint32_t>(desc.emitter);
    key.emitterGeneration =
        static_cast<std::uint32_t>(desc.emitter >> 32);
    harken::QueueCheckpointImage checkpoint{};
    checkpoint.randomSeed.worldSemanticFingerprint =
        image.world.identity.runtimeSemanticFingerprint;
    checkpoint.randomSeed.rootStableId =
        image.containers[2].containerStableId;
    checkpoint.randomSeed.callerSeed = 0x1122334455667788ULL;
    checkpoint.randomSeed.acceptedPostOrdinal = 23;
    checkpoint.randomSeed.emitterSlot = key.emitterSlot;
    checkpoint.randomSeed.emitterGeneration = key.emitterGeneration;
    checkpoint.randomSeed.resetEpoch = key.resetEpoch;
    checkpoint.randomSeedValid = true;
    checkpoint.replayCurrent = true;
    checkpoint.effective.version = 2;
    checkpoint.effective.cursor = 1;
    checkpoint.effective.selectionOrdinal = 1;
    std::array<harken::SelectionChildV1, 2> selectionChildren{};
    std::array<std::uint32_t, 2> remaining{};
    std::array<std::uint32_t, 2> permutation{};
    ASSERT_EQ(harken::SelectionStatusV1::Ok,
              harken::BuildRandomQueuePermutationV1(
                  image.containers[2], checkpoint.randomSeed,
                  checkpoint.effective, selectionChildren.data(),
                  remaining.data(), permutation.data(),
                  permutation.size()));
    checkpoint.effective.currentChildOrdinal = permutation[1];
    ASSERT_TRUE(engine->queueCheckpoints.Store(key, checkpoint));

    const std::uint64_t sequenceBefore = engine->logicCommits.IssuedCount();
    const std::uint64_t commandHeadBefore = engine->commands.PublishedHead();
    const std::uint32_t playableBefore =
        engine->playableInstances.LiveCount();
    const std::uint32_t playableHighWaterBefore =
        engine->playableInstances.HighWater();
    const std::uint32_t queueBefore = engine->queueInstances.LiveCount();
    const std::uint32_t decisionsBefore = engine->decisions.LiveCount();
    const std::uint32_t occurrencesBefore =
        engine->timelineOccurrences.OccupiedCount();
    const std::uint32_t occurrenceHighWaterBefore =
        engine->timelineOccurrences.HighWater();
    const std::uint32_t voicesBefore = engine->voices.ActiveCount();
    const std::uint32_t voiceHighWaterBefore =
        engine->voices.HighWaterVoices();
    const std::uint32_t armsBefore = engine->timelineArms.LiveCount();
    const std::uint32_t checkpointsBefore =
        engine->queueCheckpoints.LiveCount();

    VnActionFiringHandle firing = 99;
    EXPECT_EQ(VN_VARIABLE_EMITTER_SLOT_EXHAUSTED, Vn_PostAction(&desc, &firing));
    EXPECT_EQ(0u, firing);
    EXPECT_EQ(sequenceBefore, engine->logicCommits.IssuedCount());
    EXPECT_EQ(commandHeadBefore, engine->commands.PublishedHead());
    EXPECT_EQ(0u, engine->actionFirings.LiveCount());
    EXPECT_EQ(playableBefore, engine->playableInstances.LiveCount());
    EXPECT_EQ(playableHighWaterBefore,
              engine->playableInstances.HighWater());
    EXPECT_EQ(queueBefore, engine->queueInstances.LiveCount());
    EXPECT_EQ(decisionsBefore, engine->decisions.LiveCount());
    EXPECT_EQ(occurrencesBefore,
              engine->timelineOccurrences.OccupiedCount());
    EXPECT_EQ(occurrenceHighWaterBefore,
              engine->timelineOccurrences.HighWater());
    EXPECT_EQ(voicesBefore, engine->voices.ActiveCount());
    EXPECT_EQ(voiceHighWaterBefore, engine->voices.HighWaterVoices());
    EXPECT_EQ(armsBefore, engine->timelineArms.LiveCount());
    EXPECT_EQ(checkpointsBefore, engine->queueCheckpoints.LiveCount());
    EXPECT_FALSE(engine->runtimeRecreateRequired);
    harken::QueueCheckpointImage checkpointAfter{};
    ASSERT_TRUE(engine->queueCheckpoints.Load(key, &checkpointAfter));
    EXPECT_EQ(checkpoint.effective.version,
              checkpointAfter.effective.version);
    EXPECT_EQ(checkpoint.effective.cursor,
              checkpointAfter.effective.cursor);
    EXPECT_EQ(checkpoint.effective.currentChildOrdinal,
              checkpointAfter.effective.currentChildOrdinal);
    EXPECT_EQ(checkpoint.effective.selectionOrdinal,
              checkpointAfter.effective.selectionOrdinal);
    EXPECT_EQ(checkpoint.randomSeed.callerSeed,
              checkpointAfter.randomSeed.callerSeed);
    EXPECT_EQ(checkpoint.randomSeed.acceptedPostOrdinal,
              checkpointAfter.randomSeed.acceptedPostOrdinal);
    EXPECT_EQ(checkpoint.randomSeedValid,
              checkpointAfter.randomSeedValid);
    EXPECT_EQ(checkpoint.replayCurrent, checkpointAfter.replayCurrent);
}

TEST(ActionFiringApi, DefaultFactoryStorageLoanLetsSourceEndBeforeFinalServiceReclaim) {
    (void)Vn_Term();
    harkentest::EngineSession session(harkentest::MakeNullConfig(4, 64, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto& engine = *session.Engine();
    harken::Engine::OriginalPlayableServiceLifetimePin foreign;
    harken::Engine::OriginalPlayableServiceLifetimePin independent;
    std::vector<float> samples(512, 0.25f);
    const auto pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
    CanonicalActionWorld image(engine.registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision);
    image.MakeImmediateSoundPlayAction();
    ASSERT_EQ(harken::WorldInstallStatus::Ok, harken::InstallContainerWorldV1(engine, image.world).status);
    ASSERT_EQ(VN_OK, Vn_Update());
    engine.nullBackend.Pump(1);
    const auto owners = CaptureActionReclaimableOwners(engine);
    struct FactoryObservation {
        const harken::Engine::OriginalPlayableServiceLifetimeHolder* original = nullptr;
        unsigned calls = 0;
    } observed;
    engine.originalPlayableServiceReservedContextForTest = &observed;
    engine.originalPlayableServiceReservedHookForTest = [](harken::Engine& actual,
        const harken::Engine::OriginalPlayableServiceLifetimeHolder& original, void* context) {
        auto& observation = *static_cast<FactoryObservation*>(context);
        observation.original = &original;
        ++observation.calls;
        EXPECT_TRUE(original.Valid());
        ASSERT_TRUE(original.HasOriginalWorldNoPackDuty());
        EXPECT_EQ(harken::Engine::OriginalPlayableServicePackDuty::WorldNoPack, original.OriginalPackDuty());
        EXPECT_EQ(0u, original.OriginalPackDutyLease().leaseToken);
        ASSERT_TRUE(actual.MatchesOriginalPlayableServicePackDuty(original));
        const auto world = actual.variables.CurrentPlayableWorld();
        EXPECT_EQ(world.generation, original.OriginalWorldNoPackGeneration());
        EXPECT_EQ(world.identity.projectId, original.OriginalWorldNoPackProject());
        EXPECT_EQ(harken::ActionTargetKindV1::Sound, original.OriginalWorldNoPackTarget().kind);
        EXPECT_EQ(CanonicalActionWorld::kFirstSound, original.OriginalWorldNoPackTarget().stableId);
    };
    auto desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle firing = 0;
    const auto posted = Vn_PostAction(&desc, &firing);
    engine.originalPlayableServiceReservedHookForTest = nullptr;
    engine.originalPlayableServiceReservedContextForTest = nullptr;
    ASSERT_EQ(VN_OK, posted);
    ASSERT_EQ(1u, observed.calls);
    ASSERT_NE(nullptr, observed.original);
    const auto original = observed.original->FactoryReference();
    auto* row = harken::detail::EngineOriginalServiceStorageTestAccess::ActualService(*observed.original);
    ASSERT_NE(nullptr, row);
    ASSERT_TRUE(row->usesCapturedVoice);
    ASSERT_TRUE(row->capturedVoice.Valid());
    const auto* frozenVoice = row->capturedVoice.Input().facts;
    const auto partition = row->partition;
    harken::EngineTimelineVoiceInstallIdentity installation{};
    ASSERT_TRUE(engine.CaptureTimelineVoiceInstallIdentity(row->renderHandle, &installation));
    const auto* source = engine.originalSourceSubmissions.Find(installation.startArm);
    ASSERT_NE(nullptr, source);
    ASSERT_TRUE(observed.original->Borrow(&foreign));
    EXPECT_FALSE(observed.original->Borrow(&foreign));
    EXPECT_FALSE(foreign.Borrow(&foreign));
    ASSERT_TRUE(foreign.Borrow(&independent));
    harken::Engine::OriginalPlayableServiceLifetimePin moved(std::move(foreign));
    EXPECT_FALSE(foreign.Valid());
    ASSERT_TRUE(moved.Valid());
    foreign = std::move(moved);
    EXPECT_FALSE(moved.Valid());
    EXPECT_EQ(original.token, foreign.FactoryReference().token);
    EXPECT_EQ(original.invocationGeneration, foreign.FactoryReference().invocationGeneration);
    bool heard = false;
    for (unsigned block = 0; block < 96; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        const auto before = engine.mixer.BlocksRendered();
        engine.nullBackend.Pump(1);
        ASSERT_EQ(before + 1u, engine.mixer.BlocksRendered());
        if (!heard && harkentest::Peak(engine.nullBackend.LastBlock(),
                engine.nullBackend.BlockFrames() * engine.nullBackend.Channels()) > 0.01f) {
            harken::TimelineArmObservation started{};
            ASSERT_TRUE(engine.timelineArms.Observe(installation.startArm, &started));
            EXPECT_EQ(before + 1u, started.startedBlockSequence);
            heard = true;
        }
    }
    ASSERT_TRUE(heard);
    EXPECT_EQ(harken::OriginalSourceSubmissionRegistry::Phase::Disposed, source->State());
    EXPECT_TRUE(engine.voices.ReleaseObserved(installation.releaseObserver));
    EXPECT_EQ(0u, engine.voices.ActiveCount());
    ASSERT_TRUE(row->capturedVoice.Valid());
    EXPECT_EQ(frozenVoice, row->capturedVoice.Input().facts);
    EXPECT_TRUE(foreign.Valid());
    EXPECT_TRUE(observed.original->Valid());
    EXPECT_TRUE(observed.original->HasOriginalWorldNoPackDuty());
    EXPECT_TRUE(engine.MatchesOriginalPlayableServicePackDuty(*observed.original));
    EXPECT_EQ(CanonicalActionWorld::kFirstSound, observed.original->OriginalWorldNoPackTarget().stableId);
    EXPECT_EQ(original.token, row->identity);
    EXPECT_EQ(original.invocationGeneration, row->Invocation().generation);
    EXPECT_GT(row->Invocation().serviceCount, 0u);
    const auto nativeEnd = engine.mixer.BlocksRendered();
    ASSERT_TRUE(engine.playablePartitions.CanRelease(partition, original.token, nativeEnd));
    EXPECT_FALSE(engine.CanReclaimOriginalPlayableServiceStorage(*row));
    for (unsigned block = 0; block < 4; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine.nullBackend.Pump(1);
    }
    EXPECT_TRUE(engine.playablePartitions.CanRelease(partition, original.token, nativeEnd));
    EXPECT_FALSE(engine.runtimeRecreateRequired);
    foreign.Return();
    EXPECT_FALSE(foreign.Valid());
    EXPECT_FALSE(foreign.FactoryReference().Valid());
    ASSERT_TRUE(independent.Valid());
    EXPECT_FALSE(engine.CanReclaimOriginalPlayableServiceStorage(*row));
    ASSERT_TRUE(row->capturedVoice.Valid());
    EXPECT_EQ(frozenVoice, row->capturedVoice.Input().facts);
    independent.Return();
    EXPECT_FALSE(independent.Valid());
    EXPECT_TRUE(engine.CanReclaimOriginalPlayableServiceStorage(*row));
    for (unsigned block = 0; block < 64 && engine.playablePartitions.OccupiedCount() != 0; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine.nullBackend.Pump(1);
    }
    EXPECT_EQ(0u, engine.playablePartitions.OccupiedCount());
    EXPECT_FALSE(row->capturedVoice.Valid());
    EXPECT_FALSE(observed.original->Valid());
    EXPECT_FALSE(observed.original->HasOriginalWorldNoPackDuty());
    EXPECT_FALSE(engine.MatchesOriginalPlayableServicePackDuty(*observed.original));
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    for (unsigned block = 0; block < 64 && CaptureActionReclaimableOwners(engine) != owners; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine.nullBackend.Pump(1);
    }
    EXPECT_EQ(owners, CaptureActionReclaimableOwners(engine));
    EXPECT_FALSE(engine.runtimeRecreateRequired);
}

TEST(ActionFiringApi, MixedActionPublishesCommandsAfterVariableAndDeferredOwners) {
    (void)Vn_Term();
    harkentest::EngineSession session(harkentest::MakeNullConfig(4, 64, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    std::vector<float> samples(4096, 0.25f);
    const auto pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision);
    image.MakeImmediateSoundPlayAction();
    image.steps[12] = image.steps[0];
    image.steps[12].authoredEventIndex = 1;
    image.steps[13] = image.steps[0];
    image.steps[13].authoredEventIndex = 2;
    image.steps[13].valueBits = std::bit_cast<std::uint32_t>(0.75f);
    SetAbsoluteTime(&image.steps[13].delay, 1000000000);
    image.actions[9].stepCount = 3;
    image.actions[9].directFeatureMask = 1;
    image.actions[9].transitiveFeatureMask = 1;
    image.actions[9].expandedStepOccurrenceCount = 3;
    image.actions[9].programSemanticFingerprint =
        harken::ComputeActionProgramFingerprintV1(image.actions[9]);
    image.world.identity.runtimeSemanticFingerprint =
        harken::ComputeCurrentWorldFingerprintV4(image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
        harken::InstallContainerWorldV1(*engine, image.world).status);
    ASSERT_EQ(VN_OK, Vn_Update());
    engine->nullBackend.Pump(1);

    struct Observation {
        std::uint64_t head = 0;
        std::uint64_t initialHead = 0;
        std::uint32_t calls = 0;
        VnObjectId variable{};
    } observation{engine->commands.PublishedHead(), engine->commands.InitialSourcePublishedHead(),
        0, image.variables[0].variableId};
    engine->voiceCommandBatchPublishHookContextForTest = &observation;
    engine->voiceCommandBatchPublishHookForTest = [](harken::Engine& current, void* opaque) {
        auto& observed = *static_cast<Observation*>(opaque);
        ++observed.calls;
        EXPECT_EQ(observed.head, current.commands.PublishedHead());
        EXPECT_EQ(observed.initialHead, current.commands.InitialSourcePublishedHead());
        EXPECT_EQ(0u, current.actionDeferredRecords.PreparedCount());
        EXPECT_EQ(1u, current.actionDeferredRecords.LiveCount());
        VnVariableQueryDescV1 query{};
        query.structSize = sizeof(query);
        query.variableId = observed.variable;
        VnVariableQueryResultV1 result{};
        result.structSize = sizeof(result);
        ASSERT_EQ(VN_OK, Vn_QueryVariable(&query, &result));
        EXPECT_EQ(1u, result.pendingCount);
        EXPECT_FLOAT_EQ(0.0f, result.currentValue);
        const auto before = current.mixer.BlocksRendered();
        current.nullBackend.Pump(1);
        EXPECT_EQ(before + 1u, current.mixer.BlocksRendered());
        EXPECT_EQ(observed.head, current.commands.PublishedHead());
        EXPECT_EQ(observed.initialHead, current.commands.InitialSourcePublishedHead());
        EXPECT_FLOAT_EQ(0.0f, harkentest::Peak(current.nullBackend.LastBlock(),
            current.nullBackend.BlockFrames() * current.nullBackend.Channels()));
    };
    auto desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle firing = 0;
    const auto posted = Vn_PostAction(&desc, &firing);
    engine->voiceCommandBatchPublishHookForTest = nullptr;
    engine->voiceCommandBatchPublishHookContextForTest = nullptr;
    ASSERT_EQ(VN_OK, posted);
    ASSERT_NE(0u, firing);
    EXPECT_EQ(1u, observation.calls);
    EXPECT_TRUE(engine->commands.PublishedHead() > observation.head ||
        engine->commands.InitialSourcePublishedHead() > observation.initialHead);
    bool heardNewBlock = false;
    for (unsigned block = 0; block < 12; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        const auto before = engine->mixer.BlocksRendered();
        engine->nullBackend.Pump(1);
        ASSERT_EQ(before + 1u, engine->mixer.BlocksRendered());
        heardNewBlock = heardNewBlock || harkentest::Peak(engine->nullBackend.LastBlock(),
            engine->nullBackend.BlockFrames() * engine->nullBackend.Channels()) > 0.01f;
    }
    EXPECT_TRUE(heardNewBlock);
    ASSERT_EQ(VN_OK, Vn_StopActionFiring(firing, 0));
    for (unsigned block = 0; block < 32; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    EXPECT_EQ(0u, engine->actionDeferredRecords.LiveCount());
    EXPECT_EQ(0u, engine->actionDeferredRecords.PreparedCount());
    EXPECT_EQ(0u, engine->voices.ActiveCount());
    EXPECT_FALSE(engine->runtimeRecreateRequired);
}

TEST(ActionFiringApi, PostExpandsNestedActionsDepthFirstUnderOneSequence) {
    (void)Vn_Term();
    harkentest::EngineSession session(harkentest::MakeNullConfig());
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    CanonicalActionWorld image;
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = harkentest::ObjectId(43);
    VnActionFiringHandle root = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &root));
    ASSERT_NE(0u, root);

    VnActionFiringInfo rootInfo{};
    rootInfo.structSize = sizeof(rootInfo);
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(root, &rootInfo));
    EXPECT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, rootInfo.state);
    EXPECT_EQ(VN_ACTION_OUTCOME_SUCCEEDED, rootInfo.outcome);
    EXPECT_EQ(1u, rootInfo.directStepCount);
    EXPECT_EQ(1u, rootInfo.childFiringCount);

    VnActionStepResult post{};
    post.structSize = sizeof(post);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(root, 0, &post));
    EXPECT_EQ(VN_ACTION_STEP_SUCCEEDED, post.state);
    EXPECT_EQ(VN_ACTION_OPCODE_POST_ACTION, post.opcode);
    EXPECT_EQ(0u, post.executionOrdinal);
    EXPECT_EQ(1u, post.depth);
    ASSERT_NE(0u, post.childFiring);

    VnActionFiringInfo childInfo{};
    childInfo.structSize = sizeof(childInfo);
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(post.childFiring, &childInfo));
    EXPECT_EQ(root, childInfo.parentFiring);
    EXPECT_EQ(harkentest::ObjectId(41u), childInfo.actionId);
    EXPECT_EQ(rootInfo.acceptedLogicSequence,
              childInfo.acceptedLogicSequence);
    EXPECT_EQ(VN_ACTION_OUTCOME_SUCCEEDED, childInfo.outcome);

    VnActionStepResult childStep{};
    childStep.structSize = sizeof(childStep);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(post.childFiring, 0, &childStep));
    EXPECT_EQ(VN_ACTION_OPCODE_SET_VARIABLE, childStep.opcode);
    EXPECT_EQ(1u, childStep.executionOrdinal);
    EXPECT_EQ(2u, childStep.depth);
    EXPECT_EQ(rootInfo.acceptedLogicSequence,
              childStep.logicCommitSequence);

    EXPECT_EQ(VN_IN_USE, Vn_ReleaseActionFiring(post.childFiring));
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(root));
    childInfo = {};
    childInfo.structSize = sizeof(childInfo);
    EXPECT_EQ(VN_STALE_HANDLE,
              Vn_QueryActionFiring(post.childFiring, &childInfo));
}

TEST(ActionFiringApi, TenThousandStepsPreserveCompletePublicResults) {
    (void)Vn_Term();
    harkentest::EngineSession session(harkentest::MakeNullConfig());
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    CanonicalActionWorld image;
    std::vector<harken::ActionStepProgramViewV1> steps(10000, image.steps[0]);
    for (std::uint32_t index = 0; index < steps.size(); ++index) {
        auto& step = steps[index];
        step.opcode = harken::ActionOpcodeV1::Stop;
        step.target.kind = harken::ActionTargetKindV1::Sound;
        step.target.stableId = image.properties[0].stableId;
        step.target.expectedProgramSemanticFingerprint = image.properties[0].programSemanticFingerprint;
        step.authoredEventIndex = index;
        step.valueBits = 0;
    }
    auto& action = image.actions[0];
    action.steps = steps.data();
    action.stepCount = action.expandedStepOccurrenceCount = static_cast<std::uint32_t>(steps.size());
    action.programSemanticFingerprint = harken::ComputeActionProgramFingerprintV1(action);
    image.world.actionCount = 1;
    image.world.capacity.maxActionStepsPerDefinition = action.stepCount;
    image.world.capacity.maxActionStepsTotal = action.stepCount;
    image.world.capacity.maxActionExpandedWork = action.stepCount;
    image.world.identity.runtimeSemanticFingerprint = harken::ComputeCurrentWorldFingerprintV4(image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok, harken::InstallContainerWorldV1(*engine, image.world).status);

    auto desc = ValidPostDesc();
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
    EXPECT_EQ(action.stepCount, info.directStepCount);
    EXPECT_EQ(action.stepCount, info.directStepTerminalCount);
    EXPECT_EQ(VN_ACTION_OUTCOME_SUCCEEDED, info.outcome);
    VnActionStepResult step{};
    step.structSize = sizeof(step);
    for (std::uint32_t index = 0; index < action.stepCount; ++index) {
        ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, index, &step));
        ASSERT_EQ(VN_ACTION_STEP_NO_OP, step.state);
        EXPECT_EQ(index, step.authoredEventIndex);
        EXPECT_EQ(index, step.executionOrdinal);
    }
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    EXPECT_EQ(VN_STALE_HANDLE, Vn_QueryActionStep(firing, 0, &step));
}

