    harken::OriginalImmediateLaneAttemptLifetimePin laneLoan;
    if (stopWithLaneLoan) ASSERT_TRUE(attempt->originalLaneLifetime.Borrow(&laneLoan));
    const bool stopAll = stoppedMember == accepted.size() || earlyStopFollowup == 2;
