TEST(ActionFiringApi,
     ScheduleCapacityVariableControl64Source64TargetAndControllerRefusesWithoutPartialInstall) {
    (void)Vn_Term();
    auto config = harkentest::MakeNullConfig(256, 256, 48000);
    config.fxSlotsPerVoice = 1;
    config.delayEffectPoolCapacity = 64;
    config.commandQueueDepth = 1024;
    config.maxControlCommandsPerQuantum = 256;
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    auto& engine = *session.Engine();
    std::vector<float> sourceSamples(32768, 0.25f);
    std::vector<float> targetSamples(256, -0.25f);
    const auto sourcePcm = harkentest::MonoDesc(sourceSamples, 48000);
    const auto targetPcm = harkentest::MonoDesc(targetSamples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(ActionScheduleCapacityWorld::kSound, &sourcePcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(ActionScheduleCapacityWorld::kTargetSound, &targetPcm));
    ActionScheduleCapacityWorld image(64, 64, ActionScheduleCapacityTransitionRoot::VariableControl,
        engine.registry.Lookup(ActionScheduleCapacityWorld::kSound).contentRevision,
        engine.registry.Lookup(ActionScheduleCapacityWorld::kTargetSound).contentRevision);
    ASSERT_EQ(harken::WorldInstallStatus::Ok, harken::InstallContainerWorldV1(engine, image.world).status);
    const auto empty = CaptureActionPreparationOwners(engine);
    auto desc = ValidPostDesc();
    desc.actionId = ActionScheduleCapacityWorld::kAction;
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    VnActionStepResult play{};
    play.structSize = sizeof(play);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
    const auto row = std::find_if(engine.playableServices.begin(), engine.playableServices.end(),
        [&](const auto& candidate) { return candidate.ownerInstance == play.producedPlayableInstance; });
    ASSERT_NE(engine.playableServices.end(), row);
    FrontierTrace trace;
    for (std::uint32_t block = 0; block < 8; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine.nullBackend.Pump(1);
        trace.Capture(engine);
    }
    ASSERT_EQ(VN_OK, Vn_Update());
    ASSERT_EQ(64u, trace.heard.size());
    ASSERT_EQ(64u, engine.voices.ActiveCount());
    const auto incumbent = CaptureActionPreparationOwners(engine);
    harken::VariableControlInstanceSnapshot before{};
    ASSERT_TRUE(engine.variableControlInstances.Capture(row->variableControlInstance, &before));
    const auto child = row->variableControlDiscreteCurrentChildOrdinal;
    const auto entry = row->frontierLifetimeEntry;
    for (std::uint32_t block = 0; block < 3; ++block) {
        SCOPED_TRACE(block);
        engine.nullBackend.Pump(1);
        trace.Capture(engine);
        ASSERT_EQ(VN_OK, Vn_Update());
        EXPECT_FALSE(row->variableControlDiscreteRetargetPrepared);
        EXPECT_EQ(64u, row->variableControlDiscreteMemberCount);
        EXPECT_EQ(child, row->variableControlDiscreteCurrentChildOrdinal);
        EXPECT_TRUE(entry == row->frontierLifetimeEntry);
        harken::VariableControlInstanceSnapshot after{};
        ASSERT_TRUE(engine.variableControlInstances.Capture(row->variableControlInstance, &after));
        EXPECT_EQ(before.discrete.state, after.discrete.state);
        EXPECT_EQ(before.discrete.decision.slot, after.discrete.decision.slot);
        EXPECT_EQ(before.discrete.decision.generation, after.discrete.decision.generation);
        EXPECT_EQ(before.discrete.lastApplied.slot, after.discrete.lastApplied.slot);
        EXPECT_EQ(before.discrete.lastApplied.generation, after.discrete.lastApplied.generation);
        const auto current = CaptureActionPreparationOwners(engine);
        EXPECT_EQ(incumbent.playableLive, current.playableLive);
        EXPECT_EQ(incumbent.variableControlLive, current.variableControlLive);
        EXPECT_EQ(incumbent.decisionLive, current.decisionLive);
        EXPECT_EQ(incumbent.transitionLive, current.transitionLive);
        EXPECT_EQ(incumbent.armGroupLive, current.armGroupLive);
        EXPECT_EQ(incumbent.voiceActive, current.voiceActive);
        EXPECT_EQ(incumbent.ledgerAvailable, current.ledgerAvailable);
        EXPECT_EQ(incumbent.armLive, current.armLive);
        EXPECT_EQ(incumbent.occurrenceOccupied, current.occurrenceOccupied);
        EXPECT_EQ(incumbent.compositeOccupied, current.compositeOccupied);
        EXPECT_EQ(incumbent.delayInUse, current.delayInUse);
        EXPECT_EQ(incumbent.transactionLive, current.transactionLive);
        EXPECT_EQ(incumbent.occupiedStartRows, current.occupiedStartRows);
        EXPECT_EQ(incumbent.occupiedQueueProgramBanks, current.occupiedQueueProgramBanks);
        EXPECT_FALSE(engine.runtimeRecreateRequired);
    }
    ASSERT_EQ(64u, trace.heard.size());
    for (const auto& heard : trace.heard) {
        EXPECT_EQ(ActionScheduleCapacityWorld::kSound, heard.subject);
        EXPECT_EQ(heard.expectedStart, heard.start);
        EXPECT_EQ(0u, heard.complete);
    }
    ASSERT_EQ(VN_OK, Vn_StopActionFiring(firing, 0));
    for (std::uint32_t block = 0; block < 32; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine.nullBackend.Pump(1);
    }
    ASSERT_EQ(VN_OK, Vn_Update());
    EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    const auto final = CaptureActionPreparationOwners(engine);
    EXPECT_EQ(empty.firingLive, final.firingLive);
    EXPECT_EQ(empty.playableLive, final.playableLive);
    EXPECT_EQ(empty.variableControlLive, final.variableControlLive);
    EXPECT_EQ(empty.decisionLive, final.decisionLive);
    EXPECT_EQ(empty.transitionLive, final.transitionLive);
    EXPECT_EQ(empty.armGroupLive, final.armGroupLive);
    EXPECT_EQ(empty.voiceActive, final.voiceActive);
    EXPECT_EQ(empty.ledgerAvailable, final.ledgerAvailable);
    EXPECT_EQ(empty.armLive, final.armLive);
    EXPECT_EQ(empty.occurrenceOccupied, final.occurrenceOccupied);
    EXPECT_EQ(empty.compositeOccupied, final.compositeOccupied);
    EXPECT_EQ(empty.delayInUse, final.delayInUse);
    EXPECT_EQ(empty.transactionLive, final.transactionLive);
    EXPECT_EQ(empty.occupiedStartRows, final.occupiedStartRows);
    EXPECT_EQ(empty.occupiedQueueProgramBanks, final.occupiedQueueProgramBanks);
    EXPECT_FALSE(engine.runtimeRecreateRequired);
}

