TEST(ActionFiringApi,
     PreparationMatrixQueueReplacementTransitionCapacityReturnsBackpressure) {
    (void)Vn_Term();
    harkentest::EngineSession session(
        harkentest::MakeNullConfig(4, 64, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> first(512, 0.25f);
    std::vector<float> second(512, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kSecondSound,
                             &secondPcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound)
            .contentRevision);
    image.containers[2].queueCycle = harken::QueueCycleV1::Loop;
    image.containers[2].resumePosition = 1;
    image.EnableImmediateQueueTransition(64, 128);
    const auto installed =
        harken::InstallContainerWorldV1(*engine, image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok, installed.status);
    VnEmitterHandle emitter = 0;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&emitter));

    const harken::QueueCheckpointKey checkpointKey =
        CanonicalQueueCheckpointKey(*engine, image, emitter);
    harken::QueueCheckpointImage checkpoint{};
    checkpoint.effective.version = 7;
    checkpoint.effective.cursor = 1;
    checkpoint.effective.currentChildOrdinal =
        image.queueChildren[1].stableChildOrdinal;
    checkpoint.effective.selectionOrdinal = 3;
    checkpoint.replayCurrent = true;
    ASSERT_TRUE(engine->queueCheckpoints.Store(checkpointKey, checkpoint));
    harken::EnginePlayableServiceRow* row =
        StartCanonicalQueueForActionReset(*engine, image, emitter);
    ASSERT_NE(nullptr, row);
    ASSERT_TRUE(row->queueContinuationPrepared);
    ASSERT_TRUE(row->QueueFiling().queueTransition.Valid());
    const harken::DecisionToken decisionBefore = row->QueueFiling().queueDecision;
    const harken::ConditionalQueueVersionToken conditionalBefore =
        row->QueueFiling().queueConditional;
    const VnVoiceHandle successorBefore = row->QueuePayload().queueSuccessorRenderHandle;
    const harken::TransitionInstanceToken transitionBefore =
        row->QueueFiling().queueTransition;
    harken::QueueInstanceSnapshot queueBefore{};
    ASSERT_TRUE(engine->queueInstances.Capture(row->queueInstance,
                                               &queueBefore));

    std::vector<harken::TransitionInstanceToken> occupied(
        engine->transitionInstances.FreeCount());
    for (auto& token : occupied) {
        ASSERT_TRUE(engine->transitionInstances.Acquire({0, 0}, &token));
    }
    ASSERT_EQ(0u, engine->transitionInstances.FreeCount());
    const auto before = CaptureActionPreparationOwners(*engine);

    ExpectPublicActionPreparationRefusal(
        *engine, harkentest::ObjectId(49), emitter, VN_BACKPRESSURE, before);

    EXPECT_EQ(decisionBefore.slot, row->QueueFiling().queueDecision.slot);
    EXPECT_EQ(decisionBefore.generation, row->QueueFiling().queueDecision.generation);
    EXPECT_EQ(conditionalBefore.version, row->QueueFiling().queueConditional.version);
    EXPECT_EQ(successorBefore, row->QueuePayload().queueSuccessorRenderHandle);
    EXPECT_EQ(transitionBefore.slot, row->QueueFiling().queueTransition.slot);
    EXPECT_EQ(transitionBefore.generation,
              row->QueueFiling().queueTransition.generation);
    harken::QueueInstanceSnapshot queueAfter{};
    ASSERT_TRUE(engine->queueInstances.Capture(row->queueInstance,
                                               &queueAfter));
    EXPECT_EQ(queueBefore.pendingVersion, queueAfter.pendingVersion);
    EXPECT_EQ(queueBefore.resetPending, queueAfter.resetPending);
    for (const auto token : occupied) {
        EXPECT_TRUE(engine->transitionInstances.CancelBeforePublication(token));
    }
}

