#if defined(HARKEN_TEST_TIMELINE_CAPACITY_OVERRIDE)
TEST(ActionFiringApi, OriginalSourcePrivatePageDispositionSurvivesOwnerRefusalAndActualRegistryReuse) {
    (void)Vn_Term();
    harken::detail::ScopedTimelineCapacityOverrideForTest capacity(32u, 16u, 8u);
    ASSERT_TRUE(capacity.Valid());
    harkentest::EngineSession session(harkentest::MakeNullConfig(16, 64, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto& engine = *session.Engine();
    std::vector<float> first(48000, 0.25f), second(48000, -0.25f);
    const auto firstPcm = harkentest::MonoDesc(first, 48000);
    const auto secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &secondPcm));
    CanonicalActionWorld image(engine.registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
        engine.registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
    image.MakeSetValueThenImmediateMixedVariableControlPlayAction();
    // This path batches one authored physical member on each VariableControl side.
    image.containers[3].continuousRowCount = 1;
    image.containers[3].continuousRows = &image.variableControlOverlayRows[1];
    const auto pageFrame = std::max(engine.timelinePool.PublishCutoffFrame(),
        static_cast<std::uint64_t>(engine.config.blockFrames) *
            std::max<std::uint64_t>(1u, engine.config.publishLeadQuanta)) + engine.config.blockFrames;
    image.DelaySetValueThenVariableControlPlay(0, DelayNanosecondsForTargetFrame(engine, pageFrame));
    image.steps[13] = image.steps[12];
    image.steps[13].authoredEventIndex = 2;
    image.actions[9].stepCount = 3;
    image.actions[9].expandedStepOccurrenceCount = 3;
    image.actions[9].programSemanticFingerprint = harken::ComputeActionProgramFingerprintV1(image.actions[9]);
    harken::ActionStepProgramViewV1 independentStep{};
    independentStep.target.kind = harken::ActionTargetKindV1::Sound;
    independentStep.target.stableId = image.properties[0].stableId;
    independentStep.target.expectedProgramSemanticFingerprint = image.properties[0].programSemanticFingerprint;
    SetAbsoluteTime(&independentStep.delay);
    SetAbsoluteTime(&independentStep.fade);
    SetAbsoluteTime(&independentStep.cooldown);
    image.actions[8].steps = &independentStep;
    image.actions[8].stepCount = 1;
    image.actions[8].expandedStepOccurrenceCount = 1;
    image.actions[8].expandedFiringCount = 1;
    image.actions[8].directFeatureMask = image.actions[8].transitiveFeatureMask = 0;
    image.actions[8].programSemanticFingerprint = harken::ComputeActionProgramFingerprintV1(image.actions[8]);
    image.world.identity.runtimeSemanticFingerprint = harken::ComputeCurrentWorldFingerprintV4(image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok, harken::InstallContainerWorldV1(engine, image.world).status);
    auto desc = ValidPostDesc();
    desc.actionId = image.actions[8].actionStableId;
    VnActionFiringHandle independentFiring = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &independentFiring));
    harken::CommandRecord independentHeader{};
    const auto independentCut = engine.commands.CaptureBlockInputCut();
    if (const auto* initial = engine.commands.InitialSourceAtFront(independentCut.initialHead)) {
        ASSERT_NE(nullptr, initial->facts);
        independentHeader = initial->facts[0];
    } else {
        ASSERT_TRUE(engine.commands.Peek(independentHeader));
    }
    ASSERT_EQ(harken::kOpcodePlay, independentHeader.opcode);
    const auto independentArm = harken::OriginalSourceSubmissionRegistry::TokenOf(independentHeader);
    struct Probe {
        harken::EngineActionPlayScratch* scratch = nullptr;
        harken::EnginePreparedTimelineVoiceStart* oldStart = nullptr;
        harken::EngineActionPlayScratch::PreparedTimelineVoiceOwnerContext* oldOwner = nullptr;
        harken::EngineTimelineVoiceInstallIdentity independent{};
        harken::ProgramGeneration programGeneration = 0;
        harken::PlayableWorldViewV1 propertyWorld{};
        harken::PlayableRefV1 sound{};
        std::vector<harken::EngineTimelineVoiceInstallIdentity> fresh;
        harken::TimelineArmToken oldArm{};
        VnVoiceHandle oldRender = 0;
        unsigned calls = 0;
        bool pageWithdrawn = false, registryReused = false, renderReused = false;
    } probe;
    ASSERT_TRUE(engine.CaptureTimelineVoiceInstallIdentity(independentHeader.payload.play.handle, &probe.independent));
    ASSERT_NE(0u, probe.independent.rootInstance);
    probe.programGeneration = engine.timelineArms.RowAt(independentArm.slot)->programGeneration;
    probe.propertyWorld.generation = 1;
    probe.propertyWorld.identity = image.world.identity;
    probe.propertyWorld.properties = image.world.playableProperties;
    probe.propertyWorld.propertyCount = image.world.playablePropertyCount;
    probe.sound = image.child.playable;
    struct ResetHooks {
        harken::Engine& engine;
        ~ResetHooks() {
            harken::detail::SetTimelineVoiceOwnerRollbackRefusalHookForTest(nullptr, nullptr);
            engine.privateInitialVcPageBatchHookForTest = nullptr;
            engine.privateInitialVcPageBatchContextForTest = nullptr;
        }
    } reset{engine};
    engine.privateInitialVcPageBatchContextForTest = &probe;
    engine.privateInitialVcPageBatchHookForTest = [](harken::Engine& current,
        harken::EngineActionPlayScratch& scratch, std::uint32_t position, void* opaque) {
        auto& actual = *static_cast<Probe*>(opaque);
        if (position != 1 || actual.scratch != nullptr) return;
        ASSERT_NE(nullptr, scratch.row);
        ASSERT_EQ(1u, scratch.row->variableControlInitialDiscreteMemberCount);
        ASSERT_EQ(1u, scratch.row->variableControlInitialContinuousMemberCount);
        ASSERT_EQ(2u, scratch.voiceStartCount);
        ASSERT_TRUE(scratch.queueTransactions.Held());
        ASSERT_TRUE(scratch.privateInitialVcPageCohort.pageBatchTransferProof.Valid());
        actual.scratch = &scratch;
        scratch.privateInitialVcPageCohort.pageBatchTransferProof.Release();
        current.forceActionTimelineVoiceOwnerRollbackFailureForTest = true;
    };
    harken::detail::SetTimelineVoiceOwnerRollbackRefusalHookForTest([](harken::Engine& current,
        harken::EnginePreparedTimelineVoiceStart& old, void* opaque) {
        auto& actual = *static_cast<Probe*>(opaque);
        ++actual.calls;
        ASSERT_NE(nullptr, actual.scratch);
        actual.oldStart = &old;
        for (auto& owner : actual.scratch->voiceStarts.Owners()) {
            if (owner.token == &old) actual.oldOwner = &owner;
        }
        ASSERT_NE(nullptr, actual.oldOwner);
        ASSERT_TRUE(actual.oldOwner->committed);
        ASSERT_FALSE(old.voiceOwnershipHeld);
        ASSERT_TRUE(current.voices.ReleaseObserved(old.releaseObserver));
        ASSERT_EQ(harken::ArmState::Free, current.timelineArms.RowAt(old.arm.slot)->state.load());
        ASSERT_FALSE(current.timelineArms.RowAt(old.arm.slot)->originalLifetimePinned.load());
        const auto page = current.timelinePool.CapturePrivateMaterializationSnapshotForTest();
        ASSERT_EQ(0u, page.preparedEvents);
        ASSERT_EQ(0u, page.publicationHolds);
        actual.pageWithdrawn = true;
        actual.oldArm = old.arm;
        actual.oldRender = old.renderHandle;
        EXPECT_NE(actual.independent.rootInstance, old.ledgerPreparation.parent.internalToken);
        constexpr auto freshBinding = harkentest::ObjectId(99033);
        VnBindingDesc binding{};
        binding.structSize = sizeof(binding);
        binding.variableId = harkentest::ObjectId(8);
        binding.targetScopeKind = VN_TARGET_SCOPE_VOICE;
        binding.targetId = harken::kTargetVoiceVolume;
        binding.curve.structSize = sizeof(binding.curve);
        binding.curve.pointCount = 2;
        binding.curve.points[0] = {-1.0f, -6.0f};
        binding.curve.points[1] = {1.0f, -6.0f};
        binding.curve.handles[0] = harkentest::EndpointHandles(binding.curve.points[0], binding.curve.points[1]);
        ASSERT_EQ(VN_OK, Vn_RegisterBinding(freshBinding, &binding));
        VnBindingAttachDesc attach{};
        attach.structSize = sizeof(attach);
        attach.scopeKind = VN_TARGET_SCOPE_VOICE;
        attach.objectId = CanonicalActionWorld::kFirstSound;
        ASSERT_FALSE(current.variables.AdmissionClosed());
        ASSERT_TRUE(current.variables.HasBlockingWrite(harkentest::ObjectId(7)));
        ASSERT_FALSE(current.variables.HasBlockingWrite(binding.variableId));
        ASSERT_EQ(VN_OK, Vn_AttachBinding(freshBinding, &attach));
        harken::ResolvedPlayablePropertyCutStorageV1 storage;
        ASSERT_TRUE(storage.Reset({}));
        ASSERT_EQ(harken::ResolvedPlayablePropertyCutStatusV1::Ok,
            storage.Resolve(actual.propertyWorld, actual.sound, nullptr, 0));
        harken::TimelineVoiceInstallDesc install{};
        ASSERT_EQ(harken::PlayableStartStatus::Accepted,
            harken::test::BuildTimelineVoiceInstallFromCut(current, storage.View(), &install));
        ASSERT_EQ(1u, install.bindingCount);
        for (unsigned i = 0; i < 12 && (!actual.registryReused || !actual.renderReused); ++i) {
            const auto installed = harken::test::InstallTimelineVoiceStart(current, install,
                actual.programGeneration, actual.independent.rootInstance, actual.independent.rootInstance);
            ASSERT_EQ(VN_OK, installed.status);
            harken::EngineTimelineVoiceInstallIdentity fresh{};
            ASSERT_TRUE(current.CaptureTimelineVoiceInstallIdentity(installed.renderHandle, &fresh));
            actual.fresh.push_back(fresh);
            if (static_cast<std::uint32_t>(fresh.renderHandle) ==
                    static_cast<std::uint32_t>(old.renderHandle)) {
                EXPECT_NE(old.renderHandle, fresh.renderHandle);
                actual.renderReused = true;
            }
            if (fresh.startArm.slot == old.arm.slot) {
                EXPECT_NE(old.arm.generation, fresh.startArm.generation);
                actual.registryReused = true;
            }
        }
        ASSERT_TRUE(actual.registryReused);
        ASSERT_TRUE(actual.renderReused);
        EXPECT_EQ(nullptr, current.originalSourceSubmissions.Find(old.arm));
    }, &probe);
    desc.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle failedFiring = 0;
    EXPECT_EQ(VN_RUNTIME_RECREATE_REQUIRED, Vn_PostAction(&desc, &failedFiring));
    ASSERT_EQ(1u, probe.calls);
    ASSERT_TRUE(probe.pageWithdrawn);
    ASSERT_TRUE(probe.registryReused);
    ASSERT_TRUE(probe.renderReused);
    ASSERT_FALSE(probe.fresh.empty());
    EXPECT_FALSE(engine.forceActionTimelineVoiceOwnerRollbackFailureForTest);
    ASSERT_NE(nullptr, probe.oldOwner);
    ASSERT_NE(nullptr, probe.oldStart);
    EXPECT_EQ(1u, engine.actionTimelineVoiceOwnerRollbackAttemptsForTest);
    EXPECT_TRUE(probe.oldOwner->committed);
    const auto completion = engine.mixer.BlocksRendered() + 1u;
    engine.nullBackend.Pump(1);
    ASSERT_EQ(VN_OK, Vn_Update());
    EXPECT_GE(engine.actionTimelineVoiceOwnerRollbackAttemptsForTest, 2u);
    EXPECT_FALSE(probe.oldOwner->committed);
    EXPECT_FALSE(probe.oldStart->prepared);
    EXPECT_EQ(0u, probe.oldStart->renderHandle);
    EXPECT_FALSE(probe.oldStart->voiceOwnershipHeld);
    EXPECT_FALSE(probe.oldStart->ledgerOwnershipHeld);
    EXPECT_FALSE(probe.oldStart->armOwnershipHeld);
    EXPECT_FALSE(probe.oldStart->completionProgressBound);
    for (const auto held : probe.oldStart->effectOwnershipHeld) EXPECT_FALSE(held);
    for (const auto& fresh : probe.fresh) {
        EXPECT_FALSE(engine.voices.ReleaseObserved(fresh.releaseObserver));
        harken::EngineTimelineVoiceInstallIdentity retained{};
        ASSERT_TRUE(engine.CaptureTimelineVoiceInstallIdentity(fresh.renderHandle, &retained));
        EXPECT_EQ(fresh.releaseObserver.targetSequence, retained.releaseObserver.targetSequence);
        EXPECT_TRUE(harken::OriginalSourceSubmissionRegistry::SameToken(fresh.startArm, retained.startArm));
        EXPECT_EQ(completion, engine.timelineArms.RowAt(fresh.startArm.slot)->armedCompletionSequence.load());
        unsigned bindings = 0;
        engine.params.ForEachInstance([&](const harken::ParamSystem::InstanceCaptureRow& row) {
            bindings += row.handle == fresh.renderHandle && row.definitionId == harkentest::ObjectId(99033) && !row.neutralized;
        });
        EXPECT_EQ(1u, bindings);
    }
}
#endif


static void CheckOriginalPlainTwoSoundsAndFixedStop(bool fade, bool repeated, bool expired) {
    (void)Vn_Term();
    constexpr std::uint32_t frames = 64;
    harkentest::EngineSession session(harkentest::MakeNullConfig(4, frames, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    std::vector<float> first(2048, 0.125f), second(2048, 0.25f);
    const auto firstPcm = harkentest::MonoDesc(first, 48000);
    const auto secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &secondPcm));
    engine->nullBackend.Pump(7);
    const auto base = std::max(engine->timelinePool.PublishCutoffFrame(),
        (engine->mixer.BlocksRendered() + engine->config.publishLeadQuanta) * frames);
    const auto stopFrame = ((base + frames - 1u) / frames) * frames + 768u;
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
    image.MakeImmediateSoundPlayAction();
    image.steps[12] = image.steps[11];
    image.steps[12].authoredEventIndex = 1;
    image.steps[12].target.stableId = image.properties[1].stableId;
    image.steps[12].target.expectedProgramSemanticFingerprint = image.properties[1].programSemanticFingerprint;
    image.steps[13] = image.steps[11];
    image.steps[13].opcode = harken::ActionOpcodeV1::Stop;
    image.steps[13].authoredEventIndex = 2;
    constexpr auto fadeFrames = (UINT64_C(1333334) * 48000u + 999999999u) / 1000000000u;
    SetAbsoluteTime(&image.steps[13].delay,
        DelayNanosecondsForTargetFrame(*engine, stopFrame - (fade ? fadeFrames : 0u)));
    if (fade) SetAbsoluteTime(&image.steps[13].fade, 1333334);
    image.actions[9].stepCount = repeated ? 4u : 3u;
    image.world.capacity.maxActionStepsPerDefinition = image.actions[9].stepCount;
    image.world.capacity.maxActionExpandedWork = image.actions[9].stepCount;
    image.actions[9].expandedStepOccurrenceCount = image.actions[9].stepCount;
    image.actions[9].directFeatureMask = 1;
    image.actions[9].transitiveFeatureMask = 1;
    if (repeated) {
        image.steps[14] = image.steps[13];
        image.steps[14].authoredEventIndex = 3;
    }
    image.actions[9].programSemanticFingerprint = harken::ComputeActionProgramFingerprintV1(image.actions[9]);
    image.world.identity.runtimeSemanticFingerprint = harken::ComputeCurrentWorldFingerprintV4(image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok, harken::InstallContainerWorldV1(*engine, image.world).status);
    const auto baseline = CaptureActionReclaimableOwners(*engine);
    auto desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle firing = 0;
    for (std::size_t allocation = 1; allocation <= 2; ++allocation) {
        const auto commandHead = engine->commands.PublishedHead();
        harken::detail::ArmLogicAllocFaultForTests(
            allocation, harken::detail::LogicAllocSite::ImmediateEntryStorage);
        const auto refused = Vn_PostAction(&desc, &firing);
        const auto remaining = harken::detail::g_logicAllocFault.remaining;
        harken::detail::DisarmLogicAllocFaultForTests();
        EXPECT_EQ(0u, remaining);
        ASSERT_EQ(VN_BACKPRESSURE, refused);
        EXPECT_EQ(0u, firing);
        EXPECT_EQ(commandHead, engine->commands.PublishedHead());
        EXPECT_EQ(baseline, CaptureActionReclaimableOwners(*engine));
        EXPECT_FALSE(engine->runtimeRecreateRequired);
    }
    const auto capture = harkentest::monitor::OpenIdentityEvents();
    std::vector<harkentest::monitor::IdentityRecord> observedRows;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    harken::EngineImmediateEntryAttempt* attempt = nullptr;
    for (std::uint32_t index = 0; index < engine->immediateEntryAttempts.size(); ++index)
        if (engine->immediateEntryAttempts[index].active && engine->immediateEntryAttempts[index].root == firing)
            attempt = &engine->immediateEntryAttempts[index];
    ASSERT_NE(nullptr, attempt);
    ASSERT_TRUE(attempt->plainSelected);
    ASSERT_EQ(2u, attempt->plainSourceCount);
    ASSERT_EQ(2u, attempt->plainStopCount);
    EXPECT_EQ(fade ? 5u : 4u, attempt->originalLaneDemand.events);
    const std::array<harken::TimelineArmToken, 2> sourceArms = {
        attempt->plainSources[0].original.event.armToken, attempt->plainSources[1].original.event.armToken};
    if (repeated) {
        VnActionStepResult result{};
        result.structSize = sizeof(result);
        ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 3, &result));
        EXPECT_EQ(VN_ACTION_STEP_NO_OP, result.state);
        EXPECT_EQ(0u, result.capturedPlayableCount);
    }
    const auto ackEnd = expired ? stopFrame / frames + 2u : engine->mixer.BlocksRendered() + 2u;
    while (engine->mixer.BlocksRendered() < ackEnd) {
        const auto before = engine->mixer.BlocksRendered();
        engine->nullBackend.Pump(1);
        harkentest::monitor::CollectIdentityEvents(capture, observedRows);
        ASSERT_EQ(before + 1u, engine->mixer.BlocksRendered());
        EXPECT_LT(harkentest::Peak(engine->nullBackend.LastBlock(), frames * engine->nullBackend.Channels()), 0.0001f);
    }
    ASSERT_EQ(VN_OK, Vn_Update());
    harkentest::monitor::CollectIdentityEvents(capture, observedRows);
    if (!expired) {
        ASSERT_TRUE(attempt->plainPublished);
        EXPECT_GT(attempt->plainAnchor, base);
        EXPECT_EQ(attempt->plainSources[0].chosenOnset, attempt->plainSources[1].chosenOnset);
        const auto start = attempt->plainSources[0].chosenOnset;
        for (std::uint32_t index = 0; index < attempt->plainStopCount; ++index) {
            const auto& resource = engine->authoredStopResources[attempt->plainStops[index].slot];
            const auto& root = engine->authoredStopRoots[resource.operationSlot];
            ASSERT_TRUE(root.operation.has_value());
            EXPECT_EQ(stopFrame, root.operation->Identity().stopFrame);
            EXPECT_EQ(stopFrame, resource.events[resource.runtime.payloadCount - 1u].executeFrame);
            EXPECT_FALSE(resource.transactions.Valid());
            if (resource.arm.Valid()) EXPECT_TRUE(resource.originalPlainBound);
        }
        bool heardBoth = false, heardSiblingAfterStop = false;
        const auto declickFrames = (harken::kTimelineStopDeclickMs * 48000u + 999u) / 1000u;
        while (engine->mixer.BlocksRendered() * frames < stopFrame + declickFrames + 256u) {
            const auto before = engine->mixer.BlocksRendered();
            engine->nullBackend.Pump(1);
            harkentest::monitor::CollectIdentityEvents(capture, observedRows);
            ASSERT_EQ(before + 1u, engine->mixer.BlocksRendered());
            const auto* output = engine->nullBackend.LastBlock();
            for (std::uint32_t sample = frames - 16u; sample < frames; ++sample) {
                const auto frame = before * frames + sample;
                if (frame < start || (frame >= stopFrame - 128u && frame < stopFrame + declickFrames)) continue;
                const auto expected = frame < stopFrame ? 0.375f : 0.25f;
                for (std::uint32_t channel = 0; channel < engine->nullBackend.Channels(); ++channel)
                    EXPECT_NEAR(expected, output[sample * engine->nullBackend.Channels() + channel], 0.0001f)
                        << "frame=" << frame;
                heardBoth |= frame < stopFrame;
                heardSiblingAfterStop |= frame > stopFrame;
            }
            ASSERT_EQ(VN_OK, Vn_Update());
            harkentest::monitor::CollectIdentityEvents(capture, observedRows);
        }
        EXPECT_TRUE(heardBoth);
        EXPECT_TRUE(heardSiblingAfterStop);
    }
    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    for (std::uint32_t block = 0; block < 96u; ++block) {
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
        if (info.state == VN_ACTION_FIRING_TERMINAL_RETAINED) break;
        engine->nullBackend.Pump(1);
        harkentest::monitor::CollectIdentityEvents(capture, observedRows);
        ASSERT_EQ(VN_OK, Vn_Update());
        harkentest::monitor::CollectIdentityEvents(capture, observedRows);
    }
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
    EXPECT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
    EXPECT_EQ(expired ? VN_ACTION_OUTCOME_SUCCEEDED_WITH_STEP_FAILURE : VN_ACTION_OUTCOME_SUCCEEDED, info.outcome);
    if (expired) {
        for (std::uint32_t index = 0; index < 2u; ++index) {
            VnActionStepResult result{}; result.structSize = sizeof(result);
            ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, index, &result));
            EXPECT_EQ(VN_ACTION_STEP_FAILED, result.state);
            EXPECT_EQ(VN_BACKPRESSURE, result.result);
        }
    }
    EXPECT_EQ(expired ? VN_ACTION_TERMINAL_DEADLINE : VN_ACTION_TERMINAL_NATURAL, info.terminalReason);
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    for (std::uint32_t block = 0; block < 64u && CaptureActionReclaimableOwners(*engine) != baseline; ++block) {
        engine->nullBackend.Pump(1);
        harkentest::monitor::CollectIdentityEvents(capture, observedRows);
        ASSERT_EQ(VN_OK, Vn_Update());
        harkentest::monitor::CollectIdentityEvents(capture, observedRows);
    }
    EXPECT_EQ(baseline, CaptureActionReclaimableOwners(*engine));
    std::vector<harkentest::monitor::IdentityRecord> selected;
    harkentest::monitor::CollectIdentityEvents(capture, observedRows);
    for (const auto& record : observedRows)
        if (record.fact.factKind == VN_MONITOR_FACT_SELECTION_COMMITTED) selected.push_back(record);
    EXPECT_EQ(expired ? 0u : 2u, selected.size());
    for (const auto& record : selected) {
        EXPECT_EQ(firing, record.fact.selection.action);
        EXPECT_EQ(record.fact.playbackRequest.sequence, record.fact.selectionRequest.sequence);
        EXPECT_NE(0u, record.fact.selectionRequest.sequence);
    }
    EXPECT_EQ(VN_OK, Vn_MonitorCloseSession(capture));
    EXPECT_EQ(0u, engine->mixer.CommandProtocolViolationCount());
    for (auto arm : sourceArms) {
        harken::TimelineArmObservation stale{};
        EXPECT_FALSE(engine->timelineArms.Observe(arm, &stale));
    }
}

TEST(ActionFiringApi, OriginalPlainActionLateTwoSoundPcmKeepsLiteralStopAndActualOwners) {
    CheckOriginalPlainTwoSoundsAndFixedStop(false, false, false);
}
TEST(ActionFiringApi, OriginalPlainActionLateFadeAndRepeatedStopKeepActualNoOpAndSiblingPcm) {
    CheckOriginalPlainTwoSoundsAndFixedStop(true, true, false);
}
TEST(ActionFiringApi, OriginalPlainActionExpiredFixedStopAbortsAllOriginalSourcesAndReclaims) {
    CheckOriginalPlainTwoSoundsAndFixedStop(false, false, true);
}

static void CheckOriginalPlainCutoffAndLaterSibling(std::uint32_t offset, bool holdSource) {
    (void)Vn_Term();
    constexpr std::uint32_t frames = 64;
    harkentest::EngineSession session(harkentest::MakeNullConfig(6, frames, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    std::vector<float> first(4096, 0.125f), second(4096, 0.25f);
    const auto firstPcm = harkentest::MonoDesc(first, 48000);
    const auto secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &secondPcm));
    engine->nullBackend.Pump(7);
    const auto base = std::max(engine->timelinePool.PublishCutoffFrame(),
        (engine->mixer.BlocksRendered() + engine->config.publishLeadQuanta) * frames);
    const auto stop = ((base + frames - 1u) / frames) * frames + 384u;
    const auto firstOnset = stop + offset;
    const auto thirdOnset = firstOnset + 256u;
    CanonicalActionWorld image(engine->registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
    image.MakeImmediateSoundPlayAction();
    SetAbsoluteTime(&image.steps[11].delay, DelayNanosecondsForTargetFrame(*engine, firstOnset));
    image.steps[12] = image.steps[11];
    image.steps[12].authoredEventIndex = 1;
    SetAbsoluteTime(&image.steps[12].delay, 0);
    image.steps[12].target.stableId = image.properties[1].stableId;
    image.steps[12].target.expectedProgramSemanticFingerprint = image.properties[1].programSemanticFingerprint;
    image.steps[13] = image.steps[12];
    image.steps[13].authoredEventIndex = 2;
    SetAbsoluteTime(&image.steps[13].delay, DelayNanosecondsForTargetFrame(*engine, thirdOnset));
    image.steps[14] = image.steps[11];
    image.steps[14].opcode = harken::ActionOpcodeV1::Stop;
    image.steps[14].authoredEventIndex = 3;
    SetAbsoluteTime(&image.steps[14].delay, DelayNanosecondsForTargetFrame(*engine, stop));
    image.actions[9].stepCount = 4;
    image.actions[9].expandedStepOccurrenceCount = 4;
    image.actions[9].directFeatureMask = image.actions[9].transitiveFeatureMask = 1;
    image.world.capacity.maxActionStepsPerDefinition = 4;
    image.world.capacity.maxActionExpandedWork = 4;
    image.actions[9].programSemanticFingerprint = harken::ComputeActionProgramFingerprintV1(image.actions[9]);
    image.world.identity.runtimeSemanticFingerprint = harken::ComputeCurrentWorldFingerprintV4(image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok, harken::InstallContainerWorldV1(*engine, image.world).status);
    const auto baseline = CaptureActionReclaimableOwners(*engine);
    auto desc = ValidPostDesc(); desc.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    harken::EngineImmediateEntryAttempt* attempt = nullptr;
    for (std::uint32_t index = 0; index < engine->immediateEntryAttempts.size(); ++index)
        if (engine->immediateEntryAttempts[index].active && engine->immediateEntryAttempts[index].root == firing)
            attempt = &engine->immediateEntryAttempts[index];
    ASSERT_NE(nullptr, attempt);
    ASSERT_TRUE(attempt->plainSelected);
    ASSERT_EQ(3u, attempt->plainSourceCount);
    engine->nullBackend.Pump(2);
    ASSERT_EQ(VN_OK, Vn_Update());
    ASSERT_TRUE(attempt->plainPublished);
    ASSERT_EQ(firstOnset, attempt->plainSources[0].chosenOnset);
    const auto sourceArm = attempt->plainSources[0].original.event.armToken;
    const auto siblingArm = attempt->plainSources[2].original.event.armToken;
    auto* sourceRow = engine->timelineArms.RowAt(sourceArm.slot);
    ASSERT_NE(nullptr, sourceRow);
    bool held = false;
    if (holdSource) {
        ASSERT_GT(offset, frames * 2u);
        ASSERT_FALSE(sourceRow->reservation.test_and_set(std::memory_order_acquire));
        held = true;
    }
    bool heardEarlySibling = false, heardLaterSibling = false;
    while (engine->mixer.BlocksRendered() * frames < thirdOnset + 192u) {
        const auto before = engine->mixer.BlocksRendered();
        engine->nullBackend.Pump(1);
        ASSERT_EQ(before + 1u, engine->mixer.BlocksRendered());
        if (held && (before + 1u) * frames >= stop + frames * 2u) {
            sourceRow->reservation.clear(std::memory_order_release);
            held = false;
        }
        const auto* output = engine->nullBackend.LastBlock();
        for (std::uint32_t sample = frames - 16u; sample < frames; ++sample) {
            const auto frame = before * frames + sample;
            if (frame < attempt->plainSources[1].chosenOnset + frames ||
                (frame >= thirdOnset && frame < thirdOnset + frames)) continue;
            const auto expected = frame < thirdOnset ? 0.25f : 0.5f;
            for (std::uint32_t channel = 0; channel < engine->nullBackend.Channels(); ++channel)
                EXPECT_NEAR(expected, output[sample * engine->nullBackend.Channels() + channel], 0.0001f)
                    << "frame=" << frame << " stop=" << stop << " offset=" << offset;
            heardEarlySibling |= frame < thirdOnset;
            heardLaterSibling |= frame >= thirdOnset + frames;
        }
    }
    if (held) sourceRow->reservation.clear(std::memory_order_release);
    EXPECT_TRUE(heardEarlySibling);
    EXPECT_TRUE(heardLaterSibling);
    harken::TimelineArmObservation source{}, sibling{};
    ASSERT_TRUE(engine->timelineArms.Observe(sourceArm, &source));
    EXPECT_EQ(0u, source.startedBlockSequence);
    ASSERT_TRUE(engine->timelineArms.Observe(siblingArm, &sibling));
    EXPECT_GT(sibling.startedBlockSequence, 0u);
    harken::ImmediateLaneObservation lane{};
    ASSERT_TRUE(engine->immediateActionLane.Observe(attempt->lane, &lane));
    EXPECT_TRUE(lane.complete);
    EXPECT_FALSE(lane.missed);
    EXPECT_FALSE(lane.protocolRefused);
    EXPECT_EQ(0u, engine->mixer.CommandProtocolViolationCount());
    ASSERT_EQ(VN_OK, Vn_Update());
    VnActionFiringInfo info{}; info.structSize = sizeof(info);
    for (std::uint32_t block = 0; block < 160u; ++block) {
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
        if (info.state == VN_ACTION_FIRING_TERMINAL_RETAINED) break;
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
    }
    ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
    EXPECT_EQ(VN_ACTION_OUTCOME_SUCCEEDED, info.outcome);
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    for (std::uint32_t block = 0; block < 64u && CaptureActionReclaimableOwners(*engine) != baseline; ++block) {
        engine->nullBackend.Pump(1); ASSERT_EQ(VN_OK, Vn_Update());
    }
    EXPECT_EQ(baseline, CaptureActionReclaimableOwners(*engine));
}

TEST(ActionFiringApi, OriginalPlainActionFixedStopBeforeOriginalStartKeepsLaterSiblingWithoutUpdate) {
    CheckOriginalPlainCutoffAndLaterSibling(256, false);
}
TEST(ActionFiringApi, OriginalPlainActionSameBucketStopBeforeStartNeverClaimsStartedAndKeepsLaterSibling) {
    CheckOriginalPlainCutoffAndLaterSibling(10, false);
}
TEST(ActionFiringApi, OriginalPlainActionStopEqualsStartNeverClaimsStartedAndKeepsLaterSibling) {
    CheckOriginalPlainCutoffAndLaterSibling(0, false);
}
TEST(ActionFiringApi, OriginalPlainActionActualSourceGateAcrossStopAndDonePreservesCutoffWithoutUpdate) {
    CheckOriginalPlainCutoffAndLaterSibling(256, true);
}

static void CheckOriginalPlainCancellationAndJoinedTerm(std::uint32_t mode) {
    (void)Vn_Term();
    constexpr std::uint32_t frames = 64;
    harkentest::EngineSession session(harkentest::MakeNullConfig(4, frames, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    std::vector<float> samples(4096, 0.25f);
    const auto pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
    CanonicalActionWorld image(engine->registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision);
    image.MakeImmediateSoundPlayAction();
    image.steps[12] = image.steps[11]; image.steps[12].authoredEventIndex = 1;
    image.steps[13] = image.steps[11]; image.steps[13].opcode = harken::ActionOpcodeV1::Stop;
    image.steps[13].authoredEventIndex = 2;
    SetAbsoluteTime(&image.steps[13].delay, 100000000);
    image.actions[9].stepCount = image.actions[9].expandedStepOccurrenceCount = 3;
    image.actions[9].directFeatureMask = image.actions[9].transitiveFeatureMask = 1;
    image.actions[9].programSemanticFingerprint = harken::ComputeActionProgramFingerprintV1(image.actions[9]);
    image.world.identity.runtimeSemanticFingerprint = harken::ComputeCurrentWorldFingerprintV4(image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok, harken::InstallContainerWorldV1(*engine, image.world).status);
    const auto baseline = CaptureActionReclaimableOwners(*engine);
    auto desc = ValidPostDesc(); desc.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle firing = 0; ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    harken::EngineImmediateEntryAttempt* attempt = nullptr;
    for (std::uint32_t index = 0; index < engine->immediateEntryAttempts.size(); ++index)
        if (engine->immediateEntryAttempts[index].active && engine->immediateEntryAttempts[index].root == firing)
            attempt = &engine->immediateEntryAttempts[index];
    ASSERT_NE(nullptr, attempt); ASSERT_TRUE(attempt->plainSelected);
    const auto originalWorldGeneration = engine->variables.CurrentWorldGeneration();
    auto resetStatus = harken::RuntimeTransportResetStatus::Complete;
    if (mode == 0) {
        ASSERT_EQ(VN_OK, Vn_StopActionFiring(firing, 0));
    } else if (mode == 1) {
        resetStatus = harken::BeginRuntimeTransportReset(*engine, 0);
        EXPECT_TRUE(resetStatus == harken::RuntimeTransportResetStatus::Complete ||
            resetStatus == harken::RuntimeTransportResetStatus::Backpressure);
    } else if (mode == 4) {
        CanonicalActionWorld replacement(engine->registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision);
        replacement.variables[0].defaultValue = 0.25f;
        replacement.world.identity.runtimeSemanticFingerprint = harken::ComputeCurrentWorldFingerprintV4(replacement.world);
        ASSERT_EQ(harken::WorldInstallStatus::Ok,
            harken::InstallContainerWorldV1(*engine, replacement.world).status);
        ASSERT_GT(engine->variables.CurrentWorldGeneration(), originalWorldGeneration);
        ASSERT_FALSE(engine->currentWorldReplacementAdmissionClosed);
    } else {
        engine->nullBackend.Pump(2);
        harken::TimelineArmTable::Row* held = nullptr;
        if (mode == 3) {
            for (std::uint32_t index = 0; index < attempt->plainStopCount; ++index) {
                auto& resource = engine->authoredStopResources[attempt->plainStops[index].slot];
                if (!resource.arm.Valid()) continue;
                held = engine->timelineArms.RowAt(resource.arm.slot);
                ASSERT_FALSE(held->reservation.test_and_set(std::memory_order_acquire)); break;
            }
            ASSERT_NE(nullptr, held);
        }
        ASSERT_EQ(VN_OK, Vn_Update());
        if (mode == 3) {
            ASSERT_TRUE(attempt->plainLayout.Valid());
            ASSERT_TRUE(attempt->plainSources[0].bindingReader.Valid());
            ASSERT_FALSE(attempt->plainPublished);
            held->reservation.clear(std::memory_order_release);
        } else ASSERT_TRUE(attempt->plainPublished);
        ASSERT_EQ(VN_OK, Vn_Term());
        EXPECT_EQ(nullptr, harken::detail::ActiveEngine());
        return;
    }
    VnActionFiringInfo info{}; info.structSize = sizeof(info);
    bool heardOriginalWorldSources = false;
    for (std::uint32_t block = 0; block < 128u; ++block) {
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_FALSE(engine->runtimeRecreateRequired);
        if (mode == 1 && resetStatus != harken::RuntimeTransportResetStatus::Complete) {
            resetStatus = harken::BeginRuntimeTransportReset(*engine, 0);
            ASSERT_NE(harken::RuntimeTransportResetStatus::RuntimeRecreateRequired, resetStatus);
            ASSERT_NE(harken::RuntimeTransportResetStatus::InvalidRequest, resetStatus);
        }
        const auto peak = harkentest::Peak(engine->nullBackend.LastBlock(), frames * engine->nullBackend.Channels());
        if (mode == 4) heardOriginalWorldSources |= peak > 0.001f;
        else EXPECT_LT(peak, 0.0001f);
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
        if (info.state == VN_ACTION_FIRING_TERMINAL_RETAINED) break;
    }
    EXPECT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
    EXPECT_EQ(mode == 4 ? VN_ACTION_OUTCOME_SUCCEEDED : VN_ACTION_OUTCOME_CANCELLED, info.outcome);
    EXPECT_EQ(mode == 0 ? VN_ACTION_TERMINAL_STOP_REQUESTED : mode == 4 ?
        VN_ACTION_TERMINAL_NATURAL : VN_ACTION_TERMINAL_TRANSPORT_RESET, info.terminalReason);
    for (std::uint32_t index = 0; index < 2u; ++index) {
        VnActionStepResult result{}; result.structSize = sizeof(result);
        ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, index, &result));
        EXPECT_EQ(mode == 4 ? VN_ACTION_STEP_SUCCEEDED : VN_ACTION_STEP_CANCELLED, result.state);
    }
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    for (std::uint32_t block = 0; block < 64u && CaptureActionReclaimableOwners(*engine) != baseline; ++block) {
        engine->nullBackend.Pump(1); ASSERT_EQ(VN_OK, Vn_Update());
    }
    EXPECT_EQ(baseline, CaptureActionReclaimableOwners(*engine));
    if (mode == 4) {
        EXPECT_TRUE(heardOriginalWorldSources);
        EXPECT_GT(engine->variables.CurrentWorldGeneration(), originalWorldGeneration);
        EXPECT_FALSE(engine->currentWorldReplacementAdmissionClosed);
    }
    if (mode == 1) {
        for (std::uint32_t block = 0; block < 64u &&
            resetStatus != harken::RuntimeTransportResetStatus::Complete; ++block) {
            engine->nullBackend.Pump(1); ASSERT_EQ(VN_OK, Vn_Update());
            resetStatus = harken::BeginRuntimeTransportReset(*engine, 0);
        }
        EXPECT_EQ(harken::RuntimeTransportResetStatus::Complete, resetStatus);
        EXPECT_FALSE(engine->runtimeTransportResetActive);
        EXPECT_FALSE(engine->runtimeRecreateRequired);
    }
    EXPECT_EQ(0u, engine->mixer.CommandProtocolViolationCount());
}

