static void CheckNestedBoundActionOriginalStopObserverCancellation(bool worldReplacement) {
    (void)Vn_Term();
    constexpr std::uint32_t frames = 64;
    harkentest::EngineSession session(harkentest::MakeNullConfig(4, frames, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    std::vector<float> samples(4096, 0.25f);
    const auto pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
    CanonicalActionWorld image(engine->registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision);
    image.MakeImmediateSoundPlayThenStopAction();
    SetAbsoluteTime(&image.steps[12].delay, 100000000);
    image.actions[9].directFeatureMask = image.actions[9].transitiveFeatureMask = 1;
    image.actions[9].programSemanticFingerprint = harken::ComputeActionProgramFingerprintV1(image.actions[9]);
    image.MakeQuantizedPostAction(harken::ActionQuantizeTimingV1::Immediate,
        harken::ActionIfSilentV1::Immediate, 0, 10, 14, harkentest::ObjectId(51), 9);
    ASSERT_EQ(harken::WorldInstallStatus::Ok, harken::InstallContainerWorldV1(*engine, image.world).status);
    const auto baseline = CaptureActionReclaimableOwners(*engine);
    const auto originalWorld = engine->variables.CurrentWorldGeneration();
    auto desc = ValidPostDesc(); desc.actionId = image.actions[10].actionStableId;
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    VnActionStepResult post{}; post.structSize = sizeof(post);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &post));
    const auto child = post.childFiring;
    ASSERT_NE(0u, child);
    VnActionFiringInfo childInfo{}; childInfo.structSize = sizeof(childInfo);
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(child, &childInfo));
    ASSERT_EQ(firing, childInfo.parentFiring);
    bool originalService = false, originalStop = false;
    for (const auto& row : engine->playableServices)
        originalService |= row.phase != harken::EnginePlayableStartPhase::Free &&
            row.InvocationValid() && row.Invocation().actionFiring == child;
    for (const auto& root : engine->authoredStopRoots)
        originalStop |= root.committed && root.operation &&
            root.operation->Identity().actionFiring == child && root.cancellation.Handle() != 0;
    ASSERT_TRUE(originalService);
    ASSERT_TRUE(originalStop);
    for (std::uint32_t index = 0; index < engine->immediateEntryAttempts.size(); ++index) {
        const auto& attempt = engine->immediateEntryAttempts[index];
        if (attempt.active && attempt.root == firing) EXPECT_FALSE(attempt.plainSelected);
    }
    auto resetStatus = harken::RuntimeTransportResetStatus::Complete;
    if (worldReplacement) {
        CanonicalActionWorld replacement(engine->registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision);
        replacement.variables[0].defaultValue = 0.25f;
        replacement.world.identity.runtimeSemanticFingerprint = harken::ComputeCurrentWorldFingerprintV4(replacement.world);
        ASSERT_EQ(harken::WorldInstallStatus::Ok,
            harken::InstallContainerWorldV1(*engine, replacement.world).status);
        ASSERT_GT(engine->variables.CurrentWorldGeneration(), originalWorld);
        ASSERT_FALSE(engine->currentWorldReplacementAdmissionClosed);
    } else {
        resetStatus = harken::BeginRuntimeTransportReset(*engine, 0);
        ASSERT_EQ(harken::RuntimeTransportResetStatus::Backpressure, resetStatus);
    }
    VnActionFiringInfo rootInfo{}; rootInfo.structSize = sizeof(rootInfo);
    bool heardOriginalSound = false;
    for (std::uint32_t block = 0; block < 128u; ++block) {
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_FALSE(engine->runtimeRecreateRequired);
        heardOriginalSound |= harkentest::Peak(engine->nullBackend.LastBlock(),
            frames * engine->nullBackend.Channels()) > 0.001f;
        if (!worldReplacement && resetStatus != harken::RuntimeTransportResetStatus::Complete) {
            resetStatus = harken::BeginRuntimeTransportReset(*engine, 0);
            ASSERT_NE(harken::RuntimeTransportResetStatus::RuntimeRecreateRequired, resetStatus);
            ASSERT_NE(harken::RuntimeTransportResetStatus::InvalidRequest, resetStatus);
        }
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &rootInfo));
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(child, &childInfo));
        if (rootInfo.state == VN_ACTION_FIRING_TERMINAL_RETAINED &&
            childInfo.state == VN_ACTION_FIRING_TERMINAL_RETAINED) break;
    }
    const auto reason = worldReplacement ? VN_ACTION_TERMINAL_NATURAL : VN_ACTION_TERMINAL_TRANSPORT_RESET;
    for (const auto* info : {&rootInfo, &childInfo}) {
        ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info->state);
        EXPECT_EQ(worldReplacement ? VN_ACTION_OUTCOME_SUCCEEDED : VN_ACTION_OUTCOME_CANCELLED, info->outcome);
        EXPECT_EQ(reason, info->terminalReason);
        EXPECT_EQ(0u, info->livePlayableCount);
    }
    for (std::uint32_t index = 0; index < 2u; ++index) {
        VnActionStepResult result{}; result.structSize = sizeof(result);
        ASSERT_EQ(VN_OK, Vn_QueryActionStep(child, index, &result));
        EXPECT_EQ(worldReplacement ? VN_ACTION_STEP_SUCCEEDED : VN_ACTION_STEP_CANCELLED, result.state);
    }
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    const auto stopOwnersReturned = [&]() {
        for (const auto& root : engine->authoredStopRoots) {
            if (root.committed || root.operation || root.cancellation.Handle() != 0 ||
                root.cancellationPending || root.detachObserverPending || root.resourceCount != 0 ||
                root.retainedPreparation.operationSlot != UINT32_MAX) return false;
        }
        for (const auto& resource : engine->authoredStopResources) {
            if (resource.prepared || resource.committed || resource.fence || resource.arm.Valid() ||
                resource.originalControlHeader.State() != harken::CommandQueue::OriginalRangeState::Empty)
                return false;
        }
        return true;
    };
    for (std::uint32_t block = 0; block < 96u; ++block) {
        if (CaptureActionReclaimableOwners(*engine) == baseline && stopOwnersReturned() &&
            (worldReplacement ? !engine->currentWorldReplacementAdmissionClosed :
                resetStatus == harken::RuntimeTransportResetStatus::Complete)) break;
        engine->nullBackend.Pump(1); ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_FALSE(engine->runtimeRecreateRequired);
        if (!worldReplacement && resetStatus != harken::RuntimeTransportResetStatus::Complete)
            resetStatus = harken::BeginRuntimeTransportReset(*engine, 0);
    }
    EXPECT_EQ(baseline, CaptureActionReclaimableOwners(*engine));
    EXPECT_TRUE(stopOwnersReturned());
    for (const auto& root : engine->authoredStopRoots) {
        EXPECT_FALSE(root.committed);
        EXPECT_EQ(0u, root.cancellation.Handle());
        EXPECT_FALSE(root.cancellationPending);
        EXPECT_FALSE(root.detachObserverPending);
    }
    if (worldReplacement) {
        EXPECT_TRUE(heardOriginalSound);
        EXPECT_GT(engine->variables.CurrentWorldGeneration(), originalWorld);
        EXPECT_FALSE(engine->currentWorldReplacementAdmissionClosed);
    } else {
        EXPECT_EQ(harken::RuntimeTransportResetStatus::Complete, resetStatus);
        EXPECT_FALSE(engine->runtimeTransportResetActive);
    }
    EXPECT_EQ(0u, engine->mixer.CommandProtocolViolationCount());
}

TEST(ActionFiringApi, NestedBoundActionTransportReturnsOriginalChildStopObserverAndAllOwners) {
    CheckNestedBoundActionOriginalStopObserverCancellation(false);
}
TEST(ActionFiringApi, NestedBoundActionWorldReplacementKeepsOriginalChildSoundStopAndAllOwners) {
    CheckNestedBoundActionOriginalStopObserverCancellation(true);
}

static void CheckOriginalBoundActionStopObserverOnWorldOrTransport(bool worldReplacement) {
    (void)Vn_Term();
    harkentest::EngineSession session(harkentest::MakeNullConfig(8, 64, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    std::vector<float> first(4096, 0.25f), second(4096, -0.25f);
    const auto firstPcm = harkentest::MonoDesc(first, 48000);
    const auto secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &secondPcm));
    CanonicalActionWorld image(engine->registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
    image.MakeImmediateSoundPlayThenStopAction();
    const auto originalStop = image.steps[12];
    image.MakeImmediateVariableControlPlayAction();
    image.steps[12] = originalStop;
    image.steps[12].target = image.steps[11].target;
    SetAbsoluteTime(&image.steps[12].delay, 100000000);
    image.actions[9].stepCount = image.actions[9].expandedStepOccurrenceCount = 2;
    image.actions[9].directFeatureMask = image.actions[9].transitiveFeatureMask = 1;
    image.actions[9].programSemanticFingerprint = harken::ComputeActionProgramFingerprintV1(image.actions[9]);
    image.world.identity.runtimeSemanticFingerprint = harken::ComputeCurrentWorldFingerprintV4(image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok, harken::InstallContainerWorldV1(*engine, image.world).status);
    auto desc = ValidPostDesc(); desc.actionId = image.actions[9].actionStableId;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&desc.emitter));
    const auto baseline = CaptureActionReclaimableOwners(*engine);
    const auto originalWorld = engine->variables.CurrentWorldGeneration();
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    bool capturedStop = false, currentAuthority = false;
    for (const auto& root : engine->authoredStopRoots)
        capturedStop |= root.committed && root.operation && root.cancellation.Handle() != 0 &&
            root.operation->Identity().actionFiring == firing;
    for (const auto& row : engine->playableServices)
        currentAuthority |= row.InvocationValid() && row.Invocation().actionFiring == firing &&
            row.variableControlInstance.Valid() && row.variableControlWorldUsesCurrentAuthority;
    ASSERT_TRUE(capturedStop);
    ASSERT_TRUE(currentAuthority);
    ASSERT_EQ(0u, engine->mixer.BlocksRendered());
    CanonicalActionWorld replacement(engine->registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
    replacement.variables[0].defaultValue = 0.25f;
    replacement.world.identity.runtimeSemanticFingerprint = harken::ComputeCurrentWorldFingerprintV4(replacement.world);
    auto installStatus = harken::WorldInstallStatus::Backpressure;
    auto resetStatus = harken::RuntimeTransportResetStatus::Backpressure;
    if (worldReplacement) {
        installStatus = harken::InstallContainerWorldV1(*engine, replacement.world).status;
        ASSERT_EQ(harken::WorldInstallStatus::Backpressure, installStatus);
        ASSERT_TRUE(engine->currentWorldReplacementAdmissionClosed);
    } else {
        resetStatus = harken::BeginRuntimeTransportReset(*engine, 0);
        ASSERT_EQ(harken::RuntimeTransportResetStatus::Backpressure, resetStatus);
    }
    VnActionFiringInfo info{}; info.structSize = sizeof(info);
    for (std::uint32_t block = 0; block < 128u; ++block) {
        engine->nullBackend.Pump(1); ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_FALSE(engine->runtimeRecreateRequired);
        if (worldReplacement && installStatus != harken::WorldInstallStatus::Ok)
            installStatus = harken::InstallContainerWorldV1(*engine, replacement.world).status;
        else if (!worldReplacement && resetStatus != harken::RuntimeTransportResetStatus::Complete)
            resetStatus = harken::BeginRuntimeTransportReset(*engine, 0);
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
        if (info.state == VN_ACTION_FIRING_TERMINAL_RETAINED) break;
    }
    ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
    EXPECT_EQ(VN_ACTION_OUTCOME_CANCELLED, info.outcome);
    EXPECT_EQ(worldReplacement ? VN_ACTION_TERMINAL_WORLD_REPLACED : VN_ACTION_TERMINAL_TRANSPORT_RESET,
        info.terminalReason);
    EXPECT_EQ(0u, info.livePlayableCount);
    for (std::uint32_t index = 0; index < 2u; ++index) {
        VnActionStepResult result{}; result.structSize = sizeof(result);
        ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, index, &result));
        EXPECT_EQ(VN_ACTION_STEP_CANCELLED, result.state);
    }
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    const auto stopOwnersReturned = [&]() {
        for (const auto& root : engine->authoredStopRoots)
            if (root.committed || root.operation || root.cancellation.Handle() != 0 ||
                root.cancellationPending || root.detachObserverPending || root.resourceCount != 0 ||
                root.retainedPreparation.operationSlot != UINT32_MAX) return false;
        for (const auto& resource : engine->authoredStopResources)
            if (resource.prepared || resource.committed || resource.fence || resource.arm.Valid() ||
                resource.originalControlHeader.State() != harken::CommandQueue::OriginalRangeState::Empty)
                return false;
        return true;
    };
    for (std::uint32_t block = 0; block < 128u; ++block) {
        if (CaptureActionReclaimableOwners(*engine) == baseline && stopOwnersReturned() &&
            (worldReplacement ? installStatus == harken::WorldInstallStatus::Ok :
                resetStatus == harken::RuntimeTransportResetStatus::Complete)) break;
        engine->nullBackend.Pump(1); ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_FALSE(engine->runtimeRecreateRequired);
        if (worldReplacement && installStatus != harken::WorldInstallStatus::Ok)
            installStatus = harken::InstallContainerWorldV1(*engine, replacement.world).status;
        else if (!worldReplacement && resetStatus != harken::RuntimeTransportResetStatus::Complete)
            resetStatus = harken::BeginRuntimeTransportReset(*engine, 0);
    }
    EXPECT_EQ(baseline, CaptureActionReclaimableOwners(*engine));
    EXPECT_TRUE(stopOwnersReturned());
    EXPECT_FALSE(engine->runtimeRecreateRequired);
    EXPECT_EQ(0u, engine->mixer.CommandProtocolViolationCount());
    if (worldReplacement) {
        EXPECT_EQ(harken::WorldInstallStatus::Ok, installStatus);
        EXPECT_GT(engine->variables.CurrentWorldGeneration(), originalWorld);
        EXPECT_FALSE(engine->currentWorldReplacementAdmissionClosed);
    } else {
        EXPECT_EQ(harken::RuntimeTransportResetStatus::Complete, resetStatus);
        EXPECT_FALSE(engine->runtimeTransportResetActive);
    }
}

TEST(ActionFiringApi, OriginalBoundActionWorldReplacementBeforeAckReturnsActualStopObserverAndAllOwners) {
    CheckOriginalBoundActionStopObserverOnWorldOrTransport(true);
}
TEST(ActionFiringApi, OriginalBoundActionTransportBeforeAckReturnsActualStopObserverAndAllOwners) {
    CheckOriginalBoundActionStopObserverOnWorldOrTransport(false);
}


// This fixture uses two independently authored Track definitions. It never
// manufactures a service state, Arm state, receipt, or private admission grant.
static void CheckGenericInitialQueuePublishRefusalPreservesOriginalZeroWork(
    std::uint32_t refusedPublication, bool holdOriginalReader = false) {
    (void)Vn_Term();
    harkentest::EngineSession session(harkentest::MakeNullConfig(8, 64, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto& engine = *session.Engine();
    const auto sourceGenerationsBefore = CaptureSourceGenerations(engine);
    const auto sourceCount = [&]() {
        std::uint32_t count = 0;
        for (std::uint32_t slot = 0; slot < engine.sourceTerminals.Capacity(); ++slot)
            count += engine.sourceTerminals.At(slot)->occupied ? 1u : 0u;
        return count;
    };
    const auto sourcesBefore = sourceCount();
    std::vector<float> samples(128, 0.25f);
    const auto pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &pcm));
    const auto revisionA = engine.registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision;
    const auto revisionB = engine.registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision;
    CanonicalActionWorld image(revisionA, revisionB), logical(revisionA, revisionB);
    image.MakeImmediateSequenceQueuePlayAction();
    image.MakeFirstQueueChildCompositeTrack();
    image.trackPlacements[1].authoredStart = INT64_C(500000);
    image.track.scheduleSemanticFingerprint = harken::ComputeTrackScheduleFingerprintV1(image.track);
    image.queueChildren[0].timingHint = harken::MakeScheduleReferenceTimingHint(
        harken::PlayableKindV1::Track, image.track.rootDefinition.stableId,
        image.track.scheduleSemanticFingerprint);

    logical.MakeSecondQueueChildCompositeTrack();
    const auto oldLogicalId = logical.track.rootDefinition.stableId;
    const auto newLogicalId = harkentest::ObjectId(7501);
    auto logicalProperty = *std::find_if(logical.properties,
        logical.properties + logical.world.playablePropertyCount,
        [&](const auto& property) {
            return property.contentPropertyKind == harken::playableproperties::ContentPropertyKindV1::Track &&
                property.stableId == oldLogicalId;
        });
    logicalProperty.stableId = newLogicalId;
    logicalProperty.authoredStableOrder = image.world.playablePropertyCount;
    logicalProperty.programSemanticFingerprint = harken::ComputePlayablePropertyFingerprintV1(logicalProperty);
    logical.track.rootDefinition.stableId = newLogicalId;
    logical.track.rootDefinition.expectedProgramSemanticFingerprint = logicalProperty.programSemanticFingerprint;
    for (std::uint32_t index = 0; index < logical.track.placementCount; ++index) {
        logical.trackPlacements[index].authoredStart = INT64_C(10000000) * (index + 1u);
        logical.trackPlacements[index].authoredDuration = 1;
        logical.trackPlacements[index].clipId = harkentest::ObjectId(8501u + index);
        logical.trackPlacements[index].clipGuidHigh = 8601u + index;
        logical.trackPlacements[index].clipGuidLow = 8701u + index;
    }
    logical.track.scheduleSemanticFingerprint = harken::ComputeTrackScheduleFingerprintV1(logical.track);
    image.queueChildren[1].playable = logical.track.rootDefinition;
    image.queueChildren[1].timingHint = harken::MakeScheduleReferenceTimingHint(
        harken::PlayableKindV1::Track, newLogicalId, logical.track.scheduleSemanticFingerprint);
    std::vector<harken::PlayablePropertyProgramViewV1> properties(image.world.playableProperties,
        image.world.playableProperties + image.world.playablePropertyCount);
    properties.push_back(logicalProperty);
    std::vector<harken::PlayableOccurrencePropertyViewV1> occurrences(image.world.playableOccurrences,
        image.world.playableOccurrences + image.world.playableOccurrenceCount);
    for (std::uint32_t index = 0; index < logical.world.playableOccurrenceCount; ++index) {
        auto occurrence = logical.occurrences[index];
        if (occurrence.parentKind != harken::playableproperties::ContentPropertyKindV1::Track ||
            occurrence.parentStableId != oldLogicalId) continue;
        occurrence.parentStableId = newLogicalId;
        occurrence.parentProgramSemanticFingerprint = logicalProperty.programSemanticFingerprint;
        occurrence.occurrenceSemanticFingerprint = harken::ComputePlayableOccurrenceFingerprintV1(occurrence);
        occurrences.push_back(occurrence);
    }
    for (auto& occurrence : occurrences) {
        if (occurrence.parentKind != harken::playableproperties::ContentPropertyKindV1::Container ||
            occurrence.parentStableId != image.containers[2].containerStableId ||
            occurrence.stableOccurrenceOrdinal != image.queueChildren[1].stableChildOrdinal) continue;
        occurrence.childPlayable = image.queueChildren[1].playable;
        occurrence.occurrenceSemanticFingerprint = harken::ComputePlayableOccurrenceFingerprintV1(occurrence);
    }
    std::sort(properties.begin(), properties.end(), [](const auto& a, const auto& b) {
        return std::pair(a.contentPropertyKind, a.stableId) < std::pair(b.contentPropertyKind, b.stableId);
    });
    std::sort(occurrences.begin(), occurrences.end(), [](const auto& a, const auto& b) {
        return std::tuple(a.parentKind, a.parentStableId, a.stableOccurrenceOrdinal) <
            std::tuple(b.parentKind, b.parentStableId, b.stableOccurrenceOrdinal);
    });
    std::array<harken::TrackScheduleProgramViewV1, 2> tracks{image.track, logical.track};
    image.world.playableProperties = properties.data();
    image.world.playablePropertyCount = static_cast<std::uint32_t>(properties.size());
    image.world.playableOccurrences = occurrences.data();
    image.world.playableOccurrenceCount = static_cast<std::uint32_t>(occurrences.size());
    image.world.trackSchedules = tracks.data();
    image.world.trackScheduleCount = static_cast<std::uint32_t>(tracks.size());
    image.world.identity.runtimeSemanticFingerprint = harken::ComputeCurrentWorldFingerprintV4(image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok, harken::InstallContainerWorldV1(engine, image.world).status);
    const auto ownersBefore = CaptureActionReclaimableOwners(engine);
    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&desc.emitter));
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    VnActionStepResult play{};
    play.structSize = sizeof(play);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
    auto row = std::find_if(engine.playableServices.begin(), engine.playableServices.end(),
        [&](const auto& candidate) { return candidate.rootInstance == play.producedPlayableInstance; });
    ASSERT_NE(engine.playableServices.end(), row);
    ASSERT_TRUE(row->pendingImmediateEntry);
    ASSERT_TRUE(row->queueTimingPending);
    ASSERT_EQ(2u, row->QueuePayload().queueCurrentScheduleLeafCount);
    ASSERT_EQ(0u, row->QueueFiling().queueSuccessorScheduleLeafCount);
    ASSERT_TRUE(row->QueueFiling().queueSuccessorHasZeroWorkCompletion);
    ASSERT_FALSE(row->QueueFiling().queueSuccessorArm.Valid());
    const auto originalQueue = row->queueInstance;
    const auto originalComposite = row->QueuePayload().queueCurrentCompositeOwner;
    ASSERT_TRUE(originalComposite.Valid());
    const auto originalInitialDecision = row->initialQueueEntryDecision;
    const auto originalQueueDecision = row->QueueFiling().queueDecision;
    const auto originalInitialLaneGroup = row->QueuePayload().queueInitialLaneArmGroup;
    const auto originalQueueArmGroup = row->QueueFiling().queueArmGroup;
    struct Observation {
        VnActionFiringHandle firing = 0;
        harken::EnginePlayableServiceToken service{};
        harken::EnginePlayablePartitionToken partition{};
        harken::PlayableInstanceHandle owner = 0;
        std::uint64_t ownerEpoch = 0;
        harken::EnginePlayableStartRow* invocation = nullptr;
        std::uint64_t invocationGeneration = 0;
        std::uint64_t oldZeroWork = 0;
        std::uint32_t refused = 0;
        bool holdOriginalReader = false;
        harken::TimelineArmReaderPin independentReader;
        harken::ImmediateLaneHandle originalLane{};
        std::uint64_t originalAttemptGeneration = 0;
        harken::DecisionToken originalCoordinator{};
        harken::FrontierActivationDescriptor originalDescriptor{};
        std::array<harken::Plan03GroupSliceIdentity, 3> originalGroups{};
        std::uint32_t originalGroupCount = 0;
        std::uint32_t readersBeforeBorrow = 0;
        std::array<harken::TimelineArmToken, 2> arms{};
        std::array<harken::EngineTimelineVoiceInstallIdentity, 2> installs{};
        bool called = false;
        std::uint64_t actualZeroWork = 0;
        std::uint64_t chosenZeroWork = 0;
    } observation;
    observation.firing = firing;
    observation.service = row->identity;
    observation.partition = row->partition;
    observation.owner = row->ownerInstance;
    observation.ownerEpoch = row->ownerEpoch;
    observation.invocation = row->invocation;
    observation.invocationGeneration = row->invocationGeneration;
    observation.oldZeroWork = row->QueueFiling().queueSuccessorZeroWorkCompletionFrame;
    observation.refused = refusedPublication;
    observation.holdOriginalReader = holdOriginalReader;
    const auto base = row->scheduleStorageBase;
    ASSERT_LT(base + 1u, engine.playableStorage.memberCount);
    for (std::size_t index = 0; index < observation.arms.size(); ++index) {
        observation.arms[index] = engine.ReadPlayableMember(base + index).arm;
        ASSERT_TRUE(observation.arms[index].Valid());
        ASSERT_TRUE(engine.CaptureTimelineVoiceInstallIdentity(
            engine.ReadPlayableMember(base + index).render, &observation.installs[index]));
        const auto& installed = observation.installs[index];
        EXPECT_EQ(observation.arms[index].slot, installed.startArm.slot);
        EXPECT_EQ(observation.arms[index].generation, installed.startArm.generation);
        EXPECT_EQ(observation.arms[index].renderSlot, installed.startArm.renderSlot);
        EXPECT_EQ(observation.arms[index].renderGeneration, installed.startArm.renderGeneration);
    }
    struct Hooks {
        harken::Engine& engine;
        Observation& observation;
        ~Hooks() {
            // Return only the actual independently minted reader on fatal test exits.
            if (observation.independentReader.Valid())
                EXPECT_TRUE(observation.independentReader.Release(engine.mixer.BlocksRendered()));
            engine.forceImmediateQueueArmPublishFailureAtForTest = UINT32_MAX;
            engine.initialQueuePartialPublishAbortHookForTest = nullptr;
            engine.initialQueuePartialPublishAbortContextForTest = nullptr;
        }
    } hooks{engine, observation};
    engine.initialQueuePartialPublishAbortContextForTest = &observation;
    engine.initialQueuePartialPublishAbortHookForTest = +[](
        harken::Engine& actual, harken::EngineImmediateEntryAttempt& attempt, void* raw) {
        auto& observed = *static_cast<Observation*>(raw);
        if (attempt.root != observed.firing || observed.called) return;
        observed.called = true;
        EXPECT_EQ(UINT32_MAX, actual.forceImmediateQueueArmPublishFailureAtForTest);
        const auto member = std::find_if(actual.playableServices.begin(), actual.playableServices.end(),
            [&](const auto& candidate) { return candidate.identity == observed.service; });
        ASSERT_NE(actual.playableServices.end(), member);
        EXPECT_EQ(observed.firing, member->PendingImmediateCohortRoot());
        EXPECT_EQ(observed.partition.slot, member->partition.slot);
        EXPECT_EQ(observed.partition.generation, member->partition.generation);
        EXPECT_EQ(observed.owner, member->ownerInstance);
        EXPECT_EQ(observed.ownerEpoch, member->ownerEpoch);
        EXPECT_EQ(observed.invocation, member->invocation);
        EXPECT_EQ(observed.invocationGeneration, member->invocationGeneration);
        EXPECT_EQ(&*member, actual.ResolvePlayableService(observed.service,
            observed.owner, observed.ownerEpoch));
        EXPECT_TRUE(actual.playablePartitions.Owns(member->partition, member->identity));
        EXPECT_TRUE(member->QueueFiling().queueSuccessorHasZeroWorkCompletion);
        EXPECT_EQ(0u, member->QueueFiling().queueSuccessorScheduleLeafCount);
        const auto timing = std::find_if(actual.initialQueueTimingMembersScratch.begin(),
            actual.initialQueueTimingMembersScratch.end(),
            [&](const auto& candidate) { return candidate.service == observed.service; });
        ASSERT_NE(actual.initialQueueTimingMembersScratch.end(), timing);
        EXPECT_TRUE(timing->successorHasZeroWorkCompletion);
        EXPECT_EQ(observed.oldZeroWork, timing->oldSuccessorZeroWorkCompletionFrame);
        observed.chosenZeroWork = timing->newSuccessorZeroWorkCompletionFrame;
        observed.actualZeroWork = member->QueueFiling().queueSuccessorZeroWorkCompletionFrame;
        EXPECT_GT(observed.chosenZeroWork, observed.oldZeroWork);
        for (std::size_t index = 0; index < observed.arms.size(); ++index) {
            harken::TimelineArmObservation arm{};
            ASSERT_TRUE(actual.timelineArms.Observe(observed.arms[index], &arm));
            harken::ArmState state{};
            ASSERT_TRUE(actual.timelineArms.State(observed.arms[index], &state));
            EXPECT_EQ(index < observed.refused ? harken::ArmState::Published : harken::ArmState::Armed, state);
            EXPECT_EQ(0u, arm.startedBlockSequence);
            EXPECT_GT(arm.armedCompletionSequence, 0u);
            harken::EngineTimelineVoiceInstallIdentity install{};
            ASSERT_TRUE(actual.CaptureTimelineVoiceInstallIdentity(observed.installs[index].renderHandle, &install));
            EXPECT_EQ(observed.installs[index].renderHandle, install.renderHandle);
            EXPECT_EQ(observed.installs[index].rootInstance, install.rootInstance);
            EXPECT_EQ(observed.installs[index].target, install.target);
            EXPECT_EQ(observed.installs[index].releaseObserver.slot, install.releaseObserver.slot);
            EXPECT_EQ(observed.installs[index].releaseObserver.targetSequence,
                install.releaseObserver.targetSequence);
            EXPECT_EQ(observed.arms[index].slot, install.startArm.slot);
            EXPECT_EQ(observed.arms[index].generation, install.startArm.generation);
            EXPECT_EQ(observed.arms[index].renderSlot, install.startArm.renderSlot);
            EXPECT_EQ(observed.arms[index].renderGeneration, install.startArm.renderGeneration);
            EXPECT_FALSE(actual.voices.ReleaseObserved(observed.installs[index].releaseObserver));
        }
        EXPECT_EQ(observed.refused == 0u ? observed.oldZeroWork : observed.chosenZeroWork,
            observed.actualZeroWork);
        if (observed.holdOriginalReader) {
            ASSERT_EQ(1u, observed.refused);
            ASSERT_TRUE(attempt.lane.Valid());
            observed.originalLane = attempt.lane;
            observed.originalAttemptGeneration = attempt.generation;
            observed.originalCoordinator = attempt.QueueCoordinators().initialQueueCoordinator;
            observed.originalDescriptor = attempt.QueueCoordinators().initialQueueDescriptor;
            observed.originalGroupCount = actual.immediateActionLane.PrivatePinGroupCount(attempt.lane);
            ASSERT_GT(observed.originalGroupCount, 0u);
            ASSERT_LE(observed.originalGroupCount, observed.originalGroups.size());
            for (std::uint32_t index = 0; index < observed.originalGroupCount; ++index)
                ASSERT_TRUE(actual.immediateActionLane.CapturePrivatePinGroup(attempt.lane,index,
                    &observed.originalGroups[index]));
            const auto* second = actual.timelineArms.RowAt(observed.arms[1].slot);
            ASSERT_NE(nullptr, second);
            observed.readersBeforeBorrow = second->frontierReaderPins.load(std::memory_order_acquire);
            ASSERT_GT(observed.readersBeforeBorrow, 0u);
            ASSERT_FALSE(observed.independentReader.Valid());
            ASSERT_TRUE(actual.timelineArms.PinFrontierReader(observed.arms[1],
                &observed.independentReader));
            EXPECT_EQ(observed.readersBeforeBorrow + 1u,
                second->frontierReaderPins.load(std::memory_order_acquire));
        }
    };
    engine.forceImmediateQueueArmPublishFailureAtForTest = refusedPublication;
    const auto beforeAck = engine.mixer.BlocksRendered();
    engine.nullBackend.Pump(2);
    ASSERT_EQ(beforeAck + 2u, engine.mixer.BlocksRendered());
    ASSERT_EQ(VN_OK, Vn_Update());
    EXPECT_TRUE(observation.called);
    EXPECT_EQ(UINT32_MAX, engine.forceImmediateQueueArmPublishFailureAtForTest);
    EXPECT_FALSE(engine.runtimeRecreateRequired);
    if (holdOriginalReader) {
        ASSERT_TRUE(observation.independentReader.Valid());
        const auto completedWhileHeld = engine.mixer.BlocksRendered();
        auto retainedAttempt = [&]() -> harken::EngineImmediateEntryAttempt* {
            for (auto& candidate : std::span(engine.immediateEntryAttempts.data(),
                    engine.immediateEntryAttempts.size()))
                if (candidate.active && candidate.root == firing &&
                    candidate.generation == observation.originalAttemptGeneration)
                    return &candidate;
            return nullptr;
        };
        auto assertOriginalRetained = [&]() {
            auto* retained = retainedAttempt();
            ASSERT_NE(nullptr, retained);
            EXPECT_EQ(observation.originalLane.slot, retained->lane.slot);
            EXPECT_EQ(observation.originalLane.generation, retained->lane.generation);
            EXPECT_TRUE(engine.immediateActionLane.OwnsNeverCommitted(retained->lane,firing));
            EXPECT_EQ(harken::InitialQueuePrivateCleanupPhase::RootReaders, retained->privateCleanupPhase);
            EXPECT_EQ(observation.service.slot, retained->initialService.slot);
            EXPECT_EQ(observation.service.generation, retained->initialService.generation);
            EXPECT_EQ(observation.invocationGeneration, retained->initialInvocationGeneration);
            EXPECT_EQ(observation.originalGroupCount,
                engine.immediateActionLane.PrivatePinGroupCount(retained->lane));
            harken::ImmediateLaneObservation lane{};
            ASSERT_TRUE(engine.immediateActionLane.Observe(retained->lane,&lane));
            EXPECT_FALSE(lane.committed);
            EXPECT_FALSE(lane.applied);
            EXPECT_TRUE(lane.cancelled);
            EXPECT_FALSE(lane.claimed);
            EXPECT_FALSE(lane.missed);
            const auto* c0 = engine.decisions.ResolveFrontierActivation(observation.originalCoordinator);
            ASSERT_NE(nullptr,c0);
            EXPECT_EQ(harken::FrontierReceiptState::Prepared,c0->State());
            EXPECT_EQ(observation.originalDescriptor.entry,c0->Descriptor().entry);
            EXPECT_EQ(observation.originalDescriptor.primary,c0->Descriptor().primary);
            EXPECT_EQ(observation.originalDescriptor.order,c0->Descriptor().order);
            EXPECT_EQ(observation.originalDescriptor.programGeneration,c0->Descriptor().programGeneration);
            EXPECT_EQ(observation.originalDescriptor.expectedMemberCount,c0->Descriptor().expectedMemberCount);
            EXPECT_EQ(observation.originalDescriptor.expectedEntryEventCount,c0->Descriptor().expectedEntryEventCount);
            for (std::uint32_t index = 0; index < observation.originalGroupCount; ++index) {
                harken::Plan03GroupSliceIdentity identity{};
                ASSERT_TRUE(engine.immediateActionLane.CapturePrivatePinGroup(retained->lane,index,&identity));
                EXPECT_EQ(observation.originalGroups[index],identity);
                harken::Plan03PageGroupView group{};
                ASSERT_TRUE(engine.timelinePool.ResolvePlan03GroupSliceProducer(identity,&group));
                ASSERT_NE(nullptr,group.frontier);
                ASSERT_NE(nullptr,group.lease);
                EXPECT_EQ(harken::AudioSliceState::Ready,group.lease->Capture().state);
                EXPECT_EQ(identity,group.frontier->operation.group);
                EXPECT_EQ(observation.service.slot,group.frontier->operation.owner.serviceSlot);
                EXPECT_EQ(observation.service.generation,group.frontier->operation.owner.serviceGeneration);
            }
            EXPECT_TRUE(observation.independentReader.Valid());
            ASSERT_EQ(2u,retained->privateVoiceCount);
            bool foundSecond = false;
            for (std::uint32_t index = 0; index < retained->privateVoiceCount; ++index) {
                const auto& voice = retained->privateVoices[index];
                if (voice.startArm.slot != observation.arms[1].slot ||
                    voice.startArm.generation != observation.arms[1].generation ||
                    voice.startArm.renderSlot != observation.arms[1].renderSlot ||
                    voice.startArm.renderGeneration != observation.arms[1].renderGeneration) continue;
                foundSecond = true;
                EXPECT_EQ(observation.installs[1].renderHandle,voice.render);
                EXPECT_TRUE(voice.rootReaderReleased);
                EXPECT_FALSE(voice.rootArmComplete);
                EXPECT_FALSE(voice.stopQueued);
            }
            EXPECT_TRUE(foundSecond);
            ASSERT_LT(observation.arms[1].slot,engine.initialFrontierArmPins.size());
            EXPECT_FALSE(engine.initialFrontierArmPins[observation.arms[1].slot].pin.Valid());
            const auto* original = engine.timelineArms.RowAt(observation.arms[1].slot);
            ASSERT_NE(nullptr,original);
            EXPECT_EQ(observation.arms[1].generation,original->generation);
            EXPECT_EQ(observation.arms[1].renderSlot,original->renderSlot);
            EXPECT_EQ(observation.arms[1].renderGeneration,original->renderGeneration);
            EXPECT_EQ(1u,original->frontierReaderPins.load(std::memory_order_acquire));
            EXPECT_TRUE(original->nativePrivateWithdrawn.load(std::memory_order_acquire));
            EXPECT_TRUE(original->frontierAdmissionFinished.load(std::memory_order_acquire));
            EXPECT_EQ(nullptr,original->frontierActiveLease.load(std::memory_order_acquire));
            harken::TimelineArmObservation arm{};
            ASSERT_TRUE(engine.timelineArms.Observe(observation.arms[1],&arm));
            EXPECT_EQ(harken::ArmState::CancelRequested,arm.state);
            EXPECT_EQ(0u,arm.startedBlockSequence);
            EXPECT_EQ(0u,arm.tombstoneAudioSequence);
        };
        assertOriginalRetained();
        // Exercise the actual public raw methods; no Arm state or marker is injected.
        EXPECT_FALSE(engine.timelineArms.ClaimAudioSlice(observation.arms[1]));
        engine.timelineArms.ApplyClaimedAudioSlice(observation.arms[1]);
        EXPECT_FALSE(engine.timelineArms.Start(observation.arms[1],completedWhileHeld));
        assertOriginalRetained();
        for (std::uint32_t retry = 0; retry < 2u; ++retry) {
            ASSERT_EQ(VN_OK,Vn_Update());
            EXPECT_EQ(completedWhileHeld,engine.mixer.BlocksRendered());
            EXPECT_FALSE(engine.runtimeRecreateRequired);
            assertOriginalRetained();
        }
        ASSERT_TRUE(observation.independentReader.Release(completedWhileHeld));
        EXPECT_FALSE(observation.independentReader.Valid());
        // The existing normal Pump/Update loop below must complete the genuine tail.
    }
    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
    for (std::uint32_t block = 0; block < 192u &&
         info.state != VN_ACTION_FIRING_TERMINAL_RETAINED; ++block) {
        engine.nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        EXPECT_FALSE(engine.runtimeRecreateRequired);
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
    }
    const auto captureCancellationDiagnostics = [&]() {
        ::testing::Message diagnostic;
        diagnostic << CaptureImmediateQueueContinuationState(engine, firing);
        const auto printDecision = [&](const char* label, harken::DecisionToken token) {
            harken::DecisionCommittedSnapshot committed{};
            const bool captured = engine.decisions.CaptureCommitted(token, &committed);
            diagnostic << "\n" << label << "=" << token.slot << ":" << token.generation
                << " valid=" << token.Valid() << " contains=" << engine.decisions.Contains(token)
                << " open=" << engine.decisions.IsOpen(token)
                << " cancelled=" << engine.decisions.IsCancelled(token)
                << " committed=" << captured
                << " frontierBinding=" << engine.decisions.HasFrontierDecisionBinding(token);
            if (captured)
                diagnostic << " armGroup=" << committed.armGroup.slot << ":" << committed.armGroup.generation
                    << " participants=" << committed.participantCount
                    << " audioState=" << static_cast<unsigned>(committed.audioState)
                    << " slices=" << committed.consumedSlices << "/" << committed.sliceCount
                    << " futurePins=" << committed.futurePinCount
                    << " lastAudio=" << committed.lastAudioSequence;
            if (token.Valid() && token.slot < engine.decisionRetirements.size()) {
                const auto& retained = engine.decisionRetirements[token.slot];
                diagnostic << " retirement=" << retained.decision.slot << ":" << retained.decision.generation
                    << " cancelled=" << retained.cancelled
                    << " phase=" << static_cast<unsigned>(retained.phase)
                    << " group=" << retained.group.slot << ":" << retained.group.generation
                    << " audio=" << retained.retirementAudioSequence;
            }
        };
        const auto printGroup = [&](const char* label, harken::ArmGroupToken token) {
            harken::ArmGroupSnapshot group{};
            const bool captured = engine.armGroups.Capture(token, &group);
            diagnostic << "\n" << label << "=" << token.slot << ":" << token.generation
                << " valid=" << token.Valid() << " captured=" << captured;
            if (captured)
                diagnostic << " parent=" << group.parent.slot << ":" << group.parent.generation
                    << " state=" << static_cast<unsigned>(group.state)
                    << " members=" << group.memberCount << " acked=" << group.ackedCount
                    << " tombstoned=" << group.tombstonedCount
                    << " lastTombstone=" << group.maxTombstoneSequence;
        };
        printDecision("postInitialDecision", originalInitialDecision);
        printDecision("postQueueDecision", originalQueueDecision);
        printGroup("postInitialLaneGroup", originalInitialLaneGroup);
        printGroup("postQueueArmGroup", originalQueueArmGroup);
        const auto* actualRow = engine.ResolvePlayableService(observation.service,
            observation.owner, observation.ownerEpoch);
        diagnostic << "\noriginalServiceResolved=" << (actualRow != nullptr);
        if (actualRow != nullptr) {
            diagnostic << " service=" << actualRow->identity.slot << ":" << actualRow->identity.generation
                << " invocation=" << actualRow->invocationGeneration
                << " originalInvocation=" << observation.invocationGeneration
                << " root=" << actualRow->PendingImmediateCohortRoot()
                << " lifecycle=" << static_cast<unsigned>(actualRow->controlLifecycle)
                << " reason=" << static_cast<unsigned>(actualRow->controlReason)
                << " abort=" << actualRow->queueAbortRequested
                << " naturalEnd=" << actualRow->queueNaturalEnd
                << " terminal=" << actualRow->terminalObserved
                << " finalSource=" << actualRow->queueFinalSourceTombstoned
                << " cleanup=" << actualRow->queueCleanupStarted
                << " compositeMirrors=" << actualRow->queueCompositeMirrorsCleared
                << " continuation=" << actualRow->queueContinuationPrepared
                << " decisionCommitted=" << actualRow->QueueFiling().queueDecisionCommitted
                << " initialAttempt=" << actualRow->QueuePayload().initialQueueEntryAttemptGeneration
                << " firstContinuation=" << actualRow->queueFirstContinuationLane
                << " partitionRetiring=" << actualRow->partitionRetiring
                << " partitionOwned=" << engine.playablePartitions.Owns(actualRow->partition, actualRow->identity)
                << " pendingCancellation=" << static_cast<unsigned>(actualRow->pendingCancellationIntent)
                << " frontierEntry=" << actualRow->frontierEntry.Valid()
                << " frontierPin=" << actualRow->frontierLifetimePin.Valid()
                << " privateInitial=" << (actualRow->QueuePayload().privateInitialQueueCurrent != nullptr)
                << " hasZeroWork=" << actualRow->hasZeroWorkCompletion
                << " conditionalVersion=" << actualRow->QueueFiling().queueConditional.version;
            printDecision("rowInitialDecision", actualRow->initialQueueEntryDecision);
            printDecision("rowQueueDecision", actualRow->QueueFiling().queueDecision);
            printDecision("rowArrivalDecision", actualRow->queueArrivalDecision);
            printGroup("rowInitialLaneGroup", actualRow->QueuePayload().queueInitialLaneArmGroup);
            printGroup("rowQueueArmGroup", actualRow->QueueFiling().queueArmGroup);
            printGroup("rowArrivalArmGroup", actualRow->QueuePayload().queueArrivalArmGroup);
            const auto root = engine.playableInstances.Classify(actualRow->rootInstance);
            diagnostic << "\nplayableRoot live=" << root.live
                << " lifecycle=" << static_cast<unsigned>(root.lifecycle)
                << " terminal=" << static_cast<unsigned>(root.terminalOutcome.kind);
        }
        harken::QueueInstanceSnapshot actualQueue{};
        const bool queueCaptured = engine.queueInstances.Capture(originalQueue, &actualQueue);
        diagnostic << "\noriginalQueue captured=" << queueCaptured;
        if (queueCaptured)
            diagnostic << " pendingVersion=" << actualQueue.pendingVersion
                << " activation=" << static_cast<unsigned>(actualQueue.pendingActivation)
                << " initialActivation=" << actualQueue.initialActivationSequence
                << " failurePhase=" << static_cast<unsigned>(actualQueue.failurePhase)
                << " failureReason=" << static_cast<unsigned>(actualQueue.failureReason)
                << " failureFrame=" << actualQueue.failureFrame;
        for (const auto& actualAttempt : std::span(engine.immediateEntryAttempts.data(),
                engine.immediateEntryAttempts.size())) {
            if (!actualAttempt.active || actualAttempt.root != firing) continue;
            diagnostic << "\noriginalAttempt=" << actualAttempt.generation
                << " lane=" << actualAttempt.lane.slot << ":" << actualAttempt.lane.generation
                << " cleanup=" << static_cast<unsigned>(actualAttempt.privateCleanupPhase)
                << " c1Failed=" << actualAttempt.queueContinuationFailed;
            const auto* activation = engine.decisions.ResolveFrontierActivation(
                actualAttempt.QueueCoordinators().initialQueueCoordinator);
            if (activation != nullptr)
                diagnostic << " activationState=" << static_cast<unsigned>(activation->State());
            harken::ImmediateLaneObservation lane{};
            if (engine.immediateActionLane.Observe(actualAttempt.lane, &lane))
                diagnostic << " privatePins=" << engine.immediateActionLane.PrivatePinGroupCount(actualAttempt.lane)
                    << " committed=" << lane.committed << " complete=" << lane.complete
                    << " cancelled=" << lane.cancelled;
        }
        for (const auto& original : observation.arms) {
            harken::TimelineArmObservation arm{};
            if (!engine.timelineArms.Observe(original, &arm)) continue;
            diagnostic << "\noriginalArm=" << original.slot << ":" << original.generation
                << " state=" << static_cast<unsigned>(arm.state)
                << " started=" << arm.startedBlockSequence
                << " tombstone=" << arm.tombstoneAudioSequence;
            const auto* native = engine.timelineArms.RowAt(original.slot);
            if (native != nullptr)
                diagnostic << " readers=" << native->frontierReaderPins.load(std::memory_order_acquire);
            if (original.slot < engine.initialFrontierArmPins.size())
                diagnostic << " initialPin=" << engine.initialFrontierArmPins[original.slot].pin.Valid();
        }
        return diagnostic.GetString();
    };
    EXPECT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state)
        << captureCancellationDiagnostics();
    EXPECT_EQ(0u, info.livePlayableCount);
    EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    EXPECT_EQ(VN_OK, Vn_DestroyEmitter(desc.emitter));
    for (std::uint32_t block = 0; block < 192u &&
         CaptureActionReclaimableOwners(engine) != ownersBefore; ++block) {
        engine.nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        EXPECT_FALSE(engine.runtimeRecreateRequired);
    }
    EXPECT_EQ(ownersBefore, CaptureActionReclaimableOwners(engine))
        << captureCancellationDiagnostics();
    harken::QueueInstanceSnapshot queue{};
    EXPECT_FALSE(engine.queueInstances.Capture(originalQueue, &queue));
    harken::CompositeCompletionOwnerInfo composite{};
    EXPECT_FALSE(engine.compositeCompletionOwners.Capture(originalComposite, &composite));
    for (std::size_t index = 0; index < observation.arms.size(); ++index) {
        harken::TimelineArmObservation stale{};
        EXPECT_FALSE(engine.timelineArms.Observe(observation.arms[index], &stale));
        EXPECT_EQ(nullptr, engine.voices.Resolve(observation.installs[index].renderHandle));
        EXPECT_TRUE(engine.voices.ReleaseObserved(observation.installs[index].releaseObserver));
        harken::EngineTimelineVoiceInstallIdentity staleInstall{};
        EXPECT_FALSE(engine.CaptureTimelineVoiceInstallIdentity(
            observation.installs[index].renderHandle, &staleInstall));
    }
    EXPECT_EQ(sourcesBefore, sourceCount());
    for (std::uint32_t slot = 0; slot < sourceGenerationsBefore.size(); ++slot) {
        const auto& source = *engine.sourceTerminals.At(slot);
        if (source.generation == sourceGenerationsBefore[slot]) continue;
        EXPECT_FALSE(source.occupied);
        EXPECT_TRUE(engine.voices.ReleaseObserved(source.release));
        EXPECT_FALSE(engine.playableInstances.HasSourceRetirementHold(source.leaf));
        EXPECT_FALSE(engine.playableInstances.Classify(source.leaf).live);
    }
    EXPECT_FALSE(engine.runtimeRecreateRequired);
}

TEST(ActionFiringApi, GenericInitialQueueFirstArmRefusalRestoresRealZeroWorkCompletion) {
    CheckGenericInitialQueuePublishRefusalPreservesOriginalZeroWork(0u);
}
TEST(ActionFiringApi, GenericInitialQueueSecondArmRefusalRetainsExposedZeroWorkCompletion) {
    CheckGenericInitialQueuePublishRefusalPreservesOriginalZeroWork(1u);
}

TEST(ActionFiringApi, GenericInitialQueueSecondArmRefusalRetainsOwnerUntilIndependentOriginalReaderReturns) {
    CheckGenericInitialQueuePublishRefusalPreservesOriginalZeroWork(1u,true);
}

static void CheckNativeQueueOriginalHoldersAcrossTrueAckAndOldProgress(bool termAfterC1) {
    (void)Vn_Term();
    const auto config = harkentest::MakeNullConfig(8, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    const auto baselineDecisions = engine->decisions.LiveCount();
    const auto baselineArmGroups = engine->armGroups.LiveCount();
    const auto baselinePlayables = engine->playableInstances.LiveCount();
    std::vector<float> first(64, 0.25f);
    std::vector<float> second(128, -0.25f);
    const auto firstPcm = harkentest::MonoDesc(first, 48000);
    const auto secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &secondPcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
    MakeOriginalQueueCurrentTrackWith17FrameOffset(image);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
        harken::InstallContainerWorldV1(*engine, image.world).status);
    const auto ownersBefore = CaptureActionReclaimableOwners(*engine);
    const auto sourceGenerationsBefore = CaptureSourceGenerations(*engine);
    const auto sourcesBefore = CountStaggeredCurrentOriginalSourceOwners(*engine);
    auto desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&desc.emitter));
    const auto beforePostSequence = engine->mixer.BlocksRendered();
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    VnActionStepResult play{};
    play.structSize = sizeof(play);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
    ASSERT_EQ(VN_ACTION_STEP_ACTIVE, play.state);
    ASSERT_NE(0u, play.producedPlayableInstance);
    auto row = std::find_if(engine->playableServices.begin(), engine->playableServices.end(),
        [&](const auto& current) { return current.rootInstance == play.producedPlayableInstance; });
    ASSERT_NE(engine->playableServices.end(), row);
    ASSERT_TRUE(row->InvocationValid());
    ASSERT_EQ(firing, row->Invocation().actionFiring);
    ASSERT_TRUE(row->queueFirstContinuationLane);
    ASSERT_TRUE(row->QueuePayload().queueCurrentCompositeOwner.Valid());
    ASSERT_EQ(2u, row->QueuePayload().queueCurrentScheduleLeafCount);
    ASSERT_EQ(2u, row->scheduleLeafCount);
    ASSERT_EQ(2u, row->QueuePayload().queueInitialCurrentMemberLeafCount);
    ASSERT_EQ(1u, row->QueuePayload().queueInitialCurrentDelayedCount);
    EXPECT_EQ(UINT16_MAX, row->QueuePayload().queueInitialCurrentMemberIndices[0]);
    EXPECT_EQ(0u, row->QueuePayload().queueInitialCurrentMemberIndices[1]);
    const harken::EnginePlayableServiceReference savedService{
        row->identity, row->ownerInstance, row->ownerEpoch, row->invocationGeneration};
    const auto savedQueue = row->queueInstance;
    const auto savedRoot = row->rootInstance;
    const auto savedComposite = row->QueuePayload().queueCurrentCompositeOwner;
    const auto savedOccurrence = row->QueuePayload().queueCurrentOccurrence;
    const auto savedSuccessorOccurrence = row->QueueFiling().queueSuccessorOccurrence;
    const auto savedConditional = row->QueueFiling().queueConditional;
    const auto savedInitialDecision = row->initialQueueEntryDecision;
    const auto savedConditionalDecision = row->QueueFiling().queueDecision;
    const auto savedInitialArmGroup = row->QueuePayload().queueInitialLaneArmGroup;
    const auto savedSuccessorArm = row->QueueFiling().queueSuccessorArm;
    const auto savedSuccessorRender = row->QueuePayload().queueSuccessorRenderHandle;
    const auto base = static_cast<std::size_t>(row->scheduleStorageBase);
    ASSERT_LT(base + 1u, engine->playableStorage.memberCount);
    const std::array<harken::TimelineArmToken, 2> currentArms{
        engine->ReadPlayableMember(base).arm, engine->ReadPlayableMember(base + 1u).arm};
    const std::array<std::uint64_t, 2> currentRenders{
        engine->ReadPlayableMember(base).render, engine->ReadPlayableMember(base + 1u).render};
    std::array<harken::EngineTimelineVoiceInstallIdentity, 3> originalInstalls{};
    const std::array<std::uint64_t, 3> originalRenders{
        currentRenders[0], currentRenders[1], savedSuccessorRender};
    std::array<const harken::OriginalSourceSubmissionRegistry::Record*, 3> originalSubmissions{};
    for (std::size_t index = 0; index < originalInstalls.size(); ++index) {
        ASSERT_TRUE(engine->CaptureTimelineVoiceInstallIdentity(originalRenders[index], &originalInstalls[index]));
        originalSubmissions[index] = engine->originalSourceSubmissions.Find(originalInstalls[index].startArm);
        ASSERT_NE(nullptr, originalSubmissions[index]);
        EXPECT_TRUE(harken::OriginalSourceSubmissionRegistry::SameToken(
            originalInstalls[index].startArm, originalSubmissions[index]->Token()));
        EXPECT_EQ(harken::OriginalSourceSubmissionRegistry::Phase::Published, originalSubmissions[index]->State());
    }
    const auto sameArm = [](harken::TimelineArmToken a, harken::TimelineArmToken b) {
        return a.slot == b.slot && a.generation == b.generation &&
            a.renderSlot == b.renderSlot && a.renderGeneration == b.renderGeneration;
    };
    ASSERT_TRUE(sameArm(currentArms[1], row->QueuePayload().queueInitialCurrentDelayedArms[0]));
    ASSERT_TRUE(savedInitialDecision.Valid());
    ASSERT_TRUE(savedConditionalDecision.Valid());
    ASSERT_TRUE(savedInitialArmGroup.Valid());
    ASSERT_TRUE(savedSuccessorArm.Valid());
    ASSERT_NE(0u, savedSuccessorRender);
    ASSERT_TRUE(savedConditional.Valid());
    ASSERT_NE(0u, savedSuccessorOccurrence.generation);
    harken::ArmGroupSnapshot beforeGroup{};
    ASSERT_TRUE(engine->armGroups.Capture(savedInitialArmGroup, &beforeGroup));
    EXPECT_EQ(savedInitialDecision.slot, beforeGroup.parent.slot);
    EXPECT_EQ(savedInitialDecision.generation, beforeGroup.parent.generation);
    ASSERT_EQ(1u, beforeGroup.memberCount);
    EXPECT_EQ(0u, beforeGroup.ackedCount);
    harken::ArmGroupMemberSnapshot member{};
    ASSERT_TRUE(engine->armGroups.CaptureMember(savedInitialArmGroup, 0u, &member));
    EXPECT_TRUE(sameArm(currentArms[1], member.token));
    EXPECT_FALSE(member.acked);
    for (std::uint32_t leaf = 0; leaf < 2u; ++leaf) {
        harken::TimelineArmObservation original{};
        ASSERT_TRUE(engine->timelineArms.Observe(currentArms[leaf], &original));
        EXPECT_EQ(0u, original.startedBlockSequence);
        if (leaf == 0u) EXPECT_FALSE(original.parentGroup.Valid());
        else {
            EXPECT_EQ(savedInitialDecision.slot, original.parentGroup.decision.slot);
            EXPECT_EQ(savedInitialDecision.generation, original.parentGroup.decision.generation);
            EXPECT_EQ(0u, original.memberIndex);
        }
    }
    auto* attempt = std::find_if(engine->immediateEntryAttempts.data(),
        engine->immediateEntryAttempts.data() + engine->immediateEntryAttempts.size(),
        [firing](const auto& actual) { return actual.active && actual.root == firing; });
    ASSERT_NE(engine->immediateEntryAttempts.data() + engine->immediateEntryAttempts.size(), attempt);
    const auto savedAttemptSlot = static_cast<std::size_t>(attempt - engine->immediateEntryAttempts.data());
    const auto savedAttemptGeneration = attempt->generation;
    const auto savedLane = attempt->lane;
    const auto savedC0Coordinator = attempt->QueueCoordinators().initialQueueCoordinator;
    const auto savedC1Coordinator = attempt->QueueCoordinators().queueContinuationCoordinator;
    ASSERT_TRUE(savedLane.Valid());
    ASSERT_TRUE(savedC0Coordinator.Valid());
    ASSERT_TRUE(savedC1Coordinator.Valid());
    const auto resolveAttempt = [&]() -> const harken::EngineImmediateEntryAttempt* {
        const auto& actual = engine->immediateEntryAttempts[savedAttemptSlot];
        if (!actual.active || actual.generation != savedAttemptGeneration || actual.root != firing ||
            actual.lane.slot != savedLane.slot || actual.lane.generation != savedLane.generation ||
            actual.initialService != savedService.token ||
            actual.initialInvocationGeneration != savedService.invocationGeneration) return nullptr;
        return &actual;
    };
    const auto resolveRow = [&]() -> harken::EnginePlayableServiceRow* {
        auto* actual = engine->ResolvePlayableService(savedService);
        if (actual == nullptr || actual->rootInstance != savedRoot || !actual->InvocationValid() ||
            actual->Invocation().actionFiring != firing || actual->queueInstance.slot != savedQueue.slot ||
            actual->queueInstance.generation != savedQueue.generation) return nullptr;
        return actual;
    };


    harken::QueueInstanceTable::OriginalLifetimePin originalQueueLoan;
    harken::EngineQueueProgramBank::OriginalLifetimePin originalCurrentBankLoan, originalSuccessorBankLoan;
    ASSERT_TRUE(engine->BorrowOriginalQueueLifetime(savedService, &originalQueueLoan));
    ASSERT_TRUE(engine->BorrowOriginalQueueCurrentBank(savedService, &originalCurrentBankLoan));
    ASSERT_TRUE(engine->BorrowOriginalQueueSuccessorBank(savedService, &originalSuccessorBankLoan));
    ASSERT_TRUE(originalQueueLoan.Valid());
    auto* originalCurrentBank = row->QueuePayload().queueCurrentProgramBank;
    auto* originalSuccessorBank = row->QueueFiling().queueSuccessorProgramBank;
    ASSERT_NE(nullptr, originalCurrentBank);
    ASSERT_NE(nullptr, originalSuccessorBank);
    const auto originalCurrentGeneration = originalCurrentBank->Generation();
    const auto originalSuccessorGeneration = originalSuccessorBank->Generation();
    std::array<harken::Plan03ImmediateLaneGroupDescriptor, 4> beforeAckGroups{};
    ASSERT_EQ(4u, engine->timelinePool.CaptureLiveImmediateLaneCohortGroups(
        firing, beforeAckGroups.data(), beforeAckGroups.size()));
    std::array<harken::OriginalQueueFutureGroupLifetimePin, 2> originalMemberLoans;
    std::size_t originalMemberLoanCount = 0;
    for (const auto& group : beforeAckGroups) {
        const bool initial = group.identity.decision.slot == savedInitialDecision.slot &&
            group.identity.decision.generation == savedInitialDecision.generation;
        const bool conditional = group.identity.decision.slot == savedConditionalDecision.slot &&
            group.identity.decision.generation == savedConditionalDecision.generation;
        if (!initial && !conditional) continue;
        ASSERT_LT(originalMemberLoanCount, originalMemberLoans.size());
        ASSERT_TRUE(engine->BorrowOriginalQueueFutureGroup(savedService, group.identity,
            &originalMemberLoans[originalMemberLoanCount++]));
    }
    ASSERT_EQ(2u, originalMemberLoanCount);
    auto staleService = savedService;
    ++staleService.invocationGeneration;
    harken::QueueInstanceTable::OriginalLifetimePin refusedQueueLoan;
    EXPECT_FALSE(engine->BorrowOriginalQueueLifetime(staleService, &refusedQueueLoan));
    EXPECT_FALSE(refusedQueueLoan.Valid());
    EXPECT_FALSE(engine->BorrowOriginalQueueLifetime(savedService, &originalQueueLoan));
    EXPECT_TRUE(originalQueueLoan.Valid());
    EXPECT_FALSE(engine->ResetOriginalQueueBank(*originalCurrentBank));
    EXPECT_FALSE(engine->ResetOriginalQueueBank(*originalSuccessorBank));
    EXPECT_EQ(originalCurrentGeneration, originalCurrentBank->Generation());
    EXPECT_EQ(originalSuccessorGeneration, originalSuccessorBank->Generation());

    // Only the real audio installation command creates the ACK; Update binds it.
    engine->nullBackend.Pump(1);
    ASSERT_EQ(VN_OK, Vn_Update());
    ASSERT_NE(nullptr, resolveRow()) << CaptureImmediateQueueContinuationState(*engine, firing);
    const auto* published = resolveAttempt();
    ASSERT_NE(nullptr, published);
    harken::ImmediateLaneObservation lane{};
    ASSERT_TRUE(engine->immediateActionLane.Observe(savedLane, &lane));
    ASSERT_TRUE(lane.committed);
    ASSERT_FALSE(lane.missed);
    ASSERT_FALSE(lane.cancelled);
    ASSERT_FALSE(lane.protocolRefused);
    const auto c0 = published->QueueCoordinators().initialQueueDescriptor;
    const auto c1 = published->QueueCoordinators().queueContinuationDescriptor;
    const auto entryQuantum = published->entryQuantum;
    const auto lastQuantum = published->lastQuantum;
    ASSERT_TRUE(c0.Valid());
    ASSERT_TRUE(c1.Valid());
    ASSERT_EQ(2u, c0.expectedEntryEventCount);
    ASSERT_EQ(1u, c0.expectedMemberCount);
    ASSERT_EQ(1u, c1.expectedEntryEventCount);
    ASSERT_EQ(1u, c1.expectedMemberCount);
    const auto start = c0.order.executeFrame;
    const auto boundary = c1.order.executeFrame;
    ASSERT_EQ(entryQuantum * config.blockFrames, start);
    ASSERT_EQ(start + 145u, boundary);
    const auto boundaryQuantum = boundary / config.blockFrames;
    ASSERT_EQ(17u, boundary % config.blockFrames);
    ASSERT_EQ(boundaryQuantum, lastQuantum);
    ASSERT_GT(entryQuantum + 1u, beforePostSequence);
    ASSERT_LT(entryQuantum, boundaryQuantum);
    ASSERT_EQ(boundary, resolveRow()->QueuePayload().queueCompletionFrame);
    harken::ArmGroupSnapshot readyGroup{};
    ASSERT_TRUE(engine->armGroups.Capture(savedInitialArmGroup, &readyGroup));
    EXPECT_EQ(harken::ArmGroupState::Ready, readyGroup.state);
    EXPECT_EQ(1u, readyGroup.ackedCount);
    for (std::uint32_t leaf = 0; leaf < 2u; ++leaf) {
        harken::TimelineArmObservation armed{};
        ASSERT_TRUE(engine->timelineArms.Observe(currentArms[leaf], &armed));
        EXPECT_GT(armed.armedCompletionSequence, beforePostSequence);
        EXPECT_EQ(0u, armed.startedBlockSequence);
        EXPECT_EQ(harken::ArmState::Published, armed.state);
        harken::EngineTimelineVoiceInstallIdentity installation{};
        ASSERT_TRUE(engine->CaptureTimelineVoiceInstallIdentity(currentRenders[leaf], &installation));
        EXPECT_TRUE(sameArm(currentArms[leaf], installation.startArm));
        EXPECT_EQ(start + (leaf == 0u ? 0u : 17u), installation.onsetFrame);
        EXPECT_EQ(installation.onsetFrame, engine->ReadPlayableMember(base + leaf).startFrame);
    }
    std::array<harken::KnownScheduleLeafV1, 2> originalLeaves{};
    harken::CompositeCompletionOwnerInfo complete{};
    ASSERT_TRUE(engine->compositeCompletionOwners.Capture(savedComposite, &complete));
    EXPECT_EQ(savedOccurrence.slot, complete.composedOccurrence.slot);
    EXPECT_EQ(savedOccurrence.generation, complete.composedOccurrence.generation);
    EXPECT_EQ(boundary, complete.absoluteLogicalCompleteFrame);
    for (std::uint32_t leaf = 0; leaf < 2u; ++leaf) {
        ASSERT_TRUE(engine->compositeCompletionOwners.CaptureLeaf(savedComposite, leaf, &originalLeaves[leaf]));
        EXPECT_EQ(leaf == 0u ? 0 : 17, originalLeaves[leaf].authoredOffset.numerator);
        EXPECT_EQ(1u, originalLeaves[leaf].authoredOffset.denominator);
        EXPECT_EQ(start + (leaf == 0u ? 0u : 17u), originalLeaves[leaf].absoluteLeafStartFrame);
        EXPECT_EQ(start + (leaf == 0u ? 64u : 145u),
            originalLeaves[leaf].predicate.absoluteLogicalCompleteFrame);
    }
    std::array<harken::Plan03ImmediateLaneGroupDescriptor, 4> groups{};
    const auto groupCount = engine->timelinePool.CaptureLiveImmediateLaneCohortGroups(
        firing, groups.data(), groups.size());
    ASSERT_EQ(4u, groupCount);
    std::size_t nativeInitial = 0u;
    std::size_t nativeConditional = 0u;
    for (std::size_t index = 0; index < groupCount; ++index) {
        const auto& actual = groups[index];
        EXPECT_EQ(savedLane.slot, actual.laneSlot);
        EXPECT_EQ(savedLane.generation, actual.laneGeneration);
        harken::Plan03PageGroupView view{};
        ASSERT_TRUE(engine->timelinePool.ResolvePlan03GroupSliceProducer(actual.identity, &view));
        ASSERT_NE(nullptr, view.frontier);
        if (actual.identity.decision.slot == savedInitialDecision.slot &&
            actual.identity.decision.generation == savedInitialDecision.generation) {
            ++nativeInitial;
            ASSERT_EQ(1u, view.memberCount);
            ASSERT_NE(nullptr, view.members);
            EXPECT_TRUE(sameArm(currentArms[1], view.members[0]));
            EXPECT_EQ(entryQuantum, actual.dueQuantum);
            EXPECT_TRUE(view.frontier->entry == c0.entry);
            EXPECT_TRUE(view.frontier->queueInitial.Valid());
        }
        if (actual.identity.decision.slot == savedConditionalDecision.slot &&
            actual.identity.decision.generation == savedConditionalDecision.generation) {
            ++nativeConditional;
            ASSERT_EQ(1u, view.memberCount);
            EXPECT_TRUE(sameArm(savedSuccessorArm, view.members[0]));
            EXPECT_EQ(boundaryQuantum, actual.dueQuantum);
            EXPECT_TRUE(view.frontier->entry == c1.entry);
            ASSERT_TRUE(view.frontier->queueConditional.Valid());
            EXPECT_EQ(savedOccurrence.slot, view.frontier->queueConditional.current.slot);
            EXPECT_EQ(savedOccurrence.generation, view.frontier->queueConditional.current.generation);
            EXPECT_EQ(savedSuccessorOccurrence.slot, view.frontier->queueConditional.successor.slot);
            EXPECT_EQ(savedSuccessorOccurrence.generation, view.frontier->queueConditional.successor.generation);
            EXPECT_EQ(savedConditional.version, view.frontier->queueConditional.pendingVersion);
        }
    }
    ASSERT_EQ(1u, nativeInitial);
    ASSERT_EQ(1u, nativeConditional);
    EXPECT_TRUE(originalQueueLoan.Valid());
    EXPECT_TRUE(originalCurrentBankLoan.Valid());
    EXPECT_TRUE(originalSuccessorBankLoan.Valid());
    for (const auto& loan : originalMemberLoans) EXPECT_TRUE(loan.Valid());
    harken::EngineQueueProgramBank::OriginalLifetimePin postAckDescendant;
    ASSERT_TRUE(originalCurrentBankLoan.Borrow(&postAckDescendant));
    EXPECT_EQ(originalCurrentGeneration, postAckDescendant.Generation());
    postAckDescendant.Release();

    const auto checkDescriptor = [](const auto& actual, const auto& saved) {
        return actual.entry == saved.entry && actual.primary == saved.primary && actual.order == saved.order &&
            actual.worldGeneration == saved.worldGeneration &&
            actual.worldSemanticFingerprint == saved.worldSemanticFingerprint &&
            actual.programGeneration == saved.programGeneration &&
            actual.expectedEntryEventCount == saved.expectedEntryEventCount &&
            actual.expectedMemberCount == saved.expectedMemberCount;
    };
    ASSERT_LE(engine->mixer.BlocksRendered(), entryQuantum);
    while (engine->mixer.BlocksRendered() < entryQuantum) {
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_NE(nullptr, resolveAttempt());
        engine->nullBackend.Pump(1);
    }
    engine->nullBackend.Pump(1);
    ASSERT_EQ(entryQuantum + 1u, engine->mixer.BlocksRendered());
    // Inspect the exact callback before logic can reconcile or another Pump can replace it.
    const auto* entryPcm = engine->nullBackend.LastBlock();
    ASSERT_NE(nullptr, entryPcm);
    ASSERT_EQ(64u, engine->nullBackend.BlockFrames());
    for (std::uint32_t sample = 0; sample < engine->nullBackend.BlockFrames(); ++sample) {
        const auto expected = sample < 17u ? 0.25f : 0.0f;
        for (std::uint32_t channel = 0; channel < engine->nullBackend.Channels(); ++channel)
            EXPECT_NEAR(expected, entryPcm[sample * engine->nullBackend.Channels() + channel], 0.0001f)
                << "C0 sample=" << sample << " channel=" << channel;
    }
    const auto* entryActivation = engine->decisions.ResolveFrontierActivation(savedC0Coordinator);
    ASSERT_NE(nullptr, entryActivation);
    ASSERT_TRUE(checkDescriptor(entryActivation->Descriptor(), c0));
    harken::FrontierActivationReceipt entered{};
    ASSERT_EQ(harken::FrontierReceiptRead::Ready,
        entryActivation->Read(c0.entry, engine->mixer.BlocksRendered(), &entered));
    EXPECT_TRUE(entered.entry == c0.entry);
    EXPECT_TRUE(entered.order == c0.order);
    EXPECT_EQ(harken::FrontierReceiptOrigin::Audio, entered.origin);
    ASSERT_EQ(harken::FrontierReceiptOutcome::Applied, entered.outcome);
    EXPECT_EQ(harken::FrontierReceiptReason::None, entered.reason);
    EXPECT_EQ(entryQuantum + 1u, entered.audioSequence);
    for (std::uint32_t leaf = 0; leaf < 2u; ++leaf) {
        harken::TimelineArmObservation actual{};
        ASSERT_TRUE(engine->timelineArms.Observe(currentArms[leaf], &actual));
        EXPECT_EQ(entryQuantum + 1u, actual.startedBlockSequence);
        const auto* progress = engine->timelineOccurrences.CompletionProgressOf(originalLeaves[leaf].occurrence);
        ASSERT_NE(nullptr, progress);
        harken::CompletionProgressSnapshot output{};
        ASSERT_TRUE(harken::CaptureCompletionProgressExact(*progress, originalLeaves[leaf].occurrence,
            originalLeaves[leaf].renderGeneration, &output));
        EXPECT_EQ(entryQuantum + 1u, output.completedThroughBlockSequence);
        EXPECT_EQ(leaf == 0u ? 64u : 47u, output.logicalOutputFramesProduced);
    }
    // Read fresh C0 and exact per-leaf production before logic can reconcile.
    ASSERT_EQ(VN_OK, Vn_Update());
    ASSERT_NE(nullptr, resolveRow());
    ASSERT_LE(engine->mixer.BlocksRendered(), boundaryQuantum);
    while (engine->mixer.BlocksRendered() < boundaryQuantum) {
        const auto* activation = engine->decisions.ResolveFrontierActivation(savedC1Coordinator);
        ASSERT_NE(nullptr, activation);
        ASSERT_TRUE(checkDescriptor(activation->Descriptor(), c1));
        harken::FrontierActivationReceipt waiting{};
        EXPECT_EQ(harken::FrontierReceiptRead::InFlight,
            activation->Read(c1.entry, engine->mixer.BlocksRendered(), &waiting));
        harken::TimelineArmObservation notStarted{};
        ASSERT_TRUE(engine->timelineArms.Observe(savedSuccessorArm, &notStarted));
        EXPECT_EQ(0u, notStarted.startedBlockSequence);
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_NE(nullptr, resolveRow());
    }
    ASSERT_EQ(boundaryQuantum, engine->mixer.BlocksRendered());
    engine->nullBackend.Pump(1);
    ASSERT_EQ(boundaryQuantum + 1u, engine->mixer.BlocksRendered());
    const auto* continuationPcm = engine->nullBackend.LastBlock();
    ASSERT_NE(nullptr, continuationPcm);
    for (std::uint32_t sample = 0; sample < engine->nullBackend.BlockFrames(); ++sample)
        for (std::uint32_t channel = 0; channel < engine->nullBackend.Channels(); ++channel)
            EXPECT_NEAR(-0.25f, continuationPcm[sample * engine->nullBackend.Channels() + channel], 0.0001f)
                << "C1 sample=" << sample << " channel=" << channel;
    const auto* continuationActivation = engine->decisions.ResolveFrontierActivation(savedC1Coordinator);
    ASSERT_NE(nullptr, continuationActivation);
    ASSERT_TRUE(checkDescriptor(continuationActivation->Descriptor(), c1));
    harken::FrontierActivationReceipt continued{};
    ASSERT_EQ(harken::FrontierReceiptRead::Ready,
        continuationActivation->Read(c1.entry, engine->mixer.BlocksRendered(), &continued))
        << CaptureImmediateQueueContinuationState(*engine, firing);
    EXPECT_TRUE(continued.entry == c1.entry);
    EXPECT_TRUE(continued.order == c1.order);
    EXPECT_EQ(harken::FrontierReceiptOrigin::Audio, continued.origin);
    ASSERT_EQ(harken::FrontierReceiptOutcome::Applied, continued.outcome);
    EXPECT_EQ(harken::FrontierReceiptReason::None, continued.reason);
    EXPECT_EQ(boundaryQuantum + 1u, continued.audioSequence);
    harken::TimelineArmObservation successorStarted{};
    ASSERT_TRUE(engine->timelineArms.Observe(savedSuccessorArm, &successorStarted));
    EXPECT_EQ(boundaryQuantum + 1u, successorStarted.startedBlockSequence);
    harken::EngineTimelineVoiceInstallIdentity successorInstallation{};
    ASSERT_TRUE(engine->CaptureTimelineVoiceInstallIdentity(savedSuccessorRender, &successorInstallation));
    EXPECT_TRUE(sameArm(savedSuccessorArm, successorInstallation.startArm));
    EXPECT_EQ(boundary, successorInstallation.onsetFrame);
    harken::QueueInstanceSnapshot activated{};
    ASSERT_TRUE(engine->queueInstances.Capture(savedQueue, &activated));
    EXPECT_EQ(savedConditional.version, activated.pendingVersion);
    EXPECT_EQ(harken::ConditionalQueueActivation::Activated, activated.pendingActivation);
    ASSERT_TRUE(engine->immediateActionLane.Observe(savedLane, &lane));
    ASSERT_TRUE(lane.complete);
    ASSERT_FALSE(lane.missed);
    ASSERT_FALSE(lane.cancelled);
    ASSERT_FALSE(lane.protocolRefused);

    // Old native publication and both Audio Applied receipts have progressed
    // while real factory lifetime loans were held across ACK and callbacks.
    EXPECT_TRUE(originalQueueLoan.Valid());
    EXPECT_TRUE(originalCurrentBankLoan.Valid());
    EXPECT_TRUE(originalSuccessorBankLoan.Valid());
    for (auto& loan : originalMemberLoans) { EXPECT_TRUE(loan.Valid()); loan.Release(); }
    originalQueueLoan.Release();
    originalCurrentBankLoan.Release();
    originalSuccessorBankLoan.Release();
    if (termAfterC1) {
        EXPECT_EQ(VN_OK, Vn_Term());
        return;
    }

    // The actual last-quantum readers must survive the same audio sequence.
    const auto completedSequence = lastQuantum + 1u;
    ASSERT_EQ(completedSequence, engine->mixer.BlocksRendered());
    ASSERT_EQ(VN_OK, Vn_Update());
    ASSERT_TRUE(engine->immediateActionLane.Observe(savedLane, &lane));
    ASSERT_TRUE(lane.complete);
    ASSERT_NE(nullptr, resolveAttempt());
    engine->nullBackend.Pump(1);
    ASSERT_EQ(completedSequence + 1u, engine->mixer.BlocksRendered());
    ASSERT_EQ(VN_OK, Vn_Update());
    EXPECT_FALSE(engine->immediateActionLane.Observe(savedLane, &lane));
    EXPECT_EQ(nullptr, resolveAttempt());
    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    for (std::uint32_t block = 0; block < 96u; ++block) {
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
        if (info.state == VN_ACTION_FIRING_TERMINAL_RETAINED &&
            engine->voices.ActiveCount() == 0u && engine->queueInstances.LiveCount() == 0u &&
            engine->decisions.LiveCount() == baselineDecisions &&
            engine->armGroups.LiveCount() == baselineArmGroups) break;
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
    }
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
    ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state)
        << StaggeredCurrentActualCleanupDiagnostic(*engine, firing);
    EXPECT_EQ(VN_ACTION_OUTCOME_SUCCEEDED, info.outcome);
    EXPECT_EQ(VN_ACTION_TERMINAL_NATURAL, info.terminalReason);
    EXPECT_EQ(0u, info.livePlayableCount);
    EXPECT_EQ(0u, engine->voices.ActiveCount());
    EXPECT_EQ(0u, engine->queueInstances.LiveCount());
    EXPECT_EQ(baselineDecisions, engine->decisions.LiveCount());
    EXPECT_EQ(baselineArmGroups, engine->armGroups.LiveCount());
    EXPECT_EQ(baselinePlayables, engine->playableInstances.LiveCount());
    EXPECT_EQ(0u, engine->timelinePool.CaptureLiveImmediateLaneCohortGroups(
        firing, groups.data(), groups.size()));
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    ASSERT_EQ(VN_OK, Vn_DestroyEmitter(desc.emitter));
    for (std::uint32_t block = 0; block < 192u &&
         CaptureActionReclaimableOwners(*engine) != ownersBefore; ++block) {
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        EXPECT_FALSE(engine->runtimeRecreateRequired);
    }
    ASSERT_NO_FATAL_FAILURE(ExpectStaggeredCurrentOriginalTailReleased(*engine,
        ownersBefore, sourceGenerationsBefore, sourcesBefore, originalInstalls,
        originalSubmissions, savedQueue, savedComposite));
}

std::string NativeQueueOriginalLoanCleanupDiagnostic(harken::Engine& engine, VnActionFiringHandle firing) {
    std::ostringstream out;
    out << CaptureImmediateQueueContinuationState(engine, firing);
    for (std::uint32_t i = 0; i < engine.immediateEntryAttempts.size(); ++i) {
        const auto& attempt = engine.immediateEntryAttempts[i];
        if (attempt.root != firing) continue;
        out << "\noriginalAttempt active=" << attempt.active
            << " privatePhase=" << static_cast<int>(attempt.privateCleanupPhase)
            << " continuationFailed=" << attempt.queueContinuationFailed
            << " c0Descriptor=" << attempt.QueueCoordinators().initialQueueDescriptor.Valid()
            << " c1Descriptor=" << attempt.QueueCoordinators().queueContinuationDescriptor.Valid();
        const auto* c0 = engine.decisions.ResolveFrontierActivation(attempt.QueueCoordinators().initialQueueCoordinator);
        const auto* c1 = engine.decisions.ResolveFrontierActivation(attempt.QueueCoordinators().queueContinuationCoordinator);
        out << " c0State=" << (c0 == nullptr ? -1 : static_cast<int>(c0->State()))
            << " c1State=" << (c1 == nullptr ? -1 : static_cast<int>(c1->State()));
    }
    for (const auto& row : engine.playableServices) {
        if (!row.InvocationValid() || row.Invocation().actionFiring != firing) continue;
        out << "\noriginalQueue prepared=" << row.queueContinuationPrepared
            << " committed=" << (row.HasFeatureArrays() && row.QueueFiling().queueDecisionCommitted)
            << " conditional=" << (row.HasFeatureArrays() && row.QueueFiling().queueConditional.Valid())
            << " abort=" << row.queueAbortRequested
            << " natural=" << row.queueNaturalEnd;
    }
    return out.str();
}


