static void CheckQueueSourceRetainedPreparationRefusal(bool composite) {
    (void)Vn_Term();
    std::vector<float> samples(512, 0.25f);
    harkentest::EngineSession session(harkentest::MakeNullConfig(8, 64, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto& engine = *session.Engine();
    const auto pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &pcm));
    CanonicalActionWorld image(
        engine.registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
        engine.registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
    image.MakeImmediateSequenceQueuePlayAction();
    if (composite) image.MakeFirstQueueChildCompositeTrack();
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
        harken::InstallContainerWorldV1(engine, image.world).status);
    const auto owners = CaptureActionReclaimableOwners(engine);
    const auto head = engine.commands.PublishedHead();
    const auto audio = engine.mixer.BlocksRendered();
    struct FactoryLoan {
        harken::PreparedSingleCurrentOriginBundle::SourcePin source;
        harken::PreparedSingleCurrentOriginBundle::BodyPin body;
        harken::TimelineArmToken arm{};
        harken::VoiceReleaseObserver physical{};
        std::uint32_t calls = 0;
    } loan;
    engine.originalQueueSourcePreparationContextForTest = &loan;
    engine.originalQueueSourcePreparationHookForTest = [](
        harken::Engine& actual, const harken::Engine::OriginalQueueSourcePreparationHolder& original,
        void* context) {
        auto& output = *static_cast<FactoryLoan*>(context);
        ASSERT_EQ(0u, output.calls++);
        ASSERT_TRUE(original.OriginalSource().Borrow(&output.source));
        ASSERT_TRUE(original.OriginalBody().Borrow(&output.body));
        output.arm = original.OriginalArm();
        ASSERT_TRUE(actual.voices.CaptureReleaseObserver(original.OriginalSourceIdentity(), &output.physical));
        // Refuse only the actual post-Capture preparation stage. All native
        // cancellation, physical disposal and foreign loans remain genuine.
        actual.forceTimelineInheritedStopPreparationRefusalForTest = true;
    };
    auto desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&desc.emitter));
    VnActionFiringHandle firing = 0;
    EXPECT_EQ(VN_BACKPRESSURE, Vn_PostAction(&desc, &firing));
    engine.originalQueueSourcePreparationHookForTest = nullptr;
    engine.originalQueueSourcePreparationContextForTest = nullptr;
    ASSERT_EQ(1u, loan.calls);
    EXPECT_EQ(0u, firing);
    EXPECT_EQ(head, engine.commands.PublishedHead());
    EXPECT_EQ(audio, engine.mixer.BlocksRendered());
    EXPECT_FALSE(engine.forceTimelineInheritedStopPreparationRefusalForTest);
    // Preserve the existing generic fault classification; this test proves
    // retained native cleanup and does not reclassify failure as acceptance.
    EXPECT_TRUE(engine.runtimeRecreateRequired);
    ASSERT_TRUE(loan.source.Valid());
    ASSERT_TRUE(loan.body.Valid());
    ASSERT_TRUE(engine.voices.ReleaseObserved(loan.physical));
    harken::TimelineArmObservation native{};
    ASSERT_TRUE(engine.timelineArms.Observe(loan.arm, &native));
    EXPECT_EQ(harken::ArmState::Prepared, native.state);
    auto retained = std::find_if(engine.actionPlayScratch.begin(), engine.actionPlayScratch.end(),
        [&](const auto& candidate) {
            return !candidate.voiceStarts.empty() && candidate.voiceStartCount != 0 &&
                harken::Engine::SameOriginalSingleArm(candidate.voiceStarts[0].arm, loan.arm);
        });
    ASSERT_NE(engine.actionPlayScratch.end(), retained);
    ASSERT_EQ(1u, retained->voiceStartCount);
    EXPECT_EQ(harken::EngineFrontierAttemptPhase::CancelPending, retained->storage.phase);
    EXPECT_TRUE(retained->voiceStarts[0].prepared);
    EXPECT_TRUE(retained->voiceStarts[0].armOwnershipHeld);
    EXPECT_FALSE(retained->voiceStarts[0].voiceOwnershipHeld);
    const auto generation = retained->storage.generation;
    ASSERT_EQ(VN_OK, Vn_Update());
    EXPECT_EQ(1u, retained->voiceStartCount);
    EXPECT_EQ(generation, retained->storage.generation);
    EXPECT_EQ(harken::EngineFrontierAttemptPhase::CancelPending, retained->storage.phase);
    EXPECT_EQ(head, engine.commands.PublishedHead());
    EXPECT_EQ(audio, engine.mixer.BlocksRendered());
    loan.source.Release();
    loan.body.Release();
    for (std::uint32_t update = 0; update < 8u &&
         retained->storage.phase != harken::EngineFrontierAttemptPhase::Free; ++update)
        ASSERT_EQ(VN_OK, Vn_Update());
    ASSERT_EQ(harken::EngineFrontierAttemptPhase::Free, retained->storage.phase);
    EXPECT_EQ(generation, retained->storage.generation);
    EXPECT_EQ(0u, retained->voiceStartCount);
    EXPECT_FALSE(engine.timelineArms.Observe(loan.arm, &native));
    EXPECT_EQ(head, engine.commands.PublishedHead());
    EXPECT_EQ(audio, engine.mixer.BlocksRendered());
    ASSERT_EQ(VN_OK, Vn_DestroyEmitter(desc.emitter));
    EXPECT_EQ(owners, CaptureActionReclaimableOwners(engine));
}
TEST(ActionFiringApi, QueueSourceSingleLaterPreparationRefusalKeepsActualOwnerUntilForeignReturn) {
    CheckQueueSourceRetainedPreparationRefusal(false);
}
TEST(ActionFiringApi, QueueSourceCompositeLaterPreparationRefusalKeepsActualOwnerUntilForeignReturn) {
    CheckQueueSourceRetainedPreparationRefusal(true);
}

static void CheckOriginalSingleActualProducer(bool holdForeign, bool joinedTerm) {
    (void)Vn_Term();
    std::vector<float> first(512, 0.25f);
    std::vector<float> second(512, -0.25f);
    const auto config = harkentest::MakeNullConfig(8, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    auto& engine = *session.Engine();
    const auto firstPcm = harkentest::MonoDesc(first, 48000);
    const auto secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &secondPcm));
    CanonicalActionWorld image(
        engine.registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
        engine.registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
    image.MakeImmediateSequenceQueuePlayAction();
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
        harken::InstallContainerWorldV1(engine, image.world).status);
    const auto beforeOwners = CaptureActionReclaimableOwners(engine);
    const auto beforeAudio = engine.mixer.BlocksRendered();
    const auto beforeHead = engine.commands.PublishedHead();
    const auto beforeLogic = engine.logicCommits.Current();
    auto desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&desc.emitter));
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    ASSERT_NE(0u, firing);
    ASSERT_EQ(beforeAudio, engine.mixer.BlocksRendered());
    ASSERT_GT(engine.commands.PublishedHead(), beforeHead);
    ASSERT_EQ(beforeLogic + 1u, engine.logicCommits.Current());
    VnActionStepResult play{};
    play.structSize = sizeof(play);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
    ASSERT_EQ(VN_ACTION_STEP_ACTIVE, play.state);
    auto row = std::find_if(engine.playableServices.begin(), engine.playableServices.end(),
        [&](const auto& candidate) { return candidate.rootInstance == play.producedPlayableInstance; });
    ASSERT_NE(engine.playableServices.end(), row);
    ASSERT_TRUE(row->InvocationValid());
    ASSERT_EQ(firing, row->Invocation().actionFiring);
    const auto arm = row->arm;
    const auto render = row->renderHandle;
    const auto queue = row->queueInstance;
    const auto occurrence = row->QueuePayload().queueCurrentOccurrence;
    const harken::EnginePlayableServiceReference service{
        row->identity, row->ownerInstance, row->ownerEpoch, row->invocationGeneration};
    ASSERT_TRUE(arm.Valid());
    ASSERT_TRUE(queue.Valid());
    ASSERT_NE(0u, occurrence.generation);
    auto* sourceOutput = engine.OriginalSinglePreparationForArm(arm);
    ASSERT_NE(nullptr, sourceOutput);
    ASSERT_TRUE(sourceOutput->OriginalSource().Valid());
    ASSERT_TRUE(sourceOutput->OriginalBody().Valid());
    ASSERT_TRUE(sourceOutput->OriginalLedger().Valid());
    EXPECT_FALSE(sourceOutput->OriginalLedgerPreparation().Valid());
    const auto sourceIdentity = sourceOutput->OriginalSourceIdentity();
    ASSERT_NE(0u, sourceIdentity);
    auto current = std::find_if(engine.originalSingleCurrentHolders.begin(),
        engine.originalSingleCurrentHolders.end(), [&](const auto& original) {
            return original.state == harken::Engine::OriginalSingleCurrentHolder::State::Prepared &&
                harken::Engine::SameOriginalSingleArm(original.originalCurrentSourceArm, arm);
        });
    ASSERT_NE(engine.originalSingleCurrentHolders.end(), current);
    ASSERT_TRUE(current->bundle.Valid());
    ASSERT_TRUE(current->bundle.HasOriginalPlayableRetention());
    const auto currentDecision = current->originalCurrentSingleDecision;
    const auto currentOwner = current->originalCurrentCompletionOwner;
    const auto currentRoot = current->originalRoot;
    const auto currentArranging = current->originalArranging;
    ASSERT_TRUE(currentDecision.Valid());
    ASSERT_TRUE(harken::SameCompletionOwner(currentOwner,
        harken::CompletionOwnerRef::Single(currentDecision, currentOwner.factsRevision)));
    EXPECT_EQ(occurrence.slot, current->originalCurrentOccurrence.slot);
    EXPECT_EQ(occurrence.generation, current->originalCurrentOccurrence.generation);
    EXPECT_EQ(sourceIdentity, current->originalCurrentSourceIdentity);
    EXPECT_EQ(play.producedPlayableInstance, currentRoot);
    ASSERT_NE(0u, currentArranging);
    ASSERT_TRUE(engine.playableInstances.Classify(currentRoot).live);
    ASSERT_TRUE(engine.playableInstances.Classify(currentArranging).live);
    ASSERT_FALSE(current->bundle.ObserveInstalled());
    std::uint64_t started = 0;
    ASSERT_FALSE(current->bundle.CaptureStartedSequence(&started));
    EXPECT_EQ(0u, started);
    harken::CompletionOwnerRef nativeOwner{};
    ASSERT_TRUE(engine.timelineOccurrences.CaptureCompletionOwner(occurrence, &nativeOwner));
    EXPECT_TRUE(harken::SameCompletionOwner(currentOwner, nativeOwner));
    const auto* sourceRecord = engine.originalSourceSubmissions.Find(arm);
    ASSERT_NE(nullptr, sourceRecord);
    EXPECT_EQ(harken::OriginalSourceSubmissionRegistry::Phase::Published, sourceRecord->State());
    harken::TimelineArmObservation beforeInstallation{};
    ASSERT_TRUE(engine.timelineArms.Observe(arm, &beforeInstallation));
    EXPECT_EQ(0u, beforeInstallation.armedCompletionSequence);
    EXPECT_EQ(0u, beforeInstallation.startedBlockSequence);
    harken::VoiceReleaseObserver release{};
    ASSERT_TRUE(engine.voices.CaptureReleaseObserver(render, &release));
    EXPECT_FALSE(engine.voices.ReleaseObserved(release));
    harken::PreparedSingleCurrentOriginBundle foreign;
    harken::Engine::OriginalPlayableServiceLifetimePin foreignService;
    ASSERT_TRUE(current->serviceRetention.Valid());
    if (holdForeign) {
        ASSERT_TRUE(engine.BorrowOriginalSingleCurrent(*current, &foreign));
        ASSERT_TRUE(foreign.Valid());
        EXPECT_FALSE(engine.BorrowOriginalSingleCurrent(*current, &foreign));
        auto other = std::make_unique<harken::Engine>(engine.config);
        harken::PreparedSingleCurrentOriginBundle refused;
        EXPECT_FALSE(other->BorrowOriginalSingleCurrent(*current, &refused));
        EXPECT_FALSE(refused.Valid());
        ASSERT_TRUE(engine.BorrowOriginalSingleCurrentService(*current, &foreignService));
        EXPECT_EQ(service.token, foreignService.FactoryReference().token);
        EXPECT_EQ(service.invocationGeneration, foreignService.FactoryReference().invocationGeneration);
        EXPECT_FALSE(engine.BorrowOriginalSingleCurrentService(*current, &foreignService));
        harken::Engine::OriginalPlayableServiceLifetimePin refusedService;
        EXPECT_FALSE(other->BorrowOriginalSingleCurrentService(*current, &refusedService));
        EXPECT_FALSE(refusedService.Valid());
    }
    if (joinedTerm) {
        foreign.Release();
        foreignService.Return();
        ASSERT_FALSE(foreign.Valid());
        ASSERT_FALSE(foreignService.Valid());
        ASSERT_TRUE(current->bundle.Valid());
        ASSERT_FALSE(engine.voices.ReleaseObserved(release));
        ASSERT_EQ(VN_OK, Vn_Term());
        return;
    }

    engine.nullBackend.Pump(1);
    ASSERT_EQ(beforeAudio + 1u, engine.mixer.BlocksRendered());
    ASSERT_EQ(VN_OK, Vn_Update());
    ASSERT_TRUE(current->bundle.ObserveInstalled());
    ASSERT_FALSE(current->bundle.CaptureStartedSequence(&started));
    EXPECT_EQ(0u, started);
    harken::TimelineArmObservation installed{};
    ASSERT_TRUE(engine.timelineArms.Observe(arm, &installed));
    EXPECT_GT(installed.armedCompletionSequence, beforeAudio);
    EXPECT_EQ(0u, installed.startedBlockSequence);
    auto attempt = std::find_if(engine.immediateEntryAttempts.data(),
        engine.immediateEntryAttempts.data() + engine.immediateEntryAttempts.size(),
        [firing](const auto& original) { return original.active && original.root == firing; });
    ASSERT_NE(engine.immediateEntryAttempts.data() + engine.immediateEntryAttempts.size(), attempt);
    const auto initial = attempt->QueueCoordinators().initialQueueDescriptor;
    const auto entryQuantum = attempt->entryQuantum;
    ASSERT_TRUE(initial.Valid());
    ASSERT_LE(engine.mixer.BlocksRendered(), entryQuantum);
    ASSERT_EQ(entryQuantum * config.blockFrames, initial.order.executeFrame);
    while (engine.mixer.BlocksRendered() < entryQuantum) {
        ASSERT_EQ(VN_OK, Vn_Update());
        const auto previous = engine.mixer.BlocksRendered();
        engine.nullBackend.Pump(1);
        ASSERT_EQ(previous + 1u, engine.mixer.BlocksRendered());
    }
    engine.nullBackend.Pump(1);
    ASSERT_EQ(entryQuantum + 1u, engine.mixer.BlocksRendered());
    const auto* initialActivation = engine.decisions.ResolveFrontierActivation(initial.entry.coordinator);
    ASSERT_NE(nullptr, initialActivation);
    harken::FrontierActivationReceipt applied{};
    ASSERT_EQ(harken::FrontierReceiptRead::Ready,
        initialActivation->Read(initial.entry, engine.mixer.BlocksRendered(), &applied));
    EXPECT_TRUE(applied.entry == initial.entry);
    EXPECT_TRUE(applied.order == initial.order);
    EXPECT_EQ(harken::FrontierReceiptOrigin::Audio, applied.origin);
    EXPECT_EQ(harken::FrontierReceiptOutcome::Applied, applied.outcome);
    EXPECT_EQ(entryQuantum + 1u, applied.audioSequence);
    harken::TimelineArmObservation actualStart{};
    ASSERT_TRUE(engine.timelineArms.Observe(arm, &actualStart));
    EXPECT_EQ(entryQuantum + 1u, actualStart.startedBlockSequence);
    ASSERT_TRUE(current->bundle.CaptureStartedSequence(&started));
    EXPECT_EQ(actualStart.startedBlockSequence, started);
    EXPECT_GT(harkentest::Peak(engine.nullBackend.LastBlock(),
        config.blockFrames * engine.nullBackend.Channels()), 0.001f);
    ASSERT_EQ(VN_OK, Vn_Update());
    EXPECT_EQ(currentDecision.slot, current->originalCurrentSingleDecision.slot);
    EXPECT_EQ(currentDecision.generation, current->originalCurrentSingleDecision.generation);
    EXPECT_TRUE(harken::SameCompletionOwner(currentOwner, current->originalCurrentCompletionOwner));

    if (holdForeign) {
        for (std::uint32_t callback = 0; callback < 192u && !engine.voices.ReleaseObserved(release); ++callback) {
            const auto previous = engine.mixer.BlocksRendered();
            engine.nullBackend.Pump(1);
            ASSERT_EQ(previous + 1u, engine.mixer.BlocksRendered());
            ASSERT_EQ(VN_OK, Vn_Update());
            EXPECT_FALSE(engine.runtimeRecreateRequired);
        }
        ASSERT_TRUE(engine.voices.ReleaseObserved(release));
        ASSERT_EQ(VN_OK, Vn_Update());
        EXPECT_EQ(nullptr, engine.OriginalSinglePreparationForArm(arm));
        EXPECT_FALSE(current->bundle.Valid());
        EXPECT_NE(harken::Engine::OriginalSingleCurrentHolder::State::Prepared, current->state);
        EXPECT_FALSE(current->serviceRetention.Valid());
        ASSERT_TRUE(foreignService.Valid());
        EXPECT_FALSE(engine.CanReclaimOriginalPlayableServiceStorage(*row));
        harken::Engine::OriginalPlayableServiceLifetimePin tooLate;
        EXPECT_FALSE(engine.BorrowOriginalSingleCurrentService(*current, &tooLate));
        EXPECT_FALSE(tooLate.Valid());
        EXPECT_TRUE(foreign.Valid());
        EXPECT_TRUE(foreign.HasOriginalPlayableRetention());
        EXPECT_TRUE(engine.playableInstances.Classify(currentRoot).live);
        EXPECT_TRUE(engine.playableInstances.Classify(currentArranging).live);
        EXPECT_EQ(currentDecision.slot, current->originalCurrentSingleDecision.slot);
        EXPECT_EQ(currentDecision.generation, current->originalCurrentSingleDecision.generation);
        foreign.Release();
        foreignService.Return();
        EXPECT_FALSE(foreign.Valid());
        EXPECT_FALSE(foreignService.Valid());
    }
    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    for (std::uint32_t callback = 0; callback < 192u; ++callback) {
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
        if (info.state == VN_ACTION_FIRING_TERMINAL_RETAINED) break;
        const auto previous = engine.mixer.BlocksRendered();
        engine.nullBackend.Pump(1);
        ASSERT_EQ(previous + 1u, engine.mixer.BlocksRendered());
        ASSERT_EQ(VN_OK, Vn_Update());
        EXPECT_FALSE(engine.runtimeRecreateRequired);
    }
    ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state)
        << CaptureImmediateQueueContinuationState(engine, firing);
    EXPECT_EQ(0u, info.livePlayableCount);
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    ASSERT_EQ(VN_OK, Vn_DestroyEmitter(desc.emitter));
    for (std::uint32_t callback = 0; callback < 192u &&
         CaptureActionReclaimableOwners(engine) != beforeOwners; ++callback) {
        const auto previous = engine.mixer.BlocksRendered();
        engine.nullBackend.Pump(1);
        ASSERT_EQ(previous + 1u, engine.mixer.BlocksRendered());
        ASSERT_EQ(VN_OK, Vn_Update());
    }
    EXPECT_EQ(beforeOwners, CaptureActionReclaimableOwners(engine));
    EXPECT_EQ(nullptr, engine.ResolvePlayableService(service));
    EXPECT_FALSE(engine.playableInstances.Classify(currentRoot).live);
    EXPECT_FALSE(engine.playableInstances.Classify(currentArranging).live);
    EXPECT_FALSE(engine.originalSingleDecisionBaselines[currentDecision.slot].Valid());
    EXPECT_FALSE(engine.originalSingleOccurrenceBaselines[occurrence.slot].Valid());
    EXPECT_EQ(nullptr, engine.voices.Resolve(render));
    harken::TimelineArmObservation stale{};
    EXPECT_FALSE(engine.timelineArms.Observe(arm, &stale));
    harken::EngineTimelineVoiceInstallIdentity oldInstall{};
    EXPECT_FALSE(engine.CaptureTimelineVoiceInstallIdentity(render, &oldInstall));
}

