namespace {
struct InitialOriginalCoordinatorBusyProbe {
    InitialOriginalPublicProbe original;
    harken::DecisionFuturePin coordinatorPin;
    harken::DecisionToken coordinator{};
    harken::EngineImmediateEntryAttempt* attempt = nullptr;
    std::array<harken::Plan03ImmediateLaneGroupDescriptor, 8> groups{};
    std::uint32_t groupCount = 0;
    bool captured = false;
    void Capture(harken::Engine& engine) {
        original.Capture(engine);
        if (!original.captured || !original.clock.Valid()) return;
        for (std::uint32_t index = 0; index < engine.immediateEntryAttempts.size(); ++index) {
            auto& actual = engine.immediateEntryAttempts[index];
            if (!actual.active || actual.root != original.root ||
                actual.generation != original.attemptGeneration ||
                actual.initialService != original.issuerService ||
                actual.initialInvocationGeneration != original.issuerInvocationGeneration) continue;
            if (attempt != nullptr || !actual.QueueCoordinators().initialQueueCoordinatorReservation.Valid() ||
                !actual.QueueCoordinators().initialQueuePrimaryGroup.Exact()) return;
            attempt = &actual;
        }
        if (attempt == nullptr) return;
        coordinator = attempt->QueueCoordinators().initialQueueCoordinatorReservation.Token();
        if (!coordinator.Valid() || attempt->QueueCoordinators().initialQueuePrimaryGroup.decision.slot != coordinator.slot ||
            attempt->QueueCoordinators().initialQueuePrimaryGroup.decision.generation != coordinator.generation) return;
        groupCount = engine.timelinePool.CaptureImmediateLaneCohortGroups(original.root,
            groups.data(), static_cast<std::uint32_t>(groups.size()));
        if (groupCount != 4u || !engine.decisions.AcquireFuturePin(coordinator, &coordinatorPin)) return;
        // Only the authentic Coordinator pin survives the hook. Keeping a clock
        // would exercise group Busy instead of the completed-group prefix.
        original.clock.Release();
        captured = true;
    }
};
} // namespace

TEST(ActionFiringApi, InitialOriginalMixedPublicAbortCoordinatorFuturePinKeepsDisposedPrefixUntilActualReturn) {
    (void)Vn_Term();
    std::vector<float> first(128, 0.25f), second(128, -0.125f);
    harken::detail::ScopedTimelineCapacityOverrideForTest capacity(64, 16, 16, 8);
    ASSERT_TRUE(capacity.Valid());
    harkentest::EngineSession session(harkentest::MakeNullConfig(8, 64, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto& engine = *session.Engine();
    // Every genuine loan returns before the Engine on assertion exit.
    InitialOriginalCoordinatorBusyProbe probe;
    const auto firstPcm = harkentest::MonoDesc(first, 48000);
    const auto secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &secondPcm));
    CanonicalActionWorld image(
        engine.registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
        engine.registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
    image.MakeImmediateSoundPlayAction();
    const auto soundStep = image.steps[11];
    image.MakeImmediateSequenceQueuePlayAction();
    const auto queueStep = image.steps[11];
    image.steps[11] = soundStep;
    image.steps[11].authoredEventIndex = 0;
    image.steps[12] = queueStep;
    image.steps[12].authoredEventIndex = 1;
    image.actions[9].steps = &image.steps[11];
    image.actions[9].stepCount = 2;
    image.actions[9].expandedStepOccurrenceCount = 2;
    image.actions[9].expandedFiringCount = 1;
    image.actions[9].programSemanticFingerprint = harken::ComputeActionProgramFingerprintV1(image.actions[9]);
    image.world.identity.runtimeSemanticFingerprint = harken::ComputeCurrentWorldFingerprintV4(image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok, harken::InstallContainerWorldV1(engine, image.world).status);
    auto desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&desc.emitter));
    const auto baseline = CaptureActionReclaimableOwners(engine);
    engine.immediateLaneReservedContextForTest = &probe;
    engine.immediateLaneReservedHookForTest = [](harken::Engine& owner, void* context) {
        static_cast<InitialOriginalCoordinatorBusyProbe*>(context)->Capture(owner);
    };
    engine.forceImmediateLaneReservationFailureForTest = true;
    VnActionFiringHandle firing = 0;
    const auto postResult = Vn_PostAction(&desc, &firing);
    engine.immediateLaneReservedHookForTest = nullptr;
    engine.immediateLaneReservedContextForTest = nullptr;
    ASSERT_TRUE(probe.original.called);
    ASSERT_TRUE(probe.captured);
    ASSERT_TRUE(probe.original.originalsBeforeAck);
    ASSERT_EQ(VN_BACKPRESSURE, postResult);
    ASSERT_EQ(0u, firing);
    ASSERT_NE(nullptr, probe.original.original);
    ASSERT_NE(nullptr, probe.attempt);
    ASSERT_TRUE(probe.coordinatorPin.Valid());
    ASSERT_EQ(&engine.decisions, probe.coordinatorPin.Owner());
    ASSERT_EQ(probe.coordinator.slot, probe.coordinatorPin.Token().slot);
    ASSERT_EQ(probe.coordinator.generation, probe.coordinatorPin.Token().generation);
    EXPECT_FALSE(probe.original.clock.Valid());
    EXPECT_EQ(0u, engine.mixer.BlocksRendered());
    std::array<harken::Plan03ImmediateLaneGroupDescriptor, 8> after{};
    const auto checkRetained = [&]() {
        EXPECT_FALSE(engine.runtimeRecreateRequired);
        EXPECT_EQ(harken::EngineFrontierAttemptPhase::CancelPending, probe.original.original->storage.phase);
        EXPECT_EQ(probe.original.root, probe.original.original->initialOriginalGroupRoot);
        EXPECT_EQ(probe.original.attemptGeneration, probe.original.original->initialOriginalGroupAttemptGeneration);
        EXPECT_EQ(probe.original.issuerService, probe.original.original->initialOriginalCohortService);
        EXPECT_EQ(probe.original.issuerInvocationGeneration,
            probe.original.original->initialOriginalCohortInvocationGeneration);
        EXPECT_EQ(probe.original.queue.slot, probe.original.original->initialOriginalConditionalQueue.slot);
        EXPECT_EQ(probe.original.queue.generation, probe.original.original->initialOriginalConditionalQueue.generation);
        EXPECT_EQ(probe.original.version.version, probe.original.original->initialOriginalConditionalVersion.version);
        EXPECT_EQ(nullptr, probe.original.original->initialOriginalConditional);
        EXPECT_TRUE(probe.original.original->initialOriginalGroupsDisposed);
        EXPECT_FALSE(engine.originalQueueConditionalHolders[probe.original.queue.slot].baseline.Valid());
        EXPECT_FALSE(engine.originalQueueConditionalHolders[probe.original.queue.slot].clock.Valid());
        EXPECT_EQ(0u, engine.timelinePool.CaptureImmediateLaneCohortGroups(probe.original.root,
            after.data(), static_cast<std::uint32_t>(after.size())));
        for (std::uint32_t index = 0; index < probe.groupCount; ++index) {
            harken::Plan03PageGroupView oldGroup{};
            EXPECT_FALSE(engine.timelinePool.ResolvePlan03GroupSliceProducer(probe.groups[index].identity, &oldGroup));
        }
        EXPECT_TRUE(probe.attempt->active);
        EXPECT_EQ(probe.original.root, probe.attempt->root);
        EXPECT_EQ(probe.original.attemptGeneration, probe.attempt->generation);
        EXPECT_EQ(probe.original.issuerService, probe.attempt->initialService);
        EXPECT_EQ(probe.original.issuerInvocationGeneration, probe.attempt->initialInvocationGeneration);
        EXPECT_FALSE(probe.attempt->lane.Valid());
        EXPECT_FALSE(probe.attempt->QueueCoordinators().initialQueuePrimaryGroup.Exact());
        EXPECT_FALSE(probe.attempt->QueueCoordinators().queueContinuationPrimaryGroup.Exact());
        EXPECT_TRUE(probe.attempt->QueueCoordinators().initialQueueCoordinatorReservation.Valid());
        EXPECT_EQ(probe.coordinator.slot, probe.attempt->QueueCoordinators().initialQueueCoordinatorReservation.Token().slot);
        EXPECT_EQ(probe.coordinator.generation, probe.attempt->QueueCoordinators().initialQueueCoordinatorReservation.Token().generation);
        EXPECT_TRUE(engine.decisions.IsOpen(probe.coordinator));
        EXPECT_TRUE(probe.coordinatorPin.Valid());
    };
    checkRetained();
    for (unsigned repeat = 0; repeat < 3u; ++repeat) {
        const auto previous = engine.mixer.BlocksRendered();
        ASSERT_EQ(VN_OK, Vn_Update());
        EXPECT_EQ(previous, engine.mixer.BlocksRendered());
        checkRetained();
    }
    ASSERT_TRUE(probe.coordinatorPin.Release());
    EXPECT_FALSE(probe.coordinatorPin.Valid());
    ASSERT_EQ(VN_OK, Vn_DestroyEmitter(desc.emitter));
    for (unsigned block = 0; block < 256u; ++block) {
        const auto previous = engine.mixer.BlocksRendered();
        engine.nullBackend.Pump(1);
        ASSERT_EQ(previous + 1u, engine.mixer.BlocksRendered());
        ASSERT_EQ(VN_OK, Vn_Update());
        EXPECT_FALSE(engine.runtimeRecreateRequired);
        if (CaptureActionReclaimableOwners(engine) == baseline) break;
    }
    EXPECT_EQ(baseline, CaptureActionReclaimableOwners(engine));
    EXPECT_FALSE(engine.decisions.Contains(probe.coordinator));
    EXPECT_GE(probe.original.sourceCount, 3u);
    for (std::uint32_t index = 0; index < probe.original.sourceCount; ++index) {
        EXPECT_TRUE(engine.voices.ReleaseObserved(probe.original.releases[index]));
        EXPECT_FALSE(engine.originalSourceSubmissions.HasOriginalVoice(probe.original.arms[index]));
        const auto* source = engine.originalSourceSubmissions.Find(probe.original.arms[index]);
        if (source != nullptr)
            EXPECT_EQ(harken::OriginalSourceSubmissionRegistry::Phase::Disposed, source->State());
        harken::TimelineArmObservation observed{};
        EXPECT_FALSE(engine.timelineArms.Observe(probe.original.arms[index], &observed));
        harken::EngineTimelineVoiceInstallIdentity installation{};
        EXPECT_FALSE(engine.CaptureTimelineVoiceInstallIdentity(probe.original.renders[index], &installation));
    }
    for (std::uint32_t index = 0; index < engine.immediateEntryAttempts.size(); ++index)
        EXPECT_FALSE(engine.immediateEntryAttempts[index].active &&
            engine.immediateEntryAttempts[index].root == probe.original.root);
}
