TEST(ActionFiringApi, QueueCompositeSecondLeafNativeMarkerRefusalKeepsHeadPrivateAndReclaimsWholePrefix) {
    (void)Vn_Term();
    std::vector<float> samples(512, 0.25f);
    harkentest::EngineSession session(harkentest::MakeNullConfig(8, 64, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto& engine = *session.Engine();
    const auto pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &pcm));
    CanonicalActionWorld image(
        engine.registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
        engine.registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
    image.MakeImmediateSequenceQueuePlayAction();
    image.MakeFirstQueueChildCompositeTrack();
    ASSERT_EQ(harken::WorldInstallStatus::Ok, harken::InstallContainerWorldV1(engine, image.world).status);
    struct ActualPrepare {
        std::uint32_t count = 0;
        std::uint32_t head = 0;
        std::uint64_t block = 0;
        harken::CompositeCompletionOwnerPool::OriginalLifetimePin foreign;
        harken::CompositeCompletionOwnerToken token{};
        const harken::EngineOriginalCompositeCompletionPreparation* own = nullptr;
    } seen;
    seen.head = engine.commands.PublishedHead();
    seen.block = engine.mixer.BlocksRendered();
    const auto owners = CaptureActionReclaimableOwners(engine);
    const auto freeRows = engine.compositeCompletionOwners.FreeCount();
    const auto freeOccurrences = engine.timelineOccurrences.FreeCount();
    engine.originalCompositePreparationContextForTest = &seen;
    engine.originalCompositePreparationHookForTest = [](
        harken::Engine& actual, const harken::EngineOriginalCompositeCompletionPreparation& original, void* context) {
        auto& observation = *static_cast<ActualPrepare*>(context);
        ASSERT_EQ(0u, observation.count++);
        ASSERT_EQ(observation.head, actual.commands.PublishedHead());
        ASSERT_EQ(observation.block, actual.mixer.BlocksRendered());
        ASSERT_TRUE(original.OriginalOwner().Borrow(&observation.foreign));
        observation.token = original.OriginalToken();
        observation.own = &original;
        harken::detail::PreparedCompositeLeafIssuerLimitTestAccess::SeedLastNativeLeafMarker(actual.timelineOccurrences);
    };
    auto desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&desc.emitter));
    VnActionFiringHandle firing = 99;
    EXPECT_EQ(VN_NO_VOICE, Vn_PostAction(&desc, &firing));
    engine.originalCompositePreparationHookForTest = nullptr;
    engine.originalCompositePreparationContextForTest = nullptr;
    ASSERT_EQ(1u, seen.count);
    EXPECT_EQ(0u, firing);
    EXPECT_EQ(seen.head, engine.commands.PublishedHead());
    EXPECT_EQ(seen.block, engine.mixer.BlocksRendered());
    ASSERT_TRUE(seen.foreign.Valid());
    EXPECT_FALSE(seen.own->OriginalOwner().Valid());
    EXPECT_FALSE(engine.compositeCompletionOwners.IsOriginalLifetimePinned(seen.foreign));
    EXPECT_EQ(freeRows - 1u, engine.compositeCompletionOwners.FreeCount());
    harken::CompositeCompletionOwnerInfo retained{};
    ASSERT_TRUE(engine.compositeCompletionOwners.CaptureOriginal(seen.foreign, &retained));
    ASSERT_EQ(2u, retained.leafCount);
    for (std::uint32_t index = 0; index < retained.leafCount; ++index) {
        harken::KnownScheduleLeafV1 leaf{};
        ASSERT_TRUE(engine.compositeCompletionOwners.CaptureOriginalLeaf(seen.foreign, index, &leaf));
        EXPECT_EQ(nullptr, engine.compositeCompletionOwners.ResolveOriginalPreparedLeafCommit(engine.timelineOccurrences, leaf.occurrence));
        EXPECT_EQ(harken::OccurrenceStage::Free, engine.timelineOccurrences.StageOf(leaf.occurrence));
        harken::CompletionOwnerRef owner{};
        EXPECT_FALSE(engine.timelineOccurrences.CaptureCompletionOwner(leaf.occurrence, &owner));
    }
    EXPECT_EQ(freeOccurrences, engine.timelineOccurrences.FreeCount());
    EXPECT_EQ(0u, engine.timelineOccurrences.RetainedStorageCount());
    seen.foreign.Release();
    EXPECT_EQ(freeRows, engine.compositeCompletionOwners.FreeCount());
    ASSERT_EQ(VN_OK, Vn_DestroyEmitter(desc.emitter));
    for (std::uint32_t block = 0; block < 32u; ++block) {
        const auto previous = engine.mixer.BlocksRendered();
        engine.nullBackend.Pump(1);
        ASSERT_EQ(previous + 1u, engine.mixer.BlocksRendered());
        EXPECT_EQ(0.0f, harkentest::Peak(engine.nullBackend.LastBlock(), engine.nullBackend.BlockFrames() * engine.nullBackend.Channels()));
        ASSERT_EQ(VN_OK, Vn_Update());
    }
    EXPECT_EQ(owners, CaptureActionReclaimableOwners(engine));
    EXPECT_FALSE(engine.runtimeRecreateRequired);
}
