static void CheckDefaultQueueFactoryLifetime(std::uint32_t shape, bool joinedTerm, bool holdForeign = true) {
    (void)Vn_Term();
    harkentest::EngineSession session(harkentest::MakeNullConfig(8, 64, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto& engine = *session.Engine();
    std::vector<float> first(512, 0.25f), second(512, 0.125f);
    const auto firstPcm = harkentest::MonoDesc(first, 48000);
    const auto secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &secondPcm));
    CanonicalActionWorld image(engine.registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
        engine.registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
    image.MakeImmediateSequenceQueuePlayAction();
    if (shape == 1u || shape == 2u) image.MakeFirstQueueChildCompositeTrack();
    if (shape == 2u) {
        for (std::uint32_t index = 0; index < 2; ++index) {
            image.trackPlacements[index].authoredStart = static_cast<std::int64_t>(index + 1u) * INT64_C(10000000);
            image.trackPlacements[index].authoredDuration = 1;
        }
        image.track.scheduleSemanticFingerprint = harken::ComputeTrackScheduleFingerprintV1(image.track);
        image.queueChildren[0].timingHint = harken::MakeScheduleReferenceTimingHint(
            harken::PlayableKindV1::Track, image.track.rootDefinition.stableId, image.track.scheduleSemanticFingerprint);
    }
    if (shape == 3u) {
        const auto terminalChild = image.queueChildren[0];
        image.sequenceChild = image.child;
        image.containers[1].children = &image.sequenceChild;
        image.MakeImmediateQueueNestedContainerPlayAction(false);
        image.child = terminalChild;
        image.containers[0].mode = harken::ContainerModeV1::SequenceQueue;
        image.containers[0].memoryScope = harken::MemoryScopeV1::Emitter;
        image.containers[0].queueCycle = harken::QueueCycleV1::Once;
        image.containers[0].queueSplice = harken::QueueSpliceV1::Butt;
    }
    if (shape == 4u) image.MakeImmediateNestedQueueVariableControlPlayAction();
    image.world.identity.runtimeSemanticFingerprint = harken::ComputeCurrentWorldFingerprintV4(image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok, harken::InstallContainerWorldV1(engine, image.world).status);
    const auto owners = CaptureActionReclaimableOwners(engine);
    struct FactoryObservation {
        std::array<harken::Engine::OriginalQueueFactoryLifetimePin, 8> loans;
        std::array<const harken::Engine::OriginalQueueFactoryLifetimeHolder*, 8> originals{};
        std::uint32_t count = 0, head = 0;
        std::uint64_t block = 0;
        bool holdForeign = true;
    } seen;
    seen.holdForeign = holdForeign;
    seen.head = engine.commands.PublishedHead();
    seen.block = engine.mixer.BlocksRendered();
    engine.originalQueueFactoryLifetimeContextForTest = &seen;
    engine.originalQueueFactoryLifetimeHookForTest = [](harken::Engine& actual,
        const harken::Engine::OriginalQueueFactoryLifetimeHolder& original, void* context) {
        auto& observation = *static_cast<FactoryObservation*>(context);
        ASSERT_LT(observation.count, observation.loans.size());
        EXPECT_EQ(observation.head, actual.commands.PublishedHead());
        EXPECT_EQ(observation.block, actual.mixer.BlocksRendered());
        EXPECT_FALSE(actual.originalInitialSingleQueueOriginProducerEnabled);
        auto& loan = observation.loans[observation.count];
        ASSERT_TRUE(original.Borrow(&loan));
        ASSERT_TRUE(loan.Valid());
        EXPECT_EQ(original.FactoryQueue().slot, loan.FactoryQueue().slot);
        EXPECT_EQ(original.FactoryQueue().generation, loan.FactoryQueue().generation);
        EXPECT_EQ(original.FactoryCreate().rootInstance, loan.FactoryCreate().rootInstance);
        EXPECT_GT(loan.FactoryCreate().initial.version, 0u);
        EXPECT_GT(loan.FactoryService().invocationGeneration, 0u);
        EXPECT_FALSE(original.Borrow(&loan));
        harken::Engine::OriginalQueueFactoryLifetimePin independent;
        ASSERT_TRUE(loan.Borrow(&independent));
        ASSERT_TRUE(independent.Valid());
        independent.Release();
        EXPECT_TRUE(loan.Valid());
        observation.originals[observation.count++] = &original;
        if (!observation.holdForeign) loan.Release();
    };
    auto post = ValidPostDesc();
    post.actionId = image.actions[9].actionStableId;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&post.emitter));
    VnActionFiringHandle firing = 0;
    const auto result = Vn_PostAction(&post, &firing);
    engine.originalQueueFactoryLifetimeHookForTest = nullptr;
    engine.originalQueueFactoryLifetimeContextForTest = nullptr;
    ASSERT_EQ(VN_OK, result);
    ASSERT_NE(0u, firing);
    ASSERT_GT(seen.count, 0u);
    EXPECT_EQ(seen.block, engine.mixer.BlocksRendered());
    for (std::uint32_t index = 0; holdForeign && index < seen.count; ++index) {
        harken::Engine::OriginalQueueFactoryLifetimePin moved = std::move(seen.loans[index]);
        EXPECT_FALSE(seen.loans[index].Valid());
        EXPECT_TRUE(moved.Valid());
        ASSERT_TRUE(moved.Borrow(&seen.loans[index]));
        moved.Release();
    }
    if (joinedTerm) {
        for (auto& loan : seen.loans) loan.Release();
        ASSERT_EQ(VN_OK, Vn_Term());
        return;
    }
    if (shape == 4u) {
        std::uint32_t committedCoordinators = 0;
        for (const auto& record : engine.queueContinuationRecords) {
            if (!record.occupied || record.root != firing) continue;
            harken::DecisionCommittedSnapshot committed{};
            ASSERT_TRUE(engine.decisions.CaptureCommitted(record.coordinator, &committed));
            EXPECT_EQ(record.coordinatorArmGroup.slot, committed.armGroup.slot);
            EXPECT_EQ(record.coordinatorArmGroup.generation, committed.armGroup.generation);
            EXPECT_FALSE(engine.decisions.IsOpen(record.coordinator));
            EXPECT_FALSE(engine.decisions.IsCancelled(record.coordinator));
            EXPECT_FALSE(record.descriptor.Valid());
            ++committedCoordinators;
        }
        ASSERT_GT(committedCoordinators, 0u);
    }
    ASSERT_EQ(VN_OK, Vn_StopActionFiring(firing, 0));
    for (unsigned block = 0; block < 64u; ++block) {
        const auto previous = engine.mixer.BlocksRendered();
        engine.nullBackend.Pump(1);
        ASSERT_EQ(previous + 1u, engine.mixer.BlocksRendered());
        ASSERT_EQ(VN_OK, Vn_Update());
    }
    EXPECT_EQ(0u, engine.voices.ActiveCount());
    for (std::uint32_t index = 0; holdForeign && index < seen.count; ++index) {
        const auto& loan = seen.loans[index];
        ASSERT_TRUE(loan.Valid());
        auto* actualService = engine.ResolvePlayableService(loan.FactoryService());
        ASSERT_NE(nullptr, actualService);
        EXPECT_FALSE(engine.CanReclaimOriginalPlayableServiceStorage(*actualService));
        EXPECT_TRUE(engine.playableInstances.Classify(loan.FactoryCreate().rootInstance).live);
    }
    for (auto& loan : seen.loans) loan.Release();
    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    for (unsigned block = 0; block < 192u; ++block) {
        engine.nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
        if (info.state == VN_ACTION_FIRING_TERMINAL_RETAINED) break;
    }
    ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    ASSERT_EQ(VN_OK, Vn_DestroyEmitter(post.emitter));
    for (unsigned block = 0; block < 192u && CaptureActionReclaimableOwners(engine) != owners; ++block) {
        engine.nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
    }
    EXPECT_EQ(owners, CaptureActionReclaimableOwners(engine));
    EXPECT_FALSE(engine.runtimeRecreateRequired);
    for (std::uint32_t index = 0; index < seen.count; ++index) {
        harken::Engine::OriginalQueueFactoryLifetimePin late;
        EXPECT_FALSE(seen.originals[index]->Borrow(&late));
        EXPECT_FALSE(late.Valid());
    }
}

