namespace {
void CheckDefaultActionContent(int kind, bool delayed) {
    SCOPED_TRACE(kind);
    SCOPED_TRACE(delayed);
    (void)Vn_Term();
    auto config = harkentest::MakeNullConfig(8, 64, 48000);
    config.maxEmitters = 1;
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    VnEmitterHandle occupied = 0;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&occupied));
    const std::vector<float> samples(64, 0.25f);
    const auto pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &pcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
    switch (kind) {
    case 0: image.MakeImmediateRandomContainerPlayAction(); break;
    case 1: image.MakeImmediateSequenceContainerPlayAction(); break;
    case 2: image.MakeImmediateNestedContainerPlayAction(); break;
    case 3: image.MakeImmediateRandomQueuePlayAction(); break;
    case 4: image.MakeImmediateSequenceQueuePlayAction(); break;
    case 5: image.MakeImmediateVariableControlPlayAction(); break;
    case 6: image.MakeImmediateDirectContainerCompositePlayAction(harken::PlayableKindV1::Track); break;
    case 7: image.MakeImmediateDirectContainerCompositePlayAction(harken::PlayableKindV1::Segment); break;
    }
    for (auto& container : image.containers) container.memoryScope = harken::MemoryScopeV1::Emitter;
    if (delayed) image.DelayCurrentSinglePlayAction(10000000);
    image.world.identity.runtimeSemanticFingerprint = harken::ComputeCurrentWorldFingerprintV4(image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);
    auto desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    ASSERT_NE(0u, firing);
    EXPECT_EQ(0u, desc.emitter);
    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    harkentest::Capture capture;
    for (unsigned block = 0; block < 128; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        harkentest::PumpAndCapture(engine, 1, capture);
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
        if (info.state == VN_ACTION_FIRING_TERMINAL_RETAINED) break;
    }
    EXPECT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
    EXPECT_EQ(VN_ACTION_OUTCOME_SUCCEEDED, info.outcome);
    HARKENTEST_ASSERT_NON_SILENT(capture.left);
    EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    EXPECT_EQ(1u, engine->emitters.ActiveCount());
    EXPECT_EQ(VN_OK, Vn_DestroyEmitter(occupied));
}
}

